Object.assign(window.__LB,{"17500": ["病机", "左臂瘦削、屈伸不利，酸痛由肩及项上连头额，乃\"营虚生风，风入于络\"。脉细主营血亏虚、脉络失养，弦为风动筋急，细弦示虚风入络。久则气血不荣，故\"防偏枯\"，治以和养。", ["细", "弦"]], "17501": ["病机", "症见四肢麻痹、肌肤发痒，为营血不足、风动于络之象。脉细主血虚失养，弦主风动，细弦相合示营虚生风、络脉不和。麻为血虚，痒为风动，故治以和养，养血以熄风。", ["细", "弦"]], "17502": ["病机", "\"风痹走窜\"，腰以下酸而且痛，近则胸背牵引。脉沉主邪着于里、痹阻深在，弦主风动而痛、筋脉拘急，沉弦示风湿痹阻、走窜不定。治以和养，和络祛风而不峻攻。", ["沉", "弦"]], "17503": ["病机", "产前受风，风郁感邪，腰俞下酸痛无度，近乎半身不遂。产后营血本亏，脉细为血虚，弦为风动，细弦示营虚风入、筋脉失养。故治以温养，温养营血以祛风，而非单纯疏散。", ["细", "弦"]], "17504": ["病机", "脉见细弦，细为血亏，弦为风动。原文言血亏生风，腕后上升及背皆为不利，是阴血不足、肝风内扰，风循经上窜，络脉失养而不利。细弦并见，正合营血虚而风阳动之机，故治以疏和，养血之中兼疏风通络。", ["细", "弦"]], "17505": ["病机", "本段未出脉名，以舌苔与症候立论。舌腻渐退而根苔尚厚，示湿浊未净；久有风患、步履欠稳，是风未息。原文谓湿由脾生、风从肝发，两者互扰，外走络脉、内遏中宫，外偏于风、内偏于湿，新旧病皆根于此，故病机为肝风与脾湿互结为患。", []], "17506": ["病机", "脉右部滑大、左部细弦。右滑大为气虚生痰、痰湿壅盛之象，左细弦为营虚生风之征。风邪挟痰走窜经隧，故偏左肢骱酸痛、手足不能高举开步；舌苔黄腻、纳食欠旺、禀体丰腴，皆痰湿内蕴。以脉合症，属气虚于营，卫虚不用、营虚不仁。", ["滑", "大", "细", "弦"]], "17507": ["病机", "脉见弦滑，弦主风动，滑主痰热。原文言喉痹起因痰热，又复挟风，渐至手痉面麻、言语舌强，是痰热挟风上扰，走窜经络，蒙蔽舌窍。弦滑相合，正示风痰热邪内盛之机，故治以清熄，清痰热而熄肝风。", ["弦", "滑"]], "17508": ["病机", "脉息弦滑，弦为风，滑为痰。原文言风中廉泉，口不能言，舌短复长伸，四肢掣动，是风痰上阻舌本、横窜四肢。廉泉为舌本之要，风痰壅之则言语失灵；四肢掣动乃风动之征。弦滑并见，主风痰内盛、走窜经络，故拟和养以息风化痰。", ["弦", "滑"]], "17509": ["病机", "脉见细弦，细为营血不足，弦为肝风内动。原文言中风偏左，左者为瘫，手足屈伸不利、抽搐无度、舌音不清，是营虚风动、风痰阻络，筋脉失养而抽搐，舌窍不利而言謇。细弦正合营虚风动之机，故拟温降熄风，温养营血以降风阳。", ["细", "弦"]], "17510": ["病机", "脉见细弦，细主营虚，弦主风动。原文言左瘫右痪现属于右，手足麻木不仁，皆由营虚生风、风痰走窜，络脉不能流利机关。营血虚则络脉失养，风痰乘虚窜络，故麻木不仁、肢体不用。细弦之脉正示营虚风动，故拟温养以补营熄风。", ["细", "弦"]], "17511": ["病机", "脉见沉弦，沉主病在里，弦主风动。原文言偏风于右，肢节骱皆肿痛，痛甚于夜，由营阴不足、内风袭络所致。营阴亏则络脉失濡，内风乘虚袭络，气血痹阻，故肿痛夜甚。沉弦示风邪入里、络脉不和，再以和养，养营阴而和络脉。", ["沉", "弦"]], "17512": ["病机", "脉来弦滑，弦主肝风，滑主脾痰。原文谓气虚生痰、阴虚生风，风邪挟痰走窜经隧，致四肢不利、腹膨筋露。肝邪侮脾，风痰交阻，脉象弦滑正合风痰内盛之机，故恐成瘫痪，宜加意调理。", ["弦", "滑"]], "17513": ["病机", "脉见细弦，细为阴亏，弦为阳亢风动。原文言肝阴不足、肝阳有余，阳化内风上扰清空，致目星失明、头眩呕逆泛痰。气阴亏而风痰盛，脉细弦恰应此虚实夹杂之候，久防类中，拟以和养。", ["细", "弦"]], "17514": ["预后", "脉细而弦，细主阴血不足，弦主肝阳化风。原文述上重下轻、头蒙发眩、两足酸软，乃下虚上实、风阳上扰之象。脉证相合，最防类中，故以预后警示为主，提示须防肝风内动致中风。", ["细", "弦"]], "17515": ["主病", "脉见细弦，细为阴亏，弦为肝旺。原文载头疼时冲、或呕或溏，乃肝阳上扰清空则头痛，肝邪犯胃则呕，木郁乘脾则溏。脉细弦正合肝阴不足、肝阳偏亢之病机，故治以疏和，调肝理脾。", ["细", "弦"]], "17516": ["主病", "脉弦舌腻，弦主肝风，腻主痰湿。原文谓头风有根，每发必为泛恶，乃肝风挟痰上扰清空则头痛，痰浊犯胃则泛恶。脉弦舌腻正应风痰内蕴之机，故治以疏和，疏肝化痰以除头风之根。", ["弦"]], "17517": ["病机", "脉息沉弦，沉主里，弦主肝风。原文述头风痛发额筋抽搐、夜甚于昼，冲犯中焦并为呕泛。沉弦示肝风内伏于里，入夜阳潜阴盛则风动更甚，犯中则呕，故治以和降，降肝和胃。", ["沉", "弦"]], "17518": ["病机", "脉息沉弦，沉为病在里，弦为肝邪偏盛。原文言头风有根，受凉易发，发甚则肝邪犯中而为呕吐。沉弦正合肝风内伏、乘土犯胃之机，故治以调降，调肝降逆以止呕。", ["沉", "弦"]], "17519": ["病机", "脉左弦于右，左关候肝，弦为肝旺。原文谓真水素亏，肝邪上扰，头痛牙痛时作时伏，木凌土位则纳呆神倦。左脉弦于右，正示肝木偏亢、水不涵木之机，故拟和养，滋水柔肝。", ["弦"]], "17520": ["病机", "脉弦数，弦主肝，数主热，合为肝阳胃热挟风扰动之象。原文牙痛甚连头额、牙龈浮肿、齿摇，正是风火循经上攻；脉数示余邪未尽之实，弦中兼虚应阴分素亏，故断为半虚半实，治以清泄。", ["弦", "数"]], "17521": ["病机", "脉细弦，细为阴亏，弦为肝旺，合示真阴内亏、龙雷失潜而气火化风。原文头蒙烘烘、耳鸣目涩、风块走窜、肉𥆧不宁，皆风火内动上扰之候；脉细弦正应肝肾内虚、阳不潜藏，故治以镇养。", ["细", "弦"]], "17522": ["病机", "脉细滑，细属营阴不足，滑主痰湿内蕴。原文左颊酸疼、牙床开合不利，为络脉失养兼痰阻之象；细滑相合，示虚中挟痰，非纯实邪，故治以和养，养营化痰并举。", ["细", "滑"]], "17523": ["病机", "脉息沉弦，沉主里、弦主肝，示病在里而肝邪化风。原文头痛频仍、右部为多、甚则满顶皆痛，且明言并无感冒、证情由内发，正合沉弦为内风上扰、营阴内亏之脉，久则虑其损目，故治以和养。", ["沉", "弦"]], "17524": ["病机", "脉见细弦，细为营血不足，弦为肝风内动。原文左面部抽搐无度，乃阳化内风入络、筋脉失养所致；脉细弦正示虚风而非外风，故治以和养，养血柔肝以息风。", ["细", "弦"]], "17525": ["病机", "脉见细弦，细主营虚，弦主肝阳。原文历节风走窜遍体、头痛耳鸣、颈项成疬，明言肝阳挟痰、营虚生风、气虚生痰；脉细弦正合虚风挟痰之机，故治以和养，标本兼顾。", ["细", "弦"]], "17526": ["病机", "脉细舌光，细为营血亏少，舌光示阴液不足。原文历节风象、逢骱皆痛，关节尽痛而脉不实，说明非风寒湿实邪，乃营虚生风、筋脉失养；脉细舌光正是阴营内亏之凭，故治以和养。", ["细"]], "17527": ["病机", "脉细舌光，细主营虚，舌光主阴亏。原文历节风痛由足及手、由右及左，痛势游走而脉细，明言属营虚生风；营血不足则筋脉失濡，虚风走窜致痛，脉细舌光恰为营阴亏虚之征，故治以和养。", ["细"]], "17528": ["病机", "脉见细弦，细为阴血不足、络脉失充，弦为肝木偏旺、筋脉拘急。骱酸痛且麻且肿，乃血虚不能濡养筋骨，肝风挟湿痹阻关节，故防成历节风痛；兼脘胀纳呆，是木旺乘土、脾运不健。细弦之脉正合血虚肝旺、风湿内蕴之病机。", ["细", "弦"]], "17529": ["病机", "脉见沉弦，沉主里、主湿，弦主风、主肝。湿热挟风外达肌表而发游风起瘰发痒，然脉不浮而沉，说明风湿热邪虽现于肌表，其根仍郁于里，肝经风热与脾湿相搏。沉弦为里湿兼风之象，故治以宣化，透达内外。", ["沉", "弦"]], "17530": ["病机", "脉见细弦，细为营血亏虚、脉络不充，弦为肝风内动、筋脉失柔。游风之类遍体滋窜，走窜不定正是风性善行之征，而脉细说明血虚生风、肌肤失养，风邪得以乘虚窜扰。细弦并见，示血虚风动之病机，故治以清养，养血以熄风。", ["细", "弦"]], "17531": ["病机", "脉见细弦，细主阴血不足，弦主肝木偏亢、风动于内。游风遍体、发痒无度，痒属风象，走窜遍体乃风性善行；脉细则知营血内亏，不能濡润肌肤，血虚生风化燥。细弦相合，正是血虚肝旺、风燥郁于肌腠之病机，故治以清降，清肝降火以息风。", ["细", "弦"]], "17532": ["病机", "脉见沉弦，沉为病在里、湿邪内郁，弦为肝风内动。游风渐成而上下体俱为滋蔓，风邪走窜无定；脉不浮反沉，说明风邪虽蔓于外，其湿热风根仍郁于里，肝风与内湿相合。沉弦示里湿挟风之机，故治以清化，清里化湿以除风根。", ["沉", "弦"]], "17533": ["病机", "脉细弦，细为营血亏少、脉络空虚，弦为肝风内动、筋脉不利。冷麻风且冷且麻，甚于右手左足，冷属阳气不达，麻属血虚失养，偏着一侧乃气血痹阻、风邪留着。细弦之脉示血虚风动、络脉痹阻之病机，故治以和养，养血和络以祛风。", ["细", "弦"]], "17534": ["病机", "脉见细弦，细为阴血亏虚，弦为肝木失柔。原文明言本元为虚、属水不涵木，指甲枯脱乃肝血不足、筋之余失养之征；肩风发于腰痛之后，腰为肾府，肾水亏则肝木失涵，虚风内动。细弦正合水不涵木、血虚风动之机，故治以和养。", ["细", "弦"]], "17535": ["病机", "脉细，为营血不足、气血两虚之象。体倦绵延示气虚不振，肩胛酸痛乃血虚络脉失养、筋脉不荣，纳呆为脾胃虚弱、运化无力。脉细与体倦、纳呆相合，说明正虚为本，气血亏虚则外邪易袭，故防成肩风。此段以细脉提示本元不足之病机。", ["细"]], "17536": ["病机", "脉见细弦，细为营血不足，弦为风邪入络、筋脉失柔。肩风酸痛而脉不浮不数，知非外感实邪，乃营亏络虚、风邪留着肩臂所致。细弦并见，正合“和养”之法，养营以柔筋，和络以祛风，故主肩风酸痛之营虚风扰证。", ["细", "弦"]], "17537": ["病机", "原文谓“气与营早亏，风与痰用事，脉见细弦”。细主气营两亏，弦主风痰阻络，故肩部结核不一。脉不滑大而细弦，说明痰非实热壅盛，乃虚中夹风痰，故治以调气化痰、和营熄风，脉象正示虚实夹杂之机。", ["细", "弦"]], "17538": ["病机", "胁痛目赤而脉见细弦，弦为肝脉，细为阴血不足。紫云风根未脱，风热内郁肝经，循胁上攻目窍，然脉细不数实，知非纯实火，乃肝阴亏而风热内扰。故治以清降，清肝降火而不伤阴，脉象示肝经风热兼阴伤之病机。", ["细", "弦"]], "17539": ["病机", "四弯风肢酸发痒，原文自注“肺脾为患”，脉见细弦。细为营血不足，弦为风动，肺主皮毛、脾主四肢，肺脾亏虚则营卫不充，风邪乘虚客于四弯，故酸痒并作。脉细弦正示营虚风扰、肺脾同病之机，非实邪壅盛。", ["细", "弦"]], "17540": ["病机", "四弯风拳至不仁，原文断为“气痹营伤”，脉见细弦。细主营血亏虚，弦主气机痹阻、风邪窜络。营伤则肌肤失养而不仁，气痹则络道不通而拳急，细弦并见恰合气痹营伤之虚实夹杂。故以药酒方疏和气血、通痹养营。", ["细", "弦"]], "17541": ["病机", "产后营亏生风，风邪挟湿走窜经隧，两足酸软、膝肿难屈、手麻，将成四弯风，脉见细弦。细为产后营血亏虚，弦为风邪挟湿痹阻经隧。脉不浮缓而细弦，知风非外袭，乃血虚生风、湿留隧络，故治以疏和，养血疏风兼化湿。", ["细", "弦"]], "17542": ["病机", "驴唇风根向春又发，脉见细弦。细为营阴不足，弦为风邪内动，春气升发引动伏风，故宿疾复发。脉细弦而不洪数，知非实热壅盛，乃营虚风扰、伏邪乘春而作。治以和养，养营柔肝以熄内风，正合细弦所示之虚风病机。", ["细", "弦"]], "17543": ["病机", "原文谓“禀体阴虚郁热蒸痰”，发于少阳为子母疬，发于阳明为驴唇风，脉见弦数。弦主少阳郁热、痰结络脉，数主热蒸，痧疹后阴分更伤则肌肤枯燥。弦数并见，示阴虚而郁热蒸痰、热势偏亢之机，故拟清养，清热养阴以化痰。", ["弦", "数"]], "17544": ["病机", "脉沉弦带滑，沉主里、弦主肝风、滑主痰湿，合之见气虚生湿、营虚生风，风湿流窜络脉。足跟酸痛为络脉痹阻之征，脉沉弦滑又提示湿浊风邪有上盛下轻之势，故防头眩耳鸣。此脉象与“防成漏蹄风”相应，说明病机在营虚气弱、风湿入络，治当镇养。", ["沉", "弦", "滑"]], "17545": ["病机", "脉见沉弦，沉为在里，弦为肝木失和、络脉拘急。昔年痞散下血过多，血去则络脉失养，颈项转侧不利、两足骨粗肉削，渐成鹤膝风象。沉弦在此非表邪，而是营血亏虚、肝络不和之里证脉象，故治以和养，养血和络以缓其拘急。", ["沉", "弦"]], "17546": ["病机", "脉见细弦，细为营阴不足，弦为肝气偏旺。肝气犯中，中焦积痰蓄饮，故当脘痛胀、吞酸吐沫；气入于络，则腰背胁部及手足络脉牵引；奇经失禀丽，产后经久不行。细弦正合营亏气痹、木土不协之机，说明病本在营虚而标在肝气痰饮，治以和养。", ["细", "弦"]], "17547": ["病机", "脉见细弦，细主营阴大伤，弦主厥阴肝邪鸱张。产后营亏，春令应肝，肝邪既犯中又入络，故脘腹胀满、遍体络脉牵引不和；肝通于心则心悸，奇经失丽则癸事不行。细弦揭示营亏气痹、木土不协之病机，非单纯实邪，故治以调降，寓养于调。", ["细", "弦"]], "17548": ["病机", "脉见细弦，细为营阴日亏，弦为肝木失养化气侮中。产后血晕受伤，奇经不调，崩放后经事二年未行而带脉不固；肝气或呕或胀、少腹痞攻，化风上扰则痛晕头昏。舌苔前半光剥更证营虚。细弦紧扣营虚气痹、木土不协，故拟调养，非攻伐所宜。", ["细", "弦"]], "17549": ["病机", "脉见细弦，细主营亏，弦主气痹肝郁。连次偏产，营阴屡伤，气机痹阻，肝木失于柔养，横逆犯中，故当脘作胀、纳食久呆。细弦在此说明病机为营亏气痹、木土不协，而非实热积滞，故治以和养，养营柔肝以复中焦升降。", ["细", "弦"]], "17550": ["妇人", "脉息滑数，滑为血盛养胎之象，数为胎火内动。怀麟有兆，适当手厥阴司胎，胎火上升则面热，胎络下损则腰楚；由手经病及足经，肝气内扰，或胀或痛、吞酸发嗳。滑数在此主胎孕而兼火，故拟调养，藉防滑胎，非一般湿热脉可比。", ["滑", "数"]], "17551": ["病机", "脉见细弦，细为营阴不足，弦为肝气郁动。气郁动肝，肝邪充斥，中焦受侮，故当脘作痛，痛势扰腰及背皆为牵引。细弦说明此痛由肝气横逆、络脉拘急所致，而非寒凝食积，故治以调降，降肝气以和中也。", ["细", "弦"]], "17552": ["病机", "脉见细弦，细为血虚，弦为肝旺。血不养肝则肝体失柔，肝气充斥横逆，犯胃则呕逆无度，侮脾则便溏，脘宇结痞攻无度甚至大如覆盘，皆肝气乘脾犯胃、气结不行之象。脉细弦正合血虚肝郁、木旺克土之病机，故治以疏和。", ["细", "弦"]], "17553": ["病机", "脉见沉细，沉主里、主肾，细主精血不足。淋浊止后精溺未曾分清，肾关失职，以致中焦失运，吞酸吐沫、结痞作胀。肾为胃关，肾虚则关不利而中焦升降失司，脉沉细正是肾虚于下、中运不健之征，故拟固肾养肝、柔肝保胃。", ["沉", "细"]], "17554": ["病机", "脉见沉弦，沉主中焦里气不达，弦主气机郁滞、饮邪内停。当脘满闷、屡屡发嗳、多纳即胀，是脾失其使、胃失其市，中焦升降失职，水谷不化精华而反生痰饮。脉沉弦正应中焦气滞饮停之机，久则恐成反胃，故治以调降。", ["沉", "弦"]], "17555": ["预后", "脉见弦数，弦主筋脉拘急、肝肾不足，数主虚热内扰。环跳酸痛、背脊酸软、尾闾尤甚，皆督脉与筋骨失养之候。脉弦数示阴损而虚热内生，故原文恐其由损经而进劳径，有人身缩短之虞，是提示病势向虚劳深入之预后，非仅言主病。", ["弦", "数"]], "17556": ["病机", "脉见芤弦，芤主失血伤阴，弦主肝郁气滞、胸胁引痛。咳呛绵延、连次失血，又伤于产乳与殴打，阴血亏耗而肝失所养，故头眩艰寐、潮热形寒、胸胁肩背引痛。芤弦并见，正合阴血虚而肝气不柔之病机，治以和养。", ["芤", "弦"]], "17557": ["病机", "脉见沉弦，沉主里、主络脉受伤，弦主痛、主肝郁。季胁为脏会之所，内络受伤则胁痛频仍，形黄便血亦由络伤血溢、肝脾不调所致。脉沉弦正应内络受损、气血郁滞之机，故治以疏和，使络气和畅。", ["沉", "弦"]], "17558": ["病机", "脉见细弦，细主气阴不足，弦主肝气不柔。迸力伤气，气不摄血，血为暴吐，咳嗽神疲，皆气伤血失所摄之候。脉细弦说明气分已虚而肝木偏旺，虚而兼郁，故治以疏和，疏其肝气、和其气血。", ["细", "弦"]], "17559": ["病机", "脉息弦滑，弦主气分不调、肝郁胁痛，滑主痰湿内蕴、痞攻隐见。跌仆受伤则左胁作痛，腹部痞攻或隐或见，纳食呆钝而胀满，皆气分不调、痰气交阻之象。原文谓阴虚之体、气分不调，弦滑正应气郁痰滞之病机，故拟和养。", ["弦", "滑"]], "17560": ["病机", "脉见浮滑，浮为邪在表分，滑主湿痰内蕴。春温挟湿，温邪未离卫表故身热微寒、有汗不解；湿性黏滞，与温相合，郁蒸于中，故舌色带灰。浮滑并见，正示温邪挟湿、表里同病之机，治以分泄，即透表与化湿并行。", ["浮", "滑"]], "17561": ["病机", "脉息滑大，滑主热盛痰壅，大主阳明邪炽。春温之邪扰于阳明营分，热迫血溢则牙衄，热蒸浊气上泛则口臭。滑大之脉与牙衄口臭相应，明示阳明营分热盛，故拟清降，兼顾痘毒未清，防余毒与温邪相合。", ["滑", "大"]], "17562": ["病机", "身热渐除而脉息细弦，细为阴分不足、正气渐耗，弦主气机郁滞、肝木偏旺。咳呛脘闷，乃余邪未清、肺胃气机不畅，细弦正合热退后阴伤气郁之象。故再以分泄，疏其郁滞、泄其余邪，而不宜纯补。", ["细", "弦"]], "17563": ["病机", "脉见浮弦，浮为温邪郁于表分，弦主邪郁气机、木火偏亢。身热不解、头痛口渴，皆温邪郁蒸、热势向外向上之征；势将发㾦，为郁热欲透肌肤。浮弦之脉正应邪郁未透、热蒸欲发之机，故治以分泄，透达郁邪。", ["浮", "弦"]], "17564": ["病机", "脉见浮弦，浮主新感外邪在表，弦主旧伤气滞、络脉不和。旧伤新感相合，寒热咳呛为表邪犯肺，胁旁引痛为气机郁滞、络道不畅。浮弦并见，示外感与内伤气郁并存，故治以和降，既和表邪，又降气机、通络止痛。", ["浮", "弦"]], "17565": ["病机", "脉浮而身热少许，脘痛便秘，是表邪虽解而里气未通。浮脉在此示余邪仍偏于外，里滞未下，故脘痛便闭；里热不清，仍防神志昏迷。脉浮与表解里未通相应，说明不可纯攻，拟清泄以清余热、泄里滞，表里兼顾。", ["浮"]], "17566": ["病机", "脉两手弦数，弦主气逆、木火偏亢，数主热盛。风温犯肺，郁热蒸痰，故咳嗽喉鸣、气逆胁痛；舌苔罩灰质红起腐，为热灼津伤、势将劫津之兆。弦数之脉正应热盛痰壅、气逆津伤之机，故拟清解，清肺化痰以护津液。", ["弦", "数"]], "17567": ["病机", "脉两手数大，数主热盛，大主邪实壅盛。舌尖绛有芒削、肌灼少汗，为热灼营阴；脘腹胀痛拒按、便闭口渴，为食滞中焦、腑气不通；谵语手痉，乃邪入营分、热扰神明、动风之象。数大之脉与邪实热盛相应，故称棘手难许无虞。", ["数", "大"]], "17568": ["病机", "脉沉弦者，湿邪内郁，沉主里、弦主郁。霉令将临，湿邪内动，郁于阳分则形寒形热，郁于阴分则便涩溺短。沉弦正合湿郁气机不畅之象，故治以疏和，疏其郁滞、和其阴阳。", ["沉", "弦"]], "17569": ["病机", "脉细弦，细为湿滞阴伤、弦为气机郁滞。湿邪稍泄而湿蒸未除，口甜或咸、脘闷纳呆、便艰、浑身痹痛，皆湿郁阳明、机关不利之候。细弦示湿郁未化、气机不畅，故拟疏和以化湿调气。", ["细", "弦"]], "17570": ["病机", "脉细弦，细主湿滞、弦主气郁。湿邪分布三焦，清不升而浊不降，故头眩肢酸、脘腹胀闷、气道不通、便艰舌黄。细弦正示湿郁三焦、气机壅滞，故拟芳香调中、分化上下，使湿浊分消。", ["细", "弦"]], "17571": ["病机", "脉弦滑，弦主气郁、滑主湿痰。身热淹缠、形寒头痛、脘闷肢酸，乃湿邪郁遏、气机不畅之候。弦滑示湿郁化热、痰湿内蕴，故治以分泄，分利湿邪、泄其郁热。", ["弦", "滑"]], "17572": ["病机", "脉细弦，细为湿滞、弦为气郁。寒热渐除而肢酸脘闷、二便少畅，示湿邪未尽、气机未复。细弦正合湿郁气滞之象，故治以疏泄，疏其气机、泄其余湿。", ["细", "弦"]], "17573": ["病机", "脉细弦，细主湿滞、弦主气郁。身热不扬、寒少热多、脘满舌白、口渴不甚引饮，皆湿温郁遏、气机不畅之候。细弦示湿郁未化，故治以分泄，分利湿邪以畅气机。", ["细", "弦"]], "17574": ["病机", "脉浮弦，浮主邪在表、弦主肝气郁滞。脘宇胀满，肝气又复感邪，寒寒热热，防发疹㾦。浮弦示外邪与肝郁相兼，邪郁肌表、气机不畅，故治以分泄，分泄表邪、疏调肝气。", ["浮", "弦"]], "17575": ["病机", "脉芤大，芤主失血伤阴、大主邪盛。下血伤体，感受湿温，身热不扬、头痛便溏。芤大示阴血已伤而湿温之邪仍盛，正虚邪恋，故治以分泄，分利湿邪而不伤正。", ["芤", "大"]], "17576": ["病机", "脉见沉弦，沉主里、弦主痛主风，说明风暑湿三邪互缠，邪郁于里而不在表。头痛肢酸为外寒内热、风湿阻络之象，沉弦正合邪郁于里、气机不畅之病机，故治以疏和，疏其郁滞、和其表里。", ["沉", "弦"]], "17577": ["病机", "脉见浮大，浮主表、大主邪盛，说明霉令感邪后表里尚欠宣通，邪未透达。体倦绵延、脘满纳呆、头痛溺赤、舌腻，皆湿邪内蕴、表气不宣之候，浮大之脉正应邪郁肌表、正气尚能抗邪，故治以分泄，分利表里之邪。", ["浮", "大"]], "17578": ["病机", "脉数口渴，数主热、主邪盛，说明风暑互感，热邪内炽。身热头痛、咳呛鼻衄，皆风暑上扰、热伤肺络之象，数脉与口渴相应，正合热盛伤津之病机，故治以分泄，清泄风暑之邪。", ["数"]], "17579": ["病机", "脉见沉弦，沉主里、弦主气机郁滞，说明湿浊困中，邪阻于里。当脘懊𢙐、口苦舌腻，皆湿浊内蕴、中焦气机不畅之候，沉弦正合湿困中焦、气机郁滞之病机，故治以疏和，疏畅中焦、化其湿浊。", ["沉", "弦"]], "17580": ["病机", "脉见弦滑，弦主痛主气机不畅，滑主痰湿内盛，说明寒热后痰湿内阻、气机不通。当脘心痛、痛连腰背、时时泛水，皆痰饮内停、气机壅滞之象，弦滑正合痰湿内阻、痛由气滞之病机，故治以疏和，疏其气机、化其痰湿。", ["弦", "滑"]], "17581": ["病机", "脉细弦，细主气血不足、弦主气机不畅，说明中气不足而湿浊未清，虚实夹杂。纳少神倦、脘嘈气怯，皆中气虚弱、湿浊内阻之候，细弦正合正虚邪恋、气机不舒之病机，故再疏和，于疏理之中兼顾中气。", ["细", "弦"]], "17582": ["病机", "脉见弦滑，弦主气机不畅、滑主痰湿，说明湿温之邪渐得清彻而中气已伤，余湿未净。神疲肢倦、纳食未得如常，皆中气受伤、湿浊留恋之候，弦滑正合半虚半实之病机，故拟从半虚半实调之，扶正与化湿并行。", ["弦", "滑"]], "17583": ["病机", "脉见沉弦，沉主里、弦主痛主气机郁滞，说明便溏后湿浊内留、中焦气机不畅。腹痛纳少，皆湿困中焦、气机郁滞之候，沉弦正合邪郁于里、气机不舒之病机，故治以疏和，疏畅中焦气机、化其湿浊。", ["沉", "弦"]], "17584": ["病机", "脉见濡细，濡为湿郁，细为正气不足。原文述身热少汗、胸脘满闷、恶心、神昏谵语、舌胖言强，乃外受风寒、内热湿温，三焦弥漫，邪无出路。濡细示湿邪困阻而正虚，无力鼓邪外达，故表汗不多、里便不爽，势防厥逆，若隐疹不透则证非稳当。", ["濡", "细"]], "17585": ["病机", "脉见滑大，滑主湿温郁蒸，大示邪势尚盛。原文寒热未除、得汗不解、脘闷耳聋、渴不多饮、舌苔带灰，为湿温郁蒸表里解而未畅。经后营舍空虚，滑大之脉虽主邪实，然营虚防劫津为变，故须兼顾清化而不宜峻攻。", ["滑", "大"]], "17586": ["病机", "脉右部尚大、左部带数，右大主湿温余邪未净，左数示营分尚有郁热。原文表得汗透、里得两便通行，邪已有出路，耳聋减、神志清，惟舌苔仍灰腻，说明湿浊未化尽，脉右大正是湿邪留连之征，故再从清化以彻余邪。", ["大", "数"]], "17587": ["病机", "脉见浮弦，浮主邪在表分，弦主气机郁滞。原文身热出㾦、脘闷便溏，㾦为湿邪外透之象，脘闷便溏示湿困中焦、脾胃升降失司。浮弦说明表邪未解而里有气滞湿阻，故治以分泄，使表里之邪分途而解。", ["浮", "弦"]], "17588": ["病机", "脉见细弦，细为营阴不足，弦为气机郁滞。原文疹㾦密布、脘闷神烦、寒热或轻或重，疹㾦密布示邪有外透之势，然细弦说明正气已伤、邪郁未彻，故寒热起伏不定。治以分泄，意在疏泄郁邪而不伤正。", ["细", "弦"]], "17589": ["病机", "脉数而滑，数主热盛，滑主湿浊壅盛。原文寒热未解、脘闷气急、呕逆、溏稀，邪势未宣化；两寸独不应指，示上焦气机闭塞，不能宣物，虽有疹㾦不能由里达表。数滑之脉正合湿热内壅、上焦不宣之机，故治以清泄。", ["数", "滑"]], "17590": ["病机", "脉见细弦，细示营阴不足，弦主气机郁滞。原文身热白㾦先起、脘闷呕逆，白㾦为湿邪外透，脘闷呕逆示肺胃受病、升降失和。细弦说明肺胃气郁而正已不足，故治以分泄，疏泄肺胃郁邪而不伤正。", ["细", "弦"]], "17591": ["病机", "脉见弦滑，弦主气机郁滞，滑主痰湿内蕴。原文痧㾦后内热未清、纳呆咳呛、耳聋盗汗，痧㾦后余热未彻，痰湿恋肺则咳呛，纳呆示脾胃未复，盗汗示营阴已伤。弦滑之脉说明余邪痰湿未净而气机不畅，故治以清养，清余热而养营阴。", ["弦", "滑"]], "17592": ["病机", "疹痧后阴液耗伤而热邪炽盛，故见耳聋盗汗、咳呛肌灼。弦为阴伤木旺、肝火内扰之象，数为热炽之征，弦数相合，说明阴虚不能制火、热势鸱张，正合原文“阴伤热炽”之机，故以清养为治。", ["弦", "数"]], "17593": ["病机", "㾦后内热未除，口渴纳少，脉见沉弦。沉主里、主气机内郁，弦主木旺、主痛与气滞，沉弦并见说明余热内伏于里、肝胃气机不和，热郁而津未复，故口渴纳少，治以和养，正合里热未清、胃气未和之病机。", ["沉", "弦"]], "17594": ["病机", "身热出㾦而㾦色枯白，口渴无度、大便溏薄，脉见细弦。细为阴血不足、脉道不充，弦为木旺乘土、气机郁滞，细弦相合说明阴伤而脾运受抑，津不上承则渴，脾失健运则溏，故治以分泄，兼顾咳呛耳聋之肺窍不利。", ["细", "弦"]], "17595": ["病机", "㾦随汗出、汗随热泄，呕恶绵延，脉见细弦。细主阴液亏耗、脉道失充，弦主肝木偏旺、犯及肺胃，细弦说明汗出伤阴而木气不柔，肺胃升降失和，故呕恶绵延，原文断为“肺胃之病”，治以和养，正合阴伤气逆之机。", ["细", "弦"]], "17596": ["病机", "寒少热多、白㾦出没、脘腹痛胀不减，脉左弦右滑。左弦为肝胆气郁、邪留气分，右滑为痰湿内蕴、胃有实邪，弦滑并见说明虚中挟实、实中挟虚，气分邪逗留不解，舌苔前半脱液根腻亦示津伤而湿滞，故拟分化三焦兼存津养液。", ["弦", "滑"]], "17597": ["预后", "湿温误下，胃阴胃气两伤，纳食不思、肢清气怯、睡中露睛、汗多发冷，脉左部模糊、右大至数不匀。模糊为正气溃散、脉道不清，右大而数不匀为胃气衰败、脉失柔和，正虚不能胜邪，故原文断“防正不胜邪，由闭而脱”，属危重预后。", []], "17598": ["预后", "昨投清营养胃，便溏止、舌灰退，阴液有上升之势，四肢虽清而热来尚暖，脾阳有灌溉之机。然误下伤阴，胃无醒豁之象，纳食不思、汗出淋漓，心失营液所养而神志倦怠，脉象如昨示胃气未复，故再以前意增损，属正虚未复之预后判断。", []], "17599": ["病机", "身热脘闷、痱疹满发，脉见弦滑。弦主气机郁滞、木旺不舒，滑主痰湿内盛、邪实有余，弦滑相合说明湿热痰浊壅阻气分、郁于肌表而发疹，脘闷为气机不畅之征，故治以分泄，使三焦气分湿热得以分化外达。", ["弦", "滑"]], "17600": ["病机", "脉右部如无，左部细数，右部如无提示气机壅塞、痰热内闭，左细数为阴伤热扰。患者吸烟体虚，通宵不寐，邪热迅速入里，神志模糊，舌光红根灰，为热陷心包、痰蒙清窍之象，故脉细数主内热伤阴，右无主痰闭气阻。", ["细", "数"]], "17601": ["病机", "脉右部已起，且滑且大，微带数象，左部一律如是，滑主痰，大主热盛，数主热，说明风暑挟痰未清，邪势仍张。症见身热有汗不多、口渴无度、脘窒、舌灰退而根黄腻尖光绛，为痰热内蕴、津伤未复，脉象反映邪从里透而未尽。", ["滑", "大", "数"]], "17602": ["主病", "脉见浮弦，浮主表邪，弦主风动或饮邪。症见身热头痛咳呛、舌光口渴无度，为风热犯肺、表邪未解，热灼津伤。浮弦脉提示风邪在表，肺失宣降，故治以分泄，使邪从表解。", ["浮", "弦"]], "17603": ["病机", "脉见弦大，弦主燥邪郁滞，大主热盛。寒热后燥邪未清，客于肺胃，致牙龈浮肿、咳呛无度、舌苔光红，为燥热伤肺胃之阴，脉弦大反映邪热未彻而阴液已伤，治以清泄。", ["弦", "大"]], "17604": ["主病", "脉息浮大，浮主邪在表，大主热盛。燥邪客于上焦，症见牙肿喉痛、咳呛不爽，为燥热上攻清窍，肺失清润。浮大脉提示燥热之邪偏表偏上，治以辛凉透泄。", ["浮", "大"]], "17605": ["病机", "脉见弦数，弦主痰饮内阻、气机不利，数主热。痰热内阻会厌，呼吸不利，哮声如锯，为痰热壅肺、气道不畅。弦数脉反映痰热交阻，肺窍不利，故拟宣肺窍而化痰热。", ["弦", "数"]], "17606": ["主病", "脉息数大，数主热，大主邪盛。咽喉红痛、身寒发热、咳嗽口渴，为风热外袭，肺胃热盛。数大脉提示邪热方张，病势急，治以辛凉分泄，使热从表解。", ["数", "大"]], "17607": ["预后", "脉两手滑大，左右寸重按模糊，滑主痰热，大主邪盛，重按模糊为正气渐虚、邪陷之兆。冬温郁蒸，邪势方张，精液劫烁，舌灰薄如烟煤，神昏动风，高年正虚邪炽，脉象示邪盛正衰，势防内闭外脱，预后堪忧。", ["滑", "大"]], "17608": ["病机", "脉见浮弦，浮主表、弦主饮主痛，身热无汗、咳呛口渴、入夜谵语，显系冬温之邪束表，痰热内郁，有内陷心包之势。浮为邪在卫表，弦为痰饮内结，故防冬温内陷为变，治以辛凉透解。", ["浮", "弦"]], "17609": ["病机", "脉大而咽喉红痛、内热、染苔舌灰，为风暑挟痰郁于上焦，热势鸱张。大脉主热盛邪实，气分热炽，故脉形宽大，治当清凉分泄，使上焦郁热从表里分消。", ["大"]], "17610": ["病机", "咽喉红痛减而未除，脉大身热，是风暑痰热余邪未尽，仍踞上焦气分。大脉未敛，说明热势未清，故再以分泄，续清上焦郁热，防其复炽。", ["大"]], "17611": ["病机", "脉浮大，伴项肿咽痛、口疳满布，为风暑挟痰上攻，郁于上焦。浮主邪在表分，大主热盛，风暑痰热交蒸，故脉浮大，治以分泄，使邪从表里分消。", ["浮", "大"]], "17612": ["病机", "身热微寒、咳嗽头痛，势将发痧，脉见浮大。浮为邪郁肌表，大为热盛，风暑之邪欲从表透发，故脉浮大，治以分泄，因势利导，透邪外出。", ["浮", "大"]], "17613": ["病机", "风痧已发，布于四肢头面，咳呛口干、咽喉红肿，脉见浮大。浮大之脉示风热之邪仍在气分，未全清解，故治以清解，清透气分余热。", ["浮", "大"]], "17614": ["病机", "脉数大，喉腐，为热毒烁肺，气分热炽。数主热，大主邪盛，热毒壅肺，故脉数大，治以清化，清肺解毒，防热毒内陷。", ["数", "大"]], "17615": ["病机", "痧后食复，身热有汗，素脾胃失健，腹痛便溏，脉见细弦。细为阴血不足，弦为肝木乘脾，脾虚食滞，故脉细弦，治以疏和，疏肝健脾，消食和胃。", ["细", "弦"]], "17616": ["病机", "寒热后胃气为逆，呃忒频仍、纳呆脘闷，脉见细弦。细为胃气不足、阴血亏虚，弦为气机郁滞、肝木犯胃，故细弦并见提示胃虚气逆、肝胃不和之病机，与呃逆、纳呆、脘闷诸症相应，治以疏和即疏肝和胃。", ["细", "弦"]], "17617": ["病机", "右脉模糊主湿浊痰蒙、气机不畅，左脉细弦主阴寒外束、肝经郁滞。寒热不扬、神迷发痉、口渴无度、呃忒频仍，乃阴寒外束而湿热内蒸，邪无出路，故脉细弦与模糊并见，提示正虚邪陷、闭脱之危，急防闭脱。", ["细", "弦"]], "17618": ["病机", "挥霍扰乱、泻而兼呕，脉见细弦。细为脾胃虚弱、津气耗伤，弦为气机逆乱、木乘土位，故细弦提示脾胃受损、肝气横逆、升降失司之病机，与吐泻交作相应，治以苦辛通降以调升降。", ["细", "弦"]], "17619": ["病机", "上吐下泻、汗冷肢清，脉细兼弦。细主阳气衰微、气血不足，弦主气机郁滞、寒邪内侵，故细弦提示中阳不振、寒湿内困、升降悖逆之病机，与吐泻、汗冷、肢清相应，治以疏和以温运调中。", ["细", "弦"]], "17620": ["病机", "挥霍扰乱、上吐下泻、当脘懊𢙐、汗多肢清，脉来沉细。沉主病在里、阳气内困，细主气血不足、阳衰液耗，故沉细提示中阳衰微、寒湿内盛、正气欲脱之病机，与吐泻、汗多、肢清相应，治以分疏以分利湿浊。", ["沉", "细"]], "17621": ["病机", "霍然扰乱、吐泻脘闷，脉见沉弦。沉主病在里、气机内郁，弦主气滞不畅、木克中土，故沉弦提示寒湿内阻、肝胃气滞、升降失司之病机，与吐泻、脘闷相应，治以分泄以分消湿浊、疏畅气机。", ["沉", "弦"]], "17622": ["病机", "游风多年变为囊风，流滋发痒甚于下部，脉来弦滑。弦主风动、肝经郁滞，滑主湿浊痰热内蕴，故弦滑提示风湿热邪下注、肝经湿热之病机，与囊风流滋发痒相应，治以清化以清利湿热。", ["弦", "滑"]], "17623": ["病机", "一岁小儿惊风挟痰、气逆音嘶，脉弦。弦为肝风内动、气机逆乱之象，小儿肝常有余，痰随风动，故脉弦提示肝风挟痰、气逆上壅之病机，与惊风、气逆、音嘶相应，治以清泄以清肝化痰。", ["弦"]], "17624": ["病机", "脉见浮弦，浮主表邪未解，弦主痰饮内伏、气机郁滞。哮喘重发而痰不爽吐、带腥臭，是外寒引动内饮，痰热胶结于肺，肺失宣降。浮弦并见，说明表邪与里饮相搏，故治以宣解兼顾形寒形热，解表化饮并行。", ["浮", "弦"]], "17625": ["病机", "脉见细弦，细为阴血亏虚、娇脏失养，弦为气机郁滞、痰瘀阻络。久咳不已致肺阴耗伤，痰中带血、色黄或绿，肺痿渐成，是阴虚火旺、灼津成痰、损伤肺络之象。细弦反映正虚邪恋，故治以清养，清虚热而养肺阴。", ["细", "弦"]], "17626": ["病机", "脉见细弦，细主正虚，弦主饮邪内停、气逆不降。内有痰饮、外感风寒，哮嗽有根而发重，胸次痹闷、气逆喉鸣，是外寒引动伏饮，痰气交阻于胸膈。细弦示饮盛而正气已伤，故治以和降，降气化痰以平喘逆。", ["细", "弦"]], "17627": ["病机", "脉息细弦，细为正气不足，弦为痰饮内结、气机不畅。胸痹喉鸣、哮喘又发，是痰饮上逆、痹阻胸阳，肺气不得宣降。细弦并见，说明久病正虚而饮邪未化，故治以和降，和其正气而降其痰逆。", ["细", "弦"]], "17628": ["病机", "脉细主正气不足、气血亏虚。哮嗽重发、喉鸣气逆，又见寒热，是旧病痰饮未除而新感外邪，正虚不能抗邪，故脉不浮而反细。细脉提示新邪虽在表而里气已虚，治以和养，不可峻散，当养正以和营卫。", ["细"]], "17629": ["病机", "脉息沉弦，沉主病在里、水饮内停，弦主气机郁滞、痰饮结聚。哮嗽重发即为肺胀，喉痰呜呜未能爽吐，是痰饮壅盛于肺，气逆不得宣降，病位深在里分。沉弦示饮邪内结而肺气壅实，故治以疏降，疏肺气而降痰饮。", ["沉", "弦"]], "17630": ["病机", "脉息细弦，细为久病正虚，弦为痰饮未净、气机尚郁。肺胀频仍而咳痰稍松，是痰饮渐化而肺气未复，细弦说明饮邪虽减而正气已伤。故宣肺气以复其宣降，豁痰饮以除余邪，标本兼顾，不可纯补纯攻。", ["细", "弦"]], "17631": ["病机", "脉见细弦，细主正虚，弦主痰饮内盛、气逆不降。痰沫涌吐、哮嗽日进日深，是痰饮泛滥、肺气上逆，久病正虚而饮邪愈盛。细弦反映虚中夹实、饮盛气逆，故拟和降，和其正气而降其痰沫，以平哮嗽。", ["细", "弦"]], "17632": ["病机", "脉见细软，细为阴血不足，软为气虚不任，左关较弦则肝木偏旺。原文谓“操心过度”，心居肺肾之间，艰寐懊𢙐、侵晨出汗，皆心阴心气两亏、肝阳不潜之象。细软示虚多，弦示气机不舒，故以甘缓调降摄心神，属虚多邪少之病机。", ["细", "软", "弦"]], "17633": ["病机", "脉息细弦，细主营亏，弦主气痹。原文“上虚生痰，下虚生饮”，痰饮蓄积多年，咳喘不能睡，乃肺俯肾仰失司；女科以肝为先天，冲海无权、月事多年未行，诸虚杂出。细弦正是虚多感少之征，非干血成劳，故拟甘缓调降。", ["细", "弦"]], "17634": ["病机", "脉息细弦，细为虚，弦为饮。原文“痰饮内积，肺肾气道失宣”，咳呛无度、痰多气喘，皆痰饮阻遏、肺肾出纳失职所致。细弦示正虚而饮邪内踞，虚中夹实，故治以和降，使气降痰消。", ["细", "弦"]], "17635": ["病机", "脉息细软，细主阴亏，软主气虚。原文“冲失坐镇，气从腹旁上冲”，咳嗽甚于早起、有时发呕，乃冲脉不摄、气逆犯肺。细软为虚象，故断为“虚多邪少”，从虚调之，以甘缓镇冲降逆。", ["细", "软"]], "17636": ["病机", "脉见沉弦，沉主里主饮，弦主气逆。原文“气虚积饮，肺失卫外”，每发先寒热，气喘痰沫、屡屡发呕，皆饮邪内伏、卫外不固之象。沉弦示病根在里，饮积日久，故治以和降，化饮降逆。", ["沉", "弦"]], "17637": ["病机", "脉见细弦，细为阴虚，弦为饮聚。原文“气虚生痰，阴虚生饮”，痰饮咳嗽、肺俯肾仰失司，正虚而饮邪内停。细弦示虚多实少，且阴亏易伤络脉，故预告“慎防络伤失血”，拟和养兼顾。", ["细", "弦"]], "17638": ["病机", "脉之细弦，细主正虚，弦主表里不和。原文“痰饮伤中”，中主表里之权，咳嗽未减而寒热交作、肢冷背寒、神疲嗜卧，舌黄剥，显属表失卫外、里失主中。细弦正合虚而夹邪、表里同病之机。", ["细", "弦"]], "17639": ["预后", "原文未识脉名，仅言“两脉俱静”，静为平和之象。左静则根本无损，右静则感冒渐清，寒热止、大便通，惟侵晨咳痰白沫黏腻，恐扰动肺痿旧根。脉静示邪退正安，故属预后佳象，然长夏炎热，仍须清热和阴、新旧兼顾。", []], "17640": ["病机", "脉左细右弦，左细为气虚血少，右弦主气机不和。咳嗽绵延、音嘶痰沫、肉落气逆，皆气虚失运、肺金不降之象。细脉示正气不足，弦脉示气逆不柔，故云“气虚见症为多”，治以和养，正合虚中夹逆之机。", ["细", "弦"]], "17641": ["病机", "脉见细弦，细为阴血不足，弦为气机偏亢。咳嗽绵延、背脊酸痛、恶风神倦，显系气阴两伤、卫外不固。春季失血虽不多，然细弦之脉已示脱力内伤、气与阴两为不足，故治以和养，不可峻补峻攻。", ["细", "弦"]], "17642": ["病机", "脉芤主血虚失守、营阴外泄。咳嗽未减、夜重于日、痰多气怯，已见肺气耗伤；形寒潮热乃营卫两伤之候。芤脉中空，正合失血后阴血不充、营卫失调之机，故曰“营卫之伤最难调护”，治以和养。", ["芤"]], "17643": ["病机", "脉息沉弦，沉主病在里，弦主肝气劲急。原文谓“肝升太过，肺降无权”，故咳呛绵延、气逆无痰、胁痛、面部火升。沉弦示肝邪内郁、气火上逆，势防天热失血，治以清降，正针对肝升太过之机。", ["沉", "弦"]], "17644": ["病机", "脉息细弦，细为阴分不足，弦为肝气不柔。因感起咳、咳而无痰、胁痛气逆，乃外感引动肝逆、肺失清降。细弦并见，示阴血已伤而气机偏亢，最防失血成劳，故治以和养，兼顾气阴。", ["细", "弦"]], "17645": ["病机", "脉左部弦大甚于关位，关候肝，弦大为肝邪炽盛之象。素有遗泄，水不涵木，厥阴失养，以致升多降少、上烁娇脏，咳呛气逆。更因失血连次、所吐甚红，阴伤及气，食后腹胀，防足肿便溏而过中难治。", ["弦", "大"]], "17646": ["病机", "脉见数滑，数为热象，滑主痰湿内蕴。失血渐止而痰中带溢，咳呛胁痛，乃肝肺两虚、痰热未清之候。数滑示余热夹痰，青年防入损途，故再从清养，清其余热、养其肝肺。", ["数", "滑"]], "17647": ["病机", "复诊脉仍数滑，失血虽平而肝升肺降未知，痰胶气逆、咳呛夜甚，显系痰热内恋、肺降未复。数滑之脉示热未清、痰未化，故再从清养，兼和中以开胃纳，使痰热渐化而胃气渐复。", ["数", "滑"]], "17648": ["病机", "脉息弦滑，弦为肝旺不和，滑为痰湿内蕴。连年见血逢节而发、整口色鲜，乃阳明络损累及肝肺，肺失肃降则咳呛，肝失条达则胁痛；音嘶盗汗潮热形寒，是阴损及阳、营卫俱伤。弦滑示肝肺同病、痰热未清而正气已损，故治以和养，重在调肝肺、护脾胃。", ["弦", "滑"]], "17649": ["病机", "左脉弦数，弦主肝郁，数主热盛。英发太早、湿热下注致肛痈未敛、内管渐成，肺与大肠相表里，湿热上蒸则咳嗽绵延、痰薄且黏。弦数示肝经湿热内蕴、木火刑金，夏令火旺易迫血妄行，故防失血成损，治以清养急和，清湿热、保肺阴。", ["弦", "数"]], "17650": ["病机", "脉见芤数，右部为甚。芤主失血伤阴，数主虚热内扰。早遗近血，阴精亏耗，肝升肺降失司而咳逆气促；穷则伤肾，诸虚杂出，形寒潮热、咽干艰寐、腰酸盗汗，皆阴损及阳、虚火浮动之候。右部为甚，示肺胃之气亦伤，故治以和养，滋阴配阳。", ["芤", "数"]], "17651": ["预后", "脉见细软，细为阴血亏少，软为正气衰弱。遗泄失血虽减，而咳嗽气怯、喘须高枕、痰多成罐，是肺肾两虚、痰饮上泛；营卫偏胜则形寒潮热出汗，心烦神倦。细软示根本大伤、气血俱亏，故虑夏令能否有减无损，再拟甘平清降以扶正清痰。", ["细", "软"]], "17652": ["病机", "脉沉弦，沉主病在里，弦主肝郁气滞、血瘀不通。跌仆受伤，瘀血留着左胁，气机壅遏则迸痛；瘀阻胃络，血不循经而呕血又发。沉弦正合内伤瘀阻、肝胃气逆之机，故治以和降，降气行瘀、和胃止血。", ["沉", "弦"]], "17653": ["病机", "脉见沉弦，沉为病在里，弦为肝气偏旺、气逆血壅。勃然吐血而两胁作痛，乃肝火犯胃、气逆血溢，血随气上出于胃络。沉弦示病位在里、肝胃同病，气机郁逆为其关键，故治以和降，平肝降逆、和胃止血。", ["沉", "弦"]], "17654": ["病机", "脉见沉弦，沉主里，弦主肝郁气逆。血随气沸、勃然吐血，当脘发迸、两胁引痛，是肝气横逆、胃络损伤，血因气逆而妄行。沉弦正示内伤胃络、肝胃气逆之病机，故治以和降，降气平肝、和胃宁络。", ["沉", "弦"]], "17655": ["病机", "脉见芤大，芤主失血，大主虚而气浮。无端失血、整口色鲜，由胃络损伤累及肝肺，阴血骤亏则气失所附，渐加咳嗽。芤大示血去阴伤、虚阳浮动，故治以清降，清胃宁络、降气止血，兼顾肝肺。", ["芤", "大"]], "17656": ["病机", "脉见芤弦，芤主血虚失守，弦主肝气偏旺。吐血连日未止，血去阴伤则脉芤；由阳明传肝肺，木火刑金，气逆不降则脉弦。此脉示血虚而肝胃气逆，故见吐血、咳嗽，治以和降，使气降血宁。", ["芤", "弦"]], "17657": ["病机", "脉数主热，咳呛失血而内热脉数，说明热邪内迫，灼伤肺络，血随热溢。数脉为火热内盛之征，热不清则血不止，故治以清降，清其内热、降其逆气，则咳血可平。", ["数"]], "17658": ["病机", "脉见弦数，弦为肝气偏亢，数为热盛。阳明多气多血，血随气沸而整口吐出，紫红皆属热迫。久则热灼肝肺，渐加咳嗽。弦数示气火有余，故治以和降，平其气火则血自安。", ["弦", "数"]], "17659": ["病机", "素有遗泄，龙相失潜，燥灼上冲于胃，气火用事，热迫营阴。脉见芤弦，芤为营阴受损、血失内守，弦为相火肝气上逆。血随气火上腾而发，心烦神躁，皆气火用事之象，治以和养。", ["芤", "弦"]], "17660": ["病机", "脉见弦滑，弦主气逆肝旺，滑主痰热内壅。咳呛失血、口鼻俱溢，乃气火上逆、热迫血溢之候。弦滑示痰热夹肝气上冲，肺胃络伤，故治以清降，清化痰热、降其逆气。", ["弦", "滑"]], "17661": ["病机", "口鼻之血后再见咳嗽，脉细。细为阴血不足、脉道不充之象。失血之后阴血耗伤，虚热内扰，肺失清润故咳。脉细示血虚阴伤，与失血后咳嗽相应，治当养阴和络，不可再事攻伐。", ["细"]], "17662": ["病机", "腹痞胀满，阴阳络两为受伤，鼻血便血，形黄内热。脉见弦滑，弦主气机郁滞、肝脾不和，滑主湿热内蕴。气滞湿阻则痞胀，络伤则上下出血，形黄内热皆湿热郁蒸之征，故治以疏和。", ["弦", "滑"]], "17663": ["病机", "腹痞攻胀，阴阳络伤，吐血虽止而便血未除。脉见沉弦，沉主病在里，弦主气滞肝郁。气机郁结于内，络脉受伤，血不循经而下溢，故便血未除。沉弦示里气郁滞，再以调降，疏其郁滞则血自止。", ["沉", "弦"]], "17664": ["病机", "脉见细弦，细为阴血不足，弦为肝木偏旺。腹痞肢肿、形黄神倦，是脾虚湿困而肝木乘之；阴阳络伤则鼻血虽止而便血未除。细弦合参，正示肝脾络脉受损、气血两伤之病机，故治以疏和，疏肝和脾以调络。", ["细", "弦"]], "17665": ["病机", "脉息细弦，细主血少阴伤，弦主肝气郁滞。腹痛痞攻、便血澼澼，乃肝失疏泄、脾络受伤，气滞血溢并见。细弦之脉正合肝郁脾弱、络伤血溢之机，故以疏和立法，疏肝理脾而和其络。", ["细", "弦"]], "17666": ["病机", "脉来细软，细为血虚，软为气弱，合示肝脾气血早伤。右腹结痞攻动作痛、痛连腰部，是脾虚气滞、络脉不和；便血更耗气血。细软之脉与体伤肝脾相应，虚象明显，故治以温通，温养气血而通其结滞。", ["细", "软"]], "17667": ["病机", "脉数主热。腹痛痞攻而内热肌灼，是气滞痞结日久化热，热郁于内故脉数、肌肤灼热。数为热象，与内热肌灼相应，说明病机重在郁热伤阴，故拟清阴调中，清其郁热、调和中焦，使热退痞消。", ["数"]], "17668": ["病机", "脉见细弦，细为阴血不足，弦为肝木偏亢。腹痞痛胀、咳呛肢肿，原文断为旧伤新邪、肺脾同病：脾伤则痞胀肢肿，肺伤则咳呛，肝木乘之则脉弦。细弦正合肝脾肺同病、虚实夹杂之机，故拟疏和以调之。", ["细", "弦"]], "17669": ["病机", "脉见沉弦，沉主里、主水饮内停，弦主气机郁滞、饮邪搏结。中焦气痹、积痰蓄饮，当脘屡痛、两痞交攻、溏泄因之而发，皆痰饮内阻、气机不通之象。沉弦正合痰饮里结之机，久则痰饮常扰、再加呕吐，故拟温通以化饮行气。", ["沉", "弦"]], "17670": ["病机", "脉见沉弦，沉为病在里，弦为肝郁气滞。腹痞便溏是脾虚气滞；经事应通未通而鼻血屡溢，乃肝郁血滞、血不循经而上逆。沉弦之脉正示肝脾里病、气血失调之机，故治以疏和，疏肝理脾以调其气血。", ["沉", "弦"]], "17671": ["病机", "脉见沉弦，沉主里、弦主肝郁。原文明言肝脾肺三者俱伤：肝伤则胁痛，脾伤则痞胀，肺伤则咳呛。弦为肝病之脉，沉则病位在里，三脏俱伤而气机郁滞，故脉沉弦。治以疏和，疏肝理脾、调畅气机以兼顾三脏。", ["沉", "弦"]], "17672": ["主病", "脉见沉弦，沉主里、弦主肝，为肝郁气滞、络脉不和之象。原文“痞痛旧根，近发连及腰胁”，痞痛连及腰胁，正是肝气郁结、横逆走窜之征，故脉沉弦主肝郁气滞、络脉不通，治以疏和，即疏肝和络。", ["沉", "弦"]], "17673": ["病机", "脉见细弦，细为阴血不足，弦为肝气偏旺、饮邪内阻。原文“痰饮内阻，晨起咳嗽，胸痹气逆，痰沫不爽”，痰饮阻于胸膈，肝气上逆，肺失和降，故脉细弦主痰饮内阻、肝肺气逆，治以和降，即和肝降肺、化痰蠲饮。", ["细", "弦"]], "17674": ["病机", "脉见沉弦，沉主里、弦主肝，为肝邪内盛、肺失肃降之象。原文“肝为之升，肺失其降，肝肺两病”“金不制木，肝邪益炽，胸痹脘满，痰沫涌吐，咽喉且痛”，肝升太过、肺降不及，痰气上逆，故脉沉弦主肝肺同病、气逆痰壅，治以通降。", ["沉", "弦"]], "17675": ["病机", "脉风细弦，细为阴血亏虚，弦为肝气不和。原文“早有失血，去年复发”“胸痹不舒，少腹结痞，肝肺久为受伤，脘宇窒塞，略有咳嗽”，失血伤阴，肝肺受损，气机窒塞，故脉细弦主阴血亏虚、肝肺气滞，治以和降，即和养阴血、降气宣痹。", ["细", "弦"]], "17676": ["预后", "脉见细软，细为阴血虚少，软为脾胃气弱。原文“吐血咳嗽”“潮热盗汗，胃纳甚微，大便多次”“上损及脾，月事渐枯；下损过胃，脾胃两伤，过中最险”，虚劳损及脾胃，气血生化乏源，故脉细软主虚多邪少、脾胃两伤，预后险恶，治以和养。", ["细", "软"]], "17677": ["病机", "脉见弦滑，弦为肝气偏旺，滑为痰湿内蕴。原文“肺脾两伤，上为咳嗽，下为便血，渐至肉落纳少，形寒潮热，势将由伤成劳”，脾虚生痰，肝旺乘脾，肺失宣降，故脉弦滑主痰湿内蕴、肝脾不和，势将成劳，治以和养。", ["弦", "滑"]], "17678": ["主病", "脉见细弦，细为阴血不足，弦为肝气偏旺、木乘土位。原文“红白痢，昼夜百计”，痢下赤白、次数频多，必伤阴血，肝气横逆犯脾，故脉细弦主肝脾不和、湿热伤营之痢疾，治以疏和，即疏肝和脾、调气和血。", ["细", "弦"]], "17679": ["病机", "脉见细弦，细为营阴受损，弦为肝气偏旺。原文“酒客湿热伤营，每便干结，带下赤痢”“由阳明而损肝脾，渐为腹痛形黄”，湿热伤营，阳明受损，肝脾不和，故脉细弦主湿热伤营、肝脾两损，治以疏和，即疏肝和脾、清化湿热。", ["细", "弦"]], "17680": ["病机", "休息久痢新积，色白，脉沉弦。沉主里，弦主痛、主气滞，久痢伤脾，积滞未净，气机郁滞于里，故脉沉弦。此脉示脾虚积滞、虚实夹杂之病机，主休息痢反复发作、里急后重、腹痛等症，治拟苦辛固养，正合虚中夹积之候。", ["沉", "弦"]], "17681": ["病机", "痢疾小腹发迸、肛门气坠、欲便不利，属半虚半实。脉沉弦者，沉为在里，弦为气滞、为痛，里气壅滞不通，故小腹迸痛、肛坠而便难。此脉主里实气滞兼中气不足之病机，与半虚半实之证相应，故治以和养，调气和营而不峻攻。", ["沉", "弦"]], "17682": ["病机", "肝脾失协，赤痢屡发，小腹迸痛，得食欠运。脉细弦者，细为阴血不足、脾虚，弦为肝气偏旺、气机郁滞。肝脾不和，木郁乘土，故屡发赤痢、腹痛而运化不及。此脉示肝脾失调、虚实夹杂之病机，主赤痢腹痛、纳运不健等症，治以和养肝脾。", ["细", "弦"]], "17683": ["病机", "休息痢有赤无白，腹痞攻痛，脉息濡细，阴虚之体，舌苔光剥。濡细为阴血亏虚、脉道不充之象，濡更兼湿滞未化。阴虚之体而痢久不止，阴伤气弱，故脉濡细、舌光剥。此脉主阴虚血少兼余滞之病机，与腹痞攻痛、赤痢相应，治以和养。", ["濡", "细"]], "17684": ["病机", "赤痢久而不止，腹痛肛痛，肢肿纳少，脉见细弦。细为阴血亏耗、脾土虚弱，弦为肝气郁滞、腹痛之征。久痢伤阴耗气，肝脾两虚而气机不畅，故腹痛肛痛、肢肿纳少。此脉示肝脾两虚、气血不足之病机，主久痢腹痛、肢肿纳少等症，治以温养。", ["细", "弦"]], "17685": ["病机", "赤白痢减而肛坠里急，脉见细弦。细为阴血不足、正气已伤，弦为气机郁滞、下迫肛门。痢减而肛坠里急不去，乃清浊升降失司、余邪未清而正气已虚。此脉示虚实夹杂、升降失调之病机，主肛坠里急等症，故拟升清降浊以调气机。", ["细", "弦"]], "17686": ["病机", "幼年吐衄，阴分早亏，虚热内炽，热迫大肠致肠风下血如射，兼梦泄精伤、神烦少寐、头眩惊悸，脉见弦大。弦为肝旺、虚热内动，大为阴伤阳浮、脉道不敛。此脉示阴虚火旺、精血两伤之病机，主肠风下血、梦泄、惊悸等症，治以清养。", ["弦", "大"]], "17687": ["病机", "素有痰血，脏热移腑，传为肠风，血下如注，大便艰涩，渐至纳少神疲、气逆肢倦，脉见弦滑。弦为肝旺气逆，滑为痰热内蕴、血热妄行之象。此脉示痰热内蕴、阴伤气耗之病机，虚多邪少，与肠风下血、气逆肢倦相应，治以和养。", ["弦", "滑"]], "17688": ["病机", "脉见沉弦，沉主里，弦主肝木偏旺、气机郁滞。便燥带血属肠风，久则损及肝脾，形黄腹痛，乃肝脾不和、统藏失职，血不循经而下溢。沉弦正示病位在里、肝脾受病，故治以和养，调和肝脾以复统血之能。", ["沉", "弦"]], "17689": ["病机", "脉息沉弦，沉为在里，弦为肝郁。阳明郁热，肝脾统脏失司，气陷则肛坠，营虚则肠风下血。舌苔微灰，示热郁而阴伤。嗜烟体气阴两伤，脉沉弦正合郁热内蕴、肝脾失调之机，故调理不可偏阴偏阳，治以和养。", ["沉", "弦"]], "17690": ["病机", "肠风绵延，血下如水，甚则后重，脉见沉弦。沉主里，弦主肝脾郁滞。阳明郁热，肝脾失统脏之职，营不为守而血下溢。脉沉弦反映郁热内伏、肝脾不和之病机，故再以和养为治，调和肝脾以复统血。", ["沉", "弦"]], "17691": ["病机", "脉见弦大，弦主肝热，大主热盛。痔血受伤，营虚热炽，阳明传送无权，大便坚结数天一行而不畅。舌苔光红，示营阴亏耗。弦大之脉正合营虚热炽、阳明燥结之机，故拟清养，清阳明之热而养营阴。", ["弦", "大"]], "17692": ["病机", "脉息弦细，弦为阳明郁热未清，细为营阴已虚。痔血频仍，大便艰行，乃热郁而阴伤。原文明言「虚多邪少」，弦细正示邪热渐轻而正虚为主，故治以清养，清余热而养营阴，不可过用苦寒攻伐。", ["弦", "细"]], "17693": ["病机", "痢久渐成便血，昼夜六七行，腹痛里急，脉见沉弦，形黄肢肿，应月枯少。沉弦示病在里、肝脾郁滞，统藏失职，血溢于下；形黄肢肿为脾虚湿泛，月事枯少为营血亏耗。脉证合参，属肝脾两伤、湿热留恋，故治以和养。", ["沉", "弦"]], "17694": ["病机", "左脉细弦，右脉弦大不静。细弦为阴分已伤、肝邪气逆；弦大不静为阳明湿火内蒸、邪正相搏。湿火随气下陷则脱肛便血，肝邪上逆则作呕头胀，雷龙失潜则少寐多梦。邪热俱在阳明，故治宜兼顾，清化湿火而潜阳养阴。", ["细", "弦", "大"]], "17695": ["病机", "脉息濡细，濡主湿、主气虚，细主营血不足。便血绵延，脱肛腹痛，乃脾虚气陷、湿滞不化，营血亏耗。濡细之脉正示湿滞与正虚并存，故治以疏和，疏化湿滞、调和肝脾，不可峻补或峻攻。", ["濡", "细"]], "17696": ["病机", "受凉伤中而洞泄无度，脉弦为寒邪伤中、肝木乘脾之象。弦主气机郁滞、木旺克土，中焦受戕则运化失司，泄下无度。此脉弦非少阳之弦，乃土虚木贼之弦，故治以疏和，疏肝和脾以复中运。", ["弦"]], "17697": ["病机", "泄泻渐止而脘闷纳呆，脉见沉细。沉主里、细主虚，示邪已入里而正气不足，中焦脾胃虚弱、运化无力，故脘闷纳呆。原文断为「半虚半实」，即余邪未净而脾虚已现，故拟调中化邪，虚实兼顾。", ["沉", "细"]], "17698": ["病机", "由血转痢、由痢转泻，纳呆舌光，脉息沉弦。沉主里、弦主气机郁滞，病久入里，肝脾不和，气机不畅；舌光示阴液已伤。沉弦并见，为里虚夹郁、木乘土位之候，故治以和养，调肝脾而护阴液。", ["沉", "弦"]], "17699": ["病机", "久泻不止、大腹膨满、得食作胀，兼遗泄便溏，原文谓「由阴伤气，现在病寓中焦」。脉细弦者，细为阴伤血少，弦为气机郁滞、木旺乘土。阴伤气耗而中焦失运，故胀满泄泻并见，治以调养。", ["细", "弦"]], "17700": ["病机", "久泻由脾及胃，胃纳作胀，舌剥肢肿，咳呛气逆，原文谓「土衰关乎火弱」。脉细弦，细主虚、弦主木郁，示脾土衰而肝木乘之，火弱不能生土，气逆不降。细弦为虚中夹郁之象，故治以疏和，扶土抑木。", ["细", "弦"]], "17701": ["病机", "生冷伤中，中焦积滞，腹部隐痛，便溏纳呆，脉来沉细。沉主里、细主虚，示寒滞伤中、脾阳不振，积滞内阻而正气已虚。原文防其转为痢疾，正因里虚夹滞、气血凝滞，故治以疏和，温运疏滞。", ["沉", "细"]], "17702": ["病机", "肺虚生痰、肾虚生饮，咳嗽气怯，纳食欠旺，两足浮肿，脉见沉弦。沉主里、主水气内停，弦主饮邪搏结、气机不畅。肺肾摄纳无权，中焦失砥柱，水饮内停而泛溢，故沉弦为饮停里虚之候，治以和养。", ["沉", "弦"]], "17703": ["病机", "中气不振，积痰生饮，阻遏升降道路，脘宇攻动漉漉有声，必得嗳气方松。脉见沉弦，沉主里、主饮停，弦主气机郁阻、饮邪搏结。痰饮内停、升降失司，故见攻动有声，治以调降，降气化饮。", ["沉", "弦"]], "17704": ["病机", "脉细弦，细为阴血亏虚、封藏早亏，弦为木邪亢盛、水不涵木。木邪扰中，中焦积痰蓄饮，故脐腹似痞非痞、胸次窒塞；痰饮凌心则心悸艰寐，迫肾则梦遗。细弦并见，正合虚中挟实、实即痰饮之机，与头眩耳鸣、鼻衄疝坠等升降失司、阴阳造偏之症相应。", ["细", "弦"]], "17705": ["病机", "原文未识脉名，以症测机。下虚生饮、气虚生痰，喘肿多年，痰不从咳化、饮不从便达，水饮泛溢肢面皆肿，先胁痛而由络脉泛滥肌肤。此属本虚标实、气不归元之候，高年正虚，饮邪充斥表里，故防气不归元，与喘肿、胁痛相应。", []], "17706": ["病机", "脉沉弦，沉主里、主气机内郁，弦主痛、主肝木乘土。能食无力、大便屡解为脾运不健，当脘作痛、痛行臀部、得矢气较松，乃气滞不通、肝脾失调之象。沉弦正合气郁于里、木土不和之病机，故治以调养，与脘痛走窜、便解无力诸症相应。", ["沉", "弦"]], "17707": ["病机", "脉弦数，弦为少阳募原之邪、疟疾之常脉，数为暑热内伏、邪正交争。暑风客邪内伏募原，营卫不和而发疟，少热多寒、脘闷头眩，皆邪阻少阳、枢机不利所致。弦数并见，说明暑热偏盛兼有痰滞，故便坚腹痛、舌黄口渴，治以分泄兼顾。", ["弦", "数"]], "17708": ["病机", "脉弦滑，弦主疟邪伏于少阳募原，滑主痰湿内蕴。间日发疟、寒少热多、但热不寒，脘闷头痛、便涩溺赤、舌苔黄腻，正是风暑痰湿四邪交并、表里失宣之候。弦滑相合，说明邪郁少阳而痰湿偏重，故渴不多饮，治以疏和分泄。", ["弦", "滑"]], "17709": ["病机", "脉弦滑，弦为类疟寒热、邪踞少阳之象，滑为痰湿内盛之征。咳嗽痰薄、类疟寒热并见，说明外邪引动内痰、肺胃同病，少阳枢机不利而寒热似疟。弦滑正合痰湿阻遏、邪正交争之机，故治以分疏，使邪从表里分消。", ["弦", "滑"]], "17710": ["病机", "复诊类疟较轻而脉仍弦滑，弦为余邪未净、少阳枢机未复，滑为痰湿尚盛。仍咳嗽痰多、当脘满闷，说明痰湿中阻、肺胃失降，邪虽减而痰浊未化。弦滑不去，正合痰湿留恋之病机，故续以分泄，使痰湿从上下分消。", ["弦", "滑"]], "17711": ["病机", "类疟已止而脉仍弦滑，弦为肝木未和、气机尚郁，滑为痰浊内恋。咳喘未除，说明痰湿壅肺、肺失肃降，虽疟邪已解而痰饮未化。弦滑并见，正合痰湿阻肺、木郁不达之病机，故治以疏和，理气化痰以善其后。", ["弦", "滑"]], "17712": ["病机", "脉见细弦，细为营血不足，弦为气机郁滞、木邪犯土。疟发间日而寒热满闷、咳嗽泛恶，正是少阳枢机不利、痰湿内阻、肺胃失降之象。细弦并见，说明正虚邪恋、气郁痰凝，故治以分疏，疏其郁滞兼和营卫。", ["细", "弦"]], "17713": ["病机", "三疟五年，劳动即发，寒热从中，营卫受伤，脉见濡细。濡为气虚湿滞，细为营血亏少，二者相合，正合久疟耗伤营卫、气血两虚之机。原文明言「属虚而非实」，故脉不任攻伐，治以和养，扶正调营卫为要。", ["濡", "细"]], "17714": ["病机", "劳倦成疟，是为劳疟，微寒微热、盗汗纳少，脉见濡细。濡细主气虚血少，劳倦伤脾则营卫乏源，故寒热轻微而非壮热；盗汗纳少乃气阴两伤、脾运不健之症。脉症相参，属虚多实少，故拟和表里而兼顾咳嗽。", ["濡", "细"]], "17715": ["病机", "三疟阵乱，呕泻仍作，脉见沉弦。沉主病在里，弦主气郁饮停、木旺克土。疟久邪伏于里，肝气横逆犯胃则呕，乘脾则泻，故脉沉弦相应。此非表证，乃里气不和、痰饮内扰，治以疏和，疏肝调中兼化饮滞。", ["沉", "弦"]], "17716": ["病机", "疟母攻胀，肢酸脘闷，脉见细弦。疟母乃痰瘀结于胁下，久病营血暗耗故脉细；弦为肝气郁结、癥块内阻，气机不畅则攻胀脘闷，血不荣筋则肢酸。细弦并见，示正虚而积未消，治以疏和，缓消其积而不伤正。", ["细", "弦"]], "17717": ["预后", "疟母内损，头眩肢倦、便溏带血，脉见细弦。细为营血亏耗，弦为肝郁乘脾、络伤血溢。疟母日久，脾虚失运则便溏，肝伤络损则带血，气血日削故头眩肢倦。脉症皆示正损邪留，故原文断曰「恐其成劳」，属预后警示。", ["细", "弦"]], "17718": ["病机", "狐疝出没无常，少腹牵引作痛，脉见沉弦。沉主病在里、在阴分，弦主肝气郁滞、筋脉拘急。疝气下坠少腹，乃肝经气血郁结、寒湿凝滞所致，气聚则痛、气散则安，故出没无常。沉弦正合肝肾气滞、阴寒内结之机，治以疏和。", ["沉", "弦"]], "17719": ["病机", "狐疝出没无常，其声呜呜然，原文断为肝肾内虚、气为下陷，脉弦。弦虽主肝，然此属虚而气陷，肝脉失养而拘急，故弦而不任按。气陷则疝坠有声，肝肾内虚则根本不固。脉弦与气陷并见，示虚中夹郁，治以和养，补肝肾而升举下陷之气。", ["弦"]], "17720": ["病机", "脉见濡细，濡主湿、细主虚，合之水疝胀大出水，乃水湿内停而正气已虚之象。水气太过，湿浊下注，故见阴囊胀大出水；脉濡细说明湿盛而脾肾不足，不能运化水湿。治以疏和，即疏利水湿、调和气血，正合濡细所主之湿虚病机。", ["濡", "细"]], "17721": ["病机", "脉见细弦，细为阴血不足，弦为肝气郁滞、痰湿阻络。疝气两月未止，恐成𤻊疝，尾闾结核亦属湿痰，皆因肝经气血郁滞、湿痰凝聚所致。细弦之脉反映正虚而邪滞，肝郁痰凝，故治以疏和，疏肝理气、化痰散结。", ["细", "弦"]], "17722": ["病机", "脉见弦滑，弦主肝郁，滑主痰热。右部睪丸坚结不和，渐成𤻊象，目赤屡发，乃肝家素有郁热，痰热互结于肝经所致。弦滑之脉正是肝郁化热、痰热内蕴之征，故一切过温之药在禁例，治以清养，清肝化痰、养阴散结。", ["弦", "滑"]], "17723": ["病机", "脉见沉弦，沉主里、主水气，弦主肝郁、主痛。脚气疲软，朝退暮重，少腹发麻，气逆上升，乃寒湿郁滞下焦，肝气挟湿上逆所致。沉弦说明病在里，寒湿内盛，阳气不伸，气机升降失常，故再以通阳益气，温通阳气以化寒湿。", ["沉", "弦"]], "17724": ["病机", "脉见沉细，沉主里、细主虚，为脾肾阳虚、寒湿内盛之象。干脚气，两足软不能行，手亦发麻，颇有上升之势，犯胃冲心皆能传变，说明寒湿深伏，正气已虚，邪有上逆之势。沉细之脉提示正虚邪陷，急须调治，温阳化湿以扶正祛邪。", ["沉", "细"]], "17725": ["病机", "脉见细弦，细主脾肾虚，弦主风寒湿袭络、气机不畅。脚气疲软难行，两手亦麻，脘闷纳少，属脾肾致虚，风寒湿袭入络脉。细弦之脉反映正虚而邪阻经络，气血运行不畅，故仍从温养，温补脾肾、祛风散寒化湿以通络。", ["细", "弦"]], "17726": ["病机", "脉见细弦，细为正气不足，弦为寒湿郁滞、肝气不舒。脚气将成，恐上升为变，乃寒湿之邪留滞下焦，有上逆之势。细弦之脉说明正虚而寒湿内阻，气机升降不利，故拟去寒湿，温阳化湿以阻止病势上逆。", ["细", "弦"]], "17727": ["病机", "脉见沉弦，沉主里、主水湿，弦主气滞、主痛。脚气渐成，有升少降，少腹窒塞，手指发麻，塞湿之邪实少去路，二便又为失利，舌糙，乃寒湿壅滞下焦，气机升降失常，邪无出路。沉弦之脉正是寒湿内盛、气机郁滞之征，故急宜疏导，通利二便以祛湿邪。", ["沉", "弦"]], "17728": ["病机", "脉浮弦，浮主水气上泛，弦主肝木偏旺、气机冲逆。原文谓脚气暴起、两足肿亮、手麻发痉，有积水上冲之势，正是水湿挟肝风上冲之候。浮弦相合，说明水气与肝风并逆于上，故拟先开降以折其上冲之势。", ["浮", "弦"]], "17729": ["病机", "脉见沉细，沉主里、主水湿内着，细主阴血不足、经脉失养。原文谓脚气将升、酸软不和、少腹手指发麻，恐其上冲为变。沉细说明正虚而湿滞于里，气血不能充达四末，故见麻木酸软，治以和养，扶正以御冲逆。", ["沉", "细"]], "17730": ["病机", "脉左弦数，弦主肝郁气滞，数主热、主阴伤。原文谓臌胀耗阴最不易调，腹臌脐平、两便少行、舌剥口渴，皆阴亏热郁之象。左脉弦数正反映肝经郁热伤阴、气机壅塞不通，故拟通关导水，以通利为治。", ["弦", "数"]], "17731": ["病机", "脉见细弦，细主阴血亏少，弦主肝脾不和、气机郁滞。原文谓肝脾内伤已成、臌胀两便失利、上逆为咳，细弦正说明肝脾久伤、气血不足而气逆不降，故上为咳逆、下为二便不利，治以和降以调肝脾。", ["细", "弦"]], "17732": ["病机", "脉见沉弦，沉主里、主水湿内停，弦主气机郁滞、脾胃受伤。原文谓单腹胀属脾胃，积水遏湿，通行即解。沉弦说明水湿遏阻于里、脾胃运化失职、气机不畅，故腹胀而二便不利，治以疏和，使气行湿化则胀自解。", ["沉", "弦"]], "17733": ["病机", "脉见细弦，细主正虚，弦主肝郁气滞。原文谓脘腹胀满、肾囊俱肿、气急发呛，三焦不能分化，防成臌胀。细弦说明肝脾久伤、气化不利、三焦水道壅塞，水湿泛滥而为肿为胀，故治以疏和，调畅气机以分化三焦。", ["细", "弦"]], "17734": ["病机", "脉见细弦，细主气血不足，弦主肝脾郁滞。原文谓臌胀受温，温则气通逐水，又言肝脾久伤。细弦正说明肝脾久伤、阳气不足而气机郁滞，水湿因之不化，故治以温通，温阳以助气化、通利以逐水湿。", ["细", "弦"]], "17735": ["病机", "脉息濡细，濡主湿、主阳虚，细主气血不足。原文谓肢肿腹满、肿势由下升上、咳呛不爽、舌苔粉白，皆阳虚湿盛之象。濡细说明阳气虚馁、水湿内停、气化无力，湿邪由下上逆犯肺则咳呛，故治以温通，温阳化湿以消肿满。", ["濡", "细"]], "17736": ["病机", "脉芤无度，芤主阴血亏耗、脉道失充，无度言其虚散失序。痞散成臌、大腹发热且愈热愈大，是阴伤而气机痹阻，虚热与气结并见。脉芤正应阴伤气痹之机，故断为恐有不得了之势，属正虚邪盛之危候。", ["芤"]], "17737": ["病机", "脉息沉弦，沉主水气内停、病在里，弦主饮邪与气机郁滞。水势狂溢、肿胀膨满、囊肿色亮、气喘有痰，是水气上泛高原、三焦泛滥之象。沉弦正合水饮内结、气机不通之病机，故拟通导沟渠以逐水降气。", ["沉", "弦"]], "17738": ["病机", "脉见沉弦，沉为水气在里，弦为饮停气滞。皮水屡发、溺闭即肿、肿势上中下三焦俱到，说明水湿泛溢、气化不利。沉弦之脉应水饮内结、三焦壅滞之机，故治以通降，使水气下行。", ["沉", "弦"]], "17739": ["病机", "脉见细弦，细主肝脾阴血不足，弦主肝郁气滞。肝脾久伤、腹膨放后纳呆形黄、便多溺少，是脾运不健、肝失疏泄、气血两亏之候。细弦正示肝脾两伤、气滞血少之病机，故治以疏和，疏肝健脾、调和气血。", ["细", "弦"]], "17740": ["病机", "脉见细软，细为气血不足，软为正气虚弱、脉道无力。两次放臌后腹满虽平，然形黄疲倦、纳食不多，显系肝脾受伤、气血未复。细软之脉应正虚未复之机，故再从和养，以调补肝脾、缓培气血为治。", ["细", "软"]], "17741": ["病机", "脉见细濡，细主阴液亏少，濡主气弱湿滞、脉道软弱。阴耗阳结而成关格，随食随吐、更衣艰涩，攻补不受，是气液两亏、痰饮内阻之候。细濡正合气液两虚、痰饮用事之病机，故谓调理为难。", ["细", "濡"]], "17742": ["病机", "脉左右沉濡，沉主病在里、气机郁滞，濡主气弱液耗、脉道不充。上格下关，食少欲吐、吞酸吐沫、脘痛胀、便艰粪如羊矢，是气痹液耗、关格不通之象。沉濡应气痹液耗之机，故用药不可偏阴偏阳，拟和降调中。", ["沉", "濡"]], "17743": ["病机", "脉六部细微，细主阴血亏少，微主阳气衰微、脉道无力。关格数年，饮食难停、吐尽后已，气久不能升降，阴液枯槁，呕甚见血，脘腹梗痛。细微之脉正应气阴两竭、升降失司之机，故拟调中降逆，兼顾寒暖不调之外因。", ["细", "微"]], "17744": ["病机", "脉见细弦，细为阴血不足，弦为肝气偏旺。上膈随食随吐，乃肝气横逆犯胃，胃失和降，气机上逆所致。细弦之脉正示阴血亏虚而肝用有余，故治以通降，使胃气下行、肝气不逆，则呕吐可平。", ["细", "弦"]], "17745": ["病机", "原文明言“弦主阴耗，涩主气痹”。弦为阴血耗伤、脉道失柔，涩为气机痹阻、血行不畅。上呕逆下便闭，中焦窒塞，脘满懊𢙐，皆由阴耗气痹、升降不通所致，故脉见弦涩，久延难复。", ["弦", "涩"]], "17746": ["病机", "脉见细弦，细主阴血不足，弦主肝邪有余。肝邪侮中，中焦积饮，升降失调，故脘痛胀满、吞酸吐沫；厥阴之气充斥，更衣不利，遂成上格下关之势。细弦正反映肝旺乘脾、饮停气阻之病机。", ["细", "弦"]], "17747": ["病机", "脉见沉弦，沉主里、主阴分，弦主肝气郁结。上呕不止、下便不利，是为关格。老年阴耗阳结，阴液亏耗则脉道失濡，阳气结滞则气机不通，沉弦之脉正合阴耗阳结、关格不通之病机，故难许调复。", ["沉", "弦"]], "17748": ["病机", "脉见细弦，细为营虚，弦为肝风内动。昔年痢后受伤，营虚生风、气虚生湿，风湿外游肌表则寒热发瘰；肛门发麻上升至遍体，乃肝风挟湿循经窜动。细弦之脉正示营虚风动、湿滞之病机，故治以疏和。", ["细", "弦"]], "17749": ["病机", "脉见细弦，细主肝脾阴血受伤，弦主风动。休息痢后下血作泻，阳明垢滞随去随生，肝脾受伤，生风挟湿，故忽寒忽热、遍身发麻，上至巅顶下至肛门。细弦之脉正合肝脾受损、风湿内扰之病机，治以和养。", ["细", "弦"]], "17750": ["病机", "脉见沉弦，沉主里、主下焦，弦主气机郁滞。垢秽不能分化，满腹攻痛，大便鲜通，囊为出粪，乃浊阴不降、清浊相干之候。沉弦正示病位在里、气滞不通，故拟分清降浊，使垢秽从正路而出。", ["沉", "弦"]], "17751": ["病机", "脉见濡软，濡软主气血亏虚、脉道失充。大便失行，舍正路不由，阴囊膜破粪由此行，证情淹缠。濡软之脉示正气已虚、推动无力，故一时难复，拟以疏导，缓缓图之，不可峻攻。", ["濡", "软"]], "17752": ["病机", "脉沉弦，沉主里、弦主痛主气滞。原文“迸伤气分，膀胱失司”，气分受伤则膀胱气化不利，故溺时作痛、下窍发坠、尿中带血丝。沉弦正示气滞于下焦、膀胱络伤之病机，与淋痛尿血相应。", ["沉", "弦"]], "17753": ["病机", "脉沉弦，沉为病在里，弦为气迸劳伤、络脉拘急。原文“劳淋，劳伤气迸，发为淋浊，赤白交下，每解痛苦非常”，气迸则膀胱失约、脂血杂下，沉弦恰应下焦气滞络伤、痛淋之机。", ["沉", "弦"]], "17754": ["病机", "脉细数，细为阴血不足，数为阳热有余。原文“高年阳盛阴热，向来便血，今复血渗膀胱，渐成尿血”，阳盛灼络、阴亏失守，故血渗膀胱而尿血不止。细数脉正示阴虚内热、络伤血溢之病机。", ["细", "数"]], "17755": ["病机", "脉细弦，细主气虚，弦主气机郁滞。原文“气虚下陷，小便先为不利，继以淋浊，遂至分化无权，其气由前向后，更衣欲通不通，气坠矢气难转”，细弦正合气虚下陷、升降失司、二便气坠之病机。", ["细", "弦"]], "17756": ["病机", "脉濡细，濡为气虚湿滞，细为气血不足。原文“气陷脱力，溲时仿佛精坠，发酸不禁”，气陷则固摄无权，精溺失约而溲时精坠、酸楚不禁。濡细脉正示中气下陷、精关不固之病机。", ["濡", "细"]], "17757": ["病机", "脉弦滑，弦主气滞，滑主湿浊痰热。原文“精溺浑淆，小便不禁，且带白垢”，气滞则分清泌浊失职，湿浊下注则尿带白垢、精溺混出。弦滑脉正应下焦气滞、湿浊内蕴之病机。", ["弦", "滑"]], "17758": ["病机", "脉细弦，细为阴血不足，弦为气机郁滞。原文“精溺未得分清，小便色浊，每解似有阻隔”，气滞则分清泌浊无权，湿浊下流故尿浊而解有阻隔。细弦脉示气滞湿阻、精溺不分之病机。", ["细", "弦"]], "17759": ["病机", "脉细软，细为精血亏虚，软为气弱不任。原文“久则为淋，精溺窍两属受伤，溺为不禁，精为遗滑”，久淋伤及精溺两窍，气虚不固则溺不禁、精遗滑。细软脉正示气血两虚、精溺失固之病机。", ["细", "软"]], "17760": ["病机", "脉见细弦，细为阴血不足，弦为肝郁气滞，主湿热下注、热毒未清之淋浊。溺数微痒，乃热毒蕴结下焦，气化不利；细弦示阴分已伤而肝火未平，故治以清降，清其热毒，降其郁火。", ["细", "弦"]], "17761": ["病机", "脉见细弦，细主阴血亏虚，弦主肝经郁滞。迸伤为淋，便痛茎肿，囊筋牵引，乃外伤致肝络瘀滞，湿热下注。细弦示阴血不足而肝气不舒，故治以和养，和其肝络，养其阴血。", ["细", "弦"]], "17762": ["病机", "脉见细弦，细为湿郁阴伤，弦为肝火偏亢。湿热下注，溺痛如淋，且带浮肿，乃湿热蕴结下焦，气化不利；牙痛口疳为湿热上蒸。细弦示阴分不足而肝火未清，故治以通降，通利湿热，降其肝火。", ["细", "弦"]], "17763": ["病机", "脉见细弦，细主阴血不足，弦主肝郁湿热。初则为浊，溺痛发痒，郁邪未清，乃湿热郁于下焦，肝经气滞。细弦示阴分已伤而郁邪未净，故治以通降，通其郁滞，降其湿热。", ["细", "弦"]], "17764": ["病机", "脉禀六阳，阳充则阴不为守，久有遗泄，有梦渐为无梦，向春发而较勤，且有盗汗，种种心肾两亏。阳充而阴不守，乃心肾不交，阴虚不能内守，故遗泄盗汗；春令阳升，故发而较勤。治以清养，清其虚火，养其心肾。", []], "17765": ["病机", "脉见弦滑，弦主肝郁，滑主痰湿。遗泄有梦属心，无梦属肾，心虚于肾，梦泄频仍，有时艰寐，有时惊悸，诸恙交集，多属心肾两亏。弦滑示痰湿内扰、肝郁不舒，故治以清养，清其痰火，养其心肾。", ["弦", "滑"]], "17766": ["病机", "脉见细弦，细主阴血亏虚，弦主肝郁不舒。精关不固，梦泄复发，甚至小便不禁，乃肾虚不摄，肝失疏泄。细弦示阴分不足而肝气偏旺，故治以清养，清其虚火，养其阴血。", ["细", "弦"]], "17767": ["病机", "脉见细弦，细为阴血不足，弦为肝阳偏亢。外感渐清，诸恙轻减，惟心肾两为不济，肝主相火，跃跃欲动，艰寐稍平，仍关门不固，常常自遗。素有头眩耳鸣，皆属上盛下虚。细弦示阴亏阳浮，故治以清养。", ["细", "弦"]], "17768": ["病机", "脉见细弦，细为阴血不足，弦为肝木失柔。精溺管混淆、似淋非淋，乃肝胃牵连、气机不降所致；脘满腹鸣、虚阳上升头蒙，皆由阴弱阳浮、肝胃不和。细弦正示阴亏而肝气偏旺，故治以和养，柔肝益阴以调气机。", ["细", "弦"]], "17769": ["病机", "脉见细软，细主阴血亏少，软主阳气不振。著寒泛水、脘胀，为寒水内停；受热鼻血、遗精，乃虚阳上扰、下元不固；心跳气喘、神疲肢倦，皆气血两虚之候。细软之脉说明正虚而水寒内盛，故治以和养，扶正调中。", ["细", "软"]], "17770": ["病机", "脉见细弦，细为阴精不足，弦为肝气不柔。膀胱不纳、每每遗溺，乃下元虚而肝气疏泄太过、约束无权。细弦示阴亏肝旺、气化失司，故从丸剂缓调，补下元以柔肝，使膀胱约束复常。", ["细", "弦"]], "17771": ["病机", "脉见细弦，细主三阴内虚，弦主肝邪为炽。溺数且痛，是肝火下迫、八脉郁热；尊年虚多，薄有外感，则虚中夹邪。细弦说明阴分不足而肝热内郁，故治以分泄，疏肝泄热而不伤正，兼顾外感。", ["细", "弦"]], "17772": ["病机", "脉见细弦，细为阴血亏虚，弦为肝气郁滞。本有痛经，是肝郁血滞；小溲频数，乃肝气疏泄太过、下元不固。细弦示阴亏而肝用偏亢，故拟升补，升举下陷、补益阴血，使肝气条达而溺数自减。", ["细", "弦"]], "17773": ["预后", "脉沉，主病在里、阳气不升。小溲迸痛，久为不禁不约、溺数无度，乃下元虚衰、气化无权，病深在里。沉脉示正气内困，能否支持，正是对预后之疑虑，说明久病及肾、阳气难振，须防虚脱。", ["沉"]], "17774": ["病机", "脉见细弦，细为阴分不足，弦为肝气郁结。癃闭有根、溺痛不利，是肝郁气滞、下焦决渎失司；近发较甚，则郁热渐增。细弦示阴亏而肝气不疏，故治以通降，疏肝通利下焦，使气化得行而小便自利。", ["细", "弦"]], "17775": ["病机", "脉象见弦，弦为肝木偏旺。心烦足软、目赤颧红、盗汗、溺数、舌少液，皆心肾阴亏、虚阳升少降之候；阳刚易举、有时泄精，尤见肝火扰动精室。弦脉说明肝邪内炽、阴不制阳，故拟清养，清肝滋阴以潜虚阳。", ["弦"]], "17776": ["病机", "本案精血两伤而见实脉，乃龙雷不熄、阳刚发动之象。虚损本应脉虚，反见实脉，说明亢阳不潜、真阴难复，虚证中夹有亢阳为患。头痛发眩、耳聋面麻、咳嗽不固，皆阳刚上扰、关门不固所致，故拟清养并调胃纳，以潜阳复阴。", ["实"]], "17777": ["病机", "脉见细弦，细为阴血不足，弦为肝木失柔。肾为作强之官，赖心济肝辅而关门得固；今细弦示阴血亏而肝阳偏，关门不固，举坚难久。故以固摄为要，补阳助火之药皆禁，恐助火耗阴、扰动龙雷。", ["细", "弦"]], "17778": ["病机", "脉见细弦，细主液枯血少，弦主气机郁滞。气痹液枯则大肠失润，大便燥结四、五日一行；弦又主痛，故痛势上行后腰前腹。细弦合见，示气痹而液亏、肝脾不调，治以和养，养液行气并举。", ["细", "弦"]], "17779": ["病机", "脉息细滑，细为营阴素亏，滑为痰热内蕴。营亏生热，大肠津液受灼，故燥结难行、五六日一解，解时脱肛外翻。怀麟佐脾胃司胎，阴亏而兼痰热，故拟清降，清其郁热、降其痰火，兼护胎元。", ["细", "滑"]], "17780": ["病机", "脉见弦滑，弦主郁火，滑主痰浊。禀体阴亏，郁火蒸痰，痰扰于肺则咳呛绵延，火迫于肠则更衣艰涩。肺与肠相表里，上下见证相因而发。弦滑并见，正合郁火蒸痰之机，故拟清降以清火化痰、润肠肃肺。", ["弦", "滑"]], "17781": ["病机", "脉见细弦，细为阴血不足，弦为肝阳不柔。温邪先受发于产后，寒热厥逆、疹疮俱发，今脘嘈心悸、便艰，素体血热多痰。细弦示产后阴亏、余热未清而肝阳偏亢，故治以清养，清余热、养阴血。", ["细", "弦"]], "17782": ["病机", "脉见细涩，细主阴血亏少，涩主血行不畅。产虚不复，咳嗽屡发，脬坠溺数，又早便血，肢腰酸楚、经来腹痛，皆阴血亏虚、脉络瘀滞之象。细涩相合，示虚中夹滞，故治以和养，养血兼行滞。", ["细", "涩"]], "17783": ["病机", "脉见滑大，滑主痰湿热毒，大主邪盛。触毒起因，袖口疳后左胯肿痛将成鱼口，疮兼病发，身热焦灼、口渴便闭，皆热毒壅盛、痰湿交阻之候。滑大示邪实有余，故拟通降，通腑降火、解毒散结。", ["滑", "大"]], "17784": ["病机", "脉见数大，数主热，大主邪盛，说明毒疮后余热未清而阴分已伤。热邪煽烁肝肾，肝开窍于目、肾开窍于耳，故两耳发鸣、两目发赤，且左甚于右，为肝阳偏亢、虚热上扰之象。脉数与热相应，大示邪热尚盛而阴不能敛，故治以清化，清其余热、化其煽烁。", ["数", "大"]], "17785": ["病机", "脉见细数，细为阴血不足，数则为热，合之说明杨梅风久延，阴分亏耗而余热未清。阴血不能濡养筋骨，故逢骱酸痛、屈伸不利；热留经络，故脉数。此非实热壅盛，乃虚热内扰、阴血不充之候，故治以清养，清余热而养阴血，使筋骨得濡。", ["细", "数"]], "17786": ["病机", "脉见弦滑，弦主风与肝，滑主痰湿内蕴。禀体本热，风邪挟湿郁于内，痰湿随风上蒙清窍，故右耳失聪，时流脓、时痛胀。弦为风动之象，滑为湿痰之征，二者相合，正合风郁湿、清窍蒙蔽之机，故治以疏和，疏风化湿以通清窍。", ["弦", "滑"]], "17787": ["病机", "脉见沉弦，沉主病在里，弦主风邪与肝。风邪挟湿内侵，湿性重浊黏滞，风与湿合而阻遏清阳，清窍不利，故两耳为聋。沉说明邪不在表而在里，弦示风邪未散、肝气不舒，风湿内郁致耳窍闭塞，故治以和养，和其肝、养其正以化风湿。", ["沉", "弦"]], "17788": ["病机", "脉见弦滑，弦主肝阳上扰，滑主痰湿内蕴。头蒙渐减而耳仍鸣响，说明痰湿稍化而肝阳未平，风痰上扰清窍未止。弦滑并见，正是肝阳挟痰湿上逆之象，故耳鸣持续；治以清养，清肝阳、养阴分，使痰湿渐化、清窍得宁。", ["弦", "滑"]], "17789": ["病机", "脉见弦滑，弦为肝阳偏亢，滑为痰湿内蕴。下疳受伤，肝肾之阴不足，阴不制阳，肝阳上扰，故头部鸣响、两耳渐为失聪。耳为肾窍，肾阴亏而肝阳炽，痰随阳升，脉之弦滑正示阳亢痰升之机，故治以清养，清肝阳、养肝肾之阴。", ["弦", "滑"]], "17790": ["病机", "脉见沉弦，沉主里、主气机郁滞，弦主木旺与肝。头痛多年，渐致耳鸣目花、颈项牵引，皆肝木亢盛、风阳上扰之象；木旺侮土，故有时脘痛纳呆。沉弦说明病在里而肝气郁逆，横犯中土，故治以和降，和肝木、降逆气以安中土。", ["沉", "弦"]], "17791": ["病机", "脉见细弦，细为阴血不足、清空之虚，弦为肝阳为炽。耳聤青白脓交溢，脑髓受伤，肝阳上扰，渐至颊车闭而难开、颈项头目牵引作痛，清空虚而难著枕。体本丰腴，内痰与内风升多降少，细弦正示阴虚阳亢、痰风上逆之机，故治以镇养，镇肝阳、养阴血。", ["细", "弦"]], "17792": ["病机", "脉见弦滑，弦主肝郁气滞，滑主痰湿内蕴。耳聤溢血溢脓、脓薄如水，乃肝经郁热挟湿上扰清窍；头部鸣响、两额作痛为肝阳上扰；喉痹哽痛、脘闷纳少、腹痛便溏系肝木乘脾、湿滞中焦。弦滑相合，正示肝郁湿痰交阻之病机。", ["弦", "滑"]], "17793": ["病机", "脉见细弦，细为阴血不足，弦为肝经郁滞。耳菌溃烂、脓血交溢，乃肝经郁火挟湿毒上攻耳窍，久则阴血耗伤。细弦并见，说明病本阴血亏虚而肝郁未解，故治以清化，清其郁火、化其湿毒，兼顾阴血。", ["细", "弦"]], "17794": ["病机", "脉象细弦，细主阴血不足，弦主肝风内动。眼眶上下发红，原文明言属脾湿肝风所致。肝风循经上扰目窍，脾湿蕴蒸，故见目眶红赤。细弦之脉正合肝风内动而阴血不足之机，治以清泄，清肝风、泄脾湿。", ["细", "弦"]], "17795": ["病机", "脉见细滑，细为阴血亏虚，滑为痰湿内蕴。头痛未止、目仍蒙赤，乃肝阴不足、痰湿上蒙清窍所致。细滑并见，示阴亏与痰湿并存，本虚标实。治从熄养，熄肝风、养阴血，兼化痰湿，正合此病机。", ["细", "滑"]], "17796": ["病机", "脉见浮滑，浮主邪在表在上，滑主痰湿壅盛。咬牙疳满口腐烂、两腮痛胀，原文明言温毒客于上焦。温毒挟痰湿壅于上焦，故脉浮滑。浮滑之脉示温毒痰湿交蒸于上，治以清泄，清上焦温毒、泄痰湿。", ["浮", "滑"]], "17797": ["病机", "脉见数滑，数主热盛，滑主湿浊。牙疳腐烂反复不愈、舌滑腻，乃湿热蕴蒸上焦；腿部青色退而未尽，示湿热下注。数滑之脉正示湿热内盛之机，治以清阴而化湿热，清其热、化其湿，使湿热分消。", ["数", "滑"]], "17798": ["病机", "脉息细弦，细主阴血不足，弦主肝郁。痰色屡破屡结、血水裹痰涎，原文谓心脾部位无非郁热蒸痰。郁热灼津为痰，痰热交结，阴血暗耗，故脉细弦。细弦示郁热蒸痰而阴伤之病机，治以和养，和其郁热、养其阴血。", ["细", "弦"]], "17799": ["病机", "脉见细弦，细主阴血亏虚，弦主肝郁。禀体虚热，牙宣溢血旋平旋覆，寒热头疼有感即来，乃阴虚内热、肝郁化火，虚火上炎则牙宣溢血，外感引动则寒热头疼。细弦之脉示阴虚肝郁之病机，治以疏和，疏肝解郁、和养阴血。", ["细", "弦"]], "17800": ["病机", "脉见细弦，细为营阴不足，弦为气火有余。心肝两经燔灼，阳明郁热，致牙宣半年，诸虚杂出，脘胀发嘈，头蒙艰寐。细弦之脉正合营虚火旺、肝胃热郁之病机，故急宜调理牙宣，血减则诸病除。", ["细", "弦"]], "17801": ["病机", "脉见细弦，细主阴血不足，弦主肝风内动。牙宣连年，阳明郁热，肝风上扰，故头发眩晕、脘闷心悸。细弦之脉反映肝风郁热、阴血暗耗之机，治以清养，清其郁热、养其阴血。", ["细", "弦"]], "17802": ["病机", "脉见细弦，细为阴血亏虚，弦为肝经郁热。阳络受伤，鼻衄狂溢，薄而有红者属热为多。细弦之脉示热伤阳络而阴血已耗，故治以清降，清其热而降其逆。", ["细", "弦"]], "17803": ["病机", "脉见细弦，细主营阴受损，弦主肝热上逆。阳络受伤，鼻衄倾注，甚至痰中亦带，然不加咳嗽，说明病在阳络而非肺脏。细弦之脉合于营伤热逆之机，故总可调复。", ["细", "弦"]], "17804": ["病机", "脉见沉弦，沉为气机内郁，弦为肝经气滞。鼻衄狂溢致营伤气痹，两胁作胀，当脘发迸。沉弦之脉反映营伤而肝气郁痹、气机不畅之病机，故拟以和养，和其营而养其肝。", ["沉", "弦"]], "17805": ["病机", "脉见细弦，细为肺阴不足，弦为肝邪偏亢。鼻疳复发，并溢清水，鼻骨酸麻。鼻为肺窍，肝邪烁肺，肺失清肃。细弦之脉正示肝邪犯肺、肺阴受灼之机，故拟肝肺两调。", ["细", "弦"]], "17806": ["病机", "脉见细弦，细主阴液不足，弦主肝肺郁热。鼻渊稍减而咳嗽有痰、头蒙腰楚，说明郁热未清、阴液已伤。细弦之脉反映肝肺余热未净、阴分受损之病机，故治以清降。", ["细", "弦"]], "17807": ["病机", "脉见细弦，细为阴分不足，弦为肝肺郁热。喉闭较通，蒂丁未曾收敛，肝肺不和，郁热尚未清楚，汗出津津。细弦之脉示郁热未清而阴液渐耗之机，故拟从和养，和其肝肺、养其阴分。", ["细", "弦"]], "17808": ["病机", "脉弦滑者，弦主气郁痰凝，滑主痰湿内盛。原文谓“将成喉痹，咽哽音嘶”，乃痰气交阻于咽喉，络脉不利，故脉见弦滑。弦为郁、滑为痰，痰郁互结，上壅咽嗌，故哽而音嘶，治以和养，正合痰郁宜疏宜养之意。", ["弦", "滑"]], "17809": ["病机", "脉细弦者，细为阴伤，弦为郁热内动。原文谓“肺肾阴伤，郁热挟痰”“龙雷之势有升少降”，阴亏不能涵木，虚火挟痰上扰，故脉细而弦。细示阴液不足，弦示郁热升腾，与疙瘩红肿、溺多色黄、夜寐不宁相应，恐失血失音，急宜调护。", ["细", "弦"]], "17810": ["病机", "脉细弦者，细主阴血亏虚，弦主气机郁滞。原文谓“失血后咳，肺阴大伤”，阴伤则脉道不充而细，肺金失养、气机不畅则弦。咽为肺之外候，阴伤气郁，咽哽且痛，渐成喉痹，故脉见细弦，治以和养，养阴和络为要。", ["细", "弦"]], "17811": ["病机", "脉息弦滑者，弦主痰气郁结，滑主痰热内壅。原文谓“嗜饮伤肺，痰热内阻”“痰扰为肿，热炽为哽”，痰热交阻于肺咽，气机不利，故脉弦滑。弦为郁、滑为痰热，与咽肿发哽将成喉痹相应，拟以清化，清痰热、利气机。", ["弦", "滑"]], "17812": ["病机", "脉息浮弦者，浮主邪在表分，弦主气机郁滞。原文仅言“治咽红发哽，脉息浮弦”，咽红发哽乃风热郁于上焦，浮为邪浅在表，弦为气郁不舒，风热搏结咽嗌，故脉浮弦。浮弦并见，示病位偏上偏表，治当疏风清热、利咽散结。", ["浮", "弦"]], "17813": ["病机", "脉见细弦者，细为阴伤，弦为气痹。原文谓“咳嗽绵延，咽哽发呕，音嘶痰少”“阴伤气痹”，久咳伤阴，肺阴不足则脉细，气机痹阻则脉弦。阴伤气痹，咽喉失养，故哽而音嘶、痰少发呕，脉细弦正合阴亏气郁之机，治以和养。", ["细", "弦"]], "17814": ["病机", "脉见细弦者，细主阴亏，弦主气机失和。原文谓“咳嗽失音，虚而非实，属金破不鸣”“肺肾两为失司”，肺肾阴亏，金破不鸣，脉道不充故细，气失和降故弦。细弦示虚中夹郁，音之根、声之户受伤，故治以和降，养阴降气。", ["细", "弦"]], "17815": ["病机", "脉弦且滑者，弦主风动气逆，滑主痰浊内盛。原文谓“风痰互扰，肢骱抽搐，面麻舌强，甚则神迷跌仆，属五痫之一”，风痰上扰清窍，走窜经络，故脉弦滑。弦为风、滑为痰，风痰相搏，与抽搐、面麻、舌强、神迷相应，治以熄化，熄风化痰。", ["弦", "滑"]], "17816": ["病机", "脉弦滑，弦主肝风，滑主痰浊。原文谓痫厥有根，不发时舌强、肢麻头，乃风痰内伏、阻滞经络之征。弦滑并见，说明肝风挟痰上扰清窍，虽未发作而风痰之根未除，故从熄风化痰立法，以断其根。", ["弦", "滑"]], "17817": ["病机", "脉来弦滑，弦为肝风，滑为痰盛。发时神迷手痉、目瞪口呆、喉似曳锯，皆风痰上壅、蒙蔽清窍、走窜经络之象。弦滑之脉正合风痰内盛之机，故主痫厥有根，治当熄风化痰以冀除根。", ["弦", "滑"]], "17818": ["病机", "脉见细弦，细为阴血不足，弦为肝风内动。猪痫屡发、喉鸣痰响、项斜肢痉，乃惊痰入络、风动痰阻之候。细弦说明病久阴伤而风痰未息，络脉失养兼痰浊阻络，故急拟开降以豁痰熄风。", ["细", "弦"]], "17819": ["病机", "脉见细弦，细主阴亏，弦主肝旺。癫痫复发，言语喃喃、有时默默、彻夜不寐，为痰热内蒙、机关失利，兼阴血不足、肝风内扰。细弦之脉反映痰热内郁而阴分已伤，故治以镇养，镇肝养阴兼化痰热。", ["细", "弦"]], "17820": ["病机", "脉弦滑，弦属肝风，滑属痰浊。界乎癫痫之间、有根屡发，发则神迷喉鸣、言语反常，皆痰邪蒙蔽机关、风痰上扰所致。弦滑之脉与痰风内盛相符，故拟镇养，先冀艰寐得和，以安神定志为要。", ["弦", "滑"]], "17821": ["病机", "脉息弦细，弦为肝风内动，细为阴血亏虚。痫厥不平，轻发神志模糊，重发手足颤动，一日数十次，甚至身热胃呆，乃风动痰扰、阴血不足之象。弦细说明肝风未息而营阴已伤，故治以镇养，镇肝潜阳、养阴安神。", ["弦", "细"]], "17822": ["病机", "脉见弦滑，弦主肝风，滑主痰浊。阳并于阴为癫，癫象有根，每发神呆目瞪、当脘懊𢙐、言语错落，皆痰浊蒙蔽心窍、肝风内扰之候。弦滑之脉正示风痰内盛，故拟开降，豁痰开窍、降逆平肝。", ["弦", "滑"]], "17823": ["病机", "脉见弦数，弦为肝火亢盛，数为热象。癫厥屡发、口吐白沫、手痉目瞪，乃痰邪入络；心阴不足、肝火有余，故脉弦数。弦数说明肝火挟痰上扰、阴分受伤，治拟清降，清肝泻火、降痰宁心。", ["弦", "数"]], "17824": ["病机", "本案幼童寒湿互扰，发为河白肿胀。脉细主正虚、湿滞脉络，弦主寒湿内阻、气机不畅，故脉见细弦。细弦相合，说明寒湿困阻而正气已伤，与形肿之症相应，故治以疏导，祛湿而不伤正。", ["细", "弦"]], "17825": ["病机", "黄疸渐成、形黄脘闷，为湿郁中焦、气机壅滞。脉细示营血不足或湿阻脉道，弦示肝郁气滞、湿浊内阻。细弦并见，说明湿郁气滞而兼正虚，与脘闷形黄相应，故治以疏和，疏肝化湿、调和脾胃。", ["细", "弦"]], "17826": ["病机", "自汗盗汗久而未止，久汗必伤营阴，卫外不固。脉细主阴血亏虚、脉道不充，弦主虚风内动或气机失和。细弦说明汗久营阴耗损、阴阳失于固密，与自汗盗汗不止相应，故治以固养，固表养阴以止汗。", ["细", "弦"]], "17827": ["病机", "屡屡内热、咳呛频仍，热蒸痰流于络，颈项结核。脉细主阴液不足、脉道失充，数主内热亢盛。细数并见，说明阴虚内热、痰热互结于络，与咳呛、结核相应，故治以清养，清虚热、养阴液。", ["细", "数"]], "17828": ["病机", "禀体阴虚，郁热蒸痰阻于络脉，项筋牵引，结核久而成疬。脉细主阴虚脉道不充，弦主郁热内结、络脉拘急。细弦说明阴虚郁热、痰阻络脉，与项筋牵引、结核相应，故治以清养，养阴清络化痰。", ["细", "弦"]], "17829": ["病机", "耳后结核属少阳，阳亢火化煅凝成痰，溃久不敛、屡屡抽搐，头痛耳鸣面赤目花。脉弦主少阳阳亢、气火内郁，滑主痰热壅盛。弦滑并见，说明阳亢痰火流络，与诸恙蜂集相应，故拟清化。", ["弦", "滑"]], "17830": ["病机", "经事后期而少，营虚生热，热蒸痰阻于少阳，耳后结核胀大。脉沉主病在里、营血不足，弦主少阳郁滞、痰结络脉。沉弦说明营虚痰热内结于里，与经少、结核胀大相应，故拟和养。", ["沉", "弦"]], "17831": ["病机", "马刀将穿溃，余者欲成未成，体虚挟热，热则生痰流于络，坚红而痛。原文未识脉名，故脉象要素从缺。所述体虚挟热、痰流络脉，说明正虚而痰热结聚，与结核坚红而痛、将溃未溃相应，故拟宣化，宣络化痰。", []], "17832": ["病机", "脉数舌红，为消渴阴虚火旺之象。饮一溲二，上渴下消，津液亏耗，虚火内炽，故脉数；舌红亦为热象。肉落肌灼，乃阴伤液涸，肌肉失养。脉数主热，此热为虚火，非实热，故治以清养，清虚热而养阴液。", ["数"]], "17833": ["病机", "消渴绵延，饮水无度，溺亦无度，脉数。脉数主热，此因阴虚火旺，虚热内扰，故脉数。饮水无度而溺亦无度，乃上焦燥热、下焦不固，津液不能输布而直趋下窍。脉数反映阴虚内热之病机，治以清上和阴、摄下固窍。", ["数"]], "17834": ["病机", "脉象濡细，为气阴两虚之征。饮一溲二，渐成消渴，阴液亏耗，脉道不充，故细；气虚不运，湿滞脉中，故濡。濡细并见，示气阴不足，脾肾两虚，不能蒸腾津液，故治以和养，益气养阴以复其常。", ["濡", "细"]], "17835": ["病机", "脉右细左弦，右细主肺脾气虚，左弦主肝阴不足、肝阳偏亢。饮一溲二，将成消渴，乃气阴两伤，肝脾不调。右细为脾肺气虚，左弦为肝阴亏虚、筋脉失养。脉象示本虚标实，故治以和养，调和肝脾、滋养气阴。", ["细", "弦"]], "17836": ["病机", "脉见细弦，细主阴血不足，弦主气机郁滞。肺脾受毒，棉花疮遍体，肾囊发胀，淋浊虽止，寒热发作，郁邪上攻下注。细弦示正虚邪郁，气血不畅，毒邪留恋。脉细为阴伤，弦为郁滞，故见郁邪上攻下注之势，病情险重。", ["细", "弦"]], "17837": ["病机", "脉细，为气血不足之象。流火红肿，溢脓未透，形寒，乃正虚不能托毒外出。脉细主气血两虚，无力鼓动血脉，故脓未透而形寒。细脉示正气不足，邪毒内陷，治以疏托，疏邪托毒，扶正以助透脓。", ["细"]], "17838": ["病机", "脉见沉弦，沉主病在里，弦主气滞疼痛。流火坚肿，脉沉弦，示邪毒深陷于里，气血郁滞，结聚成肿。沉为病位深，弦为痛为郁，坚肿不散，恐其发头穿溃。脉象反映邪毒内结、气血壅滞之病机，故有穿溃之虞。", ["沉", "弦"]], "17839": ["病机", "脉见细弦，细主正虚，弦主邪郁。骑梁发背，红晕四散，中腐色青，属半阴半阳。细弦示气血不足而邪毒郁滞，正虚邪实，故险重之至。细为阴伤血少，弦为毒邪结聚，半阴半阳之证，脉象反映正不胜邪，病情危重。", ["细", "弦"]], "17840": ["病机", "脉见细弦，细为营血不足，弦为气机郁滞、络脉不畅。流注三处溃脓，脓泄则营液耗伤，故脉细；疮毒留滞经络，气血运行受阻，故脉弦。细弦并见，示正虚而邪滞，与曲池已溃、腋下臂上欲蒸脓之症相应，治以宣化，正合宣通郁滞、化散余毒之意。", ["细", "弦"]], "17841": ["病机", "脉见弦滑，滑主痰湿壅盛，弦主络脉拘急。原文谓疮由虚发、营液受伤，两足软弱、络脉拘挛，是营液亏而痰湿未化，痰阻络脉则拘挛，液伤筋脉则软弱。弦滑之脉反映痰湿内蕴、络脉不和，与流注溃处不一、两眼未收相应，治以和养，即和营化痰、养液舒络。", ["弦", "滑"]], "17842": ["病机", "脉见弦滑，滑为痰湿内盛，弦为气机不畅、络脉拘急。原文称痰注不一、久而不敛，渐至营卫受伤，营争为寒、卫争为热，寒热频仍，防成疮劳。痰湿流注，营卫失和，故脉弦滑；久溃不敛耗伤营卫，故见寒热。此脉主痰湿壅滞、营卫不和之病机，治以和养，即化痰和营、调养营卫。", ["弦", "滑"]], "17843": ["病机", "脉左细右弦，左候血分，细为血少；右候气分，弦为气滞。产后新血已伤，故左脉细；旧瘀入络，气机受阻，故右脉弦。左腹旁结块有形，正是瘀血留络之征，防成败瘀流注。细弦并见，示血虚而瘀滞、气机不畅，治以疏和，即疏瘀和营、行气散结。", ["细", "弦"]], "17844": ["病机", "脉见细弦，细主营血不足，弦主气机郁滞、痰络不和。右肩流痰，身热纳微，是痰毒蕴结而营液已伤，纳微示脾胃气弱，故脉细；痰阻络脉、气机不畅，故脉弦。细弦之脉示正虚邪滞，与流痰高肿、身热纳微相应，防天热难支，治以宣化，即宣通痰滞、化散郁结。", ["细", "弦"]], "17845": ["病机", "脉见弦滑，滑主痰湿壅盛，弦主气机郁滞、络脉不和。流痰发于臂部，高肿色变，势难消退，是痰湿凝聚、气血壅遏之象。痰湿内盛故脉滑，络脉受阻、气机不畅故脉弦。弦滑并见，示痰湿壅滞、气血不和，与高肿色变相应，治以疏和，即疏化痰湿、和畅气血。", ["弦", "滑"]], "17846": ["病机", "脉见细弦，细为营血不足，弦为气机郁滞、痰络不和。环跳流痰高肿，渐滋暗长，久防蒸脓穿溃，是痰毒深伏、日久耗伤营液。痰阻络脉、气机不畅故脉弦，营液渐伤故脉细。细弦之脉示正虚邪滞、痰络不和，与高肿暗长之势相应，治以疏化，即疏化痰滞、化散郁结。", ["细", "弦"]], "17847": ["病机", "脉见沉弦，沉主病在里、气机内郁，弦主气滞络阻、痰湿凝聚。身热脘闷，是湿郁气滞、中焦不运；环跳肿痛，防成流痰，是痰湿深伏经络。沉弦之脉示痰湿内郁、气机不畅，病位偏里，与脘闷、环跳肿痛相应，治以疏降，即疏通气机、降化痰湿。", ["沉", "弦"]], "17848": ["病机", "脉见细涩，细为阴血亏少，涩为气机痹阻。案中膻中流痰久溃，脓孔甚大，本元更伤，又连次失血、咳嗽，阴伤气痹，故脉细涩。此脉主内损，与失血、咳嗽相应，示气血两伤、络脉不畅，属损象，宜早护持。", ["细", "涩"]], "17849": ["预后", "脉见濡细，濡为气虚湿滞，细为血少络伤。股阴毒溃脓孔深，筋络先伤，致半身抽搐疼痛；疮毒耗气，气逆汗多、心悸神疲、纳微发呕、大便失行，皆气血两虚之候。脉濡细而见痉变之势，故言势防痉变，主正虚邪陷。", ["濡", "细"]], "17850": ["主病", "脉见弦细，弦主肝郁气滞，细主血少络虚。股阴高肿，将成流痰，乃肝气不舒、痰湿凝滞于阴股，气血不畅而肿。弦细之脉应其肝郁血虚、痰凝络阻之机，故治以疏和，疏肝和络以消痰肿。", ["弦", "细"]], "17851": ["预后", "膝眼痈流脓不止，因疮发病，脓泄日久则阴血耗伤，虚热内生，故脉数。数脉在此非实热，乃疮疡久溃、正虚邪恋之象，预示将成劳损，即“脉数将劳”。主病机为疮毒耗损气血，虚热内扰，与流脓不止相应。", ["数"]], "17852": ["兼症", "乳痈蒸脓，色红兼肿，脉浮舌白，并有表症，微寒微热。浮脉主表，邪在肌表，卫气奋起抗邪，故见微寒微热；舌白亦为表邪未解之征。此脉浮与痈肿蒸脓并见，说明疮毒兼挟表邪，表里同病，故治以疏和，疏表和中。", ["浮"]], "17853": ["病机", "脉息沉弦，沉主病在里，弦主肝经气滞、痛证。肾囊肿痛，疝气起因，将变子痈，形寒形热，蒸脓之势。沉弦说明疝气属肝经寒湿凝滞于里，气血壅阻，久则化热蒸脓。脉与肾囊肿胀、寒热并见相应，故治以疏和，疏肝理气。", ["沉", "弦"]], "17854": ["主病", "脉象浮弦，浮主邪在表分，弦主肝郁气滞。脏毒绵延，内缩不见，乃肛肠毒邪久延，气血壅滞，而脉见浮弦，说明毒邪有外浮之势，肝气不舒。浮弦与脏毒内缩相应，示正虚邪恋、气机不畅，故治以和养，调和气血以养正。", ["浮", "弦"]], "17855": ["病机", "脉见细弦，细为血虚络少，弦为肝气郁滞。肝气充斥，挟痰入络为乳癖，挟饮扰中为吐沫。细弦之脉正合肝郁血虚、痰饮内阻之机，乳癖与吐沫皆由肝气挟痰饮为患，故治以和养，养血柔肝、和络化痰。", ["细", "弦"]], "17856": ["病机", "乳癖久不消渐胀大坚结，属由癖成岩之势。厥阴、阳明之脉皆绕于乳，血不养肝、肝邪犯胃，故脘胀、头眩火升。脉息弦大为肝邪亢盛、气血壅滞之象，弦主肝郁，大主邪实，外疡由内因而发，故拟和化。", ["弦", "大"]], "17857": ["病机", "乳癖已成岩象，营阴久亏、痰热互扰，复感新邪致寒热、神烦心悸、脘胀纳呆、头眩火升。脉息弦大示肝邪未敛、痰热壅盛，正虚邪实交织，故从调气清阴、化痰热而和内外。", ["弦", "大"]], "17858": ["病机", "乳岩散漫、内胀外肿、四旁红晕，厥阴充斥、阳明内络大伤，致纳呆作胀、肢肿心悸艰寐，营虚气痹。脉见细弦，细为营阴亏虚，弦为肝邪内扰，挟痰郁湿互扰，故拟清营和络。", ["细", "弦"]], "17859": ["主病", "肠痈将成，少腹肿痛、大便不行。脉见沉弦，沉主里、主肠腑积滞，弦主痛、主气机壅结，脉证相合，示痈毒内结于肠、气血不通，故治以通降，导其壅滞。", ["沉", "弦"]], "17860": ["主病", "脐肠痈脐凸红肿、腹膨作痛，大便已通而虑外溃。脉数内热，数主热盛，热毒壅聚肠间、气血腐蒸，故红肿作痛；热势方张，防其酿脓外溃，治以清降，清其热毒。", ["数"]], "17861": ["病机", "缩脚肠痈，小产后仍未减，肢骱酸痛。脉见细弦，细为产后营血亏虚，弦为余邪郁滞、经络不和，正虚而邪恋，故肢节酸痛、痈势缠绵，治以分疏，疏其郁滞兼顾营虚。", ["细", "弦"]], "17862": ["妇人", "月事过期四月，脉见细滑，为怀麟之兆。滑主孕脉、主血盛，细为营血初聚；然阳明营事初停，脘宇懊𢙐、纳减、腹疼腰楚，皆胎元不足之象，脉证合参，故治以和养安胎。", ["细", "滑"]], "17863": ["病机", "便血后结痞内攻，脐上四旁跳动，小便不利、脘腹坚结，奔豚症肾气有伤、牵连肝肺。脉见弦细，弦为肝气上逆、奔豚动气，细为肾气亏虚，本虚标实，故治以温通，温肾降逆。", ["弦", "细"]], "17864": ["病机", "脉见弦滑，弦主肝郁气滞，滑主痰湿内蕴。患者遇事善忘，由昔年痢下之虚，致心脾两伤，气血不足，痰浊蒙蔽清窍。弦滑之脉反映肝郁痰凝之病机，与健忘证相应，治以和养，即调和肝脾、化痰养心。", ["弦", "滑"]], "17865": ["病机", "脉偏弦细，右滑。弦细为肝阳有余、心阴不足之象，滑脉主痰饮内蓄。心阴亏虚则心悸少寐，肝阳上扰则耳鸣头蒙肢麻，痰饮内停则多梦肉𥆧。脉症合参，证属怔忡，病机为心肝阴亏、痰饮内扰，故拟镇养。", ["弦", "细", "滑"]], "17866": ["病机", "脉息弦细，弦主肝阳偏亢，细主阴血不足。病后心气心阴两伤，心悸艰寐，多思多虑，怔忡之象。弦细脉反映肝阳未靖、心阴亏虚之病机，与心悸艰寐相应，治以镇养清养，即镇肝阳、养心阴。", ["弦", "细"]], "17867": ["病机", "脉见细弦，细为阴血亏虚，弦为肝阳内扰。操劳过度耗伤阴血，肝阳偏亢，神不守舍，痰热内蒙，故彻夜不寐，将成怔忡。细弦脉揭示阴亏阳扰、痰热内蕴之病机，与不寐怔忡相应，治以镇养。", ["细", "弦"]], "17868": ["病机", "脉沉弦，沉主里主虚，弦主肝风内动。封藏早亏，诸虚杂出，肝藏魂主风，心藏神主血，诸窍出风，畏光怕亮，胸脘气攻无度。沉弦脉反映肝肾亏虚、肝阳化风之病机，与畏光、气攻症相应，治以驯龙雷静肝阳。", ["沉", "弦"]], "17869": ["病机", "脉息细弦，细主阴血不足，弦主气滞疼痛。幼年食积为多，滞则痛，虫则阵痛，扰上为呕，下便如脓，防成内痈。细弦脉反映食积虫扰、气滞血瘀之病机，与脘腹阵痛、呕脓相应，治以疏和。", ["细", "弦"]], "17870": ["病机", "脉见沉弦，沉主里主虚，弦主气机郁滞。漏经三月，营阴亏虚，气痹不运，故腰酸腹痛、心跳头蒙。沉弦脉反映营亏气痹、肝脾不调之病机，与漏经、腰腹症相应，治以和补，即调和气血、补益营阴。", ["沉", "弦"]], "17871": ["病机", "脉见弦滑，弦主肝郁气滞，滑主痰湿内蕴。奇经不摄，崩后经漏，营阴大伤，诸虚杂出，头眩耳鸣，心悸腰楚。弦滑脉反映肝郁痰凝、奇经失摄之病机，与崩漏、眩悸症相应，治以和养，即调和肝脾、养营固冲。", ["弦", "滑"]], "17872": ["病机", "脉息濡细，濡为气虚阳弱，细为营血不足。老年崩放绵延未止，冲海不摄，气营两亏，故脉见濡细。濡细并见，正合气血双亏、冲任失固之机，与肢腰酸楚相应，治以和养，即调补气血以摄冲任。", ["濡", "细"]], "17873": ["病机", "脉见芤细，芤主失血，中空如按葱管，细主营阴亏少。崩放减而未止，向有失血，内络已损，营阴不摄，故脉芤细。芤为血去络伤之征，细为阴血不足之象，炎夏急宜调和，正虑暑热更耗营阴。", ["芤", "细"]], "17874": ["病机", "脉见细弦，细为血海涸竭、营阴不足，弦为奇经失养、肝木偏旺。操劳伤奇经，经漏三月不止，统藏不摄，血海愈涸，故脉细弦。细弦并见，示气血两亏而肝阳不潜，故治以温养八脉、兼补气血，栽培火土以固根本。", ["细", "弦"]], "17875": ["病机", "脉见濡细，濡主中气受伤、失于砥柱，细主营阴失养。气怯神倦，肝阳内扰，头眩耳鸣，月事趱前，皆由中气不足、营阴失养、气无以摄所致。濡细之脉正合气血两虚、肝阳偏扰之机，舌腻则兼痰湿，故拟轻重调补。", ["濡", "细"]], "17876": ["病机", "脉见细弦，左关尺俱涩。细为营血亏少，弦为奇经不摄、肝气偏亢，涩为血行不畅、络脉失养。月事早而且多、零落不止、带下淋漓，奇经久不摄，故脉细弦而关尺涩。涩象示血海空虚兼瘀滞，治以和养，调奇经而益营血。", ["细", "弦", "涩"]], "17877": ["病机", "脉息细弦，细为营阴不足，弦为肝气不舒、木郁克土。当脘作痛，是肝气侮中；头眩腰楚，是营亏而奇经失养。脉细弦正合营亏气郁、肝胃不和之机，故治以疏和，兼调月事腹痛，疏肝和营并进。", ["细", "弦"]], "17878": ["病机", "脉见细弦，细主营亏，弦为肝气充斥。营亏气痹，奇经失职，月事不调而少色泽，营失养肝，肝气转盛，侮中则腹部攻痛，入络则两乳发胀，甚则晨起发呕。细弦之脉正示营虚而肝旺，故拟调养，养血柔肝以和奇经。", ["细", "弦"]], "17879": ["病机", "脉见弦滑，弦为肝气偏旺、气痹不舒，滑为营阴渐充、血行流利。月事衍后渐得准期，惟经前腹胀腰楚，是营亏气痹、奇经未和。弦滑并见，示肝气尚郁而营血渐复，故再从和养，调肝理气以巩固疗效。", ["弦", "滑"]], "17880": ["病机", "脉见细弦，细为营血不足，弦为冲任气滞。经事后期忽又先期，乃冲任不摄、血海失约之象。细弦并见，说明营虚而气不和，故治以和养，养血调气以复冲任之常。", ["细", "弦"]], "17881": ["病机", "脉见弦滑，弦主气滞，滑主痰湿壅盛。气痹营滞，腹部胀满，经事五月未行，乃气机痹阻、痰湿内停、血行不畅之故。弦滑相合，示气滞痰凝而经隧不利，治以和养，疏气化痰以通经。", ["弦", "滑"]], "17882": ["病机", "脉息濡细，濡主湿困，细主营虚。经事不调，或一二月一行，或四五月一行，营滞由于气痹，脘胀腰楚，形黄肢肿，皆脾虚湿盛、气血不足之候。濡细并见，说明气痹营滞而兼湿困，治以疏和，健脾化湿以调经。", ["濡", "细"]], "17883": ["病机", "脉见弦数，弦主气滞，数主热盛。肌灼腹满，经事七月未行，乃气滞血瘀、郁热内蒸之故。弦数相合，示气机郁滞而热灼营阴，经隧不通，治以疏和，疏气清热以通经。", ["弦", "数"]], "17884": ["病机", "脉来如弦，弦主邪郁气滞。灼热无汗，午后尤甚，面浮色青黄，口苦而渴，咳嗽痰青白有沫如珠，舌苔滑腻灰黑，神昏不寐，乃内伏秋燥化热、外受冷露之寒，表里不通，邪深阴耗，渐至内陷，证属险危，故以逆流挽舟法透邪外出。", ["弦"]], "17885": ["预后", "真武汤连服两剂，导下燥粪甚多，脉静身凉，灰黑苔转白腻而滑，是内伏秋燥已化、阳气渐复之佳兆。然面浮喉痒、咳嗽痰青如胶、白沫如珠未松，乃外寒未宣、遏塞肺窍，恐成痰饮咳喘，故以小青龙汤直入病所。", []], "17886": ["病机", "两手关脉见弦，关候肝脾，弦主气机不和。阴阳不和，夜半大便易于受凉，骤然寒热汗出直至足底，夜半又下软粪，乃病后汗多、阳气衰微、卫外不固之象。关脉弦示肝脾失调，故拟参附汤扶阳固气。", ["弦"]], "17887": ["病机", "两手关脉弦而有力，关主肝脾，弦而有力为气滞邪争之象。连日寅刻大便，泄泻三次，体虚受寒，寒热时作，胸腹膨胀，小便混浊黄色，是虚疟来派、清浊升降失常。弦而有力说明邪正交争，故以补中益气汤升清降浊。", ["弦"]], "17888": ["病机", "脉弦不平，示阴阳未调，疟邪留于少阳，枢机不利。先寒后热、汗多指冷，为汗多亡阳之兆；泄泻止、食粥，胃气渐复。弦为疟邪未解之象，故主间日疟，治以参附汤固阳。", ["弦"]], "17889": ["病机", "原文未及脉象，然述大病甫痊、精气未复，连下宿粪、足肿虚汗、便血，断为水寒土湿木郁风动。此由火衰土湿，木郁生风，故当补火燥土、暖血温肝，痔血亦以此通之。", []], "17890": ["其他", "此段未载脉象，述热将内陷、危险之至，先紫雪丹驱热，犀角地黄汤救阴，汗出热解，继育阴、导燥粪，神静胃开。惟右手经络为湿邪所窜，软弱不便，本治痿独取阳明法获转运。", []], "17891": ["病机", "两寸关脉如弦，舌短硬苔干黑、唇破口臭、手足心胸腹火灼，为邪热耗顿肠胃津液，肌肤如鳞。弦主邪热内郁、津伤风动；进紫雪、犀角地黄后微汗，脉稍平，舌尖红转淡，津液未回，内热极则外生寒。", ["弦"]], "17892": ["预后", "昨进育阴重剂，始能脉静身和，眠安便浊，示邪热渐退、阴阳稍和，为病势向愈之兆。惟燥粪凝结、舌条干燥，津液未回，水为火涸，故仿增液汤加淡渗，引热从小肠而出。", ["静"]], "17893": ["病机", "脉软痿，右手筋脉软痿不能运动、似乎作酸，为邪化火逼入经络，耗伤气血津液，筋脉失养。舌干红而边底潮润，示内液渐复；仍宗增液法，使内液充复则舌上生津。", ["软"]], "17894": ["病机", "原文未出脉象，述八珍加黄耆后胃气已苏，右手骨节捏之知痛、肩臂手指酸麻。引经云四肢为诸阳之本，邪客经络、阳气内衰，不能荣养筋脉，日久延蔓，故双固气血加附子通阳、桑枝引经。", []], "17895": ["病机", "夜右手脉息忽伏两三刻方起，因此软弱，为邪气窜入太阳经络、阳气被遏之象。初病头疼背板从太阳而入，误以烧酒贴胸，火未引出而邪内窜；加附子后热甚，似邪为附子冲动，继小柴胡枢转外达，汗出热解。", ["伏"]], "17896": ["预后", "脉息平静，说明邪退正安，虚热已清，胃气渐复，小便清利，脏腑之病均无。惟右手不能悬起，乃经络余邪未净，故以扶正化湿专治经络。脉静为病退之征，与身常带汗、胃气日健相应，预后良好。", ["平"]], "17897": ["治法", "脉静神安，示正气渐复、神志安定，病势向愈。仿古贤独取阳明法，专治右手，因阳明主润宗筋、束骨利机关，脉静则内无躁扰，可专力于经络。此段以脉静为凭，说明病机已由脏腑转出经络，故治法独取阳明。", []], "17898": ["病机", "脉来弦紧，弦主气滞，紧主寒凝，燥粪塞于肛门，腑气不通，正气未充，不能送出宿粪。弦紧为邪结于内、气机壅滞之象，与大便十余日不行、宿粪杜于谷道相应。故用导法下粪，继以保元汤、当归补血汤扶正润肠。", ["弦", "紧"]], "17899": ["病机", "两关脉见涩，涩主血少津亏、气机不利。病久正气未充，一派虚弱之象，头汗如珠为虚阳上越。涩脉见于关部，说明中焦气血不足，肠道失润，宿粪虽存亦无几。故仿八珍汤去川芎、茯苓，加黄耆固表、苏子降气润肠。", ["涩"]], "17900": ["预后", "未载脉象，以大便如条、脏腑无病为据，断为可弗药，饮食调和则气血自然充复。背脊肩臂因之自如，渐能起坐步履，是病愈之征。此段重在预后，说明病由三月出诊至六月止，计六十九日，病变虽殊，终占勿药。", []], "17901": ["其他", "未载脉象，述乳射之证，右乳坚硬如石、乳头缩入、七处溃出黄水，头昏眼赤羞明，舌灰焦厚，昏晕。此属肝郁气滞、毒瘀互结，有转为乳岩之险。进疏肝解郁重剂后乳头伸出、疮口肉平，坚硬消软，遍身透出红脓窠疮而愈。", []], "17902": ["妇人", "产后血晕，昏倒不省三日，鼻无呼吸，挺直僵卧，腹大而高，上半身温和，下半截冰冷，脉息未绝，并无七恶形状。此离经之血不下行，上攻心，血舍空虚，止存微气。脉息未绝示生机尚存，故可救。", []], "17903": ["妇人", "产后昏厥，目闭牙关紧急，鼻无声息，惟心胸气动，腹大，腿脚若冰，上身及两手尚温。两手脉无七恶状，说明正气未绝，瘀血内阻、上攻心。灌黑龙丹后瘀血大行，再用华佗再生丹、大豆紫酒，恶露大行，腹大渐平，两手微动。", []], "17904": ["其他", "此段未识脉名，述产后病者苏醒后声微无力、口渴发热汗出，医者以独活、大豆酒、童便通阴阳经脉。原文未及脉象，故脉素为空。所论重在药后反应与预后，非脉诊主病，列其他。", []], "17905": ["病机", "脉象稍敛而不浮散，示产后气血双亏、虚阳渐收。浮散为气不内守，稍敛则虚阳有归；然舌苔白腻灰黑、汗出、声微、神疲，正是气血双亏本证。脉敛而不浮散，说明阴血虽亏而阳气未至外越，故断为产后本虚。", ["敛", "浮", "散"]], "17906": ["其他", "此段未识脉名，详述咽喉肿痛、气上塞喉、肉𥆧筋惕、睡中惊掣等症，辨为梅核气类，咽门红丝颗粒如虾蟆皮。原文无脉象描述，故脉素为空。所论重在症候辨析与病机推测，非脉诊主病，列其他。", []], "17907": ["病机", "脉见乍大乍小，为气机紊乱、神志失常之象。抑郁不遂致精神恍惚、言语错乱、妄闻妄见，脉乍大乍小正是气血逆乱、神明失主之征，大有狂意。此脉主癫狂类病机，与情志抑郁、痰火扰心相应。", ["大", "小"]], "17908": ["病机", "左手脉软而细，右手脉洪而弦，示营血亏虚而风火痰热偏盛。软细为阴血不足，洪弦为风火内动；口㖞舌歪、流涎、鼻干，正是中府中藏、风痰阻络之候。脉象左右异，说明虚实夹杂，年高涸荣耗卫，故不可峻攻。", ["软", "细", "洪", "弦"]], "17909": ["预后", "两手脉渐和，惟左手稍大而弦，示病势向愈而心经郁热未清。脉渐和说明气血渐复，稍大而弦为余热未化；舌红未起苔，正合心经郁热。此段以脉判断预后，故列预后。", ["大", "弦"]], "17910": ["其他", "此段未识脉名，述七旬老妇中风不语、口眼㖞斜、流涎便闭，医以吐下导法及转舌膏取效。原文无脉象描述，故脉素为空。所论重在类中风病机与治法，非脉诊主病，列其他。", []], "17911": ["病机", "脉微而数，微为阳气之微，数为风邪之炽。原文引《内经》以释痛痹、偏枯之由，谓血舍空虚而气分热炽，风从营卫而入，因藏府虚实寒热而变证。此脉主阳虚风炽、本虚标热之病机，与臂痛不举、偏枯历节相应。", ["微", "数"]], "17912": ["病机", "脉数恶热，为肝火内炽之象。肝火乘脾，故咯血胁痛、项下有核、咽痛；火迫脾土，运化失职则便溏。反能食者，乃脾虚求助，食入不能胜而痞满。此证本在肝火亢盛，标在脾土受侮，故治当制肝益脾，清火扶土并举。", ["数"]], "17913": ["预后", "脉弱而数，弱为脏气内衰，数为虚阳浮动。肝脏失调，侵脾则腹痛，侮肺则干咳，病从内生。形瘦色槁，上热下寒，根本已漓，乃阴阳俱损、虚阳上浮之候。脉证相悖，正虚难复，故断为难全愈。", ["弱", "数"]], "17914": ["病机", "形盛脉充而两尺独虚，尺脉候肾，独虚则根本不足。下体麻痹，火浮气急，乃肾虚不能摄纳，虚阳上浮。枝叶虽盛，根本已亏，外强中干，未足恃也。此脉象揭示下元虚惫、浮阳不潜之病机。", []], "17915": ["治法", "诒按提出参用肾气法以温摄之，针对前段根本虚衰、火浮气急之证。肾气丸温补肾阳、摄纳浮火，使下元得固，虚阳归宅。此从脉证合参，以温摄为治，切中下虚上浮之病机。", []], "17916": ["病机", "阳脉则缓，阴脉则急，缓为阳气弛纵，急为阴血拘挛。类中偏左，于法为逆，指节屈不能伸，乃阴急使然。经云肝苦急，食甘以缓之，故于前方增阴药之甘润者，以缓其急。此脉象示阴阳失和、筋脉拘急之病机。", ["缓", "急"]], "17917": ["病机", "脉虚而涩，虚为气血不足，涩为血行不畅。左半手足麻痹，食不知味，乃气血不能运行周体，肢体失养，脾胃失运。此非外邪卒中，而是内虚渐积，故为类中之渐，当及早调补气血。", ["虚", "涩"]], "17918": ["病机", "脉浮数动，浮为虚阳上越，数为热，动为肝风煽动。齿疼舌赤、精浊，乃肝肾两虚，水不涵木，肝风暴动，神必昏迷。此河间所谓肝肾气厥，舌喑不语，足痱无力之证。治宜温肾摄纳，参凉肝清火，复方兼顾。", ["浮", "数", "动"]], "17919": ["其他", "诒按即古法而化裁之，参详脉证，斟酌尽善。此段为评注之语，强调临证须脉证合参，于古方中灵活化裁，使治法切合病机。虽未出具体脉象，然示人以脉证互参、斟酌尽善之旨。", []], "17920": ["病机", "脉濡为脾虚湿盛之象，按之则弦，说明湿浊之中兼夹肝风内动。脾失健运则饮邪内生，肝风挟饮走窜经络，故见右肩及手指麻木、两腿酸痒难以名状。原文断为「脾饮肝风，相合为病」，乃类中之渐，正因濡脉主湿、弦脉主风，风饮相合，壅滞络隧，故不可不慎。", ["濡", "弦"]], "17921": ["病机", "脉虚为阴气不足，数为有热，合之则示阴虚而湿热内蕴。原文言「湿热乘阴气之虚而下注」，故两膝先软后肿、不能屈伸。虚脉主正虚，数脉主热，湿热下注膝部，久则关节肿大变形，成鹤膝风。此脉虚数并见，正是虚中夹实、湿热乘虚下注之病机。", ["虚", "数"]], "17922": ["病机", "原文言「脉不弱数」，即脉不弱而反见数象，说明非纯虚之候。惊悸易泄、腰疼足软虽似虚象，然脉数主火，形不枯瘁，故实因痰火内扰。痰火扰心则惊悸，下扰精室则易泄，腰疼足软亦痰火流注所致。脉不弱数一句，正是辨其非虚、不可遽补之关键。", ["数"]], "17923": ["预后", "脉弱色悴，示正气已虚，而肝风与痰饮相搏，内壅脏腑、外闭窍隧，故不寐不饥、肢体麻痹。病经年久，邪实正虚，攻之则正益虚，不攻则病不除，原文叹为「最为棘手」。脉弱色悴与痰风壅闭并见，说明攻补两难，预后堪忧，故列于预后。", ["弱"]], "17924": ["病机", "原文以「脉不数，口不干」为辨，说明久嗽未必即成损证。损证多脉数口干，今脉不数、口不干，则非阴虚火旺，乃肺饮郁伏不达所致。饮邪伏肺，肺气不宣，故久嗽不止。脉不数一句，正是排除损证、断为肺饮之依据，病机在饮伏而非虚损。", []], "17925": ["病机", "脉弦而细，弦主邪滞，细主正虚，合之示体虚而邪气留滞。原文言「体虚邪滞，肺络不清」，肺络为邪所阻，故脉见弦细。幸不数者，说明尚无化热伤阴之象，病势尚缓。此脉弦细而不数，正是虚中夹滞、肺络不清之病机，与体虚邪滞相应。", ["弦", "细"]], "17926": ["预后", "原文未识脉名，仅言「脉象与前无异」，重点在症候与调护。肺病以中气健旺、能食便坚为佳，今喘咳已久而大便易溏、能食难运，脾运已弱，殊非所宜。脉象未变说明病势未进，故若能节饮食、慎寒暖，犹可无虞。此段论肺病转归与调摄，属预后。", []], "17927": ["治法", "久嗽伤肺，便溏伤脾，脉虚而数，虚为气阴不足，数主虚热，示脾肺俱病。原文断为「脾肺俱病，培补中气为要」，因中气为生化之源，培土可以生金。若泄泻不止、不能食，则瘦削日增，预后可虑。脉虚数而便溏，故治法以培补中气为先，兼顾肺脾。", ["虚", "数"]], "17928": ["病机", "脉细为精血内耗，数为虚热，促则气逆不续。原文谓'肝肾精血内耗'，冲脉气逆'自下及上，气不收纳'，故咳吐清涎浊沫、喘而汗出，是根本先拔之候。脉细数促正合阴亏气逆、虚阳上浮之机，非实热咳血，若见血治肺则速其凶。", ["细", "数", "促"]], "17929": ["病机", "脉虚数为阴亏阳浮之象。原文'颧红声低''晡时热升''烦躁'皆虚阳上越，'咳甚吐食'为精液化痰沫。病已三年成内损，虚数脉示肝肾阴亏、阳不潜藏，故非消痰治嗽可愈，须固摄下焦、绝欲以复根本。", ["虚", "数"]], "17930": ["病机", "脉微小为阳气衰微、气血不足之征。原文'形寒''久嗽失音'，是气馁阳损、肺金失温。微小脉主虚主寒，故议固胃阳、取甘温之属，以温养中焦使阳气渐复，非清润所能治。", ["微", "小"]], "17931": ["治法", "本段无脉象，述复脉甘润法后呛止音出，得益水濡润；因胃弱便溏不宜再用，仿麦门冬汤养土之阴以生肺金。主旨为治法调整，从甘润转为养胃阴生肺金，属病后调治之策。", []], "17932": ["预后", "脉数为阴虚内热之象。原文久咳便溏腹满，脾肺同病已属难治，况脉数口干潮热，示肝肾之阴亦不足。数脉在此主虚热耗阴，三脏同病，故曰难治，属预后判断。", ["数"]], "17933": ["病机", "寸关大而尺小，为上盛下虚之脉。原文'口干，上气不下，足冷不温'，正是阳气不潜、浮越于上而不下达。寸关大示阳浮，尺小示下焦阳虚，故当用阴中阳药引阳归宅，使阳气潜藏。", ["大", "小"]], "17934": ["病机", "脉数减、咳亦缓，是虚热渐退之象。但原文谓'浮气不得全归根本'，说明虽减而未全复，下焦摄纳之力仍弱。数脉减示阳渐敛，然根本未固，故宜补益下焦以为吸受之地，属病机转归分析。", ["数"]], "17935": ["病机", "脉虚小为下元虚衰、气不归原之征。原文'气喘足冷至膝''下气上逆，病在根本'，虚小脉正合肾阳不足、冲气上逆。虽有结痰在项，不可漫用清克，当温纳根本，否则更伤下焦。", ["虚", "小"]], "17936": ["病机", "脉小数微呛，数主火，小主阴虚，火动于阴分之中。原文谓吐血得劳与怒即发，劳则伤脾耗阴，怒则肝火上升，故病在肝心。思虑劳心，心阴受灼，肝木失养而火动，血随气逆。脉数示火未熄，小示阴已亏，呛为肺气上逆之渐，故诫勿使延及肺家，正虑火刑金之变。", ["小", "数"]], "17937": ["病机", "肝脉独大，非六脉俱大，是肝部独见实大之象。失血而血色黯、大便黑，为瘀血内停之征；心下痞满、暮则发厥，乃瘀阻气机、血不归经所致。脉独大者，实邪壅于肝经，非气虚作胀。原文断为瘀血积留不去，故戒勿治其气，宜和其血，正恐耗气则血愈滞，瘀不去则血不宁。", ["大"]], "17938": ["病机", "寸静尺动，寸主上焦肺，尺主下焦肾。寸静则肺无实邪，尺动则肾阴亏而虚阳不潜，故气从下焦上冲则呛，劳动则气促。屡经失血，阴损于下，龙火失守而上僭。原文明断病不在肺而在肾，治嗽无益，宜滋肾阴，正合尺动为肾虚火动之脉，滋水则火自降，冲气自平。", ["动"]], "17939": ["病机", "心脉独大，是左寸独见洪大之象。心阴不足则阳无所附，心阳独亢则火炎于上，故口干易汗、善怒血逆。汗为心液，火迫则外泄；怒动肝火，火性上炎，血随气升而逆。脉独大者，阳亢无制之征，非实热壅盛。原文主以犀角地黄汤，凉血清心，正针对心阳独亢、血热妄行之机。", ["大"]], "17940": ["预后", "劳伤失血，心下痛闷，似属瘀滞，故原文戒不当作阴虚证治。然脉数而兼咳嗽潮热，数主火动，咳与潮热皆阴亏火旺之候，恐其由劳伤渐入阴损一途。此段重在辨其转归，脉数为关键：若数象不退，则虚火日炽，阴液日耗，故曰恐其渐入，非断言已成阴虚，乃警示防微杜渐之意。", ["数"]], "17941": ["病机", "阴不足而阳有余，是根本之论。肝善逆则气升，肺多郁则气滞，脉数示阳有余而火动。气喘咳逆、见血胁痛，皆肝逆犯肺、火载血上之候。胁为肝之分野，血随逆气而出，故痛见于胁。原文治宜滋降，滋其阴以配阳，降其逆以平火，更宜静养，正恐火动无制则血逆不已。", ["数"]], "17942": ["兼症", "再诊热渐减而头中时痛，是邪热未清、上扰清窍之象。脉数不退，说明热邪仍炽，未因体热渐减而尽解。喉中痰滞不清，乃热灼津液、炼液成痰，痰热交阻于咽喉。此段以脉数不退为眼目，提示热势虽减而病根未拔，痰滞与头痛皆由余热未清所致，不可因热减而遽停清化。", ["数"]], "17943": ["治法", "三诊体虽不热，而脉仍细数，细主阴血不足，数主虚火未宁。外热已退，内热未清，阴液未复，故脉象如是。原文断宜养阴气，正合细数之脉：细为阴亏之体，数为火动之征，养阴则细可渐充，阴复则数可自平。此段示诊脉当以脉象为凭，不因体热已退而忽视阴虚火动之本。", ["细", "数"]], "17944": ["病机", "脉虚而数，虚为气阴不足，数为虚热内扰。面黧形瘦、咳嗽气促乃肺阴亏虚，腰膝无力、大便时溏为脾肾俱弱，故断为先后天俱虚。数脉在此非实热，乃虚阳浮动之象，久延则成虚损。原文戒清润戕中气，正因脉虚示中气已馁，不可再伤。", ["虚", "数"]], "17945": ["病机", "原文言络脉空隙，未出具体脉名，然空隙即脉道不充、阴血亏虚之象。气虚游行作痛，阴虚则春升之时血随气溢，故虑其出血。治当填精益髓，因阴虚咳嗽是它脏累及于肺，非肺本病。若清凉治肺，反伤胃气，立成虚损，此脉示本虚不可攻。", []], "17946": ["病机", "脉来不柔，时自歇止，即脉失柔和而见结代。不柔示肝阳有余、胃阴不足，歇止为稠痰浊火壅滞脉络、气血运行不畅。虽目前安和，然脉已见微知著，肝阳化火生痰，久必扰动为患，故当加意调摄，治未病以防痉厥之变。", ["涩", "结", "代"]], "17947": ["预后", "大便通而脉和，示腑气已通、胃气渐复，脉象由病时之乖戾转为和缓，是邪退正安之候。脉和则气血调畅，无须再施攻伐，惟宜滋养以复其耗损。此段以脉和断预后向善，属调摄善后之论，非主病之脉。", ["和"]], "17948": ["治法", "脉小为气血不足、中气大伤之象，合目陷则精气内夺尤甚。下既不通，浊气上逆而呕，本应疗下，然脉小目陷示中气已伤，攻下则气愈陷，故先安中止呕，俟呕定中复再商通下。此脉小决定治法先后，不可径攻。", ["小"]], "17949": ["病机", "痛呕之余脉当和缓，今反搏大，即脉来洪大搏指，为胃阴不足、肝阳偏亢之象。土虚则木张，故头运欲呕、胸满不食、神倦欲卧。搏大之脉示肝阳上逆、胃气不和，久则风动痰升，渐致痉厥，故法当安胃清肝以先事预防。", ["洪", "大"]], "17950": ["预后", "脉涩为气滞血少、痰凝阻络之象。气郁痰凝阻隔胃脘，食入则噎，脉道不利故涩。涩脉示正气已亏而痰瘀互结，攻之则伤正，补之则碍邪，故断为难治。此以脉涩判断噎膈预后不良，非仅言病机。", ["涩"]], "17951": ["治法", "脉涩者正虚，涩为血少气滞、正气不足之征。食入则噎，肺气先郁，故于旋覆代赭方中加郁金、贝母、枇杷叶以开肺郁。然脉涩示正虚，攻痰降逆之中须加人参扶正，使祛邪不伤正。此段以脉涩定加参之法，属治法范畴。", ["涩"]], "17952": ["病机", "脉疾徐不常，指脉来忽快忽慢，节律不匀，反映中气大衰，升降失度。中焦脾胃气虚，运化无力，气机升降失常，故脉行无序；食格不下，即饮食格拒难下，由中气衰败、胃气不降所致。此脉象直接提示脾胃虚衰、气机逆乱之病机。", ["疾", "徐"]], "17953": ["病机", "脉虚主中气亏虚，叠伤则运化失健，故朝食暮吐、完谷不腐；色黑、腰脚少力为肾虚之征。脉虚与色黑并见，说明不仅胃病，肾亦受累，脾肾两虚，火不暖土，胃失和降。此脉虚非单纯胃虚，而是脾肾同病之候。", ["虚"]], "17954": ["治法", "原文未直接描述脉象，以肝阴素亏、温邪扰之立论。肝阴亏虚，筋脉失养，温邪内陷，引动肝风，故发痉病，见神昏骱齿、瘛疭不定。法当滋养肝阴以荣筋脉，清涤痰热以安神明，属标本兼治之法。脉象虽未明言，病机为阴亏邪扰、风动痰蒙。", []], "17955": ["预后", "热伤津液，脉细口干，细脉主阴液亏耗，热邪灼津，津不上承则口干。脉细为阴血不足之象，热病见之，说明津液已伤，正虚邪恋，故曰难治。此脉细与口干并见，提示热盛伤津、阴液难复之预后不良。", ["细"]], "17956": ["病机", "诒按指出存阴泄热为正法，所云难治，因脉细之故。脉细主阴液亏虚，热邪伤津，阴血不足，脉道不充。虽治法正确，但脉细反映阴伤已深，恢复不易，故难治。此条强调脉细在判断热病预后中的意义，病机为阴液耗损。", ["细"]], "17957": ["病机", "舌干脉数，数脉主热，舌干为津伤。汗为热隔，指热邪郁遏，汗不得发；虽发之亦不得，惟宜甘寒养液。脉数说明热盛，热盛伤津，汗源不足，故不可强发汗。足温后热退乃吉，提示热退津回之兆。病机为热郁津伤，汗不得出。", ["数"]], "17958": ["主病", "风温郁于肺胃，咳而胸满，痰多胁下痛，脉数口干。数脉主热，风温之邪郁于肺胃，肺失宣降则咳而胸满，痰多胁痛；热灼津伤则口干。脉数口干反映风温化热、肺胃热郁之病机，主病为风温犯肺胃。", ["数"]], "17959": ["病机", "脉右大，右脉候肺脾，大脉主邪盛或虚阳外浮。舌黄不渴，呕吐黏痰，神躁语言不清，身热不解，此劳倦内伤，更感湿温之邪。右脉大提示湿温之邪郁于肺脾，气分热盛，痰湿内阻，神躁语言不清为湿浊蒙蔽清窍。须防变端，病机为内伤湿温、痰热蒙窍。", ["大"]], "17960": ["病机", "脉素大，非一时之象，乃体质偏于湿热内蕴。脐中湿液腥臭，为少阴湿热下注外渗。大脉主邪盛，湿热久蕴则脉道宽大。此非虚大，故以六味加减清利间湿热，紧扣「少阴有湿热」之病机。", ["大"]], "17961": ["病机", "脉数而微，数主热，微主虚，为虚热内扰之象。面黑目黄、足寒至膝、皮肤爪甲不仁，皆少阴深入、酒湿与女劳交伤之候。邪深正虚，故脉微；湿热内蒸，故脉数。此虚中夹实之病机。", ["数", "微"]], "17962": ["病机", "原文未出脉象，以「寒袭于肾，气上逆」立论。胀及腰背，为督阳不用、浊阴上逆。鹿茸温通督脉，麝香开泄浊阴，故为君药。此段重在阐发寒邪伤肾、督脉失温之病机，非以脉断证。", []], "17963": ["病机", "脉弦主肝，小腹痛、食后胃脘痛上至咽嗌，为肝火循经乘胃。弦脉应肝，火性上炎，故痛自少腹上逆咽嗌。此厥阴肝火犯阳明胃土之病机，治宜泄厥阴、和阳明，脉症相合。", ["弦"]], "17964": ["主病", "心腹痛而脉弦、色青，弦为肝脉，青为肝色，故直断为肝病。肝气失和，横逆犯心腹，故痛。脉症色三者合参，皆归肝木，此以脉弦定病位在肝，主肝病心腹痛之证。", ["弦"]], "17965": ["病机", "脉虚数，虚为营血不足，数为虚热内动。色白不泽，营血不荣；左胁块杯大，肝家积块；二便自利，病不在腑。此虚中有实、营血不和之病机，故补必兼通，脉虚数正示正虚而兼郁热。", ["虚", "数"]], "17966": ["病机", "大腹右有形为聚，脉大，食入即胀，聚在六腑。大脉主邪气盛实，腑病有形，故脉应之大。此六腑积聚、传化失职之病机，治在六腑，以通降为法，脉大与有形之聚相应。", ["大"]], "17967": ["病机", "脉迟主寒，胃冷则受纳腐熟失职，故腹胀、恶心少食、泄泻。气攻胸胁，为寒浊中阻、胃气上逆。迟脉应脾胃阳虚，此振脾胃之阳之病机，脉迟与胃冷诸症一一相合。", ["迟"]], "17968": ["病机", "脉微迟为阳气不足、阴寒内盛之象。微主阳微，迟主阴盛，故浊阴不化而上攻，见左胁宿痞、腹渐胀大、便溏溺少，皆阳虚不能运化水湿、阴浊凝聚之候。原文断为“浊阴上攻”，治“通阳”，正合微迟所主之阳衰阴逆病机。", ["微", "迟"]], "17969": ["病机", "脉弦为肝木偏旺之象，中满为脾胃受困之候。弦脉主肝，中满属脾，肝气横逆则脾土受克，运化失职而胀满由生。原文直言“病在肝脾”，正是以弦脉定病位在肝、以中满定病位在脾，揭示肝脾不和、木旺克土之病机。", ["弦"]], "17970": ["病机", "原文未出具体脉名，以“脉证合参”立论，重在阐明气结在上、津不运行，遂蒸变浊痰，由无形渐成有形。此非胶固阴药所宜，当遵徐之才“轻可去实”之法。所论病机为气滞津凝、痰浊渐结，脉象仅作合参之凭，故不取脉素。", []], "17971": ["病机", "脉寸大尺小，寸主上焦，尺主下焦，寸大则风火壅盛于上，尺小则下元不足。故见头疼偏左、耳重听、目不明，皆风火升扰清窍之症。原文断为“风火在上”，姑为清解，正以寸大之脉定病位在上、病性属风火，脉症相合。", ["大"]], "17972": ["病机", "脉当迟缓而小促，迟缓为脾肾虚寒之常，小促则示中气衰惫、运化无力。寒湿下注故右膝肿痛而不赤，食少辄呕乃中气之衰已甚。原文以“和养中气为要”，正因脉见迟缓小促，知病本在中气衰败，肿痛为标，故先固中气。", ["缓", "迟", "促"]], "17973": ["病机", "原文未出具体脉名，仅言“脉不得通”，指督脉为风冷所乘、阳气阻遏不通。背脊乃督脉所过，寒凝则恶寒而痛。此以脉道不通说明风冷痹阻、阳气不达之病机，法宜通阳，使督脉阳气宣通则寒痛自解，故脉素从缺。", []], "17974": ["病机", "脉数为阳升之象，合耳鸣、吐痰、天柱与腰膝酸痛、两足常冷，知阴亏于下而阳浮于上。下虚故足冷腰膝酸，阳升故耳鸣吐痰脉数。原文断“阴亏阳升”，法当填补实下，正以数脉非实热，乃虚阳上浮之征，脉症合参自明。", ["数"]], "17975": ["病机", "原文未出具体脉名，以少阳经脉循耳外、走耳中立论，指出是经有风火则耳脓而鸣。此从经络病位推求病机，风火循少阳上扰耳窍，故脓鸣并见，治宜清散。脉象未及，故脉素从缺，主旨仍在阐发少阳风火之病机。", []], "17976": ["病机", "形伟体丰而脉得小缓，小为阳气不足，缓为湿滞不运。原文谓“阳气发泄之人，外似有余，内实不足”，水谷不得阳运，酿湿下注为浊病，已三四年。脉小缓正合内虚湿盛之机，气坠宜升阳，非少壮阴火自灼可比，故主升阳治法而非苦寒。", ["小", "缓"]], "17977": ["病机", "恼怒伤中，湿热乘之，脾气不运，水谷并趋大肠而为泄，腹中微疼。脉窒不和者，气机壅塞、湿热阻滞中焦之象，非虚非寒。原文点明“治在中焦”，脉窒正说明中焦气机不通、湿热内蕴，故以调中化湿为法。", ["窒"]], "17978": ["其他", "此段为作者自注，指出前案中“脉窒”一句不甚明了，属对脉象描述的存疑讨论，并未给出新的脉象或病机判断。故脉象要素为空，主旨归入其他，不作病机推断。", []], "17979": ["病机", "气郁不行，津枯不泽，故饮食少、大便难、形瘦。脉涩为津血亏少、气机郁滞之征，涩而无力正合津枯气郁，非实积可下。原文戒“未可概与通下”，宜养液顺气，说明此涩脉主虚滞而非实闭。", ["涩"]], "17980": ["病机", "下血后大便燥闭，继而自利白滑胶黏、日数十行，形衰脉沉。沉脉主里，形衰而脉沉，说明久伏水谷之湿内困中焦，府病宜通，故以温下法。脉沉与白滑胶黏相应，为湿浊内伏、阳气不运之候。", ["沉"]], "17981": ["病机", "鼻痒心辣、大便下血、形瘦，脉小而数，已经数年。小为阴血不足、形气衰少，数为热，热在大肠迫血下行。脉小数与形瘦下血相应，说明阴亏内热、久病损形，非一时实火，故病程数年。", ["小", "数"]], "17982": ["病机", "原文直言“脉虚细数，阴不足也”。虚细为阴血亏少、脉道不充，数为阴虚生内热。鼠漏未愈而热在大肠，脉证相合，说明久漏伤阴、虚热内扰，属损象而非实热。", ["虚", "细", "数"]], "17983": ["预后", "此段为按语，指出肛门漏即鼠漏，脉证已属损象，故以滋补肝肾为主。原文未另出脉象，只承前段虚细数而言损象，主旨在于判断病情深浅与治法方向，故归预后。", []], "17984": ["病机", "脉虚为气血不足之象，本案形瘦、食少、少腹满、足肿、小便不利，皆脾虚失运、气血亏乏之征。原文断为脾病传心、心传肝、肝复传脾之五脏相贼，脉虚正应脏气亏虚、攻补皆难取效之机，非六腑食气水血成胀之实邪，故宜泄肝和脾缓图。", ["虚"]], "17985": ["病机", "脉细濡数，细为营阴内亏，濡主湿与不足，数示温邪内扰。原文谓产后弥月形凛身热、津津汗出、舌红渴饮，乃营阴亏而冬温袭匿于痰中，相交为患。脉来去靡定，正合温邪挟痰、营卫不谐之机，故治以和阳化温、清降痰气。", ["细", "濡", "数"]], "17986": ["病机", "脉濡空软，濡为湿滞，空软示阴分亏虚、脉道不充。原文载寒热互作、有汗不止、渴饮舌绛、痰吐不爽，断为产后阴亏、冬温挟痰内伏，营卫失谐。脉空软正应营阴本亏而邪伏痰中之虚中夹实，故虑缠绵致阴伤风动，拟和阳益阴化温除痰。", ["濡", "空", "软"]], "17987": ["病机", "脉弦滑数，弦主气机郁滞，滑主痰，数示温邪未清。原文谓寒热已缓而仍漐漐有汗、体痛偏左、咳嗽痰不易出，乃冬温兼挟痰气阻痹肺络之候。弦滑数正合痰气阻络、邪郁化热之机，故当理络化痰、宣通气机。", ["弦", "滑", "数"]], "17988": ["其他", "本段仅列荆芥炭、楂炭、谷芽、陈皮、炙甘草、茯神六味，未载脉象，原文自注此方与脉案不合疑有错误。既无脉可析，亦难据方推病机，故脉象要素从缺，仅存录方药与存疑之文，不作病机推断。", []], "17989": ["病机", "脉象虚弱，虚为营血不足，弱为气衰。原文载经居四月、内热食少、腰酸腹痛膨胀，断为营虚气滞。脉虚弱正应肝脾气血两亏、冲任失养之机，故防其暴下虚波，拟和养肝脾气血，以固胎元。", ["虚", "弱"]], "17990": ["病机", "脉形细数，细主阴血亏少，数主气火内动。原文谓素体亏弱、气火上升，症见心悸、头鸣、咳呛、食少作胀，皆阴亏于下、气火浮扰于上之象。细数之脉正合虚体气火上升之机，故先清肺和胃，恐增寒热。", ["细", "数"]], "17991": ["病机", "两脉濡数无力，濡主湿，数而无力为元气虚馁、虚阳浮动。原文断为脾阳久虚、聚湿生痰、胃气失和，症见足浮、痰多、纳少、无寐，又值疟后营卫失谐、元气益虚。濡数无力正应脾虚湿痰、元气亏乏之机，故拟和养脾胃、安神化痰。", ["濡", "数", "无", "力"]], "17992": ["病机", "脉形濡数，濡主湿、主脾虚，数主热、主动。案中经居五十余日，奔走劳力动络下血，腰酸腹支急、饮食减少，乃冲任营络损伤而兼脾运不健。濡数为虚热扰动、络伤未复之象，故防腹痛暴下，拟和养健脾以固冲任。", ["濡", "数"]], "17993": ["病机", "脉形细数，细为阴血不足，数为虚热内扰。失音半载、咽干口燥、经阻两月，显系阴伤肺热、津亏血少。细数之脉正合阴虚内热之机，故曰恐入损途，示阴损难复、虚劳渐成之虑。", ["细", "数"]], "17994": ["病机", "脉虚细弦，虚细为血虚不足，弦主肝阳偏亢。咳嗽头胀皆减而耳鸣惊惕、中指发麻、痰多食少，乃血虚肝阳化风、风痰上扰之候。脉虚细弦正应血虚风动，故宜静养慎调，防其风阳再扰。", ["虚", "细", "弦"]], "17995": ["病机", "脉形细涩，细主血虚，涩主血行不畅、脾运迟滞。经阻半载、腹痛便溏、耳鸣食少，为血虚脾弱、冲任乏养。细涩之脉示营血亏少而脉道不利，病颇深，损怯可虞，故曰理之不易。", ["细", "涩"]], "17996": ["病机", "脉细弦数，细为体虚，弦主肝气，数主痰热。肝气挟痰上扰，故头痛心悸、痰咳呕恶、腹痛食减，舌黄口干为热象。脉细弦数正合肝郁痰热、久病体虚之机，故恐有痉象，示风动之虞。", ["细", "弦", "数"]], "17997": ["病机", "脉濡主湿、主脾虚。湿热伤脾，便血泄泻、腹膨食减、舌白，皆脾运失健、湿热内蕴之症。濡脉应湿邪困脾、脉道弛缓，故恐增腹满之虚，拟清脾和湿以祛湿运脾。", ["濡"]], "17998": ["病机", "脉形濡细无力，濡主湿、细主虚，无力为气血两亏。产后下血如崩，营伤脾弱，遍体浮肿、舌白便溏、气急鼻衄，乃阴阳两伤、脾肾失运。濡细无力正应虚损湿滞，故防喘塞泄浊虚变。", ["濡", "细"]], "17999": ["病机", "脉形濡细，濡主湿、细主虚。产后月余下血如崩，营伤脾弱，肢体肿胀、气急便溏、咳呛舌白，为脾肺肾三焦皆病、水湿不化。濡细之脉示虚而夹湿，故防喘塞虚波，病机险重。", ["濡", "细"]], "18000": ["病机", "产后去血过多，营伤脾弱，故脉细。细为营血不足、脾虚不运之象，脾弱则水湿不化，见肢体浮肿、食少便溏；水湿上泛犯肺则咳嗽气喘。舌白亦主虚寒湿滞。三焦皆病，喘塞可虞，脉细正示正气已虚而邪湿未化，不可忽视。", ["细"]], "18001": ["病机", "妊躯七月，脉形细濡。细为脾虚营弱，濡主湿胜，脾虚湿胜则水湿泛溢，故腿足肿胀、面浮溲少；湿阻气机、上干于肺则咳嗽头胀，舌白食少亦脾弱湿滞之征。脉细濡正合脾虚湿胜之机，故防骤产虚波。", ["细", "濡"]], "18002": ["病机", "产未满月，瘀尽而白带颇多，少腹痛腰酸，舌白脉细。细脉主营虚，营血亏虚则寒凝气阻，不通则少腹腰痛；寒湿下注则带多；脾弱则食少，肺失所养则咳嗽。脉细紧扣营虚寒凝气阻之机，故防其增重。", ["细"]], "18003": ["病机", "自乳体虚，伏邪留恋，寒热间两日一发，左胁背部作痛，咳嗽食少，脉息小弦。小为体虚，弦主邪郁少阳、气机不畅，故寒热如疟、胁背作痛；体虚邪恋则咳嗽食少。脉小弦正示正虚邪郁、缠绵难解，故曰最淹缠也。", ["弦", "小"]], "18004": ["病机", "身热肢冷，去来无定，微汗或止或不止，脉数左弦，舌白神倦呓语，头疼体痛。数主热，左弦主少阳邪郁，邪兼太少两阳，正邪交争故寒热去来无定；邪郁则肢冷、头疼体痛，神倦呓语为邪扰之兆。脉数弦示邪势未解，恐其内陷。", ["数", "弦"]], "18005": ["病机", "平旦更衣后寒热势缓而脉未静，舌绛苔白，温邪挟湿，蒸中不化。脉未静说明邪势虽减而未尽，湿与温合，蒸腾中焦而不化，故舌绛苔白。病情尚未定著，脉象未识，当从寒热缓而脉未静、舌绛苔白辨为温邪挟湿留恋，故与和解化痰以消息之。", []], "18006": ["病机", "夜来先形寒，逾时而热，后热后得汗而解，脉弦数。弦主少阳，数主热，邪伏少阳阳明，正邪交争故先寒后热、得汗而解，竟有疟状。脉弦数正合邪伏少阳阳明、郁而化热之机，故用柴胡温胆和解枢机、清化痰热。", ["弦", "数"]], "18007": ["病机", "屡屡得汗，热已退解，但脉沉细数，舌绛苔微黄，咳嗽痰不易出，胸胁隐痛。沉细主里虚阴伤，数主余热未清，热退而脉未静，示邪热内伏、肺胃阴伤，炼液成痰则咳痰难出、胸胁隐痛。故与理肺和胃化痰，以视明日动静。", ["沉", "细", "数"]], "18008": ["预后", "原文“漐漐汗出，脉渐和平”，汗出而脉由病脉渐转和缓，是邪退正复、阴阳趋于平衡之象，故曰“渐和平”。此时余邪未尽而胃阴未复，故“只宜和胃养阴”，使神安纳谷。脉和平为向愈之兆，非主病之脉，属预后判断。", ["和平"]], "18009": ["病机", "脉数空弦，数主热，空主阴亏，弦主痰热内郁。原文“汗解之后，心阴内耗，肺胃热邪又留未尽”，故见多梦谵语、舌尖红、谷食不加。数而空为阴伤有热，弦为痰热未清，脉症合参，病机为心阴耗伤、痰热留连肺胃。", ["数", "空", "弦"]], "18010": ["预后", "原文“寝食皆安，脉亦和平”，寝食安而脉和缓，示正气渐复、脏腑功能协调，故断为“扶正安神，一定成则”。脉和平在此非主病，而是疾病向愈、正安邪却的预后佳象，与上段“脉渐和平”同属恢复期脉象。", ["和平"]], "18011": ["病机", "脉数濡，数主热，濡主湿、主阴亏。原文“素体阴亏，烦劳阳伤，冬温乘袭”，身热咳喘、自利烦渴、舌浊，为肺胃热邪挟湿。数濡并见，示热邪未清而阴液已伤、湿浊内蕴，故“深恐正亏邪陷”，当从肺胃清泄。", ["数", "濡"]], "18012": ["死脉", "妊娠八月陡然昏厥，上窍血溢，扬手掷足，咬牙脉乱。脉乱为脉行失序、阴阳乖乱之死候。原文“冬温挟痰，陷入厥阴，肝阳挟胎气上迫，势极危急”，脉乱正应此邪陷厥阴、气血逆乱之危局，故曰“无从著手”，勉与应下。", ["乱"]], "18013": ["病机", "脉弦滑数，弦主肝风，滑主痰，数主热。原文“损胎既下，仍然昏痉晕厥，手臂强直”，为邪痰恶血蒙闭心胞。弦滑数并见，示肝风痰热交炽、内陷心包，故昏痉晕厥不止，正在险津，谨防陡变。", ["弦", "滑", "数"]], "18014": ["病机", "脉滑细如丝，滑主痰，细如丝主正气衰微。原文“面青肢冷，额汗津津，神倦呃忒，痰喘如锯”，为邪热匿于痰中而中气交脱。滑细如丝示痰热未去而元气已竭，故曰“不得不补，然须得补耐补乃幸”，脉症皆见脱象。", ["滑", "细"]], "18015": ["病机", "脉细濡数而伏，细濡主阴伤湿滞，数主热，伏主邪闭。原文“舌绛苔白，气喘耳聋，斑发紫黯，隐约不出肉”，为邪陷膻中、营热内闭。细濡数为阴伤湿热，伏为邪遏不达，故有昏厥立危之势，急宜清营透表。", ["细", "濡", "数", "伏"]], "18016": ["病机", "脉浮不出，为温邪痰热内扰蒙闭，渐入心营之象。邪热内闭，气机不畅，故脉浮而难出；身微热、四肢不温、神蒙耳聋、舌红渴饮、瞀闷呓语、斑发不掀，皆痰热蒙蔽心营、邪不外达之征。脉浮不出反映邪闭气壅，恐陡然昏痉厥闭，故拟清营解表、辛香开泄以冀转机。", ["浮"]], "18017": ["病机", "脉数不出，为阳明邪火极炽，热盛气壅，脉道不畅所致。身热不扬、昏狂叫喊、呓语喃喃、烦渴引饮，皆阳明邪火内炽、上扰神明之候。脉数主热，不出示热闭气机，仍虑昏痉厥闭。再拟清营辛开、甘寒化热，扶过两候方可。", ["数"]], "18018": ["病机", "脉甚细软，为汗后邪去未净而正气先虚之象。夜来汗后昏狂烦热似定、舌色少淡薄，但大便连行、神志倦怠，脉细软主气阴不足、正气亏虚。细为阴血亏少，软为气弱不鼓，故最恐邪去未净而正虚，宜清解和胃安神养阴方。", ["细", "软"]], "18019": ["病机", "脉来细数而寸不出，为太阳邪热入太阳阳明，热盛伤阴、气机不畅之征。泄泻数减、舌红苔黑，示邪热内传、阴分受灼；细数主热伤阴液，寸不出为邪壅上焦。深恐昏厥，乃热盛阴伤、邪陷心包之虑。", ["细", "数"]], "18020": ["病机", "脉数口干，为阳明之邪未净，湿热内蕴之象。热势退缓、舌红苔浊、小溲短赤，皆湿热未清、癃闭州都所致。脉数主热，口干示热伤津液，湿热阻滞下焦，气化不利，故小溲短赤。治当清化湿热，通利州都。", ["数"]], "18021": ["病机", "脉左空弦、右模糊，为痰湿混阻、邪热内蕴之象。空弦主正气内虚而邪气壅滞，模糊示痰湿蒙蔽。身热不扬、膺闷呃忒、面赤如醉、舌红苔白，皆痰湿混阻、邪热苔白之征。其势颇危，因正虚邪实、痰湿壅遏气机。", ["空", "弦"]], "18022": ["病机", "脉数左弦，为阳明之经犹热、少阳之气内亏，湿反化燥之时。大战后肤黄斑透得解，但咽喉微痛、颊车失开、舌绛口干、面油目昏，脉数主热，左弦主少阳亏而邪扰。犹恐泛而复聚，故当清营滋化、理咽除痰，不致再生更张乃吉。", ["数", "弦"]], "18023": ["病机", "脉数左细软、右浮滑，为冬令过暖、温邪蕴伏肺中，呛伤营络之象。数主热，左细软示阴分本亏，右浮滑为痰热壅肺。身热不扬、气逆咳嗽、痰中映红，皆温邪蕴肺、伤及营络之征。恐增喘急，阴分本亏，只宜轻济清泄，慎勿辛温发散。", ["数", "细", "软", "浮滑"]], "18024": ["病机", "脉浮为邪在表，滑数为痰热内盛。劳倦感邪，气痹不宣，故身微热、畏风恶寒、体痛右甚；瞀闷气喘乃痰热壅肺、气机不畅。浮滑数脉提示表邪未解而里热已生，恐厥逆者，热盛动风之兆。", ["浮", "滑", "数"]], "18025": ["预后", "脉细如发，是正气欲脱、气血衰微之象。肝气挟痰塞逆，心脘掣痛、寒颤壮热痉厥，洊至汗出如雨、肤冷如石，语言不出，乃痰邪内伏、肝风鸱张而正气外脱。脉细如发与危候相应，故曰危如朝露。", ["细"]], "18026": ["病机", "脉数不畅，数主热，不畅为痰邪内伏、气机郁滞。冬温九日，身热不扬、神烦瞀闷、舌红苔黄，手腕搐搦，是痰热内伏、肝风欲动。脉数不畅正合痰邪阻滞、热郁不透之机，故恐其复厥。", ["数"]], "18027": ["病机", "脉沉细，沉主里，细为阴伤。高年湿热内盛，冬温深入厥少，形寒身热、面赤戴阳、呕恶舌浊、少腹拘急、气上冲心，乃湿热内陷、阴阳不相顺接。沉细脉示邪入厥阴、正气已衰，其势危笃。", ["沉", "细"]], "18028": ["主病", "脉浮主表，头项强而恶寒，此太阳病也。浮脉为风寒袭表、卫阳浮盛之象，与太阳提纲证相应。病后阴虚，宜兼滋养，是既解表邪又顾阴液，防过汗伤正。", ["浮"]], "18029": ["病机", "脉不通畅，乃湿热肝气内郁、风寒外遏，气血运行受阻。心中懊𢙐不食、目黄、舌绛唇干，是湿热郁蒸、肝气不舒。脉不通畅正合郁遏之机，治当疏达，以畅气机、化湿热。", []], "18030": ["预后", "脉伏，是风寒壅遏、食滞停积、肝气上逆，邪闭气机，脉道不通。寒热昏躁、胸闷脉伏，势将昏痉厥闭，乃邪闭心包、肝风内动之危候。脉伏与闭证相应，故断其重症难治。", ["伏"]], "18031": ["病机", "脉沉数，沉主里，数主热。冬温食滞阻中，暴寒外遏，肢冷身热、烦躁呻吟，是热郁于里、寒束于外，阴阳气不相顺接。沉数脉示里热壅盛而外寒闭遏，其势棘手。", ["沉", "数"]], "18032": ["预后", "产后营虚，温邪乘袭，寒热匝月，咳呛气短，腹膨，脉细，神倦。脉细为营血亏虚、正气不足之象，正虚无力抗邪，故神倦；邪恋日久，气短腹膨，恐正虚邪陷，有邪正两脱之危，故曰至险。", ["细"]], "18033": ["病机", "冬温九日，形凛身热，脉细数，舌绛苔白。细为阴亏，数为热盛，阴亏不能运泄温邪，邪热内郁，故身热；形凛为阳郁不达。舌绛苔白示热入营分而气分未罢，恐邪陷昏愦。", ["细", "数"]], "18034": ["病机", "身热夜重，自利渴饮，舌绛苔黄，脉细，呕恶不食。脉细为阴亏之体，冬温内伏，邪热伤阴，夜热加重；热迫肠道则自利，渴饮；胃气上逆则呕恶不食。阴亏邪伏，防其昏陷。", ["细"]], "18035": ["病机", "身热旬余，微汗不解，脉细数不出，舌绛苔黄，渴饮便闭。脉细数为阴亏热盛，数而不出示邪热内郁、气机不畅；温邪夹食，腑气不通，故便闭渴饮。邪无外达之机，恐其内陷转重。", ["细", "数"]], "18036": ["预后", "冬温八日，瞀闷脉伏，邪食并重。脉伏为邪气深闭、阳气郁遏不达，邪食壅阻气机，神识瞀闷，正虚无力鼓邪外出，故脉伏。邪无出路，恐其内陷，病情危重。", ["伏"]], "18037": ["病机", "热退不净，咳呛呕吐，脉弦而数，寐则呓语。弦为肝胆之脉，数为热象，肝胆之阳挟温邪上升，木火刑金则咳呛，犯胃则呕吐，扰及心神则寐中呓语。脉症相合，主肝胆阳升挟邪。", ["弦", "数"]], "18038": ["病机", "身热不扬，遍体浮肿，脉紧，舌黄口干，咽哽胸闷。紧脉主寒主痛，严寒外遏，冬温内伏，肺气不清达，通调失职，水湿泛溢则浮肿；邪郁气壅则咽哽胸闷。肺闭水停，最恐喘急。", ["紧"]], "18039": ["病机", "身热去来靡定，得汗解而旋覆燥渴引饮，舌白中浊，脉濡数，不食不寐。濡为湿象，数为热，暑风湿热混蒸阳明太阳，湿郁热蒸则身热起伏、汗出复热；湿阻中焦则不食，热扰则不寐。恐里走转疟。", ["濡", "数"]], "18040": ["病机", "脉数软，数主热，软为不足，暑热蕴伏而正气已馁。夜热退不净、神烦无寐、舌干微黄，皆暑热内扰、肺胃津伤之象。脉数软说明热未清而正已伤，故虑复热，治从肺胃达泄，使伏邪外透。", ["数", "软"]], "18041": ["病机", "脉数不畅，数主热，不畅为邪郁不达。昏谵鼻衄、烦渴引饮、舌红苔白、小溲短赤，乃暑热内陷、肺胃邪火鸱张，热伤营络则衄，扰神则谵。脉数不畅示邪热壅遏，故恐阴伤风动，拟清解达泄。", ["数"]], "18042": ["病机", "脉细数不出，细为阴伤，数为热炽，不出者热伏营分、脉道不畅。鼻衄盈盏、舌红苔黄、烦渴彻夜无寐，暑热深伏阳明营分，迫血妄行、耗灼阴液。脉细数不出正合热迫阴伤之机，故当清营滋泄。", ["细", "数"]], "18043": ["预后", "原文未识脉名，但言「症阳脉阴」，症见热甚神昏、平旦热退不净，似疟未准，而脉反阴象，阳症得阴脉，为正不胜邪之兆。故深恐转虚迅速，颇难立法，拟清气热和胃阴以扶正达邪。", []], "18044": ["病机", "脉象模糊，非指具体脉形，乃脉气不清、正虚邪滞之象。心中甚热、额热不退、舌心剥落、口苦吞酸，为阳明湿热不化、心肝气火内盛，阳亢阴亏。脉模糊示正气不足、邪未透达，故须耐性调扶正养阴和胃安神。", []], "18045": ["病机", "脉象稍出，左弦右空。左弦为肝木偏旺，右空为脾胃气弱。身凉额不热、舌苔腻白、烦渴渐减，暑湿未楚而正渐弱。脉左弦右空示邪退正虚、肝脾不调，故虑散而复聚，宜未雨绸缪，扶正化湿。", ["弦", "空"]], "18046": ["病机", "脉左弦右数，左弦主肝胆气机不畅，右数主阳明热盛。身热至晓退解、舌红苔白，暑湿伏于阳明而为瘅疟。脉弦数示邪郁少阳阳明、热未清透，故扶正安神、化痰清热，使邪从疟解。", ["弦", "数"]], "18047": ["预后", "疟得汗解而脉仍弦数，弦主少阳，数主热，示余邪未净、伏热尚存。脉不随症减，故疑欲变日至疟。仍与扶正养阴、化痰和胃，以清余热、和枢机，防其再发。", ["弦", "数"]], "18048": ["病机", "脉数主热，空弦示阴分已耗而邪热未净。原文谓\"热甚而长退时，汗少口干，舌红\"，热退不尽则肺胃之邪尚蕴；数而空弦，是阳热灼阴、心肾之阴已耗之象。故以壮水制阳光、咸苦入阴为急，脉象正说明邪恋阴伤之病机。", ["数", "空", "弦"]], "18049": ["病机", "脉数不畅，数主热，不畅示湿阻气机。原文\"忽凉忽热，汗出不彻，舌转浊白\"，正是热蒸湿蕴、湿遏热伏之候。湿浊内蕴则脉道不利，故数而不畅；热为湿遏则寒热不定、汗出不彻。治以清滋养阴兼渗三焦分利，紧扣湿蕴热蒸之机。", ["数"]], "18050": ["病机", "原文以脉静、脉大辨身和身热：脉大则身热，是热自里发之征。值暑湿交蒸、病前夺精，三候寒热不定，脉大示邪热鸱张而阴精先亏，故最易液涸风动。脉静则热退身和，脉大则热盛，二者对举，正说明里热伤阴、动风之险。", ["大"]], "18051": ["病机", "热尽退而脉仍数，额微热、口苦耳聋，属少阳阳明见症。原文谓\"暑湿未能尽化，而阴气孤绝，阳气独发\"，脉数正是阳气独发、阴不制阳之象。邪退而脉数不减，说明余热未清、阴气已伤，故以清气热养胃阴为治。", ["数"]], "18052": ["病机", "原文未识脉名，仅言\"脉不数而少纳，四肢清凉\"。少阴脉循喉咙挟舌本，暑湿清解后邪之流弊未楚，故咽痛嗌干；脉不数示热势已减，少纳、四肢清凉则少阴本虚、阳气不布。脉症合参，主少阴里虚、余邪未净之病机。", []], "18053": ["病机", "脉数右大，数主热，右大应肺胃。表热已解而咽哽咳呛痰稠，原文断为\"少阴本亏，真阳上燔\"。右脉大示虚阳上浮、热壅肺系，非实热可比；少阴亏于下则真阳不藏而上燔，故脉数大而症见咽阻痰稠，治以咸苦滋救。", ["数", "大"]], "18054": ["病机", "热不复来、利亦减缓，而脉右甚数，右候肺胃。舌本绛苔花，示余热未清、阴液已亏。脉数偏右，说明肺胃余热未净，心肾之阴颇亏，故尚须清肺和胃、滋养心肾。脉象与舌症相合，主邪去未尽、正阴两伤之病机。", ["数"]], "18055": ["病机", "脉细软数，细软为虚，数而不洪为阴亏有热。原文\"倦怠不嗜食，寤寐纷纭\"，皆邪去正虚、心阴内亏之故。细软示气血不足，数示虚热内扰心神，故寤寐纷纭；脾运不健则倦怠少食。脉症相印，主心阴内亏、脾胃未复之病机。", ["细", "软", "数"]], "18056": ["病机", "原文未出具体脉名，仅言「形神色脉，悉属转虚」，是四诊合参而断为虚象。形神与色脉俱见退象，说明正气日削、阴分耗损，故立「必须扶正养阴」之法。脉虽未详，其转虚之势已寓于形色之中，主正虚阴亏之病机，非实邪壅盛之候。", []], "18057": ["病机", "「脉数右大」，数主热，右大应肺胃气分。原文并见小便、寤寐不安、口干舌燥、背脊轰热，断为「心肾内亏，阳亢阴虚」。数而大者，非实火鼓动，乃阴不制阳、虚阳上浮之象，故治以摄阴潜阳，使浮阳归宅。", ["数", "大"]], "18058": ["病机", "「脉空数，两关独大尺短」，空数为阴液告涸而邪热未息，两关大主胃中邪热内蒸，尺短则下元阴分已亏。合舌绛边碎、口糜气秽、咽哽塞，正合「胃中邪热内蒸，阴液日渐告涸」，故虑毒气内陷、胃败不食，法取彻热救阴。", ["空", "数", "大", "短"]], "18059": ["病机", "「脉数」而见平旦潮热、燥渴饮、胸痞气粗、口糜气秽、鼻痒舌干，数主热盛，热在肺胃气分，灼耗津液。原文断为「肺胃蕴热，阴液内涸之象」，潮热有定时、燥渴气粗皆热壅肺胃之征，故虽用喻氏对之方，仍恐热势猖狂难制。", ["数"]], "18060": ["预后", "「脉数无力」，数主邪热，无力则正气不能振托。连进苦泄滋阴而津液不回、神识模糊，是「邪热匿于痰中，蒙闭心营」。数而无力正示正虚邪恋、托邪无力，故断「明日三候陡然昏厥」，属危候预后之论，非单纯言病机。", ["数", "无"]], "18061": ["兼症", "「脉右弦数」，右候肺胃，弦主痰饮、数主热，是痰热阻于气分。原文夜来微汗、神醒倦怠懒言、唇干、身热暂解，而「痰邪终未能出」，脉仍弦数即邪未尽之验。治法清营化痰，正合脉症，本条重在兼症与转归之观察。", ["弦", "数"]], "18062": ["病机", "「渴饮脉数」，数主邪火，渴饮为热灼津伤。原文更衣不畅、胃中津液大亏，断「邪火之势未衰」，数脉正是火未衰之据。热盛阴亏则虑风动，故此时「滋清熄风之外，无他道」，脉数在此标示邪火未解、津亏将动风之病机。", ["数"]], "18063": ["病机", "原文未出具体脉名，只言「脉象稍逊」，即较前略减而未和。寤言不寐、邪热逗留不去，正气日渐消磨，脉逊正是正虚邪恋之征。所议「清阴中之热，和胆胃之热」，紧扣热留阴分、胆胃不和之病机，脉象稍逊示病势未深而正已伤。", []], "18064": ["病机", "脉软少神，是阴液亏耗、正气不足之象，非热退即安。原文热不复发虽属转机，然更衣怯力、口干舌蹇，显系阴液颇亏而伏热不清，脉软少神正应此虚象，故怕其骤虚、口疳糜烂，治当滋阴和胃以熄余焰。", ["软"]], "18065": ["病机", "脉形虽软而病情未减，说明脉软非邪退之征，乃阴气难成易亏之候。口糜不除、胃中热气上升，是余焰未熄；脉软正反映阴液不足、正气已馁，故仍宗前法滋阴清化、和胃生津，不可因脉软而误认向愈。", ["软"]], "18066": ["病机", "夜作潮热、热时神蒙，脉形仍数且翻覆不已，数脉主热，说明余邪留恋未清，伏热内扰。潮热神蒙为邪正交争之象，脉数不退则邪势未衰，故拟清骨散搜剔余邪，佐清胃以除内热。", ["数"]], "18067": ["病机", "脉数主热，左关弦、右关大，弦为少阳之象，大为阳明之征，故断邪在阳明而兼涉少阳。蒸蒸潮热莫往莫来，正合阳明热盛；病久阴液已涸，数脉又示热灼阴伤，故不可仅事和解，当清滋化热、少佐宣达。", ["数", "弦", "大"]], "18068": ["病机", "潮热两度退而不尽，渴饮舌干，脉弦数。数脉主热，弦脉主郁主少阳，说明余热未清而邪留少阳阳明之间，阴液已伤。故暂停滋腻之品，独取阳明，以清泄里热为要，防滋腻碍邪。", ["弦", "数"]], "18069": ["病机", "漐漐汗出、发白疹，似伏邪外达，然神倦脉软、口秽舌干，软脉示正气已虚，邪热未去而正不胜邪。故最恐陡然转虚，成败未卜，治用和胃养阴、扶正化邪，标本兼顾。", ["软"]], "18070": ["病机", "热退则脉小缓，热来则数大，此邪之聚散所致。小缓为邪退正安之象，数大为热邪聚盛之征，舌苔稍润、渴饮溺赤、斑发未艾，说明余邪尚在气分营分之间，故以清滋解泄为一定成则，继前法而进。", ["小", "缓", "数", "大"]], "18071": ["病机", "身凉脉静，较昨日为安，然原文谓其邪若有未净者，是脉静身凉未必邪尽，恐余邪潜伏。故仍以养阴和胃为主，清泄少阳为佐，既顾护已伤之阴，又防余邪复聚，属瘥后调理、防其复燃之旨。", []], "18072": ["病机", "脉数关大，数主热盛，大主邪实，关候中焦，结合舌红苔黄、渴饮溲赤、不更衣六日，显系阳明热结未清。虽未至腑实，然热势鸱张，故脉数关大。便通后舌淡脉静方为热退之征，此脉实为阳明热盛之据。", ["数", "大"]], "18073": ["病机", "脉芤涩，芤主血虚，涩主血瘀，湿温热毒深伤阳明，营血沸腾，遍体红紫蓝斑、齿衄成流，血热妄行而阴血耗伤，故脉芤涩。此热毒燔灼营血，血溢脉外之危候。", ["芤", "涩"]], "18074": ["病机", "脉沉滑数，沉主里，滑主痰，数主热，暑风湿热夹痰食交蒸，邪结膜膈，渐入心营，故神志昏蒙、唇肿舌强。沉滑数示邪实内结、痰热壅盛，为内陷心营之兆。", ["沉", "滑", "数"]], "18075": ["预后", "湿温疫邪九日，脉伏而神呆、斑点模糊，伏脉主邪气内闭，正气不能外达，疫毒深陷营血，不能透发，故见内陷之象，其势棘手，预后不良。", ["伏"]], "18076": ["病机", "退而复热，脉芤舌绛，芤主阴血不足，舌绛为热入营血，阴阳邪复伏，正虚邪恋，若两候不解，势必内陷风动。脉芤示阴伤，热伏营血，有动风之虞。", ["芤"]], "18077": ["病机", "脉数不畅，数主热，不畅为湿阻气机，暑湿热三气蒸蕴阳明太阳，壮热气喘、头汗如蒸笼水，热为湿遏，不得宣畅，恐其昏厥，示湿热蒙蔽清窍之机。", ["数"]], "18078": ["病机", "脉数模糊，数主热，模糊为湿浊蒙蔽，暑湿热三气交蒸，产后营虚，热甚生风，液亏成痉，故神志恍惚、手肢搐搦。脉数模糊示热盛而正虚，湿浊未清，肝风内动。", ["数"]], "18079": ["病机", "脉右软左弦，右软主阳明湿滞，左弦主少阳郁热，身热不扬、汗出、目赤面垢、呕恶吞酸，少阳阳明合病。软为湿困，弦为热郁，疹点透发，邪有外达之机。", ["软", "弦"]], "18080": ["病机", "脉软为阳气衰微，尺空乃肾阳下竭，与面赤戴阳、肢冷自汗并见，显系暑湿内闭、阴浊上干而阳气外脱之候。软脉不任重按，尺部空豁，正是下元虚惫、虚阳上浮之征，故主生脉八味及白通汤回阳摄纳。", ["软", "空"]], "18081": ["预后", "服白通汤后脉得微续，是阳气渐回之兆。微脉本主阳衰，今由无脉而微续，说明药力已效，生机尚存，故可议继进。此条以脉象变化判断预后转归，非单纯主病。", ["微"]], "18082": ["预后", "疟来呃忒烦冤、瞀闷躁扰，退则汗出肤冷神惫，脉微为正气虚极、不能敌邪之象。微脉主阳微欲绝，与躁扰汗出并见，恐有虚脱之变，故曰若今夕再来恐其虚脱，姑与摄纳以冀万一。", ["微"]], "18083": ["治法", "本条为方治，非脉象专论。生脉散加熟地、牡蛎、茯神、乌梅肉，乃针对气阴两伤、虚阳浮越而设，取敛阴摄阳、宁神固脱之意。原文未出脉象，故脉素从缺，主旨属治法。", []], "18084": ["病机", "脉细而数，细为阴血亏少，数为热象，合之温湿交蒸、身热有汗不解、腹膨满胁、腹泄、全不思谷，显系肝肾内伤、湿热壅遏中焦之候。细数并见，正虚与邪热交织，故曰大势棘手，勉拟培中泄热。", ["细", "数"]], "18085": ["病机", "脉软主气虚，暑湿伤气则脉道弛软不任，与体倦并见，说明暑湿耗伤中气、清阳不升。软脉非虚寒之软，乃湿困气馁之象，故以暑湿伤气为病机，治当清暑化湿、益气和中。", ["软"]], "18086": ["兼症", "产后腹痛偏右、虚中有瘀，身热咳呛音哑而脉数，数为热象，此热非纯外感，乃瘀血内阻、虚热上炎兼夹客感所致。脉数提示邪热鸱张，故防其内陷昏愦，属女科虚实夹杂之候。", ["数"]], "18087": ["病机", "暑湿热三气交蒸，身热脉数、烦渴溲赤，匝月不已，数脉主热盛，与三气交蒸之候相应，说明湿热壅遏气分、久稽不解。脉数不退，恐其热势转重，故曰恐其转重，当以清暑化湿为治。", ["数"]], "18088": ["病机", "脉濡主湿，暑湿伏邪内蕴，阴分本亏，舌红苔黄、烦渴咳呛、恶心鼻衄，为邪火炽盛、湿阻气机之象。濡脉示湿邪偏盛而正气已伤，故寒热不能成疟，恐邪内陷风动。", ["濡"]], "18089": ["预后", "脉微为阳气衰微之征，阳微湿胜之体，夏病缠绵未复，寒热复作、二便失司、脘痞呃忒、自汗鼻冷、神疲，皆中下无阳、阴霾痰浊上干之候。形神色脉无一不脱，脉微示正气将脱，预后堪忧。", ["微"]], "18090": ["预后", "失血损体，伏邪晚发，热解肢冷、汗出呃忒，脉微细为气血两虚、阳气衰微之象。微细脉示正气不支，虚波不测，最防其脱，故预后险恶。", ["微", "细"]], "18091": ["病机", "伏邪晚发，似疟似痢，舌绛苔干，脉细数。细为阴伤，数为热炽，阴伤已极，正气不支，夜多烦躁，恐致虚脱。脉细数示阴亏热伏，故扶正救阴泄热为一定成则。", ["细", "数"]], "18092": ["病机", "体倦、肤黄、足软、舌白，脉迟而空。迟为阳微，空为脉道不充，中下阳微，暑湿内困，阳气不能温运，故见诸症。脉迟而空示阳虚湿困，当扶阳理湿。", ["迟", "空"]], "18093": ["病机", "小产之后下血过多，暑湿热邪内蕴，遍体浮肿、微热咳呛、头胀口干、舌苔白腻，脉数。数为热，虚中有热，恐成蓐痨。脉数示热邪内蕴而阴血已亏。", ["数"]], "18094": ["病机", "伏邪初秋即发，类乎瘅疟，入冬热不了了，口淡食少、干咳气短，脉空数，舌绛苔白。空为正气受伐，数为虚热仍伏肺胃。脉空数示正虚热伏，只宜轻剂化解，不可恣意疏散。", ["空", "数"]], "18095": ["预后", "伏邪恰发霜降，表热不壮，心中烦灼如焚，舌绛渴饮，脉空数。空为阴液被劫，数为虚热内炽，势将风动昏厥。脉空数示阴亏热盛，非人力所能为，预后凶险。", ["空", "数"]], "18096": ["病机", "脉象濡数，濡主湿、数主热，为湿热内蕴之象。原文谓伏邪发在秋初，身热屡汗不解、闷烦自汗，舌绛苔白，乃邪蕴少阳阳明，湿热交蒸，正气渐虚。脉濡数正合湿热郁阻、正虚邪恋之机，故恐其变痢，因湿热下迫大肠可致下利。", ["濡", "数"]], "18097": ["病机", "原文未识脉名，仅言「脉不流畅」，指脉气郁滞不畅。表热不壮、痞胀不食、少腹隐隐攻痛、舌苔黄浊，乃阳邪陷入阴经，肺气不通，气机壅塞所致。脉不流畅正反映邪阻气滞、升降失司之病机，故曰「颇为费手」，治仿仲景法兼佐以浊泄浊。", []], "18098": ["病机", "脉弦细数，弦主邪郁少阳，细主阴伤，数主热。伏邪淹缠半月，形凛身热、日晡甚而平旦减，舌黄无苔，乃烦劳素虚之体，阳伤阴亦伤，邪难外达。弦细数正示邪郁阴伤、虚热内扰之机，故叹「复脉法如何」，言其正虚难以送邪外出。", ["弦", "细", "数"]], "18099": ["治法", "此段为方药加减，非论脉象。复脉散去人参、麻仁，加丹皮，乃针对前案脉弦细数、阴伤邪郁之体而设。去人参恐其助邪，去麻仁避其滑泄，加丹皮以清透阴分伏热。属治法调整，示养阴透邪、凉血泄热之意。", []], "18100": ["病机", "脉空数，空主阴血亏虚，数主热。伏邪两月，胸腹灼热不退，复寒热、瘕泄、痰嗽气逆、嘈杂如饥、寤言不寐，舌绛干苔黄腻，乃酒客湿热蕴蓄中焦，病久正虚邪痹。脉空数正示阴伤热扰、正虚邪恋之机，故恐阴阳风动，议泻心法。", ["空", "数"]], "18101": ["预后", "脉数空软，数主热，空软主正气虚衰。胸胀闷热、咳嗽痰塞、大便频泄，邪踞中下二焦，而脉反空软，舌伸发抖，乃下真自空、虚波陡起之兆。脉症相悖，正虚不能胜邪，故曰「不敢不虑」，示预后堪忧。", ["数", "空", "软"]], "18102": ["预后", "脉空大滑数，空大主阴伤正虚，滑数主痰热内盛。伏邪廿四日，肤黄、邪蒙语杂、咳喘痰血、舌苔浊干、大便仍泄，乃五脏之阴皆伤，痰热蒙蔽心营，肺胃内闭外脱。脉空大滑数正示正虚邪盛、痰热鸱张之危候，故曰「危如朝露」。", ["空", "大", "滑", "数"]], "18103": ["预后", "原文未识脉名，仅言「右脉如丝」，丝脉即细脉之甚，主正气衰微、血脉不充。伏邪晚发，湿热内蒸，腹痛胁胀、肤黄舌黑，而右脉如丝，乃邪结正脱之象。脉细如丝示正气将竭，不能抗邪，故曰「至险至险」。", ["细"]], "18104": ["病机", "左脉弦数，弦为肝旺，数为热，乃辛温伤阴后肝升太过之象；右脉软细，软细主虚，示肺虚降令不及。肝升太过则肺降无权，故形削色痿虽渐回而未复。脉象与症相应，揭示肝肺升降失司、阴伤未复之病机。", ["弦", "数", "软", "细"]], "18105": ["病机", "阴疟淹缠百日，形神色脉皆空虚，虚空之脉主正气大亏。项背筋惕乃冲督空虚、筋脉失养之征，故断病在冲督。脉空虚与形神俱衰相应，说明久疟耗伤精血，奇经失充，恐因循成怯。", ["虚", "空"]], "18106": ["病机", "三疟邪伏在阴，脉迟主阳气不足、阴寒内盛。便溏为脾阳不振，脉迟与便溏并见，说明脾肾之阳已衰，温运无力。故治法当先温阳截疟，脉迟正是阳虚可温之据。", ["迟"]], "18107": ["病机", "左脉弦主风与肝，右脉滑主痰湿，弦滑并见，合舌绛、肤黄、遍身瘙痒，正是湿热风痰混伏扰乱之象。疟久正消而邪未净，脉弦滑示邪实未去，故须疏风涤痰以护正，否则正难支持。", ["弦", "滑"]], "18108": ["病机", "疟发三阴缠淹四月，脉细数，细主阴血亏虚，数主邪热未清。胸闷舌红、神倦形削，正虚而邪又未达，细数之脉正示正虚邪恋、阴伤有热，故理之不易，攻补两难。", ["细", "数"]], "18109": ["病机", "疟疾几及三月，形神色脉皆虚，虚脉主气血阴阳俱损。久疟耗伤正气，脉虚与形神俱衰相应，说明正不胜邪。若再淹缠反复，则骤然脱厥可虞，脉虚在此示预后险恶。", ["虚"]], "18110": ["病机", "体盛而脉小，小主阳气虚衰，形盛脉小为脉症不符之象。舌如傅粉、胸痞脘闷，示暑风湿热之邪未离膜原，阳气虚而邪内伏，故恐疟来昏厥，脉小正提示正虚邪陷之危。", ["小"]], "18111": ["病机", "中秋伏邪疟后元气未恢，脉细数，细主阴血不足，数主虚热内扰。形神削夺、上咳下泻，肺脾同病，土不生金。细数之脉示气阴两伤而虚热未清，故恐成疟痨，预后可虑。", ["细", "数"]], "18112": ["病机", "疟久延至冬半，伏邪深踞左胁结痞，脉弦细数。弦为肝邪未解、疟母成形，细为阴血耗损，数为伏热内扰。形神削夺、面色㿠白，正是正虚不敌、邪留不去之象，故原文叹“洵可畏也”，脉示正虚邪恋、疟母已成之病机。", ["弦", "细", "数"]], "18113": ["治法", "疟久不了了，咳呛而脉数，数为热，咳呛属肺金受灼、肺阴不足，虚热内扰故脉数。原文径言“当补肺阴”，脉数在此标示肺阴亏虚、余热未清之病机，故治法以滋养肺阴为要，非实热可攻。", ["数"]], "18114": ["病机", "伏邪为痢缠绵五旬，脉细数，细为阴血亏耗、正气已虚，数为暑湿余热未净。唇红舌白、形削色㿠，是暑去湿存而中阳式微，虚象毕露。脉细数正合正虚邪恋、阳衰之机，故原文急呼“急急扶正，惟恐不及”。", ["细", "数"]], "18115": ["病机", "身热腹痛、块攻下痢频频，而脉微神倦。脉微为阳气衰微、正气不守，与频频下痢并见，说明邪从下陷、正虚不能托邪。原文谓“颇为棘手”，勉拟逆流挽舟法，正是据脉微神倦断其邪陷正溃之危局。", ["微"]], "18116": ["病机", "伏邪疟后不自慎守，里陷为痢，形脉皆虚，饮食减少。脉虚与形虚相应，示正气内溃、脾胃衰败，邪陷于里而中气无权。原文以“将何恃而不恐”发问，正说明脉虚为根本已亏、正不胜邪之病机，预后可虑。", ["虚"]], "18117": ["预后", "素阴亏营热、肝气抑郁，半产后寒热变痢，痢无休息，骨瘦如豺，脉微如丝，舌光如镜。脉微如丝为阳气外脱、阴液干涸，营卫分争，正虚已极。原文断为“阴液干涸、阳气外脱”，又逢秋冬之交，故历历危惧，属危重之候。", ["微"]], "18118": ["病机", "由疟变痢缠绵休息，腹微痛、面黄、舌苔白腻，脉左关弦右濡。左关弦为肝盛气郁，右濡为脾虚湿困，合下痢红白相兼、大便不实，正合原文“气分有湿，血分有热，脾虚肝盛”之论，脉象与湿暑伤中之机相印。", ["弦", "濡"]], "18119": ["妇人", "女久痢命门酸坠，脉细数，舌红，腹痛后重。细为阴亏，数为热扰，阴亏气陷而暑湿黏著不去，故见后重腹痛。原文虑“妨胎之险”，脉细数示阴亏热蕴、胎元失养，为妇人久痢伤胎之病机。", ["细", "数"]], "18120": ["病机", "脉细弦数，细为阴亏，弦主肝郁，数因湿热内蒸。原文谓“阴亏肝郁之体，湿热内蒸”，故见少阴咽哽、遍体浮肿、肤黄、舌浊。细弦数相合，示阴液不足而肝气郁滞，湿热蕴蒸，病机在阴虚肝郁兼湿热，非单纯表证。", ["细", "弦", "数"]], "18121": ["病机", "脉芤涩，芤主血虚，涩为阴亏血少、脉道不利。原文言“心阴过亏，暗吸肾真，水不涵木”，故见恍惚惊悸、眩晕怔忡、形疲色不华。芤涩并见，说明心阴亏耗、肾真被吸、肝木失涵，虚风内动，病本在阴血亏虚。", ["芤", "涩"]], "18122": ["病机", "色脉皆虚，虚脉主气血阴阳俱不足。原文述心营内耗、孤阳上冒、肝逆犯胃、表阳外薄，故少寐气短似喘、面赤足冷、吞酸妒谷、汗出津津。脉虚与色虚并见，说明正虚为本，虚阳上浮、肝胃不和为标，非补不可。", ["虚"]], "18123": ["病机", "脉细左弦右涩，细主营虚水亏，左弦为肝木失涵，右涩示营血不足、脉道不畅。原文谓“营虚水亏，肝木失涵，虚风内动”，故见症若此。细弦涩并见，说明肝肾阴亏、虚风内动，治当养肝肾之阴，佐以滋镇熄风。", ["细", "弦", "涩"]], "18124": ["病机", "脉数弦滑，数主热，弦主肝阳，滑主痰。原文谓“肝阳挟痰火上升无制”，故头痛满蒙、右半尤甚、鼻塞涕浊。数弦滑相合，示肝阳化火、痰火上升，治当清降化痰；若用风药升散，则助其升逆，故难忍。", ["数", "弦", "滑"]], "18125": ["病机", "脉涩右空左细，涩主血少，空为营阴亏虚，细主阴血不足。原文谓“心肾阴亏，肝木失涵，风阳窃动”，故四肢麻木、形容不泽。涩空细并见，说明心肾阴亏、肝木失养、虚风内动，治当乙癸同源，滋水涵木。", ["涩", "空", "细"]], "18126": ["病机", "原文未识脉名，仅言“脉象病情并无进退”，而终岁哓哓，心阴暗耗，阳岂能潜。脉象无进退，说明病机未变，心阴耗损、虚阳不潜为其本。今当秋冬，自宜养阴，不必炼真说假，示病机在阴亏阳浮，治重养阴潜阳。", []], "18127": ["病机", "脉形细软，两尺微数，细软主虚，微数示阴亏火动。原文谓“心肾之火不靖，脾阳不运，肝气升逆，肺失肃降”，故面黄肌瘦、舌起刺。细软微数并见，说明本虚标实，心肾火动、脾阳不运、肝肺气逆，治宜运中固下。", ["细", "软", "数"]], "18128": ["病机", "原文谓「中下阳微，痰气上泛，神惫脉缓」。中下焦阳气衰微，不能温运，痰气因而上逆，蒙蔽清阳，故神疲体惫。脉缓非平人之和缓，乃阳气不振、鼓动无力之象，缓而无力正合阳微痰泛之机，主中下阳虚、痰浊上泛之证。", ["缓"]], "18129": ["病机", "原文「午后呛甚痰稠，脉弦滑数，是肺火上浮」。弦主肝火，滑主痰盛，数主热炽，三脉合见，示痰火内蕴、肺火上炎。午后阳盛之时呛甚痰稠，正与弦滑数相应，故以轻剂清苦降之，使肺火下行、痰热得清。", ["弦", "滑", "数"]], "18130": ["病机", "原文「饮食之后，舌蹇，言语不清，脉弦数，是水谷之气挟痰火上升」。弦为肝旺，数为火盛，饮食后水谷之气不得下行，反挟痰火上升，壅塞舌本清窍，故舌蹇言謇。脉弦数正示痰火内盛、肝胃气逆之机，法宜养胃兼治痰火。", ["弦", "数"]], "18131": ["病机", "原文「中下阳微，阴浊寒痰上升，呕吐涎沫，心中嘈杂，脉濡细舌白」。濡细为阳气衰微、湿浊内停之脉，舌白亦主寒。中下阳微则阴浊寒痰上逆，故呕吐涎沫、嘈杂。值冬至阴阳交潜，恐阳不胜阴而不相维系，故加附子温阳以固根本。", ["濡", "细"]], "18132": ["病机", "原文「脉如蛇行，遍体漉漉有声，胸膺瞀闷，咳呛不爽」，断为「痰饮水湿，凝结经络」。脉如蛇行，形容脉形曲折流利不定，非正常脉象，反映痰湿流窜经络、气血运行不畅。漉漉有声、胸闷咳呛皆水湿内停之征，补攻两难，故云极难取效。", []], "18133": ["预后", "原文「脉有歇止，气喘咳嗽，呃忒频频」，断为「阴亏内热，肝升肺不降」。歇止脉示气血运行不续，高年坠伤后阴亏内热，肝升太过而肺降不及，气机上逆，故喘咳呃忒。最恐呃逆不止而致痰塞气厥，属危重之候，故列于预后以警。", ["歇止"]], "18134": ["病机", "原文「病后邪伏不清，元不复反，烦劳以致肝气逆胃，不饥不便，色脉皆虚」。脉虚示元气未复，正虚为本；烦劳引动肝气上逆犯胃，胃失和降，故不饥不便。色脉皆虚而谷食不进，则生化无源，正虚难复，故有「何恃而不恐」之叹。", ["虚"]], "18135": ["主病", "原文「胃气受寒，脘痛呕吐，脉迟而滑，老年阳衰所致」。迟主寒、主阳衰，滑主痰饮内停。老年阳气式微，胃气受寒，寒凝气滞则脘痛，胃气上逆则呕吐，寒痰内聚故脉滑。迟滑并见，正合阳虚寒痰犯胃之脘痛呕吐证。", ["迟", "滑"]], "18136": ["病机", "脉弦为肝气偏旺，左小则左脉不足，合面赤足冷、舌绛苔白，显系肝气贯膈入胃、肾病善胀。弦主肝木乘土，小示阴分不足，故见腰痛腹胀、呕吐酸水。原文明言「肝气贯膈入胃，肾病善胀使然」，脉象与肝胃不和、肾不化气之病机相应，治以苦辛泄降、咸凉内沁。", ["弦", "小"]], "18137": ["病机", "脉空数为攻药伤中、元气受戕之象。空脉主气血虚衰、脉道不充，数则示虚性亢奋，肝木乘脾。原文谓「形神削夺，脉空数，左胁痛引及背」，正合气营并亏、脾虚肝乘之机。空数非实热，乃元气耗散、营血不足所致，故缠绵难复，治当和脾养肝。", ["空", "数"]], "18138": ["病机", "脉芤主营血虚而脉道中空，涩主血行不畅、络脉瘀滞。原文「虚里穴痛，引及胸胁，饮食阻咽，脉芤涩」，明示肝气抑郁、营络空虚。芤涩并见，为营虚络涩之候，故未老先衰，恐成膈症。辛燥开气更伤营，清凉凝滞益阻络，皆与病左，脉象紧扣营络空虚之病机。", ["芤", "涩"]], "18139": ["病机", "脉细主营血不足，涩主络脉不利。原文「心痛彻背，时发时止，脉细涩」，乃中焦营虚、肝气贯膈入卫之候。细涩示营血亏少、络道涩滞，故痛作有时。治当和营养血、柔肝利络，不可香燥克气，正因脉细涩为虚涩而非实滞，香燥更耗营血。", ["细", "涩"]], "18140": ["病机", "脉细数弦滑，弦滑主肝气素盛、痰火内蕴，细数示阴分不足而热。原文「酒醴湿热化火化痰，木火横逆则胁胀背酸，肺金不肃则痰塞咳呛」，脉象正合肝火挟痰横逆、木火刑金之机。弦滑为痰火之实，细数为阴伤之虚，故治当化肝降肺，清化痰火。", ["细", "数", "弦", "滑"]], "18141": ["病机", "脉数而痛在脐下、形寒怯冷、舌干白，乃春寒袭入厥阴之候。数脉在此非实热，系寒邪郁遏、阳气被格而躁动所致。原文深虑发厥，正因寒中厥阴、阳郁不达，脉数而症见怯冷，为寒郁化躁之象，故用仲圣方温散厥阴寒邪。", ["数"]], "18142": ["预后", "脉细滑数，细主气血皆虚，滑数为肝阳化风、痰热内煽。原文「陡然昏晕神迷，右肢不用，脉细滑数，此偏中也」，明示气血虚而风阳挟痰上扰清窍。细滑数并见，为正虚邪实之候，故七日以内谨防昏厥汗越，预后堪虑，非指日可愈。", ["细", "滑", "数"]], "18143": ["病机", "脉数左细右大，右大为阳明有余，左细为少阴不足。原文「牙龈不肿而痛，脉数左细右大，阳明有余，少阴不足」，数主热，右大示阳明络热上攻，左细示少阴阴亏。故牙痛不肿、右股痹痛，皆属阳明络热而非寒，脉象与证候丝丝相扣。", ["数", "细", "大"]], "18144": ["病机", "脉细数，细为阴亏，数为虚热，故主阴亏肾热。原文言“误投刚剂燥，形疲肉消”，燥药更伤阴液，致“人火无物不消”，渐成骨痿。此脉示肾阴亏虚、虚火内炽，与形瘦骨痿相应，急宜咸苦滋泄。", ["细", "数"]], "18145": ["病机", "脉滑疾，滑主痰，疾主风火，合之则风痰袭络。病在左臂、昼轻夜重，乃气血两虚而风痰乘虚入络。原文断为“气血两虚，风痰袭络”，故脉滑疾反映风痰内动、络脉不通，治宜补气养血、熄风化痰通络。", ["滑", "疾"]], "18146": ["病机", "脉空右大，空为营气虚衰，大为虚阳外浮。右肱麻木痛楚，乃营气交虚，风湿痹阻络脉。脉空示营血不足，大示虚而无力，故主“营气交虚，风湿痹络”，与局部麻木痛楚相应。", ["空", "大"]], "18147": ["病机", "脉细数，细主阴血亏少，数主虚热内扰。秋初失血甚狂，癸水不至，逢节必发，咳呛形凛骨蒸，已成劳损。此脉示阴血亏虚、虚火灼肺，与咳呛骨蒸相应，故主劳损之病机。", ["细", "数"]], "18148": ["预后", "脉皆虚，形神色脉俱虚，久病缠绵反复，正气大伤。当一阳将萌之时，虚体难以应之，故“更何恃而不恐”。脉虚示气血阴阳俱衰，预后堪忧，故不敢用药，勉拟饮食调养以冀扶延。", ["虚"]], "18149": ["治法", "脉软音瘖，软为土气不足，音瘖乃金失所养。上吐下泻，中土大伤，土虚不能生金，故脉软而音哑。原文“法扶土生金”，正是针对土虚金弱之机，脉软主脾土虚弱，与吐泻、音瘖相应。", ["软"]], "18150": ["死脉", "原文未识脉名，但言“色脉皆脱”，乃气血津液耗竭之象。损怯至音哑喉痹、骨瘦如柴，已是劳损末传，非草木能疗。色脉皆脱示胃气已绝、真元败竭，故属死候，预后不良。", []], "18151": ["病机", "左脉弦微细，弦为肝郁，微细为阴血不足；右脉空若谷，空为气虚。左右合参，示肝阴亏虚而脾气大衰，气血两虚。原文叹“何虚之如是”，正强调虚损之甚，脉象反映阴阳气血俱亏之病机。", ["弦", "微", "细", "空"]], "18152": ["预后", "原文未出脉名，仅言“形脉皆衰”，谓形体与脉气俱衰。积劳阳伤，深秋痰嗽失血，缠淹百日，正气耗竭，脉失充盛之象，故曰“理之非易”，示预后不佳。脉衰与形衰并见，说明阳伤日久、气血难复，非一般咳嗽可比。", []], "18153": ["病机", "脉细空数，细为阴亏，空为脉道不充、阴血衰少，数为虚热内扰。冲年阴虚，疟后不复，咳呛痰稠，形神皆夺，正合阴虚火动、津液耗伤之机。脉细空数而形神俱夺，故曰“近怯之机”，示虚损已成，非外邪实热之数。", ["细", "空", "数"]], "18154": ["病机", "原文未出脉象，以“风伤皮毛，热伤血脉”立论。风热外袭，先伤肺卫皮毛，继入血脉，热灼肺络，故咳吐痰血而气腥。气腥为热壅血腐之征，肺络受损、热毒蓄结，恐成肺痈。此段重在阐明风热入血、腐灼肺络之病机，非凭脉断证。", []], "18155": ["主病", "脉滑主痰，滑为痰湿内盛、气机壅滞之象。舌白亦属痰湿之征，因痰而咳，说明咳由痰起，非外邪直伤。脉滑与舌白并见，紧扣“因痰而咳”，示病机在痰湿贮肺、肺失宣降，治当化痰为主，与阴虚燥咳之细数脉迥别。", ["滑"]], "18156": ["病机", "脉细数为阴虚火旺之象。咳呛夜甚、嗽而欲呕、动则气喘，乃肾阴下亏、肝火上逆、肺不肃降所致。细为阴亏，数为火动，夜甚动喘正合阴虚阳扰。原文明言“必须养肝摄肾，和胃化痰，断不可开泄上焦”，脉细数正是内伤虚火之凭，非表邪可散。", ["细", "数"]], "18157": ["病机", "脉数主热，舌白主痰饮。温邪内郁，挟痰饮蓄结肺俞，误服酸梅酸敛，邪固结不解，热恋伤阴，故呛甚灼热、肌瘦脉数；饮蓄于中，故舌白不浊。原文强调“近似劳怯而非怯”“断乎不可以补”，脉数在此为郁热之数，非虚劳之数，补则邪无出路。", ["数"]], "18158": ["病机", "脉细涩，细为阴血不足，涩为脉道不利、精血亏少。失血咳呛屡发不已，阴血屡耗，心肾之阴已竭，脉道失充且行涩，故主虚损。原文谓“急宜平补，偏寒偏热，均未得其病之旨”，说明细涩为纯虚之脉，非寒非热实邪，治当平补阴血。", ["细", "涩"]], "18159": ["病机", "脉数而左空弦，数为阳热浮动，空为阴血不充，弦为肝阳偏亢。春初咯血倍多，舌颧赤，乃肝肾阴亏、孤阳上冒，阴不恋阳，故脉数中带空弦。空弦并见，示阴竭阳浮，最恐暴脱，故拟乙癸同源以滋肝肾、潜浮阳。", ["数", "空", "弦"]], "18160": ["预后", "脉数右空，数主热，空为右寸肺脉失充，肺阴耗损，虚热内扰。咳呛痰血乃肺损络伤之征，脉证相合，示肺脏已伤，势难治也。", ["数", "空"]], "18161": ["病机", "驰骑习武致百脉震动，动则络逆为痛，血沸出口，脉震动应之。气为血帅，气逆血不循经，非虚损也，故不必用沉降重药。", ["动"]], "18162": ["预后", "脉沉细主里虚，足肿腹胀、筋见脐凸、舌白，乃脾肾阳虚，水湿内停，虚臌已成。沉细示阳气衰微，急切难治。", ["沉", "细"]], "18163": ["预后", "脉微为阳气衰微之象，脾肾阳虚，水湿浸渍，浮肿下甚，神倦脉微，阳衰欲脱，最易虚脱，当急温补固脱。", ["微"]], "18164": ["预后", "泄泻便溏、腹大筋见、脐突咳呛，脉数，乃膨胀痨损已成，数脉示虚热内炽，正虚邪盛，甚为棘手。", ["数"]], "18165": ["病机", "脉细数，细主阴血不足，数主虚热，脐凸腹胀偏左，肝气抑郁，气滞血瘀，郁而化热，故不易速效。", ["细", "数"]], "18166": ["病机", "脉细数涩，细数主阴伤虚热，涩主血行不畅。茎衄甫止，遍体浮肿，血化为水，邪热走入空窍，络脉瘀滞。", ["细", "数", "涩"]], "18167": ["预后", "脉迟细，迟主阳微，细主虚，泻后肿胀从下起，舌白，中下阳微，水湿不化，恐其悠悠忽忽而脱，当急温阳。", ["迟", "细"]], "18168": ["病机", "脉细为气血不足，左弦主肝郁，右涩主脾虚血少。原文“腹大囊肿，筋青脐凸”乃臌胀典型症候，因“郁怒伤肝、思虑伤脾”，木克土，血不归经，水湿内停。脉细弦涩正合肝郁脾虚、血瘀水停之病机，故主臌胀。", ["细", "弦", "涩"]], "18169": ["病机", "脉细数示气血两衰，左弦为肝郁，右软为脾虚。原文“脐腹起痞有形，略偏于左”及“高年气血两衰，思虑伤脾，郁怒伤肝”，说明中虚气滞成痞。脉细数弦软反映正虚与气郁并存，故主中虚气痞之病机。", ["细", "数", "弦", "软"]], "18170": ["病机", "原文“阳𫏋脉满，令人不寐”，阳𫏋脉满指阴阳跷脉气机失调，阳跷满则卫气不得入于阴，故不寐。此段未直接描述具体脉象，但以脉满言病机，主阳跷脉盛、阴阳失交之不寐。", []], "18171": ["病机", "脉数主热，舌绛为阴伤有热之征。原文“病逾百日，身热来去靡定，小便数欠”，结合“童年阴亏，湿热癃闭州都”，可知湿热内蕴、阴液亏耗，气化失司。脉数舌绛正合阴虚湿热之病机，故主癃闭。", ["数"]], "18172": ["病机", "脉细涩为气血两亏、脉道不利之象。原文“形寒身热，一载有余，便溏”，乃表里皆亏、气虚下陷之候。细涩脉反映气血不足且运行滞涩，与脾虚气陷、营卫不和之病机相应，故主虚损。", ["细", "涩"]], "18173": ["病机", "脉细主虚，舌白主寒。原文“上咳下泻，形神削夺”，咳属肺，泻属脾，脉细舌白示肺脾虚寒。细脉为气血不足之征，与肺脾虚寒、中焦失运之病机相合，故主虚寒咳泻。", ["细"]], "18174": ["病机", "脉小细涩为阴血亏虚、脉道不利之象。原文“形伟，脉小细而且涩”，形伟而脉反小细涩，示外强中干。心脾阴亏，血从下溢，脉道失充且行涩，正合阴亏血溢之病机，故主心脾阴亏、下血。", ["小", "细", "涩"]], "18175": ["病机", "右脉芤涩主血虚兼瘀，左寸空谷为心血不足之象。原文“肝不藏血，脾不统血，血不归经，渗而为瘀”，致“留血上下皆溢而络空气痹”，故见走注疼痛。芤涩空脉反映气营并病、虚实夹杂，主血瘀络空之病机。", ["芤", "涩", "空"]], "18176": ["预后", "六脉空谷，即脉来中空如谷，按之无力，为气血二气交虚之象。满肠皆痛、遍体浮黄、少食无寐，皆因气血亏极、精神失守所致。脉空而神衰，故原文忧其“悠悠忽忽而脱”，急急补养平调，正恐虚脱难挽，属危重预后之判。", ["空"]], "18177": ["病机", "舌光脉数，数主热，舌光示阴液大亏。夏暑秋风伤肺，热移大肠而便血溏泄，湿阻州都则茎痛。脉数在此既示热邪未清，又因舌光而显阴液耗伤，故治宜清热导湿，兼顾阴液，脉数正是热盛阴亏并见之征。", ["数"]], "18178": ["预后", "原文未出脉名，仅言“心脾极虚，八脉损伤，崩漏不已”。心脾两虚则统摄无权，八脉损伤则冲任不固，崩漏不止更耗气血。脉象虽未明载，然极虚之候已寓其中，故断“最恐虚波”，示虚脱之变，属预后警示。", []], "18179": ["预后", "原文未载脉象，仅言“病在八脉，急切难治”。八脉指冲任督带等奇经，损伤深重则气血难复，非旦夕可效。虽无脉可凭，然从“急切难治”可知其虚损根深，脉必见虚衰之象，属预后难愈之判。", []], "18180": ["病机", "脉细数，细主阴血亏少，数主虚热内扰。年届七七癸水反至，语言窒塞，乃肝肾本亏、心脾复伤、气不摄血所致。细数之脉正合阴亏血少而虚热内生之机，故拟黑归脾法补摄，然非旦夕可愈，脉象已示虚损之深。", ["细", "数"]], "18181": ["病机", "脉微细软，微主阳气衰微，细主阴血不足，软主气营两亏。产后腹痛、癸水衍期、形神削夺，皆气营大亏之候。脉微细软正应气血虚衰、无力鼓动之机，故原文断“非补不可”，非参不可，脉象为虚证用补之据。", ["微", "细", "软"]], "18182": ["病机", "脉数而虚，数主郁热，虚主血少。春产徂腊月事不来，脐下症瘕隐痛，吞酸谷少，乃肝气抑郁、血不流行所致。气郁化热故脉数，血虚不充故脉虚，数虚并见正合郁热与血虚夹杂之机，故先和肝胃缓痛，再商消痞。", ["数", "虚"]], "18183": ["病机", "脉微细涩，微主阳虚，细主血少，涩主血行不畅。产后营虚，肝不疏泄，面浮足肿、少腹痞硬、天癸衍期，皆营血虚滞之候。微细涩正示气血两虚而兼瘀滞，故急当温补气血以调达肝气，用黑逍遥散，脉象为温补调肝之凭。", ["微", "细", "涩"]], "18184": ["治法", "疔疮红肿、大便秘闭，脉实者，为热毒壅盛、腑气不通之象。脉实主邪气盛，热毒内结，故当用鲜生地、黄连、木通、生军等清热泻火、通腑解毒之品，以祛其实。", ["实"]], "18185": ["病机", "脉数细而左弦，数主热，细主阴伤，弦主肝火。症见血痣翻花、肉翻出血，乃心肝火旺、阴液耗伤，火迫血溢所致。故宜犀角地黄汤凉血滋阴、清心肝之火。", ["数", "细", "弦"]], "18186": ["治法", "骨槽风溃久，牙关不开，脉虚为病久气血亏耗之征。脉虚故用中和汤补托养血、散结清毒，但阳明多气多血，温补过施恐有偏弊，故拟照古方不增不减，以平调为妥。", ["虚"]], "18187": ["病机", "骨槽风溃后筋脉急缩，牙关紧强，脉急缩为筋脉拘急、余蕴未清之象。腠理结核、耳鸣不聪，乃厥少不和、阳浮于上，阴不敛阳，故拟养阴清肝、和络为治。", ["急", "缩"]], "18188": ["预后", "脉左散大、右濡小，散大为气血涣散，濡小为气血衰微。症见舌㖞目定、阳缩、头面无华、汗多，乃毒火蕴遏、伤阴耗气、气血两败之陷症，故曰药病不能医，命由天定。", ["散", "大", "濡", "小"]], "18189": ["预后", "进汤药虽有转机，但脉仍未起，说明正气未复，病根未拔，不可恃药效为稳。脉不起为虚象未改善，故仍守原方加生地五钱，以增养阴之力，继续观察。", []], "18190": ["病机", "右脉较起，为脾肾渐有充旺之机。营血素亏，肝阳化风，左半头痛；脾土弱则腹痛便溏。肝气虽强，水足则木自柔和，虚阳不上潜。故仍从脾肾进治，以固本缓肝。", []], "18191": ["病机", "脉神较起，为正气渐复之象。但肉翻峥崚、左腮上腭出血，乃火郁阴伤、肝火未清，灼伤血络。故当养阴清肝，以平火郁、滋耗损之阴。", []], "18192": ["病机", "原文未载脉象，然述肾阴不足、心火肝阳上亢，舌为心苗，肾脉贯肝膈循喉咙挟舌本，肾阴不升则心火不降，成未济之象，故发舌疮、舌根破碎成窟、不时内热。此属阴虚阳亢、心肾不交之病机，恐酿舌疳，法当滋水制阳。", []], "18193": ["病机", "盘槽痈月余溃脓，腮外坚肿硬势又将破溃，发热便闭食少哕恶，脉细神疲。脉细为阴血亏耗，神疲乃正气已伤，故断为阴伤胃热不化。痈久脓溃耗阴，胃热未清而化源不足，症属不轻，拟甘寒清解以护阴清胃。", ["细"]], "18194": ["主病", "肝火瘰疬颈项，自胛至胯发热，遍体经络擘痛，脉数。数脉主热，肝火亢盛，火性急迫故脉数；热灼经络、气血壅滞，故发热而经络擘痛。脉数与肝火瘰疬相应，宜逍遥散加减以疏肝清火。", ["数"]], "18195": ["病机", "原文未出脉象，述肝郁不舒，气火夹痰凝结颈左，发为失荣坚肿，筋脉攀痛。肝郁则气滞，气滞化火，火炼津液为痰，痰火凝结颈侧，故坚肿而筋脉攀痛。此属气火夹痰、郁结络脉之病机，宜清肝解郁。", []], "18196": ["预后", "乳岩一年肿突，红紫甫溃，两目筋脉掣痛，原文未载脉象。乳岩日久，肿突红紫而溃，乃阴伤火毒炽盛、肝筋失养之象；两目筋脉掣痛，为肝火循经上扰。症情深重，故断为难治之症，勉拟养阴清肝。", []], "18197": ["病机", "暴怒伤阴，厥气火偏旺，与阳明痰热交并于络，乳房坚肿、颈颜连结数核、时掣痛，已成岩症，脉数右洪。数主火盛，右洪为阳明气分热炽，气火不降故脉洪数。脉症相合，示痰火壅络，谨防破溃，急养阴清肝。", ["数", "洪"]], "18198": ["兼症", "乳核掣痛已减，而脉尚弦数。弦主肝郁，数主火旺，掣痛虽减而脉未和，知肝火未清、郁热仍存。脉象与余症相应，故仍守前法清肝散结，不可因痛减而遽停。", ["弦", "数"]], "18199": ["病机", "肝气夹痰凝滞，蔽骨发为痰疽已溃，一头肿硬不消又将破溃，脉来两尺弦数。弦主肝郁气滞，数主痰火，两尺候下焦，弦数并见，示肝经痰火未清而荣血已亏。故宜养荣和卫兼化痰软坚。", ["弦", "数"]], "18200": ["预后", "脉细为营血亏虚之象，神羸示正气大伤。原文谓抑郁伤肝、思虑伤脾，肝脾荣损，木火夹痰上升，结为石疽，硬坚如石。脉细神羸反映气血两耗、正虚邪盛，故断为已入沉疴、势难挽救，属预后不良之候。", ["细"]], "18201": ["病机", "脉沉弦涩，沉主里，弦主肝郁，涩主血滞。原文谓阴伤木郁、痰气凝痹，虽呕吐止、肿较退，但牙紧喉痹未舒，脉象示阴血内伤、肝木郁滞、痰气痹阻络脉，故虽似有转机而仍属险途。", ["沉", "弦", "涩"]], "18202": ["病机", "脉来弦强，弦为肝郁，强为气逆。原文谓郁怒伤肝，气滞络阻，胸胁痛、乳根坚肿，兼动劳喘气、自汗盗汗。弦强示肝郁气逆、阴血受伤，肾气不摄，故症势极重，治拟育阴柔肝以化坚结。", ["弦", "强"]], "18203": ["病机", "尺寸弱而急，弱主气血亏虚，急主肝木躁动。原文谓肛漏日久，阴耗阳伤，咳嗽恶寒、咽痛妨食、腹痛便溏，脉示肺肾并亏、肝木侮土，正虚而木亢，故势入损门，属重候。", ["弱", "急"]], "18204": ["预后", "脉虚细为气血两虚、正不胜邪之象。原文述肝痈背肋肿痛，咳嗽气急、痰腥肢冷、汗多蜕热，脉虚细示荣阴大伤、正气溃败，故症势极重，虽拟方而难望转机，属预后险恶之候。", ["虚", "细"]], "18205": ["病机", "脉数为内热之征。原文谓肋痈乃痰气血滞于肝络，肝胀成痈，外溃两月，肉腐外紫，内热咳嗽短气。脉数示肝肺两伤、荣阴大损，热毒未清而阴血已耗，故势入损门，治拟清养。", ["数"]], "18206": ["病机", "原文列肝痈脉象：弦数主肝火盛，弦涩主血凝气滞，弦兼滑主痰气血滞。引《素问》两胠满、卧惊、不得小便，陈远公谓郁怒致胁疼、火烁肝血，脉象正合肝气壅滞、怒火烁血、痰瘀互结之病机。", ["弦", "数", "涩", "滑"]], "18207": ["治法", "脉数为虚热内扰之象。原文谓肝痈溃后发热、虚羸脉数，服六味地黄汤以滋肝肾。溃后阴血大伤，虚热由生，故脉数而体羸，治取滋肝肾、清虚热，以复阴血而敛虚火。", ["数"]], "18208": ["病机", "肝痈溃久，脓血耗伤，气血俱虚，故脉弱。弱脉主气血不足、正气衰微，与溃后久不收口、乏力少神相应，治以八珍汤双补气血，正合虚则补之之意。", ["弱"]], "18209": ["病机", "肺痈一年，咳吐脓血而发热脉数，数主热盛，热灼肺阴，阴伤痰热互结，势入损门。脉数与发热、脓血并见，说明邪热未清而阴分已伤，故当养阴清痰热，标本兼顾。", ["数"]], "18210": ["病机", "悲哀伤中，气凝血结，脐上脘下结硬作痛，已成漫心痰，脉弦主气机郁结、痰凝络阻。寒热泻黄又夹暑邪，弦脉应肝，示气滞血瘀与暑邪交杂，故拟宣畅气血、散结化痰，非小恙可比。", ["弦"]], "18211": ["病机", "劳倦忧思郁结，颈发马刀，坚肿如石，痛掣头脑，脉细软为气血两亏、生气日残之象。细软脉示正虚不能托邪，坚肿如石则痰凝络阻，虚中夹实，极难调治，故姑拟养荣扶土以化坚结。", ["细", "软"]], "18212": ["病机", "血虚肝火夹痰凝结，颈右马刀结核坚肿硬如石，发热脉细。细脉主营血不足，阴血亏虚而肝火痰浊凝聚，症势极重，故宜和荣化痰缓缓取效，不可峻攻。", ["细"]], "18213": ["病机", "脉弦右滑左关且劲，弦劲为厥阴气火内动，滑主痰凝。荣阴不足，气火夹痰上升，凝结少阳之分，发为马刀结核坚肿。左关劲尤显肝火亢逆，故拟养荣清肝化坚，治调不易。", ["弦", "滑", "劲"]], "18214": ["病机", "少腹痈肿，肝气拂郁，寒邪乘之，血随气阻，日久化热，内脓已成，脉数主阴伤热郁。数脉与内热舌干、溲出便闭相应，示正虚邪凝，脓溃后恐胃气不苏、元气不续，故舍外从内，调胃育阴。", ["数"]], "18215": ["预后", "肠痈外溃，已得微脓，秽从孔出，浊气外泄，脉象难和，食难渐进。脉难和示正气已伤而胃气未复，与食少并见，虑正气与浊气并出，有上下交脱之危，故急加白芍、参须、熟地扶正固脱。", []], "18216": ["预后", "原文未明言脉象，仅以“脉静身凉”描述佳兆，脉静指脉不躁动，与身凉并见，说明邪退正安、阴阳暂和。然黎明外患复增，肿痛复作，乃因卯时气虚滞于大肠，邪正交攻肠膜，故虽暂安而根未除，须阴阳并补兼护膜，方保无变。", []], "18217": ["预后", "肠痈一年，内膜已伤，形衰脉弱。脉弱为气血不足、正气虚衰之象，与形衰并见，说明久病耗伤，正虚不能托邪，脓毒内损肠膜，故断为难治之证。", ["弱"]], "18218": ["病机", "两关细弦而右兼涩，细为不足，弦主肝旺，涩主湿滞。关部候肝脾，故知脾有湿痰、肝气大旺，荣卫不利，以致胸腹不舒、腰髀作痛、不能转侧，左肋痰注成漏。通利取快恐伤胃气，故宜和荣卫化痰兼平肝木。", ["细", "弦", "涩"]], "18219": ["病机", "脉冲和而关微弦，冲和示胃气未败，关微弦则木旺水亏、脾多痰湿之象。肝风晕厥数年，春分后木挟相火用事，湿痰随风火充斥三焦，发为眩晕发热、遍体作痛，并结痈毒于肝经部位。脉尚冲和，故似可无虞。", ["弦"]], "18220": ["病机", "脉滑数，滑主痰湿，数主热。背俞痰注痛、脓从肋缝出，兼发热面浮、胸腹饱胀、泄泻，乃痰湿滞脾、郁而化热之症。脉滑数正合痰湿滞脾、邪热内蕴之机，故非轻候，当先治其内。", ["滑", "数"]], "18221": ["病机", "脉细数，细为阴血不足，数主火郁。玉茎属肾，又为十二经络之总会，肾脏阴虚火郁，心肝之火复会于此，火郁日久外越，血得热而妄行，故茎头破溃翻花。脉细数示阴分大伤，龙雷之火不宜直折，当峻补真阴兼介类潜阳。", ["细", "数"]], "18222": ["预后", "脱囊黑腐，温邪内逼，哕恶泄泻，脉细舌白。脉细为正气虚衰、阴血不足，高年见之，说明温邪内陷而正不胜邪，故哕恶泄泻并作。此高年重症，慎防呃脱，先为和中止泄，以顾护胃气为急。", ["细"]], "18223": ["病机", "伏兔痈漫肿内硬，延两月，发热口干，脉虚数。虚为气血不足，数主热，脉虚数说明痈久正虚而热未清，漫肿内硬乃痰湿凝滞、经络不通。故宜养温通经络，扶正以托毒，不可纯用寒凉。", ["虚", "数"]], "18224": ["病机", "左部细弦为荣血不足、肝气不强，右部沉涩为脾气不利、气滞血凝。气血与汁沫凝结肠外，结为肠覃，状如怀子。月事仍以时来，说明病在肠外血分而非胞宫，故法宜养荣兼流气化凝。脉细弦沉涩正合血虚气滞、痰瘀互结之机。", ["细", "弦", "沉", "涩"]], "18225": ["病机", "脉见细数，细为阴亏，数为有热，合于肝肾阴亏、阳明湿热下注之鹤膝风。原文强调若进辛温则助热亏阴，致肿溃败症，故始宜通络利湿，继以养阴清络。细数之脉正是阴虚夹湿热之征，与膝肿热痛相应，非辛温开发所宜。", ["细", "数"]], "18226": ["病机", "本段未识脉名，专论麻风病机。原文谓疠者荣气热、脏气不清，风寒客络脉而不去；又分风湿、湿毒、毒疠诸种，肺虚则腠理不密，胃气薄则肌肉疏豁，气血滞而不行。初起一点麻木、毛窍闭塞，渐延遍身斑如云片，皆由气血滞、毒邪客于肌表经络所致。", []], "18227": ["治法", "本段未识脉名，为羚羊角散之主治。原文指出该方治肺胃吸受毒疠，斑红作肿、目赤泪多、四肢筋脉作痛，体虚者宜之。病机为毒疠之邪吸受于肺胃，热毒上攻则目赤，外发肌表则斑红作肿，流注筋脉则作痛；体虚者不耐攻伐，故以羚羊角散清解为治。", []], "18228": ["病机", "脉虚数为阴虚有热之象。原文言育阴化疠汤治阴虚湿热、毒疠蒸于阳明，斑红肿而脉虚数、不胜攻表者。虚为正气不足，数为热邪内蒸，湿热毒疠郁于阳明，外发斑红作肿；正虚不耐攻表，故治以育阴化疠，养阴清解兼化湿热。", ["虚", "数"]], "18229": ["病机", "脉虚数主正虚有热。原文以补肺清金饮治鸡胸龟背而脉虚数、身热少食者。鸡胸龟背多由先天肾亏、骨软失养，此处脉虚数为肺虚有热、金不清肃，故身热；脾运不健则少食。虚数之脉提示正虚热扰，治当补肺清金，不可纯用攻伐。", ["虚", "数"]], "18230": ["病机", "脉象双弦主肝脉为病。原文论龟背由先天肾亏、冷风入脊，或痰饮攻注、闪挫折伤。脊之第五椎以下属厥阴肝经，肝脉布于两胁，故在肝者脊背强痛牵引胁肋。双弦为肝气强急、经气不行之征，与腰脊板强、渐成龟背之候相应。", ["弦"]], "18231": ["病机", "脉小滑者，小为正气不足，滑主痰湿。原文以导痰汤治湿痰攻注、背俞脊庀作痛而脉小滑者。湿痰流注背俞，阻滞经气，故脊背作痛；脉滑应痰，脉小示正虚，合于湿痰攻注之病机，故治以导痰化湿。", ["小", "滑"]], "18232": ["病机", "原文未出脉名，以“脊曳酸痛，时时遗泄”点明督脉交亏。督脉贯脊属肾，亏则脊失所养而曳痛；下元不固则精关失守而遗泄。此段从症状推病机，属肾督两虚、精不内守之候，非以脉断病，故脉象要素为空。", []], "18233": ["病机", "原文未录脉象，据“先天本弱，又不谨守，梦泄神虚”立论。梦泄耗精则神虚，腿酸腰痛、肢软怔忡皆精亏神扰之象；泄后丹田疼痛、四肢头项摇动，为督脉空虚、肝风内动。故订清督养肝之方，主旨在辨病机而非凭脉。", []], "18234": ["病机", "“六脉软弱如游丝”言脉体软弱无力、细如游丝，为气血大虚、正气衰惫之象。软主虚，弱主不足，细如游丝则阴血亏甚、脉道不充。此脉见于前案梦泄神虚之后，说明久泄精亏、气血两伤，故改订丸方缓图补养。", ["软", "弱", "细"]], "18235": ["病机", "“上四部脉软弱，两尺水火俱衰”，软而弱主湿、主虚。原文引脉诀“软而弱者，湿家里恙”，断为寒湿凝于血分。上四部软弱示中上焦气虚湿困，两尺衰则肾之水火俱亏，故见怔忡耳鸣、便血紫、二便不调，徒养神安心无益。", ["软", "弱"]], "18236": ["病机", "“肾肝两部弦数”，弦主筋病、主痛，数主热。阴𤻊卵核硬筋、茎中痛、带白浊、小腹胀坠，皆肝肾二经为病。弦数并见，说明前服热药过多，热郁肝肾，筋脉拘急；后服凉药致筋缩，遂成寒热错杂之痼疾。", ["弦", "数"]], "18237": ["病机", "“右尺寸不足，关滑大，左三部软数”。右关滑大为脾胃留滞、痰食内停之象，右尺寸不足示下元虚；左三部软数则阴血不足而兼热。故断“脾胃有留滞之象，当先理之”，先化中焦积滞，再议其余。", ["滑", "大", "软", "数"]], "18238": ["预后", "“弦象无矣，数尚有之”，弦脉已去，说明肝郁筋急之势缓解，故咳减卧安、囟会已仁，为向愈之兆；但数脉独存，热未清，故“但热耳”，督脉热不退。此段以脉象进退判断病情转归，主旨在预后。", ["数"]], "18239": ["预后", "原文未出脉象，仅言“症随药减，可喜”，说明药已中病、诸症渐退；然“督脉热不除为虑”，提示阴亏内热未清，余邪留恋。此段以症状消长判吉凶，属预后之论，脉象要素故空。", []], "18240": ["兼症", "右关复数大，关候脾胃，数大为有余之象，故见肚疼、寒热仍有、大便溏、小便红黄，示脾胃湿热未清、邪势尚盛；然脉大好些、症亦减而体更弱，是邪减正亦虚，余邪未净，故未全清，当兼顾扶正。", ["大", "数"]], "18241": ["病机", "原文谓脾胃脉虽和而肾脉尚不足之甚，痰因脾生、腰痛内热不耐久坐责肾，故初诊理脾而腹痛减止；今脾脉虽和，肾虚未复，故拟晚资生丸、早大造丸，脾肾分途调补，以冀后效。", ["和"]], "18242": ["病机", "余脉俱好惟肾脉独大，肾位宜沉静而反大，是火居水位、反常之病，火扰精室故梦遗多年；近今不梦亦遗则为精滑，说明火盛失藏、精关不固，脉独大正是病本所在。", ["大"]], "18243": ["病机", "痹痛将十年，大筋短软拘挛、难于伸屈、咳噎牵引俱痛，乃风寒湿三气杂至合而成痹，久则血不荣筋；脉肝肺劲急，示邪郁筋脉、肝肺气机劲急不和，故只可养血荣筋、徐徐调治，见效纡缓。", ["劲", "急"]], "18244": ["病机", "六阴脉左关尺更觉沉迟，右三部稍好，左关尺候肝肾，沉迟为阳虚阴盛、寒凝之象；症见疟母未消、怔忡、督脉常冷牵及心胸四肢，皆阳气虚衰、寒凝脉络所致，故非大温补不效。", ["沉", "迟"]], "18245": ["其他", "本段未识脉名，仅述八味加千年健服后诸症稍减、督脉知暖，而怔忡作胀仍在，说明温补已见小效，督脉虚寒渐复，但心脾怔忡胀满未除，药力尚需续进，属服药后病情转归之记录。", []], "18246": ["病机", "痰饮十余年，每二三月或四五月一发，发则人事糊涂；脉沉小无力，沉主里、小无力为不足，原文断为水衰火盛、肾气不足，即肾虚水泛、火不归原，痰饮上蒙清窍，故发则神志糊涂。", ["沉", "小"]], "18247": ["病机", "六部皆弱为气血不足，两寸关兼涩则涩主瘀滞，寸关候上中焦，故知中宫瘀滞使然；脉弱而涩，是虚中夹瘀、气不运血，治法以和气化瘀为主，正合弱涩并见之病机。", ["弱", "涩"]], "18248": ["病机", "原文提出辨呕吐寒热虚实当参大微迟数脉，今两寸关涩而弱，涩主瘀滞，弱主胃虚，故断为胃虚有瘀。脉涩弱反映胃气不足、运化无力，瘀血内停，胃失和降，故得食即吐。治法不敢急攻，恐伤胃气，宜缓图之。", ["大", "微", "迟", "数"]], "18249": ["预后", "前诊涩脉主瘀滞，今涩脉少退，说明瘀滞稍行，气机渐通，故胸膈之胀达；小便酱色、紫黑之物尚未下净，是瘀血从下而出未彻。脉象好转与症状相应，预后向好，但仍需继续化瘀。", ["涩"]], "18250": ["预后", "右涩脉全退，瘀滞已化，故大解见黑色；但胃冷恶寒、不知饥饿，是脾胃虚寒未复。初食上焦仍胀，吐一口则愈，乃胃气上逆，吐后气顺。脉象改善而虚寒仍在，示瘀去而正未复，当温养脾胃。", ["涩"]], "18251": ["病机", "六脉虚而迟，虚主正气不足，迟主寒，故断为虚寒。饮食入胃必胀而吐，吐出物极冷，小腹亦胀，皆中焦虚寒、运化失职之象。瘀虽下而未尽，又逢天气寒，背心怕冷而胀，脉症相合，仍属虚寒，故前方续服。", ["虚", "迟"]], "18252": ["病机", "左关弦数而结滞，弦主少阳，数主热，结滞示邪气留滞。先胁胀，定时吐血，如疟应期，乃外感邪热客于少阳，留于募原，与卫气相遇，夹血上行。脉弦数结滞正合邪热与卫气相争、血随气逆之机，故以柴胡汤和解。", ["弦", "数", "结"]], "18253": ["病机", "水邪射肺，喘急不得卧，前医误作肺实，投降气及滋阴而剧。汗多乃肺窍不利、阳不卫外，非虚；脉沉小正是水饮内停之脉，沉主里，小主饮，水饮上射于肺，肺失宣降，故喘不得卧。当以逐饮为治。", ["沉", "小"]], "18254": ["其他", "此段总结前案，服后即卧，调理半月全安。诸医为脉所误，而作者认定不疑，关键在右部寸脉。右寸候肺，水饮射肺，右寸必有反映，故能独断为水饮，不为汗多脉沉小所惑，终获良效。", []], "18255": ["病机", "右关微弦尚未大败，左关虚微如毛，左关候肝，虚微如毛乃肝阴亏极。下焦真阴大亏，火无所恋，上炎致头脑拘紧、耳中蝉鸣。脉弦为肝气不敛，虚微为阴血不足，故用养阴收敛、引火归元而效。", ["弦", "虚", "微"]], "18256": ["病机", "脉左手三部皆洪弦而数，右亦同，洪为邪热盛，弦主邪郁，数主热，紧涩结滞乃前用大剂石膏逼遏，表邪内陷，热郁不得外达。身热足痛、舌干如锅焦、胸胀，皆邪热内陷、津伤气结之候，故脉象虽洪数而中带紧涩，示表未解而里热已炽，急当开腠理解表，兼存津液。", ["洪", "弦", "数", "紧"]], "18257": ["病机", "右寸洪滑，余俱沉弦，洪滑为痰热壅于上焦，沉弦主寒饮痼结中下二焦，故症见食少吐多、寒热错杂。半月后六脉沉陷、身冷汗出欲脱，乃寒痰痼结，阳气衰微，脉道不充，非辛温通阳不能开其闭，此脉由洪滑转沉陷，示病机由痰热转为寒凝阳衰。", ["洪", "滑", "沉", "弦"]], "18258": ["病机", "初诊寸关皆沉，手足逆冷，舌堆厚胎，腹大而痛，乃阴燥之象，邪遏阳气不能外达，故脉沉。服达原饮去芩加桂枝、炮姜后脉出肢温，三服脉大，是阳气渐复，邪有外达之势，复发热而脉大，为正气抗邪，故用小柴胡和解而平。此脉沉转大，示邪从内出外之机。", ["沉", "大"]], "18259": ["病机", "刚痓头足反张、口噤不语、身凉无汗，脉沉，乃寒邪束表，卫阳被遏，营阴凝滞，筋脉失养而拘急。脉沉主邪在里、阳气不伸，与身凉无汗相应。用葛根汤发汗解肌，一服能语言，次服汗出脉出，是寒邪外解、阳气宣通之征，脉由沉而出，示表解阳复。", ["沉"]], "18260": ["病机", "六脉皆伏，周身寒战，四肢逆冷，小便全闭，胸膈饱闷，乃厥阴少阴伏寒，寒凝气闭，阳气不能外达，脉道潜伏。前医误投补中益气，寒未去而膈满，三焦皆闭。脉伏非虚，乃寒邪深伏、气血凝滞之实，故当温散消导，使寒去气通，则脉自出。", ["伏"]], "18261": ["病机", "产后月余感寒，前医发汗，反增呕吐、呃逆、错语神昏，脉涩弱。涩弱为血夺津伤，脉道不充，汗因血夺，寒气无从泄越，血凝泣而不流。非养血则脉之涩弱者不活，非辛温则血之凝泣者不流，故用羌、苏、陈、半、干姜、当归，一服汗注而解，示养血温通则脉复。", ["涩", "弱"]], "18262": ["病机", "左寸关沉弦而细，右寸微洪，舌白如粉刺，乃厥阴寒与气凝，沉弦细主寒凝气滞，右寸微洪为气逆于上。后右寸浮洪而数，左寸关沉细如无，是寒凝未解，气火上逆。用左金丸后呕止，连进则通利如注，示寒散气通，脉象随之而变。", ["沉", "弦", "细", "洪"]], "18263": ["病机", "黄疸初服清热利湿不效，询知无汗，乃风寒袭表，未经解表，邪热留于经脉，郁而发黄。虽未录脉象，然症见无汗、目珠黄，知表闭营卫不和，故用茵陈、香薷、白术、黄芩、山栀、通草加葱白、桂枝，三服目珠净白，黄色大减，示荣卫一和，邪从表解而黄退。", []], "18264": ["病机", "六脉浮洪，阳旺于阴，阴不敛阳，虚火浮越，故下消虽肾虚而现阳亢之象，恐精耗肉削成损。右寸关空软，中上气分不足；左尺衰微，下元失守，疏泄多而闭藏少，气化失职。脉证合参，属气阴两虚、阳浮不摄之机，故治以益气养阴兼静摄。", ["浮", "洪", "空", "微"]], "18265": ["病机", "服铅粉下胎，痰症复发，腹中痛甚，晕厥搐搦，牙关紧闭，此痰气闭阻、肝风内动之厥。脉浮洪滑数，非绝脉，乃气闭痰壅、阳郁化风之象。筋惕与脉至相应，气达则生，气闭则死，正说明此厥为气机闭阻而非脱绝，故当开痰顺气以救之。", ["浮", "洪", "滑", "数"]], "18266": ["兼症", "产后污浊不行，气郁相触，脐下坚块如石，攻伐之后胸前坚者软、胁腹膨者消，忽添心慌意乱、汗出脉软、恶露少下、大便无度。脉软为攻伐伤正、气血两虚之征，正虚不能固摄，故汗出心慌，当暂停攻伐，以八珍加沉香、木香固其正。", ["软"]], "18267": ["主病", "产后转脬，小便不禁，精神倦怠，不思饮食，腹痛胀，寸关脉浮而芤。浮为气机上逆，芤为血虚失守，寸关候中上二焦，脉浮芤提示气血虚而小肠痈毒内结，故症见腹痛胀、小便失常，主小肠痈之病。", ["浮", "芤"]], "18268": ["病机", "寒热失血，头眩胁胀，心虚气喘，脉象细涩。细为阴血不足，涩为血行不畅，失血之后阴亏血少，脉道不充，故细涩；血虚不能养心则心虚气喘，阴不制阳则寒热，肝血不足则头眩胁胀，主阴血亏虚、肺失濡养之机。", ["细", "涩"]], "18269": ["病机", "积寒腹冷，因肝气郁结，脉象浮数。浮为气郁于外，数为郁而化热，寒积于内而气郁于外，寒热错杂，气机不畅，久延可成膈。脉浮数非纯热，乃肝郁气逆、寒热相搏之象，故主气郁膈塞之病机。", ["浮", "数"]], "18270": ["其他", "此段述嘉庆丁巳遇黄公老师，受业三载，得传嘉言、驰远六经阴阳表里寒热虚实之秘，拜别回川，屏去营谋，志在济世，杜门穷究医学，购求《内经》《灵枢》《素问》《难经》《脉诀》等书。全段为学医经历自述，未及具体脉象，故脉象要素为空，主旨属其他。", []], "18271": ["其他", "此段为七言诗句，言纤毫脉息须辨求明白，以《灵素》诸书相伴短檠，勤学不辍。原文未出具体脉名，仅泛言脉息当细辨，故脉象要素为空，主旨属其他，非论某病某脉。", []], "18272": ["其他", "此段论望闻问切四诊合参，强调切脉只是验证手段，非尽得病证于脉息。原文谓'切其脉以验证，不过再加详慎之意'，又言'倘脉证不符，犹必舍脉而从证'，说明脉诊须与望色、闻声、问因相参，不可孤立凭脉断病，体现四诊互证、脉证合参之旨。", []], "18273": ["其他", "此段仅存'切脉须知'标题，无脉象描述与病机论述，属篇目提示语，未涉及具体脉形、主病或证候，故无从分析其脉象要素与所主病机，仅可视为切脉总纲之引题。", []], "18274": ["平脉", "此段主张切脉尚简，以浮沉、迟数、大小、虚实、滑涩十脉为常法，谓'知此十脉，则凡人之病，不能出其范围'。浮沉辨表里，迟数辨寒热，大小虚实滑涩辨邪正盛衰。又以屋漏、弹石、鱼虾之游等形容死脉之变，示常以知变，属脉法纲领之论。", ["浮", "沉", "迟", "数"]], "18275": ["病机", "此段强调脉非专主一病，须脉证合参。原文举'中风之脉，浮迟者吉，大数者危'，'吐衄之脉，洪大者危，沉小者吉'，说明同一病可见不同脉，脉象反映邪正进退与胃气存亡：浮迟为阳证得阳脉故吉，大数洪大为阴伤火盛故危，示人以脉证病而非以脉猜病。", ["浮", "沉", "迟", "数"]], "18276": ["其他", "此段以六经配脏腑，论太阳膀胱、阳明胃、少阳胆、太阴脾、少阴肾、厥阴肝之归属，属经络脏腑分经之论，未涉具体脉象与病机，故脉象要素为空，主旨在于六经辨证之框架建立。", []], "18277": ["病机", "此段论一岁六气主时，厥阴风木、少阴君火、少阳相火、太阴湿土、阳明燥金、太阳寒水依次主气，谓'人身中之六经合天之六气'，人感六淫而受病，轻重各有所因。说明外感病机与天时六气相应，属六气致病之论，未及具体脉形。", []], "18278": ["其他", "此段述《内经》源流及仲景《杂病论》遭兵燹湮没，后人执陈方、鲜辨六经之弊，强调本书绘六经图以明某经某病某药，使学者不迷所往。全段为医史与著书宗旨之论，未涉及脉象与具体病机。", []], "18279": ["主病", "此案四肢烦疼，世医误作中风用消风活血，致成鹤膝枯瘦。'六脉沉迟而伏'，沉主里、迟主寒、伏主饮邪深伏，正合太阴脾经溢饮之证：脾阳不运，水饮内停，故脉沉迟而伏。误用风药更伤阳气，饮邪下注而成痿废，示脉证合参、不可误作风治。", ["沉", "迟", "伏"]], "18280": ["病机", "脉浮虚无力，浮为虚阳外越之假象，虚为里阳不足之本质。原文谓'少阴中寒，真阳不得上达'，壮热头重痛乃阴邪僭犯至高，腹痛作泄、体重恶寒、起则眩晕皆里寒之征。脉证合参，里重于表，故不可发表分利，当专主温里，用砂半耆术姜附肉桂故纸温补真阳，阳回则浮虚自敛。", ["浮", "虚"]], "18281": ["病机", "脉浮属太阳，大属阳明，弦属少阳，数主热盛。原文以'少阴病法当脉沉迟'作反衬，今恶热脉数，知非少阴。身大热多汗为热越，口苦咽干为少阳腑证，小便短赤为太阳腑证，腹满便闭为阳明胃实，头昏少气息高皆热盛燥结、浊气上干所致。三阳合病，脉证相应，故主白虎、黄芩、五苓加滑石等清解分利。", ["浮", "大", "弦", "数"]], "18282": ["主病", "阳毒为热毒壅盛之证，身重腰脊背痛、烦闷狂言、吐血下利，皆毒热燔灼、扰乱神明、伤及血络所致。其脉浮者，热毒佛郁于表分，气血浮盛于外，非表邪之浮。原文列于阳毒汤主治之下，脉浮与壮热狂乱并见，说明毒热有外越之势，故以清热解毒透邪为治。", ["浮"]], "18283": ["治法", "原文论'土郁夺之'，夺不限于下，吐亦为上夺。'下部有脉，上部无脉'指食塞胃中、气机壅遏于上，寸口脉不应，故用烧盐汤探吐，使胃土之郁从吐而解。此段以脉之上下有无判断病位在胃、病机为食积壅塞，属因势利导之治法，非一般主病之脉。", []], "18284": ["误治", "原文论瓜蒂散催吐之宜忌，'尺脉绝者不宜服，恐损胃气'，尺脉绝示下焦元气已竭，吐法更伤胃气，故列为禁忌；'亡血虚家禁用'亦同此理。此段未出具体脉名，以尺脉绝否判断吐法可否，脉象用于辨体质虚实、防误治伤正，属治法中的禁忌判断。", []], "18285": ["病机", "寸脉微浮，寸主上焦，微浮示邪郁胸中而未深陷。原文谓头不痛项不强，排除太阳表证；胸中痞硬、气上冲喉不得息，为胸中寒痰壅塞、气机不得下降。脉微浮与胸中痞硬相应，说明病位在上焦胸膈，邪有上越之势，故宜因势吐之，使寒痰从上而解。", ["微", "浮"]], "18286": ["病机", "脉紧不大，紧主寒主痛，不大示邪结不散、气血壅滞。原文以赤豆瓜蒂行水湿痰涎，治痰涎头痛、胸满寒热，脉紧不大者宜吐。紧脉与胸满寒热并见，说明寒湿痰涎结聚胸膈、阳气被遏，故脉道拘急而不洪大，吐去痰涎则气机通利、紧脉自缓。", ["紧"]], "18287": ["主病", "太阳中暑，暑热伤气耗津，气液两虚，故脉微弱。身重痛者，暑湿困阻肌表、经气不利，非寒邪束表之身痛。脉微弱与身重痛并见，说明暑伤气阴、湿滞肌腠，治当清暑益气养阴，不可妄用发汗。原文以独圣散治之，取吐越暑湿痰浊之意，脉微弱为辨证之关键。", ["微", "弱"]], "18288": ["治法", "此段论麻黄汤、桂枝汤之配伍与加减法，未涉脉象。原文强调用麻黄汤须察本气无亏，元阴不足加归、地，真阳素虚加附子，肺胃蓄热加石膏；并以恶寒喜热、爱服椒姜辨真阳素虚，以喜服寒凉生冷辨阴亏火旺，示人凭症候辨体质以定治法。", []], "18289": ["病机", "原文以脉数辨寒邪化热传经，脉静则邪未热而不传；又凭浮属太阳、大属阳明、弦属少阳分经。脉数为热化之征，故主传经；然必脉证相合，病不合脉则舍脉从证，体现凭脉辨传经与脉证合参之旨。", ["数", "浮", "大", "弦"]], "18290": ["病机", "大青龙证为太阳无汗烦躁而设，取微似汗以解。若见恶风、脉微弱，则非阳郁烦躁，乃少阴亡阳之候，脉微弱示阳气虚衰，误服大青龙发汗则速亡阳，故仲景立真武汤救误，以燠土制水为阴盛者设，与阳亢者对峙。", ["微", "弱"]], "18291": ["病机", "此段以青龙、白虎、真武方义论纵横脉证，未出具体脉象。原文谓伤寒有忽然自汗、突尔亡阳之候，虽未犯青龙之药已犯其逆；纵横之脉证不同，刺期门以制肝木、预弭亡阳，真武坐镇北方以制水，说明脉证纵横皆关阳气与水气之变。", []], "18292": ["病机", "原文论发太阳汗当顾阳气，发阳明汗当顾阴津。阳明证不论中风伤寒，脉微、脉实，汗出少则邪将自解，汗出多则阴津易竭。脉微、脉实并举，示无论脉之虚实，皆当谨持汗法之柄，不可重剂发汗以竭人津液。", ["微", "实"]], "18293": ["病机", "腹痛作泄日久，转大便闭、自汗、昏愦谵语、腹满苔焦，反通身冰凉、脉微如丝、寸脉更微。原文断为结热阻结中焦、营气不达四肢，阳极似阴之证；脉微非虚寒，乃热结深伏、脉道不利所致，故声音烈烈、扬手掷足、渴欲饮冷诸症可参。", ["微", "细"]], "18294": ["病机", "腹胀不大便而脉微而涩、舌润不渴，原文断为里气虚、脱证已具，法当扶阳固肾、醒脾和气。脉微为阳气虚衰，涩为营气不利，故不可攻下；医者误下，大便暂通而腹胀反甚，终至气壅而死，示脉微涩者下之则脱。", ["微", "涩"]], "18295": ["病机", "原文按脾脉主缓，证本发黄。脾虚湿郁则发黄，小便利则湿行而黄可免；若大便硬则胃有夙燥，因复转阳明。脉缓应脾，示湿郁之黄与胃燥转属阳明之机，凭二便辨湿行与燥结之转归。", ["缓"]], "18296": ["病机", "六脉沉细而微，沉主里，细主虚，微主阳气衰微。患者年高体丰，暑月过食寒凉致下利数十次，粪带清水，此太少二阴鹜溏之证兼陷暑邪。脉沉细微说明中气大虚、脾肾阳衰，故见眩晕、不能起床，法当大补中气、扶脾固肾、温经御邪。", ["沉", "细", "微"]], "18297": ["病机", "阳脉涩为阳虚，阴脉弦为阴盛。阳虚阴盛，阴寒内盛则腹中急痛。涩脉主阳气不足，弦脉主阴寒内盛、气机拘急，故当腹中急痛。治宜助阳御阴，用耆、术、炮姜、附、桂，而小建中、小柴胡皆不中理。", ["涩", "弦"]], "18298": ["误治", "太阴经病属里，虽脉浮亦不宜发汗。脉浮在此非单纯太阳表证，若只据脉浮用桂枝专顾太阳，不顾太阴，则误治。当以理中为主，内加桂枝，两经合治。此段强调脉浮需结合证候辨表里，不可见浮即汗。", ["浮"]], "18299": ["主病", "脉沉无力为里虚寒之象。理中汤治伤寒太阴病，自利不渴、寒多而呕、腹痛鹜溏，脉沉无力，或厥冷拘急，或结胸吐蛔，及感寒霍乱。沉主里，无力主虚，故主中焦虚寒、脾阳不振之证。", ["沉", "无", "力"]], "18300": ["病机", "右寸关浮大滑而弦甚，余脉如常。浮大滑主痰饮壅盛，弦甚主饮邪结聚。右寸关候脾肺，痰饮盘踞太阴脾经，形成巢囊之痰，故吐痰三十余年，发时左胁胀大如瓜，吐破絮状臭痰。此脉象说明脾虚痰饮内结之病机。", ["浮", "大", "滑", "弦"]], "18301": ["病机", "右寸关浮滑而紧，余脉如常。浮滑主痰饮，紧主寒饮内结。右寸关候脾肺，脾经虚弱，痰饮由胃旁流入胁，形成悬饮，故咳嗽吐痰、右胁刺痛、胸膈不开。脉象反映痰饮内结、寒饮射肺之病机。", ["浮", "滑", "紧"]], "18302": ["病机", "脉阴阳俱紧，紧主寒邪盛。反出汗者，为亡阳之象，属少阴。少阴寒盛，虚阳外越则汗出，阳亡于上则咽痛，阴寒内盛则吐利。此脉紧与汗出并见，说明寒盛阳亡、阴阳离决之病机。", ["紧"]], "18303": ["预后", "少阴病下利脉微，微主阳气衰微。干呕心烦为阴寒在下、阳烦在上。脉微续者，阳气渐复，为可治；暴出者，势必有雀啄、釜沸之象，主死。雀啄、釜沸为真脏脉，说明胃气已绝、阳气暴脱，故预后不良。", ["微", "雀啄", "釜沸"]], "18304": ["治法", "原文“脉不出者，用通脉四逆汤”，脉不出指脉微欲绝、重按不应，为少阴阳衰、阴寒内盛、气血不能外达之象。通脉四逆汤用大剂姜附回阳救逆，使阳气复、脉气通，故为治法条文，非专论脉象。", []], "18305": ["其他", "此段仅列“通脉四逆汤”方名，未出脉象与症候，当承前条“脉不出”而言。通脉四逆汤主治少阴病下利清谷、里寒外热、脉微欲绝，属回阳通脉之剂，故本条归为其他，不另作脉象分析。", []], "18306": ["病机", "原文“利止脉不出者，加人参以生其阳而长其阴也”，利止而脉仍不出，是阳衰未复、阴液亦耗，脉道无气以充。加人参于通脉四逆汤中，既助姜附生阳，又益阴以长脉，说明脉不出之机在阴阳两虚、脉气不续。", []], "18307": ["兼症", "脉见微涩，微为阳虚，涩为血少气滞，故见腹中急痛、恶寒厥逆、呕吐下利，属阴寒内盛、阳气衰微。投四逆汤无效而前阴突出如脬，是温下反逼其阴，改灸百会升阳乃愈，说明微涩脉主阳衰寒凝、气血滞涩之兼症。", ["微", "涩"]], "18308": ["病机", "原文以“脉微细欲绝”属纯阴无阳，阳衰不能鼓脉；以“脉滑而数”属阳进欲愈，热邪内盛而正气渐复。微细欲绝主厥冷、大汗、大利之亡阳；滑数主渴欲饮水、饥欲得食之阳回。两脉对举，说明厥阴阴阳进退之病机。", ["微", "细", "滑", "数"]], "18309": ["病机", "此段论先天肾中水火，以坎水为阳水、兑泽为阴水，强调“水气潜行地中，为万物受命根本”，又谓命门之火蒸腐水谷。虽未出脉象，但所论阳水阴水、火中之水、土中之水，实为脉象生成与病机水火偏胜之根本。", []], "18310": ["病机", "原文“脉耗而虚”指脉体耗损而无力，主金弱木盛、水少火亏，故八味丸补火滋水。又言“脉鼓指，按之有力，服之亦效”，因“诸紧为寒”，紧脉鼓指乃火亏内虚、寒凝所致，非实热，故温补亦效，说明虚与紧寒之脉机。", ["虚", "紧"]], "18311": ["病机", "原文以“脉散”论命门火衰。脉散为阳气离散、不能收摄之象，因命门真阳为十二官动力，火旺则精神强健，火微则衰弱，火息则无生。脉散正是火息阳散、脏腑失养之危候，故主病机在命门火衰、阳气欲散。", ["散"]], "18312": ["病机", "左尺脉虚弱而细数，为左肾真阴不足之象，阴虚不能制火故细数；右尺脉迟软或沉细数欲绝，为命门相火不足，阳虚不能鼓动故迟软。两尺微弱则阴阳俱虚。此以尺脉分肾中阴阳水火之虚，主肾虚证，治用六味、八味、十补丸。", ["虚", "弱", "细", "数"]], "18313": ["平脉", "原文引脉式歌“阿阿缓若春杨柳”，形容脉来和缓柔匀，如春柳摇曳，为脾胃冲和之平脉。此段论咳嗽分五脏六气，而脾咳土旺四时仅微咳，其脉当见缓象，故以缓脉为平脉之征，非病脉。", ["缓"]], "18314": ["主病", "咳嗽而面红潮热，脉洪数，洪为热盛，数为火急，显系火邪乘肺、肺金受灼之实热证。故用黄连解毒汤直折火势而愈。此脉洪数主实火咳嗽，与面红潮热相应。", ["洪", "数"]], "18315": ["病机", "脾肺肾三部脉皆浮而洪，按之微细，浮洪为虚火上炎之假象，按之微细方显脾土虚不能生肺金、肺金不能生肾水之本质。此脉主脾肺肾三脏虚损、虚火上炎之咳嗽，故用补中益气、八仙长寿丸培补而愈。", ["浮", "洪", "微", "细"]], "18316": ["兼症", "夏月唾痰，清火药不应，脉散。散脉主气耗火浮，火乘肺金，肺气耗散不敛，故唾痰。用麦门冬汤清润而愈，后劳复嗽，以补中益气加味及生脉散、八仙长寿丸调补，脉散示肺气耗散之兼症。", ["散"]], "18317": ["病机", "咳嗽壮热自汗口干便赤，脉虚而洪。洪为热盛于外，虚为气耗于内，乃虚火浮越、本虚标热之候。先以白虎汤彻其热，继用补中益气加山栀、麦冬、五味，兼八仙长寿丸，示脉虚洪主虚火咳嗽之病机。", ["虚", "洪"]], "18318": ["病机", "右寸大而无力，右关微弦，右尺倏有倏无，左三部软而无力。右寸大无力为肺气虚，右关微弦为脾虚木乘，右尺倏有倏无为肾气不固，左三部软而无力为肝血不足。此脉主脾肾两伤，故用补中益气、肾气丸而愈。", ["大", "弦", "软"]], "18319": ["病机", "原文未出脉名，而论痰饮由于脾虚，属太阴脾经。脾阳衰乏，水谷津液传布不尽，留而为饮。此段从病机立论，说明痰饮之本在脾虚阳弱，非脉象可主，故脉象要素为空。", []], "18320": ["病机", "右寸洪大而数，右关微弦滑甚，余脉无力，是手足太阴二经亏损、痰饮益甚之象。洪数为虚火挟痰上壅于肺，弦滑主脾虚留饮，余脉无力则中气大亏、肾气涣散，气虚上干而喘。故以耆、术补中宫阳气，佐醒脾豁痰、温中逐饮，正合右寸洪数、右关弦滑所主之脾肺虚损痰喘。", ["洪", "数", "弦", "滑"]], "18321": ["病机", "原文未出脉名，以“气脉不通”言病机。胸背手足腰项筋骨牵引钓痛、走移不定、手足冷痹，是痰涎在胸膈上下流注，阻滞气脉，非瘫痪之证。痰随气升降，故痛处走移；痰阻阳气不达四末，故冷痹。误认瘫痪则贻害匪轻，点明痰涎为病本。", []], "18322": ["病机", "劳心好色内伤真阴，真阴既伤则阳无所附，故亦发热。面赤烦躁、口渴引饮、骨痛，脉数而大，或尺数而无力，正是阴虚阳浮、无根之火上炎之象。数大为虚火奔迫，尺数无力则根本已亏，与伤寒外感发热当用汗法者迥别，误汗则殆。", ["数", "大"]], "18323": ["病机", "辨气虚血虚之内伤：阴血虚者面赤，无根之火戴于上；阳气虚者火入于内，面必不赤。口虽渴而舌必滑，脉虽数而尺脉必无力，甚者尺脉虽洪数而按之必不鼓，皆肾水干枯、引水自救而根本空虚之征。若服凉药而脉加数者，是火郁，宜升宜补，切忌寒凉。", ["数", "洪"]], "18324": ["病机", "原文未出脉名，专论咳、嗽、咯、唾皆出于肾。肾脉入肺循喉咙，二脏相连，病则俱病而根在肾。肾中水干火燃，阴火刑金故咳；水挟相火化为痰入肺，故嗽中痰唾带血。指出咳嗽吐血不可独归之肺，病机在肾水亏而相火炎上。", []], "18325": ["误治", "内伤外感，医家肆行发散，致表证难罢、干犯阴血，愈治愈热。六脉沉细而数、右关微弦，是发散太过、血虚之甚，又被阴火逼迫所致。沉细为阴血亏耗，数为阴火内迫，右关微弦应脾土受戕。故用归、芍、地、知柏栀连滋阴降火，改八珍汤而渐退。", ["沉", "细", "数", "弦"]], "18326": ["预后", "素患咳嗽吐血，误服滋阴寒凉，阴愈长而阳愈消。六脉沉微、惟右寸浮大而软，是阳虚之证：沉微为阳气衰微，右寸浮大而软乃虚阳浮越于肺。犹幸脉小身温，胃气尚存，故许予数剂而安，用补中益气倍耆术、加姜附温阳而愈，示脉小身温为可救之候。", ["沉", "微", "浮", "大"]], "18327": ["预后", "以脉判预后：脉浮而滑者易治，微细者难疗。浮滑为邪在表、正气尚能鼓动，痰浊未深结，故易治；微细则气血衰微、根本已损，正不胜邪，故难疗。此以脉之浮滑与微细对举，辨病势浅深与胃气强弱，属凭脉断吉凶之论。", ["浮", "滑", "微", "细"]], "18328": ["病机", "六脉沉微为阳气不足、正气内虚之象，惟右寸肺脉大而滑甚，是痰浊壅盛于肺、本虚标实之候。沉微示脾肾阳弱，大滑示肺中痰实，故齁喘遇风寒即发、痰尽乃平。治先以紫金丹攻其痰实，继以六味、补中培本，正合此脉机。", ["沉", "微", "大", "滑"]], "18329": ["治法", "脉数大有力者，为肺中燥热实火，故见烦渴喘呼，治当润肺为主、扶脾佐之；脉细数无力者，为脾虚阴亏，故食少善泄，治当扶脾为主、保肺佐之。原文强调分经辨证、切脉以治，数大与细数无力对举，正示虚实异治之据。", ["数", "大", "细"]], "18330": ["病机", "右尺脉滑大，右尺属命门相火，滑大为火盛之象，故原文谓相火正隆、燥渴而见此脉，偶投知母、黄柏一二剂可也。然痨瘵之火本属阴虚，多投苦寒必戕命根，故戒多用。此段借右尺滑大辨实火可暂泻、虚火不可久伐。", ["滑", "大"]], "18331": ["病机", "阴虚无以制火，火气逆上则喘嗽吐痰，脉见浮大或沉虚，浮大为虚阳外浮、沉虚为阴亏于内。原文以午后子前发热、寐时盗汗为阴虚之征，主四物加知、柏。然又戒川芎上窜、地黄腻滞、知柏滑肠败胃，示不可概施。", ["浮", "大", "沉", "虚"]], "18332": ["病机", "久病而百脉空虚，是气血真元耗损、虚火亢炎之候，非甘温不能复真元，非濡润不能泽枯朽，故宜异功散、补中益气汤与六味地黄丸。前所列苡仁、茯苓、麦冬、五味等，则为初病设，与久病空虚者层次不同，原文以虚实分治立论。", ["空", "虚"]], "18333": ["兼症", "脉散为气耗不收之象，故见少气懒言、目昏面白，宜生脉散、甘桔汤频频啜之，以敛气保肺。若病久积痰成积、腹胁常热而头面手足寅卯时乍凉，则属痰积内结、阳气升降失时，宜六君子加姜汁、竹沥送滚痰丸。此段以脉散统摄兼症与方治。", ["散"]], "18334": ["预后", "形色尪羸、阳事不禁，是精血竭于下；脉细无根，为真元已败、胃气将绝；数而无伦，为虚阳妄动、脉失常度。三者并见，故断旦夕必逝。细而无根示根本已离，数乱示阴阳不相维系，此非病机推断，乃死候之判。", ["细", "数"]], "18335": ["预后", "色欲过度损伤精血，阴虚火动，故盗汗、午后发热、咳嗽咯血，脉沉数示火郁于阴分。至肌肤消瘦、昏睡床褥而脉转细数，则阴竭火炽、胃气已衰，故难为矣。原文以沉数属初病可治、细数属晚期难治，示脉随病进而预后迥异。", ["沉", "数", "细"]], "18336": ["病机", "左尺脉虚弱或细数，为左肾真阴不足，阴虚不能制火而虚热内生；右尺脉迟软或沉细，为右肾真阳不足，火衰不能温煦。尺脉候肾，虚、弱、迟、细皆不足之象，故主三阴亏损、阴阳两虚之证，治宜六味、八味及补中益气汤调补。", ["虚", "弱", "迟", "细"]], "18337": ["病机", "左三部洪数无伦，为肾中真阴大虚，阳无依附而发越于外，故见烦热、面赤、舌刺、便结等假热之象。洪数为有余之脉，然无伦次，是阴竭阳浮，非实火可比。经云“大热而盛，寒之不寒，是无水也”，故当峻补其阴，不可苦寒直折。", ["洪", "数"]], "18338": ["病机", "六脉沉细而数，左关数甚，沉细为阴分亏虚，数为有热，左关候肝，数甚则肝经热盛。结合面黯色滞、发焦耳枯、形神俱败，乃尸虫旺极、耗伤气血之候。前医误作虚劳滋阴，反养其虫，故脉见沉细数而神败，主尸虫内蚀、元气大伤之病机。", ["沉", "细", "数"]], "18339": ["病机", "两尺脉微如丝，为先天阴阳俱虚，肾气衰微；右关弦紧乍有乍无，为脾胃虚寒、气机郁滞；两寸与左关洪大而散，为虚阳上浮、元气涣散。合观乃本实先拨、水火不济之候，故饮食不进、二便艰涩，主脾肾阳衰、虚阳外越之病机。", ["微", "弦", "紧", "洪"]], "18340": ["病机", "两寸关脉大而弱，大则为虚，弱为气血不足；两尺脉涩而小，涩主血少，小主气虚。寸关候上中焦，尺候下焦，今上下皆见虚象，故断为气血不足、大虚之证。反胃日久，中焦运化无力，下焦精血亏耗，脉证相合，主脾胃虚衰、气血两亏之病机。", ["大", "弱", "涩", "小"]], "18341": ["病机", "右尺洪大而紧，余脉如常，右尺候肾，洪大为阳热亢盛，紧为邪结，此肾中真阳之人飞越，虚阳外浮而见阳强不倒。满面红光乃虚火上炎，非实热之象。脉洪紧而余脉如常，说明病位在肾，火不归宅，主肾中真阳飞越、虚火妄动之病机。", ["洪", "紧"]], "18342": ["病机", "六脉俱伏，为阴寒内盛、阳气衰微，气血凝滞不能外达，故脉伏不见。结合面青唇黑、舌卷阳缩、四肢厥逆，乃少阴、厥阴寒邪深入，真阳欲脱之危候。伏脉主邪闭，此则寒闭阳气，主中寒阳衰、寒厥内闭之病机，急宜温阳散寒。", ["伏"]], "18343": ["治法", "此段为议论，强调三阴虚寒诸证当依脉轻重变化，重用黄芪、白术以理脾涤饮、温补气血。虽未出具体脉象，但“依脉轻重变化”点明脉诊在辨治虚寒证中的指导作用，脉轻则虚轻，脉重则虚重，据此调整补益之力，主三阴虚寒、脾肾不足之治法。", []], "18344": ["治法", "原文未出脉名，但强调“依脉轻重变化”以升提法治内伤饮食、劳役、风寒。病机为气虚下陷，脾胃不能克化，饮食不能运动，甚则成痨瘵。脉当见虚软无力或右关弱，反映中气不足、清阳不升，故用补中益气汤升举下陷之气。", []], "18345": ["主病", "原文以“右手寸口脉大于左手寸口之脉”为内伤证之凭，且言“无论左右关脉、尺脉大、小、浮、沉，即以此方投之”。右脉大于左，反映脾胃内伤、中气不足而虚阳浮越，故主内伤劳倦，治以补中益气汤升提中气，效如桴鼓。", ["大"]], "18346": ["病机", "原文指出“左手寸口之脉大于右手寸口之脉者”，是清气不升、浊阴腾上之机，非可妄用升、柴提气。左脉大于右，为清阳不升而浊阴上逆，与脾胃内伤、升降失司相应，故告诫不可误认作气虚下陷而径投升提，否则杀人无算。", ["大"]], "18347": ["主病", "原文引《金匮》“平人脉大为劳，脉极虚亦为劳”，又言“劳之为病，其脉浮大，手足烦热；春夏剧，秋冬瘥”。脉大而浮、极虚，皆劳伤精气、虚阳外浮之象，主虚劳病，症见手足烦热、时令剧瘥，治以黄芪建中汤温建中气。", ["大", "虚", "浮"]], "18348": ["病机", "原文述脾胃气衰、元气不足而阴火独盛，症见“气高而喘，身热而烦，其脉洪大而头痛，或渴不止”。洪大之脉非实热，乃阴火乘土位、壮火食气所致，主脾胃内伤、阴火上冲之病机，与元气不两立，故见喘、热、烦、渴等症。", ["洪", "大"]], "18349": ["病机", "原文言“脉之缩急”，因饥饱劳役损伤脾胃，脾胃一虚，肺气先绝，腹中急缩，带脉缩急。缩急之脉反映中气大虚、筋脉失养而拘急，主内伤脾胃、气虚下陷之病机，故用黄芪、人参、炙草、升麻、柴胡等补中升提、缓急。", ["急"]], "18350": ["主病", "原文“腹中痛，恶寒而脉弦者，是木来克土也”，弦为肝木之脉，腹中痛、恶寒为脾胃虚寒，木乘土位，故脉弦主肝木克脾土之病机，症见腹痛恶寒，治以小建中汤温中缓急、抑木扶土。", ["弦"]], "18351": ["主病", "原文“脉沉细腹痛，以理中汤主之”，沉细为里虚寒之脉，沉主里、细主虚，腹痛因中焦虚寒、水气内停，故脉沉细主脾胃虚寒、水湿内盛之病机，治以理中汤，干姜味热于土中泻水以温中散寒。", ["沉", "细"]], "18352": ["病机", "脉来濡缓，濡为湿邪困阻、脉道弛缓，缓为湿性黏滞、气血运行徐缓。原文以“体重肢节痛，或腹胀，自利”伴濡缓脉，断为“湿胜也”，湿邪困阻肌腠则体重肢节痛，湿困中焦则腹胀自利，故加苍术、厚朴燥湿运脾，脉症相合。", ["濡", "缓"]], "18353": ["主病", "脉浮而紧，浮主表、紧主寒，为风寒束表之象。原文“冬月恶寒，发热无汗”与浮紧脉相应，寒邪闭表则无汗，正邪交争则发热恶寒。故于本方中酌加麻黄、桂枝以辛温解表、发汗散寒，并减参、耆用量以防敛邪。", ["浮", "紧"]], "18354": ["主病", "脉浮而缓，浮主表、缓主风，为风邪伤卫、营卫不和之象。原文“冬月恶风，发热有汗”与浮缓脉相应，风性开泄故汗出恶风。故加桂枝、芍药以调和营卫、解肌祛风，与麻黄汤证之浮紧无汗形成对举。", ["浮", "缓"]], "18355": ["病机", "原文以气口脉“急大而数，时一代而涩”立论：涩为肺之本脉，代为气不相接、脾胃不足，大为洪大、心脉刑肺，急为弦急、肝木挟心火刑肺金。右关独大而数、数中时显一代，乃饮食不时、寒温失所致胃脉损弱，脾脉内显，总属脾胃不足、五脏相乘之机。", ["大", "数", "代", "涩"]], "18356": ["病机", "原文以“人迎脉大于气口”辨外感，人迎属胃经而主表，气口属肺经而主里。外感邪气袭表，经气奋起抗邪，故人迎脉大于气口；与内伤气口大于人迎相对，此以脉位大小判表里病机，非具体脉象描述。", []], "18357": ["病机", "原文论内伤劳倦之热，以手扪热分皮毛、肌肉、骨髓。尺脉数者，数主热，尺候肾，故为肾中真阴不足、虚热内生；若尺脉数而无力，则数而无力为虚火，非实热。原文“扪之烙手，骨中如炙者，肾中之真阴虚也”，与尺脉数相应，揭示阴虚发热之病机。", ["数"]], "18358": ["主病", "原文“上部有脉，下部无脉”为食填太阴、气机壅塞之食厥，非具体脉象写法。食积中焦，升降失常，阳气不能下达，故下部无脉；不急治则死，以探吐急去其食。若食积肠腹绞痛、手不可按，则审寒热而用巴豆丸或大承气急下，示食厥当分上下缓急。", []], "18359": ["病机", "原文以“左手脉不足”“右手脉不足”分气血虚实，左候血、右候气，脉不足即气血亏虚之象。丹溪以四物补血、四君子补气，佐竹沥、姜汁治痰，然持此法疗中风多不效，因只治气血痰之标而不知治其本，故原文强调当以阴虚、阳虚为主，求本论治。", []], "18360": ["病机", "六脉弦续而虚软无力，弦为风动之象，虚软无力则示气血不足、脉络失养。此脉说明正虚而风邪内动，虽未倒仆，但中风晕厥之候可指日而决。原文强调‘脉证之虚实’，两尺虚衰者补肾，寸关虚弱者补脾肺，可见脉之虚软处即元气亏虚之处，风由虚生，故当预防。", ["弦", "虚", "软"]], "18361": ["预后", "寸关如丝，两尺全无，上部有脉下部无脉。寸关如丝示气血衰惫、脉道不充；两尺全无则肾气已竭，下部无脉。经云‘其人当吐，不吐者死’，因宿食痰涎填塞太阴，气机不通，吐则气机得畅，故预后取决于能否吐。此脉象反映气血衰惫、食填太阴之危候。", ["细", "无"]], "18362": ["病机", "六脉沉伏，惟肝脉洪数。沉伏示气血壅滞、阳气不达；肝脉洪数则为阴中之伏火亢盛。原文谓‘此肾水枯竭也’，水不涵木，肝火挟痰上涌，故见口眼㖞斜、语言蹇涩、痰涎上涌、右手足不活。洪数之肝脉正是阴亏火旺之征，故治以滋化源、泻伏火。", ["沉", "伏", "洪", "数"]], "18363": ["预后", "六脉浮迟，乍有乍无。浮为阳气外越，迟为气血虚寒，乍有乍无则脉气断续、根本已亏。原文见头晕仆地、手撒鼾睡、气息如丝，此气血久枯、虚极欲脱之候。脉浮迟而乍有乍无，说明阳气浮散、脏气衰败，故虽得嚏而苏，终至一载无功而殁，预后不良。", ["浮", "迟"]], "18364": ["误治", "此段未直接描述脉象，但以‘脉散为夏月最宜’点出暑证脉虚散之常。香薷饮乃散阳气、导真阴之药，元气素虚或房劳过度者服之，更伤正气，为祸尤深。原文批评不究其因、不温其内而泛用香薷饮，致暑证卒殁、指甲青黯，属误治之害，故列误治。", []], "18365": ["病机", "热病脉盛，暑病脉虚，此为辨证之要。暑为阳邪，易伤气耗津，气液两伤则脉道不充，故脉虚。虚脉在此非单纯不足，而是暑热伤气、津气两伤之病机反映。原文强调‘斯为辨耳’，说明暑证与热证虽相似，但脉虚为暑病之特征，临证当慎辨。", ["虚"]], "18366": ["病机", "六脉微细而缓，惟右关弦紧而芤。微细缓示气阴两伤；右关弦紧为暑邪内侵、气机壅滞，芤则津气骤伤、脉道中空。原文谓‘暑邪侵入阳明之里’，故壮热大汗、烦渴饮冷；热盛神昏则晕眩不言。弦紧而芤正合暑热伤津、邪壅阳明之机，故用白虎加参耆以撤热补气收汗。", ["微", "细", "缓", "弦"]], "18367": ["病机", "六脉弦细而芤。弦为暑湿郁遏气机，细为气弱，芤则津血骤伤。原文谓‘此溽暑也’，暑湿伤中，故吐利发热、触痛甚。弦细芤并见，说明暑湿内侵而气阴已伤，故用益元散合四苓散清暑利湿，继以补中益气倍参耆加麦味，以顾其气弱。", ["弦", "细", "芤"]], "18368": ["病机", "原文论湿邪来源有在天、在地、饮食、汗湿及脾土所化，阳盛化湿热，阴盛化寒湿。所列证候如发热恶寒、身重自汗、筋骨疼痛、小便秘涩、大便溏泄、跗肿肉如泥，皆湿邪困阻气机、伤及肌肉筋骨血脉之象，故主病机为湿邪内蕴，随体质从化。", []], "18369": ["病机", "原文论喘与胀相因，皆小便不利。先喘后胀主肺，因肺失降令，水道不通，皮肤胀满；先胀后喘主脾，脾土受伤不能制水，水湿妄行侵肺。故病机为肺失肃降或脾失健运，水气内停，标本先后不同。", []], "18370": ["兼症", "脉浮大按之微细，两寸皆短，为虚阳外浮、脾肾元气不足之象。患者因误用行气消导分利，致咳嗽喘促、肚腹渐胀、足肿便溏，诸证由脾肾两虚、气不化水而成。脉浮大非实，按之微细更证实虚，故用补中益气、金匮肾气温补脾肾而渐愈。", ["浮", "大", "细", "短"]], "18371": ["病机", "两手脉皆虚微，右手微甚，为元气虚极、虚阳浮越之候。虽病热而舌焦黑、谵语撮空，似实热，然脉虚微无力，知非外邪，乃内伤虚极，阴寒内盛，逼阳外越。故用四物加参、耆、术、附温补，汗出热退，继进附子而安。", ["虚", "微"]], "18372": ["病机", "脉细而迟，为阳气虚衰、阴寒内盛之象。夏月病热而现此脉，口渴谵语似热，实乃虚阳外浮，真寒假热。故用四君子加归、芍、耆、附温补，初服热愈甚，脉如旧，仍增附子，终汗出热退脉复常，体现舍时从证、舍证从脉。", ["细", "迟"]], "18373": ["其他", "此段为按语，总结前证治法，强调“舍时从证，舍证从脉”，即不囿于时令与表象，而以脉症本质为凭。虽无具体脉象描述，但点明脉诊在辨证中的关键作用，示人临证当有定见，不为假象所惑。", []], "18374": ["误治", "脉洪数而无力，为内伤元气、虚阳外浮之象，非外邪实热。患者饮食劳倦发热恶寒，误用发表，致神昏胸发赤斑。洪数似热，无力则虚，故宜温补。其兄惑于斑疹，重投消斑化斑，终致殒命，此误治之戒。", ["洪", "数", "无", "力"]], "18375": ["预后", "原文引《总录》论消渴能食与不能食之传变，并言痈疽而渴，色黑或紫，为“火极似水”，乃肾水已竭，脉散之类主元气耗散，故属不治，惟峻补其阴或可挽救。脉散为根本已离之兆，预后凶险。", ["散"]], "18376": ["治法", "本段未言脉象，专论目病分证治法。以体倦少食、视物昏花、劳役益甚归脾胃虚弱，用补中益气汤；眵多紧涩、赤脉贯珠、脏腑秘结归肝经郁热，用芍药清肝丸；赤翳布白、畏热羞明、痛如针刺归上焦风热，用黄连饮子。午前甚痛属阳气不足，午后甚痛属阴火，能近怯远属肾虚，能远怯近属心虚，皆从症测机而施治。", []], "18377": ["病机", "本段无脉象，论目病本于脾虚与相火妄动。原文谓“五脏六腑之精气皆禀受于脾土，上贯于目”，脾虚则精气难周于目而多不明；又谓“相火，包络也，主百脉皆荣于目”，劳役运动则相火妄行，损血脉而目中诸病生。故治目当理脾健胃、养血安神，若概用辛凉苦寒，反伤真气而成内障。", []], "18378": ["病机", "脉大而虚，大为劳役耗气、虚为心脾两伤，故不任祛风散热之攻。原文载医用祛风散热药反畏明重听，正因脉虚非实火，攻之则气愈耗。劳心过度、饮食失节致中气不足，清阳不升则目赤不明。治以补中益气加茯神、枣仁、远志等，后以十全大补渐愈，皆从脉大而虚之虚象立法，非直散肝胆郁火之实证可比。", ["大", "虚"]], "18379": ["病机", "原文谓“男子寸强而尺弱，女子寸弱而尺强”，今诊得尺强寸弱，阴阳相反。尺强为下元虚而虚阳不敛，寸弱为上焦阳气不足，故见形体尪羸、双目昏暗、羞光怕日、阳事不举，已成虚劳。此非实强，乃本实先拨、阴阳倒置。治以补中益气加白菊、茯苓滋化源，继服四神丸加鹿茸壮水明目、填补精血，从尺强寸弱之反象培补下元。", ["强", "弱"]], "18380": ["主病", "两寸浮洪而溢，寸候上焦，浮洪为君相二火独盛、热正络，故主喉痹，与嗌干、嗌痛、喉肿、舌本强诸症相应。脉微而伏者，阳气衰微、伏匿不显，正不胜邪，故为死证。原文以“火”一字括喉痹之因，分君火势缓、相火势速，单乳蛾、双乳蛾、缠喉痹等皆热气结于外所致，脉之浮洪与微伏正判其顺逆。", ["浮", "洪", "微", "伏"]], "18381": ["病机", "脉微欲绝为阳气衰微欲脱之象，与下利清谷、里寒外热、面赤咽痛并见，是阴寒内盛、虚阳上浮之戴阳格局，非实火咽痛。原文指出冬月伏寒在肾经，发则咽痛下利，故用通脉汤、附子汤温经则愈。世医多知咽痛是火而少知是寒，此脉微欲绝正是辨寒咽痛之关键，与浮洪实火之喉痹判然不同。", ["微"]], "18382": ["预后", "尺脉洪数无伦，次按之微细若无，原文断为“有形而若无，戴阳证也”。洪数无伦为虚阳外越之假象，微细若无为真阴耗竭之本，阴阳离决故主死。患者本咽喉肿痛，针去血反伤阴血，峻补其阴已不及，是夜果殁。此案以尺脉洪数无伦而按之微细判戴阳死证，为粗工轻用刀针之戒，脉象直接关涉预后。", ["洪", "数", "微", "细"]], "18383": ["病机", "脉浮大而空，浮大为虚阳外浮，空为按之无根，非实热壅盛。原文断为太阴脾肺二经气虚，兼足太阳膀胱经虚热，故牙龈不时肿痛、针出脓血即已，乃气虚不能摄血、虚热上浮所致。素禀阳虚是其本，治以人参理中汤加山萸、山药温补中气而瘥，正合浮大而空之虚象，与实火牙痛之洪数有力者迥别。", ["浮", "大", "空"]], "18384": ["病机", "脉浮大而重取细涩，浮大乃真阳飞越于上，细涩为真阴虚极于下，阴阳不相维系，故痰结喉间。此非实火，乃本实先拨、虚阳上浮之候，去生已远，急宜独参汤固脱。", ["浮", "大", "细", "涩"]], "18385": ["病机", "尺脉数而无力，数主火，无力为虚，尺部应肾，此肾水亏损、相火无制而上炎，故咽喉肿痛、内热口干、痰涎上涌。治以六味丸加麦冬、五味，壮水制火而安。", ["数", "虚"]], "18386": ["病机", "脉浮大而数，浮大无力、数而不实，乃饮食劳伤中气，无根虚火上促所致。症见咽喉肿闭、痰涌喘促汗出、肢体痿软，皆中虚阳浮之象，故用补中益气汤加桂心引火归元。", ["浮", "大", "数"]], "18387": ["主病", "六脉俱实，按之有力，合咽喉肿痛、作渴饮冷、大便秘结，为实热壅盛之证。故用防风通圣散加减，重用硝、黄下之。然原文特诫虚热多、实热少，此方不可轻用。", ["实"]], "18388": ["预后", "失血证察五脏脉为据：心沉、肝浮、脾数、肺浮、肾沉，各主咯血、肠风、吐鲜、吐衄、淋血。脉沉小者生、身凉者生；脉大身热者死；吐后脉微可治，吐衄后脉复大而热躁急者主死，以脉证相反、阴竭阳浮故也。", ["沉", "浮", "数", "大"]], "18389": ["病机", "寒伤营，太阳少阴易感，皮毛先入而肺金先受。血亦水类，得寒则凝滞不行，随咳痰而出，症必恶寒，脉紧为寒邪束表之验，血中紫黑数点亦寒凝之征。误作阴虚火动、概用滋阴降火则日深，故以麻黄桂枝汤微汗而愈。", ["紧"]], "18390": ["主病", "伤暑吐衄，症见面垢、口渴喜饮、干呕、腹痛或发热，脉必虚，大汗出者，暑热伤气耗津，气不摄血而吐衄。脉虚为正虚之应，故用黄连解毒汤，甚者白虎汤清暑泻热。", ["虚"]], "18391": ["病机", "暑伤心，心气既虚，暑气乘虚而入，心主血，故吐衄。心虚无以生血，脉必虚，其人无气以动。过用寒凉泻心则益虚，宜清暑益气汤加生地、丹皮、犀角地黄，更以参、芪助气摄血。", ["虚"]], "18392": ["误治", "失血后大发热，六脉洪大，乃血虚阳浮之象，非实热。原文强调“阳旺能生阴血”，以当归补血汤主之。若误认白虎汤证而用发散或白虎，则危殆立见。洪大脉在此提示阴血亏虚、阳气外浮，不可作实火攻伐。", ["洪", "大"]], "18393": ["病机", "患者身受寒气、口受冷物，血得冷而凝，妄行吐血，其血黑黯，色白而夭，身清凉，脉必微迟。微迟为寒凝血脉、阳气不振之征，故当急用姜、桂温通，若误用凉血则殆。", ["微", "迟"]], "18394": ["病机", "原文述误食冷物、服凉剂后阳气复消，余阴再作，脉退而小、弦细而迟。小弦细迟示寒湿凝泣、阳气衰微，致吐衄、便血尿血，色紫不鲜，乃重沓寒湿化毒，浸溃水谷道路而成。", ["小", "弦", "细", "迟"]], "18395": ["兼症", "男子咳嗽吐血，热渴痰盛，盗汗遗精，劳则吐血，脾脉与肺肾脉皆洪数。洪数为阴虚火旺、虚火上炎之象，涉及脾肺肾三脏，故用归脾汤、六味地黄丸培补而愈。", ["洪", "数"]], "18396": ["病机", "原文论吐血、衄血同是上炎之火，分出于肺、胃、肾、脾，总由肾水随相火炎上之血。虽未出脉，然病机为相火妄动、迫血上行，肾脉上入肺循喉咙，故病则俱病。", []], "18397": ["病机", "怒气伤肝成吐衄者，唇青面青脉弦；郁气伤脾者，脉必涩。弦为肝郁气逆，涩为郁滞血瘀，郁则火不得舒，血不得藏而妄行，故见恶风恶寒、面滞喜呕等症，不可误作虚而温补。", ["弦", "涩"]], "18398": ["预后", "虚劳咳嗽，酒色沉迷后吐血不止，误用寒凉，脉小细数而微，其势将脱。小细数微为真阳受困、气血衰败之象，刻不容缓，示误治后阴损及阳、元气欲脱之危候。", ["小", "细", "数", "微"]], "18399": ["病机", "因怒气吐血，六脉沉小，惟左关弦细而数。沉小为气郁于内，左关弦细数为肝郁化火、怒气伤肝之征，郁气结于胸中，冲激而吐，故宜逍遥散舒肝解郁，不可强止骤补。", ["沉", "小", "弦", "细"]], "18400": ["预后", "脉小无力、乍有乍无，为血脱气随血耗之象，气不固血则崩中昏晕。然脉小身凉，是阴血虽脱而阳气未浮越，故断为可救。治以固气涩血，气固则血自不脱，正合‘血崩之后惟气独存’之旨。", ["小", "虚"]], "18401": ["病机", "六脉沉小，惟左关尺细数无伦，沉小为气郁不达，左关尺细数乃肝火炽盛、郁迫血海，故怒气填胸而血崩，痰涎上涌、四肢作逆皆肝火冲逆之兼症。先以逍遥散加黑栀、侧柏等疏肝凉血，继以六君子加柴胡、栀仁运中清火。", ["沉", "小", "细", "数"]], "18402": ["病机", "六脉沉小而微，手足厥逆，是久病吐血发热、肌肉瘦削之后，气血大亏，阳气衰微欲脱，故暴吐昏晕、周身俱冷、其气将绝。脉沉小为里虚，微为阳微，与‘独心中微温’相应，急用加味补中益气汤升举固脱。", ["沉", "小", "微"]], "18403": ["误治", "六脉沉小而微，势在将脱，前医误认吐血为热，肆用犀角、芩、连、知、柏寒凉克伐，致太少二阴中寒，真阳受困，血冲激而出。脉微身凉，孤阳将绝，幸未洪数身热，故以温中固脱挽回，一剂而苏。", ["沉", "小", "微"]], "18404": ["预后", "六脉沉微，是忿激暴吐、鲜血盈盆后气随血脱之候。身温脉微，阳虽微而未浮越，故引《经脉篇》‘脉微身凉者生’；若吐衄后脉洪数、身热，则孤阳外越，主死。此以脉之微与洪数对举，决失血之吉凶。", ["沉", "微", "洪", "数"]], "18405": ["预后", "白浊日久，误用渗泄寒凉，致脾肾肝三经失职，精无统摄，转加吐血、饮食俱困。按之沉小而微，是精气亏耗、孤阳将绝之候；然脉尚微小而未至洪数，故曰‘幸脉微小，天犹或永其寿’，以脉决其可治。", ["沉", "小", "微"]], "18406": ["病机", "六脉沉小，暴吐盈盆而面青、形神俱倦，是怒气伤肝，少阴、厥阴二脏受伤，肝尤甚。沉小为气血郁滞不升，故胸前背心微热、心中甚紧。先以逍遥散吞左金丸疏肝和脾，继以补中益气摄血归经，二剂血渐微。", ["沉", "小"]], "18407": ["预后", "大便下血三载，肌肉瘦削、白若枯骨，六脉沉微，是气血耗竭、势在将脱，故断为不可救。然竟以熟地、当归、川芎等养血涩血之剂获生，说明脉沉微虽主阳衰血脱，若胃气未绝、药力得助，犹可挽回，不可遽弃。", ["沉", "微"]], "18408": ["病机", "两寸浮大而空，余脉沉微，乃阴寒内盛、虚阳上浮之象。前医一味滋阴，致阴愈长而阳愈亏，故见声哑、咳紧、形神俱疲。脉沉微主三阴虚寒，浮大而空为阳气外越，非实热也。", ["浮", "大", "沉", "微"]], "18409": ["病机", "右寸浮大而空，左关弦细而数，余俱沉小，乃大失血后气随血脱、阴亏阳浮之候。浮大而空为血脱气浮，弦细而数为肝阴不足、虚火内扰，故吐衄盈盆、昏晕不省。", ["浮", "大", "弦", "细"]], "18410": ["病机", "右关微涩而芤，余脉如常，乃饮食所伤、脾胃气虚、不能传布，致停蓄吐血。微涩主脾虚血少，芤为失血之象，故先理脾涤饮，后大补中气而血止。", ["微", "涩", "芤"]], "18411": ["病机", "此段论梦遗病机，以肾肝为主。肾阴虚则精不藏，肝阳强则火不秘，不秘之火加临不藏之精，故梦即泄。引《灵枢》厥气客于阴器则梦接内，说明遗精与相火妄动、阴精失守相关。", []], "18412": ["病机", "脉紧涩，知冷药利水太过，阴气独降，阳气不升。紧为寒凝，涩为气滞血少，故梦遗多痰瘦削。用升提之法升坎水济离火，降阳气滋阴血，以鹿茸、人乳填补精血而愈。", ["紧", "涩"]], "18413": ["病机", "右寸浮大，右关微弦，左寸关俱沉微，两尺俱迟而芤，乃劳伤脾肾、气血亏损之候。浮大为中气不足，弦为脾虚木乘，沉微迟芤为肾阳衰、精血亏，故发热遗精、小便不禁。", ["浮", "大", "弦", "微"]], "18414": ["病机", "右寸脉大于五部，左尺沉迟而芤，乃浊气下降、清阳不升、中州郁滞、脾失健运，兼肾气涣散。右寸大主中气不足，左尺沉迟芤为肾阳亏、精血少，故遗精唾血，劳则遗精。", ["大", "沉", "迟", "芤"]], "18415": ["病机", "六脉已伏，惟右寸浮大乍有乍无，乃脱证已具八九之危候。伏脉主气机闭阻、阳气欲绝，右寸浮大乍有乍无为残阳浮越，故昏晕倒卧。经舒肝解郁、理脾涤饮而脉出如常。", ["伏", "浮", "大"]], "18416": ["病机", "六脉沉微示中气大虚、阳气衰微；右寸脉大而空为肺气虚浮无根，左尺迟细而芤乃肾气涣散、精血亏耗。脉证合参，见脱证已具、下利不收、屁无休息，皆脾肾气脱之象。虽病重，然面白唇红、声音清亮，生气未绝，故可大补中气、收固肾气而解。", ["沉", "微", "大", "空"]], "18417": ["主病", "脉大而虚、浮而濡，为大虚之象，浮濡主表虚不固。寸部见之则卫气不敛而自汗，尺部见之则阴不内守而盗汗。此以脉位分主自汗、盗汗，总由气血虚浮、腠理不密所致。", ["大", "虚", "浮", "濡"]], "18418": ["病机", "自汗属阳虚，盗汗属阴虚，此论汗证之阴阳属性。伤寒脉阴阳俱紧，为寒邪束表，法当无汗；若反自汗不止，则阳气外亡，名曰亡阳，故曰不治。紧脉主寒，今汗出而阳脱，脉证相悖，故预后不良。", ["紧"]], "18419": ["兼症", "内伤自汗属阳虚，主以补中益气汤加味。左寸浮洪为心火炎，故加麦冬、五味、川连；左关浮弦为挟风邪，故加桂枝、白芍；左尺浮洪无力为水亏火旺，故重加生地、熟地；右寸浮大无力为肺气虚，故加五味、枣仁；右关浮洪无力为脾虚，随证加减。此凭脉定位以分兼症。", ["浮", "洪", "弦", "大"]], "18420": ["病机", "梦遗滑精、发热盗汗，前医误用清滋、四物加知柏，致汗更甚。六脉皆浮，为气虚阳浮、卫外不固之象，非外感也。故用补中汤加麦、味、茯神等补气敛阳，兼服八仙长寿丸而愈。浮脉在此主虚阳外浮，不可作表证论。", ["浮"]], "18421": ["病机", "脉微如丝、按之即绝，为阳气衰微欲绝之候。症见神识不清、饮食不下、翕翕微热、濈濈微汗、昏眩少气，皆阳虚气脱之象。兴阳强良乃孤阳下陷、为阴所逼、阳从下竭之假热，非真阳强也。脉微欲绝，主病机为阳衰阴竭。", ["微"]], "18422": ["病机", "此段未出脉象，专论病本。引经“邪之所凑，其气必虚”“治病必求其本”，指出发热脸红、烦躁似有余，实为脾胃气虚不能传运；伤风感冒似实，因卫气不固；咳嗽喘促似肺热，实水不制火或虚阳上浮。总归虚为本、标为末，不可从标攻伐。", []], "18423": ["治法", "此段未出具体脉象，而言“必须凭脉用药，不可问病执方”。虚者宜补，然有不受补者，非不受补，乃补之不得其法。强调凭脉以辨虚实、定补法，反对执方问病，体现脉诊在治法中的指导作用。", []], "18424": ["病机", "原文以“六脉洪大有力”为真阴不足，龙雷之火妄作，故脉洪大而数；若“弦数、细数”则真阴真阳亏损。洪大为假阳乘之，非真阳盛实，故不可误用知柏地黄汤。脉之微缓为有神之常，反衬疾乱变常之病机。", ["洪", "大", "数", "弦"]], "18425": ["病机", "“六脉浮大无力”主中气不足、营阴有亏，失收摄元气之用。浮大无力为气虚不敛、营阴亏虚之象，故宜温补气血中加敛纳之味，如养营汤用五味子，更去陈皮之耗散。", ["浮", "大"]], "18426": ["病机", "“六脉沉细无力”为元阳中气大虚，脾胃气血化源不足。沉细无力示阳气衰微、中州不运，故大宜培补中州、温补气血，用辛温鼓舞药力，如归脾汤用木香、十全汤用肉桂，使药力不劳脾胃转输。", ["沉", "细"]], "18427": ["病机", "“六脉迟缓甚微”主元阳大虚，纯以挽救阳气为主。迟缓甚微为阳气衰微、鼓动无力之象，故轻则人参理中汤，重则附子理中汤，不得杂一阴分之药，盖阳可生阴，阴可化阳。", ["迟", "缓", "微"]], "18428": ["病机", "“六脉细数，久按元神”主先天、后天之阴阳并亏。细数为阴亏虚热之象，久按元神示根本亏损，故早服八味地黄丸，晚服人参养营汤去陈皮，或十全大补汤去川芎，生地换熟地，以双补阴阳。", ["细", "数"]], "18429": ["治法", "“肺脉洪大者”示肺气壅盛或虚火上浮，故用十全大补汤时芎、耆应去，麦、味应加。川芎辛升、黄耆甘厚功专肺脾固表，肺脉洪大不宜升补，加麦冬、五味子敛降肺气，体现因脉施治之宜禁。", ["洪", "大"]], "18430": ["治法", "“六脉无力”主气虚，十全大补汤最宜。无力服参者，倍用耆、术，只用当归，勿用地、芍，盖重在补气，当归为阴中之阳，地黄、白芍为阴中之阴，故去阴柔之品以专补气。", []], "18431": ["误治", "“六脉沉微”为亡阳之证，地黄汤暂所忌之。沉微示阳气衰亡，虽有桂、附之热，终属佐使，而熟地黄、山萸肉一队阴药乃系君臣，故能消阴翳之火，然过酸强于吞服便伤胃气，故亡阳时忌用。", ["沉", "微"]], "18432": ["治法", "原文以“生脉散之类为当”论治，脉散指肺虚清化之源绝，水不生津。虚劳汗多，五内枯燥，脂腴既去，不能生津，膀胱无水而小便不利。脉散主肺气耗散、津液不布，故用清金之药助秋令，使水自生，非见散即固涩。", ["散"]], "18433": ["妇人", "原文言妇人“诊其脉气无定，纺缉织纴之余，脉因而动，目瞑嗜卧之际，脉因而静”，说明劳逸动静可使脉动，非病脉。此段主妇人诊法之难，望闻问切皆受限，脉动因事而变，当悉心观变，不可执一。", ["动"]], "18434": ["误治", "原文“右寸洪劲无伦”见于秋燥伤肺、漏下清水，前医误作脾虚，用耆、术、砂、半温燥，愈助其燥而肺愈伤，终致喘促直视。右寸洪劲主肺经燥热炽盛，气逆下迫，非脾虚自利之脉，故误治致危。", ["洪", "劲"]], "18435": ["病机", "原文“依然右寸脉洪劲，皮色干枯，心烦不眠”，与上案同属秋燥伤肺。右寸洪劲为肺燥热盛、津液受灼之象，故用天冬、麦冬、玉竹、蒌仁、阿胶、鸡子白清肺润燥，桔梗开提，甘草和中，一剂而效。", ["洪", "劲"]], "18436": ["误治", "原文脉滑而数，症见身重恶寒、食不下、便泄、小便不利、腹中痞块作痛，庸工谬谓血气，用元胡四物汤加蒲黄，转加膨胀。滑数主阴寒凝结、阴邪逼塞，非血瘀实热，妄投血药则阴愈长而阳愈消，误破其气则气亏邪凑。", ["滑", "数"]], "18437": ["其他", "原文未识脉名，只言“另察其脉证在何经，即以何经之药施治之”。此段论卒然昏迷、颠仆身痛、有青筋之证，先以乱发搓痛处验发卷成团而硬，不愈则察脉证归经用药，脉象非本段重点，故脉象要素为空。", []], "18438": ["病机", "原文“脉续浮者”论疫病九传，先表后里，膜原伏邪先后溃传。脉续浮说明表证先见，伏邪先溃于表，宜先解表；表解已而里证后见，乃后溃之伏邪至。此脉主疫邪出表之机，非单纯外感表证。", ["浮"]], "18439": ["预后", "原文未出脉名，只言“应下之证，下后当脉静身凉。今反发热者，此内结开，正气通，郁阳暴伸，此不久自愈”。此段论下后脉静为顺，反发热为郁阳暴伸之暂象，预后自愈；若仍有余邪未尽，当辨表里以消悉之。", []], "18440": ["治法", "原文未及脉象，专论痧证治法三法：刮、放、药。指出痧在肌肤刮之而愈，痧在血肉放之而愈，二者尚浅；若痧深而重，胀塞肠胃、壅阻经络、直犯心君，则刮放难施，必以药救醒。强调三法兼备方可回生，脉象非本段主旨。", []], "18441": ["病机", "原文言痧胀则脉不对证、证不合脉，痧筋为据仅现于外。痧有食积、血痰阻于上下左右两胁之分，须认证的确。治痧见脉不合，先看痧筋，次审气色，三听声音，四问病由。痧脉有一部独异或六脉俱异，异中有阴阳寒热表里虚实可辨，非一端可执，强调凭脉须合痧筋诸诊。", []], "18442": ["其他", "此段仅为篇题「痧脉十二经辨」，标示下文将按十二经分述痧证脉象，本身无脉象描述与病机论述，故脉象要素为空，主旨归为其他，不作病机推断。", []], "18443": ["病机", "原文以脉辨痧在何经：脉芤而浮者手太阴肺痧，芤而数者手少阴心痧，弦长而动者足厥阴肝痧，芤大滑实者足太阴脾痧，沉细而动止不匀者足少阴肾痧。芤主血伤，浮数弦长动各应脏腑，故以脉之部位形态定痧邪所犯之经，为十二经辨痧之纲。", ["芤", "浮", "数", "弦"]], "18444": ["病机", "原文按病因分痧脉：伤食之痧脉多战动，伤血脉多芤滑，伤暑脉多洪滑疾数，伤风脉多沉微，伤气脉多沉伏或如雀啄，伤湿脉多沉细。痧证脉与诸证不同，杂证兼痧其脉必变、病必凶暴。故脉之变异反映痧毒与食、血、暑、风、气、湿相搏之病机。", ["动", "芤", "滑", "洪"]], "18445": ["病机", "原文论痧中于里，痧气壅阻、毒攻心膂，立时发晕，刮放皆不中用，强放仅得紫黑血点，示痧毒深而凶危立见。主张审脉辨证，辨明风、寒、暑、湿、燥、火、气血、食积、痰饮何因施治，候气血活动再放痧调治。本段未出具体脉象，重在痧毒内攻心膂之病机与救急。", []], "18446": ["病机", "原文指出痧证轻者脉固如常，重者脉必变异。若但据脉不识痧筋，势必据脉用药，而脉已多变，则实病变虚、虚病变实，不可恃。故脉证不合时，当认痧筋有无：有则据痧用药，无则据脉用药，并兼望闻问三法。说明痧重脉变、脉不可独凭之理。", []], "18447": ["主病", "原文治曹秉让遍身肿胀，势在危急，手足俱肿将逮胸腹，诊之脉微如丝，腿湾十指青筋交现。脉微如丝主气血虚衰、阳气不振，肿胀而脉微示正虚邪盛；青筋交现为痧毒瘀滞之征。刺出紫黑毒血、服宝花散及桃仁红花汤后肿痛消，印证虚中夹瘀、痧毒壅滞之病机。", ["微"]], "18448": ["病机", "两寸芤而散，余脉如常，重按歇指。芤主血虚，散主气散，寸部候心肺，暑热秽气触犯心君，致心气涣散、血行失守，故发晕昏迷。重按歇指为气机暂阻，非虚甚，与暑秽闭窍相应。", ["芤", "散"]], "18449": ["其他", "原文未识脉名，强调“必须审脉辨证”，以脉参合昏迷、痰喘、眼目上吊等症辨暗痧。痧毒内闭，气机壅塞，故见倏忽昏迷；痰喘眼吊为热痰上扰。脉诊在此为鉴别痧毒与它病之关键，非主病脉象。", []], "18450": ["病机", "六脉微细而伏，微细主气血不足，伏主邪闭气机。首夏发热口渴、昏迷上翻，暑热秽毒内闭心包，阳气不能外达，故脉伏；气血为热所耗，故微细。放痧出紫黑血，毒泄则脉复。", ["微", "细", "伏"]], "18451": ["病机", "原文未出脉象，而言“审肺、肾、脾三经之脉”。默默不语、语亦无声，乃痧气壅盛，热痰上升阻逆气管，咽喉闭塞。肺脉主气，肾脉主纳，脾脉主运，三经脉象可察痰热壅塞之轻重，以推病源。", []], "18452": ["病机", "左脉有力，右脉沉微。左候肝，有力为怒气伤肝、肝气郁实；右候脾肺，沉微为痧气阻塞、气机不宣。怒伤肝，痧毒乘之，肝经壅滞，故烦闷昏昏不言。刺放紫血，气机得通，脉乃复。", ["沉", "微"]], "18453": ["主病", "脉大而数实，大主邪盛，数主热，实主积滞。腹痛如绳绞，痧毒内结，热积大肠，腑气不通，故脉实大数。放痧不应，知非表闭，乃里实，故用乌药顺气汤加大黄下积而愈。", ["大", "数", "实"]], "18454": ["病机", "脉伏，主邪闭气机，阳气不能外达。盘肠绞痛，痧毒内攻，气血壅塞，脉道不利，故伏。刮放痧后稍愈，复绞痛，知积滞未净，脉伏非虚，乃实邪内闭，故用细辛大黄丸下之。", ["伏"]], "18455": ["病机", "六脉俱伏，刺痧后复诊沉实而上鱼际。伏为痧毒闭阻，气血不通；沉实上鱼际，为热痰内结，气逆上壅。头痛发晕沉重，痰热上扰清窍。先刺以开闭，后以清气化痰饮冷服，脉证相应。", ["伏", "沉", "实"]], "18456": ["病机", "左尺虚微，右尺洪实，脉且歇指，此痧毒中于肾经。左尺虚微示肾阴不足，右尺洪实为痧毒壅盛于下焦，歇指乃邪阻脉道、气血不畅之象。腰中强硬如板、发热烦躁、昏沉痰壅，皆痧毒内攻、肾经气机壅滞所致，故主痧中于肾之病机。", ["虚", "微", "洪", "实"]], "18457": ["病机", "左脉洪数，右脉似伏，洪数为热盛邪壅，伏为痧毒闭阻气机。身热、吐痰、胁痛、喘呕，皆痧毒内郁、热壅气逆之候。右脉伏而左洪数，示邪偏壅于右而热盛于左，故断为痧也，刺痧筋、服丸药而瘳。", ["洪", "数", "伏"]], "18458": ["病机", "脉多怪异，痰气壅盛，凶暴痛极，此三焦命门痧也。怪异之脉示痧毒深伏、气机逆乱，非寻常脉象可拘。痰壅痛极乃痧毒闭阻三焦命门，气血不通所致，故刺痧筋出紫黑毒血，以救苦丹等清解痧毒而愈。", []], "18459": ["病机", "左脉微细无根，乃痧毒为害。微细无根示正气虚衰、痧毒内陷，虽见烦热、头眩、目红肿如桃等热象，脉反微细，是毒盛正虚、脉不应症之候。眼珠突出、昏沉发晕，皆痧毒上攻清窍所致，故放痧不应，以解毒凉血之剂而安。", ["微", "细"]], "18460": ["病机", "六脉沉紧，是瘟痧为害也。沉主里，紧主寒主痛，寒热如疟、心腹绞痛、吐泻不已，皆瘟痧秽毒壅遏中焦、气机闭阻之象。沉紧之脉正合邪闭于里、寒凝气滞之病机，故用沉香阿魏丸及和脾宣化饮以辟秽化浊、通利气机。", ["沉", "紧"]], "18461": ["病机", "脉洪大无伦，胸腹绞绞痛极，喊叫几死，此痧毒壅盛、气机逆乱之候。洪大无伦示邪热亢盛、脉道壅迫，与胸腹肠胃绞绞作痛相应，乃痧毒内攻、气血壅滞不通所致，故放痧筋、服救苦丹等清解痧毒而安。", ["洪", "大"]], "18462": ["病机", "右脉俱伏，左脉洪大无伦，胸腹迷闷，作苦之极。右伏为痧毒闭阻气机，左洪大为邪热壅盛，左右脉象迥异，示痧毒壅遏、气血分布不均。迷闷苦极乃痧毒内闭、气机不通之候，故放痧、吐去新食、服蒲黄饮而愈。", ["伏", "洪", "大"]], "18463": ["病机", "脉细而数，犯喉疳证。细为阴血不足，数为热毒内蕴，细数并见示痧毒伤阴、虚热上炎。喉疳乃痧毒上攻咽喉、腐灼血肉所致，故放腿湾痧筋出紫黑毒血，服清凉至宝饮加减以清热解毒、养阴利咽而安。", ["细", "数"]], "18464": ["病机", "左寸沉细、右关无力，沉细为气血不足、脉道不充，无力则中气虚弱。重舌本多心脾积热，然脉不数不洪而反沉细无力，说明此证非纯实热，乃痧毒内闭、正气受困，故据证宜补而据脉宜凉，先放痧血泄毒，再以清凉兼川连清心脾，温凉服调护胃气，五日而痊。", ["沉", "细"]], "18465": ["病机", "脉微而紧，微为阳气不振、气血不足，紧主寒主痛、亦主痧毒郁闭。右耳肿痛日夜不安，似属热证，然脉不洪数而微紧，说明痧毒闭阻经络、阳气被遏，非单纯风热。故先放腿湾痧筋出紫黑血以泄毒，再服清凉至宝饮加减微温饮，使郁闭得开、毒去而安。", ["微", "紧"]], "18466": ["病机", "脉数急甚，数为热盛，急为邪势鸱张、正气受迫。发热面赤、痰涎如锯、两目上视、昏迷之极，皆痧毒内攻、痰热蒙蔽心窍之象，诸医不应正因未识痧证。故先与圆红散稍冷饮，继刮痧透毒，再以和脾宣化饮研细辛大黄丸微冷饮，使痧毒外泄、痰热下行而愈。", ["数", "急"]], "18467": ["病机", "右脉微弦、左脉沉细，弦主痛主郁，沉细为气血亏虚、痧毒深伏。筋骨疼痛卧床一载，诸医不应，正因痧筋闭阻经络、气血不能濡养筋骨。放腿湾痧筋出紫黑毒血，使伏毒外泄，再以圆红散、蒲黄饮加五灵脂、天丁温服，活血通络，四剂而愈。", ["弦", "沉", "细"]], "18468": ["病机", "脉浮紧而数，浮主邪在表，紧主痧毒郁闭、痰气交阻，数则为热。猪痫风六载，痰浊内伏、痧毒闭阻心窍，故发为癫痫。阅痧筋放之，毒血外出则脉乃平，可见紧数由痧毒壅遏所致。继以沉香滚痰丸微温汤饮，降气逐痰，痰去痧清，痫遂不发。", ["浮", "紧", "数"]], "18469": ["病机", "六脉紧伏不匀，紧主痧毒郁闭、气机壅塞，伏为邪深脉道不利，不匀则气血运行失序。羊痫风七载，痰浊与痧毒互结，闭阻心窍经络，故脉紧伏不匀。视少阳穴痧筋放之，毒血去则气机得通，再与沉香滚痰丸微温饮，逐痰降气，遂不再发。", ["紧", "伏"]], "18470": ["病机", "六脉俱微细而伏，与痘后余毒当沉紧有力者相反，故断为脉证不合。微细伏为气血内闭、痧毒深伏，非热毒壅盛。刺痧筋出紫黑血不应，再与荆芥金银花汤合和脾宣化饮稍冷饮而苏，后变痢疾，以归、楂、酒军入童便微温饮，通因通用而愈。", ["微", "细", "伏", "沉"]], "18471": ["病机", "孕娠七月闷乱不安、寒热交作，初诊脉尚未现，用药不应而渐昏沉，明早左脉俱伏、面色微黑，方知痧毒内闭、气血壅遏，脉伏不出。刺腿湾青筋出紫黑毒血，毒泄则稍安，继以桑寄生、红花、益母草等安胎活血，再以小柴胡加茯苓、归、地健脾养血而安。", ["伏"]], "18472": ["兼症", "产后七日周身疼痛、寒热往来、昏沉之极，而六脉乍隐乍现，脉不循常度、忽有忽无，非单纯产后虚损之象。中指无名指稍黑，为痧毒内闭、气血壅滞之征，故知兼痧。脉乍隐乍现正合痧毒阻遏脉道、气血不能接续之机，刺指放紫黑毒血后痧退，继以归术地芍加桃仁山楂益母草调补而安。", []], "18473": ["病机", "妇人隐疾多兼痧，最难认识，惟在审脉。脉不合者，谓脉象与所见症候不相符，如症似虚寒而脉反滞涩隐伏，即当疑痧毒内伏、气血被遏。此段强调脉诊为辨痧之要，脉症相违则秘问其夫以得隐情，庶不致误，是脉象不合常度即为痧毒内闭之病机提示。", []], "18474": ["病机", "血淋半载，头面手足俱肿，六脉洪大紧盛，热已极矣。洪大紧盛为热毒炽盛、气血壅实之象，然血淋日久兼通身浮肿，非单纯热淋，乃痧毒内蕴、热极气壅、水湿不化所致。放痧筋二十余针、用解毒之剂后肿痛俱消，继以补中益气、六味地黄调理，正合热毒兼痧之病机。", ["洪", "大", "紧", "盛"]], "18475": ["病机", "痢血日数十次、腹中绞痛、呕哕不食，六脉或迟或数、或时歇指。迟数互见、歇指不定，为痧毒壅滞、气血运行失序、脉道时阻时通之象，非单纯痢疾之脉。故断为秋痢兼痧，恐防危殆。放痧后痛略松，继以活血解毒、通下之剂，痢转鹜溏，终用兜涩大肠而愈。", ["迟", "数", "歇", "指"]], "18476": ["病机", "季秋患疟，发热痰嗽、烦闷口渴，左三部微涩数甚。涩为气血壅滞，数甚为热，左三部独显，示痧毒郁于血分。放痧后脉始弦紧，弦紧为痧毒外透、气机搏击之象，故仍与前药而诸证顿退。此段以脉由涩数转弦紧，说明痧毒由郁闭渐得宣达，疟兼痧之病机随之缓解。", ["涩", "数", "弦", "紧"]], "18477": ["病机", "心疼发热、吐涎沫蛔虫，右关沉细而紧，余脉洪数。右关候脾胃，沉细而紧为寒滞虫积内结、气机收引之象；余脉洪数为热邪充斥。寒热错杂、虫痧交结，故刺痧筋放紫黑血，与连翘薄荷饮痧退，仍寒热往来，再以小柴胡汤和解而热退身安。", ["沉", "细", "紧", "洪"]], "18478": ["病机", "七岁痧发痛极、头汗如雨，脉芤洪数。洪数为热盛，芤为中虚血少、脉道失充，示痧毒炽盛而正气已伤，故放痧不出、刮亦不起，痧毒深伏难透。与细辛大黄丸微冷服、荆芥防风汤透达，次日痧筋自现、血流如注，下死蛔结粪而愈，正合热毒内闭兼正虚之机。", ["芤", "洪", "数"]], "18479": ["病机", "遍身疼痛、背发一毒黑烂、指头黑色而恶热饮，脉沉微。沉微为阳气衰微、痧毒内陷、气血不能外达之象，故黑烂成背疽，乃痧变恶毒、误用冷围药所致。去围药放痧，俟痧气绝根，用参耆姜桂熟附子温托，外敷代刀散，黑变红而痊，示沉微脉主痧毒内陷、阳气不振之病机。", ["沉", "微"]], "18480": ["其他", "此段为游仙馆拜谒黄超凡先生并讨论《集注》经络绘图之文，全无脉象描述，亦不涉病机。文中'分经绘图，注明脉穴'之'脉'指经脉穴位，非诊脉之脉，故脉象要素为空。主旨属医籍考据与师徒问答，归入其他。", []], "18481": ["病机", "久咳失血，阴血已亏，脉道不充故细；寒热似疟、自汗过多，营卫交虚，气机郁滞故弦。弦细并见，非实邪之弦，乃营卫两虚、心肺不足之候。咳血与寒热自汗并作，正合气血两耗、卫外不固之机，故以补益心肺、调和营卫为治。", ["弦", "细"]], "18482": ["病机", "脉虚滑而右大于左，两尺空豁，尺主肾，空豁为肾元亏虚之象。少年阳道不举、溺浊遗精、寐多汗泄，皆真阴内亏、肾虚不固所致。滑非实热之滑，乃虚阳浮动、精浊下泄之征，故原文戒'未可徒作相火治'，当从补肾固摄着眼。", ["虚", "滑"]], "18483": ["病机", "脉虚数为阴亏而虚热内生，两关坚锐则肝木郁而化火，坚锐即弦劲不和之象。阴虚为本，火郁为标，故曰'阴虚复多火郁'。治法心肾宜补以滋水制火，肝脏宜疏以解郁达木，补疏兼施，正合虚数兼坚锐之脉机。", ["虚", "数", "坚"]], "18484": ["病机", "左弦涩为肝血郁滞，右弱为肺气不足。肺主出气、肾主纳气，气虚则阳不下达，金不制木，木反乘金，故咳嗽、浮肿先见于身半以上，继以失血。弦涩弱并见，示本虚标实、气机升降失司，治宜滋肝益肾、纳气归元，不可徒作相火。", ["弦", "涩", "弱"]], "18485": ["预后", "风温初起即谵妄自汗，脉沉细数促，已半月而误汗误下，左脉细乱、右脉断续，更见口开目闭、唇板舌焦、不语失溲、头顶强直、手足拘挛，皆阴气不荣、阳邪郁伏、枢转不利之坏症。脉乱促断续为正气溃散、清浊升降失度之兆，故断为难治。", ["沉", "细", "数", "促"]], "18486": ["预后", "湿温蓄热发黄，脉数无神，数而无力无神，是阳邪劫伤心荣肺卫、正气日溃之象。便闭二旬、肠胃枯燥、府气不通，神昏头汗，内不守外不固。脉数本主热，然无神则正不胜邪，延久邪火固踞，有正邪交脱之虞，故属危候。", ["数"]], "18487": ["预后", "风温风证而脉躁神狂，躁为阳邪鼓动、血气流行失度之象；邪风被火，搏击营分，故胸腹胀闷、身半以下痛难转侧。妊娠五月，正虚邪盛，脉躁神狂示邪热内扰、胎元受迫，故有胎堕之虞，属危险之候。", ["躁"]], "18488": ["病机", "左关弦结搏指，为厥阴肝气郁结、脉道不利；两尺微细欲绝，乃少阴肾阳衰微、根本欲脱。原文以齿舌喉闭、腹痛吐蛔为少阴厥阴见症，正因肾虚水无坐镇之权，龙雷之火上浮，故见肉𥆧筋惕。脉弦结与尺脉欲绝并见，提示本虚标实、阴阳不相维系，若不回阳固本，则虚虚之祸难免。", ["弦", "结", "微", "细"]], "18489": ["主病", "脉数口甜，善食易饥，渴饮便数，原文断为过啖肥甘、积久酿热所致之脾瘅。数脉主热，热灼脾阴则脾阴亏而邪火亢，故消谷善饥、渴饮；火烁津液则便数。脾土主诸阳之本，阴亏火亢则肢节酸、背痛。议玉女煎加辛香荡涤陈气，正是针对脾瘅热盛阴伤之机。", ["数"]], "18490": ["病机", "心脉涩为心阳虚而血行不畅，胃脉滑为痰浊内壅，两尺微示下元不足。原文谓气升兀兀、鼓动咽喉、窒塞多痰、嘈杂吞酸、汗多面赤，皆心阳不足、虚火上浮、肺燥郁而清肃不行之象。气火炎烁则道路不利、津液日消，故以清燥汤法润燥降逆，脉涩与滑并见，正虚与痰火错杂之征。", ["涩", "滑", "微"]], "18491": ["病机", "左脉细弦，为肾精肝血内损、肝失柔养；右寸关短滑，示脾肺之阳亦亏而痰浊内停。原文以睪丸漏卮有年、腰脊牵引酸痛，明言肾精肝血已自内损；今食减咳逆多痰，则脾肺阳气不足、运化失职。细弦主虚损，短滑主痰滞，故先崇土固金以治中上，后补下焦，标本缓急分明。", ["细", "弦", "短", "滑"]], "18492": ["病机", "酒湿酿热，多饮则肝浮胃胀，咳血半月而脉已弦细。弦为肝旺，细为阴伤血少，酒客伤中，湿热内蕴，阳络损伤，血逆不归经络，故咳血。病在肝胃二脏，弦细并见说明肝胃不和而阴血已耗，非单纯实热，故不可峻攻，当于清化之中顾护阴血。", ["弦", "细"]], "18493": ["病机", "血症而脉弦大空豁，弦大为阳亢气火升动之象，空豁则阴亏血虚、脉道不充。原文谓少年阳亢阴亏，血随气火升动，正合此脉。弦大非实，空豁非虚，乃阴虚阳浮、气火迫血妄行之机，故急宜凉肝滋肾，引血归经，使火降则血自宁，再商进退治法。", ["弦", "大", "空", "豁"]], "18494": ["病机", "头目眩运空痛，脉虚弦无力，两尺微涩。虚弦为肝郁血燥、虚风内动，微涩为精髓内枯、肾阴不足。原文谓木郁生火，风自火出，虚风郁火上乘高巅，脑为髓海而肝胆之络络于脑，故眩运空痛。此非外感，乃内伤精血枯槁所致，法宜滋肝养阴、息风降火，兼以开畅情怀。", ["虚", "弦", "微", "涩"]], "18495": ["病机", "脉左细涩，右虚滑，肢节酸疼、腿足麻木不仁而患偏于右。左细涩为肝血枯少、血行不畅，右虚滑为脾运失健、浊痰凝聚。原文谓男子中年后精血易枯，肝风鼓动，脾失健运，浊痰凝聚清阳，胸脘噎塞，此偏风血槁之渐。细涩与虚滑并见，正虚风痰浊交杂之候。", ["细", "涩", "虚", "滑"]], "18496": ["病机", "脉弦滑，右关独大，弦主风，滑主痰，右关候脾胃，独大示风痰郁滞中焦。经络郁久生火，火与风合，上凌空窍，蒙蔽清阳，故头目眩冒、神不健爽；风痰流注下焦，则腿股酸痛。此脉象揭示风痰郁滞、化火上扰之病机，治当降火豁痰，风自愈。", ["弦", "滑"]], "18497": ["病机", "脉数弦滑，数主火，弦主风，滑主痰，三脉并见，示痰火内滞、风邪外触。痰火内蕴则脉数滑，风邪外袭则脉弦，内外合邪，病机为痰火为风邪所引动。原文直言“痰火内滞，风邪外触”，脉象与病机相应，当治痰火兼疏风邪。", ["数", "弦", "滑"]], "18498": ["误治", "原文述劫夺强汗致木燥火炎、营血耗、君相动而精泄不固，乃误汗伤阴之变。交长夏火土司升，烦躁、面庞精采外越，为虚阳外越之兆，须预防狂乱。引仲景太阳条火迫劫汗亡阳惊狂起卧不安为证，仿复脉汤意救逆。此段主旨为误治致变，脉象未识，故脉素为空。", []], "18499": ["病机", "脉左弦数，右关滑大，弦数主肝风火旺，右关滑大主脾胃痰热。风横脾胃，煽灼中土，致谷食不能荣长肌肉，故善饥肉脱。经云“二阳之病发心脾，其传为风消”，子病累母，藏病连府。脉象揭示风火痰热交炽、脾胃受灼之病机，仿河间法清火熄风。", ["弦", "数", "滑", "大"]], "18500": ["病机", "右脉微弱，左弦细，微弱主气血虚，弦细主肝风内动、阴血不足。木燥血枯，肾阴虚损，肝风内动，火灼津液，气壅生痰，阻塞隧道，故项强肢挛、语言艰涩。经云“诸风掉眩，皆属肝木”，木失水滋，母病累子。脉象示本虚标实、风痰阻络之病机，治以甘寒标本兼施。", ["微", "弱", "弦", "细"]], "18501": ["兼症", "原文述神脉稍清、语言略爽，而痰涎挛痛仍复如前，引经云肝痹善痛、肾痹善胀，肝肾血痹，筋骨焉能流利。此段重在兼症变化与转归，脉象未识，故脉素为空。病机为肝肾血痹、筋骨失养，仍从前法加减缓调，属兼症与治法相兼之段。", []], "18502": ["预后", "左脉短数，较甚于右，短主气损，数主虚热，因去血过多，气亦无附，故肢体虚浮、倦卧痿弱。交夏至节前后，阴阳升降之大关，吉凶由此而系，宜加意慎之。脉象示气血两亏、虚阳浮动之病机，而段末强调节气关口的吉凶转归，故主旨归为预后。", ["短", "数"]], "18503": ["病机", "诊脉沉而有力，舌焦身汗，神昏壮热发斑，晦滞坚满，二便闭结，适合伤寒下格、邪气内盛、脉反郁伏之说。沉而有力主邪实内结，热郁于里，故脉反郁伏。羌防辛散徒耗其阴，于里症无与，急当苦以泄之。脉象揭示邪热内盛、郁伏于里之病机，治当苦泄里实。", ["沉"]], "18504": ["病机", "左脉细弱为阴血不足、肾虚腰痛之根；右寸滑大为风热客邪袭伤肺络之象。细弱与滑大并见，示本虚标实：下焦肝肾亏虚故腰痛，上焦肺络受风热故右寸滑大。原文'风热客邪，袭伤肺络'点明病机，故先议清凉清上，先治其标。", ["细", "弱", "滑", "大"]], "18505": ["病机", "弦主少阳枢机不利，细为邪郁阴伤，数为热象。寒热胁痛乃少阳经气不舒之症，脉弦细数正合'邪郁少阳不清'：邪在半表半里，枢机郁滞则弦，郁热伤阴则细数。脉症相参，病机在少阳郁热，非单纯表证。", ["弦", "细", "数"]], "18506": ["预后", "病过两候而脉不缓和，是正气未复、邪热未退之征；舌干为津伤，鼻鼾为热扰神明，上哕下泄示脾胃升降俱乱。脉失和缓之常，与诸症并见，故断为'非退象也'，属病势未衰、预后堪忧之候，非平脉可比。", []], "18507": ["病机", "浮主外邪在表，弦主经气不舒。寒热头痛、经脉不舒，正是风热外客两阳（太阳、少阳）之象：邪袭肌表则脉浮，经气被郁则脉弦。原文'风热外客两阳'点明病位在表之阳经，脉弦浮与寒热头痛相呼应，主外感风热。", ["弦", "浮"]], "18508": ["病机", "弦主少阳寒热似疟，滑主痰积；右关独大，关候脾胃，示中虚而积痰内盛。肢体麻木不舒为痰阻经络。原文'虽外感风热，然中虚向有积痰，尤宜兼顾其里'，说明脉弦滑右关大揭示本虚标实、外感引动宿痰之病机，治当表里兼顾。", ["弦", "滑"]], "18509": ["病机", "浮为风邪在表，数为热，弦为络脉拘急。风热之邪外袭，伤及肺胃之络，故脉见数浮弦。肺主皮毛、胃主肌肉，风热客于肺胃络脉，脉浮数应表热，弦应络脉受邪不舒。原文'风伤肺胃之络'即此脉所主之病机。", ["数", "浮", "弦"]], "18510": ["治法", "本段未载脉象，纯为方药：复脉汤加天冬、茯神、玉竹、鲜生地，去麻仁、大枣。复脉汤本为脉结代、心动悸而设，此处加减偏于滋养阴液、清心安神，去麻仁之滑、大枣之壅，加鲜地、天冬、玉竹以润燥生津，属治法范畴，非脉象主病之论。", []], "18511": ["病机", "细为阴血不足，涩为气滞血瘀。少腹胀如复杯、便闭，是太阳府热结、血蓄下焦之征；舌燥渴饮、躁狂为心阳火炽。原文'心阳火炽，藏病连府，气不宣化，致手足太阳之府俱热结'，脉细涩正合瘀热内结、血行不畅之机，故议桃核承气汤逐瘀泻热。", ["细", "涩"]], "18512": ["病机", "脉虚滑数而两尺细微，虚为久病羸弱、肝肾式微，滑数为痰火内迷，细为阴不交阳、胞络空虚。虚中夹实，故痰火乘虚厥动、精识蔽蒙、语言失绪。脉象揭示阴亏于下、痰火扰于上之病机，治当早安神志心肾、晚涤痰火。", ["虚", "滑", "数", "细"]], "18513": ["预后", "病后虚风柔痉，精气内灼，汗泄不止，卫阳失护而气易外浮，筋脉失荣则手足振掉，神志失守则口噤不语。脉涣无神、直视失溲，脉症俱系散脱，散为元气离散之象，故断势已难挽，属危重预后。", ["散"]], "18514": ["治法", "原文仅言脉散而用生脉散频灌。散为气阴耗散、脉气不敛之象，故以生脉散益气敛阴、固摄脉气。此段以脉散为据立法，属治法范畴，示脉散者当急敛其耗散之气阴。", ["散"]], "18515": ["病机", "脉涩细数、两尺无神，涩细为阴气下虚、阳浮上结，数为五火挟痛亢胃。初起咽喉肿痛，继则暴中跌仆、呕吐黑血，乃痰火秘结于上、本气衰脱于下。水源不清则关门不禁，遗溺便泄，脉象示上实下虚、本衰标急之险途。", ["涩", "细", "数"]], "18516": ["病机", "努力负重伤中，气结不舒，脘痛按之有声。脉左细右弦、两尺空豁，细为气血不足，弦为肝脾两伤、气血痹阻其经，空豁示下元亏虚。痛久肝脾两伤，水饮溢于膜外而为病，故主调气和络缓图。", ["细", "弦"]], "18517": ["病机", "关脉弦、尺脉弱，弦主肝邪，弱主肾虚。腰脊痛、少腹胀、气从左胁下绕脐攻逆，皆浊阴凝聚下焦、肝肾见症。关弦尺弱正合肝肾不足、阴寒内聚之病机，故议温柔通剂以温养肝肾、通散浊阴。", ["弦", "弱"]], "18518": ["病机", "胁痛脘闷、气塞不通、日晡烦热、小便赤色而脉弦数。弦为肝木张，数为火旺，水亏木张则肝火上乘脾土，交春夏木火升腾而前病复来。脉弦数正示水亏火旺、肝脾受乘之病机，故暂拟疏泄。", ["弦", "数"]], "18519": ["病机", "病起左胁，上及中脘，下趋少腹，脉弦结歇止。弦为肝邪用事、胆阳不舒，结与歇止为气血痹阻、冲突其间而脉行不畅。症脉相合，示胆阳不舒、肝邪犯及气血之病机，故宗通则不痛之意治之。", ["弦", "结"]], "18520": ["病机", "脉数弦芤，数主热，弦主肝，芤主血虚失血，合为肝肾真阴内损、阴虚阳搏，血动下溢而淋漓。脉缓弱则火渐降，血可引归经。然汗多食减色夺，乃阴虚阳无所附，急宜补气通血，勿徒见血投凉。", ["数", "弦", "芤", "缓"]], "18521": ["病机", "脉虚弦不和，两关尤大而涩，虚为元气不足，弦为肝胆阳郁，涩主血少气滞，大则中州壅塞。此因过服滋阴寒凉，脾胃窒塞，升降无由，肝脾两脏同病，故成胀满之候。", ["虚", "弦", "涩", "大"]], "18522": ["治法", "咳逆浮肿而脉得弦数，弦主风水相搏，数主热，乃风水郁热之证。宗仲景越婢汤法，发越水气、清透郁热，使风从外解，水从下行，则咳逆浮肿自平。", ["弦", "数"]], "18523": ["预后", "脉缓嗽减，缓为胃气渐和之象，嗽减则肺气肃降，知风水已退。病势向愈，故从脾肺两经调养，培土生金，以善其后。", ["缓"]], "18524": ["病机", "脉来微弱无神，右尤甚，微弱为气血式微，右主脾肺。脾损不能散精于肺，胃损不能司肾关钥，中焦窒塞，升降无由，决渎不宣，水湿泛滥，故成肿胀。总由中央孤藏无气，不能灌溉四旁。", ["微", "弱"]], "18525": ["主病", "脉弦细，弦主肝积，细主血少气滞。左胁坚大如盘，乃痰裹气凝血结，结于肝之募原，为五积中之肥气。弦细应肝，坚大如盘应积块，故主此病。", ["弦", "细"]], "18526": ["主病", "脉浮弦，浮主虫动不安，弦主痛主积。神色痿弱、睛明穴黑滞，乃虫积耗伤气血；腹痛喜食香味、寐则肠鸣，皆虫扰之征。脉症合参，故断为虫积为患。", ["浮", "弦"]], "18527": ["病机", "脉沉细，沉主里主寒，细主虚。肾肝交损，阴中之阳内离，健运不司，故食减腹胀。此藏寒生满之渐，宜温通宣补，以复中阳。", ["沉", "细"]], "18528": ["病机", "脉迟弦滑，迟为气机壅滞，弦主木郁克土，滑为水谷壅闭成痰。原文谓\"思郁结，气陷于土\"，脾不升胃不降，水谷之海壅闭，故纳食则胀痛猛甚、上引胸胁。弦滑并见，正合木郁土壅、痰食内停之机，故治宜疏木达土，取《内经》胜克之旨。", ["迟", "弦", "滑"]], "18529": ["病机", "脉弦细而迟，弦为木郁胁痛，细为土衰少生化之权，迟属中阳不振。原文谓\"戊无火不运而痛斯作\"，土衰则纳谷生津失职，故吞酸脘痛、妨于饮食，兼嗽血乃金水交亏。此非徒下元虚，实中州窒塞，故宜温中辛散佐苦甘淡泄，若徒补下元则脾藏愈窒。", ["弦", "细", "迟"]], "18530": ["病机", "本段未出脉名，纯论病机。原文谓\"真阴亏，相火动\"，精不能养神，阳虚阴必走，故梦泄不固；耳为少阴少阳寄窍，精不守则龙雷不宁，上扰清空致耳鸣震动，属上实下虚。法当厚味填阴、介类潜阳，取\"下病治下\"之旨，与脉象描述无涉。", []], "18531": ["病机", "心脉细数劲，细为阴亏，数为火动，劲乃肝阳左升太过；两尺微弱，肾母收摄少权。原文谓\"阴不交阳，心君妄动\"，故耳鸣失聪、梦多遗泄。劲脉见于心部，正示肝阳上僭、肾不纳摄之上实下虚格局，故以填补下元、导引静镇为主。", ["细", "数", "劲", "弱"]], "18532": ["病机", "久泄必伤肝肾之阳，腰痛而脉数，原文断为\"水亏不能制火\"。数脉本主热，然久泄伤阳、水亏火浮，此数乃虚火不敛之象，非实热。腰为肾府，水亏失养故痛；火不制则脉数。寥寥数语，点出久泄致肝肾阳伤、水亏火旺之病机。", ["数"]], "18533": ["病机", "脉细弱，细为气衰，弱为力倦，正合\"劳倦伤中\"。原文引\"中气不足，溲为之白\"，中气亏则清浊不分，故淋浊便溺作痛。细弱之脉主气虚不运，非湿热实邪，故病本在劳倦伤中、气化无力，与淋浊溺痛之症相应。", ["细", "弱"]], "18534": ["病机", "脉数大按之微弦，数为热，大为湿热交蒸，弦为脾阳不舒。原文谓\"浊阴下陷膀胱\"，致便浊精遗、溺痛。数大示湿热壅盛，微弦示土郁木乘，湿热下注州都，故以淡渗苦泄为治。此脉此症，正合湿热困脾、浊阴下陷之机。", ["数", "大", "弦"]], "18535": ["病机", "脉至弦数，两尺细涩。弦数为木火偏亢，细涩为少阴肾藏有亏、精血不足。原文谓\"太阳府气不化\"，故小便淋沥、精随溺泄。尺部细涩正示肾亏，肾亏则气化失司，膀胱不利，用滋肾丸方法，取滋肾以化太阳府气之意。", ["弦", "数", "细", "涩"]], "18536": ["病机", "原文未明言脉象，但述“脉症气结在上”，症见中脘阻塞吐涎、食阻痛呕、漉漉有声。此因中年后阴气先亏，津不运行，聚液成痰，闭遏胃阳，气结于上，故见阻塞吐涎；胃阳被遏，稍食即阻痛欲呕，漉漉有声为痰饮内动。此属噎膈渐成之机，病位在胃脘，与阴亏痰阻相关。", []], "18537": ["病机", "脉左涩右滑，左涩主营血内枯，右滑主痰火内盛。酒客伤中，胃阳痹阻，燥火易动，气逆胸痞吐痰，食入噎塞，大便燥结。涩为血少，滑为阳盛痰聚，上焦不通则上下脘不行，老年阴液已亏，怕延关格，此脉症示痰火痹阻、营血枯涸之机。", ["涩", "滑"]], "18538": ["治法", "原文仅载丸方金匮肾气丸，用生脉散加白蜜汤送下，未述脉象。此为治法，以肾气丸温补肾阳，生脉散益气养阴，白蜜润燥，送下以缓图。虽无脉症，然从方测证，当属肾阳不足、气阴两虚之噎膈，治在温补下元、益气生津。", []], "18539": ["病机", "脉左搏右平，左搏为肝气亢盛，右平示胃气尚和。恚怒伤肝，肝厥乘胃，血不藏聚，呕吐见血，阳明大络亦损，阳络伤则血外溢。食下噎塞、痛连胸腹，皆肝厥犯胃、气逆血溢之象。脉左搏独显，正合肝病及胃之机，故用柔剂缓调。", ["搏"]], "18540": ["病机", "脉右滑左涩，右滑为阳盛，左涩为肺象，金刑木位，胆阳不舒。积怒动肝损营，燥气乘复，上噫气下泄气，血少藏聚流而不行，痹阻厥阴，故喉不利、胁痞痛、脘中迷痛、食减液消。值疟后余邪未尽，先宜清暑和标，再商治本。", ["滑", "涩"]], "18541": ["治法", "原文仅载四君子汤合生脉散，未述脉象。此为治法，四君子健脾益气，生脉散益气养阴，合用以补气阴之虚。从方测证，当属气阴两虚之证，治在健脾益气、养阴生津，以缓调其本。", []], "18542": ["病机", "脉至细小涩数，细小为阴血亏少，涩为血行不畅，数为虚热内扰。咽喉肿胀、气塞眩冒、心烦汗泄、食减便溏，皆心脾之亏，由肝肾内损，阴心亢逆，上凌少阴循经之地。归脾虽当，泥于心脾，于少阴肾藏有间，当兼顾肝肾。", ["细", "小", "涩", "数"]], "18543": ["妇人", "原文未识别脉名，述久淋久带必伤肝肾之阴，致奇脉交损，腰脊垂痛，维纲不振，寒热交作。女科以肝为先天，宜柔剂缓调以和八脉。此属妇人久病，肝肾阴伤，奇经八脉交损，冲任不固，故淋带不止，腰脊痛而寒热交作。", []], "18544": ["病机", "咳血而脉弦，弦为肝脉，主肝血失藏，气逆于上；肺气不降，血随气升而咳血。此脉象揭示肝肺同病，肝失疏泄、肺失肃降，故从清阳治法，以升清降浊、调畅气机。", ["弦"]], "18545": ["病机", "血脱日久，阴气难复，营虚失守，督脉亦伤，故脊膂微痛；平旦口苦舌干，脉反见数，数主热，此非实热，乃阴液内损，君相之火易升动，虚热内生之象。", ["数"]], "18546": ["病机", "左脉小弱，右寸滑大，小弱为虚，滑大为痰，髫年喘症数载，遇劳感寒即发，风痰结于肺底成窠囊，阻塞空窍，清肃不行；肺病传三焦，少阳气分用事时喘促更甚。", ["小", "弱", "滑", "大"]], "18547": ["治法", "此段为方药，无脉象描述。海浮石、马兜铃、杏仁、桑皮等化痰降气，晚服复脉汤和阴，体现化痰定喘与复脉和阴分时论治，与上段脉案相承。", []], "18548": ["病机", "久嗽脉数，数主热，食减骨蒸，得自产后，阴亏蓐劳之渐。产后阴血亏虚，虚热内生，灼肺则嗽，伤脾则食减，阴不制阳则骨蒸，脉数正是阴亏火旺之征。", ["数"]], "18549": ["预后", "大风胀满脉多沉迟，按之有神为有胃气；今沉细如丝、寸关歇止，知谋虑伤肝，延及心脾，血不流、食不化，胶滞成痞块，暴腹胀大如蛊。脉无胃气，预后不良，姑进参附理中冀谷食渐进。", ["沉", "迟", "细", "结"]], "18550": ["病机", "左弦劲而右细涩，弦劲为肝气横逆，细涩为精血内枯；气逆从左上升，引胸脘闷痛，食下噎塞，高年精血枯，恼怒动肝，横逆中土，上凌肺下侵肾，致咳呕便闭，清阳不升浊阴不降，关格之渐。", ["弦", "劲", "细", "涩"]], "18551": ["预后", "怒则气高，阳气薄厥于上，神蒙窍蔽；向有厥症，痰随气火上胃，胸闷口噤耳聋神愦。今发五六日，心下痞满，脉微色脱，两颧时红，乃气未平而神已耗，下虚本实先拨，从少阴厥阴两治。", ["微"]], "18552": ["病机", "痢久不止而脉见细数，细为阴血亏少，数为虚火内动。原文谓“少阴肾虚，亡血失精之象”，因久痢耗伤肾阴，阴不制阳，相火侵凌，上炎下夺，津液告竭，故又作渴；脾火不化，不能食。此脉示肾虚火炎、阴精欲竭之病机，非实热痢疾可比。", ["细", "数"]], "18553": ["病机", "少年火盛，心肾不交，梦多走泄或无梦自遗，颧赤脉数，全属阴虚。数为阳热之象，此数乃相火妄动、精气不固所致，玉关不闭，虚火扰精。脉数与颧赤并见，说明阴虚火旺、精关失守之病机，治宜壮水制火，不再动其火。", ["数"]], "18554": ["病机", "原文未出脉名，述太阴厥阴之络为寒气引痛，致项强舌卷、语言似乎蹇涩。其邪由府及藏，气不外卫，血不内营，风邪并入于心，沉著于络，无阳以煦之，故不条达。此段论阴寒滞络、阳气不煦之病机，当治八脉为病。", []], "18555": ["病机", "六脉弦大搏指，足征平素火必有余。弦为肝强，大为胃盛，肝强胃盛，内伏之火挟外来之风，致口眼㖞斜、头目不明，清阳之分经络为风所中。此脉示肝胃火盛、风火相煽之病机，然原文谓在上之风乃实邪，缓散自出。", ["弦", "大"]], "18556": ["病机", "腹胀甚于少腹，按之坚急，大便泄，小便少，脉虚细。虚细为阳气不足、阴寒内盛之象。原文谓“皆阴寒凝结，厥气在下而单腹膨满”，阴寒凝结下焦，厥气上逆，故腹胀坚急而二便失常。此脉示阴寒内结、阳气虚衰之病机，当用温通之法。", ["虚", "细"]], "18557": ["病机", "肝脾素郁，气血素亏，清浊混乱，窒塞中焦及小腹，足膝脉络不仁，食减吞酸，乃木来侮土。按脉皆微，原文谓“真阳不运，阴凝阻遏，致𪱥郁不宣”。微脉主阳气衰微，真阳不能运化，阴寒凝阻，故胀满不宣。此脉示真阳不运、阴凝气郁之病机。", ["微"]], "18558": ["病机", "脉微腹胀，小腹上逆，即经云“厥气在下，营卫留上，真气逆上，正邪相攻而为胀”。微为阳气衰微，产后下焦空乏，寒从此入，致气不行。此脉示下元虚寒、厥气上逆之病机，故拟宣通兼温下元，取宣可去壅、通可去滞、温可去湿之义。", ["微"]], "18559": ["病机", "三疟之后，中脘痞结，气郁生痰，痛呕少食，经水愆期，来时作痛且呕，甚至经逆不调，脉细并涩。细为血少，涩为气滞血瘀。原文谓形气未弱，血则有余，而气太郁，色紫有寒，因血积胞门或凝子宫，冲任不荣，经年不孕。此脉示气郁血滞、冲任不荣之病机。", ["细", "涩"]], "18560": ["病机", "原文“脉象略和”为模糊描述，非具体脉象要素。少腹痛处高突已平，示局部浊阴稍散，但交阴气冲、浊阴之邪上干犯胃，故脉虽略和而病机未解。脉象略和反映邪势稍缓，然上冲之势仍在，主浊阴犯胃、气机逆乱，需渗利以清肃上焦。", []], "18561": ["病机", "脉皆浮弦，浮主表邪未解，弦主少阳枢机不利。身热十余日、头有汗而热不解、口苦耳聋，为少阳邪郁；自利不止乃上厥下夺之症。浮弦并见，说明表里同病、两阳之邪未散，故用柴苓法一表一里和之。", ["浮", "弦"]], "18562": ["病机", "脉浮弦略减，浮弦为少阳表邪之象，略减示邪势渐退。自利稀少、里邪欲和，反恶寒为表邪亦欲和；身热漐漐汗出、口渴，有转退少阳之象。脉减而症缓，说明表里之邪均欲和解，故用温胆法清余热。", ["浮", "弦"]], "18563": ["病机", "脉数细少神，数主热，细主阴伤，少神为正气不足。瘟毒之邪郁而未散，一身斑疹隐然，脉数细少神说明毒热内郁而营阴已伤、正气不支，邪不得透达，故症非轻候。", ["数", "细"]], "18564": ["病机", "左脉微而无神，微为阳气衰微，无神为胃气将败，甚属可虑；右脉数实，数实主里热结聚，十余日不大解，颇有下证。左微右实并见，示正虚邪实、烦躁不宁，故未敢轻下，先以竹叶门冬饮止烦乱。", ["微", "数", "实"]], "18565": ["预后", "脉微欲绝，微为阳气衰微欲脱。少阴病但欲寐、躁不得卧，为阴阳离决之兆；舌卷唇焦、不大便，脉微欲绝示肾阳衰败、阴寒内盛，故属不治之候，用苦辛入肾救逆。", ["微"]], "18566": ["病机", "脉浮大，浮主邪在表，大主热盛。冬温邪伏，起于吐泻之后，中气不和，热不减、神昏谵语、口渴恶心、苔白厚、左胁呼吸不利、时咳，皆热邪为害。脉浮大且无汗，说明邪尚在经未入府，故先理阳明。", ["浮", "大"]], "18567": ["病机", "脉浮大而数，浮主表邪未尽，大数主里热炽盛。得微汗后势略减、外热稍清，但舌苔黄黑干燥、转矢气、结燥未下、胃不和，说明里热重于表。脉浮大数示表里俱热而里结未通，故前方再为加减。", ["浮", "大", "数"]], "18568": ["病机", "原文未载脉名，仅言「三诊脉症俱减」，说明前诊脉象已趋缓和，但「里热未尽，胃不和，大便未通，小便赤色」提示余热仍羁留中下二焦，腑气未通，热邪下注膀胱。脉症俱减是邪势稍退而非尽解，故治法仍以通利下焦、生津液为要，属病机层面的余邪未清、津伤腑滞之候。", []], "18569": ["病机", "原文未出脉名，只言「四诊脉象略减，热亦稍清」，表明脉随症减、热势渐退，余邪不足虑。然「左胁痛处，大如手掌部位，痛且拒按」，左胁为肺之经络所布，痛而拒按、积伤气血，说明病机已由外感余热转为气血积伤、络脉瘀阻，故用和伤之法，非单纯清热可解。", []], "18570": ["病机", "「脉左细弱，右弦大」，左候阴血、右候阳气，左细弱示阴血不足，右弦大示阳气偏亢，合为「阴虚阳盛」。原文点明「卫气不得下行之故」，卫气入夜当行于阴，今阳盛不入阴，故先不寐而后头痛发热。脉之左右偏胜正是阴阳升降失司之象，故从阴引阳以调其枢。", ["细", "弱", "弦", "大"]], "18571": ["病机", "「脉左小右大而皆数」，左小为肝血不足，右大为胃热壅盛，数则主热。热久无汗、肌肉瘦削、干咳不食、腹痛按之虚软，是肝胃之热已深而正气渐虚；昼静夜剧、渐积为虫，又兼冬旱风燥之邪上受于肺。脉数应热，左右大小不均应肝胃偏热、虚实夹杂，故主内外兼治。", ["小", "大", "数"]], "18572": ["预后", "前诊「据云细弱」，今「左弦而右大，中虚无神」，弦为肝郁，大为虚阳外浮，中虚无神则胃气已败。面如渥丹而洒淅恶寒、上热下冷、头汗淋漓、气怯神倦，皆阴阳不相维系之象，故断为「阴阳有离脱之兆，可惧之甚」。所幸经水届期，生生未绝，尚存一线生机，脉象由细弱转弦大无神，正是病进之征。", ["弦", "大"]], "18573": ["预后", "「脉细弱无神，右关为最」，细弱为气血两虚，无神则胃气衰败，右关候脾胃，最弱说明中焦生气将绝。腹如仰瓦、脐右动气大如鸡卵震跃不息，是「中虚已极，生气索然」，虚阳躁动于下。痢久复发、人事昏沉，脉证合参属脾胃虚败、根本欲脱之危候，故投建中而病势不减。", ["细", "弱"]], "18574": ["治法", "原文未载脉象，以症测机：痢下肠垢五十余日，腹痛抽掣、憔悴尪羸几几欲脱，是久痢伤阴、阴损及阳。「胃口有滞，势难消导」说明中气已虚不堪攻伐，故急救其阴以恋其阳，取复脉汤之意。此段主旨不在辨脉而在立治法，示久痢虚脱当以救阴恋阳为急，不可拘泥消导。", []], "18575": ["病机", "「诊左脉弱，右较有神」，左候阴血、右候脾胃，左弱右有神说明阴血虽虚而中宫胃气尚存。连进复脉汤后「中宫柔和，神乱烦躁俱止」，是津回液转、阴得滋而阳得恋之机。原文「此时不问其虚，安问其余」，强调既见津液来复之象，当守方续进，脉左弱正是阴亏未复、须缓图之据。", ["弱"]], "18576": ["预后", "原文述痢久不止，胃中邪火燔灼，能食而利不上，身不能转侧，面浮足肿，终至“脉息俱绝”而亡。脉息俱绝乃胃气已竭、生机将息之征，与除中能食、面浮足肿并见，说明中焦衰败、阴阳离决，故主预后不良，虽能食亦不过暂延数日。", []], "18577": ["病机", "暑症复发，壮热退后舌苔煤黑，两脉沉而数细，手指牵掣，神昏不省。沉为邪陷，数为热郁，细为阴伤，乃寒药遏邪太过，虚邪舍于神明之室，热闭心包而阴液已耗，故见神昏牵掣，病机属邪陷正虚、闭窍伤阴。", ["沉", "数", "细"]], "18578": ["病机", "时症经发表清火杂治后，神昏谵语，遍身似斑非斑，胸腹痞满，舌苔白中黄，脉皆数大。数为热盛，大为邪实，乃时行疫邪横连募原，郁遏膜原而化热，邪不在表里而在半表半里，故脉数大而见痞满谵妄，主疫邪盘踞募原之病机。", ["数", "大"]], "18579": ["病机", "伤寒身热而脉沉、头不痛，断为少阴症。沉为在里，头不痛则非三阳，乃少阴阳虚、寒邪直中，故用麻黄附子细辛汤温经发表。后脉中神情来往不续，是阳气衰微、胃中寒湿宿病蛰藏，干健之阳不振，病机由寒邪外束转为少阴阳气欲绝。", ["沉"]], "18580": ["预后", "连进温补后脉象或断或续，继而右尺断续、左关微弱如丝，涎沫上泛。脉断续为阳气不能接续，微弱如丝为真元衰微，故危症复见；后脉象来复则向安。此段以脉之断续来复判断阳气存亡，主预后吉凶，非单论病机。", []], "18581": ["病机", "痢减半、谷食增而安寝，脉皆和缓，唯右尺独劲大不平。和缓为胃气渐复之象，右尺劲大不平则浊邪陷于大肠之分未清，故虽症减而余邪未净。脉象整体和缓而局部劲大，说明正复而邪滞，主大肠浊邪未清之病机。", ["缓", "大"]], "18582": ["病机", "痢止便溏，肌润有汗，神清谷增，而脉细弱而数。细弱为阴血亏虚、正气未复，数为余热未清，痢后阴亏，故脉细弱而数。此脉不主邪盛，而主痢后阴液耗伤、虚热内扰之病机，故曰“痢后阴亏宜和”。", ["细", "弱", "数"]], "18583": ["病机", "左脉不弦而小弱，右洪大，症见寒热、呕吐、头偏右痛、汗多、脘痞。左小弱为肝血不足、非少阳弦脉，右洪大为暑邪由肺入胃、暑兼湿壅阻三焦气分。脉不弦而小弱，正说明非少阳疟症，乃暑湿弥漫气分之病机。", ["小", "弱", "洪", "大"]], "18584": ["病机", "脉弦大搏如指数，右洪大，为邪郁阳明经分，凉剂遏之，邪未发泄，化热生风。弦主风动，大数主热盛，搏指为邪正相争，故见口噤目定、两手牵搐、身僵无汗、面赤如妆，刚痉之症悉具，与《金匮》刚痉脉象相合。", ["弦", "大", "数", "洪"]], "18585": ["病机", "平昔脉象六阴，今觉数大，是素体阴盛而现阳脉，因雨霪过多、酒客内湿，湿郁化热，通阳利湿后脉转数大，示湿滞血中、阳气不通。数大主湿热内蕴，故左半身痛、腰胯甚、足不能伸、溺混浊短涩，为湿瘀阻络之征。", ["数", "大"]], "18586": ["病机", "脉细涩不和，右尺激之鼓指，为暑湿内郁肠胃，邪未外达内消，阴液已耗。细涩主阴亏血少、湿滞不畅，故痢五色相杂、腹痛后重、舌白烦热、手温足冷；前服辛温燥涩，反伤阴助热，非藏病下利，乃邪郁液亏之候。", ["细", "涩"]], "18587": ["预后", "脉象虚涩，较前细涩不和稍转，痢减烦痛亦减，但神倦似睡、汗微欲出，正虚欲脱之兆。虚涩主气血两亏、津液不足，交白露节正气当倍，故虽病减而脉未复，须防虚脱，预后当以扶正为要。", ["虚", "涩"]], "18588": ["病机", "脉浮而带弦，重按空虚，为厥象渐成。浮弦主风痰上扰，重按空虚示正气内溃，故头痛面青、神识日呆、耳聋无汗、昏谵遗溲、目瞑神呆。邪陷厥阴，游移未定，变幻最多，极难图治，当降厥豁痰、开窍育阴息风。", ["浮", "弦", "虚"]], "18589": ["病机", "脉弦急，舌苔转白，汤水能咽，不兴则不知，口噤多汗、手足强、痰涎满口，体翁断为尸厥之象。弦急主风痰内闭、气机逆乱，较前浮弦空虚更显邪实，故痉作而神识不用，仍守前方加减以息风豁痰。", ["弦", "急"]], "18590": ["预后", "脉弦大而数，谵语狂妄，夜半发狂，症转阳分。弦大数主热盛风动、邪从阳化，较前弦急之阴闭转为阳证，故体翁谓可无虑。脉由弦急转弦大而数，是邪有外达之机，预后转佳，仍当清解息风。", ["弦", "大", "数"]], "18591": ["误治", "弱脉神虚，肢振鼓栗，暑风内郁，药以寒凉杂进，病日益甚，体日益虚，神识渐昏。弱脉主气血虚，神虚则肢振鼓栗，寒凉杂进更伤中阳，暑风不得外达，故虚象日增，姑以枇杷叶散挽之，示误治致虚之弊。", ["虚"]], "18592": ["病机", "原文未明言脉象，仅述“脉颇有神”，结合“鼓栗已减七八，舌苔尚白”，可知寒邪大伤胃阳，中阳不振，故畏风多汗、十余日不大便。脉有神示胃气渐复，但舌苔尚白、畏风多汗，仍属中宫虚寒，胃气不降，故以建中温运中阳，使化物自通，无庸攻伐。", []], "18593": ["病机", "左寸关浮弦而虚，右浮大按之无神，舌苔白滑，面微浮，鼻与环口气色青黑，身热多汗，头痛烦闷，食下则眠睡。此中土阳和之气不运，风木厥动，水谷与风暑郁而变幻。浮弦虚为风木亢而中虚，浮大无神为阳气外浮不敛，故从静顺汤法冀中旺木和。", ["浮", "弦", "虚", "大"]], "18594": ["病机", "发汗后肿势大减，喘息渐平，但脉微神倦，恍惚惊惕。此水去而封蛰不固，肾阳失于镇纳，故脉微而神倦惊惕。水气虽去，真阳已伤，封藏不固，以真武汤镇之，温阳固摄，使封蛰有司。", ["微"]], "18595": ["病机", "脉左涩结，关芤，右亦涩弱，失血十几年，今怒动肝伤，气逆上溢，精遗龙雷不宁，甚至无梦自泄。涩结芤弱为血亏阳伤、气机郁滞，阳虚阴必走，龙雷不潜。当处阳发泄之候，贵调平气分，宜降气不宜降火，与仲淳三要符合。", ["涩", "结", "芤", "弱"]], "18596": ["病机", "连进济生八味丸后血色稀、精不复遗，脉较前日胜，少涩结之形，有鼓荡之致。涩结为阳虚阴走、龙雷不潜之象，今渐减而有鼓荡，示氤氲之气与干健之阳渐复冲和。然龙雷不肯潜伏，反升清阳之所，故必引之导之，咸润介潜，调摄勿懈。", ["涩", "结"]], "18597": ["病机", "脉弦大而数，发热左胸胁痛，难以转侧，咳吐自汗，口渴不欲饮，先悲泣而后能嗽，痰有秽气，毛际胀痛，目微赤，多叫呼。弦大为肝木亢盛，数为热，悲哀动中伤魂，风木湿土令退，君火燥金加临，肝郁化热，魂伤气逆，故用甘麦大枣清燥救肺等法。", ["弦", "大", "数"]], "18598": ["病机", "右寸浮大重按无力，脾脉软弱，下血十余载，今思虑忧郁后暴下数斗，食直出如箭，肛门脱出，面浮不泽，唇焦口干，鼻孔煤黑。浮大无力为气虚阳浮，软弱为脾虚不运，中气下陷，肠风下血日久，脾肾两虚，故痢下无度而肛脱。", ["浮", "大", "软", "弱"]], "18599": ["病机", "昨服一剂后内邪消去，但手太阳之脉洪数，此胃气未复也。洪数为热盛，示余邪未清、胃气未和，故宜扶胃养脾为主，勿亟亟于治痢，痢亦自止。洪数脉在此主胃气未服，当以养胃健脾收功。", ["洪", "数"]], "18600": ["预后", "脉由弦急转为缓弱，嗽减痛止、胸脘亦宽，是木旺渐平、土得稍安之象；然久患脾泄、中气大亏，缓弱亦示脾胃虚惫未复。脉证相参，病势虽退而根柢已虚，故须慎饮食杂投，否则诸症复增，愈难调摄。", ["缓", "弱"]], "18601": ["病机", "肝脉渐平，是木气渐退；胃脉反见滑大，滑主食滞痰聚，大主邪气有余，胃脉独显滑大，说明饮食不调、食滞内停于胃，胃气壅实。脉象由肝旺转为胃实，提示病机重心已从肝木犯土转为食伤胃腑。", ["滑", "大"]], "18602": ["病机", "六脉迟弱、两尺尤甚，迟为阳虚，弱为气衰，尺部候肾，两尺尤甚说明肾阳亏虚、下焦失于温煦。阳虚不能温养腰膝，故左腰膝足肿、关节疼痛麻木，遇温暖即稍止，正合虚寒得温则减之性，属三阴经虚寒之恙。", ["迟", "弱"]], "18603": ["主病", "六脉弦数，弦为少阳之脉，数为热象；寒热往来、间日而作，是疟邪伏于少阳；两额巅顶微痛、舌黄苔、大便艰涩，又兼阳明里热。弦数并见，说明少阳枢机不利而阳明热结，故断为少阳阳明两经疟症，治以小柴胡加阳明之药。", ["弦", "数"]], "18604": ["病机", "六脉弦数，身热如烙、舌起黑苔、中脘按痛、小便赤色，皆邪热郁伏之征；弦主邪郁，数主热盛，热与实结于中焦，故按之痛而便自利、小水赤。高年正气已衰而邪热鸱张，脉证俱实，故属大险，一剂稍减即为生机。", ["弦", "数"]], "18605": ["病机", "六脉洪滑有力，洪为阳明热盛，滑主食积痰滞，有力为邪实；舌燥唇焦、口渴无汗是热灼津伤，胸满胀痛、手不可按是食积壅塞胃腑。脉证合参，为阳明热邪夹食之候，故先解肌透邪，后议清里攻下。", ["洪", "滑"]], "18606": ["病机", "两寸浮大、关尺弦数，浮大为上焦气逆，弦数为木郁化热；素多郁怒、产后咳未除，又见恶寒壮热、水入即吐、气痛泄泻、小水全无，是肝郁乘脾、气机升降失司。前服柴芩等药外热似减而诸症转甚，说明非单纯外邪，乃郁怒与产后虚损相杂之候。", ["浮", "大", "弦", "数"]], "18607": ["病机", "脉势涩弱，涩为血少行滞，弱为气虚；后转涩数而弱、左关略旺，数示虚热内扰，左关旺为肝木乘脾。产后饮食不入、乳汁全无、频频自汗，是气血两伤；寒热时发、神气不清，则由血室空虚留瘀随热而入、胃阳不固心神随汗而伤，非外邪所致。", ["涩", "弱", "数"]], "18608": ["病机", "脉来软弱，非外感六经之邪，亦非内伤五藏之患，乃劳苦旬余、枵腹任劳，过伤脾胃，复食生冷难化之物，一吐再伤，脾胃气馁，故脉软弱无力。面黧神瘁、口噤自合、饮食不思、胀痛自若，皆脾胃虚极、中气困顿之候，脉证相合，主劳伤脾胃、中气大虚之病机。", ["弱", "软"]], "18609": ["病机", "右脉弦中带紧，弦主痛、主气机郁滞，紧主寒、主邪结。寒热头疼、胸腹胀闷不堪，先服解肌消导不效，知非单纯表邪，乃邪气内陷、寒凝气结，胸腹气机壅塞不通，故脉见弦紧。此段借脉辨结胸之疑似，弦紧示邪结在里、气滞不通之病机。", ["弦", "紧"]], "18610": ["病机", "六脉浮数，两寸兼大，浮为阳浮于外，数为火旺，大为邪盛。大肉已脱、面赤唇红、干咳、午后发热尤甚，乃精液被药久伤，肺金为火所烁，阴虚阳盛之极。浮数大见于久病形脱之人，非表邪，乃虚阳外越、火烁肺金之象，故断为阴虚阳盛、将成痨瘵之病机。", ["浮", "数", "大"]], "18611": ["病机", "原文未识脉名，然述神昏口噤、手足拘挛，力持其手乃可切脉，脉象难凭。所论风寒湿三气杂合难解，正虚邪盛，以至此极，当遵太阳刚痉法通经络、开心神。此段主旨不在脉，而在辨风寒湿杂合、正虚邪盛致痉之病机，故脉象要素从缺。", []], "18612": ["病机", "脉细为气血不足、阳气衰微之象。久患三疟，又经发散、消导克伐，汗出过多反恶寒，吐清水、小便全无、少腹肿满，乃脾气虚极，土不制水、水泛为痰，土不生金、金难化气。脉细正合脾虚水泛、气化不行之病机，故主纳气归肾、燥脾培元之法。", ["细"]], "18613": ["病机", "右脉滑大，左脉弦急。滑主痰热，大主邪盛，弦急主风热郁遏、气机劲急。头疼壮热、咳逆烦渴，病六七日，系风热郁遏三阳，热盛于内而不得外解，故脉滑大弦急。此脉示风热壅盛、三阳郁遏之病机，当以凉解为法，属风热咳之实证。", ["滑", "大", "弦", "急"]], "18614": ["预后", "吐泻后六脉微弱，面青肢冷，气脱神疲，脉微为阳气衰微，弱为气血俱虚。吐泻伤中，脾阳欲脱，中气衰败，已成慢脾风候。脉微弱与面青肢冷、气脱神疲相应，示脾阳将脱、危候已成，故拟参附理中回阳救逆，本条重在判断预后之险。", ["微", "弱"]], "18615": ["病机", "产后脉涩而数，涩主血少行滞，数主虚热内扰。形羸气怯、腹痛腰疼、潮热心悸，乃产后气血亏耗，营卫不和，虚热内生，瘀滞未净，将成蓐劳。涩数并见，正合气血两虚兼虚热之病机，症非轻可，故宜建中汤以培中调和营卫。", ["涩", "数"]], "18616": ["病机", "脉左尺寸俱紧，紧主寒主痛，寸紧则上焦壅遏，故喉口糜烂；尺紧则下焦凝滞，故腹痛便溏。右关重按见涩，涩主血少气滞，关候中焦，示脾运不健、湿浊内蕴。合面色赤黑晦滞、苔腻厚黄白，显系肾水郁而化火，三焦失司，虚火挟湿上炎下迫，故寒热如疟、口糜腹痛并见。", ["紧", "涩"]], "18617": ["其他", "此段论医之渊源，谓医与卜并见于《周礼》，孔子称「人而无恒，不可以作巫医」，巫筮古通。又言卜之先出于羲文周孔，医之先谓出神农黄帝，书虽亡而绪余存于先秦。末举《本草》《素问》《难经》《脉经》四书，言其「诊其脉以究表里」，乃泛论脉学源流，非具体脉象主病，故脉象要素为空。", []], "18618": ["其他", "此段述医道源流：肇自轩岐，次及和缓扁仓，至张仲景制方剂，王叔和撰次《脉经》，「全生之术，于斯备矣」。又评华佗剖腹、王针妖等奇技非百代活法，末推宋金张元素、刘守真深达阃奥。全段为医史评述，未涉具体脉象与病机，故脉象要素为空，主旨归「其他」。", []], "18619": ["其他", "此段仅标目「手厥阴别脉经见证（心主）」，为经络辨证之提纲，未出具体脉象，亦未言主病。手厥阴心包经别脉见证，当从经络所过与心主病候求之，然原文过简，无脉可析，故脉象要素为空，主旨归「其他」，不作病机推断。", []], "18620": ["其他", "此段仅标目「能合色脉可以万全」，为色脉合参之纲领，未出具体脉象。原文强调望五色以合五脏之脉、切五脉以合五脏之色，内外相参则万举万全。因无脉象描述，故脉象要素为空，主旨归「其他」，不涉具体病机。", []], "18621": ["病机", "此段总论色脉相参，谓「有诸内者形诸外」，望五色以合五脏之脉，切五脉急大缓涩沉以合五脏之色。又引《脉要精微论》「脉之至也喘而坚」「长而左右弹」「上坚而大」等，示脉随脏气变动而主不同病机。脉与色顺则吉、逆则病，故诊外知内、内外相参，方得万全。", ["急", "大", "缓", "涩"]], "18622": ["病机", "此段论「治病必求于本」，谓疾疢之原不离阴阳二邪：风热火属阳邪所客，湿燥寒属阴邪所客。病本于阳则求阳之本，本于阴则求阴之本，否则邪「滋蔓而难制」。以水有本、草有本为喻，明邪气久而传化、变证多端，当穷源疗疾。全段未出具体脉象，故脉象要素为空。", []], "18623": ["治法", "此段论中风治法，主血虚有痰，治痰为先，次养血行血，分气虚血虚。半身不遂在左属死血瘀血，用四物加桃仁红花竹沥姜汁；在右属痰有热兼气虚，用二陈四君子加竹沥姜汁。痰壅口眼㖞斜不能言者用吐法，轻则瓜蒂、稀涎散，重则藜芦加麝香。全段为治法，未出脉象，故脉象要素为空。", []], "18624": ["病机", "原文论中风之脉，谓“脉微而数，或浮而紧，缓而迟”，微数示正虚而热，浮紧为外风之象，缓迟属湿痰内蕴。又言“脉迟浮可治，大数而极者死”，迟浮者邪浅正未大伤，大数而极则邪盛正溃，故主病机为虚实夹杂、风痰热互结，与东南湿土生痰化热生风相应。", ["微", "数", "浮", "紧"]], "18625": ["治法", "原文述“时春脉伏”，以淡盐汤齑汁吐之，继用健脾化痰、清热活血之剂，终以四君子汤收功。脉伏主痰湿内闭、气机郁滞，故用吐法开提，使伏邪从上越，吐后脉气渐通，夜间微汗、手足能动而能言，示痰去窍开、气血渐复，脉伏为痰闭之征，非虚寒之候。", ["伏"]], "18626": ["病机", "原文辨中府中脏，谓中府者“有表证而脉浮”，风邪在表，故脉浮；又言“脉多沉伏”，沉伏主邪陷于里、气血内闭，与中脏失音、鼻不闻香臭相应。浮为在经，沉伏为入脏，脉象示风邪由表入里、闭阻机窍之病机，故治有汗下之异。", ["浮", "沉", "伏"]], "18627": ["兼症", "原文于方后加减云“筋急拘挛，语迟，脉弦，加苡薏仁”。脉弦主筋脉拘急、风痰阻络，与筋急拘挛、语迟相应，故加薏苡仁舒筋缓急。此段以脉弦为兼症用药之据，示弦脉在此主风痰入络、筋脉失柔之病机，非单纯肝胆气旺。", ["弦"]], "18628": ["病机", "原文未出脉名，而论四肢不举之病机，谓“上太过则敦阜”，膏粱之疾，三阳有余则为痿易，三阴不足则发偏枯，脾虚则四肢不用。虽无脉象，然以“太过”“不及”言病机，示实邪壅盛与脾虚不运皆可致四肢不举，与脉之实大或虚弱相应，当据脉辨其虚实。", []], "18629": ["病机", "原文辨寒热二证，谓寒证“脉必沉细，手足厥冷，息微身倦”，沉细主阳气大虚、阴寒内盛；又谓“凡脉数者……皆热病”，数主热盛。沉细与数对举，示寒热病机相反，寒者宜急温，热者不可温，误治杀人，脉象为辨寒热之关键。", ["沉", "细", "数"]], "18630": ["兼症", "原文于方后云“筋脉牵急，加木瓜”。脉牵急即筋脉拘急之象，主风邪或湿邪阻滞筋脉，气血失于濡养，故加木瓜舒筋活络。此段以脉牵急为兼症加减之据，示其病机为筋脉挛急，与挟气、挟湿等兼邪相关，非独立脉名。", ["急"]], "18631": ["治法", "原文论暑证治法，未出脉名，而言暑病内伤用清暑益气汤，注夏属阴虚元气不足，宜补中益气汤加减，暑风挟痰挟火实者用吐法。虽无脉象，然以证言治，示暑证有虚实痰火之异，脉当随证而见虚细或滑数，治分补泻吐下，不可一概而论。", []], "18632": ["病机", "原文言暑热咳嗽发寒热、盗汗不止而脉数，数为热盛之象，热邪在肺经，故脉数应之。此为暑热伤肺、火乘金之候，须急用清肺汤、柴胡天水散清解；若迁延失治，则火乘金而难救，脉数正是热势鸱张、病进之征。", ["数"]], "18633": ["病机", "中暑属阴证，脉沉弱为正虚阳微，故切不可用寒凉；脉弦实则为暑热内郁、邪实之象，宜黄连香薷汤；吐泻而脉沉微甚者，阳气衰微欲脱，故用附子大顺散温阳。原文以脉之沉弱、弦实、沉微分虚实寒热，定治法用药。", ["沉", "弱", "弦", "实"]], "18634": ["其他", "本段仅列「生脉汤」方名，未载脉象描述，亦无论述脉理之文，故无从据脉析其病机。生脉汤本为益气养阴生脉而设，然原文于此未言脉症，不可臆测附会，仅录方名以备查考。", []], "18635": ["病机", "人参白虎汤治暑热发渴而脉虚，虚脉主气阴不足。暑热炽盛耗气伤津，热盛而正已虚，故脉不洪实而反虚，渴由津伤。此脉虚与暑热发渴并见，示热盛正伤之机，故用人参益气、白虎清热，攻补兼施。", ["虚"]], "18636": ["病机", "伤暑而见霍乱腹痛烦躁，脉沉微或伏，沉微主阳气衰微、阴寒内盛，伏则邪闭阳郁。暑伤冷中，清浊相干而吐泻腹痛，阳气不能外达故脉沉微欲绝。此为阴暑寒证，故用冷香饮子温中散寒、通阳化浊。", ["沉", "微"]], "18637": ["病机", "风温之邪袭表，脉浮为邪在肌表、正气趋外抗邪之象。身重汗出恶风或痛，乃风湿郁于肌腠、卫阳不固所致。脉浮与汗出恶风相应，主表虚风湿之证，故用防己黄耆汤益气固表、祛风除湿。", ["浮"]], "18638": ["病机", "左手脉大于右手，浮缓而盛，按之无力。浮缓而盛似为邪盛，然按之无力则示中气不足、虚阳浮越，左大于右亦气血偏倾之象。此脉盛而无力，主正虚不敛、虚风内动之机，非实邪可比，当从虚论治。", ["浮", "缓", "大"]], "18639": ["病机", "浑身壮热、发渴而脉长滑，长为气盛有余、热势绵长，滑主痰热内壅、阳毒火炽。脉长滑与壮热发渴相应，示阳毒火邪炽盛于内，故用地骨皮散清泄阳毒、凉血退热。", ["长", "滑"]], "18640": ["主病", "伤寒汗吐下后，正气受损，脉虚为气血不足之象。斑发而脉虚，说明正气已伤，无力托邪外出，故用化斑汤清解余热兼扶正气。脉虚主病机为正气亏虚，与斑疹外发并见，提示病情虚实夹杂，治当兼顾。", ["虚"]], "18641": ["病机", "疟脉多弦，为邪伏少阳之象。但热则弦而带数，主热盛；寒则弦而带迟，主寒盛。病久脉极虚微而无力，似乎不弦，然虚微之中见弦，但不搏手，说明久病正虚而邪未净，弦象虽弱仍存，细察可见，此脉虚中夹弦，主正虚邪恋之病机。", ["弦", "数", "迟", "虚"]], "18642": ["治法", "热多寒少、目痛多汗、脉大，脉大主热盛邪实，正气未衰。治以大柴胡汤微利为度，使邪从下泄。脉大在此提示阳明热盛，与目痛多汗相应，故用和解攻里之法，余邪未尽则以白芷石膏三物汤尽之。", ["大"]], "18643": ["预后", "下痢脉沉小留连或微者易治，脉宜滑大，脉沉小者生，脉浮洪者危，屋漏水者死。脉沉小为邪轻正未大伤，滑大为胃气尚存，故易治；浮洪为邪盛正衰，屋漏脉为胃气已绝，故主死。此段以脉判预后，强调脉证合参。", ["沉", "小", "微", "滑"]], "18644": ["病机", "痢有气虚兼寒热、食积、风邪、湿热、阳气下陷等不同，脉沉弱而腹痛、脉虚者，主气虚阳陷，正不胜邪。沉弱为阳气不足，虚为气血亏虚，腹痛因虚而滞。治当分因，不可遽补，以免闭门留寇，强调辨脉以分虚实。", ["沉", "弱", "虚"]], "18645": ["兼症", "老人面白，脉弦数，独胃脉沉滑，因饮白酒作痢，下血淡脓水，腹痛，小便不利，里急后重。弦数主热，沉滑主湿滞胃脘，酒毒湿热伤及肠胃，故见下痢脓血、腹痛后重。脉证合参，治以健脾化湿、清热导滞。", ["弦", "数", "沉", "滑"]], "18646": ["病机", "此段论便秘病机，未出脉象。大肠司出而不纳，停蓄蕴结不得疏导，因邪入里胃有燥粪、三焦伏热津液中干，为大肠挟热；虚人脏冷血脉枯、老人脏寒气涩，为大肠挟冷；亦有肠胃受风涸燥秘涩。气不下降则谷道难，噫逆泛满，皆可致秘。", []], "18647": ["病机", "内有所积，外有所感，致成吐泻，阳不升阴不降，垂隔而成。脉多伏欲绝，伏脉主邪闭气阻，阳气不能外达，与吐泻交作、气机壅塞相应。治以二陈汤探吐提气，或生姜理中汤，转筋属血热，用四物加酒芩、红花等。", ["伏"]], "18648": ["治法", "原文“霍乱多寒，身冷，脉绝”，脉绝指阳气衰微，不能鼓动血脉，故脉道不通。寒邪内盛，阳气外脱，故身冷。通脉四逆汤用附子、干姜回阳救逆，甘草和中，以通脉复阳，针对阳衰寒盛之病机。", ["绝"]], "18649": ["病机", "原文“脉浮当吐”，浮脉主邪在表或痰在膈上，因势利导当吐。“久得脉涩”，涩主气血滞涩，痰湿胶固，故“卒难开也，必费调理”。下文论治痰诸法，皆围绕痰湿阻滞、脾气虚而生痰之病机展开。", ["浮", "涩"]], "18650": ["预后", "原文“脉滑而手足温者生”，滑脉主痰，手足温为阳气未衰，故生。“脉涩而四肢寒者死”，涩主气血滞涩，四肢寒为阳气衰败，故死。脉微亦示阳气虚衰。此以脉症合参判断喘证预后，强调阳气存亡之关键。", ["滑", "涩", "微"]], "18651": ["病机", "原文“寸口脉数，其人咳，口中有浊唾涎沫者，为肺痿之病，其人脉数虚者是”。数脉主热，虚脉主津液亏耗。热在上焦，重亡津液，肺失濡养，故咳吐浊唾涎沫。脉数而虚，正合虚热肺痿之病机。", ["数", "虚"]], "18652": ["病机", "原文“口中辟辟燥，咳即胸中隐隐痛，脉反滑数或数实者，此为肺痈也”。滑数主痰热，数实主热毒壅盛。热毒壅肺，腐肉成脓，故咳则胸痛、口燥。脉反滑数实，说明邪实热盛，与肺痿之虚数脉形成对比。", ["滑", "数", "实"]], "18653": ["病机", "原文“吐血，阳盛阴虚，故血不得下行。因火炎上之势而上出，脉必大而芤，大者发热，芤者血滞与失血也”。大脉主阳热亢盛，芤脉主失血。火炎上迫，血随气逆，故吐血。脉大而芤，正合阳盛阴虚、火载血上之病机。", ["大", "芤"]], "18654": ["预后", "原文“诸见血，身热脉大者难治，是火邪胜也；身凉脉静者易治，是正气复也”。脉大主火邪亢盛，身热为邪热鸱张，故难治。脉静为邪退正复，身凉为热退，故易治。又引《脉诀》“鼻衄吐血沉细宜，忽然浮大即倾危”，沉细为阴血未竭，浮大为火盛阳浮，故危。", ["大", "静", "细", "浮"]], "18655": ["病机", "原文“呕血，火载血上，错经妄行。脉大发热，喉中痛者，是气虚”。大脉主热盛，数脉主火，发热为火邪内炽。火载血上，故呕血。喉中痛为虚火上炎。脉大发热而兼气虚，说明火盛与气虚并存，治当益气降火。", ["大", "数"]], "18656": ["兼症", "此段辨下血色鲜为热、色瘀为寒，分连蒲散、理中汤等治。原文未出脉名，仅言血之鲜瘀以别寒热，故脉象要素为空。其主旨在下血兼症之辨治，非以脉断病，故归兼症。", []], "18657": ["病机", "脉缓大而口渴、月经紫色，缓属湿滞，大属气虚不收，合之劳伤挟湿。劳则气耗，湿则缓滞，故脉缓大；湿郁化热则口渴、经色紫。此脉示劳伤挟湿之病机，非单纯虚损可比。", ["缓", "大"]], "18658": ["病机", "原文论痔由脏腑本虚、外伤风湿、内蕴热毒、气血下坠结聚肛门而成，分牡牝脉肠血酒气诸痔。全段未出脉名，故脉象要素为空。其主旨明痔之病因病机与诸外证，治法以解热调血顺气为先，故归病机。", []], "18659": ["病机", "翻胃有痰者寸关脉沉或伏而大，沉伏主痰气壅滞，大主痰浊搏结；有气结者寸关脉沉而涩，涩主气滞不行。二脉皆示中焦壅塞、气痰交阻之机，故治以二陈、开滞导气，与反胃之痰气证相应。", ["沉", "伏", "大", "涩"]], "18660": ["预后", "血虚脉数而无力，数而无力为阴血亏虚、虚热内生；气虚脉缓而无力，缓而无力为气馁不运；有热脉数而有力，有痰脉滑数。段末言气血俱虚沫大出者必死，故主旨重在凭脉判翻胃之可治与危候，归预后。", ["数", "缓", "滑"]], "18661": ["兼症", "脉缓有痰而痞，缓主湿痰内滞，故加半夏、黄连化痰消痞；脉弦而四肢满闷、便难、心下痞，弦主气郁不舒，故加柴胡、黄连、甘草疏达。此段随脉症加减用药，主旨为痞证之兼症辨治，故归兼症。", ["缓", "弦"]], "18662": ["主病", "右关脉浮弦，右关候脾胃，浮主中气外浮，弦主气机郁滞，合之心下虚痞、恶食、懒倦，知脾虚气滞、痞塞不运。枳实消痞丸开胃进食，正为此脉此证而设，故本段主旨为凭脉主病。", ["浮", "弦"]], "18663": ["病机", "原文明确提到“脉微数，面目青黑，或大便黑”，微为阳气虚衰，数为热郁于内，主酒疸日久、湿热伤络、瘀血内停之病机，故见面目青黑、大便黑等瘀热互结症候。又言“脉弦涩”，弦主气机郁滞，涩主血行不畅，属湿阻气滞、血瘀发黄之机，与女劳疸、酒疸等久病入络相应。再言“发黄，脉沉细迟，四肢逆冷，身冷，自汗不止”，沉细迟为阳虚寒盛、阴寒内凝之脉，主寒湿发黄、阳气衰微之病机，故见四肢逆冷、身冷、自汗等阴盛阳衰症候，宜茵陈四逆汤温阳退黄。", []], "18664": ["病机", "原文以“阳病水兼阳证者，脉必沉数；阴病水兼阴证者，脉必沉迟”辨水肿病机。沉主水气内停，数为阳热兼证，迟为阴寒兼证。水肿分阴阳，阳证见脉沉数，阴证见脉沉迟，提示水病虽一，而寒热属性不同，治法亦异。此脉象反映水湿内停兼夹寒热之病机，与腰以下肿、小便不利等症相应。", ["沉", "数", "迟"]], "18665": ["病机", "原文指出鼓胀“有脉实坚人壮盛者，或可攻之”，脉实坚为邪气壅盛、正气未衰之象，故可暂用攻下。然鼓胀本属脾虚之甚，虽脉实坚，仍须“用参、术为主”，攻补兼施。此脉实坚提示邪实为主，与腹大胀满、形气壮盛相应，但不可纯攻，以免伤正。", ["实", "坚"]], "18666": ["病机", "紫苏子汤证见“脉虚紧而涩”。虚为脾胃气伤，紧主气机壅滞，涩示血行不畅。忧思过度伤脾，气结不行，故心腹胀满、喘促烦闷、肠鸣漉漉、二便不利。脉虚紧涩反映本虚标实、气滞血涩之病机，与情志所伤、脾胃气结证候相应。", ["虚", "紧", "涩"]], "18667": ["病机", "关格“脉两手寸俱盛四倍以上”，寸脉盛极，反映气机横格于上，寒热痞结。原文谓“寒在上，热在下”，寸盛为阳热壅于上焦，与吐逆、二便不通之关格症相应。脉盛四倍提示邪气亢盛、格拒不通之病机，故治用吐法以提其气之横格。", ["盛"]], "18668": ["病机", "原文虽未明言脉弦主何，但浊病“主湿热，有痰、有虚”，赤白浊由“胃中浊气下流”所致。脉弦主湿痰流注、气机不畅，与赤白浊、湿热下注之症相应。治宜燥中宫之湿，用二陈加苍术、白术，赤者加白芍药，虚劳用补阴药，皆据脉弦所主之湿痰病机而设。", ["弦"]], "18669": ["病机", "原文“肝脉弦，加青黛”，以脉弦定位肝病。弦为肝脉，主气机郁滞、木旺克土。方中半夏燥湿、猪苓分水，加青黛清肝泻火，说明脉弦提示肝经郁热或肝气横逆之病机，与湿浊内停兼肝火之证相应。此以脉弦为据，指导加减用药。", ["弦"]], "18670": ["病机", "原文“凡脉数而无力者，便是阴虚也”。数主热，无力为虚，数而无力乃阴亏火旺、虚热内扰之象。阴虚发热症难治，治用四物汤加炒黄柏、黄芩、龟板降火补阴。此脉象反映阴虚内热病机，与发热、手足心热等症相应，兼气虚者加人参、黄耆、白术。", ["数", "虚", "无力"]], "18671": ["病机", "原文“若脉实数有实热者，神芎丸”。脉实主邪气壅盛，数主热，实数并见为实热内结之象。胸中烦热、烦躁由实热扰心所致，故用神芎丸清热泻火。此脉象反映实热内盛病机，与烦热、烦躁等症相应，与虚热烦躁之脉虚数者形成对比。", ["实", "数"]], "18672": ["病机", "脉浮大而无力，浮为阳虚外浮，大为虚阳不敛，无力为正气不足。背恶寒甚者，因阳虚不能温煦督脉，故见背寒。此脉主阳虚，与背恶寒相应，治当温阳益气。", ["浮", "大", "虚"]], "18673": ["病机", "原文论湿与汗之阴阳，谓汗多亡阳，阳去阴胜，甚则寒中。湿胜则音声壅塞如从瓮中出，此湿浊困阻之象。虽见热中蒸汗，终传大寒，乃表虚亡阳不任外寒所致。脉候地之阴阳，形候地之阴阳，皆可察有形无形。", []], "18674": ["病机", "体弱肌肥壮而血虚，脉见大。大脉主虚，因血虚不能充盈脉道，气浮于外故脉大。此大而必无力，与血虚相应，治当养血益气，使脉复常。", ["大"]], "18675": ["主病", "脉虚极，主正气大虚。虚极则心气不足，故咳则心痛，喉中介介或肿，乃虚火上炎或痰气阻滞。此脉虚极与心肺气虚、咽喉不利相应，治以茯神汤养心安神。", ["虚"]], "18676": ["主病", "血脉虚损，脉虚。心肺俱损则皮聚毛落，血虚则妇人月水愆期。虚脉主气血不足，与心肺虚损、月经失调相应，治宜益气和血，四君子合四物汤主之。", ["虚"]], "18677": ["主病", "脉弱主诸虚百损，五劳七伤。弱脉为气血不足，肌体失养故消瘦，肤燥失润。此脉弱与虚劳消瘦、皮肤干燥相应，治以无比山药丸补益虚损。", ["弱"]], "18678": ["病机", "郁者结聚不得发越，传化失常。气郁脉沉涩，气滞血瘀；湿郁脉沉细，湿性黏滞；痰郁脉沉滑，痰浊内壅；热郁脉沉数，热郁于内；血郁脉沉，血行不畅；食郁人迎平和气口繁盛，食滞中焦。诸脉皆沉，主病在里。", ["沉", "涩", "细", "滑"]], "18679": ["治法", "此方治劳役病甚，以黄耆、人参、甘草除燥热肌热，当归和血脉，柴胡引清气上行，陈皮导滞气，白术、升麻升胃气，葛根解渴，少加黄柏救肾水泻伏火。全方益气升阳，兼和血脉，乃补中升阳之治法。", []], "18680": ["兼症", "原文两处言\"脉洪大\"，皆与耳鸣目黄、颊颔肿、面赤、嗌痛颔肿并见。洪大为阳明热盛、经气壅滞之象，热循经上攻则面赤颊肿，气血涌盛故脉洪大。故加羌活、防风通经，黄芩、黄连消其肿，是凭脉辨为实热壅盛，非虚阳外越。", ["洪", "大"]], "18681": ["预后", "原文论五积六聚，末言\"积聚之脉，实强者生，沉小者死\"。积为有形之邪，实强脉示正气尚能抗邪，故生；沉小则正气衰微、邪气深痼，脉不应病，故死。此以脉之强弱判积聚之吉凶，属凭脉断预后，非泛论病机。", ["实", "强", "沉", "小"]], "18682": ["病机", "原文以脉辨厥之因：\"气虚脉细，血虚脉大，热厥脉数，外感脉沉实，有痰脉弦\"。细为气弱不充，大为血虚失养，数为热盛，沉实为外邪内闭，弦为痰饮内停。五脉各对应一因，故治法有补气、养血、承气、双解、化痰之别，是脉因证治相贯。", ["细", "大", "数", "沉实"]], "18683": ["病机", "原文辨阴厥：\"始得之，身冷脉沉，四肢逆，足蜷卧，唇口青\"。沉脉主里主寒，阳气衰于下，不能温达四末，故身冷肢逆、足蜷、唇青、小便色白。脉沉与诸寒象相合，确为阴寒内盛之候，故治以四逆、理中，速灸关元以回阳。", ["沉"]], "18684": ["预后", "原文论癫狂：\"脉虚者可治，实则死\"。癫属阴、多痰结心包，脉虚示正气未竭、痰邪未固，尚可镇心开痰而治；脉实则邪气壅盛、神机闭阻，正气难支，故预后凶。此以虚实二脉判癫证之可治与死，紧扣\"痰结心胸\"之病机。", ["虚", "实"]], "18685": ["病机", "原文辨肢节肿痛：\"脉滑者，当用燥湿\"，滑主痰湿流注，故用苍术、南星兼行气；\"脉涩数者，此是瘀血\"，涩为血行不畅，数为郁热，瘀阻经络故肿痛，宜桃仁、红花、归芎加大黄微利。同是肢节痛，凭滑与涩数分痰湿、瘀血两途。", ["滑", "涩", "数"]], "18686": ["病机", "原文仅言\"治麻风脉大而虚者\"。麻风为疠气蚀形，脉大为邪盛或虚阳外浮，虚为正气不足，大而虚并见，示邪留而正已伤，气血耗损不能充脉。故治当兼顾扶正，不可纯用攻伐，是凭脉辨麻风之虚实夹杂。", ["大", "虚"]], "18687": ["治法", "原文于丸药之后言\"候脉实，再用通天再造散取虫\"。脉实示邪气尚盛、正气未衰，堪任峻药攻逐，故以通天再造散取虫。此以脉实为用攻之凭据，属凭脉定治法，示攻邪须待脉实方可再进，否则恐伤正。", ["实"]], "18688": ["病机", "原文分左右手论脉：左手脉数主热多，因火动其痰而眩；脉涩主有死血，瘀阻清窍。右手脉实主痰积，脉大主久病，久病气血俱虚而脉大，乃痰浊不降之象。诸脉皆围绕头眩之痰、火、虚、瘀病机，故以病机为纲。", ["数", "涩", "实", "大"]], "18689": ["病机", "原文以脉辨头痛所属经络：太阳头痛恶风，脉浮紧，为风寒束表；少阳头痛往来寒热，脉弦细，为邪郁半表半里；阳明头痛自汗发热恶寒，脉浮缓长实，为邪在阳明肌表。三脉各主相应经病病机，故归病机类。", ["浮紧", "弦细", "浮缓长实"]], "18690": ["治法", "原文于痰厥头痛见脉缓，则减羌活、防风、川芎、甘草等风药，加半夏以化痰降逆。脉缓主湿痰内蕴，故治法重在燥湿化痰，而非疏散风邪。此段以脉缓为凭，指导方药加减，属治法范畴。", ["缓"]], "18691": ["病机", "原文论心痛（胃脘痛）：痛甚者脉必伏，因剧痛气结、脉道不利；脉坚实不大便者，为实邪内结；脉数热多，主热郁；脉涩有死血，主瘀阻；脉紧实痰积，主痰实内壅。诸脉分主寒、热、瘀、痰、实之病机，故归病机。", ["伏", "坚实", "数", "涩"]], "18692": ["主病", "原文仅言“一人脉涩，心脾常痛”。脉涩主血行不畅、瘀血内阻，心脾疼痛因瘀阻气机而作。涩脉为瘀血之征，故主心脾痛之病。此段以脉涩直接主病，属主病类。", ["涩"]], "18693": ["病机", "原文论胁痛，有肝火盛、木气实、死血、痰流注等因。若气郁而胸胁痛者，看其脉沉涩，当作郁治。沉主气滞于里，涩主血行不畅，沉涩相合，为气郁血滞之象，故主郁证病机，非单纯瘀血。", ["沉涩"]], "18694": ["病机", "原文辨腹痛之因：脉弦主食积，因食滞气机、脉道劲急；脉滑主痰，因痰湿内壅、脉来流利。弦滑二脉分别提示食积与痰湿为腹痛之病机，故以病机归类，指导用台芎、苍术、香附等消食化痰。", ["弦", "滑"]], "18695": ["病机", "原文论腰痛主湿热、肾虚、瘀血等：脉大者肾虚，因虚阳外浮、脉体宽大；脉涩者瘀血，因血行瘀滞；脉缓者湿热，因湿性濡缓、热邪弛张。三脉各主相应病机，故归病机类，并示以杜仲、桃仁、苍术等分治。", ["大", "涩", "缓"]], "18696": ["病机", "原文以脉辨腰疼之因：弦而沉者为虚，沉主气滞不行，涩主瘀血内阻，缓主湿邪留着，滑与伏主痰积。诸经贯肾络腰脊，肾虚则冲寒受湿、血涩气滞、水积堕伤皆可致痛，故脉象随病因不同而各异，示人凭脉分虚实痰瘀湿滞。", ["弦", "沉", "涩", "缓"]], "18697": ["病机", "疝痛由湿热痰积流下、寒郁而作，兼痰饮食积与死血，专主肝经。脉沉紧豁大者，沉主里、紧主寒主痛，豁大示邪实而正气有损，故原文谓挟虚者当以参、术为君佐疏导；按之不定则属虚，用桂枝、乌头温通劫痛，示脉定虚实以定攻补。", ["沉", "紧"]], "18698": ["病机", "本段论耳聋诸因，未出具体脉象。肾寄窍于耳、主精，精气调和则聪；劳伤气血、风邪袭虚致精脱肾惫则聋。又有气厥而聋者，因脏气逆、厥气搏耳，必伴眩晕。原文以病因分厥聋、风聋、劳损诸类，脉象需结合后段肾脉推求。", []], "18699": ["病机", "脉虚而风邪乘之，风入耳脉使经气痞而不宣，成风聋，必头痛；风则浮而盛，热则洪而实，虚则涩而濡。故凭肾脉推求：浮盛为风、洪实为热、涩濡为虚，治法分疏散、清利、调养，邪退再通耳调气安肾，示脉证相应而定治。", ["浮", "盛", "洪", "实"]], "18700": ["病机", "本段论气为身之根本，一息不运则机缄穷，血脉荣卫脏腑皆赖气升降运转。气盛则盈、衰则虚、顺则平、逆则病，七情生七气。气结生痰、痰盛气愈结，故调气必先豁痰，七气汤以半夏为主佐官桂，兼用温中之剂，全段未及具体脉象。", []], "18701": ["病机", "胃风因饮食讫乘风凉而致，症见胀满、食饮不下、形瘦腹大、恶风头多汗、膈寒不通。脉右关弦而缓带浮：右关候脾胃，弦主风木乘土，缓主湿滞，浮示风邪在表，故以胃风汤正治，并看挟证加减，脉象正合风邪犯胃之机。", ["弦", "缓", "浮"]], "18702": ["病机", "时毒疮疹脉浮，浮主邪在表，红在表者疮发于头面胸膈之际，故用郭氏升麻牛蒡子散升散透邪。脉浮与病位在表相应，示邪未入里，治当因势利导从表解，紧扣原文“红在表者”一语。", ["浮"]], "18703": ["病机", "痈疽只是热胜血。阳滞于阴则脉浮洪弦数，为阳热之邪郁于阴分，故以寒治之；阴滞于阳则脉沉细弱涩，为阴寒凝滞，故以热治之。中年后痛肿参脉见虚弱便与滋补，若妄用驱热拔毒则虚虚之祸立至，示凭脉分阴阳虚实而定温清补泻。", ["浮", "洪", "弦", "数"]], "18704": ["主病", "脉洪实者，洪为热盛，实为邪壅，示疮疡热毒内壅、气血壅滞。原文“皮色肿硬，发热而呕，大便闭”皆实热壅结之症，脉与症合，故主内疏黄连汤证，以泻热通壅。", ["洪", "实"]], "18705": ["治法", "本段未言脉，主述疔疮、瘰疬治法。以紫梗菊花汁、牡蛎玄参丸、夏枯草等，示“散结气”“补养血脉”“退寒热”之法。虚者倚仗夏枯草补养，实者佐行散药并艾灸，体现辨虚实而治。", []], "18706": ["病机", "本段未言脉，专论经水过期、不及期之病机。过期血少、血虚，不及期血热、气血俱热；紫黑有块为血热，淡色为痰多。以四物加减，示调经须辨血虚、血热、痰湿之异。", []], "18707": ["兼症", "脉微数者，微为血少，数为有热。原文“经候微少，渐渐不通，手足烦疼，渐瘦，生潮热”，乃血虚发热、经隧渐闭之候。脉症相合，故以四物加减，加泽兰活血通经。", ["微", "数"]], "18708": ["其他", "本段仅言“当归散治经脉不通”，未及脉象与症候。经脉不通可由血虚、血瘀、寒凝等致，当归散养血活血通经，然原文简略，无脉可析，故归其他。", []], "18709": ["治法", "本段未言脉，论血崩治法。东垣主寒，然须分寒热：因寒用干姜，因热用黄芩，紫色成块者热用黄连，漏下热而虚用四物加黄连。急则治标用白芷汤调百草霜，体现辨寒热虚实而治。", []], "18710": ["病机", "脉数者，主热。白带因七情所伤而脉数，示情志郁结化热，热扰带脉，故带下。数脉为热象，与七情内伤相合，说明此白带非纯虚寒，而有郁热之机。", ["数"]], "18711": ["病机", "本段未言脉，论赤白带病机。引叔和“崩中日久为白带，漏下多时骨本枯”，示崩漏日久，血少亡阳，血海将枯，津液复亡，不能滋养筋骨，故白滑之物下流不止。治法以行经药引经，辛甘润燥，卒热补阳，寒苦泄肺，人参补元。", []], "18712": ["妇人", "原文虽未明言脉象主病，但以“脉细匀”为产前常脉之背景，细匀示血循经而不妄行。文中强调“产前当清热产血”“产前宜清热，令血循经而不妄行，故能养胎”，故脉细匀为血分无热、胎有所养之象；若火动胎则脉必数，故以黄芩清热安胎，使脉复细匀。", ["细", "匀"]], "18713": ["妇人", "原文列产后脉象：洪数为血虚火载血上行之血晕，细小涩弱为气血大虚之常。产后“无得令虚，当大补气血为先”，洪数乃虚火，细涩弱乃血少，故一切病多属血虚，不可发表，芍药酸寒亦忌，总以补气血为要。", ["洪", "数", "细", "涩"]], "18714": ["小儿", "原文以“脉上分虚实”为纲论痘疮，虽未列具体脉名，但辨气虚血虚、里虚里实、表虚表实。吐泻食少为里虚，不吐泻能食为里实；陷伏倒靥灰白为表虚，红活绽凸为表实。脉之虚实即对应痘疮之可补可清，里实而补则结痈毒，表实再发则溃烂不结痂。", []], "18715": ["小儿", "原文论小儿疮疹与伤寒相似，证候多端，未提脉象，而以“耳冷骫冷足冷”及“耳后有红脉赤缕”为验。疮疹属阳，肾脏无证，故肾所部独冷；红脉赤缕为热毒外透之征，可稽验疑似，非脉诊所能独断。", []], "18716": ["病机", "原文谓“弦坚之脉，虽是有积，亦带阴虚，脉无水不软之意”，弦坚示积与阴虚并见，脉失柔和；又“脉紧指者，其气大虚，多死”，紧指非寒实，乃元气虚极、脉无胃气之恶候，故峻补气用参、术、归，形脱面白肥人皆以补气为急。", ["弦", "坚", "紧"]], "18717": ["治法", "原文以“趺阳脉不应”为点三里穴之验，趺阳属阳明胃经，脉不应则胃气不足，故取三里以补阳明。此非论脉主病，乃借脉定穴之治法，三里属阳明经，点之使胃气复而趺阳脉应。", []], "18718": ["其他", "此段为丹溪先生卒后之墓表序文，叙宗属失倚、濂受请为表之由，全无脉象病机内容，故脉象要素为空，主旨属其他，不涉医理。", []], "18719": ["其他", "此段为丹溪翁传记，叙其弃举子业专攻医，虽列“脉大无伦、脉滑而数、脉弱而迟、脉虚弦而沉数、脉数而涩、脉弦数而且滑、脉弦出左口”诸脉名，然系行文所带，非本段主旨；本段重在述翁学医之由，故归其他，脉象仅存原文顺序之前四字。", ["大", "滑", "数", "弱"]], "18720": ["其他", "此段为《伤寒杂病论》自序，非论脉专文。文中“并平脉辨证”指结合平脉（正常脉象）以辨病证，强调脉诊为辨证之依据。平脉在此代表诊脉之常法，非具体病脉，故不主特定病机，而示脉诊在全书中的纲领地位。", ["平"]], "18721": ["其他", "此段仅标“辨脉法第一”篇题，未出具体脉象文字，故无脉象要素可录。其主旨为脉法总纲之开篇，提示后文将系统论述辨脉之法，属篇章结构内容，不涉具体病机与主病。", []], "18722": ["病机", "原文以“脉大、浮、数、动、滑”为阳脉，主阳热亢盛之病机；以“沈、濇、弱、弦、微”为阴脉，主阴寒内盛之病机。并据“阴病见阳脉者生，阳病见阴脉者死”判断预后，说明脉之阴阳属性反映正气盛衰与邪气性质，阳脉多主实证热证，阴脉多主虚证寒证。", ["大", "浮", "数", "动"]], "18723": ["主病", "“脉浮而数”主阳结，浮为阳盛，数为热炽，热灼津液故“能食，不大便”，属阳明实热内结；“脉沈而迟”主阴结，沈为阴寒内盛，迟为阳气不振，寒凝气滞故“不能食，身体重，大便反鞕”，属太阴寒凝。两脉对举，明辨阳结阴结之实寒实热病机。", ["浮", "数", "沉", "迟"]], "18724": ["病机", "“寸口脉微”为阳不足，阴气上入阳中，故“洒淅恶寒”；“尺脉弱”为阴不足，阳气下陷阴中，故“发热”。“阳脉浮阴脉弱”主血虚，血虚则筋脉失养而“筋急”。“其脉沈者，荣气微也”，荣血不足故脉沈；“其脉浮，而汗出如流珠者，卫气衰也”，卫外不固则汗出如珠。全段以脉之微、弱、浮、沈辨阴阳气血之虚损。", ["微", "弱", "浮", "沉"]], "18725": ["病机", "原文以“脉蔼蔼，如车盖者”形容阳结之脉象，蔼蔼如车盖，轻浮盛大而中空，主阳气郁结于上、不能下达之病机。此属以比喻描述脉形，非具体脉名，故脉象要素为空。阳结者，阳热之气结聚，脉气浮盛如盖，与后文阴结之“累累如循长竿”相对。", []], "18726": ["病机", "原文以“脉累累，如循长竿者”形容阴结之脉象，累累如循长竿，沉实弦长而连续，主阴寒之气凝结于内、脉道拘急之病机。此亦为比喻描述，非具体脉名，故脉象要素为空。阴结者，阴寒内盛，脉气沉紧如循长竿，与阳结之“蔼蔼如车盖”相对。", []], "18727": ["病机", "原文以“脉瞥瞥，如羹上肥者”形容阳气衰微之脉象，瞥瞥如羹汤上浮油，轻浮无根、涣散不定，主阳气虚浮外越、不能内守之病机。此属比喻描述，非具体脉名，故脉象要素为空。阳气微者，脉气浮散如羹上肥，与阳气内守之正常脉象相悖，示虚阳外浮之危候。", []], "18728": ["病机", "原文以“萦萦如蜘蛛丝”形容脉象细弱欲绝、若有若无，此为阳气衰微、无力鼓动血脉所致。阳气虚衰，脉道不充，故脉细如丝而萦绕不定。此脉主阳气衰败之病机，常见于虚劳、厥脱等症，属危重之候。", ["细"]], "18729": ["病机", "原文以“绵绵如泻漆之绝”描述脉来连绵细弱、按之欲绝，此因血液亏耗、脉道空虚所致。血亡则脉失濡养，故脉细软无力而断续。此脉主亡血之病机，常见于失血、崩漏等症，与阴血亏虚相应。", ["细"]], "18730": ["病机", "原文指出脉来缓而时一止复来为结，脉来数而时一止复来为促，并明言“阳盛则促，阴盛则结”。结脉因阴寒内盛、阳气不伸，脉行迟缓而时止；促脉因阳热亢盛、灼伤阴液，脉行急数而时止。二者皆属病脉，主阴阳偏盛、气血失调之病机。", ["缓", "数", "结", "促"]], "18731": ["病机", "原文言“数脉见于关上，上下无头尾，如豆大，厥厥动摇”，此即动脉之象。数脉主热，见于关上则热郁于中焦；脉形如豆、厥厥动摇，为阴阳相搏、气血冲动所致。此脉主邪热内郁、阴阳相搏之病机，常见于惊悸、疼痛等症。", ["数", "动"]], "18732": ["平脉", "原文以“阳脉浮大而濡，阴脉浮大而濡，阴脉与阳脉同等”释缓脉。浮大而濡，是脉来宽柔和缓、不疾不徐之象，阴阳脉同等则示气血调和、营卫通畅。此非病脉，乃平人脉象之和缓者，主脾胃气充、阴阳和平之生理状态。", ["浮", "大", "濡", "缓"]], "18733": ["病机", "原文辨弦紧之别：“脉浮而紧者，名曰弦”，弦脉状如弓弦、按之不移，因浮紧相合、脉道拘急而成；“脉紧者，如转索无常”，紧脉则如转索之劲急不定。弦主气机郁滞、经脉拘急，紧主寒邪收引、疼痛。二者皆主邪气内结、脉道紧张之病机。", ["浮", "紧", "弦"]], "18734": ["病机", "原文言“脉弦而大，弦则为减，大则为芤”，弦而大者，减与芤相合，即革脉。弦为阳气衰减，芤为阴血虚亏，寒虚相抟，脉道失充而外急中空，故成革象。妇人见之则半产漏下，男子见之则亡血失精，皆主精血亏虚、阳气不足之病机。", ["弦", "大", "芤", "革"]], "18735": ["病机", "原文言“脉浮而紧，按之反芤，此为本虚”，浮紧为邪在表，按之芤则示营血本虚。本虚之人，正气抗邪无力，故当战而汗出；脉浮则邪有外达之势，故汗出而解。此段主本虚邪郁之病机，说明战汗作解之由，与虚人外感相应。", ["浮", "紧", "芤"]], "18736": ["病机", "脉浮而数，浮为邪在表，数为阳热盛；按之不芤，说明脉管充盈、阴血未伤，故曰「此人本不虚」。正因正气不虚，邪正交争可从表以汗解，且汗出而解不须发战。此段以脉辨正气虚实，进而推断解病方式，属病机与预后之间，主表热实证欲从汗解。", ["浮", "数", "芤"]], "18737": ["病机", "脉大而浮数，大为阳盛邪实，浮为病位在表，数为热盛，三者相合说明表热壅盛、正气充旺，正邪交争有力。邪热可从肌表外泄，故不须发战，汗出而解。原文以「脉大而浮数」直接回答不战之因，强调脉象反映阳气鼓动有力，主表热实证，与汗出而解相应。", ["大", "浮", "数"]], "18738": ["病机", "脉自微，为阳气阴液俱不足之象。原文指出曾发汗、吐、下或亡血，致「内无津液」，脉道不充故微。然此非邪盛，乃阴阳自趋调和，故不战不汗而自愈。脉微在此说明津液亏虚、正气不足，但因邪已衰、阴阳自和，故主自愈，属病机与预后判断。", ["微"]], "18739": ["预后", "伤寒三日，脉浮数而微，浮为邪在表，数为热，微为邪气已衰；身凉和则表热已退，故为「欲解」，解以夜半阴尽阳生之时。原文又分述：脉浮而解者濈然汗出，脉数而解者必能食，脉微而解者必大汗出，皆以脉象推断解病途径与症候，主病势向愈之预后。", ["浮", "数", "微"]], "18740": ["预后", "寸口、关上、尺中三处，大小、浮沉、迟数同等，即三部脉象匀平一致，无偏亢偏衰，原文称「脉阴阳为和平」。虽尚有寒热不解之症，但脉已和平，说明脏腑气血调和，故「虽剧当愈」。此段以三部脉同等判断愈后，脉象平和为阴阳自和之征，主病虽重而预后良好。", ["大", "小", "浮", "沉"]], "18741": ["平脉", "立夏得洪大脉，洪大为夏令时脉，原文称「是其本位」「是其时脉」，属四时平脉。脉应时令则人体气机与天时相应，故身体疼重者可因势发汗，汗自出者明日便解。此段以脉合四时判断平脉与病解，强调脉应时令则病易愈，四时仿此，主平脉与时令相应。", ["洪", "大"]], "18742": ["病机", "寸口脉浮为邪在表，沉为病在里，数为热在府，迟为寒在藏。原文以浮沉数迟分表里府藏，假令脉迟则「此为在藏」，说明迟脉主藏病、主寒。此段以脉位与脉率辨病位深浅及府藏属性，脉象为辨证定位之依据，主病机表里藏府之辨。", ["浮", "沉", "数", "迟"]], "18743": ["病机", "趺阳脉浮而涩，浮为胃气浮越，涩为血少，故知「脾气不足，胃气虚也」，法当下利。若脉浮大则气实血虚。少阴脉弦而浮，才见为调脉，称如经。若反滑而数，则知当屎脓。此段以趺阳脉辨脾胃虚实，脉浮涩主脾虚下利，脉弦浮为少阴调脉，滑数则主肠痈脓血。", ["浮", "涩", "大", "弦"]], "18744": ["病机", "脉浮为风邪伤卫，脉紧为寒邪伤荣，荣卫俱病则骨节烦疼。浮紧并见，说明风寒外束，卫阳被遏，营阴凝滞，邪正交争于表，故当发汗以解表。", ["浮", "紧"]], "18745": ["病机", "趺阳脉迟而缓为胃气如经；浮而数则因误下伤胃动脾，荣卫内陷。数脉先微而反浮，示邪气独留，脾气不治，故大便鞕、气噫、潮热发渴。数脉当转为迟缓，若数脉不时则生恶疮。", ["迟", "缓", "浮", "数"]], "18746": ["病机", "脉微而濇为医误汗下所致，阳微则恶寒，阴弱则发热。夏月欲著复衣，冬月欲裸其身，乃阳气内微不能胜冷、阴气内弱不能胜热。阴脉迟濇，故知血亡。", ["微", "濇", "迟"]], "18747": ["治法", "脉浮而大，心下反鞕，有热属藏者当攻，不可发汗；属府者不可溲数，溲数则大便鞕。脉迟则尚未可攻，示里热未实，攻下宜慎。", ["浮", "大", "迟"]], "18748": ["死脉", "脉浮而洪，身汗如油，喘而不休，水浆不下，体形不仁，乍静乍乱，此为命绝。浮洪为阳气外越，汗出如油为阴液枯竭，喘不休为肺气将绝，故主死。", ["浮", "洪"]], "18749": ["误治", "寸口脉浮大，医反下之为大逆。浮则无血，大则为寒，寒气相抟则肠鸣；反饮冷水，水寒相抟则䭇。趺阳脉浮为胃气虚竭，脉滑则为哕。脉浮鼻燥者必衄，皆医咎。", ["浮", "大", "滑"]], "18750": ["主病", "诸脉浮数当发热而洒淅恶寒，若有痛处、饮食如常者，为畜积有脓。脉浮而迟，面热赤而战惕者，迟为无阳不能作汗，故当汗出而解，反发热则差迟，其身必痒。", ["浮", "数", "迟"]], "18751": ["病机", "寸口脉阴阳俱紧，为清邪中上焦、浊邪中下焦。清邪中上则发热头痛项强；浊邪中下则阴气为栗、足膝逆冷、便溺妄出。表气微虚，里气不守，三焦相溷，内外不通，故变证丛生。", ["紧"]], "18752": ["预后", "脉阴阳俱紧，紧主寒邪束表、内外皆寒。原文见口中气出、唇口干燥、踡卧足冷、鼻中涕出、舌上胎滑，为寒盛阳郁、津不上承之象，故戒'勿妄治'。至七日微发热、手足温，是阳气渐复，紧脉将去，为欲解；八日以上反大发热，则阳复太过或邪郁化热，故难治。恶寒欲呕、腹内痛欲利，皆紧脉寒邪内迫之兼症。", ["紧"]], "18753": ["预后", "脉阴阳俱紧而吐利后紧不去，是寒邪未解、里气未和，故'其脉独不解'；紧去则寒散人安，为欲解。若脉迟至六七日不欲食，迟主阳虚水停，'此为晚发，水停故也'，胃气未复故未解；食自可者胃气已和苏，故为欲解。全段以紧、迟两脉进退判寒邪与水停之解未解。", ["紧", "迟"]], "18754": ["预后", "手足三部脉皆至，是气血周流、阴阳相接，虽大烦、口噤不能言、躁扰，乃正邪交争、阳气欲伸之象，故'必欲解也'。若脉和，则营卫自调，其人大烦、目重、睑内际黄，为郁热外达、胃气渐和之征，亦为欲解。此段以脉'至'与'和'为关键，辨病解之机在脉气调和而非症候轻重。", ["和"]], "18755": ["病机", "脉浮为风邪在表，数为虚，虚则卫阳不固。原文'风为热，虚为寒，风虚相抟'，说明风邪与卫虚相合，表气失护，故见洒淅恶寒。浮数并见，非单纯实热，而是风虚相搏、营卫不和之病机，恶寒为卫气不能温分肉所致，与一般表实寒证不同。", ["浮", "数"]], "18756": ["预后", "脉浮为阳，滑为实，阳实相抟则脉数疾。原文'卫气失度，浮滑之脉数疾，发热汗出者，此为不治'，说明阳热实邪亢盛，迫津外泄，卫气失其常度，故发热汗出。浮滑本主实热，更加数疾，是邪热鸱张、正气耗散之危候，故断为不治，非一般表热可比。", ["浮", "滑", "数", "疾"]], "18757": ["死脉", "伤寒欬逆上气，肺气上逆之证；其脉散者，散为气血耗散、根本脱离之象。原文'谓其形损故也'，指出形气已损，脉气不能收摄，故主死。散脉非寻常虚脉，乃阴阳离决、脏气败绝之候，与欬逆上气并见，说明正虚邪盛、气不归元，故列为死脉。", ["散"]], "18758": ["平脉", "此段仅为'平脉法第二'篇题，无具体脉象描述与病机论述，故脉象要素为空。篇题标示该篇主旨为平脉法，即论述正常脉象及平人脉气调和之理，属脉学总纲类内容，不涉及具体病脉主病，故归入平脉类。", []], "18759": ["平脉", "此段论脉有三部、阴阳相乘，荣卫血气随呼吸出入，'春弦秋浮，冬沈夏洪'，说明四时平脉各有其象，随时动作而效象形容。尺寸参差、或短或长，是脉随病变之常。'肾沈心洪，肺浮肝弦'，以五脏配四时脉象，皆属经常之平脉，非病脉，故归平脉类，示人知常达变。", ["弦", "浮", "沉", "洪"]], "18760": ["病机", "原文以「来疾去迟」为「出疾入迟」，定为「内虚外实」；「来迟去疾」为「出迟入疾」，定为「内实外虚」。脉之出入疾迟反映气机出入之偏：来疾去迟者，气出外疾而内入迟，故外实内虚；来迟去疾者，气出外迟而内入疾，故内实外虚。此以脉之头（呼吸）辨内外虚实之病机，非主一病，乃示虚实之所在。", ["疾", "迟"]], "18761": ["预后", "原文言表有病者「脉当浮大」，今病人发热身疼而脉反「沈而迟」，知表病已去，故「知其差也」。沉迟为里脉，表病得里脉，说明邪已离表入里或表证已解，脉证不符而反见沉迟，是向愈之征。此以脉之浮沉迟数辨表里，断病之愈否，属预后判断。", ["沉", "迟"]], "18762": ["预后", "原文言「若里有病者，脉当沈而细」，今腹内卒痛而脉「浮而大」，知里病已去，故「知其愈也」。浮大为表脉，里病得表脉，说明里邪已散或病不在里，脉证相反而见浮大，是向愈之征。此以脉之浮沉细大辨表里，断病之愈否，属预后判断。", ["浮", "大"]], "18763": ["其他", "原文述诈病之辨：病人向壁卧，闻师到不惊起盼视，三言三止，脉之咽唾，此诈病也。又言「设令脉不和，处言已愈」；「设令脉自和，处言汝病大重」。脉不和与脉自和在此非主病机，乃辨病之真假、预后之顺逆。脉自和而病重，是脉证不符，故须吐下针灸；脉不和而热已去，是病退脉未复。", []], "18764": ["兼症", "原文以持脉时病人之姿态动作辨病：欠者无病，呻者病，言迟者风，摇头言者里痛，行迟者表强，坐而伏者短气，坐而下一脚者腰痛，里实护腹如怀卵物者心痛。此段未出具体脉名，乃以望闻姿态辅助脉诊，辨病位与症候，属兼症辨识，非单凭脉象主病。", []], "18765": ["病机", "原文论伏气之病，以意候之。若「脉微弱者」，当喉中痛似伤，非喉痹也，病人云实咽中痛，虽尔今复欲下利。脉微弱为正气不足，伏气内发，虚火上炎则咽痛，非外感喉痹；正气虚而下陷，故欲下利。此脉微弱示正虚邪伏，上则咽痛，下则下利，属伏气病机。", ["微", "弱"]], "18766": ["病机", "原文答恐怖之脉状：「脉形如循丝，累累然，其面白脱色也。」如循丝、累累然，即脉细而连续不断之象，属细脉类。恐怖伤肾，气机内敛，血脉拘急，故脉细如丝；气血不能上荣于面，故面白脱色。此脉细与面白并见，示恐伤气、气血内却之病机。", ["细"]], "18767": ["病机", "原文答「人不饮，其脉何类」曰：「其脉自濇，唇口干燥也。」濇即涩脉，主津血少而脉道不利。人不饮则津液乏竭，不能濡润唇口，故唇口干燥；津亏血少，脉行不畅，故脉涩。此涩脉与唇口干燥相应，示津液亏乏、脉道失濡之病机。", ["涩"]], "18768": ["病机", "原文言人愧者脉浮而面色乍白乍赤。愧则心神不宁，气机浮动于外，故脉应之而浮；气血一时紊乱，不能上荣于面，故面色乍白乍赤。此非外邪之浮，乃情志波动、气浮于表之象，与太阳表证之浮脉不同，当从神色合参。", ["浮"]], "18769": ["平脉", "原文以三菽、六菽、九菽、十二菽及按之至骨分候肺、心、脾、肝、肾之气，言指按轻重不同而脉气深浅有别。此非论病脉，乃示诊脉候五脏之气的方法，说明脉气由浅入深与五脏相应，属平脉诊法范畴。", []], "18770": ["预后", "原文言下利而寸口、关上、尺中悉不见脉，唯尺中时一小见、脉再举头者，为肾气尚存；若见损脉来至，则肾气衰败，故为难治。此以尺脉有无及损脉之见判断下利后肾气存亡，主预后吉凶。", []], "18771": ["病机", "原文论脉有相乘，分纵、横、逆、顺：水乘火、金乘木为纵，火乘水、木乘金为横，水乘金、火乘木为逆，金乘水、木乘火为顺。此以五行生克说明脉象相乘的病机传变规律，纵横逆顺各示脏气偏乘之势，非具体脉形。", []], "18772": ["病机", "原文列弦、紧、浮、滑、沈、濇六脉为残贼，谓其能为诸脉作病。此六脉各主不同病机，如弦主肝郁、紧主寒痛、浮主表、滑主痰湿等，然其共性在于皆能乘虚为患、变生诸病，故称残贼，示人见此六脉当审其致病之由。", ["弦", "紧", "浮", "滑"]], "18773": ["其他", "原文论灾怪：人病脉得太阳、形证相应，服汤后忽大吐下利腹痛，师言前未见证而今变异，乃旧时服药今乃发作所致。此非脉象主病之论，乃说明脉证相应而突发变异之因，属诊法中的灾怪现象，故归其他。", []], "18774": ["预后", "原文言肝脉微弦、濡弱而长，是肝之平脉，肝病得濡弱者自愈；若得纯弦脉、脉如弦直，则肝藏伤，故知死。微弦而濡弱长为胃气尚存、肝木柔和之象；纯弦如弦直则胃气已绝、真脏脉见，故主死，示肝病预后。", ["弦", "濡", "弱", "长"]], "18775": ["预后", "原文言心脉洪大而长为平脉，心病得洪大者愈；若脉来微去大名反，病在里；头小本大名覆，病在表。上微头小则汗出，下微本大则关格不通、不得尿，头无汗可治，有汗者死。此以脉来去头本之变判断心病表里及预后吉凶。", ["洪", "大", "长"]], "18776": ["预后", "肺脉毛浮为常，肺病得之为顺；若得缓迟，土气生金，故皆愈。数脉属火，火克金，法当痈肿，为难治。原文以五行生克判断预后，数脉示火盛刑金，故剧。", ["毛", "浮", "缓", "迟"]], "18777": ["预后", "二月肝木用事，脉当濡弱为常。反得毛浮，是肺金之脉，金来克木，故知至秋死。原文以脉逆时令、五行相克推断死期，强调脉应四时。", ["浮", "濡", "弱"]], "18778": ["病机", "肥人肌厚，脉当沉；瘦人肌薄，脉当浮。今肥人反浮、瘦人反沉，故责之。原文以体质与脉位相反为病机，提示脉象与形气不符，当求其因。", ["浮", "沉"]], "18779": ["死脉", "寸脉下不至关为阳绝，尺脉上不至关为阴绝，阴阳不相接续，故皆不治决死。原文以脉不贯通关部判断阴阳离决，死期以月节克之。", []], "18780": ["预后", "脉病人不病，名曰行尸，以无王气，卒眩仆不识人者，短命则死；人病脉不病，名曰内虚，以无谷神，虽困无苦。原文以脉病与形病相反判断预后，强调胃气与王气之有无。", []], "18781": ["病机", "翕奄沉名曰滑，沉为纯阴，翕为正阳，阴阳和合故令脉滑。关尺自平，阳明脉微沉，食饮自可；少阴脉微滑，滑者紧之浮名也，此为阴实，必股内汗出、阴下湿。原文以滑脉辨阴阳和合与阴实之不同。", ["滑", "沉", "微"]], "18782": ["病机", "紧脉从亡汗、吐、欬、下利而来，皆因肺里寒、饮冷水、胃中虚冷，寒邪收引故令脉紧。原文列举三因，说明紧脉主寒、主痛、主虚冷。", ["紧"]], "18783": ["平脉", "寸口脉缓而迟，缓则阳气长，其色鲜、颜光、声商、毛发长；迟则阴气盛，骨髓生、血满、肌肉紧薄鲜鞕。阴阳相抱，荣卫俱行，刚柔相抟，名曰强也。原文以缓迟为阴阳和调之平脉，主强健。", ["缓", "迟"]], "18784": ["病机", "趺阳候脾胃，滑为胃气实，紧为脾气强，二者相合是实邪与强气相互搏击。原文以“持实击强，痛还自伤，以手把刃，坐作疮也”为喻，说明脾胃实强相攻，气血壅遏，可致脘腹疼痛、疮疡自伤之候，非外邪所致，乃实实相并之病机。", ["滑", "紧"]], "18785": ["病机", "寸口脉浮而大，原文以“浮为虚，大为实”分释，浮主正虚，大主邪实。脉见于尺则关，关则气化不行而不得小便；见于寸则格，格则胃气上逆而吐逆。此段以脉位分关格，说明阴阳升降失司、上下痞隔的病机。", ["浮", "大"]], "18786": ["病机", "趺阳脉伏而涩，伏则阳气内郁、胃气不宣，故吐逆、水谷不化；涩则血脉不利、胃脘枯滞，故食不得入。原文名之“关格”，是脾胃阳气郁伏、纳化俱废之候，与上段浮大之关格虚实不同，此偏于阳郁血滞。", ["伏", "涩"]], "18787": ["病机", "脉浮为风虚，大为气强，风气相抟于肌表，故原文谓“必成瘾疹，身体为痒”，痒者名泄风，是风邪外泄于皮肤。久而不解，风毒郁于肌肤，则“久久为痂癞”。此段以浮大之脉说明风虚气强、外搏肌肤的病机与演变。", ["浮", "大"]], "18788": ["病机", "寸口脉弱而迟，弱为卫气微，迟为荣中寒。原文指出“荣为血，血寒则发热”，是血分受寒、阳郁而热；卫气微弱则心内饥，然“饥而虚满不能食”，为中虚不运、虚满不纳之候。此段以弱迟说明营卫俱虚、寒从中生的病机。", ["弱", "迟"]], "18789": ["预后", "趺阳脉大而紧，大为邪盛，紧为寒凝，脾胃之脉大紧并见，是寒邪盛而正气不支。原文断为“当即下利，为难治”，因大则邪实，紧则寒胜，中阳受戕，下利乃脾胃衰败之兆，故属难治之预后判断。", ["大", "紧"]], "18790": ["病机", "寸口脉弱而缓，弱为阳气不足，缓为胃气有余。阳气不足则运化无力，胃气有余则壅滞不降，故见“噫而吞酸，食卒不下，气填于膈上也”。此段以弱缓说明中阳不振、胃气壅逆、食气填膈的病机。", ["弱", "缓"]], "18791": ["病机", "趺阳脉紧而浮，浮为气，紧为寒。浮主腹满，紧主绞痛，浮紧相抟则肠鸣而转、气动隔下；少阴脉不出，则阴寒内盛、水气不行，故“其阴肿大而虚也”。此段以浮紧说明寒气搏结、气机转动失常及阴肿之病机。", ["紧", "浮"]], "18792": ["病机", "脉微为卫气不行，涩为荣气不足，荣卫不能相将则三焦失养。原文以“身体痹不仁”言荣卫不贯肌肤，以“烦疼、口难言”言荣虚失濡，以“恶寒数欠”言卫虚不温，更分上焦噫而酢吞、中焦不能消谷、下焦遗溲，皆由三焦不归其部，脉微涩正是荣卫俱虚、三焦无仰之象。", ["微", "涩"]], "18793": ["病机", "趺阳脉沉为实，数则消谷，言胃中有实热，故能消谷。原文又云“紧者，病难治”，紧为寒，实热而见紧，寒热错杂、邪气锢结，故难治。沉数主胃实消谷，紧则示病势转深，非单纯胃热可比。", ["沉", "数", "紧"]], "18794": ["病机", "脉微为卫气衰，涩为荣气不足。原文以荣为根、卫为叶，荣卫俱微则“根叶枯槁”，故见面色黄青、寒栗、欬逆唾腥、吐涎沫。微涩并见，说明荣卫两虚、根本枝叶俱损，外不能温肤，内不能濡脏，故寒栗欬逆，唾腥涎沫由肺失温养而来。", ["微", "涩"]], "18795": ["病机", "趺阳脉浮为卫气衰，芤为荣气伤。浮芤相抟，荣卫俱损，宗气衰微，不能充养四属，故“身体瘦，肌肉甲错”，四属断绝。芤脉中空，正示荣血伤而脉道不充；浮而无力，示卫外之气衰，故肌肉失荣而甲错。", ["浮", "芤"]], "18796": ["病机", "脉微为卫气疏，疏则肤空；缓为胃气实，谷消水化，血乃成。原文言“荣盛则其肤必疏，三焦绝经，名曰血崩”，是荣盛而卫疏，血虽盛而失统摄，三焦经隧失约，故致血崩。微缓并见，非纯虚纯实，乃卫疏胃实、荣盛失守之机。", ["微", "缓"]], "18797": ["病机", "趺阳脉微为虚，紧为寒，微紧相抟则为短气。微示中阳不足，紧示寒邪内束，阳虚而寒凝，气机升降不利，故短气。原文以“紧则为寒，微则为虚”对举，说明此短气由虚寒相合、胸中阳气不展所致。", ["微", "紧"]], "18798": ["病机", "少阴脉弱为微烦，涩为厥逆。弱示少阴气血不足，虚热内扰故微烦；涩示脉道不利、阳不外达，故厥逆。弱涩并见，说明少阴本虚而气血滞涩，烦与厥并作，非实热之烦，亦非单纯寒厥。", ["弱", "涩"]], "18799": ["病机", "趺阳脉不出，是胃脉隐伏不显，原文谓“脾不上下”，言脾胃升降之机阻绝，不能上下交通，故身冷而肤鞕。脉不出非无脉，乃胃气不能外达于趺阳，脾失运化，阳气不布，故身冷；营卫不濡肌肤，故肤鞕。", []], "18800": ["病机", "原文“少阴脉不至，肾气微，少精血”，脉不至示肾气衰微、精血亏少，致奔气上逆、宗气反聚、血结心下，阳气退下而热归阴股，与阴相动令身不仁，发为尸厥。脉不至为根本，说明肾中精气不能充脉，气机逆乱，故当刺期门、巨阙以通阳调气。", []], "18801": ["病机", "寸口脉微为阳虚，尺脉紧为阴寒内盛，原文“其人虚损多汗，知阴常在，绝不见阳也”，说明阴寒独存而阳气衰绝。虚损多汗乃阳不固阴，阴寒紧束于尺，阳气不能外达，故脉微紧并见，主阴阳离决之病机。", ["微", "紧"]], "18802": ["其他", "此段未出具体脉象，而言“录其证候、诊脉、声色，对病真方”，强调伤寒须逐日浅深施治，批评不早治、治不对病、不次第而治之误。主旨在于临证须消息制方、脉证声色合参，故归其他，非专论某脉主病。", []], "18803": ["病机", "尺寸俱浮为太阳受病，脉上连风府，故头项痛、腰脊强；尺寸俱长为阳明受病，脉侠鼻络目，故身热目疼鼻干不得卧；尺寸俱弦为少阳受病，脉循胁络耳，故胸胁痛而耳聋。三经未入府，脉象各随经气为病，可汗而已。", ["浮", "长", "弦"]], "18804": ["病机", "尺寸俱沉细为太阴受病，脉布胃中络嗌，故腹满嗌干；尺寸俱沉为少阴受病，脉贯肾络肺系舌本，故口燥舌干而渴；尺寸俱微缓为厥阴受病，脉循阴器络肝，故烦满而囊缩。三阴受病已入府，脉沉细、沉、微缓示邪入阴分，可下而已。", ["沉", "细", "微", "缓"]], "18805": ["预后", "原文列“脉浮滑”“脉濡弱者”“脉洪数”“脉实大者”“脉弦紧者”等，论两感于寒及传经预后。两感则表里俱病，三阴三阳五藏六府皆受病则荣卫不行、府藏不通而死；不两感者按期病衰。脉象随证而变，此段重在判断传变与死生愈期。", ["浮", "滑", "濡", "弱"]], "18806": ["预后", "原文“脉动数，服汤药更迟；脉浮大减小；初躁后静”，皆言病退之象。脉动数转迟为热减，浮大减小为邪衰，初躁后静为神安，故“此皆愈证也”。脉象由数、浮大转向和缓，说明正复邪退，预后向愈。", ["数", "浮", "大"]], "18807": ["死脉", "原文以平人呼吸次数与病人脉至对比定损：四损三日死、五损一日死、六损一时死。脉一至而平人四、五、六息，示脉气极度衰败，不能应呼吸而动，乃胃气已绝、真脏脉现之死候，故列死脉，判断危重期限。", []], "18808": ["病机", "以脉之盛虚辨伤寒伤暑之异。脉盛而身寒，为寒邪外束、阳气内郁，故脉盛；脉虚而身热，为暑热伤气、气耗不收，故脉虚而身热。脉象盛虚与身热身寒互参，说明病机在邪正交争与气耗之别，非单凭一症可断。", ["盛", "虚"]], "18809": ["预后", "脉阴阳俱盛，指寸尺皆见盛脉，邪气壅盛可知。大汗出而病不解，是邪热内闭、津液外泄而正气不支，盛脉不去则邪无出路，汗出更伤津气，故断为死候。原文以“大汗出，不解”点明正虚邪实、阴阳离决之势。", ["盛"]], "18810": ["预后", "脉阴阳俱虚，寸尺皆见虚象，示气血阴阳俱衰。虚脉本主不足，而热不止者，是阴不敛阳、虚阳外浮，热由虚生而非实邪。正虚而热不退，阴液日耗，故原文断为死候，强调虚脉与持续发热并见，预后不良。", ["虚"]], "18811": ["死脉", "脉至乍疏乍数，即脉来节律忽慢忽快，疏数交替。数为阳躁，疏为气衰，乍疏乍数示阴阳之气不相接续、胃气败乱。脉律无常则生机不续，故原文直断为死脉，属胃气已绝、真脏脉现之候。", ["数"]], "18812": ["死脉", "脉至如转索，形容脉来紧硬如绳索旋转，毫无柔和之象。转索之脉为紧脉之极，主邪气壅盛、胃气已竭，脉失冲和而现劲急。原文断“其日死”，强调此种脉象为真脏脉外露、生机将绝之危候。", ["紧"]], "18813": ["预后", "谵言妄语、身微热而脉浮大、手足温，是邪热尚在阳分、正气未败，故主生。若手足逆冷、脉转沉细，则阳衰阴盛、邪陷于里，正不胜邪，故“不过一日，死矣”。原文以脉之浮大与沉细、手足温与逆冷对举，辨阳气存亡以决预后。", ["浮", "大", "沉", "细"]], "18814": ["其他", "此段为篇题，标明辨痓、湿、暍三种病证的脉证专篇，并注“痓”字音义。原文未出具体脉象，故脉象要素为空。其主旨在于统摄痓湿暍三病之脉证辨析，属篇章总纲，非论某一脉所主病机。", []], "18815": ["主病", "太阳病本应脉浮，今发热而脉沉细，是邪不外达而内陷，筋脉失养而拘急，故名曰痓。沉细示正气不足、邪阻于里，与太阳表证之浮脉相异，原文以脉沉细为辨痓之要，说明发热而脉不浮反沉细者，当从痓论治。", ["沉", "细"]], "18816": ["主病", "原文未出脉名，然“病身热足寒，颈项强急，恶寒，时头热面赤，目脉赤，独头面摇，卒口噤，背反张”为痓病典型症候。身热足寒、恶寒示表邪未解，阳郁于上则头热面赤目赤，筋脉失养而强急、口噤、反张，头面摇为风动之象。此段以症候定病，脉象缺如，故脉素取空，主病机为外邪引动内风、筋脉拘急。", []], "18817": ["病机", "脉沉而细，沉主里、细主湿滞，湿邪痹阻关节，阳气不布，故关节疼痛而烦。湿痹之候，小便不利、大便反快，乃湿邪内盛、水走肠间，气化失司。脉沉细正合湿性重着黏滞、阻遏脉道之机，故当利小便以通阳化湿，此脉象揭示湿痹以里湿为主、非表邪所致。", ["沉", "细"]], "18818": ["病机", "湿家身疼痛、发热面黄而喘，头痛鼻塞而烦，其脉大。脉大非热盛，乃湿邪郁于上、阳气壅遏之象；自能饮食、腹中和无病，说明湿未入里，病在头中寒湿，故鼻塞。脉大与头面症候相应，示邪聚高位，内药鼻中取嚏以宣通上窍，此脉主湿郁于上之病机。", ["大"]], "18819": ["病机", "太阳中暍，身热疼重而脉微弱。微弱为阳气虚馁、水湿内停之象，夏月伤冷水，水行皮中，阻遏卫阳，故身热疼重。脉微弱与身热疼重并见，说明暑湿伤阳、水气不化，非单纯暑热，乃阴暑夹湿之候，脉象揭示正虚湿遏之病机。", ["微", "弱"]], "18820": ["病机", "太阳中暍，发热恶寒、身重疼痛，脉弦细芤迟。弦细为暑湿伤阴、筋脉失柔，芤迟为津气两伤、脉道不充。小便已洒洒然毛耸、手足逆冷，阳气虚而不达四末；小有劳身即热、口开齿燥，阴津亏耗。此脉象示暑热耗气伤津、湿阻阳郁之病机，故汗、温针、下法皆禁。", ["弦", "细", "芤", "迟"]], "18821": ["其他", "此段为“辨太阳病脉证并治上第五”篇题，非具体脉证条文，无脉象描述，亦无病机可析。篇题统摄太阳病诸脉证，提示后文将论太阳表证之脉浮、头项强痛等，但本段本身不构成独立病机分析，故脉素空、归为其他。", []], "18822": ["主病", "太阳之为病，脉浮，头项强痛而恶寒。脉浮为邪在表、卫阳浮盛抗邪之象，与头项强痛、恶寒相应，说明风寒袭表、太阳经气不利。浮脉主表，此条为太阳病提纲，揭示表证初起、邪未入里之病机，故以脉浮统摄太阳表证。", ["浮"]], "18823": ["主病", "太阳病，发热汗出恶风，脉缓者，名为中风。脉缓非平和之缓，乃营卫不和、汗出肌疏、脉道松弛之象，与发热汗出恶风相应，说明风邪袭表、卫强营弱。缓脉在此示表虚风伤卫之病机，故名为中风，区别于伤寒之脉紧无汗。", ["缓"]], "18824": ["主病", "脉阴阳俱紧，为寒邪束表、卫阳被遏之象。紧主寒主痛，寒性收引，故见恶寒体痛；表气不通，胃气上逆则呕逆。此脉说明太阳伤寒表实证，与发热恶寒、无汗而喘等症相应。", ["紧"]], "18825": ["病机", "脉数急为邪气内传、正邪交争之象。伤寒一日，脉若静则邪留太阳不传；今脉数急，说明邪热亢盛，传变入里，与颇欲吐、躁烦等症相应，提示病势进展。", ["数", "急"]], "18826": ["病机", "脉阴阳俱浮，为风温之邪充斥表里、热盛气浮之象。温病初起即见浮脉，风温则浮而兼数，热蒸津泄故自汗出；热壅气机则身重多眠、鼻息鼾、语言难出。此脉说明热邪弥漫三焦，与发热而渴、不恶寒相应。", ["浮"]], "18827": ["误治", "脉浮紧为寒邪束表、卫闭营郁之象。浮主表，紧主寒，发热汗不出，此麻黄汤证。桂枝汤本为解肌和营，若误用于浮紧无汗之伤寒表实证，则闭门留寇，故曰不可与之。此脉说明表寒实证，与发热无汗相应。", ["浮", "紧"]], "18828": ["治法", "脉促为误下后胸阳受损、邪陷胸中、阳气欲抗之象。促脉数中一止，主阳盛而郁，胸满为邪阻胸膈。下后中阳受伤，故去芍药之酸寒，专以桂枝通阳宣痹。此脉说明胸阳不振、邪陷胸膈，与胸满相应。", ["促"]], "18829": ["治法", "脉促胸满，为太阳病误下后邪陷胸中、胸阳被遏之象。促脉主阳郁不伸，胸满为邪阻气机。桂枝去芍药汤通阳宣痹，去芍药之阴柔，恐其碍阳。此脉说明胸阳不振、邪陷胸膈，与胸满相应。", ["促"]], "18830": ["预后", "脉微缓为邪气渐衰、正气来复之象。太阳病八九日，如疟状，热多寒少，脉由紧数转为微缓，说明邪退正复，为欲愈之兆。若脉微而恶寒，则阴阳俱虚，不可再汗吐下。此脉说明正邪进退，与寒热往来、清便自可相应。", ["微", "缓"]], "18831": ["预后", "脉微缓为邪退正复、病欲愈之象。太阳病日久，如疟状，热多寒少，脉转微缓，说明表邪渐解，正气来复。若脉微而恶寒，则阴阳俱虚，禁汗吐下。此脉说明正邪消长，与发热恶寒、热多寒少相应。", ["微", "缓"]], "18832": ["主病", "服桂枝汤后大汗出而脉洪大，为表证未解、阳热内盛之象。洪大脉主热盛，此段以脉洪大提示仍宜桂枝汤解表，若形似疟则属表郁轻证，用桂枝二麻黄一汤小发其汗。脉洪大在此非白虎汤证，因无大烦渴，故仍从表治。", ["洪", "大"]], "18833": ["主病", "本条与上条同文，脉洪大者，服桂枝汤大汗出后，表证未罢而阳热偏盛。洪大脉主热，然无烦渴，故仍与桂枝汤调和营卫；若寒热如疟一日再发，为表郁不解，宜桂枝二麻黄一汤。脉洪大在此提示表热未解，非里热炽盛。", ["洪", "大"]], "18834": ["主病", "服桂枝汤大汗出后，大烦渴不解而脉洪大，为阳明里热炽盛、津气两伤之候。洪大脉主热盛，大烦渴为热灼津伤，故用白虎加人参汤清热益气生津。此脉洪大与上条不同，彼无烦渴，此有烦渴，故治法迥异。", ["洪", "大"]], "18835": ["主病", "本条与上条同文，脉洪大见于大汗出后大烦渴不解，为阳明热盛、津气两伤。洪大脉主里热蒸腾，大烦渴为热盛伤津，故主白虎加人参汤。脉洪大在此明确为里热证，与表证脉洪大需鉴别于烦渴之有无。", ["洪", "大"]], "18836": ["病机", "太阳病发热恶寒、热多寒少而脉微弱，为阳气虚衰、表邪不解之候。微弱脉主阳气不足，故曰「此无阳也」，不可发汗，宜桂枝二越婢一汤微发其汗兼清里热。脉微弱在此提示正虚，不可峻汗，与表实脉浮紧者不同。", ["微", "弱"]], "18837": ["病机", "本条与上条同文，脉微弱见于太阳病热多寒少，为阳气虚弱、无阳以抗邪。微弱脉主阳虚，故不可发汗，宜桂枝二越婢一汤小汗兼清。脉微弱在此说明正虚不耐峻汗，与脉浮紧之表实证形成对比。", ["微", "弱"]], "18838": ["误治", "伤寒脉浮、自汗出、小便数、心烦、微恶寒、脚挛急，为表证兼阳虚津伤。脉浮主表，然小便数、脚挛急已示津液不足，反与桂枝攻表，此误也。误汗则厥、咽干、烦躁吐逆，故以甘草干姜汤复阳，芍药甘草汤伸脚，随证救治。", ["浮"]], "18839": ["误治", "本条与上条同文，脉浮为表证，但自汗、小便数、心烦、脚挛急已露津伤阳弱之机，反用桂枝攻表，致厥逆咽干烦躁吐逆。脉浮在此虽主表，然不可单纯解表，误治后变证蜂起，故列甘草干姜汤、芍药甘草汤、调胃承气汤、四逆汤等救逆诸法。", ["浮"]], "18840": ["病机", "脉浮为风邪在表，大为正虚，风邪外袭则生微热，正虚不能濡养则两胫拘急。此脉象似桂枝汤证而实兼阳虚，故单用桂枝增桂令汗出反致亡阳，出现厥逆、咽中干、谵语等症，说明病机为表邪未解而阳气已伤，虚风内动。", ["浮", "大"]], "18841": ["其他", "此段仅为《伤寒论》辨太阳病脉证并治中第六的篇题，未载具体脉象与证治内容，故无脉象要素可析，亦不涉及病机讨论，仅作为篇章标识。", []], "18842": ["病机", "太阳桂枝证误下后利遂不止，脉促为阳气被遏、抗邪外出之象，表明表邪未解而里热已迫。喘而汗出是热邪内陷阳明、迫肺蒸津所致，故用葛根黄芩黄连汤解表清里，此脉促提示表里同病、热势鸱张。", ["促"]], "18843": ["病机", "与上条同文，太阳病桂枝证误下，利遂不止而脉促，说明表邪未解、阳气受挫而仍欲抗邪。喘汗出为里热壅盛、肺胃受迫，故以葛根芩连汤清热止利、解表透邪，脉促在此反映表里合病、热邪内陷之病机。", ["促"]], "18844": ["兼症", "太阳病十日已去，脉浮细而嗜卧，浮为表邪未尽，细为正气已虚，嗜卧是邪退正复之象，故曰外已解。若胸满胁痛则邪入少阳，与小柴胡汤；脉但浮而不细，则表邪仍在，与麻黄汤，此以脉象辨邪之进退及兼症用药。", ["浮", "细"]], "18845": ["病机", "脉浮紧为风寒束表、卫阳被遏，故发热恶寒、身疼痛、不汗出而烦躁，属表寒里热之实证，宜大青龙汤。若脉微弱而汗出恶风，则属表虚阳弱，不可更发其汗，误服则亡阳厥逆、筋惕肉𥆧，此以脉之紧与微弱辨表实与表虚之异。", ["浮", "紧", "微", "弱"]], "18846": ["病机", "同前条，脉浮紧主风寒外束、里有郁热，故见发热恶寒、身疼、不汗出而烦躁，宜大青龙汤发汗兼清里热。脉微弱为阳气不足之象，汗出恶风者若误用大青龙则亡阳厥逆、筋惕肉𥆧，说明脉之紧与微弱是辨表实可汗与表虚禁汗的关键。", ["浮", "紧", "微", "弱"]], "18847": ["病机", "伤寒脉浮缓，浮为邪在表，缓为湿邪困阻、营卫不和，故身不疼但重、乍有轻时，此湿郁肌表而非少阴寒化。无少阴证则可用大青龙汤发越水湿、外解表邪，脉浮缓在此提示湿滞体表、阳气不宣之病机。", ["浮", "缓"]], "18848": ["治法", "脉浮为邪在表、正气趋外抗邪，弱则营卫不足、腠理疏松。外证未解而脉不紧实，说明表虚风邪留恋，非麻黄峻汗所宜，故当以汗解而取桂枝汤调和营卫、解肌祛风。浮弱并见正是桂枝汤证脉象依据。", ["浮", "弱"]], "18849": ["误治", "先发汗不解复下之，脉仍浮，说明邪未内陷而仍在表。原文点明「浮为在外，而反下之，故令不愈」，误下伤里而表邪未除，故病不愈。今脉浮故知病仍在外，当须解外则愈，宜桂枝汤，示人凭脉辨表里、不可妄下。", ["浮"]], "18850": ["病机", "脉浮紧、无汗、发热身疼痛，为寒邪束表、卫阳闭郁之麻黄汤证。八九日表证仍在，服药微除后发烦目瞑、剧者必衄，原文归因于「阳气重故也」，即阳郁太甚、不得汗解而迫血妄行，衄则郁阳得泄故解。", ["浮", "紧"]], "18851": ["预后", "脉浮紧、发热无汗，为寒邪闭表、阳郁不得外泄。原文言「自衄者愈」，因郁阳随衄血外泄，邪有出路，故不药自解。此与上条麻黄汤证衄乃解同理，示浮紧无汗之表实证可因衄而愈，属红汗之机。", ["浮", "紧"]], "18852": ["病机", "二阳并病，汗出不彻，阳气怫郁在表不得越，故面色缘缘正赤、躁烦、不知痛处、短气但坐。原文以「脉濇故知也」点明汗出不彻、营卫郁滞、气血运行不畅，涩脉正是邪郁肌表、汗孔闭塞之征，故更发汗则愈。", ["涩"]], "18853": ["误治", "脉浮数本为表热，法当汗出而愈；若误下则伤里，身重心悸。原文指出「尺中脉微，此里虚」，尺脉微主里气不足、津液亏虚，故不可再发汗，须待表里实、津液自和而自汗出愈，示凭尺脉辨虚实以定汗法禁例。", ["浮", "数", "微"]], "18854": ["病机", "脉浮紧主寒邪束表，法当身疼痛宜汗解；然「尺中迟者，不可发汗」，因尺候里、迟主血行不畅，原文断为「荣气不足，血少故也」。营血亏虚者虽见表实，亦不可峻汗伤营，示人凭尺脉迟以察营血之虚而禁汗。", ["浮", "紧", "迟"]], "18855": ["治法", "脉浮为邪在表、正气趋外，故原文直断「病在表，可发汗」。浮脉主表，与无汗表实相应，故宜麻黄汤发汗解表。此条以脉浮定病位在表、以脉定治，为凭脉用麻黄汤发汗之例。", ["浮"]], "18856": ["治法", "脉浮为邪在表，数为阳热亢盛，浮数相合，示表阳闭郁而热势外浮。原文据此断为可发汗，以麻黄汤开腠发汗，使表解热散。浮数在此非里热，而是表证未解、正气尚能抗邪之象，故为汗法之凭据。", ["浮", "数"]], "18857": ["病机", "原文未出脉名，以“病常自汗出”立论，指出“荣气和”而“卫气不共荣气谐和”，即营无病而卫外失固，营卫不相协调。汗出乃卫气不谐所致，故复发其汗以调营卫，营卫和则愈，宜桂枝汤。此段重在营卫失和之病机，非脉象主病。", []], "18858": ["主病", "脉浮紧为寒邪束表、卫阳闭遏之象，浮主表，紧主寒主痛。伤寒当汗不汗，表闭日久，阳郁化热，迫血妄行而致衄。原文以“不发汗，因致衄”点明病机，仍主以麻黄汤开表泄闭，使邪从汗解，则衄自止。", ["浮", "紧"]], "18859": ["主病", "发汗已解而半日许复烦，脉见浮数，说明余邪未尽、表热复聚。浮为邪仍在表，数为热势未清，故烦。原文断为“可更发汗”，以桂枝汤解肌调营卫，使表邪尽去。此浮数属表证复发，非里热内盛。", ["浮", "数"]], "18860": ["病机", "下之复汗，攻伐太过，阳气阴液两伤。脉微为阳虚无力鼓动，细为阴血不足、脉道不充，微细并见，正是“内外俱虚”之征。阳虚不能温煦，故必振寒。原文以脉微细点明阴阳俱虚之病机，非单主一脏。", ["微", "细"]], "18861": ["病机", "下后复汗，阳气骤虚，阴寒内盛。脉沉主里，微主阳虚，沉微示阳气衰微不能外达。昼日烦躁、夜而安静，乃虚阳外扰、入夜阳微更甚之象；不呕不渴、无表证、身无大热，排除实热。故以干姜附子汤急救回阳。", ["沉", "微"]], "18862": ["病机", "此段与上条同文，重申下后复汗致阳气虚衰。脉沉微为里阳不振、鼓动无力之候，昼烦夜静、不呕不渴、无表证、身无大热，皆示虚阳浮扰而非实邪。干姜附子汤温补回阳，正针对沉微所主之阳虚阴盛病机。", ["沉", "微"]], "18863": ["病机", "发汗后身疼痛，若脉浮紧当属表邪未尽，今脉沉迟，沉主里、迟主虚寒，示汗后营血耗伤、阳气不足，筋脉失养而痛。原文以脉沉迟断为里虚，故用桂枝新加汤加芍药、生姜、人参，益营气、温通血脉，非再发其表。", ["沉", "迟"]], "18864": ["病机", "发汗后身疼痛，脉见沉迟，沉主里、迟主虚寒，说明汗后营气耗伤、气血不足，筋脉失养而痛。此非表证未尽，乃里虚夹瘀滞之机，故以桂枝新加汤益气和营、通阳止痛。脉沉迟与身痛并见，提示虚多而邪少，不可再汗。", ["沉", "迟"]], "18865": ["病机", "吐下后心下逆满、气上冲胸、起则头眩，脉沉紧，沉主里、紧主寒饮内结，说明中阳受损、水饮上逆。此脉紧非表寒，乃饮邪内伏之象，故用苓桂术甘汤温阳化饮。若误发汗则动经，身为振振摇，更伤阳气。", ["沉", "紧"]], "18866": ["病机", "本条与上条同文，脉沉紧为里寒水饮内停之征。吐下伤中，饮邪上冲，故心下逆满、气上冲胸、头眩。沉紧之脉反映饮结于里而非表邪，治当温阳化饮，苓桂术甘汤主之。误汗则动经振摇，属阳虚饮动之变。", ["沉", "紧"]], "18867": ["病机", "发汗后大汗出，胃中干而烦躁，若脉浮、小便不利、微热消渴，则非单纯胃燥，而是太阳表邪未尽、膀胱气化不利，水蓄下焦。脉浮说明表邪仍在，与小便不利并见，主蓄水证，故用五苓散化气行水，兼解表邪。", ["浮"]], "18868": ["病机", "本条与上条同文，脉浮为太阳表邪未解之象，兼小便不利、微热消渴，说明水蓄膀胱、气化失司。脉浮在此不主单纯表证，而与蓄水证相应，故以五苓散通阳化气、利水渗湿，使表里之邪分消。", ["浮"]], "18869": ["病机", "发汗已，脉仍浮数，烦渴，说明表邪未尽而里热已起，水蓄下焦、气不化津。浮主表、数主热，浮数并见提示表里同病，以五苓散利水化气，使水去则热除、津布则渴止。此脉数非纯里热，乃水热互结之征。", ["浮", "数"]], "18870": ["误治", "本条未持脉而先观症：病人叉手自冒心，试令咳而不咳，知耳聋无闻，皆因重发汗虚其心阳与肾气。发汗后饮水多必喘，以水灌之亦喘，说明汗后阳虚，水寒上射于肺。原文虽未出脉，但以症测机，属误汗致虚、水气上逆之候。", []], "18871": ["误治", "衄家阴血本亏，不可发汗。汗出则额上陷、脉急紧，急紧为阴血亏耗、筋脉失濡而拘急之象，非表寒之紧。直视不能眴、不得眠，皆阴血不能上荣目系、心神失养所致。此脉急紧提示误汗后阴血更伤、虚风内动之机。", ["急", "紧"]], "18872": ["病机", "原文“病发热，头痛，脉反沈”，发热头痛为表证，脉应浮而反沉，说明正气不支，邪陷于里，阳气虚衰不能鼓动脉气外达。脉沉主里主虚，故“若不差，身体疼痛”，表证未解而里虚已急，当先救里，宜四逆汤温阳救逆。此脉沉揭示表病见里虚之机，不可再汗。", ["沉"]], "18873": ["病机", "原文“脉阴阳俱停”指寸尺脉一时隐伏不显，是邪正相争、气血郁滞之象，故“必先振栗汗出而解”。若“阳脉微者”，寸脉微示阳气不足，须先汗出而解；若“阴脉微者”，尺脉微示里气不足，可下之而解。脉微在此反映正气暂抑、邪欲外解或内结之机，非单纯虚象。", ["微"]], "18874": ["误治", "原文“脉迟浮弱”，迟为阳虚，浮弱为表虚，合之示表虚里寒。症见恶风寒、手足温，本属虚寒挟表，医反二三下之，伤其中气，故不能食、脇下满痛、面目及身黄、小便难，皆脾虚湿郁之变。脉迟浮弱已露里虚，误下更伤，故与柴胡汤后必下重，示中气下陷。", ["迟", "浮", "弱"]], "18875": ["主病", "原文“阳脉濇，阴脉弦”，阳脉涩示气滞血少，阴脉弦主痛主急，故“法当腹中急痛”。弦为肝木乘脾之象，涩为营血不充，木郁克土，筋脉拘急而痛。先与小建中汤温中缓急，不差者与小柴胡汤疏达肝木。脉弦涩并见，揭示虚寒腹痛兼肝郁之机。", ["濇", "弦"]], "18876": ["主病", "原文“阳脉濇，阴脉弦”，阳脉涩主气滞血少，阴脉弦主痛主急，故“法当腹中急痛”。弦为肝木乘脾，涩为营血不充，木郁克土，筋脉拘急而痛。先与小建中汤温中缓急，不差者与小柴胡汤疏达肝木。脉弦涩并见，揭示虚寒腹痛兼肝郁之机。", ["濇", "弦"]], "18877": ["误治", "原文“脉调和者，知医以丸药下之，非其治也”，又言“若自下利者，脉当微厥，今反和者，此为内实也”。脉微厥指脉微而手足厥冷，为虚寒下利之应；今脉反和，说明非虚寒而是内实燥结，故谵语、小便利、大便当鞕。脉和在此排除虚寒，揭示误下后内实仍在之机。", ["微"]], "18878": ["病机", "原文“寸口脉浮而紧”，浮为阳邪外浮，紧为寒束气机，症见腹满、谵语，此非阳明腑实，乃“肝乘脾也，名曰纵”。肝木亢盛，乘克脾土，气机壅滞故腹满，木火扰心故谵语。脉浮紧示邪在表而气机紧张，刺期门以泻肝木之实，疏泄其纵。", ["浮", "紧"]], "18879": ["误治", "原文“伤寒，脉浮，医以火迫劫之，亡阳，必惊狂，卧起不安”。脉浮本为表邪，医误用火法迫劫，汗出过多而亡阳，心神失守，故惊狂不安。脉浮在此既示原为表证，又因火劫后阳气外浮不敛，揭示误治致亡阳、心神浮越之机，故用救逆汤敛阳安神。", ["浮"]], "18880": ["误治", "伤寒脉浮，本为表证，医误以火法迫劫，致汗出过多而亡阳。浮脉在此示邪在表，火劫后阳气外越，心神失守，故见惊狂、卧起不安。脉浮与亡阳并见，说明表邪未解而阳气已伤，火逆之变由浮脉可察。", ["浮"]], "18881": ["病机", "形似伤寒而脉不弦紧反弱，弱为津血不足，故必渴；若被火则津伤热炽而谵语。弱而发热脉浮，示邪仍在表而正已虚，当以汗解。脉弱与浮并见，说明表邪未罢而津气已伤，不可妄攻。", ["弱", "浮"]], "18882": ["误治", "脉浮热甚，本为表实热证，反以灸法温补，是实以虚治。火气内攻，因火而动，热伤血络，故咽燥吐血。浮脉主热在表，灸之则热不得外泄而内迫，此火逆之变由浮脉与热甚并见可推。", ["浮"]], "18883": ["误治", "微数之脉，数主热而微为虚，慎不可灸。火邪内攻，追虚逐实，血散脉中，焦骨伤筋。脉浮宜汗解，反灸则邪无从出，因火而盛，腰以下重痹，名火逆。脉浮示邪在表，故知汗出可解，先烦乃解之兆。", ["数", "浮"]], "18884": ["误治", "太阳病当恶寒发热，今自汗出而不恶寒发热，关上脉细数，为医吐之过。细为津伤，数为虚热，吐后胃气受损，故腹中饥而口不能食，或朝食暮吐。脉细数示吐后中虚热扰，此小逆之候。", ["细", "数"]], "18885": ["病机", "病人脉数，数本主热，当消谷引食，今反吐者，因发汗太过，阳气微，膈气虚，脉乃数也。此数为客热，非真热，不能消谷，胃中虚冷故吐。数脉在此示虚阳外浮之假热，与胃中虚冷并见，当辨其虚实。", ["数"]], "18886": ["病机", "太阳病六七日表证仍在，脉微而沉，反不结胸而发狂，为热在下焦，少腹硬满，小便自利，瘀热在里，下血乃愈。微为阳气不显，沉为病在里，脉微沉示表邪随经入里，瘀热结于下焦，抵当汤主之。", ["微", "沉"]], "18887": ["病机", "太阳病六七日表证仍在，脉微而沉，反不结胸而发狂，为热在下焦，少腹硬满，小便自利，瘀热在里，下血乃愈。微为阳气不显，沉为病在里，脉微沉示表邪随经入里，瘀热结于下焦，抵当汤主之。", ["微", "沉"]], "18888": ["病机", "脉沉主里，结主气血凝滞。太阳病身黄而脉沉结，少腹鞕、小便不利，是瘀热与湿相结于下焦，病在气分而非血分，故曰“为无血也”；若小便自利而其人如狂，则瘀血已成，脉沉结正是血蓄下焦、络脉不畅之征，故断为血证谛，主以抵当汤。", ["沉", "结"]], "18889": ["其他", "此段仅为《伤寒论·辨太阳病脉证并治下第七》篇题，未载具体脉象与证治内容，故脉象要素为空。篇题提示该篇讨论太阳病下篇诸证，包括结胸、藏结、痞证等，但本条本身不构成独立病机分析，仅作篇章标识。", []], "18890": ["病机", "寸脉浮、关脉沉，按之痛，为结胸主脉。寸浮示阳热郁于上，关沉示水饮结于中，阳热与水饮互结，故按之硬痛。此脉象说明邪热内陷与胸中水饮相结，病位偏上，属结胸实证，与“按之痛”相应，非藏结之虚寒。", ["浮", "沉"]], "18891": ["病机", "寸脉浮、关脉小细沉紧，为藏结主脉。寸浮示阳气浮越于上，关小细沉紧示脏气虚寒、阴寒内结，气血凝滞。饮食如故而时时下利，是脏寒不运、下焦不固。舌上白胎滑者，阴寒更甚，故曰难治。此脉说明正虚寒结之病机。", ["浮", "小", "细", "紧"]], "18892": ["预后", "结胸证脉浮大，浮为邪盛于表，大为正虚不敛，是表邪未解而里结未成实之象。此时不可下，下之则伤正引邪内陷，故曰“下之则死”。此条以脉浮大判断结胸禁下，说明脉象反映正虚邪结、表里同病之机，下法当慎。", ["浮", "大"]], "18893": ["病机", "脉浮而动数，浮为风，数为热，动为痛，数为虚，是表邪未解而里已化热之象。医反下之，动数变迟，迟为阳气内陷、邪结于里，故膈内拒痛、心下因鞕而成结胸。若邪不外陷而郁于上，则头汗出、小便不利、身发黄。此脉说明误下后邪热内陷与水饮相结之病机。", ["浮", "数", "动", "迟"]], "18894": ["病机", "本条与上条文字相同，脉浮而动数，浮为风，数为热，动为痛，数为虚，示表邪未解。医反下之，动数变迟，迟为阳气内陷、邪结于里，故膈内拒痛、心下因鞕而成结胸。若邪郁于上，则头汗出、小便不利、身发黄。脉象变化说明误下致邪热内陷与水饮相结之病机。", ["浮", "数", "动", "迟"]], "18895": ["病机", "脉沉而紧，沉主里，紧主痛主实。伤寒六七日，结胸热实，心下痛、按之石鞕，是邪热与痰水互结于胸膈，病位在里且实，故脉沉紧。此脉说明热实内结、气血壅滞之病机，与“按之石鞕”相应，主以大陷胸汤泻热逐水破结。", ["沉", "紧"]], "18896": ["主病", "脉浮滑者，浮主病位在上在表，滑主痰热内壅。小结胸病位正在心下，按之则痛，为痰热互结于心下，故脉见浮滑。浮示邪热偏上，滑示痰热胶结，与黄连、半夏、栝蒌实清热化痰开结之治法相应。", ["浮", "滑"]], "18897": ["主病", "脉浮滑者，浮为热邪偏上，滑为痰热内结。小结胸病正在心下，按之则痛，乃痰热互结于心下所致。脉浮滑正反映痰热壅结之病机，故主以小陷胸汤清热涤痰开结。", ["浮", "滑"]], "18898": ["病机", "脉微弱者，微弱主正气不足、里虚有寒。太阳病二三日，不能卧但欲起，心下必结，脉微弱说明本有寒分内伏，非实热结聚。反下之则伤正，若利止则寒邪内陷作结胸，未止则协热下利，脉微弱正是里虚寒分之征。", ["微", "弱"]], "18899": ["预后", "太阳病下后，脉促不结胸为欲解；脉浮必结胸，紧必咽痛，弦必两脇拘急，细数头痛未止，沈紧欲呕，沈滑协热利，浮滑下血。诸脉各主不同变证，示误下后邪气传变之预后，脉象为辨变证之关键。", ["促", "浮", "紧", "弦"]], "18900": ["误治", "太阳少阳并病，本有头项强痛、眩冒、心下痞鞕，慎不可发汗。发汗则谵语、脉弦，弦为少阳木旺之象，汗伤津液，少阳邪热内扰神明，故谵语不止。脉弦示少阳邪盛，当刺期门以泻其实。", ["弦"]], "18901": ["病机", "妇人中风，经水适来，七八日后热除而脉迟身凉，胸脇下满如结胸状，谵语者，为热入血室。脉迟身凉示热邪内陷血分，外热已除而血分瘀热未解，故胸脇满、谵语，当刺期门随其实而泻之。", ["迟"]], "18902": ["病机", "伤寒五六日，头汗出、微恶寒、手足冷、心下满、口不欲食、大便鞕，脉细者，为阳微结，半在里半在外。脉虽沈紧，不得为少阴病，因阴不得有汗，今头汗出，故知非少阴。脉细示阳微，沈紧示里有结，可与小柴胡汤和解。", ["细", "沉", "紧"]], "18903": ["病机", "脉浮而紧，本为太阳伤寒表实之脉，反下之则紧反入里，邪气内陷，结于心下则作痞。按之自濡，但气痞耳，说明无形邪气壅滞，非有形实结。脉浮紧示表邪因误下而内陷，紧反入里正是气机痞塞之病机。", ["浮", "紧"]], "18904": ["主病", "脉关上浮，关候中焦，浮为阳热之象。心下痞按之濡，说明无形邪热痞塞中焦气分，非有形实邪结聚。热郁气壅，故关上脉浮，治以大黄黄连泻心汤清泄中焦邪热。", ["浮"]], "18905": ["主病", "关上浮脉主中焦有热。心下痞满而按之柔软，为无形邪热痞塞气分，非实结。热郁则脉浮见于关部，故用大黄黄连泻心汤清泄中焦之热，以消痞满。", ["浮"]], "18906": ["病机", "伤寒吐下发汗，重伤阳气阴液，故脉甚微。阳虚不能化气行水，水气上冲，则心下痞硬、胁下痛、气上冲咽喉、眩冒；经脉动惕为阳虚水气窜动。久则阳气阴液俱虚，筋脉失养而成痿。", ["微"]], "18907": ["病机", "寸脉微浮，寸候上焦，浮主邪在上。胸中痞硬、气上冲咽喉不得息，为胸中寒痰宿食壅塞，气机不得下降。病位在上，故脉见寸浮，治当因势利导，用瓜蒂散吐之。", ["浮"]], "18908": ["病机", "寸脉微浮，提示邪在上焦。胸中痞硬、气上冲咽喉不得息，为胸中寒痰壅塞，气逆不降。脉浮病位在上，故宜瓜蒂散因势吐之，祛除胸中寒痰。", ["浮"]], "18909": ["误治", "脉浮、发热无汗为伤寒表实证，表邪未解。此时若误用白虎汤清里，则表邪冰伏，故不可与。必待表证已解，仅见渴欲饮水者，方可用白虎加人参汤清热益气生津。", ["浮"]], "18910": ["主病", "脉浮虚而涩，浮为风邪在表，虚为阳气不足，涩为湿邪阻滞、气血不畅。风湿相搏，痹阻肌表经络，故身体疼烦、不能自转侧。治以桂枝附子汤温经散寒、祛风除湿。", ["浮", "虚", "涩"]], "18911": ["主病", "浮虚而涩之脉，主风湿相搏。浮为风，虚为阳虚，涩为湿滞。风湿痹阻，营卫不通，故身体疼烦、不能自转侧。桂枝附子汤温阳祛风除湿；若大便硬、小便自利，则去桂加白术以健脾燥湿。", ["浮", "虚", "涩"]], "18912": ["主病", "脉浮为邪在表，滑为里热炽盛。原文言\"表有热，里有寒\"，然脉浮滑并见，实为热邪充斥表里、阳明热盛之象，故以白虎汤清解里热。浮主表热未解，滑主里热已成，脉症合参，知热势弥漫，非单纯表证。", ["浮", "滑"]], "18913": ["主病", "脉浮滑，浮为热越于表，滑为热盛于里。原文\"表有热，里有寒\"，然滑脉主热，浮脉主表，合而观之，实为阳明热邪亢盛、充斥内外之候。白虎汤清阳明独盛之热，脉浮滑正是热势张扬、气血涌盛之征。", ["浮", "滑"]], "18914": ["主病", "脉结代并见，结为脉来缓而时一止，代为止有常数、不能自还，皆主心气不足、血脉不畅。原文\"心动悸\"，正是气血亏虚、心失所养之症。炙甘草汤益气滋阴、通阳复脉，脉结代与心动悸相应，说明心之气血两虚、脉道不充。", ["结", "代"]], "18915": ["主病", "脉结代，结为缓而时止、止无定数，代为止有定数、不能自还，二者皆属阴脉，主心气虚弱、血脉运行不畅。原文\"心动悸\"，为气血亏虚、心失所养之候。炙甘草汤通阳复脉、益气养血，正对结代脉所反映的心之气血两虚病机。", ["结", "代"]], "18916": ["其他", "此段为炙甘草汤方后煎服法及别名\"复脉汤\"的记载，未涉及脉象描述。\"复脉\"之名提示该方主治脉结代、使脉复常，但本段文字本身属方剂用法，无脉象要素可析，故脉象要素为空，主旨归为其他。", []], "18917": ["预后", "原文详辨结、代二脉：\"按之来缓，时一止复来\"为结；\"动而中止，更来小数，中有还者反动\"亦为结，属阴；\"动而中止，不能自还，因而复动\"为代，属阴。结代皆主气血虚衰、脉道不利，原文明言\"得此脉者，必难治\"，故主旨为预后判断。", ["缓", "结", "代", "数"]], "18918": ["其他", "此段为\"辨阳明病脉证并治第八\"篇题，属篇章标题，未含具体脉象描述与病机分析。篇题仅标示论述范围，无脉象要素可提取，故脉象要素为空，主旨归为其他，不作病机推断。", []], "18919": ["病机", "原文\"伤寒三日，阳明脉大\"，大脉主邪热亢盛、气血涌盛。伤寒三日邪传阳明，阳明多气多血，热邪入里，正邪交争剧烈，气血充盈脉道，故脉象洪大。此脉大反映阳明热盛之病机，为阳明病典型脉象，与阳明里热证候相应。", ["大"]], "18920": ["病机", "脉浮为邪在表，缓为太阴湿土之象，浮缓并见说明邪已由阳转属太阴。手足自温是太阴有阳、湿郁未化热之征，故身当发黄；若小便自利则湿有出路，不能发黄。至七八日大便鞕，是湿从燥化转归阳明。全段以脉浮缓定太阴病机及转归。", ["浮", "缓"]], "18921": ["误治", "脉浮而紧，浮为在表，紧为寒束，说明阳明中风而表邪未解，故见口苦咽干、腹满微喘、发热恶寒。表未解而误下，则里气受伤，腹满不减而小便难。原文以脉浮紧提示表证尚存，不可径下，属误治之戒。", ["浮", "紧"]], "18922": ["预后", "水不胜谷气，谷气胜则正气奋起驱邪，与汗共并而濈然汗出，奄然发狂是正邪交争之象。脉紧则愈，紧为邪气尚实、正气能鼓邪外出，故汗出而解。此段以脉紧判断胃气尚强、水湿不能胜谷气，属预后良好之征。", ["紧"]], "18923": ["病机", "脉迟为胃中虚冷、谷气不化，故食难用饱，饱则微烦头眩，小便难，湿郁欲作谷瘅。虽下之而腹满如故，正因脉迟示中焦虚寒，非实热可下。原文以脉迟故也点明病本在虚寒，下之无功，说明谷瘅由胃虚湿滞而成。", ["迟"]], "18924": ["兼症", "脉浮而紧，浮为阳热外浮，紧为邪实内结，故必潮热发作有时，是阳明里实之候。但浮不紧者，阳热偏盛而迫津外泄，故必盗汗出。原文以浮紧与但浮对举，说明同一阳明病脉象不同则兼症各异，浮紧主潮热，但浮主盗汗。", ["浮", "紧"]], "18925": ["治法", "脉迟虽汗出不恶寒，然身重短气、腹满而喘、潮热，是里实已成而脉反迟，迟为邪结气滞、脉道不利。手足濈然汗出为大便已鞕之征，故可攻里，大承气汤主之；若外未解、热不潮则不可与，腹大满不通者只可与小承气微和胃气。全段以脉迟辨可攻与不可攻。", ["迟"]], "18926": ["治法", "脉迟而汗出不恶寒，身重短气、腹满而喘、潮热，说明表已解而里实结聚，迟脉主邪结气滞而非虚寒。手足濈然汗出示大便已鞕，故大承气汤主之；若微发热恶寒则外未解，热不潮不可与承气；腹大满不通者与小承气微和胃气，勿令大泄下。以脉迟定攻下分寸。", ["迟"]], "18927": ["预后", "发汗多又重发汗，亡其阳而谵语，是阳气外脱、心神失守。脉短者，短为气衰不能接续，阴阳气血俱竭，故主死；脉自和者，虽亡阳而脉气未败，阴阳尚能自和，故不死。原文以脉短与脉自和对比，判断亡阳谵语之预后吉凶。", ["短"]], "18928": ["预后", "伤寒吐下后不解，潮热谵语、循衣摸床、微喘直视，为邪热炽盛、阴液耗竭之危候。脉弦者，弦为肝脉，尚存胃气生机，故主生；脉涩者，涩为血少津枯，阴竭血涩，故主死。此以脉之弦涩判胃气阴液之存亡，非主病之脉。", ["弦", "涩"]], "18929": ["病机", "阳明谵语潮热，脉滑而疾，滑主食积、疾主热盛，为里实燥结之征，故小承气汤主之。若下后不大便而脉反微涩，微为气虚，涩为血少，是里虚津亏，攻下更伤正气，故为难治，不可再与承气汤。", ["滑", "疾", "微", "涩"]], "18930": ["误治", "伤寒四五日，脉沉而喘满，沉为在里，病本在里而反发其汗，致津液越出，肠燥便难，表虚里实，久则谵语。此段以脉沉明里实，指出误汗伤津、表虚里实之变，非主病之脉。", ["沉"]], "18931": ["病机", "阳明病脉浮而紧，浮为热越于外，紧为邪结于里，咽燥口苦、腹满而喘、发热汗出、不恶寒反恶热、身重，为阳明里热兼表邪未解之候。若误汗则津伤躁烦谵语，温针则怵惕不眠，下之则胃虚客气动膈而懊憹，示人不可妄攻。", ["浮", "紧"]], "18932": ["主病", "脉浮发热，渴欲饮水，小便不利，为水热互结、气化不行之候。浮脉主热盛于外，亦示病位偏表；水热内蓄，津不上承故渴，膀胱气化失司故小便不利。猪苓汤育阴清热利水，使水去热清，脉浮自解。", ["浮"]], "18933": ["主病", "脉浮发热，渴欲饮水，小便不利，为水热互结、气化不利之证。浮脉主热盛于外，亦示病位偏表；水蓄下焦，津不上承则渴，气化不行则小便不利。猪苓汤滋阴清热利水，水热去则脉浮发热自平。", ["浮"]], "18934": ["病机", "脉浮而迟，浮为阳热在外，迟为阴寒在里，表热里寒，下利清谷，为脾肾阳虚、阴寒内盛之候。浮脉非表邪，乃虚阳外浮；迟脉主脏寒。四逆汤温里回阳，使阳复寒散，则浮迟之脉自和。", ["浮", "迟"]], "18935": ["病机", "脉浮发热，口干鼻燥，能食者则衄，为阳明热盛、迫血妄行之候。浮脉主热盛于外，热循经上扰，口干鼻燥；能食示胃热未结，热不得下泄，迫血上溢而为衄。此以脉浮辨热盛致衄之机。", ["浮"]], "18936": ["主病", "脉弦浮大，为阳明中风，风邪外袭，少阳枢机不利，故脉弦；邪郁肌表，故浮；热势渐盛，故大。症见短气、腹满、胁下及心痛、鼻干、不得汗、嗜卧、一身及目悉黄、小便难、潮热、时时哕、耳前后肿，皆三阳合病、湿热郁蒸之候。刺之小差而外不解，脉续浮者，示邪仍偏表，故与小柴胡汤和解枢机。", ["弦", "浮", "大"]], "18937": ["预后", "脉但浮，无余证，说明表邪未解而里热不盛，故与麻黄汤发汗解表。若不尿、腹满加哕，则气机壅塞，胃气上逆，三焦水道不通，正虚邪实，故曰不治。此段以脉浮辨表证尚存，以不尿、腹满、哕判预后不良，突出脉症合参。", ["浮"]], "18938": ["病机", "阳明病脉迟，非里实热结之数脉，乃汗出多、微恶寒，表邪未解，阳气为汗所伤，鼓动无力，故脉迟。此迟为表虚寒象，非阳明腑实之迟。表未解，可发汗，宜桂枝汤调和营卫。原文以脉迟辨表证未罢，提示不可早下。", ["迟"]], "18939": ["主病", "阳明病脉浮，无汗而喘，为风寒束表，肺气不宣，邪偏于表。脉浮主表，无汗喘促为表实，故发汗则愈，宜麻黄汤开腠发汗。此条虽冠阳明病，实为表证未解，脉浮为辨证眼目，示邪仍在太阳之表。", ["浮"]], "18940": ["治法", "病人烦热，汗出则解，又如疟状，日晡所发热，属阳明。脉实者，邪热内结，腑实已成，故宜下之，与大承气汤；脉浮虚者，表邪未解，正气偏虚，故宜发汗，与桂枝汤。此以脉实、浮虚辨表里虚实，定汗下之法，脉象为治法之关键。", ["实", "浮", "虚"]], "18941": ["病机", "阳脉微而汗出少者，为自和；汗出多者为太过，阳脉实。因发其汗，出多者亦为太过，太过则阳绝于里，亡津液，大便因鞕。脉微为阳气不足，脉实为邪热内盛，汗多伤津，阳热独亢于里，津亏肠燥，故大便鞕。此段以脉微、脉实辨汗出太过与津液存亡。", ["微", "实"]], "18942": ["病机", "脉浮而芤，浮为阳，芤为阴，浮芤相抟，胃气生热，其阳则绝。浮主阳热有余，芤主阴血不足，阳热与阴伤相合，胃中燥热内生，阴液竭绝，阳无所附，故曰其阳则绝。此以浮芤并见，说明胃热津伤、阴阳不相维系之病机。", ["浮", "芤"]], "18943": ["病机", "趺阳脉浮而濇，浮则胃气强，濇则小便数，浮濇相抟，大便则鞕，其脾为约。浮为胃热亢盛，濇为津液不足，小便数则津液偏渗，肠失濡润，故大便鞕。此脾约证，以脉浮濇说明胃强脾弱、津亏肠燥之病机，麻子仁丸主之。", ["浮", "濇"]], "18944": ["病机", "趺阳脉浮为胃气强，涩为津液不足而小便数，浮涩相抟则津液偏渗、肠道失润，故大便鞕而成脾约。此脉象揭示胃热盛而脾阴弱、约束津液之病机，主脾约证，与小便数、大便鞕相应，故以麻子仁丸润肠泄热。", ["浮", "涩"]], "18945": ["病机", "得病二三日脉弱，说明正气不足而邪未全实，虽烦躁心下鞕，仍不可峻攻。脉弱提示胃气未充，故先以小承气汤微和，待小便利、屎定鞕方可用大承气。此脉主正虚邪结之病机，与烦躁、心下鞕、不大便等症相应，示攻下须审慎。", ["弱"]], "18946": ["主病", "阳明少阳合病下利，脉滑而数，滑主宿食内积，数主热盛，说明宿食化热、壅滞肠道之病机。脉不负为顺，负则木克土为逆。此脉主宿食内结之病，与下利、宿食相应，故当下之，宜大承气汤荡涤积热。", ["滑", "数"]], "18947": ["病机", "病人无表里证而发热七八日，脉浮数者，示热邪偏盛于外；已下后脉数不解，合热则消谷善饥，至六七日不大便，说明热与瘀血相合、蓄于下焦之病机。脉数不解主瘀血内结，与消谷善饥、不大便相应，故宜抵当汤破血逐瘀。", ["浮", "数"]], "18948": ["预后", "若脉数不解而下不止，数脉主热，下不止为热迫肠道，热与下利相协，必致协热便脓血。此脉说明热邪内陷、灼伤血络之病机，主协热下利脓血之变证，与下不止、便脓血相应，属误下后热邪未解之预后转归。", ["数"]], "18949": ["其他", "此段为辨少阳病脉证并治篇题，未出具体脉象，故脉象要素为空。篇题统摄少阳病脉证，提示少阳病以脉弦细、口苦咽干目眩、往来寒热等为提纲，属六经辨证之篇目，非具体病机分析，故归其他类。", []], "18950": ["病机", "伤寒脉弦细，弦为少阳主脉，细为邪入半表半里、气血不畅，说明邪郁少阳、枢机不利之病机。头痛发热属少阳，故不可发汗，发汗则谵语属胃，胃和则愈，胃不和则烦而悸。此脉主少阳病，与头痛发热相应。", ["弦", "细"]], "18951": ["病机", "本太阳病不解转入少阳，脇下鞕满、干呕不能食、往来寒热，为少阳证具；脉沉紧说明邪已离表入里、结于少阳之病机。沉紧非表脉，故不与柴胡汤解表，而与少阳和解，主少阳枢机不利，与脇下鞕满、往来寒热相应。", ["沉", "紧"]], "18952": ["病机", "三阳合病，脉浮大，浮为太阳之邪未解，大为阳明热盛，脉势上关上，示邪热壅盛于上中二焦。热盛神昏故但欲眠睡，目合则阳气入阴，热迫津液外泄而汗出。此脉主阳热炽盛、三阳合病之机，与但欲眠睡、目合则汗相应。", ["浮", "大"]], "18953": ["预后", "伤寒三日，邪传少阳，其脉当弦。今少阳脉小者，小为邪气已衰之象，脉不弦大而反小，说明少阳之邪渐退，正气来复，故为欲已之候。此脉主邪退向愈之机，与伤寒三日病程相应，属预后良好之征。", ["小"]], "18954": ["其他", "此段为辨太阴病脉证并治篇目，非具体脉象条文，无脉象描述可析。篇目统括太阴病之脉证治法，提示太阴病以脉浮缓、手足自温、腹满而吐、自利益甚等为提纲，主脾阳虚弱、寒湿内盛之病机，与后文具体条文相呼应。", []], "18955": ["预后", "太阴中风，四肢烦疼，脉阳微阴濇而长。阳微示表邪已衰，阴濇为营血不畅，长为正气渐复之象。脉由濇转长，说明邪气将退、气血渐和，故为欲愈之候。此脉主太阴中风邪退向愈之机，与四肢烦疼渐解相应。", ["微", "濇", "长"]], "18956": ["治法", "太阴病脉浮者，浮为邪在表，太阴本脉当缓弱，今脉浮说明太阴之邪有外达之势，可因势利导而发汗，宜桂枝汤解肌和营。此脉主太阴表证、邪欲外解之机，与太阴病兼见表证相应，属治法条文。", ["浮"]], "18957": ["病机", "伤寒脉浮而缓，手足自温，系在太阴。浮为表邪，缓为脾湿，手足自温示太阴脾阳尚能温煦四末。太阴湿郁当发身黄，若小便自利则湿有出路而不发黄。至七八日暴烦下利，为脾家实、腐秽当去，脉缓主湿，与脾阳来复、驱邪外出之机相应。", ["浮", "缓"]], "18958": ["误治", "太阴为病脉弱，弱为胃气虚弱之象，其人续自便利，示脾虚不运、清浊不分。设当行大黄、芍药等苦寒攻下之品，宜减其量，因胃气本弱，易为苦寒所动。此脉主胃气虚弱、脾运不健之机，与自便利及攻下宜慎之戒相应。", ["弱"]], "18959": ["其他", "此段为辨少阴病脉证并治篇目，非具体脉象条文，无脉象描述可析。篇目统括少阴病之脉证治法，提示少阴病以脉微细、但欲寐为提纲，主心肾阳衰、阴寒内盛之病机，与后文具体条文相呼应。", []], "18960": ["病机", "少阴病提纲。脉微为阳气虚衰，脉细为阴血不足，微细并见，示心肾阴阳俱虚、气血衰少，故见但欲寐之精神萎靡。此脉主少阴本证之虚寒病机，非表实，故不可发汗。", ["微", "细"]], "18961": ["病机", "脉阴阳俱紧本主寒，今反汗出，是阴寒内盛、虚阳外亡之象。紧脉在此非表寒，而为少阴亡阳、寒凝内外之征，故属少阴，法当咽痛而复吐利，示虚阳上浮、中焦虚寒之病机。", ["紧"]], "18962": ["病机", "脉细为阴血虚少，沉主病在里，数为虚热内扰。细沉数并见，说明少阴病邪已入里，非在表，故不可发汗。此脉示里虚有热之病机，发汗则更伤阴液阳气。", ["细", "沉", "数"]], "18963": ["病机", "脉微为阳气衰亡，故不可发汗；阳已虚而尺脉弱濇，弱主阳虚，濇主血少，示下焦阴阳俱虚，故复不可下。此段以脉微、尺弱濇说明少阴亡阳、下元虚损之病机，汗下皆禁。", ["微", "弱", "濇"]], "18964": ["预后", "少阴病脉紧为寒盛，至七八日自下利而脉暴微，是寒邪随利外泄、紧脉去而阳复之象。手足反温、紧去，示阳气来复，故为欲解，虽烦下利必自愈。此段以脉紧转微说明邪退阳复的预后转归。", ["紧", "微"]], "18965": ["预后", "少阴中风，阳脉微为表邪已衰，阴脉浮为里阳来复、邪从外解。阳微阴浮并见，示正气渐复、邪气衰退，故为欲愈。此段以脉象变化判断少阴中风向愈之机，属预后之论。", ["微", "浮"]], "18966": ["预后", "少阴病吐利而手足不逆冷、反发热，是阳气尚存、未至厥逆，故断为不死。脉不至为阳气一时不能接续，灸少阴以温通阳气。此段以手足温、发热与脉不至对举，论少阴病阳气存亡之预后。", []], "18967": ["死脉", "少阴病四逆、恶寒身踡，为阳气衰微；脉不至则阳气已绝，不能鼓动血脉；不烦而躁，是阴盛格阳、神气散乱之危候。脉不至而躁，示阴阳离决，故主死。此段以脉不至合躁逆判少阴死候。", []], "18968": ["预后", "少阴病脉微细沉，微为阳气衰微，细为阴血不足，沉主病在里，阳气不能外达，故但欲卧；汗出而不烦，是阳衰于外、虚阳外越之象；自欲吐为阴寒上逆。至五六日自利更伤中阳，复烦躁不得卧寐，乃阴盛格阳、残阳欲脱之危候，故断为死。", ["微", "细", "沉"]], "18969": ["治法", "少阴病始得之，本应脉微细但欲寐，今反发热而脉沉，沉主里，知非单纯表证，乃少阴阳虚兼外感寒邪，太阳少阴两感。脉沉说明阳气不足、寒邪直中，故用麻黄细辛附子汤温经解表，附子温少阴之阳，麻黄散太阳之寒，细辛通彻表里。", ["沉"]], "18970": ["治法", "本条与上条同文，少阴病始得之反发热而脉沉，沉为在里，发热为寒邪外束、虚阳外浮。脉沉揭示少阴阳虚为本，故不可纯用汗法，主以麻黄细辛附子汤温阳解表，使寒从表解而阳不外脱，体现少阴兼表之治法。", ["沉"]], "18971": ["病机", "少阴病身体痛、手足寒、骨节痛而脉沉，沉主里主寒，说明少阴阳气虚弱，寒湿内盛，阳气不能温煦四肢，故手足寒；寒湿留着筋骨肌肉，气血凝滞不通，故身体痛、骨节痛。脉沉正是阳虚寒盛在里之征，故用附子汤温经散寒、除湿止痛。", ["沉"]], "18972": ["预后", "少阴病下利而脉微，微为阳气衰微，阴寒内盛，故与白通汤破阴回阳。若利不止、厥逆无脉、干呕烦，是阴盛格阳、虚阳上扰，用白通加猪胆汁汤引阳入阴。服汤后脉暴出者，是残阳尽泄于外，故死；脉微续者，是阳气渐复，故生。", ["微"]], "18973": ["预后", "本条与上条同文，少阴病下利脉微，主阳气衰微、阴寒内盛。白通汤通阳破阴；若厥逆无脉、干呕烦，为阴盛格阳，加猪胆汁、人尿引阳入阴。服汤后脉暴出为孤阳外脱之死候，微续为阳气渐回之生兆，脉象变化直接判断预后吉凶。", ["微"]], "18974": ["病机", "少阴病下利清谷、手足厥逆、脉微欲绝，是阴寒内盛、阳气衰微欲脱之象；身反不恶寒、面色赤，为虚阳被阴寒格拒于外之上热下寒、里寒外热证。脉微欲绝说明心肾阳气将竭，故用通脉四逆汤大剂回阳救逆，脉即出者阳回而愈。", ["微"]], "18975": ["病机", "本条与上条同文，下利清谷、手足厥逆、脉微欲绝，主阴寒内盛、阳气衰微；身反不恶寒、面赤为阴盛格阳、虚阳浮越。脉微欲绝是阳气欲脱之危象，故以通脉四逆汤急温回阳，方后随症加减，利止脉不出者加人参益气复脉，体现脉症合参之旨。", ["微"]], "18976": ["治法", "本条为通脉四逆汤方名，原文未出脉象，故脉象要素为空。方名“通脉”提示所主病机为少阴阴寒内盛、阳气衰微，致脉道不通、脉微欲绝，治以回阳通脉。属治法条文，非脉象主病之论。", []], "18977": ["预后", "原文“其脉即出者愈”“利止、脉不出者，去桔梗，加人参二两”，以脉出与不出判断阳气来复与否。脉不出为阳衰未复，故加人参益气；脉出则阳回向愈。全段以脉之出没言预后及方药加减，未直接描述脉形。", []], "18978": ["治法", "“少阴病，脉沈者，急温之”，沉脉主里主寒，少阴病见沉，为阴寒内盛、阳气衰微之里寒证。脉沉提示病已在里，故不急温则阳亡，宜四逆汤回阳救逆。此以沉脉定病位在里、病性属寒，指导急温治法。", ["沉"]], "18979": ["病机", "“脉弦迟者，此胸中实”，弦主饮主痛，迟主寒，弦迟并见为寒饮实邪壅阻胸中，阳气不布故手足寒、饮食入口则吐。因属胸中实，故不可下而当吐；若膈上寒饮干呕则不可吐而当温。脉弦迟在此辨寒实与寒饮之异。", ["弦", "迟"]], "18980": ["病机", "“下利，脉微濇，呕而汗出”，微为阳气衰微，濇为阴血不足、脉道不利。少阴下利日久，阴阳两伤，阳虚不能固摄则汗出，阴亏肠燥则数更衣而反少。脉微濇示阴阳俱虚，故当温其上而灸之，以扶阳固脱。", ["微", "濇"]], "18981": ["其他", "本条仅为“辨厥阴病脉证并治第十二”篇题，无具体脉象与证候内容，故脉象要素为空。篇题统摄厥阴病脉证治法，属篇章分类标识，不构成独立病机分析，归入其他类。", []], "18982": ["预后", "“厥阴中风，脉微浮为欲愈，不浮为未愈”，厥阴病邪由阴出阳，脉见微浮，示阳气来复、邪气外达，故为欲愈之兆；若脉不浮，则邪仍郁于阴分，阳气未复，故未愈。此以脉之浮与不浮判断厥阴中风之预后转归。", ["微", "浮"]], "18983": ["病机", "“后三日脉之而脉数，其热不罢者，此为热气有余，必发痈脓也”，厥利之后脉数而热不退，为阳复太过、热气有余，热毒壅聚营血，腐肉成脓，故必发痈脓。脉数在此示热盛，与厥利相应之期相较，辨阳复适度与太过之病机。", ["数"]], "18984": ["预后", "脉迟为寒，伤寒六七日反与黄芩汤彻其热，是误治。寒证误用苦寒，腹中应冷不能食；今反能食，乃胃气败绝、回光返照之“除中”，必死。脉迟揭示里寒本质，误治后反能食是假象，故断预后不良。", ["迟"]], "18985": ["病机", "脉微而厥，微为阳虚，厥为阴阳气不相顺接。肤冷、躁无暂安时，是藏厥，非蚘厥。藏厥为阴寒内盛、真阳欲脱；蚘厥则静而复时烦、吐蚘，因藏寒蚘上入膈。脉微点明阳气衰微，为辨藏厥与蚘厥之关键。", ["微"]], "18986": ["病机", "脉微而厥，微主阳虚，厥主阴阳不接。藏厥者肤冷、躁无暂安时，为纯阴无阳；蚘厥者静而复时烦、吐蚘，因藏寒蚘扰。脉微揭示阳气衰微，是辨藏厥与蚘厥之眼目，蚘厥用乌梅丸温脏安蚘。", ["微"]], "18987": ["预后", "脉微为阳气衰微，手足厥冷、烦躁是阴盛格阳、虚阳上扰。灸厥阴以通阳，厥不还则阳气不复，故死。脉微在此示真阳欲绝，灸后厥逆不回，预后凶险。", ["微"]], "18988": ["误治", "脉虚复厥，虚为血虚，厥为阳衰。腹濡不结胸，知非实邪。此亡血之厥，不可下，下之则竭阴耗血而死。脉虚揭示血虚本质，误下更伤阴血，故戒。", ["虚"]], "18989": ["治法", "脉促而手足厥逆，促为阳郁不伸，非热盛。阳郁致厥，可灸以通阳。脉促在此示阳气被遏，灸法助阳外达，厥逆可回。", ["促"]], "18990": ["病机", "脉滑而厥，滑主里有热，热郁于里，阳气不达四末故厥。此真热假寒，白虎汤清里热。脉滑是辨热厥之据，与寒厥脉微截然不同。", ["滑"]], "18991": ["治法", "脉细欲绝，细为血虚，欲绝为阳衰。手足厥寒因血虚寒凝、脉道不通。当归四逆汤温经散寒、养血通脉。脉细欲绝点明血虚寒厥之机。", ["细"]], "18992": ["病机", "脉细欲绝，是血虚寒凝、脉道不充之象。手足厥寒因阳气不达四末，细为阴血亏少，欲绝则气血运行几近断绝，故主血虚寒厥。当归四逆汤温经散寒、养血通脉，正对细欲绝之脉，说明此脉主血虚寒凝、经脉失养之病机。", ["细"]], "18993": ["病机", "脉乍紧者，紧主邪实内结，乍紧说明邪结胸中而脉气时紧时缓。手足厥冷因胸中阳郁不达，心下满烦、饥不能食皆邪结胸膈之征。脉乍紧与邪结胸中相应，故用瓜蒂散因势吐之，此脉主实邪结聚胸中之病机。", ["紧"]], "18994": ["预后", "大下后寸脉沉而迟，沉主里、迟主寒，寸部沉迟说明上焦阳气虚陷、寒凝阳郁。手足厥逆、下部脉不至为阳衰不达，喉咽不利、唾脓血为虚火上炎，泄利不止为下焦虚寒，上下寒热错杂，故原文断为“难治”，此脉示误下后阴阳错杂之危候。", ["沉", "迟"]], "18995": ["预后", "寸脉沉而迟，沉为阳气内陷，迟为寒凝，寸部候上焦，沉迟则上焦阳微。大下后手足厥逆、下部脉不至，是阳衰不能温煦四末与下焦；喉咽不利、唾脓血为虚阳上浮，泄利不止为脾肾虚寒。脉证合参，寒热错杂、虚实并见，故曰难治。", ["沉", "迟"]], "18996": ["预后", "下利后脉弱，弱为正气不足而邪气亦衰之象。有微热而渴，是利后津伤、阳气渐复之征，脉弱而不数不紧，说明邪热已退、胃气未复。原文断“今自愈”，正因脉弱反映邪去正虚、无实邪留滞，故主病退向愈之预后。", ["弱"]], "18997": ["预后", "下利脉数，数为阳热，有微热汗出是阳气外达、邪从表解之象，故“今自愈”。设脉复紧，紧主邪实内结，说明利虽减而寒邪未散、病根未除，故“为未解”。此段以脉数转紧判断邪之去留，脉数主阳复，脉紧主邪结未解。", ["数", "紧"]], "18998": ["死脉", "下利手足厥冷而无脉，是阳气衰绝、脉道不通之危候。灸之而手足不温、脉不还，说明阳不复；反微喘者，是虚阳上脱、肺气欲绝，故主死。少阴负趺阳为顺，指趺阳脉胜于少阴，胃气尚存则生机未绝。此段以无脉、脉不还辨阳气存亡。", []], "18999": ["病机", "下利而寸脉反浮数，浮为热盛于上，数为热象，寸候上焦，说明热邪偏聚于上；尺中自涩，涩主血行不畅、阴络受伤。上热下利、尺涩伤阴，热灼血络，故原文断“必清脓血”。此脉主热伤血络、下利便脓血之病机。", ["浮", "数", "涩"]], "19000": ["预后", "下利脉沉弦，沉主里、弦主急，示里气壅滞、下焦气机不畅，故见下重；脉大则邪气盛、病势未衰，故为未止；脉微弱数，微弱为正气虽弱而邪亦衰，数为阳气来复，故为欲自止，虽发热亦不至死。三段以脉判下利之轻重进退。", ["沉", "弦", "大", "微弱数"]], "19001": ["病机", "下利脉沉而迟，沉主里、迟主寒，示里虚寒盛；面少赤、身微热乃虚阳浮越于上，即“其面戴阳”；下利清谷为脾肾阳衰、完谷不化。阳气郁冒，正邪相争，故必郁冒汗出而解，然下虚阳浮，故病人必微厥，此“下虚故也”。", ["沉", "迟"]], "19002": ["预后", "下利脉数而渴，数为有热、渴为津伤，示阳热内盛、津液受灼。若正能胜邪，热从外解，则今自愈；设不差，则热邪深入下焦，灼伤血络，必清脓血，以有热故也。此以脉数口渴辨下利之转归，热化则或愈或便脓血。", ["数"]], "19003": ["预后", "下利后脉绝，乃阴液耗竭、阳气暴脱，血脉不充；手足厥冷为阳衰不能温煦四末。若晬时脉还、手足转温，是阳气来复、生机尚存，故生；脉不还则阳气已绝，故死。此以脉之还与不还、手足温与不温判生死。", []], "19004": ["死脉", "伤寒下利日十余行，正气当虚，脉应微弱；今脉反实，是邪气独盛、正虚不能敌邪，脉证相反。实脉示邪实壅盛，下利更伤正气，正不胜邪，故主死。此以脉反实辨下利之危候，属脉证不符之死证。", ["实"]], "19005": ["治法", "下利清谷为脾肾阳衰、完谷不化；里寒外热、汗出而厥，乃阴寒内盛、虚阳外越，故外见假热而汗出，阳衰不能温煦故厥。此内真寒外假热之证，非通脉四逆汤不能破阴回阳、通达内外，故主之。", []], "19006": ["兼症", "呕而脉弱，弱主正气虚衰；小便复利，示下焦阳虚不能固摄；身有微热为虚阳外浮；见厥则阳衰更甚，不能温煦四末。脉弱、小便利、微热、厥并见，正虚阳浮，故难治，四逆汤主之以回阳救逆。", ["弱"]], "19007": ["其他", "此段为辨霍乱病脉证并治篇题，非具体脉象条文，故无脉象要素可录。霍乱以吐利交作为主，其脉证当结合全篇互参，此仅标篇目，示该篇专论霍乱之脉证并治，属篇章总纲。", []], "19008": ["病机", "脉微为阳气衰微，涩为血少津亏，故知本是霍乱吐利后阴阳两伤。今转属伤寒，四五日至阴经，若入阴必下利；本有呕而复下利，是脾胃阳败、中气不守，故曰不可治。脉微涩正示正气虚竭、邪易内陷之机，与后文便鞕、能食与否的转归判断相呼应。", ["微", "涩"]], "19009": ["治法", "恶寒而脉微，是少阴阳气衰微、不能温煦肌表；复下利至利止，非邪去，乃津血耗竭、无物可下，故曰亡血也。脉微为阳气虚衰之象，与恶寒、下利并见，主阴寒内盛、气血两伤。故用四逆加人参汤，回阳救逆兼益气生津，以救微脉所主之阳亡液脱。", ["微"]], "19010": ["治法", "本条与上条同文，恶寒脉微而复利，利止非病愈，乃下利日久、阴血耗竭之亡血。脉微主阳气衰微，恶寒为少阴寒化外候，下利伤津耗血，故以四逆加人参汤温阳救逆、益气生血。脉微在此提示阳衰为本、液脱为标，单温阳不益气则津血难复。", ["微"]], "19011": ["治法", "既吐且利，小便复利而大汗出，下利清谷，是内外阳气俱虚、阴寒内盛；内寒外热为阴盛格阳之象。脉微欲绝，乃阳气衰微欲脱、鼓动无力之候，与吐利汗出、清谷不化相应。故主四逆汤回阳救逆，以挽欲绝之微脉，救垂危之阳气。", ["微"]], "19012": ["治法", "吐已下断，非病解，乃吐利过度、津液枯竭无物可出；汗出而厥、四肢拘急不解，是阳亡液脱、筋脉失养。脉微欲绝，示阳气衰微欲绝、脉道不充。故用通脉四逆加猪胆汁汤，大剂回阳通脉，佐猪胆汁苦寒反佐，防格拒并益阴液，服后其脉即来。", ["微"]], "19013": ["治法", "本条与上条同文，吐已下断而汗出厥逆、四肢拘急不解，脉微欲绝，是吐利后阳亡液竭、筋脉失濡之危候。脉微欲绝紧扣阳气衰微、不能鼓脉，故主通脉四逆加猪胆汁汤，回阳通脉兼反佐益阴，使欲绝之脉得复，与上证互明。", ["微"]], "19014": ["其他", "本段仅为通脉四逆加猪胆汁汤方药组成，未载脉象，故脉象要素为空。方以四逆汤大剂回阳通脉，加猪胆汁苦寒反佐，针对前条脉微欲绝、阳亡液竭之证，属治法方药内容，非脉诊主病之文，故归其他。", []], "19015": ["其他", "本段为煎服法及服后转归，未识别脉名，故脉象要素为空。文中“其脉即来”是服药后阳气回复、脉道复通之效验，非诊脉主病之象。全段属治法方药与服药观察，故归其他，不涉具体脉象主病。", []], "19016": ["病机", "吐利发汗后脉平，示邪已去而正气暂虚。小烦者，非病脉，乃新虚脾胃不胜谷气，食入难化，郁而微烦。脉平说明无大邪，病机在胃气未复，故主症为小烦，损谷自愈。", ["平"]], "19017": ["其他", "此段为篇题，未出具体脉象与证治，仅标示辨阴阳易、差后劳复病之脉证并治范围。无脉象可析，故列其他，提示后文诸条当从此篇求之。", []], "19018": ["治法", "伤寒差后更发热，脉浮者邪在表，故以汗解；脉沉实者邪在里，故以下解。脉浮主表，沉实主里实，示差后复热当据脉定表里，分别施汗下，非一概小柴胡也。", ["浮", "沉", "实"]], "19019": ["病机", "病人脉已解，示邪气已退，脉象平和。日暮微烦者，因病新差，脾胃气尚弱，强与谷则不能消谷，谷气郁滞而微烦。脉解而症微，故损谷则愈，病机在脾胃未复。", []], "19020": ["其他", "此段为篇题，标辨不可发汗病脉证并治，未出具体脉象。无脉可析，故列其他，提示后文诸条当从不可发汗之脉证求之。", []], "19021": ["病机", "脉濡而弱，弱在关、濡在巅，微在上、涩在下。微则阳气不足，涩则无血。阳微故中风汗出而躁烦，无血故厥而且寒。阳微发汗则躁不得眠，示气血俱虚，不可发汗。", ["濡", "弱", "微", "涩"]], "19022": ["误治", "诸脉得数动微弱者，数动似热而微弱属虚，乃阴阳俱不足之象。虚家不可发汗，汗则津液耗伤，大便难、腹中干、胃燥而烦。形似实热，根本异源，故戒发汗。", ["数", "动", "微", "弱"]], "19023": ["病机", "脉微而弱，弱在关、濡在巅，弦在上、微在下。弦为阳运，微为阴寒，上实下虚，意欲得温。微弦为虚，不可发汗，汗则寒栗不能自还，示阳虚阴寒，发汗更伤其阳。", ["微", "弱", "弦"]], "19024": ["误治", "厥证见脉紧，紧主寒主痛，为寒邪内闭、阳气不达之象。厥本阴阳气不相顺接，若误认表实而发汗，则更伤阳气、耗津液，致声乱、咽嘶、舌萎、声不得前，皆津气两伤、咽喉失养之候。原文以“脉紧”戒发汗，正因紧非表邪，乃里寒收引，汗之则阳气愈虚，变证丛生。", ["紧"]], "19025": ["其他", "此段为篇题“辨可发汗脉证并治第十六”，非具体脉证条文，故无脉象可录。其主旨在于总括可发汗之脉证范围，提示发汗须以脉证相参、表邪确在肌表为前提，与后文具体脉证条文相呼应，属篇章纲领性文字，不涉具体病机分析。", []], "19026": ["病机", "脉浮大为邪在表、正气趋外抗邪之象。病者言但便鞕，似里实，然脉浮知病势仍偏表，便鞕非燥结内实，故不可遽下；设利之则为大逆，伤其里气。原文“鞕为实，汗出而解”指出此实乃表实，脉浮当以汗解，汗出则表和而便自通，示人凭脉辨表里、慎攻下。", ["浮", "大"]], "19027": ["其他", "此段为篇题“辨发汗后病脉证并治第十七”，属篇章标目，无具体脉象与证候可析。其义在总领发汗后诸变证之辨治，提示汗后脉证变化多端，须详辨虚实寒热，与前后具体条文相贯，为纲领性文字，不构成独立病机判断。", []], "19028": ["病机", "胸上诸实、郁郁而痛、不能食、涎唾，为痰实壅塞胸中；下利日十余行而脉反迟，迟非虚寒，乃实邪内阻、脉道不利所致；寸口脉微滑，滑主痰实，微示病位偏上。原文断为“此可吐之”，吐后气机通畅则利自止，说明下利由胸中实邪上壅、气不下行而致，脉迟滑正是邪实内结之征。", ["迟", "滑"]], "19029": ["病机", "手足厥冷而脉乍结，结为脉来缓时一止、止无定数，主邪气阻遏、脉道不利。原文明言“以客气在胸中”，客气即外来邪气客于胸膈，胸阳被阻，不达四末则厥冷，心下满而烦、欲食不能食皆邪结胸中之候。脉乍结正应邪阻气机、脉行不畅，故当因势利导，吐去胸中客邪。", ["结"]], "19030": ["其他", "此段为篇题“辨不可下病脉证并治第二十”，属篇章标目，无具体脉象与证候。其义在总领不可下之脉证，提示下法须严格凭脉辨证，凡脉证不宜攻下者误下则生变，与前后条文相贯，为纲领性文字，不构成独立病机分析。", []], "19031": ["病机", "脉濡弱而微濇，微为阳气不足，濇为无血，阳微则中风汗出而躁烦，血少则厥而且寒，皆气血两虚之候。原文“阳微不可下，下之则心下痞鞕”，指出阳虚者误下更伤中阳，气机痞塞而成痞鞕。濡弱微濇并见，正示阳气衰微、营血亏少，故禁攻下。", ["濡", "弱", "微", "濇"]], "19032": ["误治", "原文论“诸外实者，不可下”，误下则“发微热，亡脉厥”，甚则“当脐握热”。外实之证，邪在表卫，当从汗解；妄下伤里，阳气内陷，故脉亡而厥，脐周握热乃虚阳浮越之象。此段强调下法禁忌，脉象未明，然“亡脉”示阳气暴脱，与厥逆相应。", []], "19033": ["病机", "脉濡而弱，弱在关、濡在巅，复见弦上微下，是“上实下虚”之候。弦为阳运，微为阴寒，阳浮于上而阴弱于下，故“意欲得温”。微弦并见，总属虚象，虚者不可下，下之则伤阳。此段以脉位分上下，明虚实错杂之机。", ["濡", "弱", "弦", "微"]], "19034": ["误治", "脉濡弱而浮数，浮为阳虚自汗恶寒，数为无血而痛、振寒。微弱在关则胸下急、喘汗胁痛，形如疟状。医反下之，虚其里气，故脉数发热、狂走见鬼、心下痞、小便淋沥尿血。此段示濡弱之脉本属虚，误下则变证蜂起。", ["濡", "弱", "浮", "数"]], "19035": ["误治", "脉濡而紧，濡则卫气微，紧则荣中寒，阳微卫中风而发热恶寒，荣紧胃气冷而微呕心烦。医误为热，解肌发汗，致亡阳虚烦躁、心下痞坚、表里俱虚。更以水灌其身，寒气因水发，清谷不容，呕变肠出，手足逆冷。此段详述濡紧脉误汗误水之坏病。", ["濡", "紧"]], "19036": ["预后", "脉浮而大，浮为气实，大为血虚。血虚无阴，孤阳下陷阴部，当小便赤难，今反小便利而大汗出，津液四射，荣竭血尽，干烦不眠，血薄肉消。医复以毒药攻胃，重虚其虚，客阳去有期，必下如污埿而死。此段以浮大脉判气血虚竭之危候。", ["浮", "大"]], "19037": ["误治", "脉数久不止，止则邪结，正气不能复，却结于藏，邪气浮之与皮毛相得。数脉主热，热邪久稽则正气受阻，邪结于表。脉数者不可下，下之则虚其里，必烦而利不止。此段明数脉禁下之理，下之伤正，邪陷生变。", ["数"]], "19038": ["误治", "脉浮大，浮主表、大主邪盛，其病在表，应发汗解肌。医反下之，是逆其病势，引邪内陷，故曰“大逆”。此段以浮大脉定汗法之宜，下之为误，示人凭脉辨治，不可违逆表证之机。", ["浮", "大"]], "19039": ["预后", "伤寒脉阴阳俱紧，恶寒发热，脉欲厥。厥者脉初来大，渐渐小，更来渐渐大，是邪正交争、阴阳气不相顺接之候。甚则翕翕汗出、喉中痛，热多则目赤睛不慧。医复汗、下、熏、熨，变证丛生。小便利者可救，小便难者危殆，以津液存亡判预后。", ["紧", "大"]], "19040": ["病机", "原文于恶水者误下、误汗诸变后指出「脉数实，不大便，六七日后必便血」，数主热盛，实主邪结，热邪内壅阳明，故不大便；热伤血络，日久迫血下行，故必便血。此脉数实正是里热成实之征，与头痛目黄、衄血等热象相应，非虚寒下利可比。", ["数", "实"]], "19041": ["病机", "下利而「脉大者，虚也」，因强下伤正，脉大为虚阳外浮之象；又「设脉浮革，因尔肠鸣」，浮革主血虚寒凝、脉道失充，寒客肠间故肠鸣，属当归四逆汤证。此段以脉大、浮革辨下利后正虚寒凝之病机，非实邪内结。", ["大", "浮", "革"]], "19042": ["其他", "本段仅为「辨可下病脉证并治第二十一」篇题，未载具体脉象与证治文字，故脉象要素为空。篇题提示该篇专论可下之脉证，属篇章归类，不构成独立病机分析，故归入其他。", []], "19043": ["病机", "下利而「三部脉皆平」，脉不见虚衰，说明正气未败；「按之心下鞕」，为实邪结聚心下之征。脉平而心下硬，是邪实而正未大虚，故可急下，宜大承气汤。此脉平非无病，乃与心下鞭合参，辨为里实可下之机。", ["平"]], "19044": ["病机", "下利「脉迟而滑者，内实也」，迟非虚寒，乃实邪阻滞、脉道不利所致；滑主实热内壅。实积在里，故利未欲止，当因势下之，宜大承气汤。此以迟滑合参，辨下利属内实而非虚寒，脉证相应。", ["迟", "滑"]], "19045": ["病机", "寸口「脉浮而大，按之反濇，尺中亦微而濇」，浮大主谷气壅盛于外，按之涩、尺中微涩，为宿食内结、气血运行不畅之征。脉证合参，知有宿食，故当下之，宜大承气汤。涩脉在此主宿食阻滞，非单纯血虚。", ["浮", "大", "涩", "微"]], "19046": ["病机", "下利「脉反滑」，滑主实邪内聚，下利本应脉虚，今反滑，说明里有当去之积，故「当有所去，下之乃愈」，宜大承气汤。此以脉反滑辨下利属实积内停，因势攻下，邪去则利自止。", ["滑"]], "19047": ["病机", "伤寒后「脉沈，沈者，内实也」，沉主病在里，伤寒后脉沉，为邪热内结、里实已成之征，故当下解之，宜大柴胡汤。此以沉脉辨里实，与伤寒后余邪入里、腑气不通相应，属可下之证。", ["沉"]], "19048": ["病机", "脉双弦而迟，弦主饮主痛，迟主寒，双弦则饮邪偏盛，故必心下鞕，乃寒饮结聚于中焦之象。脉大而紧，大为阳脉，紧主寒实，大紧并见是阳中有阴，即热实中夹寒邪，邪实可下，故宜大承气汤攻其里实。此段以脉测证，明寒饮与实热夹阴之不同病机。", ["弦", "迟", "大", "紧"]], "19049": ["其他", "此段仅为篇题「辨发汗吐下后脉证并治第二十二」，标明所论为汗吐下后变证之脉证治法，原文未出具体脉象，故无从论其脉理。其主旨在于提示误治后脉证变化之辨治范围，属篇章标目，非脉象主病之文，故脉象要素为空。", []], "19050": ["病机", "此段泛论人身禀气厚薄强弱不同，六气七情交侵而诸疾生，千状万证要之不外虚实两端，故引经「虚则补，实则泻」，以虚实为诊病标的、补泻为施治大要。文中未出具体脉象，乃总论病机与治法大纲，并批评张戴人偏泻、薛立斋偏补各有所偏之弊，非专论某脉所主。", []], "19051": ["病机", "脉状如弓弦而有力，弦为肝木之脉，劲直有力正是风木亢盛之象。原文列掉摇眩运、纡曲劲直、手足掣颤、筋急挛搐、角弓反张等症，皆风木善行数变之为病，属厥阴肝用。其因在肺金为心火所制不能胜木，故肝木自甚。弦而有力，正合风动筋急之病机。", ["弦"]], "19052": ["病机", "脉沉涩，沉主里主阴，涩主血少气滞、经脉不利。痹由风湿寒三气杂合而成，寒胜为痛痹，阴受之则痛，湿胜为著痹，著而不去、肌肉削而著骨。沉涩正示邪入阴分、气血痹阻不通之机，与麻木不仁、著而不去诸症相应，说明痹从外入、留着筋骨血脉之病机。", ["沉", "涩"]], "19053": ["误治", "此段论今人见痹证遽作脚气治之之误，滥用乌附乳没等燥热攻之，又中脘灸、脐下烧、三里火、蒸熨汤炕，致便旋涩滞、前后俱闭、虚燥转甚、肌肤日削、食饮不入。原文未出脉象，主旨在于斥治痹不分经络脏腑表里、误作寒湿脚气而致坏证，故归误治，非脉象主病之论。", []], "19054": ["病机", "脉浮而大，浮主在上在表，大主热盛，正合痿由肾水不能胜心火、心火上烁肺金、六叶皆焦之机。诸痿喘呕皆属于上，属肺金部分，客热而成，故脉见浮大。浮大之脉示热在上焦、肺叶焦而皮毛虚弱急薄，与两足痿弱不能行用、躄而足不能伸之痿躄相应。", ["浮", "大"]], "19055": ["误治", "两手脉俱滑之而有力，滑主痰热内盛，有力为实，正合痿以肺热为本、叶焦而成之机，非寒证可比。原文斥见脚膝痿弱便作寒湿脚气、骤用乌附乳没及燔针艾火汤煮袋蒸，致痿弱转加而死，乃用药之误。滑而有力之脉证明痿属热实，反用燥热温攻则杀人，故归误治。", ["滑"]], "19056": ["病机", "原文以“阳明虚则宗脉纵，宗脉纵则大脉不伸，两足痿弱”立论，脉大而纵弛不伸，正是阳明胃气虚衰、宗筋失润之象。胃为水谷之海，胃气不固则精不化、髓不充，故足不能履。此脉不主实热，而主虚痿，与两足痿弱、宗筋弛纵相应。", ["大"]], "19057": ["病机", "原文谓厥由“邪气乱，阳气逆，是少阴肾脉不至也”，肾气微少、精血奔逸，宗气反结心下，阳气退下，五络俱绝则“身脉皆动，而形体皆无所知，其状如尸”。脉不至是肾气败绝、阳气逆乱之征，非一般脉象可名，故列痰厥、风厥、酒厥、气厥诸候，皆气逆所为。", []], "19058": ["病机", "原文载寒厥、热厥夫妇二人“脉皆浮大而无力”，浮为阳气外越，大为虚阳浮张，无力则中气不足。此非外感实邪，乃“得之贪饮食，纵嗜欲”内伤所致，阳失所守而浮越于外，故手足寒热之厥并见。浮大无力正提示虚阳外浮、内真虚寒之病机。", ["浮", "大"]], "19059": ["误治", "原文批评世医用升麻、五积等辛温解利伤寒温疫，致发狂谵语、衄血泄血、喘满昏瞀，谓“皆由辛温之剂，解之不愈，而热增剧”。虽段中仅言“脉有浮沉”，实强调解利当先推天地寒暑、人之虚实，辨脉浮沉以定辛凉辛温，误用辛温则助热伤络，故归误治。", ["浮", "沉"]], "19060": ["治法", "原文列伤寒六禁，其三曰“当汗之时，宜详解脉之迟数，用辛凉之剂，禁妄用热药”。脉迟为寒、脉数为热，解表须据迟数辨寒热而选辛凉或辛温，妄投热药则助邪。此段以脉之迟数定治法宜忌，属治法范畴，迟数在此为辨寒热用药之依据。", ["迟", "数"]], "19061": ["病机", "原文论小儿疮疱、丹熛、瘾疹“皆少阳相火客气胜也”，引《内经》“诸痛痒疮疡，皆属心火”，明其非寒。脉息浮大而有力，浮主表、大主热盛，有力为实火，正合少阳相火、心火炽盛外发肌肤之机，与发热恶寒、头项痛、斑疹先从胁下而出诸症相应。", ["浮", "大"]], "19062": ["妇人", "原文辨《圣惠方》赤白带下之论，谓“劳神过度，损动经血，致令身虚，受于风冷，风冷入于脬络”，又引巢氏任脉为病、女子带下之说，冲任起于脬内，阴阳过度则伤脬络，风邪乘虚而入。全段未出脉名，主论妇人带下之因，故归妇人，病机为虚损兼风冷入脬络。", []], "19063": ["病机", "原文论治病当先识经络，十二经与奇经八脉共二十道周流，惟带脉环身一周、无上下之源，“络脬而过，如束带之于身”，引《难经》“带之为病，溶溶如坐水中”，冲任为经脉之海。全段未及脉象，主述经络循行与带脉、冲任病机，故归病机。", []], "19064": ["病机", "原文未出脉名，论带下白物由“遗热于带脉之间”而“血积多日不流，火从金化”所致。热郁血分，久则从肺金之化而为白，故“白物滑溢，随溲而下，绵绵不绝”。其痛者因“壅碍”而成，非本经自病，乃他经“冤抑”所致。此段重在阐发赤白带下及赤白痢的病机，以“新旧”分赤白，不可曲分寒热。", []], "19065": ["预后", "原文述“思慕色欲，内生后蚀”，渐至“形削羸瘦脉大者，必死而不救”。脉大为邪盛而正气已衰，形瘦脉大，脉证相反，故主死。此段先论筋痿白物之由，继以脉大断其危候，并指出赤白痢与带下皆可“同治湿法”，先导水泻讫，次淡剂降火益肾。", ["大"]], "19066": ["兼症", "妇人带下连绵三载，两手脉“俱滑大而有力，得六、七至”，伴上热口干眩运、时呕醋水。滑大有力且数，为实热痰浊壅盛之象，故断“实有寒痰在胸中”，以瓜蒂散吐冷痰醋水，次养胃气，再导水泻下，渗利水道而愈。此脉症相应，示痰热内实之带下。", ["滑", "大"]], "19067": ["误治", "原文未出脉名，强调“不察病人脉息，不究病人经脉，妄断寒热，信用群方暴热之药”必致失手。批评巢氏“赤热白寒”之说与《难》《素》相违，指出赤白带下、白液白物、蛊病肾消“皆不能死人”，惟肠澼便血“血温身热者死”。此段主旨在于戒医者凭脉辨证、不可偏执寒热而妄投燥热。", []], "19068": ["主病", "原文论霍乱由“温凉不调，阴阳清浊，二气相干”，寒气客于脾胃，致吐泻挥霍撩乱。末言“霍乱者，脉必代”。代脉主脏气衰微、脉气不续，吐泻交作，津气暴伤，脉道不能相继，故见代。此段辨巢氏霍乱之说，以脉代点明其病机在脾胃虚逆、清浊相干。", ["代"]], "19069": ["病机", "原文未出脉名，论目之五轮分属五脏，而“目不因火则不病”。气轮赤为火乘肺，肉轮赤肿为火乘脾，黑水神光被翳为火乘肝肾，赤脉贯目为火自甚。总以“热胜则肿”括之，治火一句可了。此段以五轮配五脏阐发目病火郁之机，非论脉象。", []], "19070": ["治法", "原文未出脉名，辨“热汤沃眼”之谬，谓火方乘目更以热汤沃之是“两热相搏，犹投贼以刃”，主张凉水沃之。又论偏头风为“少阳相火”，久则目束小；大肠闭涩目昏，久病滑泄目明。末言“宜出血而大下之”，示目赤肿翳以泻火为治。此段主在治法与误治之辨。", []], "19071": ["误治", "原文未出脉名，戒服药不可不慎。伤寒、温疫、时气、中暑、风温、风疟与中酒伤食初起相类，医者“不察其脉，不言其始”，径用备急丹等巴豆大毒之剂，走泄五七行至十余行，致“津液枯涸，肠胃转燥，发黄瘀热，目赤口干，恍惚潮热，昏愦惑狂”，如此误死。此段专论不辨脉而妄下之害。", []], "19072": ["病机", "原文未提脉象，而论妇人产后寒热腹痛等症，医者不察败血恶物，误作虚寒用温热补剂。张氏以孕物之理喻阴阳和合，指出偏阴偏阳则无孕，产后之疾非尽虚寒，当辨败血为患，不可概用温补。", []], "19073": ["预后", "妇人风痫日久，昏痴健忘，食憨葱苗（藜芦苗）吐涎后“百脉皆和”，示邪去正安、脉转和平，为病愈之兆。脉和反映吐法后气机调畅，故预后良好。", ["和"]], "19074": ["误治", "病头项强类伤寒，误以辛热发汗，致汗出不解、发黄血泄，下之更甚，“其脉犹搏击”，示邪热炽盛、正气尚与邪争，脉象搏击有力，为误治后邪势未衰之征。", ["搏击"]], "19075": ["治法", "论攻邪之法，强调邪气加身当速攻，不可妄补。惟“脉脱、下虚、无邪、无积之人”方可议补。脉脱示正气虚脱，为可补之凭；其余有邪积者补之则邪横骛，故以脉脱界定补法适应证。", ["脱"]], "19076": ["病机", "胸上诸实郁痛、涎唾、下痢，脉沉迟而寸口微滑，迟滑为内实，微滑为上实，乍结为客气在胸中，皆邪气在上之征，故可吐之。脉象反映实邪壅遏上焦，气机不畅。", ["沉", "迟", "微", "滑"]], "19077": ["病机", "飧泄完谷下出，腹鸣泄注，小便涩滞，前医作脾胃虚寒温补无效。诊得两手脉息俱浮大而长，身表微热，示风邪外束、阳气怫郁，非虚寒，故用桂枝麻黄汤发汗而愈。", ["浮", "大", "长"]], "19078": ["病机", "狂人“阴不胜其阳，则脉流薄疾”，阳并乃狂。脉流薄疾指脉行急迫疾速，为阳热亢盛、阴不制阳之象，故登高而歌、弃衣而走，以承气下之、吐法涌之而平。", ["疾"]], "19079": ["病机", "酒病人头痛身热恶寒类伤寒，两手脉俱洪大，三两日不圊，洪大为阳明热盛、酒毒蕴结之象，故用防风通圣散加姜葱豉探吐取汗，火郁发之而愈。", ["洪", "大"]], "19080": ["病机", "两手皆沉滑有力，沉主里、滑主痰湿食积，说明风寒湿邪久痹经络，郁而化实，非纯虚寒。前医误用乌附姜桂燥热及燔针著灸，反助邪气，故三年不愈。沉滑有力正是里有实邪、水湿壅滞之征，故先以导水丸、通经散泻下，痛减半，继以赤茯苓汤等渗湿通经，脉证相应。", ["沉", "滑"]], "19081": ["治法", "两手脉迟而滑者，内实也，宜下之。迟非虚寒，乃宿食壅滞、气机不利；滑为实邪内结。故以脉迟而滑断为内实可下，下后三部脉平。又言心下按之硬满、腹中满痛不止者，脉沉实，皆里壅为实，宜再下。此段以脉辨可下之证，脉实为凭，不以男女久泄久吐为拘。", ["迟", "滑", "沉", "实"]], "19082": ["误治", "伤寒脉浮者不可下，浮为邪在表，下之则引邪入里，伐伤正气。此段列举诸不可下之证：洞泄寒中、表里俱虚、五痞心证、厥而唇青手足冷属寒者、小儿慢惊目直视鱼口出气者、十二经败甚者，皆宜调养温和。以脉别之，浮则在表，寒者禁下，下则误人。唯大积大聚大秘大涸大坚，下药乃补药。", ["浮"]], "19083": ["病机", "赵显之洞泄寒中，两手脉沉而软，沉主里、软为虚，故用灸水分及桂苓甘露散等温补而愈，示虚者不可妄下。赵进道腰痛岁余，两手脉沉实有力，沉实为里实，故以通经散下之，继以杜仲猪腰子补之。同是沉脉，一软一实，虚实判然，补泻异施，正合损有余乃补不足之旨。", ["沉", "软", "实"]], "19084": ["病机", "两手脉急数如弦之张，甚力而实，急数主风火，弦实主邪盛，故断为风火交胜。其人齿壮气充，与长吏气虚风入者不同，故不用灸而用承气汤泻下四五十行，继以苦剂解毒、升降水火。同是口眼㖞斜，一虚一实，脉急数弦实为实火之凭，陷下则灸之，此则宜下。", ["急", "数", "弦", "实"]], "19085": ["病机", "诸疝皆归肝经，脉滑甚、脉大急、脉急者曰疝瘕，滑主湿痰壅聚，大急主邪气搏结，沉主在里。疝病位在足厥阴肝经环阴器入小腹之处，与冲任督相附，膀胱小肠虽司水道，受疝之处乃肝之部分。脉滑大急沉，正示肝经气血壅滞、寒湿痰结之病机，故疝瘕多责之肝。", ["滑", "大", "急", "沉"]], "19086": ["预后", "五实者脉盛，五虚者脉细。脉细为心，心主血脉，脉细乃心血不足、五脏俱虚之征，与皮寒、气少、泄利前后、饮食不入并见，为五虚之证。五脏皆虚为不及，故《内经》言五虚亦死，非谓必死，谓不救则死，救之得其宜则可生。脉细在此为虚证之凭，与脉盛为实相对。", ["细"]], "19087": ["病机", "此段论咽喉会厌舌为气食出入门户，其病一言可了，曰火。引《内经》一阴一阳结谓之喉痹，王注一阴为手少阴君火、一阳为手少阳相火，二火皆主脉并络于喉，气热则内结，结甚则肿胀。原文未出脉象，故脉象要素为空，主旨在于阐明喉痹火结之病机。", []], "19088": ["病机", "原文未及脉象，专论噎食病机。以“三阳结”为纲，谓小肠热结则血脉燥，大肠热结则后不圊，膀胱热结则津液涸，三阳既结则前后闭塞，下既不通必反上行，故噎食不下、纵下复出。此以结热立论，非脉象可候，故脉象要素为空。", []], "19089": ["病机", "原文未出脉象，辨留饮所得之源。先列痰饮、悬饮、支饮、溢饮及五饮之名，谓皆观病形而定名；继言饮之所得有五：愤郁、困乏、思虑、痛饮、热时伤冷。虽饮证多端，病机不出此五途，故脉象要素为空。", []], "19090": ["病机", "原文无脉象，详析留饮五因之病机。愤郁则肝气乘脾，脾气不化；久虑则饮气不行；久思则脾结；劳役困饮则脾胃力衰，不能布散于脉；饮酒过多则脬经不及渗泄；暑渴乘快饮冷逸而不动。皆致水饮留滞，故脉象要素为空。", []], "19091": ["主病", "左手脉三部皆微而小，右手脉三部皆滑而大。原文自释“微小为寒，滑大为燥”，故以瓜蒂散涌寒痰，导水、禹功去肠胃燥垢。此案脉象左右异候，寒燥并见，主饮积日久、寒痰与燥垢互结之病，非单纯水饮可比。", ["微", "小", "滑", "大"]], "19092": ["病机", "原文未出脉象，专论嗽病归肺。引《素问》《灵枢》谓肺病喘咳逆、肺胀满膨膨而喘咳，他经不言；又言皮毛为肺之合，寒邪从合而入，寒饮食入胃从脾脉上至于肺则肺寒，内外合邪客之则为肺咳。此以寒邪合肺立论，故脉象要素为空。", []], "19093": ["病机", "原文无脉象，推衍情志所伤之病。怒则呕血、飧泄、煎厥、薄厥、阳厥、胸满胁痛等；喜则笑不休、毛发焦、阳气不收甚则狂；悲则阴缩、筋挛、肌痹、脉痿、数溲血、血崩等；恐则破䐃脱肉、骨酸痿厥、暴下绿水、阴痿等。皆情志动气之病机，故脉象要素为空。", []], "19094": ["治法", "原文以“脉舒和故也”点出治效之验。所举巫跃、针下杂舞、击拍门窗、假醉激怒、酸枣仁丸、白虎汤、无忧散、瓜蒂散涌、刺痏出血等，皆因情志、暑、寒、痹等施治，而收效之征在脉舒和。脉和则气机调畅，故列治法，脉象取“和”。", ["和"]], "19095": ["病机", "原文未出脉象，论消渴之渴有三：甘之渴、石之渴、火燥之渴。肥甘令人内热中满，气上溢转为消渴；咸入胃走中焦注肺，血与咸相得凝干而善渴；石药气悍滋热伤脾；又引司天之气言嗌干引饮、炎暑民病渴、水行凌火火气郁等。皆以病因病机立论，故脉象要素为空。", []], "19096": ["病机", "原文以“心脉滑为善渴”说明滑脉主阳气胜，阳热耗津故渴；“心脉微小为消瘅”则微细之脉示五脏柔弱、气血不足，柔弱者易伤，刚强者多怒，怒则气逆，血气逆留，转而为热，热则消肌肤，故为消瘅。脉滑与微小对举，揭示消瘅本虚标热、气逆化火的病机。", ["滑", "微", "小"]], "19097": ["主病", "原文诊蛔虫云“腹中痛，其脉法当沉弱，今脉反洪大，是蛔虫也”。沉弱为里虚常脉，反见洪大，说明虫动气逆、湿热内扰，脉不应常而反张，故以脉之反常辨蛔虫腹痛。此以脉症相逆为辨，突出洪大主虫扰气逆之病机。", ["沉", "弱", "洪", "大"]], "19098": ["治法", "本段论补法，提出“有余者损之，不足者补之”，阳有余则损阳补阴，阴有余则损阴补阳，热用芒硝、大黄，寒用干姜、附子，皆非单纯温补。原文批评执“温补”二字概用热药，强调温补特为形精不足而设，非为病不病而设，体现辨证论治、以平为期的思想。", []], "19099": ["病机", "原文述暑及风温为病，脉“两手多沉”，自汗出、身重、多睡必鼾。沉脉在此非独主里，乃暑湿郁遏、阳气不伸之象；风伤荣、温伤卫，气血受困，故脉沉而症见身重多睡。若表未罢不可下，下则胃中虚空，示沉脉须结合表里辨治。", ["沉"]], "19100": ["治法", "原文论四时不正之气初感太阳，先治外后治内；若不大便、喘满谵语实热，“两手脉沉”，可用承气汤下之。沉脉主里实，故可下；又言“脉浮滑者可用”吐法，浮滑主邪在上焦。同篇脉沉可吐、寸脉沉兮胸有痰，示沉脉须参部位与症，辨其可下可吐。", ["沉", "浮", "滑"]], "19101": ["治法", "本段论痔漏肿痛，引《内经》“因而大饱，筋脉横解，肠澼为痔”，说明饱食伤脾、筋脉松弛、湿热下注而成痔，痔久不愈变漏。治以同治湿法，先用导水丸、禹功散泻湿，次服枳壳丸等通利肠胃，并忌房室、鸡鱼酒醋，体现湿滞下焦、以通利为治的病机。", []], "19102": ["病机", "原文述冷食不消、宿酒不散，症见身热恶寒、战栗、头项痛、腰脊强，似伤寒而“两手脉沉”。沉脉说明冷食宿酒内伤脾胃，阳气被遏，不能外达，故外症虽似表而脉不浮。治用导饮丸推尽宿滞，则头痛等症自愈，示沉脉主内伤积滞。", ["沉"]], "19103": ["病机", "原文论骨蒸热劳，症见皮肤枯干、痰唾稠黏、四肢疼痛、面赤唇干烦躁、虚汗黄瘦，脉空。空脉主血气虚少，男子精不足、女子血不流，阴虚火旺，耗灼营血，故脉空而见虚劳诸症。亡血者不宜吐，吐则神昏，强调血者人之神，示空脉主精血亏虚。", ["空"]], "19104": ["主病", "原文引叔和“寸脉急而头痛是也”，寸脉主上焦，脉急为邪气上扰、经气不利之象。三阳受病，胸膈宿痰上攻，清阳不展，故头痛不止。脉急与头痛相应，提示病位在上、病性属实，痰浊风热壅遏经脉。", ["急"]], "19105": ["病机", "原文未出脉象，专论便痈（血疝）病机。指出足厥阴肝经为气血行流之道，冲任督脉亦属肝经旁络，瘀血不散结于大便处而成痈。治以峻泻瘀血、和血通经，强调“不知和血通经之道”则有不愈者，脉象虽未言，病机在肝经瘀滞。", []], "19106": ["预后", "妇人月事不来，胞脉闭阻，气上迫肺，心气不得下通。若误服峻热之药，则变生肺痿、骨蒸潮热、咳脓呕血等症，渐至形瘦脉大。脉大为邪热炽盛、阴液耗伤之象，形瘦脉大提示正虚邪盛，故曰“虽遇良医，亦成不救”，属预后不良之候。", ["大"]], "19107": ["妇人", "原文未出脉象，论述妇人癃闭、遗溺、嗌干等证，虽服药针灸亦不能孕，因冲、任、督三脉之病故不治。三脉同起胞中，与生殖密切相关，病则经气不利、水道失调，故难成孕。此段重在妇人病机与不孕之由。", []], "19108": ["妇人", "原文未出脉象，论妇人无乳。天生无乳者不治；因啼哭悲怒郁结，气溢闭塞，乳脉不行者，可用精猪肉清汤调益元散，更用木梳梳乳以通乳络。病机在气郁乳脉闭塞，非脉象所主，故列妇人门。", []], "19109": ["病机", "原文未出脉象，论乳痈（吹乳）病机。风热结薄于乳房之间，血脉凝注，久而不散，溃腐为脓。吹者风也，风热外袭，与气血相搏，壅结乳络，故发为痈痛。此段重在阐明乳痈由风热致病的机理。", []], "19110": ["妇人", "原文未出脉象，论妇人妊娠九月而喑哑不言，因脬之络脉不相接，故不能言。《经》曰“无治也”，但可煎玉烛散放冷入蜜呷之，使心火下降、肺金自清而能作声。病机在胞络阻绝、心火刑肺，属妇人妊娠特发之证。", []], "19111": ["小儿", "小儿乳痈癖（奶脾），因乳食伤多、积热熏蒸所致。生于肌表者，两手脉浮而数，浮主表、数主热，为风热客于肌腠之象，症见赤眼、丹瘤、疮疖等；伤于肠胃者，两手脉沉而紧，沉主里、紧主积，为乳食壅滞肠胃之象，症见吐泻、腹胀、肌瘦面黄、肚大筋青。浮数沉紧，表里寒热之辨昭然。", ["浮", "数", "沉", "紧"]], "19112": ["病机", "两手脉皆浮数，浮为风邪在表，数为热。原文谓“春伤于风，夏必飧泄”，风邪入中脾胃，木克土，肠中有风故雷鸣飧泄。脉浮数正是风热在表之征，故戴人断为“风在表也，可汗之”，以汗法使风随汗出。", ["浮", "数"]], "19113": ["病机", "脉洪大，为阳明气分热盛之象。原文谓“面肿者，风，此风乘阳明经也。阳明气血俱多”，风热乘阳明，气血壅盛，故脉洪大而头项遍肿。洪大之脉应阳明多气多血，风肿宜汗，故用通圣散微汗，继以鼻衄泄热而肿消。", ["洪", "大"]], "19114": ["病机", "脉浮而大，浮主风，大主水湿壅盛。原文直断“此风水肿也”，产后忧恚气滞，风与水搏，泛溢肌肤，故浑身肿绕、阴器皆肿。浮大之脉应风水肿病，故先发汗以散风，继以舟车丸、浚川散峻下逐水，乃《内经》治郁之法。", ["浮", "大"]], "19115": ["病机", "两手脉皆沉伏而有力，沉伏主里，有力为实，故断“内有积也，此是肥气”。原文述左胁下肥气、肠中作痛、形如复杯，乃疟久积成癥。沉伏有力之脉，正应积块内结、气血壅滞，故用神祐丸、常山散吐下攻积，疟乃悉除。", ["沉", "伏"]], "19116": ["病机", "两手脉皆洪大如𫄠绳，洪大为阳明火盛之脉。原文谓“徭役烦扰，便属火化。火乘阳明经，故发狂”，又引《经》言阳明病登高而歌、弃衣而走。火乘阳明，气血燔灼，故脉洪大如绳，主胃火发狂之病机。", ["洪", "大"]], "19117": ["病机", "脉初洪数有力，洪数为火热内盛之象。原文述腹胀乳痛、壮热面赤、寒热往来、嗌干呕逆、胸胁痛，皆上焦火郁之症；虽兼滑泄，脉仍洪数有力，说明火邪未衰。故用益元散降火解表，使汗出热退，诸症悉减。", ["洪", "数"]], "19118": ["病机", "原文未载具体脉象，仅言“戴人诊其脉曰：此痰隔也”，以脉断为痰隔。症见咽中如物塞、食不下、中满，乃痰涎壅塞膈上，格拒饮食。引《内经》“三阳结为隔”，故先用通经散越之，再以舟车丸下之，吐下痰积而食进。", []], "19119": ["病机", "两手脉弦而紧，弦主肝，紧主痛。原文谓“心火甚而乘肺，肺不受其屈，故哭”，心火烁肺，气郁不伸，故脉弦紧。小儿悲哭弥日不休，正合弦紧为痛为郁之象。浴以温汤发汗，汗出肺热散，啼止，继服凉膈散泻膈热。", ["弦", "紧"]], "19120": ["病机", "脉沉细者，病在里也。沉为在里，细为积聚，酒毒蕴结，气血壅滞，故吐血、身黄如橘、昏愦如厥。戴人断为中有积聚，以舟车丸、浚川散大下，积去则神清。此脉沉细非虚，乃实邪内结之征，与症候相应。", ["沉", "细"]], "19121": ["病机", "尺寸皆潮于关，关脉独大，戴人曰痈象也。关候中焦，独大者，邪聚于里，气血壅结，故右胁稍高，按之避痛。此肺部有痈，非肺痈，以药托里待破。脉大主邪盛，与寒热、胁痛相应。", ["大"]], "19122": ["病机", "年高涌泄，目脉易乱，身体内有炎火，外有太阳，故出门见日而仆，不知人。脉乱非死候，乃气血暂乱，火扰神明。戴人以凉水蜜雪投之，待之以静，静属水，自然无事。此段言脉乱之由，非脉象本身。", []], "19123": ["病机", "阴虚阳搏为之崩，阴脉不足，阳脉有余，数则内崩，血乃下流。血得热而流散，非寒也。悲哭伤肺，心系恐而血不禁。脉数主热，热迫血妄行，故血崩一载。以黄连解毒汤泻火，血止而安。", ["数"]], "19124": ["病机", "身冷脉微，似寒，然两手脉皆如𫄠绳有力，一息六、七至。脉诀曰：六数七极热生多。此真热假寒，热郁于内，格阴于外，故身冷、重衣、泄注。以冷水淋之，大战汗出，热除而愈。脉数为热之确征。", ["数"]], "19125": ["病机", "两手脉皆沉迟，沉者在里也，在里者泄之。腰股沉痛，行步不便，误作寒湿虚损，温补无效。沉迟主里积，水湿壅滞，故以舟车丸、浚川散去积水二十余行，病愈。脉沉迟非寒，乃积阻气机。", ["沉", "迟"]], "19126": ["病机", "两手寸脉皆沉而伏，知胸中有痰实也。阳火盛于上，阴火盛于下，故夜梦鬼神、见神堂阴府。沉伏主痰实内闭，胸阳不布。三涌三泄三汗，痰去则梦止，一月有孕。脉沉伏为实邪壅塞之征。", ["沉", "伏"]], "19127": ["预后", "泄泻数年，脉沉而有力。脉诀云：下利，脉微小者生，洪浮大者无瘥。今脉沉有力，非微小，然沉主里实，有力为积滞，故可涌泄。以瓜蒂散吐寒痰，无忧散泄积，调理而起。此段引脉诀辨预后，沉有力示实可攻。", ["沉"]], "19128": ["预后", "原文载产后泄一年余，四肢瘦乏，诸医断为死证，而戴人诊得“两手脉皆微小”，断为“痢病之生脉”。脉微小虽似虚衰，但泄痢日久，脉当沉细而弱，此微小之脉尚存胃气，非无根之散脉，故为可生之候。戴人据此用舟车丸、无忧散峻下，更以胃风汤调补而愈，说明脉微小在此非死脉，而是痢病正虚邪恋、尚可攻补兼施之生机。", ["微", "小"]], "19129": ["病机", "原文述年六十余，从左手指麻发展至半身皆麻，大便二三日不通，他医皆作风治不效。戴人诊“左手三部脉皆伏，比右手小三倍”，断为“枯涩痹也”，并谓“不可纯归之风，亦有火燥相兼”。脉伏主气血壅滞、经络不通，火燥灼津则血枯不荣，故见偏麻、便结。此脉伏非外风，乃内火燥结、气血痹阻之征，故以涌泄汗法通其壅滞。", ["伏"]], "19130": ["病机", "原文载大便燥涩，结实如针石，三五日一行，目星鼻血，肛门广肠痛，痛极发昏，误用巴豆、芫花、甘遂等温下反剧。戴人诊“两手脉息，俱滑实有力”，断为燥结实证。脉滑实有力主邪热内结、腑气不通，燥屎内踞故脉实，热灼津伤故脉滑。此非虚燥，乃实热燥结，故以大承气汤峻下，继以润燥之剂收功。", ["滑", "实"]], "19131": ["兼症", "原文载妇人大便燥结，小便淋涩，半生不娠，屡孕屡坠。戴人诊“两手脉俱滑大”，虽滑大主实热燥结，但“以其且妊，不敢陡攻”，遂以食疗润导，半载居然生子。脉滑大在此既示燥结内盛，又见于妊娠，故不可纯作实治。戴人变通常禁，以食养代药攻，使燥病愈而胎得安，说明滑大之脉须结合妊娠兼症审辨。", ["滑", "大"]], "19132": ["病机", "原文载妇人偏头痛五七年，大便燥结如弹丸，两目赤色昏涩，连年针灸反致目将失明。戴人诊“两手脉，急数而有力”，断为“风热之甚也”。脉急数有力主火邪亢盛，风热上攻则头痛目赤，燥金胜则大便结硬。戴人谓“燥金胜，乘肝则肝气郁”，气血壅滞上冲，故脉急数。此脉示三焦相火与阳明燥金合邪，非单纯头风。", ["急", "数"]], "19133": ["病机", "原文载男子腰尻脊胯皆痛，昼静夜躁，大痛往来，肉瘦皮枯，众皆以为鬼神阴谴。戴人诊“两手脉，皆沉滞坚劲，力如张𫄠”，断为邪实内结。脉沉滞主病在里，坚劲如张弦主痛、主寒、主气结血瘀。痛久入络，气血凝滞，故脉沉滞坚劲。此脉非鬼神所致，乃瘀血寒凝、经络不通之实痛，故戴人攻其瘀滞而痛减。", ["沉", "滞", "坚", "劲"]], "19134": ["病机", "原文载僧病疝，冷气上贯齿、下贯肾，紧若绳挽两睪，时肿而冷。戴人诊“两手脉细而弱”，断为“秋脉也”，谓“金气在上，下伐肝木，木畏金抑而不伸”。脉细弱主气血不足、肝木受抑，非真寒也。肝气不能下荣睪丸故寒，木受金制传胃故上贯齿。此脉细弱示金胜木郁、气机不伸，故用涌泄达木，使气入睪中而愈。", ["细", "弱"]], "19135": ["病机", "原文载妇人心下脐上结硬如斗，按之如石，人皆作病胎。戴人诊“两手寸脉皆沉”，断为“寒痰”。寸脉主上焦，沉主里、主水饮停聚。寒痰结于心下，阻遏气机，故寸脉沉而不起。此沉脉非虚寒，乃痰实内结之征，故以瓜蒂散涌吐痰涎，吐后结块消半，继以调中而平。脉沉在此示痰实内踞，可吐可下。", ["沉"]], "19136": ["病机", "两手寸脉皆滑，滑主痰饮内停。患者泻利不止、腹鸣如雷、不敢冷坐，诸医误作寒证温补，戴人断为水饮内蓄，非真寒。水气下注则泻利，饮邪上泛则脉滑。以茶调散涌吐寒水、无忧散泻积，通因通用，水去则泻止。脉滑为辨证眼目，说明病本在水饮而非虚寒。", ["滑"]], "19137": ["病机", "原文引《内经》「忧则气结，喜则百脉舒和」，以喜胜悲治忧结心痛。患者大悲哭后心痛成块，乃忧思气结所致。戴人学巫狂言令其大笑，气机舒畅，结块自散。脉舒和指喜则气机条达、百脉和畅，非病脉，说明情志致病可因情志相胜而愈，气结得舒则脉和。", ["舒和"]], "19138": ["病机", "两手脉俱缓，缓主脾病。患者伤思虑过甚，二年不寐，思则气结伤脾，脾主思，故脉缓。戴人以怒激之，怒则气上汗出，思结得解，是夜困眠，食进脉平。脉缓在此示脾受思虑所伤、气机壅滞，非平人从容之缓，说明情志伤脾之病机。", ["缓"]], "19139": ["小儿", "小儿寐而不寤，诸医作睡惊治。戴人诊两手脉皆平和，并指出「若惊风之脉，当洪大而强，今则平和，非惊风也」。脉平和说明无惊风实邪，乃乳母饮酒，酒气入乳，乳儿亦醉。以甘草、葛花等解酒而醒。脉平和为鉴别诊断关键，排除惊风，提示病因在乳母。", ["平和"]], "19140": ["妇人", "孕妇临产，稳媪暴力拽扳致胎死腹中，妇经脉断闭，腹如刀剜、大渴、小溲闭绝，昏愦欲死。原文未载脉象，主病在瘀血内阻、气机闭绝。戴人先以冰雪水恣饮解渴，次以舟车丸、通经散下瘀，瘀去则食进，调以甘露散等获安。说明暴力伤胎致瘀闭之危候，当以通下瘀血为治。", []], "19141": ["预后", "女子嗜食紫樱十余年，潮热如劳，两手脉皆洪大而有力。洪大有力主阳热亢盛，热毒内蕴，戴人断为「阳盛阴脱之证」，预言他日必发恶疮肿毒、热上攻目。后果患背疽如盘，目昏无子。脉洪大有力说明阳热炽盛、阴液受灼，为热毒发痈之预兆，示阳盛阴竭之病机与预后。", ["洪", "大", "有力"]], "19142": ["病机", "患者身弱无力、面苍黄、左胁下如臂状痛无时，诊胆脉小。小脉主虚，胆脉小示胆气受惊所伤。戴人曰「此因惊也，惊则胆受邪，腹中当有惊涎绿水」。病人曾屯军被火，惊伤胆腑，涎水停聚。以小脉定惊伤胆之病机，下绿水而愈，说明脉小在此主胆虚受惊、痰涎内结。", ["小"]], "19143": ["妇人", "妇人年四十余得孕，医者不察，误以燔针毒药攻磨。戴人诊六脉皆平，惟右尺脉洪大有力，断为孕脉。右尺候肾与胞宫，孕则气血充盛，故尺脉洪大有力；六脉皆平说明无他病。此以尺脉洪大有力辨孕，示孕脉特征，并告诫治妇当先问娠，不可仓卒误治。", ["洪", "大", "有力"]], "19144": ["病机", "两手脉俱沉实而有力，沉主里、实主邪结，说明冷酒积于左胁、结硬不散，属有形实邪内停。先吐后服和脾去湿药，五七日百脉冲和，脉由沉实转为和平，正说明积去气畅、脾胃复常，故原文以脉之变验证针灸无功而吐下取效。", ["沉", "实", "有力", "和"]], "19145": ["病机", "原文言“两手脉沉细，有积故然”，沉主里、细主积滞久留，茶癖积于左胁十年，气血被积所困而脉道不充，故沉细。虽与肥气形似，然㾬疟不作，非肥气。吐下后诸苦悉蠲，正合积去则脉复之理。", ["沉", "细"]], "19146": ["病机", "脉沉而迟，主里寒积滞，与心下有冷积如复杯、按之水声相应；尺脉洪大而有力，尺候下焦胞宫，洪大为气血充盛之象，故断“非无子之候”，可逾年而孕。吐涎、温中、养血后气血合度，果娠二子，说明沉迟为积寒、尺洪大为有子之征。", ["沉", "迟", "洪", "大"]], "19147": ["病机", "原文诊得“寸口独沉而迟”，寸口候胸中，沉迟主痰水内停、阳气不布，故断“此胸中有痰”。水停心下，渐流两胁，按之水声、心腹结硬，皆痰水结聚之征。以瓜蒂散涌痰后病减，正说明沉迟之脉主胸中痰实，而非单纯冷积。", ["沉", "迟"]], "19148": ["病机", "脉涩而小，涩如刀刮竹，主血行滞涩；小主脉道不利。原文引《脉诀》谓涩脉“女人败血”，故断为块病非孕。孕脉当滑利，今涩小，是瘀血结块阻于胞脉，气血不畅，故以舟车丸、桃仁承气泻下青黄脓血而病去。", ["涩", "小"]], "19149": ["病机", "原文以“尺脉洪大”断为孕，引《素问·阴阳别论》“阴搏阳别”之脉。尺候胞宫，洪大为阴血充盛、搏指有力之象，故虽脐下积块、呕食面黄、肌瘦不月，形似干血气，实为胎孕。脉象为辨孕之关键，不可因症疑脉。", ["洪", "大"]], "19150": ["预后", "两手脉沉且微，沉主里、微主阳气衰微，泄十余年、神昏足肿、泄如泔水，似属危候；然戴人断曰“生也”，是因沉微之中胃气未绝，尚可受食。食羊肝、浆粥后泄减，月余而安，说明脉沉微在此主久泄正虚，而非死脉，忌口太过反伤胃气。", ["沉", "微"]], "19151": ["平脉", "小满至大暑为少阳相火之位，阳气发泄、万物俱成，人应之而脉洪大而长。洪大为阳气盛，长为气机条达，属四时之常脉，非病脉。原文以“天气并万物，人脉盛衰”说明脉随节气而变化，此段主旨为平脉应时。", ["洪", "大", "长"]], "19152": ["平脉", "此段以时令言常脉：大暑至秋分太阴湿土当旺，湿性濡缓，故脉见缓大而长，为湿土之气应时之象；燥金旺时万物干燥，脉转紧细短涩，亦为秋令常脉。原文以脉象随时令更替说明三阴三阳与天气标本相应，非主病之脉，故归平脉。", ["缓", "大", "长", "紧"]], "19153": ["平脉", "秋分至小雪为阳明燥金之位，原文谓气衰阴盛、金气旺，其脉细而微。细为阴血不足、脉道收敛，微为阳气衰微、鼓动无力，合而示秋令阴盛阳衰之常象。此段承前以时令论脉，属应时之平脉，非病脉主病。", ["细", "微"]], "19154": ["主病", "此段论心主脉所生病，未出具体脉名。是动则手心热、臂肘挛急、腋肿，甚则胸胁支满、心中憺憺大动、面赤目黄、喜笑不休；所生病为烦心、心痛、掌中热。诸症皆循心脉所过与心主神明、主血脉相关，示心脉经气变动、火热内扰之病机。", []], "19155": ["主病", "此段论大肠经所生病，未出脉名。是动则齿痛、颈肿；所生为目黄、口干、鼽衄、喉痹、肩前臑痛、大指次指痛不用。气有余则脉所过者热肿，虚则寒栗不复。原文以经脉所过与津液所生立论，示大肠经气实热或虚寒之病机，属主病。", []], "19156": ["病机", "此段论乳痔肠风，引《内经》因而饱食、筋脉横解、肠澼为痔，指出肛门左右有核，属大肠经，可服枳壳之属。原文从饮食饱食致筋脉弛解、湿热下注大肠立论，说明痔核形成之病机，未及脉象，故脉象要素为空。", []], "19157": ["预后", "此段以脉判下痢、水肿、便血之吉凶：下痢脉微小者生、浮大者死，水肿反是，浮大者生、沉细者死；下痢脉浮滑、水肿脉沉细为表里俱病不治；便血两手脉俱弦者死绝，滑大者生，血温身热者死。原文以脉之浮沉大小滑涩弦细与病位表里、胃气存亡相参，定预后生死。", ["沉", "浮", "滑", "细"]], "19158": ["治法", "此段论治湿泄之法，戒骤用豆蔻、乌梅、罂粟壳等塞剂，主张通塞互用、不拘一方；治湿以利小溲为主，诸泄不已灸水分穴，腹鸣如雷为水道行之候；凡湿勿针，并参仲景伤寒汗吐下和法，仍察脉以视深浅、问年壮以视虚实。原文未出具体脉名，主旨在治法。", []], "19159": ["病机", "此段论四时不正之气感而发病：恶寒为表热里和，故脉浮大；发热为里热表和，故脉滑实，可吐法解之；若脉沉实，或不大便、喘满谵语，则不拘日数急攻于里。原文以浮大、滑实、沉实分表里寒热，说明邪在巨阳、阳明、少阳传变之病机与相应治法。", ["浮", "大", "滑", "实"]], "19160": ["病机", "原文以「两寸口脉俱浮滑」主胸中痰攻上，浮为邪在阳位，滑为痰涎壅盛，故可用瓜蒂散吐之；又言「脉沉实者」主邪热在胃，潮热腹满，沉实为里实热结之征。发黄因瘀血宿谷相抟，发斑因心经受热，脉象与证候相参，明辨病位在胸、在胃、在营血。", ["浮", "滑", "沉", "实"]], "19161": ["主病", "原文引仲景云「伤寒头痛，脉寸口急而头痛是也」，寸口脉急主风邪上扰、经气拘急，故见头痛。急脉为紧束不和之象，反映外邪束表、清阳被遏，故治以葱豉汤涌吐、川芎薄荷汤辛凉清上，疏风散邪则脉急可解。", ["急"]], "19162": ["误治", "原文未识脉名，但述前医误认「下元虚冷」而投暖药，病转困弱。后诊脉断为「伤寒瘀血之证」，据小便赤、大便黑，用大黄芍药汤、犀角地黄汤下瘀血，换大便黄色为效。此段主旨在于脉证合参以纠误治，瘀血内阻当以攻下为法，温补反致壅滞。", []], "19163": ["病机", "原文未出脉名，列皮肤发热、肌肉消瘦、盗汗潮热、喘嗽等症，断为「女子不月，血滞之病」「男子肾虚，精不足」，治以降心火、益肾水。此即阴虚火旺、精血亏耗之病机，脉虽未言，当参虚数细涩之象，故戒亡血者不可吐、不可服酸辛热物。", []], "19164": ["误治", "原文未识脉名，专论虚劳误治：不明发表攻里而乱投汤剂，夏月燔灸中脘关元等穴千百壮全无一效，反受其殃。又引「谷入于胃，脉道乃行」说明气血化源，忌食辛酸燥涩致胃口闭涩、形体渐瘦，此死之由。主旨为虚劳当护胃气、忌妄攻妄灸。", []], "19165": ["预后", "原文未出脉名，论脏毒下血因「邪热伤肝，因而大饱，筋脉横解，肠澼为痔」，血随热行入肠胃。以「身体壮热则为难治，身凉者可治」辨预后，壮热示邪热鸱张、血溢不止，身凉则热势已退。治先荡除积血，后以芍药柏皮丸、黄连解毒汤清解。", []], "19166": ["病机", "原文以「脉大」冠首，述骨蒸热发、皮肤枯干、盗汗烦躁、喘嗽黄瘦等症，引《内经》「男子因精不足，女子因血不流」为病本。脉大见于虚劳，乃阴虚阳浮、精血亏耗而气无所附之象，非实热可比，故治先轻涌轻泻，继以柴胡饮子等，慎勿服峻热姜附。", ["大"]], "19167": ["病机", "原文未出脉名，论痔瘘肿痛病机。引《至真要大论》「太阳之胜，凝凓且至，非时水冰，痔疟乃发」，注云「水气太胜，阳火不行」，言阳火畏水郁而为痔；又少阴之复，火气内蒸，金气外拒，热多则内结痈痤，小肠有热则中外为痔。治先导水丸、禹功散泻之。", []], "19168": ["治法", "原文未出脉象，专论便痈即男子血疝，归厥阴肝经及冲任督旁络，属血疝之一。因瘀血聚而不散，故治同瘀血法，用导水丸、桃仁承气汤、抵当汤大泻一二十行，次以玉烛散和血通经；并批评世人多用大黄、牡蛎而不知和血通经之道，全段重在攻瘀泻实之治法。", []], "19169": ["病机", "原文未言脉，论妇人乳痈即吹奶，谓风热结于乳房之间，血脉凝注，久而不散，溃腐为脓。指出病生于心、风热为因，故治用益元散生姜汤调下冷服，或新汲水时时呷之，昼夜三五十次以解热，或煎解毒汤顿服，重在清热散结。", []], "19170": ["病机", "原文未出脉，论妇人年五十以上经脉暴下。经血终于七七之数，数外暴下乃《内经》所谓火主暴速，因暴喜暴怒、忧愁惊恐致然。慎勿作冷病治，下峻热药必死；止宜黄连解毒汤清上，莲壳、棕毛灰渗下，次用四物汤、玄胡索散凉血和经，主火迫血妄行之机。", []], "19171": ["预后", "原文论月事不来皆胞脉闭，胞脉属心络胞中，气上通肺、心下不通故经闭。若误服峻热有毒之药，变成肺痿、骨蒸潮热、咳嗽咯脓、呕血喘满、寝汗不止，渐至形瘦脉大。脉大见于形瘦，是阴血枯竭而虚阳外浮，故虽遇良医亦成不救，属危候预后。", ["大"]], "19172": ["妇人", "原文未出脉，论妇人身重九月而喑哑不言，是胞之络脉不相续，故不能言，《经》曰无治。然以玉烛散煎服入蜜，时时呷之，令火下降，肺金自清则声复出，因肺主声音。全段属妇人妊娠病证及调治之法，非脉象主病之论。", []], "19173": ["妇人", "原文未出脉，论妇人二三十岁无病而无子，经血如常或失调，乃阴不升阳不降，上下不得交通、有所滞碍不能为用。故先涌寒痰，再泄三五行，次服葱白粥养胃，继以玉烛散、白术散、茯苓降火益水，既济则数月有孕；并引《内经》冲任督病不能孕之说。", []], "19174": ["妇人", "原文未出脉，论妇人半产即小产，多在三四月或五六月男女成形之时，因忧恐暴怒、悲哀太甚，或劳力扑打损伤，或触冒暑热所致。慎勿用黑神散犯热药，止宜玉烛散、和经汤。又论无乳及因啼泣郁结、气血闭塞乳脉不通者，以益元散调服、木梳梳乳通之。", []], "19175": ["治法", "原文未出脉，属方药加减治法。加甘遂去湿热腰痛、泄水湿肿满，久病则加；加白芥子去遍身走注疼痛；加朴硝退热散肿毒止痛，久毒宜加；加郁李仁散结滞、通关节、润肠胃、行滞气、通血脉；或加樟柳根去腰腿沉重。全段列药味功用与加减法，不涉脉象。", []], "19176": ["病机", "原文论脾胃肾为根本，五味五气养五脏，强调'太过则病，不及亦病，惟平则常安'。此段无脉象，主旨阐明饮食五味五气偏胜偏衰皆可致病，平则为常。脾病四肢不用，因四肢禀气于胃而不得至经，揭示脾胃为气血生化之源、气机升降之枢的病机。", []], "19177": ["病机", "原文述足太阴脾脉贯胃属脾络嗌，为胃行津液于三阴；足阳明为五脏六腑之海，行气于三阳。四肢不得禀水谷则气衰、阴道不利、筋骨肌肉无气以生而不用。此段无脉象，主旨阐发脾胃行津液、养四肢百骸的生理与脾病四肢不用的病机，并批评以燥热养脾之误。", []], "19178": ["病机", "原文批评世医论消渴不知本，指出消渴'上实热而下虚冷'，本因下部肾水虚不能制上焦心火。强调肾水为人之本、命之元，'根本不坚则枝叶不茂'。此段无脉象，主旨辨析消渴上热下寒、肾水虚衰的病机，反对妄投寒药，主张暖药补养元气使肾水得实。", []], "19179": ["病机", "原文引《刺热论》《热论》论肾热而渴，口燥舌干。批评叔世以热药温补肾水之误，阐明'肾水属阴而本寒，虚则为热；心火属阳而本热，虚则为寒'，肾水阴虚则心火阳实，为阳实阴虚、上下俱热。此段无脉象，主旨辨明肾热消渴的阴阳虚实病机。", []], "19180": ["病机", "原文引《阴阳别论》'二阳结为之消'，注谓胃与大肠俱热结，肠胃藏热善消水谷；又引《气厥论》大肠移热于胃，善食而瘦；《脉要精微论》'瘅成为消中，善食而瘦'。此段虽标'脉要精微论'，实论消中病机，为胃肠热结、善食而瘦之证，非脉象主病。", []], "19181": ["病机", "原文论标本之道与药之巧能，阐发五味功用：酸能收、甘能缓、辛能散、苦能坚、咸能软，并以五行燥湿解释其理，如'燥万物者莫燥乎火''凡物燥则坚'。此段无脉象，主旨说明气味阴阳燥湿之性及苦坚、甘缓、辛散等治疗机理，属药性病机理论。", []], "19182": ["死脉", "原文'病人面白目黑者，死。此谓荣华已去，血脉空索'。面白为气血衰败之象，目黑为神气将绝，血脉空索即脉道空虚、血不充盈，故主死。此以面色与血脉空虚并见，判断荣华已去、生机将竭，属死候之诊，非一般病脉。", ["空", "索"]], "19183": ["病机", "原文诊目病，以赤脉走向辨病位：从上下者属太阳，从下上者属阳明，从外入内者属少阳。此段无脉象，主旨以目络赤脉的循行方向判断邪在何经，属望诊辨经络病机之法，说明目与三阳经脉相连，赤脉走向反映病邪所在之经。", []], "19184": ["预后", "原文以目中赤脉从上下至瞳子的条数推断死期，一脉一岁死、三脉三岁死，赤脉愈多则死期愈远。此非论脉象本身，而是以眼部血络数目测瘰疬寒热之预后，赤脉为热毒内蕴、血络瘀滞之征，故主病深难治，属死候推断。", []], "19185": ["病机", "原文按阳明之脉来太过以定热之所在，太过即脉盛，为阳明热盛之象。热在右则右热，在左则左热，在上则上热，在下则下热，说明脉之太过可反映热邪偏聚部位，牙齿痛由阳明热盛上攻所致，脉来太过正是热盛之病机。", []], "19186": ["兼症", "原文论诊血之色以辨寒热痛痹，又述黄疸见齿垢、爪甲黄等症。脉小而涩者，小为气血不足，涩为血行不畅，故不嗜食，乃脾胃虚弱、血瘀食少之兼症表现，非主病之脉，而是黄疸病中兼见之脉症。", ["小", "涩"]], "19187": ["预后", "伤寒热盛，邪在表阳，脉浮大者与热盛之证相应，为正盛邪实、脉证相符，故生；沉小者脉不应病，正气已衰、邪陷于里，故死。此以脉之浮沉大小判断伤寒热盛之预后顺逆。", ["浮", "大"]], "19188": ["预后", "伤寒已得汗，邪随汗解，脉当静。脉沉小者，为邪去正安、脉证相应，故生；若汗后脉反浮大，是邪热未解或正气外越，脉证相逆，故死。此以汗后脉象判断伤寒预后。", ["沉", "小"]], "19189": ["预后", "温病三四日以下不得汗，邪热郁闭。脉大疾者，邪热盛而正气尚能抗邪，脉证相符，故生；脉细小难得者，正气衰微、无力鼓动，邪盛正虚，故死不治。此以脉之大小疾细判断温病预后。", ["大", "疾", "细", "小"]], "19190": ["预后", "温病穰穰大热，邪热炽盛，脉当洪大。今脉细小，是脉不应病，正气已衰不能胜邪，故主死。此以热盛而脉反细小判断温病危候，属脉证相逆之死脉。", ["细", "小"]], "19191": ["预后", "厥逆汗出，阳气外脱。脉坚强急者，正气尚能抗争，脉证相应，故生；虚缓者，正气涣散、阳气衰微，故死。此以脉之坚强急与虚缓判断厥逆汗出之预后顺逆。", ["坚", "强", "急"]], "19192": ["预后", "温病二三日，身热腹满头痛而食如故，脉直而疾，是邪热亢盛、正气尚能受纳，然脉来劲直急疾，失柔和之象，为胃气已败、邪热独盛，故断八日死；四五日脉来细强，细为阴伤，强为邪实，正虚邪恋，故十二日死；八九日脉来喋喋按之不弹手，脉气衰竭，故十七日死。", ["疾", "细", "强"]], "19193": ["预后", "热病七八日，脉不软不散，是邪热内郁、正气未衰而脉失柔和，热邪上攻咽喉，故当有喑；喑后三日温汗不出，则邪无出路、津液枯竭，故死。脉不软示邪实，不散示气未溃散，正邪交争而汗不得出，预后凶险。", ["软", "散"]], "19194": ["预后", "热病七八日，脉微细，是邪热伤阴、正气衰微；小便不利、暴口燥、舌焦干黑，为阴液枯涸、热毒内陷；脉代则脏气衰败、脉气不能接续，故主死。微细为虚，代为气竭，舌焦干黑为阴竭之征，三者并见，预后不良。", ["微", "细", "代"]], "19195": ["预后", "热病未得汗，脉盛躁疾，是邪热亢盛、正邪交争剧烈，脉象与证相符；若得汗则邪有出路、营卫调和，故生；不得汗则邪无外泄之途，热毒内闭，故难瘥。脉盛躁疾为实热之象，汗之有无决定转归。", ["盛", "躁", "疾"]], "19196": ["预后", "热病已得汗，邪随汗解，脉静安者，是邪退正安、脉证相符，故生；若汗后脉仍躁动，是邪热未净、内热复炽，脉证相悖，故难治。脉静与脉躁对举，以脉之动静判断汗后邪热是否尽解，静则安，躁则病进。", ["静", "躁"]], "19197": ["误治", "热病已得汗而热未去，脉微躁者，是邪热未尽而正气已伤，脉微为虚，躁为热扰，正虚邪恋，此时若再刺治，恐更伤正气、耗竭津液，故慎不得刺。脉微躁示虚实夹杂，宜静养待其自和，不可妄施针泻。", ["微", "躁"]], "19198": ["误治", "热病发热热甚，其脉阴阳皆竭，是邪热亢盛而阴液枯竭、阳气亦衰，脉气不能充盈，故阴阳之脉皆竭。此时正气已败，若再刺治则更伤气血，故慎勿刺；不汗出则邪无出路，必下利则阴液下脱，预后凶险。", []], "19199": ["预后", "诊人被风，不仁痿蹶，是风邪中于经络、气血痹阻；其脉虚者，为正气尚存、邪未深陷，故生；若脉坚急疾，则邪气亢盛、脉失柔和，坚急为风邪劲急，疾为热盛，正不胜邪，故死。脉虚与坚急疾对举，以脉之柔和与否判预后。", ["虚", "坚", "急", "疾"]], "19200": ["预后", "癫病属神志失常，脉实坚为邪气虽盛而正气未衰，脉道充实有力，故主生；脉沉细则正气虚衰，阳气不能鼓动，故主死。原文以脉之实坚与沉细判癫病之生死，实坚应邪实正不虚，沉细应正虚邪陷。", ["实", "坚", "沉", "细"]], "19201": ["预后", "癫疾脉得大滑，为气血尚充、痰浊可化，故久而自已；脉沉小急实，沉小为正虚，急实为邪盛，正虚邪实，故不可疗；小坚急者亦为邪坚正弱，故同属不治。原文以脉之大小滑涩判癫疾之可治与不可疗。", ["大", "滑", "沉", "小"]], "19202": ["预后", "心腹积聚脉坚强急，为邪实而正气尚能抗邪，故生；虚弱则正不胜邪，故死。实强生、沉者死，沉为阳气衰微。脉大而腹大胀、四肢逆冷、脉形长，为阴寒内盛、阳气外越，故死；腹胀满便血脉大时绝，为气随血脱，小疾者亦死。", ["坚", "强", "急", "大"]], "19203": ["预后", "肠澼下白沫，病在阴分，脉沉为脉证相应，阳气内守，故生；脉浮为阳气外浮，阴病见阳脉，正虚邪盛，故死。原文以脉之沉浮判肠澼下白沫之生死，沉则生，浮则死。", ["沉", "浮"]], "19204": ["预后", "肠澼下脓血，脉悬绝为胃气已绝，故死；滑大为气血尚充、邪有外出之机，故生。原文以脉之悬绝与滑大判肠澼下脓血之生死，悬绝主胃气败绝，滑大主正气未竭。", ["滑", "大"]], "19205": ["预后", "肠澼之属，身热而脉不悬绝，滑大者生，为胃气尚存、邪热可解；悬涩者死，悬为胃气将绝，涩为血少气滞，正虚邪恋，故死。原文以脉之滑大与悬涩判肠澼身热之生死，并以脏期之。", ["滑", "大", "涩"]], "19206": ["预后", "肠澼下脓血，脉沉小留连为邪毒虽盛而正气尚能约束，脉证相应，故生；数疾且大为邪热鸱张，热毒炽盛，故死。原文以脉之沉小留连与数疾且大判肠澼下脓血之生死，沉小主正未大伤，数疾主热盛。", ["沉", "小", "数", "疾"]], "19207": ["预后", "肠澼筋挛，为肝血亏虚、筋脉失养，脉小细安静为脉证相应、正气尚能自守，故生；浮大紧为邪气亢盛、正气外浮，故死。原文以脉之小细安静与浮大紧判肠澼筋挛之生死，小细主正虚未竭，浮大紧主邪盛正衰。", ["小", "细", "浮", "大"]], "19208": ["预后", "洞泄食不化、下脓血，为脾胃虚败、肠络损伤之候。脉微小者，正气虽虚而脉证相合，胃气尚存，故生；紧急者，脉来劲急无和缓之象，是邪气鸱张、胃气已绝，正不胜邪，故死。原文以脉之微、紧对举判吉凶，正说明泄利下脓血时脉宜柔缓而不宜劲急。", ["微", "小", "紧", "急"]], "19209": ["预后", "泄注为水湿下趋、脾胃受困之病。脉缓时小结者，缓为胃气尚在，小结虽示邪滞而脉不浮张，脉证相应故生；浮大数者，浮为气越于外，大为邪盛，数为热迫，是阴泄于下而阳浮于上，正气将脱，故死。原文以缓小结与浮大数对举，明泄注脉贵沉静而忌浮数。", ["缓", "小", "结", "浮"]], "19210": ["预后", "蚕蚀阴注为阴部蚀烂之疾，多由湿热虫毒久蚀、气血耗伤所致。脉虚小者，虚小应其正虚邪恋之候，脉证相符，胃气未竭，故生；紧急者，脉来劲急少胃气，是邪毒内攻、正气受迫，故死。原文以虚小与紧急对举，示阴疮蚀注之脉宜虚弱而不宜劲急。", ["虚", "小", "紧", "急"]], "19211": ["预后", "咳嗽而脉沉紧者，沉为邪陷于里，紧为寒饮内搏，肺气壅塞，邪深正困，故死；浮直、浮软者，脉浮则邪犹在表，直软尚有胃气，故生；小沉伏匿者，脉沉伏不起，是阳气衰微、邪气深藏，故死。原文以沉紧、伏匿为死脉，浮软为生脉，明咳病脉贵浮缓而忌沉紧伏匿。", ["沉", "紧", "浮", "直"]], "19212": ["预后", "咳嗽羸瘦，是久咳伤肺、肌肉消削，正气已衰。脉形坚大者，坚为脉无胃气、劲急不和，大为邪气独盛，正虚而邪实，形与脉反，故主死。原文以羸瘦之形与坚大之脉对举，正说明久咳虚损之体，脉宜柔弱而不宜坚大，坚大则胃气败而病深。", ["坚", "大"]], "19213": ["预后", "咳而脱形发热，是久咳伤肺、肌肉脱削而虚热外浮，正虚邪盛之候。脉小坚急者，小为正气衰少，坚急为脉无和缓、邪气劲迫，虚体而见劲急之脉，脉证相反，故死。原文以脱形发热与坚急之脉并见，明虚损咳热之病脉宜柔缓而忌坚急。", ["小", "坚", "急"]], "19214": ["预后", "咳而呕、腹胀且泄，是肺病及脾，气逆于上而水谷不化，三焦俱病。脉弦急欲绝者，弦为木气乘土，急为脉无胃气，欲绝则正气将竭，脉证俱败，故死。原文以弦急欲绝断死，说明咳呕胀泄并见时，脉宜和缓而忌弦急无根。", ["弦", "急"]], "19215": ["预后", "吐血、衄血为血热妄行、络伤血溢之候。脉滑小弱者，滑为血中尚有流动之机，小弱为脉不张而胃气未败，血虽出而正未脱，故生；实大者，实为邪热壅盛，大为脉张无制，热迫血溢而正气随脱，故死。原文以滑小弱与实大对举，明失血脉宜柔弱而忌实大。", ["滑", "小", "弱", "实"]], "19216": ["预后", "汗出或衄血，津血已伤，脉小滑者，小为形损而脉不亢，滑为胃气尚存、阴血未竭，故主生；若脉大躁，大为邪盛，躁为阴不敛阳、虚阳外越，与汗衄后津血耗散相应，故主死。原文以大小躁滑对举，判气血存亡之预后。", ["小", "滑", "大", "躁"]], "19217": ["预后", "吐血后脉紧强者，紧为寒凝收引，强为脉体劲急无胃气，示血出而阴寒内盛、络脉拘急，气血难复，故死；脉滑者，滑为血中尚有胃气、营血未至枯竭，故生。原文以紧强与滑对举，辨吐血后脉之胃气存否。", ["紧", "强", "滑"]], "19218": ["预后", "吐血而咳上气，已属肺胃气逆、血不归经；脉数有热，数为热盛，热迫血行而气逆不降，加之不得卧，示阴不敛阳、肺气壅逆，正虚邪盛，故主死。原文以数、热、不得卧三者相合，明热盛气逆、形损难支之危候。", ["数"]], "19219": ["预后", "上气而脉数者，数为阳热亢盛，气逆于上而脉亦急促，示邪热耗损形气，原文谓“损形故也”，即形气已为热所消烁，故主死。数脉在此非单纯热象，而是形损气逆、阴阳不相维系之征，与上气并见则预后不良。", ["数"]], "19220": ["预后", "上气喘息低昂，气逆已甚；脉滑而手足温者，滑为胃气尚存、阳气未绝，温为阳气得达四末，故生；脉涩而四肢寒者，涩为营血凝滞、脉道不利，寒为阳气衰败不达四肢，故必死。原文以脉之滑涩合手足温寒，判阳气存亡。", ["滑", "涩"]], "19221": ["预后", "上气而面浮肿、肩息，为水气上逆、肺气壅塞之重候；脉大者，大为邪气盛而脉无收敛，示正气不能制约水气，形气与脉俱张，故不可治，加利则更伤正气必死。原文以脉大断其邪盛正衰、水气泛溢难返。", ["大"]], "19222": ["预后", "上气注液，气逆而津液外泄，脉虚而宁伏匿者，虚为正气虽弱而脉不亢，伏匿为邪气未张、胃气尚能自守，故生；若脉坚强者，强为脉失柔和、邪气锢结，示正气已不能胜邪，故死。原文以虚伏与坚强对举，辨正邪进退。", ["虚", "伏", "匿", "坚"]], "19223": ["预后", "寒气上攻，脉实而顺滑者，实为邪实，滑为营卫尚通、胃气未败，故生；实而逆涩，涩为气血凝滞、邪无出路，故死。若形尽满而脉急大坚、尺满不应，急大坚示邪盛脉失柔和，顺逆以手足温寒为断，温则阳气犹达，寒则阳衰，故判生死。", ["实", "滑", "涩", "急"]], "19224": ["预后", "病瘅见脉实大，为邪盛而正气未衰，故病久可治；若脉弦小坚急，弦小为正气已损，坚急为邪气深入，脉证相反，故病久不可治。原文以脉之实大与弦小坚急对举，判断瘅病久病之预后。", ["实", "大", "弦", "急"]], "19225": ["预后", "消渴脉数大者，为燥热内盛而正气尚能抗邪，故生；细小浮短者，细为阴伤，小为气衰，浮短为虚阳外浮，脉证相失，故死。原文以数大与细小浮短对举，辨消渴之生死预后。", ["数", "大", "细", "浮"]], "19226": ["预后", "消渴脉沉小者，沉为病在里，小为阴液虽伤而邪热不亢，脉证相合，故生；实坚大者为邪热亢盛而正气已伤，脉证相反，故死。原文以沉小与实坚大对举，判消渴之预后。", ["沉", "小", "实", "坚"]], "19227": ["预后", "水病脉洪大者，为水气虽盛而正气尚充，脉证相应，故可治；微细者为阳气衰微，无力运化水湿，脉证相失，故不可治。原文以洪大与微细对举，辨水病之可治与不可治。", ["洪", "大", "微", "细"]], "19228": ["预后", "水病胀闭脉浮大软者，浮大示水气在表，软为正气尚和，脉证相合，故生；沉细虚小者为阳气虚衰，水湿内停，脉证相反，故死。原文以浮大软与沉细虚小对举，判水病胀闭之预后。", ["浮", "大", "软", "细"]], "19229": ["预后", "水病腹大如鼓，脉实者，为水湿内盛而正气尚能抗邪，脉证相应，故生；脉虚者为正气已衰，无力运化水湿，脉证相失，故死。原文以脉实与虚对举，辨水病腹大之生死预后。", ["实", "虚"]], "19230": ["预后", "卒中恶咯血数升，脉沉数细者，沉细为阴血已伤，数为虚火内扰，脉证相失，故死；浮大疾快者为邪热外达，正气尚能抗邪，故生。原文以沉数细与浮大疾快对举，判咯血之预后。", ["沉", "数", "细", "浮"]], "19231": ["预后", "卒中恶腹大四肢满，脉大而缓者，大为邪盛，缓为胃气尚存，脉证相合，故生；紧大而浮者为邪气亢盛而正气外浮，故死；紧细而微者，紧为邪结，细微软弱为正气虽伤而未绝，故亦生。原文以三脉对举，判卒中恶之预后。", ["大", "缓", "紧", "浮"]], "19232": ["死脉", "寒热瘛疭为邪正交争、筋脉失养之候，脉见代绝，是脏气衰微、脉气不能接续之象。代主脏气衰，绝则脉气断，故主死。此段以脉代绝判断预后，说明邪盛而正气已败，脉道不通，故为死候。", ["代", "绝"]], "19233": ["预后", "金疮血出太多，阴血骤亏，脉宜虚细，为脉证相符，故生；若见数实大，是失血后反见邪热亢盛、脉道壅实，阴血亏而阳热独盛，脉证相反，故死。此段以脉之虚实判断失血后预后。", ["虚", "细", "数", "实"]], "19234": ["预后", "金疮出血，脉沉小者，沉为在里，小为血少，脉证相应，故生；浮大者，浮为气外越，大为邪热盛，失血后脉反浮大，是阴不敛阳、气随血脱之兆，故死。此段以脉之沉浮大小辨出血后吉凶。", ["沉", "小", "浮", "大"]], "19235": ["预后", "斫疮出血一、二升，失血已多，脉宜沉细，今脉来大，是大为邪热亢盛、脉道扩张，失血后脉反大，为脉证相反，阴血亏而阳热独亢，故预后不良，二十日死。此段以脉大判断失血后死期。", ["大"]], "19236": ["预后", "斫刺俱有病，血出不自止，失血过多，脉来大者，大为邪热盛而脉道不收，失血后脉反大，为脉证相反，故七日死；滑细者，滑为血有余，细为脉道和缓，脉证相应，故生。此段以脉之大小滑细辨出血后生死。", ["大", "滑", "细"]], "19237": ["预后", "从高顿仆，内有瘀血，腹胀满，脉坚强者，坚为脉道充实，强为邪实，脉证相应，故生；小弱者，小弱为正气衰微，瘀血内阻而脉反小弱，是正不胜邪，故死。此段以脉之坚弱辨瘀血内停之预后。", ["坚", "强", "小", "弱"]], "19238": ["预后", "人为百药所中伤，脉涩而疾者，涩为血行不畅，疾为邪毒内扰，脉证相应，故生；微细者，微细为正气衰微，邪毒内陷而脉反微细，是正不胜邪，故死；洪大而迟者，洪大为邪盛，迟为脉道尚和，故生。此段以脉辨中毒后预后。", ["涩", "疾", "微", "细"]], "19239": ["预后", "人病甚而脉不调者，脉不调为脉气紊乱，病甚而脉乱，是正气已衰、邪气独盛，故难治；脉洪大者，洪大为邪热亢盛而脉道充盈，正气尚能抗邪，脉证相应，故易瘥。此段以脉之调与不调、洪大与否判断病之难治易愈。", ["洪", "大"]], "19240": ["预后", "脉实满为邪气壅盛、阴阳格拒之象，手足寒而头热，是阳郁于上、阴凝于下，上下不交。春秋气机升降有序，尚可生机；冬夏寒暑偏极，格拒更甚，故必死。此以脉实证逆断死生，非单论病机。", ["实", "满"]], "19241": ["预后", "老人脉微为阳羸阴强，阴阳尚能相守故生；脉大加息者，脉大而加急，是阳强阴弱、根本已离，故死；阴弱阳强而脉至代，代主脏气衰败、脉不接续，故期月而死。三段皆以脉之微、大、代判老人阴阳离决之预后。", ["微", "大", "代"]], "19242": ["病机", "尺脉涩而坚，涩主血少、坚主邪实，故为血实气虚。血实气滞则腹痛逆满、气上行；妇人胞中绝伤、恶血久成结瘕，正涩坚之脉所主。得病冬时，黍穄赤而死，以脉证与时令相逆断预后。", ["涩", "坚"]], "19243": ["病机", "尺脉细而微，细主血少、微主气虚，故血气俱不足；细而来有力，是脉虽细而按之有力，为谷气不充、胃气未绝。病得节辄动，言其病随节气而发，秋时得之，枣叶生而死，以脉细微而胃气弱断其预后。", ["细", "微"]], "19244": ["预后", "左手寸口脉偏动，乍大乍小不齐，从寸至关、关至尺三部脉动各异不同，是脉气偏聚、阴阳不相顺接，非平和之象。仲夏得之，火气当令而脉反偏动不齐，故桃花落而死，以脉之偏动不齐断预后。", ["动"]], "19245": ["预后", "右手寸口脉偏沉伏，乍小乍大，朝浮大而暮沉伏，浮大则太过上出鱼际，沉伏则下不至关中，往来无常，是脉气散乱、阴阳不相维系。时复来者，胃气尚存一线，然终至榆叶枯落而死，以脉之偏沉伏、往来无常断死期。", ["沉", "伏", "浮", "大"]], "19246": ["预后", "右手尺部脉三十动一止、二十动一止，乍动乍疏，连连相因，不与息数相应，是脉来结代、脏气衰败、脉不接续之象。虽食谷犹不愈，谷气不能续脉，故蘩草生而死，以脉之结代疏数不匀断预后。", ["结", "代"]], "19247": ["死脉", "右手尺部脉四十动一止，止而复来，来逆如循张弓弦，𫄠𫄠然如两人共引一索，是脉来劲急弦紧、毫无胃气柔和之象，止而复来更见脏气败绝。至立冬死，以脉之弦紧劲急、结止不复断为死脉。", ["弦", "紧"]], "19248": ["病机", "原文分饮、食二端论病机：饮为无形水气，大饮则气逆，形寒饮冷伤肺，病见喘咳肿满水泻，治以发汗利小便分消其湿；食为有形之血，饱食则筋脉横解、肠澼为痔，伤太阴厥阴则寸口大于人迎，见呕吐痞满下痢。全段以水谷寒热分伤六腑立论，非辨脉象，故脉象要素为空。", []], "19249": ["病机", "原文引《金匮》\"平人脉大为劳，脉极虚亦为劳\"，又言劳病\"其脉浮大\"。脉大为热邪亢盛，极虚为气损不足，浮大乃虚阳外浮、劳伤气耗之象，与手足烦热、喘乏自汗、懒言困热相应。春夏剧者时助邪，秋冬瘥者时胜邪，故以黄芪建中汤甘温补中、酸收散气。", ["大", "虚", "浮"]], "19250": ["病机", "脉弦洪缓而沉按之中之下时一涩，为饥饱劳役损伤脾胃元气之象：弦洪缓见于外，是虚火与湿浊相兼；沉取时涩，乃元气不足、血行不畅。故证见四肢满闷沉重、肢节疼痛难屈伸、烦心不安、二便不调、餐泄不化、耳鸣目花等，皆脾虚湿郁、清阳不升、湿热壅遏之候。", ["弦", "洪", "缓", "涩"]], "19251": ["兼症", "原文论大便虚坐不得、便了而不了、腹中逼迫，断为\"血虚血涩\"，故加当归身养血润肠；又言身体沉重、小便数多，加茯苓、黄柏、泽泻、苍术以暂去湿热，并指出足太阴已病其脉络心，故湿热相合而生烦乱。全段重在随兼症加减用药，未及脉象，故脉象要素为空。", []], "19252": ["病机", "原文言秋冬之月胃脉四道为冲脉所逆，胁下少阳脉二道反上行，名曰厥逆。冲脉之气上逆，故证见气上冲咽不得息、喘息有音、不得卧，乃厥气上逆、胃气不降之病机，治加吴茱萸温降逆气，并观厥气多少而用之。段中论经脉逆行之理，未出具体脉象。", []], "19253": ["治法", "原文述丸药服法：空心白汤送下，多饮热汤，少时以美食压之，使药不停留胃中，直下下元以泻冲脉之邪。并总括饮食劳倦所得之病属虚劳七损证，治宜甘温平调、甘多辛少。全段主在服法与治则，未言脉象，故脉象要素为空。", []], "19254": ["误治", "原文借易水张先生之戒，批评峻利食药之害：药丸下咽未化，标皮之力始开便言快，所伤之物未去而脾胃已损，真气元气败坏，促人之寿。故设枳实白术荷叶烧饭为丸，先补脾胃之弱，而后化其所伤，则不峻利。全段论误用峻利之弊与补救之法，未涉脉象。", []], "19255": ["病机", "原文引《六元政纪论》\"诸湿肿满皆属脾土\"，论脾为阴中太阴、同湿土之化，脾湿有余则腹满食不化；又言脏寒生满病，饮食劳倦损伤脾胃，始受热中、未传寒中，脾胃气虚不能运化精微，水谷聚而不散而成胀满，过在太阴阳明，乃寒湿郁遏，即《脉经》\"胃中寒则胀满\"之谓。", []], "19256": ["病机", "原文论腹胀满，分寒热虚实。热胀为八益之邪传里化热，胃实便结；寒胀为内虚不足，寒湿中满，浊气在上。脉家当辨寒热多少，胃中寒则胀满，三阳膀胱寒水为胀。强调脉象可较寒热，但未出具体脉名，故病机为寒热错杂、虚实相因。", []], "19257": ["治法", "右关脉弦，关候脾胃，弦主肝木乘土。心下虚痞、恶食懒倦，乃脾胃虚弱，肝气犯胃，气机壅滞。治以开胃进饮食，抑木扶土，使脾胃复运。脉弦为木郁克土之象，与虚痞恶食相应。", ["弦"]], "19258": ["病机", "脾胃虚弱至极，心火乘之，冬寒水旺，子令母实，肺金大肠来克心乘脾胃，为大复仇。外则大寒大燥乘之，恶风寒、耳鸣、鼻塞、脑痛；内则寒水反乘，痰唾沃沫、食反出、腹痛、泄泻、霍乱。脉虽未明，病机为脾胃虚极、寒燥外袭、脏腑相乘。", []], "19259": ["病机", "上部有脉下部无脉，为木郁之象。饮食过饱填塞胸中，太阴分野气口反大于人迎三倍，食伤太阴，肝木生发之气被郁于下。木郁则达之，吐法使食去木舒。脉绝于下非真无脉，乃食塞上焦、气不下达所致。", []], "19260": ["治法", "盛食填塞胸中，窒塞闷乱，两寸脉当主事而两尺不见。食为坤土，胸中为肺金，金土俱上旺而克木，肝木伏于地下，故木郁。吐去上焦阴土之物，木得舒畅。若两手尺脉绝无，不宜便用吐药，恐损元气。脉绝于下因食塞于上，非脏气真绝。", []], "19261": ["预后", "二阳结谓之消，阳明津血不足，燥热为病。数食甘美多肥，气上溢转为消渴。脉实病久可治，脉弦小病久不可治。实脉为邪气尚盛，弦小为阴气已衰，故预后不良。消瘅仆系偏枯痿厥，肥贵人膏粱之疾，脉象关乎津血存亡。", ["实", "弦", "小"]], "19262": ["兼症", "口干舌干、小便数、舌上赤脉，为津液不足、燥热内生之兼症。治以生津液、除干燥、生肌肉。舌上赤脉为心火或胃热上炎，小便数为津亏不能制约。脉象未出，主症为燥热伤津。", []], "19263": ["治法", "方中柴胡、升麻升清，当归、生地、知母、黄柏滋阴清热，黄连治舌上赤脉，石膏治小便赤色，杏仁、桃仁、红花活血润燥。全方针对口干舌干、小便数、舌上赤脉，乃津亏燥热、血中伏火之治法，脉象未明。", []], "19264": ["病机", "原文仅言'诸脉者皆属于目'，未出具体脉名，故脉象要素为空。此段论目与血脉相通，五脏六腑之精气由脉上注于目，脉为目之根本。脉象虽未明言，然其主旨在于说明目病当察脉之盛衰，脉和则目得血而能视，脉病则目失所养。属病机总论，非主一脉一病。", []], "19265": ["病机", "此段未出脉名，论目之构造与邪中目系之病机。'邪中于项，因逢其身之虚，其入深'，邪随眼系入脑，脑转引目系急而目眩；'精散则视岐，故见两物'。又言'神劳则魂魄散，志意乱'，强调目为神气所主，神乱则精明失用。全段以目系受邪、精气散乱为病机核心。", []], "19266": ["病机", "此段未出脉名，论瞳子散大之病机。'心主火，肝主木，此木火之势盛也'，心包络代心行事，与少阳相火为表里，木火相煽则瞳子开大。故饮食宜苦酸凉，大忌辛辣热物以助火邪；药中去茺蔚子之辛，加芩连泻火。全段以木火亢盛、相火代令为病机，属瞳神散大之证治。", []], "19267": ["病机", "此段未出脉名，述目疾久服寒凉不愈之证。'两眼蒸热如火之熏，赤而不痛，满目红丝血脉贯睛'，羞明畏日，睑赤烂，内外眦破。此乃寒凉遏抑，火热郁于血分，不得外泄，故血脉贯睛而蒸热。病机为郁火内伏、血热上攻，非单纯实火，故累服寒凉反不愈，当以洗法透泄郁热。", []], "19268": ["主病", "两手寸脉细紧，按之洪大无力，细紧为寒水之象，洪大无力为相火虚张。原文断为'足太阳膀胱为命门相火煎熬，逆行作寒水翳及寒膜遮睛'，相火煎熬而水寒上逆，故见黑翳、目紧缩、呵欠善悲、嚏喷眵泪、面赤白、小便数而欠、气上而喘。脉细紧主寒水，洪大无力主火不归元，寒热错杂之候。", ["细", "紧", "洪", "大"]], "19269": ["病机", "此段未出脉名，论血弱阴虚不能养心，心火旺而阳火甚，致瞳子散大。'少阴为火，君主无为，不行其令，相火代之'，心包络与少阳相火同气，火盛则令母实，乙木肝旺，风热从少阳之道上攻头目，偏头肿闷，视物则花。病机为血虚阴弱、木火相煽、风热上攻，法当养血凉血、收火散大、除风热。", []], "19270": ["病机", "此段未出脉名，历举头痛诸因：风寒伤上客于经络，令人振寒头痛身重恶寒，治在风池风府；肠胃气虚则头痛耳鸣九窍不利；湿热头痛病在膈中；下虚上实则头痛癫疾；偏头痛取手足少阳阳明。全段以头痛分经辨证为纲，示人头痛非一因，当辨风寒、气虚、湿热、下虚上实、偏侧之别。", []], "19271": ["主病", "原文'太阴脉缓有痰，名曰痰厥头痛'，脉缓主太阴脾湿，湿聚生痰，痰浊上蒙清窍则为头痛。故于羌活防风川芎甘草方中减其升散，加半夏一两五钱以燥湿化痰。脉缓为脾湿之征，痰厥头痛以痰湿内阻为病机，与太阴脉缓相应，属主病兼治法之论。", ["缓"]], "19272": ["病机", "本段论齿痛诸证，未出脉名，而以经络脏腑分病机：上龈属足阳明胃脉贯络，下龈属手阳明大肠脉贯络，手阳明恶寒饮、足阳明恶热饮，故有恶寒、恶热、寒热兼恶诸痛之别。又言“牙者肾之标亦喜寒”，热甚则齿动龈袒脱作痛，虫蚀则齿缺色变。全段以寒热虚实、风邪虫蚀辨齿痛所主，非论脉象，故脉象要素为空。", []], "19273": ["病机", "原文谓“其脉上中下三部阳虚阴盛”，脉微小为阳气衰微、阴寒内盛之象；小便滑数则属下焦不固、虚阳不藏。脉证合参，知非实热牙痛，乃阳虚阴盛、五脏内盛而六腑阳道衰微，故虽齿痛剧烈、头脑项背痛而微恶寒饮、大恶热饮，治当温阳散阴，不可径用寒凉。", ["微", "小", "滑", "数"]], "19274": ["兼症", "本条为丸药服法及兼治诸证，末言“其脉洪大而缓者”，洪大为气分热盛、脉道充盈，缓为胃气尚存或湿热壅滞之象。原文以此脉统摄血痢、血崩、血下褐色紫黑及肠澼下血等兼症，又治麻木厥气上冲、逆气上行、妄闻妄见，示湿热郁蒸、气血逆乱之病机，脉洪大而缓正是邪盛而胃气未败之征。", ["洪", "大", "缓"]], "19275": ["病机", "“六脉俱大按之空虚”是大而中空之象，主气盛而血亡，即原文所谓“此气盛多而亡血”。气盛则脉道张大，血亡则脉体不充，故按之空虚。心动面赤善惊上热，为手少阴心脉之病，阴血亏而阳气浮越。治以甘寒镇坠大泻其气、坠气浮，以甘辛温微苦峻补其血，正是针对气盛亡血、浮阳上逆之病机。", ["大", "空", "虚"]], "19276": ["主病", "“两寸脉芤”者，芤脉浮大中空，如按葱管，主失血。寸部候上焦，两寸俱芤，故知血在上焦，或衄血或呕血，血去脉道空虚而外浮，遂见此象。原文径以犀角地黄汤治之则愈，是取凉血止血、清解血分郁热之义，脉芤与上焦出血之症相应，为失血主脉。", ["芤"]], "19277": ["其他", "本条仅存“救脉汤（一名人参救肺散）”方名，未载脉象、脉名及脉理，亦无论证文字，无从据脉析其病机。方名“救脉”“救肺”提示所治当与肺气欲绝、脉气将败相关，然原文过简，不可臆测其脉象要素与所主症候，故脉象要素为空，归类为其他。", []], "19278": ["治法", "本条为方药组成及药后注文，人参益上焦元气而实表，麦冬保肺气，桂枝补表虚，当归和血养血，甘草补脾胃之虚，麻黄去根节，黄耆实表益卫，白芍药各一钱，五味子五个“安其脉气”。全段以补益肺气、实表固卫为法，五味子安其脉气，示脉气浮散不敛之病机，然未出具体脉象，故脉象要素为空。", []], "19279": ["病机", "“六脉弦细而涩按之空虚”，弦细涩为血少脉道不充、气血凝滞之象，按之空虚则阴血内亏尤甚。原文断为“脱血也，此大寒证”，又谓“亡血亦伤精气”，色白而天不泽正是血脱不能荣养之征。大寒伤阳、血涩不行，故以辛温补血益血，佐甘温甘热滑润之剂，使血得温而行、得润而充。", ["弦", "细", "涩", "空"]], "19280": ["病机", "原文未提脉象，但述役人露宿寒湿之地，腰痛不能转侧、两胁搐急作痛月余。病机为寒湿外袭，足太阳、足少阴血络中凝血作痛，间涉少阳胆经外络。寒湿凝滞血络，气血不通则痛，故治以通经络、破败血。", []], "19281": ["病机", "脉缓而迟，缓主湿、迟主寒，正值季春，阳气当升而寒湿困阻，故见阴室中汗出懒语、四肢困倦无力、走注疼痛。下焦伏火不得伸，风湿相搏，一身尽痛。脉缓迟示寒湿在经，故宜升阳发汗，使风湿去而阳升。", ["缓", "迟"]], "19282": ["病机", "心包脉洪数躁作，为包络火邪炽盛；沉脉涩不利，则月事沉滞。洪数主热，涩主血滞。热烁津液，血海干枯，故经水闭绝、肌肉消瘦、渴躁，病名血枯经绝。治宜泻胃燥热、调血脉、除包络火邪。", ["洪", "数", "涩"]], "19283": ["病机", "命门脉沉细而数疾，或沉弦洪大有力，寸关亦然。沉细数疾主脾胃虚损、湿热下迫；弦细为寒作于中，洪数疾为热明矣。脾胃有亏，下陷于肾，与相火相合，湿热下迫，经漏不止，色紫黑如腐肉之臭，兼白带、赤带、腰痛脐痛。", ["沉", "细", "数", "疾"]], "19284": ["病机", "脉缓而弦急，按之洪大，中指下得之，为脾土受邪。缓主脾虚湿盛，弦急主痛、主木乘土，洪大为心火乘脾。饮食劳倦伤脾，心火乘之，包络代心主令，故漏下恶血、月事不调、暴崩不止，兼怠惰嗜卧、四肢不收、气短上冲。", ["缓", "弦", "急", "洪"]], "19285": ["治法", "脉缓者是也，缓主脾虚湿盛。足太阴脾经血海穴治女子漏下恶血、月事不调、逆气腹胀，其脉缓，正合脾经湿滞、气血不调之机。灸三壮以温通脾经，除湿调血，故以脉缓为用穴之凭。", ["缓"]], "19286": ["病机", "脉沉厥紧而涩，按之空虚，为气血俱虚之极。沉紧主寒，涩主血虚，按之空虚为真气欲竭。上中下三阳真气俱虚，故见癫疝白带、腰以下如冰雪、面白如枯鱼、肌肉削瘦、小便遗而不知、哕呕不止，乃阴寒内盛、胃虚之极。", ["沉", "厥", "紧", "涩"]], "19287": ["病机", "原文未出脉象，述白带久下不止、脐腹冷痛、目中溜火、齿恶热饮。病机为寒湿乘胞内，故喜干恶湿；肝经阴火上溢走标，故目溜火；肾水侵肝上溢，故目䀮䀮；齿恶热饮为阳明伏火。治当大泻寒湿，以丸药缓治，忌汤散。", []], "19288": ["病机", "二尺脉弦紧洪而按之无力，弦紧为寒凝收引，洪为虚阳外浮，按之无力则中气已虚。原文谓脐下如冰、求厚衣被，是下焦沉寒；白带白滑多而间如屋漏水下、时有鲜血，乃脾虚不摄、血海不固，故尺脉时微洪为虚火扰动，主崩漏不止、心气不足兼脾胃虚寒之证。", ["弦", "紧", "洪", "微"]], "19289": ["病机", "脉沉细而缓，间而沉数，沉细缓为脾胃虚弱、气血不足，间数则虚中有热。原文载掌中寒、四肢无力、上喘气短、胃脘当心而痛、左胁下缩急有积、当脐动气，皆心气不足、脾胃虚弱、元气下陷之候。脉与证合，故先治其本，安心定志、调和脾胃、大益元气，余证可去。", ["沉", "细", "缓", "数"]], "19290": ["病机", "原文未明载脉象，然述经脉漏下不止、色鲜红，因劳役脾胃虚弱，气短气逆、自汗不止、身热闷乱、恶食倦卧、四肢无力、大便时泻，复因心气不足而经下不止，觉气下脱、元气逆上全无、气短不能言。此脾胃气虚下陷、气不摄血之崩漏，故以补中升阳、益气摄血为主。", []], "19291": ["病机", "右尺脉控之空虚，是气血俱脱、大寒之证；轻手数疾、举指弦紧或涩，数疾为虚阳外越，弦紧涩为寒凝气滞，皆阳脱之象。原文谓阴火亦亡、热证见于口鼻眼或渴，此阴躁阳欲先去。故当温之举之升之浮之燥之，大升浮血气、补命门之下脱，主崩漏日久、气血大脱之危候。", ["虚", "数", "疾", "弦"]], "19292": ["病机", "诊得心包尺脉微，微为阳气衰微、气血不足。原文引叔和“崩中日久为白带，漏下多时血水枯”，谓崩中始病血崩，久则血少复亡其阳，故白滑之物下流不止，本经血海将枯、津液复亡，不能滋养筋骨。脉微正合阳衰血枯之机，故以辛甘润燥滋液、辛热补阳生血、苦寒泄肺救上热，佐人参益元气。", ["微"]], "19293": ["病机", "六脉俱弦洪缓相合而按之无力，弦在上为风热下陷入阴中、阳道不行；洪缓按之无力，是阳气衰而阴旺。原文述闭目则浑身麻木、开目渐退，闭目属阴、阳道闭而不行，故知阳衰阴旺。虽肌肤充盛、饮食不减，然麻木、痰嗽、烦躁气短喘促，皆阳气不能布达之候，非外风实证。", ["弦", "洪", "缓"]], "19294": ["治法", "脉涩主气机涩滞、血行不畅。原文谓脉涩觉身痒、气涩而大便不通，涩为气燥血少、肠道失润之象，故于主方中加郁李仁、大黄以除气燥、通大便。此段以脉涩定气燥便闭之兼症，属随脉加减之治法，非专论病机。", ["涩"]], "19295": ["误治", "病人虽属阴证阴寒，而病显躁、脉实坚，实坚为邪热内郁、躁动不安之象，非纯寒可温。原文告诫此时宜于阳药中少加苦寒之药以去热躁，躁止勿加，防过用苦寒伤阳。此段辨阴证见实坚躁脉之处理，属治法纠偏，示不可一味温燥。", ["实", "坚"]], "19296": ["病机", "原文辨阴躁欲坐井中者，谓其肾脉按之必虚，或沉细而迟。肾阳衰微，虚阳浮越于外则躁扰不宁，脉按之虚乃肾气不足之征；沉细而迟为阳虚阴盛、脉道失充之象。此脉主肾虚阴躁，与欲坐井中、内真寒外假热之症相应，故言易辨，并提示客邪当从权加药去之。", ["虚", "沉", "细", "迟"]], "19297": ["病机", "原文引《内经》饱食致筋脉横解、肠澼为痔，论大肠燥金受木火侮而火就燥，大便必闭。虽未出脉名，然以五行生克推病机：阳衰则土不生化，木乘火势侮燥金，故以苦寒泻火、辛温和血润燥疏风止痛为治，方用秦艽、当归梢、桃仁、皂角仁等，示痔漏由湿热风燥壅结大肠所致。", []], "19298": ["治法", "原文承前饱食筋脉横解、肠澼为痔之论，提出治法当补北方、泻中央。北方属肾水，中央属脾土，补北即滋肾水以制火，泻中即清脾胃湿热以除壅滞。此段未及脉象，专论痔漏经年之治则，体现泻火润燥、标本兼顾之法，与上段病机相呼应。", []], "19299": ["病机", "原文述前阴臊臭因连日饮酒，腹中不和。前阴为足厥阴肝脉络所过，臭属心主，肝臭为臊，故泻行间治本、泻少冲治标。酒气味俱阳，能生里之湿热，风湿热合于下焦为邪，下焦如渎，宜引而竭之，决前阴以去湿热。此段未出脉象，以经络脏腑与酒湿论病机。", []], "19300": ["主病", "原文治脐下撮急疼痛、周身皆急痛、小便频数，五脉急而独肾脉按之不急、皆虚无力，名曰肾疝。五脉急为寒凝收引之象，肾脉虚无力则肾气本虚，虚寒内结于下焦，故脐下撮急而周身牵痛、小便频数。此脉主肾虚寒疝，与少腹急痛、尿频之症相应。", ["急", "虚"]], "19301": ["病机", "原文治肠澼下血另作一派，其血唧出有力而远射四散如筛，肠中血下行、腹中大作痛，断为阳明气冲热毒所作。虽未言脉，然血出有力远射、腹痛俱属热毒壅盛、气冲血溢之征，故治当升阳去湿热、和血脉，使热毒清而血自宁。", []], "19302": ["病机", "原文治肠澼下血、血色紫黑、腹中痛、腹皮恶寒，右手关脉弦按之无力而喜热物熨之，断为内寒明矣。关脉候脾胃，弦为寒凝气滞，按之无力则中阳不足；血色紫黑、腹皮恶寒、喜热熨皆虚寒之征。此脉主脾胃虚寒、血失统摄之下血。", ["弦"]], "19303": ["病机", "原文治太阴阳明腹痛、大便常泄或秘而难、后传湿热毒下鲜红血、腹中微痛、胁下急缩，脉缓而洪弦、中下得之、按之空虚。缓为脾土本象，洪弦主湿热壅盛，按之空虚则中气不足；湿热下注大肠则便血鲜红，脾虚肝急则胁下急缩。此脉示脾虚湿热下血之机。", ["缓", "洪", "弦", "虚"]], "19304": ["治法", "原文未出脉名，专论护皮毛、实腠理、虚补元气、活血脉生血之药效，属疮家圣药的功能归纳。其“补表实元气之弱”点明虚者当补，非凭脉断病，故无脉象要素可录，主旨归于治法而非主病。", []], "19305": ["兼症", "原文以“脉涩”为凭，涩主气机涩滞、血行不畅，故见身痒；气涩不行则大便不通。治加郁李仁、大黄“以除气燥”，是据涩脉辨气燥内结之兼症，非单主一病，故归兼症。", ["涩"]], "19306": ["病机", "左右尺脉俱紧，按之无力，紧主寒凝、痛聚，无力则示正气不足。寒凝下焦血络，故尻臀生痈、坚硬肿痛大作。脉紧而无力说明寒凝兼虚，非实热壅盛，病位在足太阳经，故以脉断病机。", ["紧"]], "19307": ["病机", "脉弦洪为气火有余、热毒壅盛之象，按之细小则示营血不足、毒陷于里。妇人乳间黑头疮、疮顶陷下作黑眼子，正合外有热毒、内兼血虚之机。弦洪与细小并见，说明毒盛而正伤，故以脉析病机。", ["弦", "洪", "细", "小"]], "19308": ["病机", "左三部细而弦，按之洪缓微有力。细弦示厥阴肝经气血不足而经气不舒，洪缓微有力则示湿滞血壅、毒聚成痈。病在足厥阴肝经之分兼侵足太阴脾经，故附骨痈漫肿木硬、疮势甚大，脉象正说明肝脾经气血凝滞之病机。", ["细", "弦", "洪", "缓"]], "19309": ["病机", "左右寸脉皆短，中取俱弦，按之洪缓有力。短主气郁，弦主风邪，洪缓有力示邪郁经脉、血气凝滞。原文据脉断“邪气在表”“不在里”，又云“凝于经络为疮痈”，说明此痈由八风之变、寒邪客于阳明经脉、血气凝滞而成，故归病机。", ["短", "弦", "洪", "缓"]], "19310": ["病机", "脉洪大而虚，重按全无，是血虚发热之典型脉象。洪大似实而重按无根，说明阴血亏虚、阳浮于外，故肌热躁热、目赤面红、烦渴引饮。原文引“脉虚血虚”，并以“脉不长实”与白虎汤证相辨，明言误服必死，脉象所主正是血虚发热之病机。", ["洪", "大", "虚"]], "19311": ["主病", "右寸脉弦急，右寸候肺与胸中，弦主气机郁滞、急主痛。气郁胸中则胸中痛、头痛，肺气不利则咽嗌不利，木郁克土则食减少。脉弦急与胸痛、咽不利、食少相应，说明气郁上焦、肺失宣降，故以脉主病。", ["弦", "急"]], "19312": ["主病", "右寸脉洪大，右寸候肺，洪大为气分热盛、痰湿壅盛之象。原文见两腿麻木沉重无力、多汗喜笑、口中涎、下身重如山、语声不出，乃湿浊内盛、肺气壅滞，故右寸脉洪大。湿性重浊故腿重如山，肺主气、声由肺出，肺气壅塞则语声不出，洪大之脉正应湿郁化热、气壅于上。", ["洪", "大"]], "19313": ["病机", "此段论湿与汗皆属阴，以西南坤土、脾胃为喻，谓汗多亡阳、阳去阴胜，甚则寒中。原文言湿胜则音声如从瓮中出，如居深瓮里，言其壅塞不出，明湿为阴寒之邪。虽见热中蒸蒸为汗，终传大寒，表虚不任外寒，多成痹寒。脉气候之，皆有形无形可见，强调湿邪由阳转阴、由热中传寒中的病机演变。", []], "19314": ["病机", "六脉俱弦甚、按之洪实有力，弦主风、主筋挛，洪实为内有实热。原文谓风寒始至加于身，四肢脾主，风寒伤之则搐急而挛痹，寒则筋挛；本人素饮酒，内有实热乘于肠胃，故大便秘涩、面赤热。外有风寒、内有实热，脉弦洪实正合外寒内热、筋脉拘急之病机。", ["弦", "洪", "实"]], "19315": ["主病", "两手寸脉短，右脉弦细兼涩，关脉虚。寸短主肺气不足，弦细涩为血少气滞、脾虚湿困，关虚主脾胃虚弱。原文见面黄、汗多、目赤、四肢沉重、减食、腹中时时痛、咳嗽，乃脾虚湿盛、气血不足、肺气不宣之候。弦细涩应气滞血少，关虚应中焦不足，与减食、腹痛、肢重相应。", ["短", "弦", "细", "涩"]], "19316": ["小儿", "此段述二岁小儿大寒证，未言脉而重望色：明堂青脉、额上青黑、脑后青络高起、舌上白滑、大便微青、耳尖冷、泪多眵多、胸中不利、卧而多惊。青黑主寒、主痛、主惊，白滑为寒湿，诸症皆寒邪内盛、阳气不伸之象。无搐则寒，说明寒邪郁闭、惊由寒扰，属小儿寒证之辨。", []], "19317": ["病机", "此段论癍疹始出之证，见面烧腮赤、目胞赤、呵欠烦闷、乍凉乍热、咳嗽嚏喷、足稍冷、多睡惊。原文归其因于太阳寒水起于右肾之下，煎熬左肾，膀胱寒水夹脊逆流上头下额，逆手太阳丙火不得传导，逆于面上。盖旺癸寒水克丙丁热火，诸癍皆从寒水逆流而作，阐明寒水逆流、火郁于上的病机。", []], "19318": ["主病", "心出小红癍，先见嗌干、惊悸、身热、肌肉肿，脉弦洪。弦主肝火、主惊，洪为心火炽盛。嗌干、身热、肌肿为热郁肌肉，惊悸为心火扰神。脉弦洪少加黄连，示心火与肝火并盛、热毒外发肌肤之病机，故以黄连清心泻火。", ["弦", "洪"]], "19319": ["主病", "小儿寒郁而喘，喉鸣、腹满、鼻流清涕，脉沉急而数。沉主里、主寒郁于内，急数示寒邪郁闭、气机急促，数非尽热，寒郁气逆亦可见。喉鸣为寒痰壅肺、气道不利，腹满为寒凝气滞，清涕为寒邪在表。脉沉急数与寒郁喘鸣相应，属寒邪闭肺、气逆痰壅之候。", ["沉", "急", "数"]], "19320": ["病机", "原文未出脉名，以“风邪伤人筋骨”“水谷之寒热害人六腑”分论外感内伤。风从上受，伤肝肾筋骨，为有余之证；饮食劳役伤脾胃，元气不足，湿从下受，冲脉之火逆上，为无形质元气受病。虽无脉象，然所论“筋骨疼痛”“脾胃之气不足”提示外感内伤之病机根本不同，为后文脉辨内外伤张本。", []], "19321": ["其他", "此段仅存“辨脉”二字，无具体脉象与文义可析。从标题看，当为讨论脉法辨别之总纲，但原文过简，无法确定所主病机或具体脉象要素，故脉象要素为空，类别归为其他，不作过度推断。", []], "19322": ["病机", "以人迎气口辨内外伤：人迎大于气口为外伤，气口大于人迎为内伤。外感寒邪则左寸人迎脉浮紧，按之洪大，紧甚于弦，为足太阳寒水之脉，内显洪大乃伤寒脉；外感风邪则人迎脉缓而大。内伤饮食则右寸气口脉大而数、急大而涩数，或损弱、沉滑。此以脉之浮紧洪大主外感有余，大数涩弱主内伤不足。", ["浮", "紧", "洪", "大"]], "19323": ["病机", "原文未出脉名，论内虚而伤者之躁热。因口吸风寒郁其阴火，冲脉之火拒吸入之气，致咽膈不通、口开目瞪、气塞欲绝；表虚无阳不任风寒，躁热间作而寒热不齐。此非外伤之寒热齐作无间断，乃内伤表虚、阴火乘之病机，躁作寒已、寒作躁已为其特征。", []], "19324": ["病机", "原文未出脉名，以渴与不渴辨外感内伤。外感风寒三日外邪传里始渴；内伤饮食劳役久病必不渴，邪在血脉中有余。若伤重初病而渴，乃心火炽上克肺金。虽渴欲冷饮，当徐徐少与，恐水多峻下伤胃气，致胀满传变、百脉不安、夜剧不卧。此论内伤病机及饮水宜忌。", []], "19325": ["病机", "饮食失节、劳役过度损伤脾胃，元气不足而心火独盛，阴火起于下焦乘其土位。症见气高而喘、身热而烦、头痛、渴不止、皮肤不任风寒，其脉洪大。阴火上冲则脉洪大、气高喘、烦热头痛渴；脾胃之气下流则谷气不升、无阳护荣卫而恶风寒。洪大之脉主阴火亢盛、脾胃气虚之病机。", ["洪", "大"]], "19326": ["治法", "脾胃虚而心火亢甚乘土位，肺气受邪。治用黄耆益皮毛闭腠理、人参补上喘气短、炙甘草泻火热补元气；脾胃急痛大虚、腹中急缩者多用甘草，取“急者缓之”。升麻柴胡引清气上升、补卫气散解、缓带脉之缩急。原文“脉之缩急”与腹中急缩、带脉缩急相应，示脾胃虚急之象，此段主在治法。", ["急", "缩"]], "19327": ["主病", "耳鸣、目黄、颊颔肿、颈肩臑肘臂外后廉痛、面赤、脉洪大，为风热邪气壅滞经络、火邪上炎之证。洪大脉主热盛邪实，与面赤、肿痛相应。治以羌活、防风、藁本通经血，黄芩、黄连消其肿，人参、黄耆益元气泻火邪，标本兼顾。此段以脉洪大统摄诸症，主风热肿痛之病。", ["洪", "大"]], "19328": ["主病", "脉洪大而面赤嗌痛颔肿，为热邪上攻、阳明火盛之象。洪大主热盛，热壅咽喉则嗌痛，热灼经络则颔肿，面赤亦为热蒸于上。原文以脉洪大与面赤并见，说明热势炽盛，故加黄芩、甘草、桔梗清上焦热、利咽消肿。", ["洪", "大"]], "19329": ["兼症", "心下痞而脉缓有痰，缓主湿痰内蕴，故加半夏、黄连化痰消痞；脉弦而四肢满、便难，弦主木郁克土、气机壅滞，故加柴胡、黄连、甘草疏肝和胃。原文以脉缓、脉弦分别提示痰湿与气郁之兼症，随脉加减用药。", ["缓", "弦"]], "19330": ["病机", "腹中痛而脉弦，弦为木旺，是木来克土，故用小建中汤酸泻肝木；脉沉细而腹痛，沉细主水寒，是水来侮土，故用理中汤辛热泻水；脉缓而体重节痛、腹胀自利，缓主湿胜，故用平胃散苦温燥湿。原文以弦、沉细、缓三脉分述木克土、水侮土、湿胜之病机。", ["弦", "沉", "细", "缓"]], "19331": ["病机", "脚膝痿软乏力或痛，乃肾肝伏热，故少加黄柏清下焦伏热；若脉缓而显沉困怠惰无力，缓主湿困，湿邪阻遏阳气则沉困怠惰，故加苍术、人参、泽泻、白术、茯苓、五味子健脾渗湿、益气敛阴。原文以脉缓辨湿胜困脾之机。", ["缓"]], "19332": ["病机", "长夏湿热大胜，人感之而四肢困倦、胸满气促、身热自汗等，其脉洪缓，洪为热盛，缓为湿滞；若湿气相搏则兼迟，迟主湿阻阳气。原文以洪缓、迟说明暑湿交蒸、湿热壅遏之病机，故用清暑益气汤清燥湿热。", ["洪", "缓", "迟"]], "19333": ["治法", "本段未出脉象，专论暑邪干卫、身热自汗之治法。暑热伤气耗津，故以黄耆、人参、甘草补中益气为君；湿胜则食不消而痞满，故用苍术、白术、泽泻渗湿，炒曲、青皮消食快气；又以黄柏泻热补水、五味子麦门冬救天暑伤金。全段以药测证，示暑湿伤气之治法。", []], "19334": ["病机", "脾胃虚弱之人，遇霖雨湿旺，汗多身重短气，脉散。散脉主气耗不收、元气浮散，湿助热邪更伤元气，故骨乏无力、神思朦朦如烟雾中。原文以脉散提示元气耗散、湿热伤气之机，故用生脉散补天真元气、泻热补水。", ["散"]], "19335": ["病机", "肌热燥热、困渴引饮、目赤面红，其脉洪大而虚、重按全无。洪大似热盛，然虚而重按无根，是血虚发热、阴血亏虚而阳气浮越，非实热白虎证。原文强调「脉不长实有辨耳」，以脉虚辨血虚发热，误服白虎汤必死，示脉象为辨证关键。", ["洪", "大", "虚"]], "19336": ["病机", "原文于黄耆方后注半夏「此一味脉涩者用」，涩脉主血少气滞、脉道不利。脾胃气虚则运化无力，血少难以充盈脉道，故脉涩。方中人参、白术、甘草补脾胃，半夏和胃，佐以风药升阳，正针对脾胃虚弱、脉涩之病机而设。", ["涩"]], "19337": ["病机", "原文言「脉弦，皆阳气衰弱，伏匿于阴中故耳」。脾胃久衰，阳气不能升发，反被阴寒所乘，伏匿于内，脉气紧张而见弦。此弦非少阳之弦，乃阳气衰弱、阴盛乘阳之象，故伴气短、精神不足、体重肢痛、泄泻、小便闭塞等症。", ["弦"]], "19338": ["误治", "本段未出脉象，专论内伤脾胃误用大热药（集香丸、巴豆）或大寒药（大黄、牵牛）攻下之害。热药重伤元气，寒药重泻其阳，致「皮肤筋骨肉血脉无所依倚，便为虚损之证」。虽无脉，然脉必随之虚损，示人误治可致真气衰败。", []], "19339": ["病机", "本段未出脉象，引仲景「谷入于胃，脉道乃行」，说明胃气为脉道运行之本。血不可不养，胃不可不温，血温胃和则荣卫通行。内伤饮食妄服食药，可轻生损命。脉之根本在胃气，故养胃即所以养脉。", []], "19340": ["病机", "原文引《内经》「内伤者，其气口脉反大于人迎，一倍二倍三倍，分经用药」。气口属太阴脾肺，内伤饮食则脾胃气滞，故气口脉反大于人迎，且以倍数分经之轻重。又言「上部有脉，下部无脉，其人当吐」，示食积上壅、气机不通之脉象。", ["大"]], "19341": ["治法", "本段未出具体脉象，而言「诊其脉候，伤在何脏，方可与对病之药」。强调据脉定位所伤之脏，再结合所伤食物寒热多少、禀气盛衰、是否强食等，斟酌用药，不可妄泄天真生气。脉候为辨证用药之依据。", []], "19342": ["主病", "原文「脉缓体重自利，乃湿气胜也」。缓脉主湿，湿性重浊，故体重；湿胜困脾，运化失职，故自利。脉缓与体重、自利并见，正是湿气偏胜之征，故用五苓散、平胃散加炒曲，名对金饮子，以燥湿利水、运脾止泻。", ["缓"]], "19343": ["主病", "原文「脉弦，恶寒腹痛，乃中气弱也」。中气虚弱，肝木乘脾，脉气紧张而弦；阳虚失于温煦，故恶寒；脾络不和，故腹痛。弦脉在此非实证，乃中气弱而木贼土之象，故用小建中汤加黄耆、异功散加芍药，温中补虚、缓急止痛。", ["弦"]], "19344": ["治法", "此段论饮食内伤分饮、食二类，饮为无形之气，伤则宜发汗利小便以分消其湿；食为有形之物，伤则宜损谷、消导、攻化，甚则吐下，以平为期。原文未及脉象，而强调“脾已伤，又以药伤”则营运之气减削，食愈难消，故治法当顾护脾胃，不可过用毒药。", []], "19345": ["治法", "此段为吐法应用之脉诊辨治总纲，指出须辨“上部有脉下部无脉”方可言吐。原文未出具体脉名，然以寸尺脉之有无判断病位上下、邪气壅塞与否，作为吐法宜忌之依据，体现因势利导、邪去正安之旨。", []], "19346": ["病机", "此段释“上部有脉，下部无脉”之机理：饮食过饱填塞胸中，胸中为太阴分野，气口脉反大于人迎三倍，为食伤太阴。食塞于上则气机壅遏，肝木生发之气被郁于下，故下部无脉，此即“木郁”。木郁则达之，故其人当吐，吐则气机得通，不吐则死。", []], "19347": ["误治", "此段言吐药使用禁忌：若两手尺脉绝无，则不可便用吐药，恐损元气，令人胃气不复。原文以“尺脉绝无”为禁吐之脉，因尺候下焦肾元，尺脉绝无提示下元虚衰，吐法更伤正气。若仅胸中窒塞闷乱，可先用指探等法，得吐则已，食不去方用此药。", []], "19348": ["病机", "此段进一步解释食填胸中而两尺脉不见之理：胸中为肺金之分，食为坤土之物，金土俱在于上而旺于天，金能克木，故肝木生发之气伏于地下，形成木郁。吐去上焦阴土之物，则木得舒畅，郁结自去。原文以五行生克阐发“上部有脉下部无脉”之病机。", []], "19349": ["病机", "此段以天地阴阳之道阐发食塞于上而脉绝于下之理：物者阴也，阴者水也，右三部脉主之，偏见于寸口。食塞其上，绝五脏之源，源绝则水不下流，故两尺竭绝。原文强调“独阳不生，独阴不长”，天地相根，上下交通，食塞上焦则升降阻绝，故下脉不见。", []], "19350": ["误治", "此段论针刺不知逆顺之害：虚证而反泻之，则经脉空虚，血气枯竭，肠胃㒤辟，皮肤薄著，毛腠夭焦，予之死期。原文以“经脉空虚”言误泻致虚之脉象，虚而泻之使气血耗竭，形气不相合，故预后不良。强调用针之要在于调阴与阳，使精气乃光，合形与气。", ["虚", "空"]], "19351": ["其他", "此段品评医工等级：上工平气，中工乱脉，下工绝气危生。原文以“乱脉”指中工未能平调气机，反致脉气紊乱。下工则绝气危生，故不可不慎。临证必审五脏变化之病、五脉之应、经络之虚实、皮肤之柔粗，而后取治，体现脉诊与整体辨证相结合之原则。", ["乱"]], "19352": ["治法", "原文论形气与病气盛衰以定补泻，非论脉象。形气不足而病气增加为邪胜，急当泻；潮作时精神困弱、语言无力为真气不足，急当补；形气与病气俱不足为阴阳俱不足，禁针宜甘药补，不可尽剂，不灸弗已取气海。全段以形气辨虚实，不从脉断。", []], "19353": ["主病", "刘守真病伤寒八日误下，症见头疼、呕恶不食，脉紧。误下伤正而寒邪未解，紧脉主寒主痛，寒束于表则头疼，寒犯胃腑则呕恶不食，故脉紧与头疼呕恶相应，示表寒未罢而里气已伤，非单纯可下之证。", ["紧"]], "19354": ["其他", "此段为篇目提纲，标举五脏六腑除心包络十一经脉证法，未出具体脉象与病机。其意在统摄诸脏腑经脉证治，为后文分述各经虚实寒热生死逆顺立目，故无脉可析，亦不主一病。", []], "19355": ["治法", "原文强调五脏六腑虚实寒热、生死逆顺皆见形证脉气，非诊切无由识，故以虚补实泻、寒温热凉、不虚不实以经调之为良医大法。此段总论凭脉辨证以定治法，脉气为识证之要，未列具体脉象，主旨不在主病。", []], "19356": ["其他", "此段标举肝经提纲：肝脉本部在于筋，足厥阴属风乙木。原文只明肝脉诊位在筋、其性属风木，为下文论肝脉弦长平脉及太过不及诸脉立基，未出具体脉象与病机，故不主一病。", []], "19357": ["病机", "原文以脉弦长曰平，实而弦为太过病在外，令人忘忽眩运；虚而微为不及病在内，胸胁胀满。又沉而急主胁支满、小便难、头痛眼眩；急甚主恶言。弦长为肝之平脉，实弦则肝气太过，沉急则肝气逆，诸脉皆从肝木太过不及立论。", ["弦", "长", "实", "沉"]], "19358": ["主病", "原文言胆病善太息、口苦、吐宿汁、心中戚戚恐如人将捕之，脉在左关上浮而得之者是其部。左关浮取属胆，阳微者胆虚，阳数者胆实。浮脉应胆之表部，微数分虚实，与胆虚恐畏、胆实惊悸精神不守相应。", ["浮", "微", "数"]], "19359": ["平脉", "原文以持脉指法按至筋平，脉道如筝弦者为弦，脉道迢迢者为长，此弦长乃肝家不病之状。肝合筋，脉本部在筋，弦长应春木生发之性，故为平脉；若出筋上见于皮肤血脉，则非其常部，示病脉之变。", ["弦", "长"]], "19360": ["病机", "原文仅述心之经属手少阴君火，心脉本部在于血，未出具体脉象。其意在心主血脉，脉以血为本，故诊心脉当察血之盛衰与火之亢抑。此段为总纲，提示心脉病机多从血分与火化立论，与后文钩脉太过不及相呼应。", []], "19361": ["主病", "夏脉钩来盛去衰为平，来盛去亦盛为太过病在外，令人身热骨痛口疮舌焦；来衰去亦衰为不足病在内，令人烦躁咳唾气泄。脉如循琅玕连珠曰平，啄啄连属微曲曰病，前曲后倨如操带钩曰死。所列脉大、沉小而紧、急甚、坚搏而长、浮大、浮紧而大、左寸口与人迎实大，皆示心火亢盛或邪搏血脉之变。", ["大", "沉", "紧", "急"]], "19362": ["病机", "小肠与心为表里，脉浮而微，浮主表属小肠，微为阳气不足。原文言小肠实则伤热生口疮，虚则伤寒泄脓血黑水，寒则下肿重，积则夕热旦止，胀则小腹䐜胀引腰痛厥。浮微之脉正合小肠虚寒、气化不行之机，故见泄脓血、便难、咽痛颔肿等候。", ["浮", "微"]], "19363": ["平脉", "此段述持脉指法：轻手得之属小肠表，重手得之属心里。按至血脉而得者为浮，稍加力脉道粗大者为大，又稍加力脉道润软者为散。浮大而散为心家不病脉之状，因心合血脉，脉循血脉而行，故其常脉见于血脉之分，浮大而散乃心血充盈、火气冲和之象。", ["浮", "大", "散"]], "19364": ["病机", "原文仅言脾之经属足太阴湿土，脾脉本在肌肉，未出具体脉象。其旨在于脾主肌肉，脉以肌肉为分部，诊脾脉当于肌肉之间求之。此段为总纲，提示脾病脉机多从湿土运化、肌肉缓急立论，与后文缓大之平脉及太过不及相呼应。", []], "19365": ["主病", "脾脉来似流水曰太过病在外，令人四肢沉重言语謇涩；如鸟距曰不及病在内，令人中满不食乏力手足缓弱。和柔如鸡践地为平。所列急甚、大而虚、微缓而长、阿阿然缓、浮大而缓，示脾病有实有虚：急甚为土气亢急，大而虚为中虚气浮，微缓而长为脾胃和缓之象。", ["急", "大", "虚", "缓"]], "19366": ["病机", "胃为水谷之海，人之根本。脉搏坚而长，坚长为胃气实、邪热内搏，故见中胀便难、肢节痛、呕逆不食，甚则登高而歌弃衣而走。脉弱而散，弱散为胃气虚弱，故见肠鸣胀满滑泄、四肢肿满短气、谷不化。坚长主实热，弱散主虚寒，皆胃气失常之候。", ["坚", "长", "弱", "散"]], "19367": ["平脉", "此段述右关脾胃持脉指法：轻手得之属胃表，重手得之属脾里。按至肌肉，脉道如微风轻扬柳梢者为缓，稍加力脉道敦实者为大，缓大为脾家不病脉之状。脾合肌肉，脉循肌肉而行，缓则土气和柔，大则中气敦厚，故缓大乃脾胃健运之常象。", ["缓", "大"]], "19368": ["主病", "本段述心主脉所生病，见手心热、肘臂挛急、腋肿、胸胁支满、心中憺憺大动、面赤、喜笑不休等。原文未出脉名，然『心中憺憺大动』为心脉受病、神气不宁之征，『胸胁支满』示经气壅滞。诸症皆属心与心包络脉所过及所主，故列为主病，治法与小肠同，取表里经相应之意。", []], "19369": ["病机", "本段论三焦为三元之气、中清之腑，总领脏腑荣卫，主通阴阳、调虚实。原文未及脉象，而述其病则腹胀气满、小腹坚、溺不得、大便窘迫，『溢则作水，留则』示水道不利。此以三焦气化失司为病机核心，故归病机，非专论某脉所主。", []], "19370": ["主病", "本段先述三焦是动病耳聋、嗌肿喉痹，所生病汗出、目锐眦痛、颊痛、肩臑肘臂外痛、小指次指不用；后引《脉诀》言右尺轻手得之为三焦属表、重手得之为命门属里，并列上中下焦热及气血分热之治法方药。虽涉脉位分部，主旨仍在三焦病证与用药，故归主病。", []], "19371": ["其他", "本段仅标肺之经、手太阴、燥辛金及脉本部在于皮毛，属脏腑经络分属之提纲，未出具体脉象与病候。原文无脉形可录，亦无病机推论，故脉象要素为空，类别归其他，以存其经属本部之说。", []], "19372": ["平脉", "本段论肺脉平、太过、不及。『脉浮而毛曰平』『浮而短涩者，肺脉也』，浮毛短涩应秋金轻虚之象，故为平脉；『毛而中央坚，两头虚』为太过，令人气逆胸满背痛；不及则喘咳上气见血。以脉形坚虚辨肺气之强弱，紧扣原文脉象描述。", ["浮", "毛", "涩", "短"]], "19373": ["主病", "本段论大肠为肺之腑、传道之司，寒则泄、热则结、绝则利下不止而死，热极便血、风中下血、实热胀满不通、虚寒滑泄，及积冷当脐痛、泄白物等。原文未出脉名，以寒热虚实统括大肠病证，末言『生死逆顺脉证之法』，主旨仍在大肠主病。", []], "19374": ["平脉", "本段述大肠是动病齿痛颈肿及津液所生病，末引《脉诀》言右寸轻手得之属大肠、重手得之属肺，并以三菽之重按至皮毛得浮、稍加力脉道不利为涩、再稍加力缩入关中为短，明『浮涩而短，肺不病之状』，故归平脉，示肺脉本部之常。", ["浮", "涩", "短"]], "19375": ["其他", "本段仅标肾之经、命门、足少阴、寒癸水及脉本部所在，属脏腑经络分属提纲，未出脉形与病候。原文无脉象可录，亦无病机可推，故脉象要素为空，类别归其他，以存肾与命门经属本部之说。", []], "19376": ["主病", "原文以肾脉沉滑为平，反此则病。脉来如弹石为太过，病在外，令人解㑊脊痛少气；去如解索为不及，病在内，令人心悬、小腹满、小便滑。又喘喘累累如钩按之紧为平，如引葛按之益坚为病，如转索辟辟如弹石为死。肾有水则腹胀脐肿、腰重痛、不得溺，皆沉滑失平、水气太过之候。", ["沉", "滑", "紧", "细"]], "19377": ["病机", "本段论膀胱为津液之府，与肾表里，总通五腑。伤热则小便不利、黄涩，因热入膀胱气急；膀胱寒则小便数而清白。水发根在膀胱，四肢瘦小而腹反大，是水气偏聚。膀胱咳久传三焦，满而不欲食。上焦主心肺，有热食不入，寒则神不守、泄利不止、语声不出，皆脏腑寒热影响津液气化之病机。", []], "19378": ["平脉", "原文列膀胱足太阳是动病，冲头痛、目似脱、项似拔、脊痛腰似折等，主筋所生病。又述脉法：左尺轻手得之属膀胱表，重手得之属肾里；命门与肾脉循骨而行，按至骨上得之为沉，重按脉道无力为濡，举手来疾流利为滑。此沉濡而滑，乃命门与肾脉不病之状，示平脉指法。", ["沉", "濡", "滑"]], "19379": ["病机", "二之气多发风湿风热。经曰风伤于阳、湿伤于阴，微则头痛身热，发作风湿之候，风伤血、湿伤胃气。风湿为病，阴阳俱虚而脉浮，汗出身重、眠多鼻息、语言难出。脉浮为风湿伤阳、邪在表之征，故不宜热药，下之必死，宜桂枝麻黄汤发汗。", ["浮"]], "19380": ["平脉", "小满至大暑为三之气，少阳相火之位，阳气发万物俱盛，故云太阳旺。其脉洪大而长，乃天气并万物、人脉亦盛之应。洪大而长示阳气外盛、火令当权，非病脉，属四时平脉，与万物蕃茂相应。", ["洪", "大", "长"]], "19381": ["平脉", "大暑至秋分为四之气，太阴湿土之位，阳气发散之后阴已用事，故太阴旺。脉缓大而长，为燥金旺之应；紧细短涩，则因万物干燥而显。缓大而长示湿土当令、脉象从容，紧细短涩示燥金偏胜，二者对举以明四时脉随气变。", ["缓", "大", "长", "紧"]], "19382": ["平脉", "秋分至小雪为五之气，阳明燥金之位，阳衰阴盛，故曰金气旺。其脉细而微，乃阳气衰减、阴气用事之应。细而微示气血内敛、燥金收敛之象，属秋令平脉，与阳衰阴盛之气相应。", ["细", "微"]], "19383": ["平脉", "小雪至大寒为终之气，太阳寒水之位，阴极而尽，天气所收，故曰厥阴旺。其脉沉短而微，因万物收藏在内，寒气闭塞肤腠，气液不能越，故脉微也。沉短微示阳气潜藏、寒水闭藏之象，属冬令平脉，与阴极气收相应。", ["沉", "短", "微"]], "19384": ["主病", "原文以“脉细而微者，寒证也”点明脉象主寒。细为阳虚阴盛，微为阳气衰微，脉道不充，故主里寒之泻痢。症见完谷不化、色不变、吐利腥秽、澄澈清冷、小便清白不涩、身凉不渴，皆一派寒象，与脉细而微相应，故断为寒证。", ["细", "微"]], "19385": ["治法", "原文以“脉浮在表，当汗之；脉沉在里，当下之”为纲，浮脉主邪在肌表，故宜汗法解表；沉脉主邪入于里，故宜下法攻里。此以脉之浮沉定病位表里，从而确立汗下治法，并据搐搦部位分经用药，体现脉象指导治则。", ["浮", "沉"]], "19386": ["病机", "原文言破伤中风“风热燥甚，怫郁在表，而里气尚平”，症见善伸数欠、筋脉拘急、恶寒而搐，脉浮数而弦。浮主病在表，数主热，弦主风主筋急，三脉合见，说明风热郁表、荣卫不得宣通之病机，故治以辛热开冲结滞，使荣卫宣通而愈。", ["浮", "数", "弦"]], "19387": ["治法", "原文以“脉浮者为在表，宜行经”与“脉沉者在里，当疏利脏腑”对举，浮脉主邪在表，故用行经药引至疮所；沉脉主邪在里，故当疏利脏腑，利后加大黄取利。此以脉之浮沉分表里，而定行经、疏利之治法，随虚实定分两。", ["浮", "沉"]], "19388": ["主病", "原文驳“带下皆寒”之误，指出带下为任脉之病，症见头目昏眩、口苦舌干、嗌咽不利、小便赤涩、大便涩滞，脉实而数者，皆热证也。实脉主邪盛，数脉主热，实而数乃实热内蕴之象，故主热证带下，与赤白痢义同而无独寒者。", ["实", "数"]], "19389": ["病机", "原文注云“喘，热则息数气粗而为喘也，故热则脉实而甚数，喘之象也”。实脉主邪气盛，数脉主热，实而甚数说明热邪壅盛、气粗息数，故为喘之脉象。此以脉实甚数揭示热盛致喘的病机，脉象与喘症相应。", ["实", "数"]], "19390": ["病机", "原文以“寒者，脉当沉细而迟；热者，脉当实大而数”辨吐利之寒热。沉细而迟为寒，实大而数为热。又言“损气亡液过极，则脉亦不能实数，而反缓弱也”，说明津液耗伤过极可致脉由实数转为缓弱，然此缓弱非热，乃亡液所致，故“虽尔，亦不为热矣”。", ["沉", "细", "迟", "实"]], "19391": ["病机", "原文论湿为留饮、痞隔，传化失常，甚则霍乱吐泻。又辨利色青、黄、红、黑之属热属寒，指出“利色青为寒者，误也”，引仲景少阴病下利清水色纯青为热在里，及小儿热甚急惊利色多青为热明矣。脉迟细而微者，乃湿邪内留、阳气不运之象，非独寒也。", ["迟", "细", "微"]], "19392": ["病机", "原文言耳鸣由“水虚火实，热气上甚”所致，脉气微甚决定耳中声响强弱，故脉象非具体脉名，而是脉气盛衰。病机为肾水虚、心火实，热客耳之经络，冲于耳中鼓动听户。主耳鸣，与肾虚火旺证相应。", []], "19393": ["病机", "原文以“火主动”释夏热脉洪大而长，并联系“惕跳动”“𥆧瘈之象”。洪大而长乃火热亢盛、气血涌盛之象，主夏月热盛，与肌肉瞤动、瘈疭等热极生风之症相应。", ["洪", "大", "长"]], "19394": ["病机", "原文以“湿润则滑泽，干燥则涩滞”释涩脉，谓“水液衰少而燥涩，气行壅滞”故脉涩，或见麻。涩主燥金之化，津液亏少、气行不畅，与遍身中外涩滞、肌肤麻木相应。", ["涩"]], "19395": ["病机", "原文以燥金“紧敛”释秋脉紧细而微，以湿土“纵缓”释六月脉缓大而长。紧细而微主燥金收敛、津液干燥，缓大而长主湿土纵缓。二者对举，说明燥湿异用，与皮肤皴揭、启裂相应。", ["紧", "细", "微", "缓"]], "19396": ["病机", "原文言“筋脉劲急”由风病过极反燥、兼金化制之所致，脉劲急为风燥亢极、筋脉失柔之象。主腹中坚硬如症、筋脉拘急，体现“亢则害，承乃制”之病机。", ["劲", "急"]], "19397": ["病机", "原文论瘕“忽聚忽散，无有常准”，由血不流而寒薄、血内凝或小肠移热于大肠、血涩不利所致。未出脉名，但强调“宜以脉证别之”，示瘕有寒热血涩之异，与月事沉滞、腹中积块相应。", []], "19398": ["病机", "原文释㿗疝“小腹连卵肿急绞痛”为寒主拘缩，脉急者寒之象，寒则脉当短小而迟；紧脉主痛，急为病甚。痛则心神不宁而脉紧急，故脉紧急主寒痛，与阴器连小腹急痛相应。", ["急", "短", "小", "迟"]], "19399": ["病机", "原文言寒主拘缩故急痛，寒极则血脉凝冱，兼土化制之故坚痞腹痛；或热郁于内亦腹满坚结痛。未出脉名，但强调“当以脉别之”，示腹痛坚痞有寒凝与热郁之别，须凭脉辨其寒热。", []], "19400": ["病机", "原文未出具体脉名，但强调“二证以脉别之自见”，即胃热消谷与邪热不杀谷之辨当凭脉。胃热则消谷善饥，脉多洪数有力；若阳热太甚而郁结、传化失常，虽不食亦不饥，脉亦当见数实或沉滞。文中“腹热胀满”“燥热”点明热郁气机，故脉象是区分寒热虚实的关键，不可仅凭不食一症断为寒。", []], "19401": ["病机", "原文以“冬脉沉短以敦”喻寒象，阴厥者“脉迟细而微”，属阴证，身凉不渴；阳厥者“脉数”，属阳证，热极反厥而烦渴谵妄。脉迟细微为阴寒内盛、阳气衰微之候，故主阴厥；脉数则为阳热郁极。若阳厥极深反见阴脉欲绝，是热极欲死之危候，强调阴阳以平为和、以偏为病。", ["沉", "迟", "细", "微"]], "19402": ["治法", "原文未出脉名，列风热郁结、气血蕴滞所致筋脉拘挛、手足麻痹、头痛昏眩、肠胃燥热、便溺淋闭等症，甚则阳极似阴而寒战烦渴。其病机为风热怫郁、气血壅滞，治当退风散热、行经和血、开发腠理，使荣卫调和、郁结得散，故属治法条文。", []], "19403": ["治法", "原文未出脉名，提出治风二法：“行经和血”治经脉凝滞于内，“开发腠理”治皮肤郁结于外。经脉凝滞则血不顺，皮肤郁结则荣卫不和，故用发散之药使内外通调。此段专论风热郁结之治法，强调内行经血、外开腠理，非凭脉断病。", []], "19404": ["主病", "原文以“筋脉挛急”为脉象写法，实指筋脉拘急之症，非独立脉名。诸风所致手足軃曳、口眼㖞斜、语言謇涩、痰涎壅盛、肌肉顽痹等，皆风痰阻络、筋脉失养之候。脉挛急反映风邪内动、筋脉拘急，故主诸风新久、痰涎壅盛、经络不通之病。", ["急"]], "19405": ["主病", "原文未出脉名，列身热呕吐泄泻、肠癖下利、癃闭淋痛、腹胀痛、痫痓惊悸、口疮齿疳等症，并称“大养脾胃肾之气”“补五劳七伤”。其主旨为通利九窍六腑、消水谷、和血气、解邪毒，属主病兼补益之方，非以脉象立论。", []], "19406": ["主病", "原文列“脉沉而可下者”“脉数沉实”，主阳明胃热、腹满咽干、烦渴谵妄、大便结滞，热郁可下；又“脉反沉细欲绝”“脉微而绝”，为阳热暴甚、肾水阴虚而僵仆卒中，热极反见阴脉之危候。沉数实主里热壅结，沉细欲绝主热极伤阴、阳气欲脱，故当脉证合参。", ["沉", "数", "实", "细"]], "19407": ["治法", "原文以“脉涩”辨大便不通之因：“血涩而大便燥者”加桃仁、大黄；“觉身有气涩而大便不通者”加郁李仁、大黄以除气涩。脉涩主血少津枯或气机涩滞，故血涩者润燥活血，气涩者行气通便。此段凭脉涩分气血论治，属治法条文。", ["涩"]], "19408": ["主病", "原文列大寒积冷、脏腑虚寒诸症，而归结于“神昏脉短”。脉短者，气血不足、阳气暴衰，脉道不能充盈，故短而无力。阴寒独盛，阳气不能外达，故手足厥冷、神昏、四肢怠惰；寒凝气滞则心腹疼痛、胸胁胀满、泄泻肠鸣、米谷不化。脉短正合阳虚阴盛、正气衰微之病机。", ["短"]], "19409": ["主病", "原文言阴证伤寒，自利不渴、呕哕、手足厥冷、下利清谷，而“脉微欲绝”。微为阳气衰微，欲绝则阳将脱，脉道鼓动无力。阴寒内盛，阳气不能温煦，故厥冷、腹痛胀满；不能运化，故下利清谷、吐利俱作。此脉此症，正示助阳救衰之治所本。", ["微"]], "19410": ["兼症", "此段为方药加减法，非论脉象。原文“筋脉挛急，加木瓜半两”，是言兼症用药，非以脉断病。筋脉挛急属筋失濡养、拘急不舒，故加木瓜舒筋活络。全段主旨在于随兼症加减，脉象无涉，故脉象要素为空。", []], "19411": ["病机", "此段论荣卫化生之源，非辨脉之文。原文“水入于经，其血乃成；谷入于胃，脉道乃行”，说明水谷入胃，化生荣卫，脉道乃得充盈而行。又言“安谷则昌，绝谷则亡”，强调胃气为本。荣散卫亡则神无所居，故血不可不养，卫不可不温，血温卫和则荣卫乃行。", []], "19412": ["治法", "此段论用方之法，非论具体脉象。原文“当体指下脉气，从而加减”，强调后人用前人方，须验脉处方，随脉气变化而加减。又言五行相制相兼、变乱无常，故须“验脉处方”。全段主旨在于凭脉用药、灵活加减，属治法范畴，未及具体脉象。", []], "19413": ["病机", "原文“阳脉涩，阴脉弦，法当腹中急痛”，阳脉涩为营血不足、脉道不充，阴脉弦为里急、筋脉拘急。涩弦并见，示中焦虚寒、营卫不和，故腹中急痛，制小建中汤以温中补虚、缓急止痛。此段以脉涩弦明里虚急痛之病机，与桂枝汤治表虚相对。", ["涩", "弦"]], "19414": ["其他", "此段论药根梢分用，非论脉象。原文“气脉上行，以生苗者为根；气脉下行，入土者为梢”，以气脉升降说明根升梢降之理，进而言病在中焦用身、上焦用根、下焦用梢。全段主旨在于药部位与病位相应，属用药法度，未涉及具体脉象。", []], "19415": ["其他", "此段述荆芥性味功用，非论脉象。原文“辟邪毒，利血脉，宣通五脏不足气”，言荆芥气温味辛苦，能发汗、通关节、利血脉。全段主旨在于药物主治与用法，未及脉象，故脉象要素为空，归入其他类。", []], "19416": ["病机", "原文述干姜“治沉寒痼冷，肾中无阳，脉气欲绝”，脉气欲绝指阳气衰微、脉道不充，故主沉寒痼冷、肾阳衰败之病机。干姜大辛大热，能通心气助阳、去脏腑沉寒，正针对此阳衰寒盛之机。", []], "19417": ["主病", "原文言黄耆“治虚劳自汗，补肺气，实皮毛，泻肺中火，脉弦、自汗”。脉弦在此与自汗并见，属虚劳肺气不足、卫外不固，虚火内扰之象；弦为气机不和，亦主虚劳里急。黄耆甘温补虚，实皮毛，故主此证。", ["弦"]], "19418": ["主病", "原文述京三棱“主心膈痛，饮食不消，破气，治老癖症瘕结块，妇人血脉不调，心腹刺痛”。此虽未出脉，然所主皆气滞血瘀、积块内结之病机，故以破气消积、通血脉为治，虚人不用，恐损真气。", []], "19419": ["主病", "原文述阿胶“主心腹疼痛，血崩，补虚安胎，坚筋骨，和血脉，益气止痢”。所主病机为阴血亏虚、血脉不和，故见疼痛、崩漏、胎动不安；阿胶甘平微温，补血滋阴，故能安胎坚骨、和脉止痢。", []], "19420": ["治法", "原文以白芍药“补中焦之药，炙甘草为辅，治腹中痛”，并随寒热加减。所论为腹痛之治法，其病机属中焦虚寒或寒热错杂、营血不和，故用芍药甘草汤酸甘化阴、缓急止痛，随证加桂、芩以调寒热。", []], "19421": ["病机", "原文言麦门冬“治肺中伏火，脉气欲绝”，以生脉散补肺中元气不足。脉气欲绝乃肺之气阴两伤、脉道失充之象，伏火内灼则气耗，故脉微欲绝；麦冬甘寒清润，配人参、五味子益气生脉，针对气阴两虚之机。", ["散"]], "19422": ["主病", "原文治“劳瘵羸弱已甚，饮食减少，喘促咳嗽，身热脉虚数者”。脉虚数为阴血亏虚、虚火内扰之象，劳瘵日久，气阴耗伤，故见羸弱、喘咳、身热；虚数之脉正主虚劳内热之病机，亦治女子血枯不月。", ["虚", "数"]], "19423": ["其他", "原文引《脉要精微论》“头者精明之府”，论思由心脑相辅而成，非脉诊病机之论。所引“脉要精微论”仅为篇名，非言脉象，故脉象要素为空，主旨属理论阐发，归为其他。", []], "19424": ["主病", "脉甚虚数，虚为气阴亏耗，数为虚热内扰。劳瘵日久，月信不见、羸弱不起，显系阴血亏虚、元气不足，虚热内生故脉数而无力。此脉象与劳瘵主证相应，提示病本在虚，热为标象，故用资生汤补虚退热而愈。", ["虚", "数"]], "19425": ["病机", "左部弦细，右部微弱，数近六至。弦细为阴血亏虚、肝木失养，微弱为肺脾气弱。咳嗽吐痰腥臭、喘促自汗、午后发热，乃痨瘵兼肺病，子虚及母。脉象示气阴两虚、虚热内炽，故以资生汤加减补脾肺、滋肾阴而取效。", ["弦", "细", "微", "弱"]], "19426": ["主病", "虚劳脉见弦、数、细、微，弦为肝郁或虚风，数为虚热，细为阴血不足，微为阳气衰微。肌肤甲错、形体羸瘦、自汗咳逆、寒热不时，皆气血虚滞、阴阳两亏之候。此脉象反映虚劳病机复杂，正虚与瘀滞并存，故见多端症候。", ["弦", "数", "细", "微"]], "19427": ["病机", "先冷后热而汗出，脉兼微弱不起，系胸中大气下陷。微弱为阳气虚陷、鼓动无力，大气不升则营卫失和，故寒热汗出。此脉象提示气分虚甚，非单纯阴虚，治当升补大气，与劳瘵破血之法不同，需细辨。", ["微", "弱"]], "19428": ["预后", "脉散乱欲脱、阳浮而阴不应、数至七八至，皆为阴竭阳越、元气将脱之险候。散乱为根本离决，浮为虚阳外越，数为虚热亢盛而无根。劳瘵至此，阴虚发热之常法已难挽回，故原文列为险证，提示预后不良。", ["散", "乱", "浮", "数"]], "19429": ["治法", "脉数几至八至，前医以阴虚治之不效。此数非尽属阴虚，乃元气虚极、气化无力而代偿为数。重用黄耆温升补气、知母寒润滋阴，使阳升阴应，脉数渐缓。原文引脉法“数至七八至为不治”而验之非确论，示脉数当辨气虚与阴虚。", ["数"]], "19430": ["其他", "本段未识脉名，专论肾气丸方义。地黄逐血痹、桂枝调营卫、山萸肉逐痹、丹皮破血、附子温通血脉，共成逐血痹之功。虚劳腰疼若属瘀血痹阻者，此方有效；若纯虚而无瘀，则非所宜。强调方证相应，不可拘泥古方。", []], "19431": ["病机", "脉数之证，世俗多责阴虚血涸，然元气虚极莫支者脉可至极数。力作奔驰气力不支时脉必数，同理气虚不能支持亦致数。理气药多于补气药则脉加数，补气药多于理气药则脉渐缓，知脉数不数兼视气分强弱，非独血分盈亏。", ["数"]], "19432": ["兼症", "脉弦而浮数，弦主肝郁，浮数为有热。患者寒热往来、午后先寒后热、微咳无痰、日夜作泻、黎明头汗、胸间绵绵作疼、食后胀满，显系肝郁乘脾、郁而化热之象。脉弦应肝，浮数应热，与寒热、咳、泻、胀满诸症相应，故立逍遥散方疏肝解郁。", ["弦", "浮", "数"]], "19433": ["主病", "脉数而弱，数为有热，弱为气阴不足。虚劳发热，或喘或嗽，乃阴虚内热、气耗液伤之候。数脉主热，弱脉主虚，数而弱并见，说明虚热内扰而正气已损，与虚劳喘嗽之症相应，故以此脉定虚劳发热之病机。", ["数", "弱"]], "19434": ["病机", "原文谓「脉数者必是脾阴受伤」，又言「脾脉原主和缓」，脉数则失和缓之常。劳热之证责之阴虚，肺阴虚则咳喘，肾阴虚则不纳气。脉甚数者，乃脾阴受伤，滋阴药中加甘草引之归脾，兼用薏米、石斛淡味之品，以滋脾阴。", ["数", "缓"]], "19435": ["预后", "年少妇人经闭，寒热干嗽喘逆，胸满不食，脉数几至七至，为阴虚火旺、血枯成劳之候。服赭石易丹参方后，咳喘愈半，胸开能食，数剂后脉亦和缓，诸病皆愈。脉由数急转为和缓，示阴复火降、胃气渐和，故为向愈之兆。", ["数", "缓"]], "19436": ["病机", "脉微弱异常，为胸中大气下陷之征。患者泄泻半载方愈，又因劳力过度，觉喉中气不舒，时咳一两声气始舒，四肢无力，饮食懒进。大气一陷，包举无力，肺失附丽则咳，鼓舞机滞则喘，脉微弱正合气虚下陷之机，故投升陷汤而愈。", ["微", "弱"]], "19437": ["病机", "脉数近六至兼沉濡，初疑阴虚不纳气，然沉濡之象示大气下陷。患者努力任重而喘发，背恶寒发紧，皆大气下陷之征。沉濡为气陷不升、脉道不充之象，数则因虚而躁。故不用降气，改投升陷汤加减，以升举大气为治。", ["数", "沉", "濡"]], "19438": ["预后", "脉数八至，按之即无，形羸弱，虚劳咳嗽，呕吐不食，寝食俱废，精神恍惚。脉数八至为危候，然询知病起新证，非久病虚损，故断为可治。投醴泉饮加减，吐止食进，三日后脉数亦见愈，犹六至余，示邪热渐退而胃气未复，脉象由危转安。", ["数"]], "19439": ["预后", "脉数六至，虽细弱仍有根柢，知可治。劳嗽二年，动则喘，食少羸弱，上焦发热，便燥。数主热，细弱主气阴两虚，有根柢则胃气未绝。投醴泉饮加减，数剂后食增便调，数日热退脉复常，惟咳嗽未已，示脉数渐退为向愈之机。", ["数", "细", "弱"]], "19440": ["预后", "脉散乱如水上浮麻，不分至数，是元气将脱、阴阳离决之候。散乱脉主正气涣散，浮麻无根，故断为“将脱”。原文述温病痰喘，黎明喘大作而见此脉，正是肺肾气竭、根本动摇之象，故急用山药煮汁以敛固元气，脉稍敛乃可容取药。", ["散", "乱"]], "19441": ["主病", "产后大喘大汗、身热劳嗽，脉甚虚弱而数至七至，是气阴两脱、虚阳外浮之候。虚数无力，主正气大虚；数至七至为虚热逼迫。前医误用黄耆、熟地、白芍，汗出愈多，更伤阴液。故用生山药大剂煮汁，补脾肺、固气阴，使虚数之脉渐复。", ["虚", "弱", "数"]], "19442": ["病机", "温病十余日，外感之火已消，而大便滑下、喘息迫促、烦渴，脉甚虚，两尺微按即无，是脾肾气阴下脱、根本空虚之候。尺脉无根，主肾气不固；虚而滑泻，主脾失统摄。故用生山药煎汁代茶，补脾固肾、敛气生津，使喘渴与滑泻皆愈。", ["虚"]], "19443": ["治法", "此段论肺肾相传及累及脾胃之治法，分肾传肺、肺传肾、肺肾俱病累及脾胃数种，分别以滋真阴、清肺理痰、肺肾双补兼顾脾胃为治。原文言“脉之稍有根柢可挽回者”，强调脉有根柢为可治之凭，兼服阿斯匹林以助透达，需以时日而愈。", []], "19444": ["治法", "劳瘵阴虚之证，脉急数者，主阴虚火旺、虚热内扰。急数为热象，阴亏不能制火，故脉来急迫而数。于滋补剂外兼服阿斯匹林微汗，使虚热从表透解，旬日之间“脉之数者可渐和缓”，是阴液渐复、虚火渐平之征。", ["数", "急"]], "19445": ["病机", "少年枵腹力作，劳嗽发热，咳吐痰涎，脉虚数兼弦。虚数主气阴两伤，弦为肝脉。因脾土受伤不能濡养四脏，肺金受伤不能镇肝，故肝木恣横而脉弦。原文断为“肺脾皆有伤损”，正合虚数兼弦之象，故用补脾肺之方而愈。", ["虚", "数", "弦"]], "19446": ["病机", "此段释脉弦主脾肺伤损之理。左右脉皆弦，弦为肝脉，肝盛侮脾；脉不和缓而弦硬，是脾气受伤、不能包括四脏；肺金受伤，不能镇肝，故脉现弦象。原文以“和缓为贵”为平脉之常，弦硬为病脉，说明弦象反映肝横、脾伤、肺弱之病机。", ["弦", "硬"]], "19447": ["病机", "素有喘证，复发无外感，脉五至余，右寸浮大，重按即无。右寸主肺，浮大无根，是肺肾伤损、气不归元之候。前服小青龙取效于外感，今无外感而发，知病本在肺肾。浮大重按即无，正虚阳浮越、根本空虚之象，故治当补肺肾之本。", ["浮", "大"]], "19448": ["病机", "脉上盛下虚，两寸摇摇、两尺欲无，数至七至，乃下焦元气虚极不能固摄，虚阳上浮之象。寸摇为阳气浮越无根，尺无则肾元将竭，数至七至是虚阳躁动。故见大便滑泻、头面汗出如洗、精神颓愦昏睡，属元气欲脱之危候，非实热可攻。", ["数", "虚"]], "19449": ["病机", "左脉微细模糊、按之即无，是肝胆虚极、元气欲脱之征。微细为气血衰微，按之即无则根本已空。肝胆虚则寒热往来，故见忽热忽汗、汗出如洗；目上窜不露黑睛为虚风内动、元气上脱。此非外邪未尽，乃正虚欲脱之危象。", ["微", "细"]], "19450": ["病机", "脉浮而弱、不任循按，继则微弱益甚，是劳病日久、元气虚浮无根之象。浮为虚阳外越，弱微为正气衰微。痰喘甚剧而脉弱，说明喘由虚作，非实邪壅肺。故服小青龙后脉更微弱，呼吸俱微、气息不续，属元气欲脱，急宜补敛固脱。", ["浮", "弱", "微"]], "19451": ["预后", "尺部无根、寸部摇摇有将脱之势，是肾元亏虚、虚阳上浮之危脉。尺无根则下焦不固，寸摇摇则阳气欲脱。虽自言病愈，实为元气暴脱前兆，故后二日骤然眩晕、周身颤动、汗出、言语错乱、怔忡，脉上盛下虚益甚，证实前诊预后之危。", ["虚"]], "19452": ["病机", "产后角弓反张、汗出如珠，六脉散乱无根，有将脱之象。散乱无根是气血耗散、元气不能维系之征。产后阴血骤虚，虚风内动则角弓反张；汗出如珠为阳气外泄。脉证合参，属元气欲脱、虚风鸱张之危候，急宜敛补固脱。", ["散", "乱"]], "19453": ["病机", "脉大而弦、按之似有力而非真有力，是脾胃真气外泄、冲脉逆气上干之象。大而弦为木气横逆，似有力非真有力说明中气已虚，非实邪内结。故胸膈满闷由冲气上逆所致，慎勿作实证开通，服补敛之剂后脉见柔和即病有转机。", ["大", "弦"]], "19454": ["病机", "真有力之脉当有洪滑之象，洪如波涛起伏、滑如贯珠。此脉弦直，既无起伏又无贯珠，虽大而有力实非真有力。弦直为肝木失和、胃气不充之象，大而无力是气外泄而非内实，故不可误作实证，当辨其胃气之虚。", ["弦", "大"]], "19455": ["病机", "和缓为脾胃正脉，弦长为肝胆正脉，六部脉皆宜有和缓之象。今脉弦而有力，是肝木横恣、侵侮脾土之象，故知脾胃虚。弦为肝旺，有力为横逆，失和缓则土气受克。此以脉之有无和缓辨脾胃虚实，非以弦长本身为病。", ["弦", "缓"]], "19456": ["病机", "原文谓冲脉隶阳明，胃气虚不降则冲气上干，脾胃气化不固已有外越之势，冲气复排挤之，故脉兼大。大脉在此非实热，乃气化外越、冲气上逆之象，主胃气虚而冲气上干之病机。", ["大"]], "19457": ["主病", "脉象大而弦硬，大主气化外越，弦硬主冲气上逆、胃气不降。症见胸腹满闷、气自下上冲、饮食不能下行，正合冲气上冲、胃气不降之病机，故以此脉主冲气上冲之病。", ["大", "弦", "硬"]], "19458": ["病机", "脉弦硬而长，右部尤甚，弦硬主冲气上逆，长主气逆亢盛，右部甚则病在脾胃。原文明言此冲气上冲并迫胃气上逆，故见心中满闷、呕吐痰水、气起下焦上冲胃口，大便干燥亦由胃气不降所致。", ["弦", "硬", "长"]], "19459": ["病机", "六部脉弦硬有力、粗大异常，无一点柔和之象，原文引镇摄汤注谓此脾胃真气外泄、冲脉逆气上干之证，慎勿以实证治之。虽胸膈满闷、食已即吐似实，实为真气外泄、冲气上干，故脉弦硬粗大而不柔和。", ["弦", "硬", "大"]], "19460": ["病机", "两尺洪滑有力，洪滑主热盛，尺部应下焦相火。原文论君火发于心中，温暖脾胃助消化，此脉见两尺洪滑有力，说明下焦相火偏旺，而君火虚衰则脾胃消化力减，故多廉于饮食、寒饮留滞为恙。", ["洪", "滑"]], "19461": ["主病", "脉甚沉细，沉主里、细主虚寒，结合小便不利、周身皆肿、下焦常觉寒凉，知为火不胜水、寒水泛溢而成水肿。沉细脉说明下焦阳虚寒盛、水气不化，故主水肿而兼疝气寒凉之证。", ["沉", "细"]], "19462": ["病机", "脉象甚迟濡，迟主寒、濡主阳虚湿滞，说明脾胃阳虚寒盛，不能运化水谷，故常常呕吐涎沫、甚则吐食。投大热之剂不觉热，久服无效，正因沉寒痼冷非草木所能温，故脉迟濡主寒饮内停之病机。", ["迟", "濡"]], "19463": ["主病", "脉甚迟，不足三至，迟主寒，说明寒饮内停、阳气衰微。症见频频咳吐痰涎、兼发喘逆，皆寒饮上逆犯肺所致。服温药后喘咳轻而脉迟仍旧，知沉寒非草木可挽，故脉迟主寒饮为恙之病。", ["迟"]], "19464": ["病机", "脉甚弦细且不足四至，弦主寒饮内停、阳气被遏，细主阳分虚损、气血不足，迟为阳虚有寒。上焦阳分虚损，寒饮留滞作嗽，故脉弦细而迟；前医误认阴虚，投熟地、阿胶滞泥之品，反助寒饮，病益剧。此脉象说明病机在阳虚寒饮，非阴分虚损，故用理饮汤加附子温阳化饮而效。", ["弦", "细", "迟"]], "19465": ["病机", "脉象沉迟微弱，关前尤甚，沉主病在里，迟主阳虚，微弱主气衰。胸中大气下陷，气短不足以息，努力呼吸似喘，甚则气息将停。大气虚陷不能鼓动血脉，故脉沉迟微弱；关前候胸中，大气下陷于此最著，故关前尤甚。剧者六脉不全、参伍不调，皆大气陷极、气血不相接续之象。", ["沉", "迟", "微", "弱"]], "19466": ["病机", "脉象微细迟弱，微细主气衰血少，迟弱主阳虚无力。大气以元气为根本、水谷为养料、胸中为宅窟，肾系命门少火生气，徐徐上达，培养于后天水谷。若元气虚、水谷衰，则大气生成不足而微细迟弱。此段论大气生成之源，脉微细迟弱正示元气与水谷之气俱虚、大气失养之病机。", ["微", "细", "迟", "弱"]], "19467": ["病机", "本段未识脉名，引《素问》平人气象论「胃之大络名虚里，出于左乳下，其动应衣，脉宗气也」，以虚里动脉应衣论证宗气即大气。虚里之动由胃输水谷之气上养胸中大气而外现，其动应衣则示宗气之盛衰可察。此段主旨在于以虚里动脉阐明大气（宗气）为生命宗主之病机依据，非论具体脉象。", []], "19468": ["病机", "虚里之络为胃输水谷之气养大气的道路，其贯膈络肺之余出于左乳下为动脉，此动脉乃大气之余波。动而应衣，说明宗气（大气）充盈、游行胸中空虚之处；若动微或不应，则大气衰。此段以虚里动脉释宗气即大气，为生命之宗主，脉动之处即大气输布之征，属病机阐发。", ["动"]], "19469": ["病机", "本段未识脉名，引《灵枢》客邪篇「宗气积于胸中，出于喉咙，以贯心脉，而行呼吸」，论证宗气即大气，且大气不但为诸气之纲领，并为周身血脉之纲领。又引五色篇「大气入于脏腑者，不病而卒死」，说明大气下陷之理寓于《内经》。全段以经文阐发大气贯心脉行呼吸之病机，非论脉象。", []], "19470": ["病机", "脉微弱而迟，右部尤甚，微弱主气衰，迟主阳虚，右部候肺脾，右甚则肺脾之气尤虚。因室中氧气被煤火耗尽，胸中大气乏氧又受炭气所伤，日久虚陷，故呼吸短气、心中发凉、少腹下坠作疼。前医误投开破，更伤大气，其兄竟至不起。此脉示大气下陷已剧，当升补而禁开破。", ["微", "弱", "迟"]], "19471": ["病机", "脉数至六至兼沉濡，数主虚热上逆，沉濡主阴亏不纳、气不归元。素有喘病，大喘昼夜不止，前医小青龙加石膏不效，疑阴虚不能纳气。因脉兼沉濡，不敢用降气之品，投大滋真阴送服人参而喘减。复诊脉已不数仍沉濡，询知努力搬运重物，说明喘由肾虚不纳、气逆上浮，数去而沉濡存，正见阴虚之本未复。", ["数", "沉", "濡"]], "19472": ["病机", "脉非微细而指下若不觉其动，乃大气下陷不能鼓脉外出，故起伏之势不显。大气虚陷则动则作喘、时或咳嗽，非劳疾之微细脉，误治数年转剧。此脉象反映胸中大气不足，鼓动无力，主大气下陷证，与喘咳、脉势不显相应。", []], "19473": ["病机", "脉象和平而重按微弦无力，脉稍弱，乃大气下陷之征。胸满咳嗽胁疼，非气分不舒，误投理气药则益甚，言语声颤动，皆因大气虚陷不能升举。弦为气机郁滞之假象，弱为正气不足，主大气下陷，与胸满、胁疼、咳甚相应。", ["弦", "弱"]], "19474": ["病机", "两寸微弱，毫无轩起之象，乃胸中大气下陷之明征。大气不能上奉，故失音、咽喉发紧溃烂、畏风恶寒、饮食减少，浸成虚劳。寸脉微弱反映上焦气虚，鼓动无力，主大气下陷，与咽喉诸症及虚劳相应。", ["微", "弱"]], "19475": ["病机", "脉关前微弱不起，关前候胸中大气，微弱不起即大气下陷不能鼓动之象。故夜不能寐、饮食减少、四肢无力、常觉短气，种种诸证皆由胸中大气虚陷所致。此脉主大气下陷，与短气、不寐、纳减相应。", ["微", "弱"]], "19476": ["病机", "脉沉迟微弱，沉为气虚不能外达，迟为大气下陷鼓动无力，微弱为正气大虚。故夜忽不能言、不能息，呼吸短气。原文明言“大气下陷之脉大抵皆迟，非因寒凉而迟”，用知母以济黄芪之热。此脉主大气下陷，与失语、短气相应。", ["沉", "迟", "微", "弱"]], "19477": ["病机", "脉关前微弱，关后重按似有力，乃胸中大气下陷而伏邪随陷化热之象。关前微弱主大气虚陷，关后有力为伏热内郁。故小便处若火炙、腹气下坠则热益甚、呼吸短气、心中发热。此脉主大气下陷兼伏邪化热，与短气、发热、下坠感相应。", ["微", "弱"]], "19478": ["死脉", "脉见雀啄，乃真气将竭、胃气已败之死脉。患者因大气下陷，误治反复，病势垂危，喘不能卧，昼夜倚壁而坐，假寐片时气息即停，心下突突。雀啄脉主脏气衰败，与喘促、气息将停之危候相应，预后凶险。", ["雀啄"]], "19479": ["病机", "脉多数，乃大气下陷过甚，呼吸机关将停，勉强鼓舞肺气努力呼吸以自救，故脉数迫促。此喘非气逆之喘，必不肩息，因呼气难而非吸气难。数脉反映虚性代偿，主大气下陷之喘，与迫促似喘、气息将停相应，须与气逆作喘鉴别。", ["数"]], "19480": ["病机", "脉沉迟微弱，右部尤甚，沉迟主阳气不足，微弱主气血虚衰。右部候肺脾，右部尤甚说明大气下陷，不能鼓动血脉。患者吐血、咳嗽痰涎壅滞、动则喘、短气，皆因大气下陷，气机升降失常，故投升陷汤升举大气而愈。", ["沉", "迟", "微", "弱"]], "19481": ["病机", "脉滑而有力，滑主痰湿，有力主实热，故疑湿热壅滞。症见小便不利、周身漫肿、痰涎杜塞、咳痰带血、尿血，皆湿热壅滞三焦，气化不利。后脉虽滑实但沉分，说明热退而气陷，故见起坐喘息，大气下陷之象。", ["滑", "实"]], "19482": ["病机", "脉微弱欲无，呼吸略似迫促，微弱主气血虚极，大气下陷，不能鼓脉。症见咳嗽短气、大汗如洗、怔忡，皆大气下陷，卫外不固，心气失养。投升陷汤加龙骨牡蛎止汗固脱，三剂而愈。", ["微", "弱"]], "19483": ["病机", "脉近和平，右部较沉，右部候胸中大气，沉主气陷。因惊恐过甚，恐则气陷，致胸中大气下陷，故呼吸短气、怔忡、食后气不上达、常作太息。脉近和平说明未至虚极，但右部沉已露气陷之机，投升陷汤而愈。", ["沉"]], "19484": ["病机", "脉左部如常，右部来缓去急，分毫不能鼓指，右部候胸中大气，来缓去急、不能鼓指，是大气下陷，不能鼓脉外出以成波澜。因常恼怒，致大气下陷，故呼吸短气、咽干作渴、气息将停。投升陷汤后右脉较前有力，证明气陷渐复。", []], "19485": ["病机", "左脉沉细欲无，右脉沉紧，皆有数象。左脉沉细欲无主气血虚极，右脉沉紧数主热药所伤，大气下陷。产后努力过甚，大气下陷，又服干姜热药，故寒热益甚、渴饮、身热如炙而恶寒。投升陷汤加知母玄参清热而愈。", ["沉", "细", "紧", "数"]], "19486": ["病机", "右脉沉紧，沉而有力，非洪象。因大气下陷，虽内有实热，不能鼓脉作起伏之势，故不为洪而为紧，且为沉紧。紧为受寒之脉，此证因热药所伤，胃先受之，故独见于右部。说明大气下陷与实热并见，脉象反映气陷不能鼓脉。", ["紧", "沉"]], "19487": ["病机", "脉无起伏为弦，弦而有力即紧脉。若但弦则为寒。仲景谓「双弦者寒，偏弦者饮」，饮多因寒而成。说明弦紧脉主寒、主饮，紧脉为弦之有力者，反映寒邪或饮邪内停，气机收引之病机。", ["弦", "紧"]], "19488": ["病机", "脉细如丝，右手尤甚，右手主气，细如丝为气虚无力鼓动之象。胸中大气下陷，统摄失职，故两腿痿废；卫外不固则自汗；神魂无所依附则不寐；三焦气化不行则小便不利。脉细如丝正合大气下陷、全身失统之病机。", ["细"]], "19489": ["病机", "脉迟而且弱，迟为阳气不振，弱为气虚无力。因过用开破之药，胸中大气下陷，阳气不能敷布，故寒热；呼吸短气亦因大气陷而肺失所养。脉迟弱非寒实证，乃气虚阳弱之征，单用黄耆、桂枝、干姜温补升提而愈。", ["迟", "弱"]], "19490": ["病机", "左寸关尺皆不见，右部脉虽见而微弱欲无，左脉主血，右脉主气，左脉不见为大气下陷、气血不能上奉。因枵腹劳力过度，大气下陷，故寒热、短气、大汗、头疼咽干、畏凉嗜睡。脉微弱欲无正合气虚下陷之机。", ["微弱"]], "19491": ["病机", "脉微弱异常，为气虚至极、鼓动无力之象。胸中大气下陷甚剧，故短气、汗出，甚则气不上达而昏不知人，睡中惊寤亦因神魂失依。脉微弱异常直接反映大气虚陷之重，投升陷汤加人参、萸肉补敛而愈。", ["微弱"]], "19492": ["病机", "脉左右皆微弱，至数稍迟，微弱为气虚，迟为阳运无力。外感温证经误治，邪陷而大气下陷，故神昏、舌干、周身凉、长出息。大气不达脑中则神昏，不潮舌本则舌干，不布营卫则身凉，脉微弱迟正合此机。", ["微弱", "迟"]], "19493": ["病机", "脉五至为数，浮分微弱，重按似有力，数而浮微为邪陷正虚、虚阳外浮之象。温病误用破气，邪陷已深，不能外出，故谵语、循衣摸床、周身颤动。浮分微弱示正气不足，重按有力示邪陷于里，后脉象和平乃邪退正复。", ["数", "微", "浮"]], "19494": ["病机", "脉沉细，沉为气陷不升，细为气虚血少。胸中大气下陷，气机闭塞，故咽喉发闷；脉沉细非郁气实证，乃大气陷下、无力升举之候。误用开气之药更伤正气，故翌日即逝，此脉沉细主大气下陷之危候。", ["沉", "细"]], "19495": ["死脉", "脉左右皆无，为大气下陷至极、气血不能外达之死候。因劳碌过度，大气下陷，肺之呼吸将停，努力呼吸以自救，故气息迫促。医者误作气逆喘，屡投纳气降气之药，更促其亡。脉无而气息迫促，乃大气将绝之死脉。", []], "19496": ["病机", "原文论大气下陷脉象多变：因肺脉诊在右，故右部脉多微弱为常；若肝肾素虚或破肝气太过，则左脉更形微弱，甚至沉细欲无、参伍不调。脉多迟而间有数，乃阴分虚损或气机失调所致。可见同一大气下陷，因体质与用药不同，脉象左右迟数各异，总以微弱为常。", ["迟", "微弱", "沉细", "数"]], "19497": ["病机", "脉甚沉微，示胸中大气下陷过甚，鼓动无力，故气短不足以息、努力呼吸似喘；大气不运，痰涎内积，故心中满闷怔忡、喉干作渴。沉微为气虚陷下之征，非外邪实滞。服药后吐出黏涎，正是大气来复、运转痰涎外出，合《金匮》「大气一转，其气乃散」之旨。", ["沉", "微"]], "19498": ["病机", "左脉微细如丝、按之即无，右脉亦无力，为大气下陷、气血不能上奉之象。气陷则气息不接、胸闷不畅、精神恍惚；清阳不升，他经逆气乘虚上干，故头疼甚剧。脉微细如丝，正虚陷无力鼓脉之征，非外感头痛之浮紧可拟。", ["微", "细"]], "19499": ["病机", "脉濡弱无力，为大气下陷、中气不足之征。患儿乳哺不足，面白神疲，身体孱弱，呼吸促短若不能接续，气陷则下焦气化失固，故脱肛近四载。濡弱无力非湿盛之濡，乃气虚不能鼓脉，与呼吸促短、肛坠相应，主升补大气以固下焦。", ["濡", "弱"]], "19500": ["病机", "两手尺寸之脉皆极沉，惟关脉坚而有力、两关坚弦，非实热内结，乃因误用二陈推荡，大气下陷而药力搏激之象。尺寸极沉示气陷不达；关脉坚弦为药力推荡所致。故见心内动悸、痞塞短气，甚则全身一战、冷汗满额、心跳连次，皆大气下陷之危候。", ["沉", "坚", "弦"]], "19501": ["病机", "脉沉微，瞳神涣散，呼吸甚微如一线游丝，肢冷额汗，气息仅属，此非猝中闭证，乃高年大气下陷、元气欲脱之候。沉微为阳气衰微、不能鼓脉外达；瞳散息微为气陷将脱之危象。故断为大气下陷，而非寻常中风。", ["沉", "微"]], "19502": ["病机", "左关弦硬，右寸独微弱，口不能言，气息甚微。右寸候肺，微弱为胸中大气下陷、肺气将竭之征；左关弦硬乃肝郁乘脾、气机失调之象。年高乳疮疼痛耗气，大气因之下陷，故病势危殆。弦硬非实，乃气陷后肝失疏泄之变。", ["弦", "硬", "微"]], "19503": ["病机", "脉微细若无，身无寒热，心跳，少腹微疼，知非外感。产后乳痈出脓甚多，气血骤耗，胸中大气因之下陷，故神昏不食、头疼。微细若无为气陷不能鼓脉之征；无寒热可排除外感。头疼乃清阳不升、浊气上扰所致，投升陷汤提补大气则愈。", ["微", "细"]], "19504": ["病机", "原文未出脉象，论心肺之阳皆虚而周身热力不足，谓肺与心同居膈上、血脉循环相通，二脏宣通热力相助为理，必有大气斡旋其功用始彰。故热力不足非独心火亏，实由心肺阳虚、大气不运，斡旋失职则宣通无力，与后文脉微弱而迟、右部兼沉之案相呼应。", []], "19505": ["主病", "脉微弱而迟、右部兼沉，微弱为阳气虚衰，迟为阳不胜阴，右部沉则大气下陷。心身寒凉、饮食不化、短气，皆心肺阳分虚损、大气下陷之候；服热药不觉热，正因阳虚不能受纳。故主心肺阳虚、大气下陷之病。", ["微", "弱", "迟", "沉"]], "19506": ["主病", "脉沉细微弱、至数甚迟，沉细为阳衰气陷，微弱迟为虚寒。大怒后下痢，胸中满闷、食不化、心中觉凉，乃大气下陷兼上焦阳分虚损。前医通利破气，愈服愈增，正伤其已陷之气。故主大气下陷、上焦阳虚之病。", ["沉", "微", "细", "弱"]], "19507": ["主病", "脉微弱而迟，素体羸弱畏寒、胸满短气，忽昏倒不语、呼吸滞碍，乃大气下陷兼寒饮结胸，势将痰厥。微弱迟为阳虚气陷、寒饮内结之征；胡椒、干姜开寒饮后仍呵欠太息，知大气未复。故主大气下陷兼寒饮结胸之病。", ["微", "弱", "迟"]], "19508": ["病机", "脉迟而无力，迟为阳虚，无力为气虚。产后劳力过度，胸中满闷作疼、鼻息发热、作渴，似热而脉反迟无力，知非实热，乃气分郁结又下陷，阳气不运故郁而似热。服山药、鸡内金后脉无力更甚，益证气陷。故主气分郁结下陷之病机。", ["迟", "无", "力"]], "19509": ["病机", "脉细小而沉，细为气少，小为虚，沉为气陷。少女脐下症瘕坠疼连腰，因小便努力过甚，上焦之气陷至下焦而郁结，结久愈坚。脉细小沉正合气陷郁结之机，故以脉象参病因，知为努力致气陷下焦、郁结成瘕之病机。", ["细", "小", "沉"]], "19510": ["兼症", "脉甚微弱而数至六至，微弱为大气下陷、正气虚，数为虚热或肝火横恣。少妇经闭两月、寒热往来、胁下疼、短气，乃大气下陷兼肝气横恣，故用龙骨、牡蛎敛肝火、缩黄耆膨胀之力，加玄参、生地、白芍以清数脉之热。此段论兼胁痛脉数之兼症治法。", ["微", "弱", "数"]], "19511": ["病机", "脉浮而微数、按之即无，浮为阳虚外越，微为阴阳俱虚，数为虚阳不敛，按之无根则元气不能自摄。喘逆迫促、呼吸几脱，乃阴阳两虚，阳虚不摄、阴虚肝肾不纳气。前医补敛则窒碍，散邪则益甚。故主阴阳两虚、元气不摄之喘病机。", ["浮", "微", "数"]], "19512": ["病机", "左关弦硬为肝胆火旺之象，右寸无力示肺气不足。怒激肝胆之火上冲胃气，胃气本降反逆，并迫肺气上逆，故喘逆迫促；逆气填塞胸膈，排挤胸中大气下陷，致呼吸顿停。脉象反映肝火冲逆、肺气不降、大气下陷之病机。", ["弦", "硬"]], "19513": ["病机", "脉浮而无力，浮为气机上逆，无力为正气不足。胸次郁结如有物杜塞，饮食至胃间烧热不下，乃胃气上逆不降所致。脉浮无力反映气逆而中气虚弱，故用参赭镇气汤补虚镇逆，使胸次开通、饮食下行。", ["浮", "虚"]], "19514": ["预后", "脉微细不起，形状颓败殊甚，为阴阳将脱之危候。患者喘逆上冲、不能平卧、胸痞腹胀、大便旬余未行、语不接气、时或瘛疭，种种见证已濒极险。微细之脉示正气衰微、阴阳脱离之虞，故用重镇之品恐正气随以下陷，需配党参、山药等扶正。", ["微", "细"]], "19515": ["病机", "此段论吸气时腹膨胀之理，阐明膈上大气司呼吸、膈下中气保合脾胃、脐下元气固性命根蒂。下焦肝肾属阴虚，阴虚气化不摄则内气膨胀，遂致吸气困难而喘。虽未明言脉象，但病机为阴虚气化不摄、内气膨胀致喘。", []], "19516": ["病机", "脾脉缓大为太阴湿土正象，虚劳喘嗽者脉多弦数，与缓大相反，乃脾土病脉。脾失中空之体，或紧缩或胀大，壅激气血上逆迫肺作喘；胃气不降转上逆亦迫肺作喘。脉弦数反映脾病及虚劳喘嗽之病机，故重用山药滋脾阴、于术理脾阳。", ["缓", "大", "弦", "数"]], "19517": ["主病", "脉数至七至，喘逆甚剧，用一切治喘药不效。数脉主热，亦主虚，此喘剧而脉数，为气逆火升、心肺热盛之象。制方煎成因喘剧不能服，温汤三次始服下，一剂见轻，数剂全愈，说明脉数与此喘证相应，方证合拍。", ["数"]], "19518": ["病机", "喘者之脉多数，脉之原动力发于心，脉动数则心动亦数。心动太急逼血力过常度，肺脏呼吸亦速过常度，故喘。心与肾为对待之体，心动急数则肾真阴不能上潮靖安心阳，故心累肺作喘之证亦即肾虚不纳气之证。数脉反映心火急数、肾阴不能上济之病机。", ["数"]], "19519": ["治法", "心肺阳虚致脾湿不升、胃郁不降，饮食不化精微变为饮邪，停于胃口为满闷，溢于膈上为短气，渍满肺窍为喘促，滞腻咽喉为咳吐黏涎。必诊其脉确乎弦迟细弱者，方能投以此汤。弦迟细弱示阳虚饮停、气机不畅，故以温阳化饮为治。", ["弦", "迟", "细", "弱"]], "19520": ["病机", "脉沉细几不可见，沉主里、细主虚，反映心肺阳虚，阳气不能宣通脾胃，致痰饮内生。胸中满闷发热、大喘为痰饮上逆之症；误用清火理气更伤阳，故久服转剧。此脉象说明病本在阳虚，非实火。", ["沉", "细"]], "19521": ["病机", "脉象浮大按之甚软，浮大似实而软则无力，乃心肺阳虚、脾胃气弱之象。因过服礞石滚痰丸苦寒攻泻，伤及阳气，致虚阳外浮。症见耳鸣欲聋、热气上腾、饮食难化，皆阳虚不运、虚火上浮之候。", ["浮", "大", "软"]], "19522": ["病机", "脉弦细而迟，弦主饮、细主虚、迟主寒，合为寒饮结胸、阻塞气化之征。上焦满闷烦躁、思食凉物而食之益甚，是寒饮内结、阳气不布；黎明泄泻日久，乃脾肾阳虚。故投理饮汤温阳化饮而愈。", ["弦", "细", "迟"]], "19523": ["病机", "脉弦细欲无，弦为饮邪凝结，细欲无乃阳气衰微、气血不足。频吐稀涎、觉物杜塞胃口、气不上达，皆寒饮凝结、阻遏气机之症。饮食日减、羸弱不起，说明久病阳衰。此脉象主寒饮内结、阳气虚极。", ["弦", "细"]], "19524": ["病机", "脉甚弦细，弦主虚寒饮邪，细主血虚。患者饮食甚少，心肺脾胃阳分虚惫，不能运化精微以生气血；血虚不能荣筋，气虚不能充体，故卧则发搐、抚之辄发。此脉象说明病机为阳衰血少、筋脉失养。", ["弦", "细"]], "19525": ["病机", "本段未识脉名，专论痰之本在肾。肾闭藏不固，气注膀胱，膀胱膨胀不能吸引胃中水饮下行，遂生痰；冲脉上隶阳明，冲气上干则胃气上逆，亦生痰。故治痰当求其本，二陈汤仅治痰之标。", []], "19526": ["主病", "脉滑、体丰，滑主痰涎，体丰多痰湿，故知痫风由痰涎为恙。痰涎内壅，蒙蔽清窍，发为痫风。治以理饮汤加赭石降痰镇逆，数剂拔除病根，说明脉滑在此主痰涎壅盛之痫证。", ["滑"]], "19527": ["病机", "脉左部平和微嫌无力，右部直上直下仿佛有力而按之非真有力，右部应冲脉，直上直下为冲气上逆之象，按之无力则非实。肾虚致冲气挟痰上冲，乱其神明，故胆怯、呃逆、癫狂唱呼；下焦觉凉、遗精，皆肾虚不固之候。", ["平和", "无力"]], "19528": ["病机", "脉大于平时一倍而重按无力，乃肝肾大虚、冲气上逆之象。虚阳外浮故脉形倍大，重按无力正示根本亏虚；冲气挟痰火上并，扰乱心神，故见妄言妄见、惊惧扰动。少腹塌陷、胸膈突起，为下虚上实之征，脉症相合，主肝肾虚而冲逆痰火。", ["大"]], "19529": ["病机", "脉沉迟兼闭塞之象，沉主里、迟主寒，闭塞为痰气壅阻之征。唇𥆧动乃有痰之据，合参脉症，系寒痰壅滞上焦过甚，蒙蔽清窍，故昏昏似睡、半日不醒。点天突令咳吐凉痰后能言，干姜温化而愈，反证脉沉迟所主为寒痰内闭。", ["沉", "迟"]], "19530": ["病机", "脉仿佛若动，乃冻僵后气血凝滞、脉道不通之象，非死脉也。以手掩口鼻微觉有热，知阳气未绝，犹可救。寒邪外束，痰涎内壅，故僵卧不动、呼吸全无、昏不知人。点天突吐凉痰、饮干姜而愈，说明此脉象所主为寒痰闭塞、阳气郁遏之病机。", []], "19531": ["病机", "左手沉濡、右三部皆无，非虚寒之候。沉濡为痰涎壅盛、瘀阻脉道之象，故脉气不显；面有红光、不受生姜，俱属热痰杜塞胃口，胃气蓄极上逆，故连连干呕、状似呃逆。用生白矾化热痰而愈，证明脉象如此者，乃痰多瘀脉，主热痰内闭。", ["沉", "濡"]], "19532": ["病机", "脉闭塞不全，乃痰涎壅盛、气机闭塞、脉道不利之象。患者因情志激变，身躯后挺、牙关紧闭、口出涎沫，显系内风掀动、痰厥不醒。麝香清油灌之即醒，说明脉闭塞不全所主为痰气壅闭、内风扰动之病机，非气血败绝之死脉。", []], "19533": ["病机", "六脉皆伏，乃产后五内空虚，骤食饱填，胸中大气不能宣通，诸气因之闭塞所致。伏脉主气机闭阻，非脉气绝无；故猝然昏倒、四肢抽搐、不省人事。点天突、刺十宣后咳吐稠痰、气顺腹响而愈，证明此伏脉所主为食填气闭、痰壅清窍之病机。", ["伏"]], "19534": ["病机", "脉弦而有力，主肝经偏盛。肺金病不能镇木，肝木横恣，故脉现弦劲有力；木火刑金，则上焦发热、咳吐失音、痰腥臭而羸瘦。清火润肺不效，加生黄耆助元气即愈，说明此脉虽有力，实为肝木侮金、元气亦伤之病机，非纯实热。", ["弦"]], "19535": ["病机", "脉洪而有力多系外感实热，弦而有力多系肝经偏盛。此证脉弦而有力，乃肺金病不能镇木，肝木横恣、转欲侮金之象，故为有病之脉。真有力当于敦厚和缓中见之，此则弦急少和，主肝木偏胜、肺金受侮，肺痿肺痈胁下疼亦由肝木偏胜所致。", ["洪", "弦"]], "19536": ["病机", "脉浮而有力，关前兼滑，浮主外感，滑主痰火。肺中素郁痰火，又为外感拘束，故脉浮滑有力。此脉象提示外感引动痰火，肺气壅滞，症见咳嗽吐痰腥臭，恐成肺痈。", ["浮", "滑"]], "19537": ["病机", "脉数至六至，按之无力，数主热，无力为虚。咳吐腥臭痰、夜间出汗、日形羸弱，乃肺中热毒腐溃，气阴两伤。脉数无力说明热毒未清而正气已虚，故投清金解毒汤加龙骨、知母，清热敛汗。", ["数", "虚"]], "19538": ["治法", "脉虚弱者，酌加人参、天冬各数钱。脉虚弱提示正气不足，肺痈病剧而见脉弱，当顾护气阴。故于方中加人参补气、天冬滋阴，以扶正托邪，体现凭脉施治、虚实兼顾之法。", ["虚", "弱"]], "19539": ["病机", "肺痈者肺中生疮或腐烂，脉虚者正气已伤。甘草为疮家解毒主药，味甘得土气最厚，能生金益肺，治肺中虚损糜烂。调以知母寒滑，制甘草壅滞，滋阴退热而不伤胃，说明脉虚当以甘润清补为要。", ["虚"]], "19540": ["病机", "脉浮而有力，右胜于左，按之却非洪实，后脉象虚弱。浮取有力似实，按之不实，乃肺中热毒壅滞而正气已伤。昼夜咳嗽、吐痰腥臭、胸中隐痛，恐成肺痈。脉虚说明攻伐伤正，故改用甘草、金银花等清解兼护胃气。", ["浮", "虚", "弱"]], "19541": ["病机", "脉一分钟八十五至，右脉滑而实，舌黄苔满布，大便燥。数主热，滑实主痰热内壅。外感稽留肺胃，久而生炎欲腐，故咳嗽吐痰腥臭、羸弱。左脉近平和，病偏右部肺胃，脉象揭示热壅痰实之病机。", ["数", "滑", "实"]], "19542": ["病机", "脉洪滑而长，或上入鱼际，洪滑主热盛，长脉主气火有余。吐血、衄血因热而胃气不降，血随逆气上升。脉象洪滑长说明胃热炽盛，气逆血溢，故以寒凉重坠之药降胃气则血止。", ["洪", "滑", "长"]], "19543": ["病机", "童子陡然吐血，脉洪长，右部尤重按有力。洪长有力主胃热炽盛，气火上升。胃气因热不降，血随逆气上溢，故吐血一昼夜不止。服降胃清热之剂后脉亦和平，说明热降气顺则血止。", ["洪", "长"]], "19544": ["病机", "脉如水上浮麻，莫辨至数，乃大吐亡血后血分虚极，脉道不充，气血涣散之象；再诊左右皆无、重按不见，即吕沧洲所谓“脉者血之波澜”，血伤不能复作波澜，故脉不出。此脉主血脱气耗之危候，与心中安稳、酸懒无力相应，非热实闭阻，故不用药立止其血则危可翘足而待。", ["虚"]], "19545": ["病机", "脉象弦细无力，弦为寒饮内结、胃气不降，细为脾胃湿寒、气血不充，无力则中阳不振。上焦烦热、频吐稀涎，乃寒湿留饮阻遏，胃气不能运化下行，反逆于上所致。此脉主脾胃湿寒、留饮为恙，与不能饮食、咳吐稀涎相应，故用苓桂术甘汤加干姜、半夏温运降逆。", ["弦", "细"]], "19546": ["病机", "脉浮而洪，至数微数，重按不实，浮洪为热盛气逆之象，数则热迫，重按不实知非实热内结，乃热迫胃气不降、血随气升而吐衄。此脉主吐衄因热者，与吐血剧、诸药不效相应，故放胆投赭石、台参、生杭芍，降逆清热而愈。", ["浮", "洪", "数"]], "19547": ["病机", "左脉细弱，右脉弦而有力，左细弱为血虚阴亏，右弦有力为胃气因热上逆。病久生热，胃气上逆，血随气升，故吐血时发时愈，咳嗽音哑、胸中烦热、食少倦怠皆由血虚热逆所致。此脉主胃热上逆、血随气升之吐衄，故用寒降汤降胃清热，加川贝以治咳嗽音哑。", ["细", "弱", "弦"]], "19548": ["病机", "脉象洪滑，重按甚实，洪滑为热盛痰壅，重按实为胃热内迫、气逆不降。赤日晴天，热迫胃气上逆，血随气升，故吐血呕不止。此脉主热迫胃气不降之吐衄，与呕血不止相应，故用泻心汤送服黑山栀，继以寒降汤加三七降逆止血。", ["洪", "滑", "实"]], "19549": ["病机", "脉虚濡而迟，虚濡为脾胃气虚、湿滞不化，迟为寒凉内阻。饮食停滞胃口，不能消化，因凉而胃气不降，血随上逆而为吐衄。此脉主因凉胃气不降之吐衄，与饮食停滞相应，故以温补开通之药降其胃气，则血止矣。", ["虚", "濡", "迟"]], "19550": ["病机", "初诊脉甚和平，用清凉止血后衄益甚，脉转微弱，微弱为胃气因寒不降、中阳不足之象。胃气厥逆，血随气上而为衄，因寒者间亦有之。此脉主胃寒不降之衄血，与心中不觉凉热、衄血四次相应，故知前用清凉反伤中阳，当温降胃气。", ["微", "弱"]], "19551": ["病机", "脉微细而迟，微细为气血虚衰，迟为脾胃虚寒。脾胃虚寒，中气下陷，太阴不升，血失统摄，故小便下血久不愈，身体虚弱、恶寒、饮食减少皆虚寒之征。此脉主脾胃虚寒、中气下陷之便血，故用干姜、于术、山药、熟地、乌附子、炙甘草温补升提，不用肉桂恐动血分。", ["微", "细", "迟"]], "19552": ["病机", "吐血过多致气分虚甚，血脱气将脱，脉上盛下虚反映上焦虚阳浮越、下焦根本空虚。上盛为烦热之象，下虚为气脱之根，故主气血将脱之候，与喘促咳逆并见。", ["上盛下虚"]], "19553": ["预后", "脉摇摇无根、一动一止或两三动一止，为气血虚极、将脱之候。劳嗽呕血数碗后见此脉，说明元气涣散、脉无胃根，故主预后危重，与痰血相杂、心中发热相应。", []], "19554": ["病机", "咳嗽吐血咯吐甚多，气分太虚，喘息迫促，上焦烦热，脉大而无力右部尤甚，为大虚反见大脉、气脱于上之象。血脱气亦将脱，故脉大无力，主气分虚极。", ["大", "无力"]], "19555": ["病机", "下元虚损、中气衰惫，冲气胃气因虚上逆，脉弦而硬急转似有力，为虚气上逆、脉失柔和之象。弦硬急非实热，乃冲胃之气上逆所致，主吐衄之证。", ["弦", "硬", "急"]], "19556": ["病机", "脉弦而有力，似实热而非真有力，乃下元虚损、冲气因虚上逆并迫胃气上逆所致。直上直下为冲脉昭昭，故主冲胃气逆之吐血，不可误作实热恣用苦寒。", ["弦", "有力"]], "19557": ["兼症", "脉一分钟九十至、按之不实，为数而无力之象，主虚热上浮。咳嗽痰中带血、心中发热，因肝气郁遏、怒梦哭泣后吐血，故脉数不实与肝郁化火、虚火上炎相应。", ["数"]], "19558": ["病机", "脉象滑数、摇摇有动象、按之不实，为痰热内蕴而正气已虚之象。吐血证见滑数不实，说明痰火扰动、胃气不降，心若虚悬无著，故主痰热挟虚之吐血。", ["滑", "数"]], "19559": ["病机", "童子大便下血数月，所下若烂炙杂油膜，脉弦数无力，为肝脾湿热下注而气阴已伤之象。弦数主热，无力主虚，故主虚热便血，与久病不愈相应。", ["弦", "数", "无力"]], "19560": ["病机", "原文言“脉之虚弱已甚”，是气血阴阳亏虚已极之象。虚弱脉主正气不足，故见“日服补药毫无起象”或“病虚极不受补”。此段以脉虚弱说明虚劳本质，而用龙骨、牡蛎安魂强魄，使精神自足而虚弱自愈，提示脉虚非独补益，尚需镇摄魂魄。", ["虚", "弱"]], "19561": ["主病", "脉“近和平，微有芤象”，芤主失血，虽脉近和平，但微芤提示吐血日久，阴血已伤。此段治吐血用此方，三剂全愈，说明脉芤为血虚有热之征，方中养阴清热止血，故取效。若吐血甚，加赭石、三七，亦从脉芤知血失而设。", ["芤"]], "19562": ["病机", "脉“似沉牢”，沉主里，牢主瘀血坚积。患者素患吐血，误服补药致胸中发紧、血益不止，后虽血止而胸中不舒、食少肢懒，脉沉牢提示膈上瘀血为患。用鸭蛋子化瘀，数日而愈，证明沉牢脉主瘀血内结，非虚证可补。", ["沉", "牢"]], "19563": ["病机", "脉“沉迟无力”，沉主里，迟主寒，无力为虚。此脉象说明怔忡多因胸中大气下陷，清阳不升，心失所养。原文指出若脉沉迟无力，其怔忡非热证，不可妄加生地，当从升陷汤诸法升举大气，则怔忡自愈。", ["沉", "迟", "无", "力"]], "19564": ["其他", "此段纯述西人心肺解剖生理，未及脉象，故脉象要素为空。原文论心肺关系全体、血行路径，虽无脉诊内容，但为理解心病脉理提供背景。其主旨属其他，非直接论脉，故不归主病或病机。", []], "19565": ["病机", "原文论心跳真假及怔忡证，言“其收发血脉之动力，非大于常率”，未直接描述脉象，故脉象要素为空。其主旨辨析心跳与怔忡病机：真跳为心体自病或身弱累心，假跳即怔忡因气血虚而神明虚，故以手扪之不觉跳，治以定心汤。", []], "19566": ["病机", "脉有滑象，身形丰腴，滑主痰湿。累月不眠，屡药无效，脉滑提示心下停痰，痰浊扰心则失眠。用此汤化痰，两剂而愈，证明滑脉在此主痰饮内停，非妊娠或实热，故从痰治而效。", ["滑"]], "19567": ["病机", "脉左右皆有滑象，滑主痰。妇人一月未睡，倦极欲睡即惊恐而醒，脉滑提示痰浊内阻，胆胃不和，痰热扰心。用苦瓜蒂吐胶痰数碗，心中舒畅，继以利痰养心安神而愈，说明滑脉主痰，痰去则神安。", ["滑"]], "19568": ["主病", "脉滑实者，滑主痰浊内盛，实主邪气壅盛。癫狂失心之证，多因痰火扰心、神明失主，脉见滑实，说明痰浊实邪结聚，正气未虚，故脉象应指有力。此脉象提示病机为痰实闭阻心窍，与癫狂失心之症相应，治疗当以豁痰开窍、泻实为主。", ["滑", "实"]], "19569": ["病机", "原文指出“痰脉多滑”，滑脉主痰湿内蕴。然癫狂剧者，脉多瘀塞，甚或六脉皆不见，此因顽痰闭阻脉道，气血不能外达，故脉象一时隐伏。用开痰药通之，脉方出，说明顽痰能闭脉，脉滑为痰之常，脉闭为痰之变，病机关键在于痰浊壅塞、气机不通。", ["滑"]], "19570": ["病机", "脉关前浮洪，摇摇而动，浮主上焦，洪为阳盛，动主惊扰。患者夜间呕吐头疼、怔忡甚剧、上半身自汗，乃肝阳上冲、扰动心神之象。关前浮洪摇动，说明阳热亢盛于上，气血随之上逆，故见呕吐头疼、怔忡自汗，病机为肝阳上扰、心神不宁。", ["浮", "洪", "动"]], "19571": ["病机", "左关虚浮，左关候肝，虚浮为肝血不足、肝气浮越之象。患者恼怒之后，身躯后挺、气息即断，乃肝气上逆、虚风内动所致。脉虚浮说明肝体不足而肝用亢逆，病机为肝血亏虚、气逆风动，故用萸肉、龙骨、牡蛎、白芍等敛肝潜阳之品而愈。", ["虚", "浮"]], "19572": ["病机", "脉浮小无根，浮为虚阳外越，小为气血不足，无根为肾气不固。患儿禀质甚弱，肝风内动，抽掣不休，囟门微凸，指纹紫爪，目睛无神，此因虚气化不固，肝阳上冲脑部，扰及神经。脉浮小无根正说明正气虚衰、虚阳上浮，病机为虚风内动、阳浮于上。", ["浮", "小"]], "19573": ["病机", "脉数身热，数主热盛，身热为阳热之征。患儿夜间肝风抽动喘息，指纹红爪，时当仲夏燥热，脉数身热说明热邪内盛、肝风内动。热盛则风生，风火相煽，故见抽动喘息，病机为热极生风、肝风内动，治以散风清热、潜阳镇逆。", ["数"]], "19574": ["病机", "脉弦细而迟，弦主肝风，细主血虚，迟主寒凝。吐泻交作，带有黏涎，六脉不闭塞，非霍乱之象。弦细迟说明寒痰结胸、格拒饮食，肝血不足而寒痰凝滞，乃慢惊风将成之兆。病机为寒痰凝结、肝风内动，故用逐寒荡惊汤、加味理中地黄汤温中化痰而愈。", ["弦", "细", "迟"]], "19575": ["病机", "脉甚迟濡，迟主寒，濡主湿。患者身挺搐搦、不省人事，状类急惊，然畏食凉物、呼吸短气，时当仲夏而畏凉，征以脉象病情，其为寒痰凝结、瘀塞经络无疑。迟濡之脉说明寒湿内盛、阳气不伸，病机为寒痰闭阻经络，故用白通汤温通阳气而愈。", ["迟", "濡"]], "19576": ["病机", "脉微细欲无且迟缓，为阳气衰微、寒饮内伏之象。患者素寒饮，猝中风寒，外寒引动内饮，凝结壅滞，故脉道鼓动无力而见微细，寒性凝滞故脉行迟慢。此脉主阳虚寒凝、痰饮阻络之中风，与昏倒、痰涎壅滞、呼吸碍滞相应。", ["微", "细", "迟", "缓"]], "19577": ["病机", "脉象郁涩，为邪实内闭、气血郁滞之征。风邪中于经络，闭塞太甚，气血不得宣通，故脉气往来艰涩不畅。此脉主邪实闭塞之证，与二便不通并见，提示当用大黄内通外散，仿防风通圣散意，以开郁泄实。", ["涩"]], "19578": ["病机", "脉洪大有力，为痰火充实、邪热内盛之象。洪大主热盛，有力主邪实，痰火壅闭诸窍，故脉形洪大而搏指有力。此脉主痰火闭窍之实证，与昏厥、遗尿、口噤手拳、痰声如锯、面赤气粗相应，服参附温补则危，当以凉泻开通为治。", ["洪", "大"]], "19579": ["兼症", "脉滑主痰，为痰湿内蕴之征。滑脉往来流利，如珠走盘，是痰浊内盛、气机被阻之象。此段以脉滑为辨痰之据，见滑脉则于主方中加半夏以化痰，说明脉滑与痰证相应，属兼症加减之法。", ["滑"]], "19580": ["病机", "脉浮数有力，为经络虚而有热之象。浮主病在经络肌表，数主热，有力为邪热内郁。历节风证见浮数有力，知非纯虚，乃经络空虚而热邪留著，故用加味黄耆五物汤加知母等清热通络，服之速效。", ["浮", "数"]], "19581": ["治法", "原文仅言“脉象有热者”，未出具体脉名，故脉象要素从略。此段论黄耆治大风及中风抽掣之加减法，以脉象有热为凭，酌加知母、天冬清热，体现凭脉辨证、随证加减的治法思路，非专论某脉主病。", []], "19582": ["病机", "脉弦长有力，为肝阳上亢、气血上逆之象。弦主肝病，长主气火有余，有力主邪实，合为内中风（类中风）之典型脉。此脉主上盛下虚、脑充血，与眩晕、头痛发热、目胀耳鸣、心烦噫气、肢体不利、口眼歪斜乃至昏仆偏枯相应。", ["弦", "长", "有", "力"]], "19583": ["兼症", "尺脉重按虚者，为肾阴不足、下元亏虚之征。尺部候肾，重按无力而虚，说明肾精亏耗，不能涵养肝木。此段以尺脉重按虚为凭，于主方中加熟地、萸肉补肾填精，属兼症加减，示人凭脉辨虚实以定去取。", ["虚"]], "19584": ["病机", "两尺脉虚，提示肾气不摄、根本亏虚，故冲胃之气上逆，肝木失和而风自内生。原文谓“肾气不摄，冲气胃气又复上逆”，致脏腑气化上升太过，血随气逆充塞脑络，发为内中风、昏厥。脉虚为肾虚不摄之征，与肝风上冲之病机相应。", ["虚"]], "19585": ["病机", "原文未出脉象，专论内中风病机。谓肝为将军之官，怒则生热，煎耗肝血，相火暴发，挟气血上冲脑部而致昏厥，即《内经》煎厥、大厥、薄厥。此段阐明内中风由肝风内动、气血上逆而成，非外风所致，与脉象无直接关联。", []], "19586": ["误治", "原文辨补阳还五汤之适用：脉虚而无力者，气虚偏枯，用黄芪峻补可效；若脉实而有力或洪实，多脑充血，复用温升之黄芪，助血上行，必致凶危。此段以脉之虚实为凭，指出不辨脉象而妄补气升阳之误治，强调脉实者忌升补。", ["虚", "实", "洪"]], "19587": ["主病", "脉弦长有力，左右皆然，为肝胆气火亢盛、气血上冲之象。原文断为脑充血证，因愤激焦思日久，肝火挟气血上逆，故脑中热、眩晕、烦躁。经镇肝熄风汤加减治疗后脉转和平，烦躁亦除，说明弦长有力主肝阳上亢、脑充血之病机。", ["弦", "长", "实"]], "19588": ["主病", "脉弦硬而长，左部尤甚，为肝胆之火上冲过甚之明征。新妇头痛，误投发表更剧，因风药升散助火。原文谓“知其肝胆之火上冲过甚也”，投镇肝熄风汤加龙胆草泻火，一剂病减，脉仍有力，继加生地养阴，脉象如常。弦硬长脉主肝火冲逆之头痛。", ["弦", "硬", "长"]], "19589": ["主病", "脉象迟弱，主阳气虚衰、气血不足。原文列身形软弱、肢体不遂、头重目眩、神昏健忘，甚则昏仆偏枯、全身痿废，断为内中风之偏虚寒者，即脑贫血病。因肝虚极亦可生风，气血不能上奉养脑，故脉迟弱无力，治当温补气血。", ["迟", "弱"]], "19590": ["病机", "原文未出脉象，专论脑贫血病机。谓脑充血因血过多伤神经，脑贫血因血过少失养，皆令神经失司。引《内经》“上气不足，脑为之不满”，说明胸中大气不升，血随气注脑者少，脑髓失养。此段从气血关系阐发脑贫血之因，与具体脉象无涉。", []], "19591": ["主病", "脉微弱无力，且重按不任，为气血大虚、脾肾不足之象。年过六旬，两腿乏力、眩仆、神昏健忘，恐成痿废，正是气虚血少、脑失所养。服补益方后脉有起色而仍不任重按，加参、冬等培补，二十余剂始愈。微弱无力脉主虚损痿废之病机。", ["微", "弱"]], "19592": ["兼症", "脉弦硬而大，为肝风内动、真气不固之象。弦主肝风，硬主劲急，大主虚张，故于主方中加龙骨、牡蛎以熄内风、敛真气，或加山萸肉以助收敛。此脉提示风动而根基不固，非单纯外风，故治法侧重镇摄。", ["弦", "硬", "大"]], "19593": ["病机", "此段论痿证三端，虽未出脉，然述病机：肌肉痹木因胸中大气虚损，致腠理不固、脉管湮淤，风寒痰涎郁塞经络；筋拘挛因脾胃弱、蕴热铄耗宗筋。脉象虽未明言，但气血虚损、经络闭塞之机已寓其中，为后文脉弦硬而大等张本。", []], "19594": ["病机", "脉弦硬而大，乃内风煽动、真气不固之象。弦为肝风，硬为劲急，大为虚张，故用龙骨、牡蛎熄内风敛真气。此脉非实热，故加石膏仅治阳明实热，加附子仅解凝寒，而主方以补大气、健脾胃、通血脉为要，脉象提示风动而真气不固。", ["弦", "硬", "大"]], "19595": ["治法", "此段述肢体受凉疼痛、凝寒阻遏血脉致麻木不仁之治法，未出脉象。病机为寒凝血脉，治当温通。虽无脉可凭，然从症测机，寒邪阻遏、血脉不通为其核心，与后文脉弦硬而大之内风真气不固者不同，此属外寒凝滞。", []], "19596": ["兼症", "脉关后微弱，关前又似滑实。关后主下焦，微弱为气血不足；关前主上焦，滑实为痰涎壅滞。此上盛下虚之象，故知上焦痰涎壅滞而致膈证呕吐，用旋覆花降痰涎，四剂而愈。脉象揭示病位偏上，痰实为标，下元不足为本。", ["微", "弱", "滑", "实"]], "19597": ["病机", "脉弦长而硬，左右皆然，为冲气挟胃气上冲之象。弦主肝，长主气逆，硬主劲急，冲脉隶属肝肾，冲气上逆故脉弦长而硬。症见气上冲咽喉、妨碍饮食、呕吐，正合冲胃之气上逆，故用旋覆花、芡实降冲逆而收敛，十剂而愈。", ["弦", "长", "硬"]], "19598": ["病机", "脉弦细无力。细因饮食菲薄而气血衰，弦因劳心过度而痰饮盛。无力为虚，弦为饮，细为血少，故脉象揭示气血两虚兼痰饮内停之机。患者勤俭劳心，自奉甚薄，正合气血衰而痰饮盛，投补虚化痰之剂而愈。", ["弦", "细", "无", "力"]], "19599": ["病机", "脉略似滑实，重按无力。滑实似痰热内壅，然重按无力，知为虚中夹实，非真有余。患者素羸弱多病，劳心过度，彻夜不寐，气血暗耗，故脉虽滑实而按之无力，乃虚火挟痰之象，治以补虚为主，佐以化痰，两剂见轻。", ["滑", "实"]], "19600": ["病机", "脉弦长有力、右部尤甚，弦为肝木之象，长为气机有余，有力示冲气上冲过甚。右部属脾胃，右甚则冲胃之气不降，迫胃气上逆，故膈证饮水难下、大便干燥。服参赭培气汤后脉稍和，正是冲气渐平、胃气渐降之征，后加半夏清痰涎而脉复常。", ["弦", "长", "有", "力"]], "19601": ["病机", "脉甚弦硬，弦主肝木、主冲气上冲，硬则示血液枯少、脉道失濡。冲气上逆兼血虚不润，故膈食不能下。吴氏于参赭培气汤中加芡实敛冲、龙眼肉滋血，一剂即能进食，正合弦硬为冲逆兼血枯之病机。", ["弦", "硬"]], "19602": ["病机", "脉浮数而濡、尺弱于寸，浮数似热，濡弱则示气血不足、血分未充。因受惊气乱血乱，经闭两月，冲为血海隶属阳明，血不下行必上逆，阳明有升无降，故翻胃吐食、便燥自汗，肢体消瘦。濡弱尺甚正是血海空虚、气机上逆之候。", ["浮", "数", "濡", "弱"]], "19603": ["病机", "原文以脉辨呕吐凉热：滑疾为热，弦迟为凉；滑而无力为上盛下虚，上热下凉；弦而有力为冲胃气逆，脉似热却非真热。滑主痰热、疾主热盛，弦主气逆、迟主寒凉，故须细审脉象并问饮食消化、呕吐改味，方能辨凉热虚实不误。", ["滑", "疾", "弦", "迟"]], "19604": ["其他", "本段专论朱砂、冰片、薄荷冰、粉甘草诸药解毒、重坠止呕、通血脉、发表透邪之功，未及脉象。其旨在于说明卫生防疫宝丹诸药配伍可解霍乱之毒、止吐泻，属治法方药之论，故脉象要素为空。", []], "19605": ["病机", "本段论霍乱（虎列拉）之病因病机：毒气随呼吸入肺，由肺传心胞，由心胞传三焦，为手厥阴、少阳脏腑相传。中气充盛则毒伏不动，若饮食过量或寒凉伤脾胃，毒乘虚袭胃肠，上下不通，遂吐泻交作，甚则上窜于脑。全段未言脉象。", []], "19606": ["预后", "霍乱上吐下泻、转筋腹疼而六脉闭塞，脉闭示毒邪盘据、气血不通、阳气一时不能外达，病情危重。服卫生防疫宝丹后吐泻渐止而愈，说明脉闭乃邪阻气机而非脏气竭绝，故预后可转佳。原文未出具体脉名。", []], "19607": ["预后", "霍乱吐泻转筋、六脉皆无，兼心中迷乱、时作谵语，脉闭而神昏，示毒邪内陷、气血阻绝，证情危笃。服卫生防疫宝丹初服仍吐，至二次脉即徐出而愈，可见脉之徐出为正气渐复、邪毒渐解之兆，脉闭非真元败绝，预后尚可挽回。", []], "19608": ["病机", "原文未提脉象，但论霍乱吐泻日久“虚极将脱，危在目前”，病机为阴阳将离、肝气欲脱。因吐泻不止，正气耗竭，故重用人参回阳，山药、芍药滋阴，山萸肉敛肝气之脱，赭石助心气下降。此段虽无脉，但所述证候与虚脱病机相应，属危重之候。", []], "19609": ["其他", "原文未及脉象，专论霍乱实热证与真寒凉证之鉴别。提出“百脉闭塞，周身冰冷”不可即断为寒，当以欲饮凉水及饮后反应辨之。此段重在辨证方法，非脉诊，故脉象要素为空。", []], "19610": ["主病", "脉弦细以涩，两尺如无，为霍乱转筋危证之脉。弦主痛主筋急，细涩为阴血亏耗、脉道不利，两尺如无则肾气衰微。症见音哑肢寒、口渴即吐、腓坚硬如石，乃邪阻中焦、肝木侮土、阴阳不相顺接之候，故以蚕矢汤清热舒筋、和胃降浊。", ["弦", "细", "涩"]], "19611": ["病机", "六脉俱伏，为霍乱吐泻、清浊相干、气乱于中之脉。伏脉主邪闭气阻，阴阳反戾，清浊升降失常，故脉气不能外达。此非寒证独有，热证霍乱亦可见伏，治宜和阴阳、分清浊，乱定则脉自出。", ["伏"]], "19612": ["治法", "原文未涉脉象，专论霍乱外治针灸之法，以素髎穴刺血为要著。其病机为吐泻交作、心中撩乱，气机逆乱。刺素髎出血可泄热开窍、调畅气机，辅药饵所不逮。此段属治法范畴，故脉象要素为空。", []], "19613": ["治法", "原文未提脉象，论述霍乱刮痧、放痧外治法。病机为周身冰冷、回血管血液凝滞不行，毒气壅遏。刮脊旁及四肢曲处，使毒气下行；刺尺泽、委中出血，助血脉流通。此段属外治治法，无脉象可录。", []], "19614": ["其他", "原文未载脉象，记妇人泄泻数月，诸药不效，脉不凉亦非完谷不化，断为脾虚不运。单用白术、枣肉为饼服之而愈，取其健脾燥湿、甘温补中。此案以脉不凉排除寒证，以非完谷不化排除肾阳虚，属辨证论治之验案。", []], "19615": ["病机", "脉虽濡弱，而无弦数之象，知犹可治。濡弱为脾虚气弱、气血不足之脉，无弦数则非肝火乘脾或热邪内迫。症见泻久身弱、虚汗淋漓、心中怔忡、饮食减少，乃脾虚及心肾、水气无出路之候，故补脾兼补心肾，后以分利小便收功。", ["濡", "弱"]], "19616": ["病机", "脉象虚数，虚为气阴不足，数为虚热内生。患者羸弱发热、不能饮食，正合脾胃虚弱、阴血亏少、虚热外浮之机。脉虚主正气亏，数主热，然此热非实火，乃因虚致热，故以山药粥补脾、玄参滋阴清热而愈，说明脉虚数在此标示虚损发热之病机。", ["虚", "数"]], "19617": ["病机", "娠妇日发痫风，脉无受娠滑象，反微似弦而兼数。弦为肝木失养、筋脉拘急，数为阴亏生热。原文断为“阴分亏损，血液短少”，血少不能濡养筋脉，肝风内动而发痫。脉失妊娠之滑而见弦数，正说明阴血亏虚、虚风内扰之病机，故以山药粥补脾生血而愈。", ["弦", "数"]], "19618": ["病机", "脉象细微浮数，细为阴血不足，微为正气衰微，浮为虚阳外越，数为虚热。患儿因苦寒伤脾，大便滑泻月余，脾胃受损，气阴两伤，故脉细微；上焦热炽、表里俱热，故浮数。此脉示脾胃虚损、虚热浮越之病机，与羸弱、恶心、不食、泻下相应，故用山药粥补脾而愈。", ["细", "微", "浮", "数"]], "19619": ["病机", "脉甚小弱，小为气血不足，弱为正气虚衰。患者漏疮日久，兼泄泻不止，肠滑不固，气血耗伤，故脉小弱，原文谓“渐已成痨”。此脉示脾肾虚损、气血亏耗之病机，与久漏久泻、精神衰惫相应。用薯蓣鸡子黄粥补脾固肠，泻止而精神焕发，说明小弱脉主虚损劳怯。", ["小", "弱"]], "19620": ["病机", "脉毫无闭塞之象，惟弦数无力，左关稍实。弦为肝木乘脾，数为有热，无力示虚。原文断为“下焦寒火交战”“上焦虚热壅迫”，故腹疼、下痢脓血、恶心呕吐。脉不闭塞而弦数无力，说明非霍乱暴证，乃痢证之剧、寒热错杂、虚实并见之病机，左关稍实示肝脾郁滞。", ["弦", "数"]], "19621": ["病机", "脉左右皆微弱，尺脉尤甚。微为阳气衰微，弱为气血不足，尺甚则病在下焦。患者溏泻不止、带红色、怔忡不食，原文断为“下焦虚寒”，兼有痢证。此脉示脾肾阳虚、下焦虚寒之病机，与久泻、怔忡、不食相应。温补下焦送服鸭蛋子而愈，说明微弱脉主虚寒泻痢。", ["微", "弱"]], "19622": ["病机", "脉象洪实，洪为热盛，实为邪实。患者下赤痢、多鲜血，脉洪实，原文断为“纯系热痢”。热毒蕴结肠道，灼伤血络，故下鲜血；邪热亢盛，正气未衰，故脉洪实有力。此脉示肠中热毒壅盛之病机，与赤痢鲜血相应，故用苦参子清热化瘀而两次即愈。", ["洪", "实"]], "19623": ["病机", "脉数而有力，两尺愈甚。数为热，有力为实，尺甚则热在下焦。患者大怒后郁热，又为外寒所束，热郁肠中，大便下血，前医误温补升提而病增。此脉示热毒郁于肠中、肠腐下血之病机，与腹中切疼、后重、便如烂炙相应，故以清热化瘀之剂两剂而愈。", ["数", "有", "力"]], "19624": ["主病", "脉洪数，纯是热象，为赤痢热毒壅盛之征。洪为热盛，数为热急，热毒腐伤肠络，故下痢血液腐败如烂炙，少腹切疼；热扰胃腑则恶心懒食。此脉证实为热痢，故治以清热凉血之剂而愈。", ["洪", "数"]], "19625": ["病机", "脉至数略数，虽非洪实有力，实无寒凉之象，说明痢久肠中蕴热，非下焦虚寒。热郁血腐，故下痢血水相杂、腐败色；热结少腹则切疼，热灼胃气则噤口不食。舌苔黄厚亦为热征，误用热砖熨腹反致肠腐，脉数正是内热之据。", ["数"]], "19626": ["病机", "脉弦而有力，弦主肝胆，有力为实，知下久阴虚而肝胆蕴有实热。热迫肠道，故腹疼重坠、赤白稠黏、日夜十余次。虽自言腹中凉甚，然脉实不受温补，投温补即痢复，改用通变白头翁汤清肝凉血而痢愈，脉实为辨证关键。", ["弦", "实"]], "19627": ["病机", "脉弦而浮，按之不实，弦为肝热，浮为热在上焦，按之不实示非实积。上焦有热故不能饮食，热迫肠道则腹疼泄泻兼痢、赤多于白。此脉说明热郁上焦而肠道滞下，非虚寒之证，故用三宝粥、通变白头翁汤清解而愈。", ["弦", "浮"]], "19628": ["病机", "脉象微弱，至数略数，微弱为气血两虚，略数为久痢阴伤有热。饮食减少、头目眩晕为清阳不升，心中烦热为虚热上扰，便时下坠作疼为气虚下陷。此脉示虚实夹杂，温补则烦热，清理则腹疼，故用平补兼清之剂而愈。", ["微", "弱", "数"]], "19629": ["病机", "脉数而细弱，两尺尤甚，数为热，细弱为阴血亏虚，尺甚示下焦虚损。痢久脓血杂脂膜，羸弱已甚，乃热毒未清而阴血已伤。服通变白头翁汤后腹疼下脓血，为瘀滞下尽之象，脉数细弱正是虚中夹热之征，故清补兼施而愈。", ["数", "细", "弱"]], "19630": ["病机", "脉近和平，按之无力，毫无数象，说明下痢两月已无热象，按之无力为下焦寒凉、气血不足。血液腐败、便时不甚觉疼、后重不剧，皆虚寒之征。前用清剂病增，后以山药粥送小茴香末温补而愈，脉无力正是寒凉之据。", ["弱"]], "19631": ["病机", "脉微弱而沉，微弱为阳气虚衰，沉为病在里，示下焦虚寒。此段答问指出痢证有寒有热，寒证久不愈肠亦可腐烂，如疮疡白硬者阴而寒。脉微弱而沉正是寒痢之征，故用热药成功，说明肠腐非皆属热，寒凝亦可致腐。", ["微", "弱", "沉"]], "19632": ["病机", "原文言服凉药而热不休，脉象确有实热，说明下痢虽久，热邪未因凉药而解，反郁于内，脉证实热为凭。实脉主邪气盛，热毒壅滞肠腑，故见赤白下重腹疼、周身发热；凉药不效正因热未清而正气未虚，当从实热论治，不可因久痢而妄补。", ["实"]], "19633": ["病机", "脉洪长有力，为外感之热与痢毒之热相合，下迫肠腑。洪长有力主实热炽盛，故见赤白胶滞、肠中热干、小便发热、腹痛下坠并迫、脊骨尽处作痛、时作眩晕。舌白苔厚亦示热邪未化，治当兼解外感，两剂诸病皆愈，脉犹有余热，可见洪长有力确为实热之征。", ["洪", "长", "有", "力"]], "19634": ["病机", "脉洪长有力，而重用黄连热如故、痢不愈，说明热邪非单纯肠腑湿热，乃实热壅盛、药轻不能胜。洪长有力主邪热炽盛，故心中发热、间作寒热、下坠过午尤甚。一剂热退痢止后脉仍似有力而无和缓之致，知痢久津液有伤，余热未净，故去白芍、柴胡加玄参、知母养阴清热而愈。", ["洪", "长", "有", "力"]], "19635": ["病机", "脉洪而无力，肌肤热烙指，为气分热痢兼受暑邪，壮火耗气，故脉虽洪大而按之无力。洪为热盛，无力为正气已伤，年六旬素多疾病，不能支持，故浑身大热、不省人事、循衣摸床。治以石膏清暑热、台参扶正气，徐饮至夜半尽剂而醒，正合洪而无力之虚实夹杂病机。", ["洪", "无", "力"]], "19636": ["病机", "脉细数无力，为痢久泻久、气阴两伤，又夹暑温之邪。细数主阴虚有热，无力主正气虚馁，故精神昏愦、气息奄奄、肌肤发热、心中觉热、舌黄苔、噤口不食。暑热弥漫胃口，虚热上逆故不能食；虚多实少，故不用石膏、人参，而以山药补虚、滑石清暑利湿，两剂全愈。", ["细", "数", "无", "力"]], "19637": ["病机", "脉象洪数，为肝胆肠胃郁热，暑月劳苦烈日，火气陡然下迫，故下痢多带鲜血，纯是一团火气，宜大苦大寒直折。若脉大而虚，则热盛而气已伤，宜加人参扶正；若洪大甚实，则邪热壅实，可大承气下之而佐白芍、知母。同一痢证，凭脉之洪数、大虚、洪大甚实以分清热之轻重与正气之虚实。", ["洪", "数", "大", "虚"]], "19638": ["病机", "脉虚甚者，为痢久清阳下陷、正气亏虚之征。清阳不升，故间作寒热、胸中短气；脉虚甚说明气虚较著，故于治痢药中加黄耆、柴胡升清阳，酌加人参补气，佐山药固下焦。此段论痢久正虚与初得兼外感两种转归，脉虚甚者当以扶正升阳为要，不可一味清痢。", ["虚"]], "19639": ["病机", "脉象数而且弦，数主热，弦主痢证气机壅滞、木邪犯土。年九旬下痢赤白甚剧，脉数弦示热邪与气滞并存，然高年阴血已亏，故用大熟地、生杭芍滋阴养血、柔肝缓急，服下即愈，再剂脉亦和平。可见弦数不尽属纯实，高年久痢当顾阴血，脉转和平即邪退正复之验。", ["数", "弦"]], "19640": ["病机", "脉象沉迟，沉主里，迟主寒，说明痢证属凉者，寒邪在里。原文指出凉痢“不过百中之一”，且多系纯白之痢，必脉象沉迟，食凉物、坐凉处则觉剧，进一步印证寒凉伤中。治以干姜、小茴香温中，佐白芍防肝胆伏热，故脉沉迟为寒痢之病机关键。", ["沉", "迟"]], "19641": ["预后", "奇恒痢脉缓小迟涩，乃阳气偏盛、阴气受伤所致。脉小迟涩示阴血亏耗，脉气平缓易被误认为常，实则“血温身热者死，热见七日者死”，预后凶险。原文强调急宜大承气汤泻阳养阴，缓则不救，若见脉气平缓而用平易之剂必误事，故本段主旨为预后判断。", ["缓", "小", "迟", "涩"]], "19642": ["治法", "脉虚甚，提示正气大虚，不任通下。原文在莱菔朴硝通结方后指出“若脉虚甚，不任通下者，加人参数钱”，以人参扶正，使攻下而不伤正。脉虚为正气不足之象，故治法上需兼顾补虚，体现攻补兼施之旨。", ["虚"]], "19643": ["治法", "脉虚不任通下，说明患者正气虚弱，难以承受朴硝咸寒攻破。原文强调朴硝“咸寒太过，损肺伤肾”，故以莱菔甘温化其咸寒、缓其攻破，更借人参大力扶持保护，使猛悍之品亦可用。脉虚为正气不足之据，治法以扶正制攻为要。", ["虚"]], "19644": ["病机", "脉虽微弱，至数不数，重按有根，说明虽病结聚不通、烦躁便闭，但正气未败，犹可任攻下。微弱脉通常主虚，但“重按有根”示胃气尚存，故断为可下之证。原文以此脉象判断病机为实结而正未大虚，故敢用赭石、朴硝等攻下。", ["微", "弱"]], "19645": ["病机", "脉甚微细，按之即无，为正气虚极之象。患者腹胀便闭，似实，但脉虚证实，故非阳明实热燥结。前医误投承气，更伤正气，致腹胀增剧、怔忡。脉微细按之即无，说明气血大亏，攻下不可，故用葱白熨法外治，继以猪胆汁导法，终得便通而愈。", ["微", "细"]], "19646": ["病机", "脉近和平，微弦无力，说明虽不大便十日，但非实热壅盛。微弦无力示肝脾不和、中气不足，肠中结而不行由寒食积滞所致。前医误用大黄附子细辛汤及保赤万应散，未效且伤正。脉近和平提示正气尚可，但无力说明推动不足，故用葱白熨法外通，赭石干姜内服止呕。", ["弦", "无", "力"]], "19647": ["病机", "脉弦而沉，两尺沉尤甚，弦主痛、主气滞，沉主里、主寒。患者房事后恣食生冷，少腹抽疼、肾囊紧缩、便闭烦躁，显系寒凝下焦、气机不通。前医投大黄附子细辛汤，两胁转疼胀，因寒滞未解而气逆。脉弦沉，尤尺沉，说明寒结在里，故用葱白熨法及赭石附子当归苏子温通降下而愈。", ["弦", "沉"]], "19648": ["病机", "原文以右部脉滑而且实为胃腑实热可下之征，滑主痰热、实主邪盛，故中消可暂用调胃承气；若饮食勤而一时不食即怔忡、脉象微弱，则非实热，乃胸中大气下陷、中气随陷，微弱为正虚气陷之象，误下则危。同篇两脉对举，正示消渴须辨虚实。", ["滑", "实", "微", "弱"]], "19649": ["病机", "少年咽干饮水不解渴，脉微弱迟濡。微、弱为阳气虚衰，迟为寒，濡为湿，合之知非肺热，乃脾胃湿寒、真火衰微，气化不升，津不上承。故用四君子加干姜、桂枝尖温补中阳，一剂渴止，正合脉证。", ["微", "弱", "迟", "濡"]], "19650": ["病机", "消渴患者饮水旋即小便、须臾数次，脉甚微细。微细为气阴两虚、气化不固之象，水饮入胃不能化津上承，直趋下焦，故渴而多尿。投玉液汤加参补气生津，加萸肉收涩固摄，渴止而尿仍数，终以固涩收功，脉证相应。", ["微", "细"]], "19651": ["治法", "原文言中上二焦积有实热、脉象洪实者，可先服白虎加人参汤数剂，消去实热强半，再服猪胰子方。洪为热盛，实为邪结，洪实并见示阳明实热炽盛，故先清后调，是消渴兼实热之先后治法，非泛言消渴皆可用白虎。", ["洪", "实"]], "19652": ["病机", "此段论消渴起于中焦，谓膵病累及于脾，脾气不能散精达肺，故渴而多饮多尿、尿有甜味。原文虽提膵之动脉自脾脉分支，然通段以脏腑气化立论，未出具体脉象，故脉象要素从缺，主旨仍在阐发中焦致消之病机。", []], "19653": ["病机", "老媪水肿，屡服峻泻之药，旋消旋肿而益衰惫，脉数而无力。原文自释：脉数者阴分虚也，无力者阳分虚也。阴虚则数，阳虚则无力，气化不行，水饮不能达于膀胱，故小便滴沥全无。此示水肿攻伐伤正、阴阳两虚之候，与实肿可下者迥别。", ["数", "无", "力"]], "19654": ["预后", "妇人水肿，脉象大致平和而微有滑数之象，平和示正气未败，滑数示水湿郁有微热，故浓煎鲜茅根汤即愈强半。原文重点在告诫忌食牛肉、避风，否则食复兼受风，一身尽肿、目不能开。脉平和而病易反复，示证轻而调护不可疏。", ["滑", "数"]], "19655": ["主病", "水肿小便不利而脉沉迟无力、自觉寒凉，沉主里、迟主寒、无力为阳虚，合之知非湿热壅结，乃脾肾阳虚、气化不行，水湿内停。阳虚不能蒸化，故小便不利而身肿；寒从中生，故自觉寒凉。此脉此证，治当温阳化气利水，与实热水肿之洪数者相反。", ["沉", "迟", "无", "力"]], "19656": ["病机", "脉沉迟如故，说明阳气未复，水饮内停。沉主里，迟主寒，服苓桂术甘汤后小便微利而脉象未变，表明上焦阳虚、水饮停滞之病机仍在，故需以生硫黄末温阳化饮，待脉象转温为效。", ["沉", "迟"]], "19657": ["病机", "原文未直接描述脉象，但论述水饮停蓄因三焦阳虚所致。上焦阳虚水停膈上，中焦阳虚水停脾胃，下焦阳虚水停膀胱，久则渐渍周身而头面肢体皆肿，甚或腹如抱瓮。治以苓桂术甘汤等助三焦之阳，阳气宣通则水饮自消。", []], "19658": ["病机", "脉浮水肿多系风水，腠理闭塞，小便不利；浮而兼数者为阴虚火动。脉沉水肿未可遽断为凉，沉而按之有力者系下焦蕴热未化；惟脉沉而且迟、微弱欲无、自觉寒凉者，方为阳虚水停，可放胆用温阳之剂。", ["沉", "浮", "数", "迟"]], "19659": ["主病", "脉浮不渴，为风水恶风、一身悉肿之证。风邪袭表，肺失宣降，水气泛溢肌肤，故脉浮；水停于内，津液未伤，故不渴。越婢汤发汗宣肺，通调水道，使水从汗解，小便自利。", ["浮"]], "19660": ["病机", "脉沉而有力，沉主里，有力为实，结合溺血、小便不通、身覆厚被犹觉寒凉，知实热郁于下焦，溺管因热肿胀不通。热郁于内，阳气不达外，故身寒；热伤血络，故溺血。治以清热利水，通利溺管。", ["沉", "有"]], "19661": ["病机", "六脉皆沉细，沉主气郁于里，细主气分不舒。患者心中发热、太息频作、胁下隐痛，为气分郁滞、郁而化热之象。服茅根后脉还浮分、重诊有力，太息止、胁痛愈，证明茅根能理气分之郁，气机宣通则脉象转浮。", ["沉", "细"]], "19662": ["病机", "脉象沉微，沉主里，微主阳气衰微。肺鼠疫之邪闭塞少阴，肾气不能上达，故咽喉唇舌干燥、精神昏昏似睡、周身肌肤不热而心中烦闷。服白虎加人参汤及茅根后脉变洪滑，是肾气上达、邪热外透之佳兆。", ["沉", "微"]], "19663": ["病机", "脉弦细至数略数，弦主肝郁气滞，细主阴血亏虚，数为郁热内扰。患者忿怒之火为外寒所束，郁于下焦，灼伤血络，故血淋兼膏淋；久病尪羸，肌肤甲错，足骨凸处旋螺高起，皆肝郁血瘀、阴血不足之征。", ["弦", "细", "数"]], "19664": ["病机", "脉微弱而迟，微弱为气阳不足，迟为寒象，故断为中气虚弱、命门相火衰微。中虚不能摄血，火衰乏吸摄之力，致肾脏失封固之职，血随小便脱出。原文‘自觉下焦凉甚’正合此虚寒病机，故用四君子加熟地、乌附子温补而愈。", ["微", "弱", "迟"]], "19665": ["治法", "本段未出脉象，专论大便下血之治法。以龙骨、牡蛎收涩补血脉破裂，去阿胶防滑肠，加龙眼肉补脾统血；虚甚重用白术、参耆，虚陷佐柴胡、升麻，虚寒佐干姜、附子。所举少妇便血月余，用理血汤加减而愈，示脾虚不统血者当以补脾升陷为治。", []], "19666": ["主病", "六脉坚数，肝脉尤甚，坚为实，数为热，肝脉独甚知热郁肝经。膏淋继血淋，溺频茎疼，气色青黑，皆湿热下注、肝火迫血之征。服理血汤后血止脉稍平，他证仍旧，继以治淋浊方清其余热，故坚数脉主实热淋浊之病机。", ["坚", "数"]], "19667": ["主病", "脉弦数无力，弦为肝郁，数为有热，无力为虚。小便频数、遗精白浊兼疼涩，乃阴虚火动、肝郁不疏而湿热下注；或咳嗽、自汗、阴虚作热，皆虚热之象。故弦数无力主虚热夹郁之遗浊淋涩，与实热洪滑有力者当别。", ["弦", "数", "无", "力"]], "19668": ["主病", "脉洪滑有力，洪为热盛，滑为湿聚，有力为实，故确系实热。小便频数疼涩、遗精白浊，乃湿热蕴结下焦，扰动精室、灼伤溺窍所致。此脉此证，主实热淋浊，治当清利湿热，与虚寒微弱或虚热弦数无力者迥异。", ["洪", "滑", "有", "力"]], "19669": ["主病", "六脉平和，似属无病，然两尺重按有力，尺候肾与下焦，重按有力知肾经确有实热。年七十余而遗精白浊、小便频数微疼涩，高年脉平而尺实，说明病非虚衰，乃实热扰动精室、下迫膀胱，故投清利实热之汤五剂而愈。", ["平", "和"]], "19670": ["主病", "脉滑而有力，滑主湿浊，有力为实热，故知系实热之证。遗精白浊、小便疼如刀剺、涩数，乃湿热毒邪下注，灼伤溺窍。年少而脉实，疑兼花柳毒淋，故于清热方中加没药、鸭蛋子以解毒散结，数剂而愈。", ["滑", "有", "力"]], "19671": ["病机", "脉弦而长，左脉尤甚，弦主肝、主风寒，长为邪气有余。小便遗精白浊因受风寒，风寒外束，肝脉郁滞，疏泄失职，故左脉独甚。此非湿热下注，乃风寒郁肝、气机不达之病机，治当散风寒、疏肝郁，与实热淋浊之洪滑数脉不同。", ["弦", "长"]], "19672": ["病机", "原文言「脉左右皆弦，而左部弦而兼长」，断为「肝木之盛也」。弦长为肝木有余之象，又因房事后肾虚受风，「风气通于肝」，肝因风助而失和，鼓动肾之蛰藏，疏泄太过，故见骗白证剧而衰惫。脉象反映肝风内动、肾失封藏之病机，非单纯外感。", ["弦", "长"]], "19673": ["病机", "「脉阴阳俱紧」因太阳外卫为风寒所袭，阳气内陷与脉相并，寒性收缩逼压脉道，使脉失起伏而现「弦直有力之象」，甚则「左右弹动」。紧脉在此示寒邪束表、卫阳被遏、脉道收缩之病机，主伤寒初起背恶寒尤甚、背连腿痛之症。", ["紧"]], "19674": ["病机", "原文谓「凡脉之紧者必有力」，紧脉有力而「转若无所起伏」，因严寒束其外表，收缩之力逼营卫之热内陷与脉相并助其有力，又遏抑脉之跳动使无起伏，故紧脉真相为「平行中见其有力」。此示外寒束表、营卫郁热内并之病机，故仲师以麻黄汤解表散寒。", ["紧"]], "19675": ["病机", "原文辨桂枝汤证「阳浮而阴弱」，关前因风而浮，关后仍微弱；若阴弱为下焦阴虚则「脉宜兼数象」，而实际「脉多迟缓，不及四至」，故知为气分虚损而非阴分虚损。脉象说明大气虚损、气分怯弱之病机，与啬啬恶寒、淅淅恶风、翕翕发热相应。", ["浮", "弱", "数", "迟"]], "19676": ["治法", "原文述「热实脉虚，心中怔忡，精神骚扰者」，以龙骨与萸肉、生石膏并用而奏效。脉虚示正气耗散、心神不敛，虽热实而脉反虚，故用龙骨收敛正气而不敛邪气，佐石膏清热、萸肉固脱。此段以脉虚为凭，讲的是热实正虚、心神耗散时的用药治法。", ["虚"]], "19677": ["兼症", "原文载外感痰喘「其喘剧脉虚」，医皆诿为不治。喘剧而脉虚，示痰壅气逆而正气已虚，攻邪恐伤正、补正恐碍邪。高氏以小青龙汤去麻黄加杏仁，佐生石膏、野台参，一剂喘定。脉虚在此提示喘证兼正虚之兼症，故用药须兼顾扶正。", ["虚"]], "19678": ["兼症", "原文未识脉名，然明言「其脉搏一息六至」，又「上焦烦躁，舌上白苔满布」，审证论脉似难挽回。一息六至为脉数，示热郁于上；前医投小青龙汤未加石膏而病剧，因「脉有热而不敢多加生石膏」。此段以脉数合烦躁、白苔，示外感痰喘兼上焦蕴热之兼症，故加石膏、参、龙牡而愈。", []], "19679": ["病机", "原文言「其脉浮洪有力，按之未实，舌苔白而未黄」，示胸中先有蕴热，又受外感，热郁胸中而烦闷喘息。浮洪有力为热盛于上之象，按之未实说明热未结聚成实，苔白未黄示邪尚在表未全化热。脉象反映胸中蕴热兼外感、热郁气逆之病机，主烦闷喘息迫促之症。", ["浮", "洪"]], "19680": ["病机", "脉浮洪而长，重按未实，浮为太阳未罢，洪长为阳明热盛。喘不能卧、胸中烦闷，是热壅上焦、肺气不降；舌苔白厚、重按不实，说明热未成实。故断为太阳余邪未解、阳明热已入里，属表里同病之机，非单纯阳明腑实。", ["浮", "洪", "长"]], "19681": ["病机", "脉浮弦、重按有力，浮主表邪，弦主少阳枢机不利，重按有力为里有实热。头疼恶寒、寒热交作、眩晕，是邪郁少阳、表里失和；心中热甚、大便五日未行，为热结阳明。此脉示表邪未净而里热已实，故用和解兼通下，下后脉不浮弦而重按仍有力，是表解里热未尽。", ["浮", "弦"]], "19682": ["病机", "脉浮数无力，浮为外感在表，数为有热，无力则正气已衰。年近七旬、素有劳嗽，痰涎壅滞、几不能息、昏不知人、身躯后挺，是外感引动宿痰、痰热壅肺、气机闭塞，兼正虚不能胜邪。浮数无力正合虚人受邪、痰热内壅之机，故治当兼顾扶正与清化痰热。", ["浮", "数", "虚"]], "19683": ["主病", "脉浮滑，浮主温邪初袭肌表，滑主热盛痰滞、气血涌盛。头疼、骨节酸疼、肌肤壮热、背微恶寒无汗，为温病初得、邪在卫表而热已渐盛；浮滑正是温邪犯表、里热初萌之象，故列为此证之主脉，示人从浮滑识温病初起之表热证。", ["浮", "滑"]], "19684": ["病机", "脉阴阳俱浮，是寸尺皆浮，为风温之邪充斥表里、阳气外浮之象。自汗出、身重、多眠睡、息鼾、言语难出，皆热邪弥漫、气机壅滞所致。仲景以脉阴阳俱浮为风温提纲，说明温病发汗后热邪未解而反灼热，此浮非表寒之浮，乃热盛气浮之浮，故主风温里热鸱张之病机。", ["浮"]], "19685": ["主病", "脉洪长，洪为阳明热盛、气血燔灼，长为热邪有余、气机亢盛。春温伏邪内蕴，至春阳动而发，表里俱热，若发于暑月则热尤甚，初得即脉洪长、渴嗜凉水，正是阳明气分热盛之征。此脉此症相应，故主大剂白虎汤清解阳明之热。", ["洪", "长"]], "19686": ["病机", "脉但浮而无热象，是风温初袭、邪尚在表而热未盛；脉浮而且洪，则表邪未解而里热已炽。原文以时序寒热参脉分别治之，说明风温之脉随邪之浅深而变：浮为邪在卫表，洪为热入阳明。脉象不同，病机浅深亦异，故治法有清解、凉解、和解之别。", ["浮", "洪"]], "19687": ["病机", "脉洪长而浮，浮为邪从表入，洪长为阳明热盛。仲夏夜凉受寒，晨起恶寒，巳时表里大热兼喘促，是外寒束表、内热骤炽，邪由太阳速转阳明。洪长而浮正示表里俱热、热势鸱张之机，故用清解汤加石膏、牛蒡子，得汗而愈，说明此脉主风温表里同病。", ["洪", "长", "浮"]], "19688": ["主病", "脉浮数而滑，浮为邪在表，数为热盛，滑主痰湿或里热。结合舌苔白厚、时时昏睡，此温病初起，热邪在气分，兼有痰湿内蕴。脉数故加玄参清热，一剂病愈，说明脉象反映表里俱热、痰热蒙蔽之病机。", ["浮", "数", "滑"]], "19689": ["主病", "脉洪而兼浮，洪为阳明气分热盛，浮为邪热有外达之势。表里俱觉发热，正是热邪充斥表里，脉象洪浮相应。此脉主温病热盛于阳明而兼表证，治当清解表里。", ["洪", "浮"]], "19690": ["病机", "原文未明确脉名，但言“两三日间，亦多见有此脉、证者”，结合上下文，此脉当指洪滑或浮洪之类，反映风温、春温、暑温等证表里俱热之病机。得汗即愈，说明邪热可从表解，脉证相应。", []], "19691": ["主病", "脉洪滑，洪为阳明热盛，滑主里热痰实。周身壮热、心中热渴、舌苔白欲黄，皆阳明气分热盛之象。头犹疼、周身拘束，是表邪未尽。脉洪滑主里热已实而兼表，治当清里透表。", ["洪", "滑"]], "19692": ["病机", "脉洪滑而渴，洪滑为阳明府热已实，渴为热灼津伤。原文明言“阳明府热已实，原是白虎汤证”，但头微疼、外表拘束，是太阳流连未去。故脉洪滑主里热实，兼表邪未尽，治当清里兼透表，使热还太阳作汗而解。", ["洪", "滑"]], "19693": ["预后", "脉浮数，右寸浮尤甚，两尺按之即无。浮为病还太阳，数为热，右寸浮为将汗之势；尺脉甚弱，为肾阴将竭，阳升而阴不能应，故汗不得作。目清白无见、循衣摸床、谵语，皆阴竭风动之危候。脉象反映正虚邪盛、阴阳不相接续之病机。", ["浮", "数", "弱"]], "19694": ["主病", "脉洪滑而浮，洪滑为里热痰实，浮为表邪未解。风寒外束不得汗，胸中烦热喘促，是表闭里热。前医误用降气散风清火，病益进。脉象示表里俱热，投寒解汤后汗出病失，说明脉洪滑浮主表寒里热、肺气壅遏之病机。", ["洪", "滑", "浮"]], "19695": ["病机", "脉虽洪而有力，仍兼浮象。洪而有力为阳明热盛，浮为太阳表邪未尽。虽迁延十余日，但头疼、渴欲饮凉水而不至燥渴，说明阳明之热未甚实，太阳之表犹未尽罢。脉象反映表里同病、热未全入里之病机。", ["洪", "浮"]], "19696": ["病机", "脉洪滑异常，两寸皆浮，右寸尤甚，为寒邪束表，热郁胸中，不得外达。洪滑主里热炽盛，浮主邪在表，右寸候肺，肺气壅遏，故烦躁益甚。此大青龙汤证误用麻黄汤，汗不得出，热无出路，故脉象如此。", ["洪", "滑", "浮"]], "19697": ["病机", "脉弦长浮数，按之有力，无洪滑之象，为外感兼内伤。弦长主肝阳上逆，浮数主外邪化热，热入阳明。素有劳疾，喘逆复发，热盛于里而脉不洪滑，乃正虚邪实之征。", ["弦", "长", "浮", "数"]], "19698": ["病机", "脉洪滑异常，为阳明热盛，热扰神明，故精神昏愦、间作讝语。舌苔白厚，热邪初入气分，尚未化燥。洪滑主里热蒸腾，气血涌盛，投寒解汤使热从汗解。", ["洪", "滑"]], "19699": ["病机", "脉竟沉细异常，肌肤不热，而咽喉疼、舌强、渴饮，为温病热郁于里，病机不能外达，脉象反现沉细。此非阴证，乃阳证之郁，舍脉从证，投寒解汤得微汗，热郁稍解。", ["沉", "细"]], "19700": ["病机", "温病脉沉细，多系阳证，因热郁于里，病机不能外达，脉道不利。伤寒脉沉细则多阴证。此段辨寒温脉沉细之异，强调温病郁热可致沉细，误认凉证必误事。", ["沉", "细"]], "19701": ["病机", "脉洪滑兼浮，为阳明热盛兼表邪未解。烦热异常，白痢滞下，乃热邪充斥表里，气血壅滞。洪滑主里热，浮主表邪，投寒解汤加芍药，表里双解，汗出热解痢愈。", ["洪", "滑", "浮"]], "19702": ["病机", "下后脉浮而微数，为邪热浮于肌表，里无壅滞；脉空虚而数，按之豁然如无，为气阴两伤，热邪未清。浮数主表热，空虚主正虚，故宜白虎汤或加人参，使邪从汗解。", ["浮", "数", "虚", "空"]], "19703": ["病机", "脉象沉浮皆有力，为表里俱实，热邪壅盛。沉取有力主里热，浮取有力主表实，表里壮热无汗，热不得外达。投寒解汤重用石膏、知母清热，少加连翘、蝉蜕透表，汗出而愈。", ["沉", "浮", "有", "力"]], "19704": ["主病", "六脉洪数，为阳明热盛之象。洪者脉体阔大，主热邪充斥阳明；数者脉行急迫，主热势炽烈。原文谓\"阳明热势甚剧，面赤气粗\"，正与洪数脉相应，热盛上蒸则面赤，热壅气机则气粗，热扰神明则时作谵语。此脉此症，皆阳明实热之明征，故用寒解汤清解里热而一剂病愈。", ["洪", "数"]], "19705": ["主病", "脉浮滑者，浮主邪在表，滑主热盛于里，为表里俱热之征。原文谓\"温病表里俱热，时有汗出，舌苔白\"，汗出为热迫津泄，苔白示热未全入里。浮滑相兼，说明热邪既浮越于表，又壅盛于里，故治当表里双解，清透并用。", ["浮", "滑"]], "19706": ["治法", "脉浮滑而兼洪象，浮为热越于表，滑为热盛于里，洪则热势更炽、脉体阔大。原文以此脉象定生石膏用量，谓\"生石膏当用一两\"。洪象愈显，说明阳明热势愈盛，故须重用石膏清解里热。此段以脉象轻重为用药剂量之依据，体现凭脉定治之法。", ["浮", "滑", "洪"]], "19707": ["病机", "脉洪滑微浮，洪滑主里热壅盛，微浮示热邪尚连表分。原文谓\"风温之热，由太阳经入于膀胱之府，阻塞水道，而阳明胃府亦将实也\"，热壅膀胱则小便涩热、周身悉肿，热盛于里则心中热渴、痰涎上泛、微兼喘息。洪滑微浮正合表里俱热、水道阻塞之机，故加石膏清透而肿消病愈。", ["洪", "滑", "浮"]], "19708": ["病机", "脉浮滑而数，重诊无力。浮滑数为上焦烦热之象，重按无力则示正气已虚。原文谓年近七旬、素患漫肿，又滑泻不止而烦热益甚，此热盛于上而气伤于下，虚实夹杂。浮滑数应上焦热，无力应高年正虚，故治以滋阴宣解，兼顾虚实，一剂泻止而愈。", ["浮", "滑", "数"]], "19709": ["病机", "脉浮数无力，浮主风热在表，数主热，无力则示正气不足。原文谓室女感冒风热，遍身瘾疹、烦渴滑泻又兼喘促，风热外袭则瘾疹，热伤津则烦渴，热迫下趋则滑泻，热壅肺气则喘促。浮数无力说明外有风热而内已伤正，故用滋阴宣解汤两剂而诸病皆愈。", ["浮", "数"]], "19710": ["病机", "脉象甚虚数者，数为有热，虚则示正气不足。原文谓\"确有外感实热，而脉象甚虚数\"，说明热邪虽实而正气已虚，故不可纯用寒凉攻伐。虚数之脉与滑泻、喘息、咳嗽、频吐痰涎并见，示热伤气阴、正虚邪恋之机，治当清补兼施，于清热中顾护正气。", ["虚", "数"]], "19711": ["病机", "脉似洪滑，重诊指下豁然，两尺尤甚。洪滑似实热，然重按豁然中空，则为虚象，两尺尤甚示下元亏虚。原文谓妊妇小产、上焦燥渴喘呻、痰涎壅盛，又转添滑泻，此热盛于上而正虚于下，脉似实而实虚。故先以山药石榴固涩止泻，再诊洪滑较实，方敢清解实热。", ["洪", "滑", "虚"]], "19712": ["病机", "脉数至七至而微弱欲无，为暴虚之象，非久病虚损。伤寒过旬，瘦弱昏愦，过午发热咳喘，乃阴液暴伤、虚热内扰。脉数主热，微弱示正气骤虚，根柢未损，故投滋阴清燥汤得愈。", ["数", "微", "弱"]], "19713": ["病机", "脉甚细数，按之微觉有力，细为阴伤，数为热，微有力示虚热内蕴。年近七旬，羸弱卧床，受温病后发热咳痰稠黏、精神昏愦，乃阴虚燥热之候，故用滋阴清燥汤加减而愈。", ["细", "数"]], "19714": ["病机", "原文未识脉名，仅言「脉尚有根柢」。温病邪在表，误投苦寒致滑泻不止，上焦燥热、闭目而喘、精神昏愦，乃燥热伤阴、下久亡阴。脉有根柢示生机未绝，故用滋阴清燥汤清燥止泻而愈。", []], "19715": ["病机", "脉象洪数，重按无力，洪数为热盛，无力为虚。伤寒误治，大便滑泻无度，上焦烦热谵语，乃燥热内炽而气阴两伤。脉虽不实仍有根柢，至数不过六至，知犹可治，故用白虎加人参汤清补兼施。", ["洪", "数", "虚"]], "19716": ["病机", "脉如水上浮麻，不分至数，按之即无，惟两尺似有根，为虚甚欲脱之象。膨胀证误用辛燥开破，致烦渴泄泻、奄奄一息，乃气阴耗竭、中气将败。脉虚甚且气息将脱，故于滋阴清燥汤中加参、萸以固脱。", ["虚"]], "19717": ["病机", "脉洪滑而长，洪滑主实热内蕴，长为气机壅盛。胸中素蕴实热，又受外感，内热为外感所束不得发泄，故烦躁、喘或胸胁疼。此脉象示表寒束热、热郁胸膈之病机。", ["洪", "滑", "长"]], "19718": ["病机", "脉浮洪而长，浮为外感，洪长为郁热炽盛。胸疼连胁、心中发热，服理气清火不效，乃上焦郁热为风寒所束，风寒与郁热相搏而作疼。脉浮洪长正合外束内热之机，故用此汤加没药、川楝子得汗而愈。", ["浮", "洪", "长"]], "19719": ["病机", "脉洪长浮数，洪长主热盛，浮数示外感。年过七旬素有劳病，冬令伤寒劳病复发，喘咳痰涎壅盛、上焦烦热，乃外寒束内热、痰热壅肺之候。脉证相合，故投此汤加玄参、潞参一剂汗出而愈。", ["洪", "长", "浮", "数"]], "19720": ["病机", "脉象洪滑，为外感痰喘之候。洪为热盛，滑主痰壅，痰热交阻于肺，故喘剧。四五日间脉洪滑，舌苔白微黄，示表邪未净而里热已生。服石膏、连翘后汗出热退，脉转平和无力，乃邪去正伤，故去苏子加潞参以扶正。此段以脉象动态说明痰热壅肺、表里同病之机。", ["洪", "滑"]], "19721": ["主病", "脉象洪滑而不甚实，主寒温阳明证之表里俱热。洪为阳明热盛，滑为里热蒸腾，然不甚实，说明热虽盛而燥结未成。症见心中热、嗜凉水而不至燥渴、舌苔白厚或微黄、背微恶寒，皆热郁气分、表邪未尽之象。此脉此症，为白虎汤类方之的证。", ["洪", "滑"]], "19722": ["病机", "脉洪大有力，继而益洪实，主伤寒热入阳明之府。洪大为阳明经热炽盛，实为府热内结。头疼异常、彻夜不寝，乃经府之热相并上逆冲头；便三日未行、舌苔白厚，示热已入府而燥结未甚。初误作表证汗解不效，脉反益实，说明热势深入，故用竹叶石膏汤清其余火而愈。", ["洪", "大", "实"]], "19723": ["治法", "本段未载脉象，专论竹叶石膏汤治寒温大热退后之余热。其旨在于：大热铄涸之余，必兼虚热，故用石膏清热、人参复阴，使真阴顿复而余热自消。又论麦冬黏滞，得石膏、半夏则不留邪。此段从方义阐明治法，说明余热未清、真阴已伤之病机，非以脉断证。", []], "19724": ["主病", "脉洪而长，主暑温兼感。洪为热盛，长为气分热炽而邪势方张。童子暑日力田，陡觉发热无汗、烦渴引饮，脉证合参，知为暑热内逼、表气不通。洪长之脉见于新病，示邪热充斥气分而未入营血，故投仙露汤清透暑热，未尽剂而愈。", ["洪", "长"]], "19725": ["预后", "脉关前洪滑、两尺无力，主上焦热盛而下焦虚寒。关前洪滑为心肺热壅，尺弱为肾气不充。本应徐徐饮药防寒凉侵下，竟顿饮致滑泻、鼻如烟熏、面如火炙，关前脉大于前倍、数至七至，已成戴阳之证。此段以脉象变化示误治后虚阳上浮、阴寒下逼之危候，关前洪滑数愈盛而尺愈弱，预后堪忧。", ["洪", "滑", "数"]], "19726": ["治法", "脉近虚数者，主阳明应下而正气已伤。虚为津液不足，数为余热未清。此段论阳明应下证，先投大剂白虎汤清之，使实火消而津液自生，大便自通；若仍不通，则用玄明粉、蜂蜜润下，或生大黄末通其大便。以脉虚数，故避承气之猛，取白虎润下之缓，示人避难就易之法。", ["虚", "数"]], "19727": ["病机", "脉洪长有力，主伤寒阳明热盛。洪为热炽，长为邪实气分。表里俱热、烦渴异常、大便未行，服白虎加人参汤后便通而脉仍洪长，细审乃肠有匿藏结粪，故单用大黄下结粪而病愈。此段说明洪长脉持续不退，为热与燥屎互结之征，下后脉净身凉方为向愈。", ["洪", "长"]], "19728": ["病机", "脉变为弦象，原文谓“弦主火衰，亦主气虚”。此因重用石膏清解太过，阳明火实虽退而元气亏损，不能运行白虎汤凉润之力，故大便不通。弦脉在此非主肝胆气郁，而主火衰气虚，与精神恍惚、便闭相应，故单用人参补气而便通。", ["弦"]], "19729": ["主病", "温病初得，脉浮而有力，浮为邪在表，有力为热盛，故身体壮热。此属温病初起、热郁肌表之证，与“身不恶寒而心中发热”相应。若热已入阳明之腑，亦可用代白虎汤清解，说明此脉主温病初起之实热。", ["浮", "数"]], "19730": ["病机", "脉洪大无伦、按之甚实，为阳明腑热至极之象。洪大为热盛，实为邪结，故见昏昏似睡、大声呼之毫无知觉。外治以冰反使热愈内陷，故重用生石膏清阳明实热，热退则神醒。此脉主阳明腑实热盛之病机。", ["洪", "大", "实"]], "19731": ["主病", "脉甚洪实，洪为热盛，实为邪实，主瘟病热毒炽盛、内陷阳明之证。症见神昏如睡、高呼不觉，为热扰神明。故用石膏粳米汤重用生石膏清解实热，热清则神安。此脉主瘟病阳明实热之病机。", ["洪", "实"]], "19732": ["病机", "脉洪滑有力，洪为热盛，滑为痰热内壅，有力为实，主温证热盛于阳明、胃气上逆之病机。症见呕吐、心下满闷、热而且渴、舌苔黄厚，皆热郁胃腑、痰热上逆所致。故用白虎汤加减托邪外出，清胃热而止呕逆。", ["洪", "滑", "数"]], "19733": ["主病", "脉象细数，细为阴伤，数为热盛，主寒温实热已入阳明之府而兼阴液耗伤之病机。症见燥渴嗜饮凉水，为热盛伤津之象。细数脉说明热实而阴亏，故治当清阳明实热兼顾阴液，非单纯攻下所宜。", ["细", "数"]], "19734": ["治法", "脉虚者、或虚数、或细微，主元气素弱而阳明热炽之病机。虚为元气不足，数为热，细微为气阴两伤。此脉说明正虚邪实，故宜白虎加人参汤，以人参补元气、山药固摄下焦，使清解而不伤正，既祛实火又清虚热。", ["虚", "数", "细", "微"]], "19735": ["病机", "脉甚虚数，虚为元气不能支持，数为邪火横恣，主“脉虚证实”之病机。症见昏愦不知人、肌肤烙手，确有实热，而素羸弱劳嗽，元气亏虚，故邪火虽盛而正不能支。此脉说明正虚邪实，故放胆投白虎加人参汤，扶正以祛邪。", ["虚", "数"]], "19736": ["病机", "脉象细数按之无力，细为阴血不足，数为有热，无力为虚，合示气阴两虚、虚热内扰。原文“脉虚”故加参，然略用清火即滑泻，说明下焦气化不固，虚热在上、不固在下，故先固下焦再清上中。", ["细", "数", "虚"]], "19737": ["病机", "脉结代为气血虚衰、脉道不续之险脉，故仲景炙甘草汤用干地黄以滋阴养血复脉。原文以熟地黄救寒温危证，并指出结代属险脉，说明此脉主气血亏虚、心脉失养之病机。", ["结", "代"]], "19738": ["病机", "初诊脉微弱而浮，为素弱感寒、正气不足之象；误温补后脉转细而数、按之略实，细数主阴伤热炽，略实示热结阳明。原文“上有浮热”与“脉细而数”相应，说明误治后虚热浮越、里热未清之病机。", ["微", "弱", "浮", "细"]], "19739": ["病机", "脉数至六至、浮分摇摇、按之若无，数主热，浮摇无根为阴虚阳浮、正气外越。原文“心为热迫”“怔忡”与脉数浮虚相应，说明外感日久、气阴两伤、虚热上扰之病机。", ["数", "浮", "虚"]], "19740": ["病机", "脉确有实热而数至七至、摇摇无根，实主邪热内盛，数主热炽，无根示资禀素弱、劳心伤阴，热盛而正不支。原文“呼吸迫促”“痰血相杂”与实热数脉相应，说明热壅肺络、灼伤血络之病机。", ["数", "实"]], "19741": ["病机", "初脉象虽实却非洪滑，实而不洪滑示热结阳明而正气已伤；再诊脉微热退、谵语益甚，脉微为正气衰微，热退而神昏示正不胜邪。原文“精神昏昏，不省人事”与脉微相应，说明气阴两竭、邪陷心包之病机。", ["实", "微"]], "19742": ["病机", "此段论白虎汤加人参之脉候：脉现虚弱之象，或脉象虽实而无洪滑之象，或脉有实热而至数甚数，皆示热盛而正气已伤。原文“劳心过度”“劳力过度”“老年”“宿疾”说明正虚之由，故脉实无洪滑、数甚者，主热盛正伤之病机。", ["虚", "弱", "实", "数"]], "19743": ["病机", "脉象洪数按之无力，洪数为阳明实热之象，无力为汗出过多、气阴外泄之征。原文“表里大热”“汗出淋漓”“怔忡”与洪数无力相应，说明热盛于里而表里皆虚、心气浮越之病机。", ["洪", "数", "虚"]], "19744": ["病机", "脉结代而洪滑，按之有力，为外感实热内盛，气血运行受阻，脉道不利而现结代；洪滑主热盛于内。然重按无力，又示正气已伤。故用白虎加人参汤清热益气，加生地滋阴，使脉转调匀有力。", ["结", "代", "洪", "滑"]], "19745": ["治法", "脉甚洪实，为热盛邪实之象，年过六旬者正气渐衰，虽脉实亦不可纯用寒凉攻伐，故用白虎汤时少加人参以扶正，防苦寒伤气，体现攻补兼施之治法。", ["洪", "实"]], "19746": ["病机", "脉洪实异常，至数不数，右部有止无定数，为结脉，主温病大实之证，热结于内，气血壅滞，脉道时阻；下血日久，正气亦伤，故结脉益甚，腹中觉胀，得诸恼怒，气机郁滞。", ["洪", "实", "结"]], "19747": ["病机", "脉象虚数，按之不实，为气阴两虚，虚热内扰；舌干因真阴亏损或气虚不上潮，治宜白虎加人参汤，多用人参补气，减石膏加玄参、生地滋阴，使气旺津生，虚热自退。", ["虚", "数"]], "19748": ["病机", "脉微细而数，按之无力，为胸中大气下陷，气陷不能托火外出，脉道瘀塞，津液不能上潮，故舌干缩、频饮凉水不解；虽似实热，实为虚陷，治以白虎加人参汤补气托邪。", ["微", "细", "数"]], "19749": ["治法", "脉虚数而舌干，为气阴两虚，虽有便闭舌黑，亦不可下，下之更伤气阴；宜白虎加人参汤加减，使大便徐通，火退舌润，若下后滑泻，则用滋阴固下汤，气陷者单用人参。", ["虚", "数"]], "19750": ["治法", "下后不解，脉象不虚弱者，仍可依白虎加人参汤原方；若脉更兼虚弱，则正气已伤，以山药代粳米、生地代知母，兼顾气阴，防寒凉伤中，体现凭脉辨治、攻补适宜。", ["虚", "弱"]], "19751": ["病机", "脉细数，按之无力，为真阴太虚，虚热内炽，高年温证，阴液亏耗，故舌干缩、精神昏愦；细数无力主阴亏，治以白虎加人参汤滋阴退热，或重用熟地、山药、枸杞以填阴。", ["细", "数"]], "19752": ["病机", "脉洪滑而长，重按有力，为阳明实热炽盛之象。洪为热盛，滑主痰热内壅，长则气分热炽，重按有力更证实热内结。患者烦热燥渴，舌苔白厚中心微黄，皆热盛津伤之征。虽年高而火甚实，故投白虎加人参汤清泄阳明，热渴俱愈。", ["洪", "滑", "长"]], "19753": ["病机", "此段总结前案，强调“随病、脉之虚实”灵活加减。前案脉洪滑而长、重按有力，为实热，故重加生石膏；此案则辅以熟地、枸杞滋真阴，当是脉虚而热不实。脉之虚实决定治法，实者清泄，虚者滋补，故投之辄效。", []], "19754": ["病机", "脉变洪长，为阳明实热内盛之象。洪主热盛，长主气分热炽，此因瘫痪基础预伏于内，复感伤寒，两病偕来，热邪入阳明，故脉由前之散风补气理痰证转为洪长。脉象已现阳明实热，当投白虎加人参汤清之，迟延则病势垂危。", ["洪", "长"]], "19755": ["病机", "脉数近六至，虽非洪滑鼓指，而确有实热；脉象不洪滑者，元气素虚故也。数主热，虚因元气不足。舌苔微黄而毫无津液，脉数液短，兼有真阴虚损之象，尤忌发汗。此阳明府热而兼虚，故宜白虎加人参汤，清热兼益气阴。", ["数", "虚"]], "19756": ["病机", "产后温证，心中燥热，舌苔黄厚，脉象洪实，为阳明府实热之征。洪主热盛，实主邪结。虽产后体虚，然热实脉实，亦宜白虎加人参以山药代粳米汤，更以玄参代知母。若脉不甚洪实，则热较轻，可重用玄参。此示产后温证凭脉辨虚实以定治法。", ["洪", "实"]], "19757": ["病机", "病脉皆甚实，指症状与脉象均现实象，为产后温热、阳明胃府大实之征。实脉主邪气盛，虽产后体虚，然脉实证实，非用白虎加人参汤清泄不可。药坊拘于产后忌寒凉之说，延误病机，终致垂危，后如法服之而愈，证明凭脉辨证之要。", ["实"]], "19758": ["病机", "脉浮数有力，重按甚空，为阳明热极、阴分将竭之象。浮数有力主热盛于外，重按甚空则阴液内竭，脉体不实。此因误服桂枝、柴胡之坏证，热渴喘促，头汗自出，舌苔深灰。急投白虎加人参汤，连服两剂，脉不浮数而仍有力，热退阴复。", ["浮", "数", "虚"]], "19759": ["病机", "脉弦数有力，一息七至，为热盛阴伤、肝胃热炽之象。弦主热郁，数主热盛，有力为实。产后误用热药发汗，致热渴喘促，舌苔干黑，循衣摸床，皆热极阴伤之危候。急投白虎加人参汤，重用生石膏，加生地、白芍，清热救阴，尽剂而愈。", ["弦", "数", "实"]], "19760": ["病机", "脉细数有力，细为阴血亏虚，数为热盛，有力示邪实。产后血虚复感温病，又误服补药，致外邪无由而出，内热如焚，阴血告罄。热扰神明则谵语发狂，阴伤则舌黑唇焦、目睛直视，热结下焦则小便赤涩、大便紫黑黏滞。此脉主阴虚热盛、邪热内陷之病机。", ["细", "数"]], "19761": ["病机", "初诊脉尽伏，乃阳极似阴、热深厥深，热邪闭遏阳气不能外达，故身冷厥逆、气息将无。泻止后脉出洪长滑数，右部尤甚，洪长为阳明热盛，滑数为邪热炽盛，右部尤甚主气分热实。此脉由伏转洪，示热邪外透，病机由热厥转为阳明实热。", ["伏", "洪", "长", "滑"]], "19762": ["病机", "脉数近八至且微细无力，数为热盛，微细为阴血大亏、正气不足。温病小产，邪热太甚而阴分耗伤，故舌缩不能伸、神气恍惚；热迫大肠则大便滑泻。此脉主邪热炽盛而阴血亏虚、正虚邪实之病机，故治以滋阴清燥、白虎加人参，兼顾产后阴亏。", ["数", "微", "细"]], "19763": ["病机", "脉象数而不实，数为热盛，不实示正气已虚。年近七旬，素有劳疾，阳明府热炽盛而正气不足，故喘嗽吐痰稠黏，热退后气息微弱似不接续。此脉主热盛而气阴两虚之病机，故用白虎加人参汤，以山药代粳米，清热兼扶正。", ["数", "虚"]], "19764": ["病机", "脉细数，按之略实，细为阴伤，数为热盛，略实示邪结。表里俱热，胃口杜塞，腹中疼痛，饮水即吐，大便不通，乃热结阳明、胃气上逆，吐久伤津故脉细。此脉主热结胃肠兼阴伤之病机，故治以清热通下兼养阴，便通而愈。", ["细", "数", "实"]], "19765": ["病机", "脉浮滑，浮主表邪未罢，滑主痰涎壅盛。温病两三日，痰涎郁塞胸膈，频频咳吐黏若胶漆，喘促，饮水停滞，头疼，乃外感引动痰饮、表里同病。此脉主表邪未解、痰热壅阻之病机，故师双解散之意，解表兼荡痰，微汗便通而愈。", ["浮", "滑"]], "19766": ["病机", "脉沉滑而实，沉主里，滑主痰，实主邪结。中脘郁结，饮食不下仍上逆吐出，舌苔白微黄，表里俱热不甚，素多痰饮，受外感益甚，乃外感之邪与痰饮相凝滞于中脘。此脉主痰热结聚、气机壅塞之病机，故用荡胸汤开结化痰。", ["沉", "滑", "实"]], "19767": ["病机", "关前脉洪实，一息五至余，上盛于下一倍。洪实为阳明热盛，数因吐久伤津。温病十日，上焦燥热，呕吐，大便燥结，热结胃腑、胃气上逆，故关前独盛而作呕吐。此脉主热结阳明、胃气上逆兼津伤之病机，故一剂热退呕止便通。", ["洪", "实", "数"]], "19768": ["主病", "脉洪滑有力，关前益甚，洪为热盛，滑为痰实，关前候上焦心肺，故主热毒壅于头面、上焦烦热、心中怔忡。头面肿大疼痛、两目肿不能开，皆热毒上攻之象；洪滑有力说明邪实正未虚，故投清盂汤重用石膏清解而愈。", ["洪", "滑"]], "19769": ["主病", "脉洪滑而长，洪为阳明热盛，滑为热毒挟湿，长为热邪有余之象。头面悉肿、皮肤含黄水溃烂、身有斑点，皆热毒入胃随胃气外现；烦热嗜凉物亦胃热之征。脉证相合，故放胆用生石膏、知母清胃解毒而愈。", ["洪", "滑", "长"]], "19770": ["病机", "原文脉尽伏、举按皆无，舌苔滑，两颧赤如火而语言不乱。吕沧洲断为血为邪热所搏，掉而为斑，外现皮肤，血伤则脉不见，如沟渠之水无风不能成波澜，故斑消则脉出。此非坏证，乃热毒发斑、血伤脉伏之病机，与白虎加人参汤化斑后脉复常。", []], "19771": ["病机", "六脉沉细，沉为在里，细为阳虚，与肌表虽热、按之须臾冷透如冰相合，说明内真寒而外假热。斑出数点随出随隐、语言狂乱非谵语，皆阴寒内盛、虚阳外浮之象，故用姜附等温里，得大汗而愈，此阴毒发斑之病机。", ["沉", "细"]], "19772": ["病机", "六脉沉细，昏沉不知人事、不能言语、身冷厥逆、通身黑斑而心头温暖，沉细主阳气衰微、伏火内郁。因凉药太过伤阳，阴寒外闭而伏火不能透达，故斑黑肢厥；用参附姜温通，斑色渐红、手足渐暖，说明沉细所主为阴毒发斑中有伏阳之病机。", ["沉", "细"]], "19773": ["病机", "本段未识出脉名，专论瘟疫之毒传变路径。原文言毒随呼吸入肺，心与肺同居膈上、血脉相通，其相传似易，而包络护心代受邪，由包络下传三焦，为手厥阴、少阳脏腑相传，故心不易受邪。此讲疫毒传心之病机与包络代受之理，非脉象主病。", []], "19774": ["主病", "脉甚洪数，洪为热盛，数为热急，与周身壮热、疹稠密、舌苔白厚相合，说明疹而兼瘟、热毒壅盛。洪数有力示邪热炽于气分，故初用轻剂不应，热益甚、鼻衄烦躁，重用生石膏、玄参、麦冬清解后诸证轻减，脉象主热毒壅盛之病机。", ["洪", "数"]], "19775": ["病机", "脉象弦而无力，弦为肝木乘脾、疟邪留于少阳，无力则示久疟正虚、气血耗伤。久疟不愈，邪伏膜原而正气已衰，故脉弦而不任按。此脉所主为久疟正虚、邪恋不去之病机，与久疟不愈之症相应，治当扶正截疟兼顾。", ["弦"]], "19776": ["病机", "原文谓疟邪不专在少阳而实以少阳为主，故六脉恒露弦象。弦为少阳木气之象，疟邪伏于少阳经，脉气应之而弦。先寒为少阳之邪外与太阳并，后热为内与阳明并，说明弦脉在此标示疟邪盘踞少阳、出入太阳阳明之病机，非单纯表证或里实。", ["弦"]], "19777": ["病机", "原文言凡疟脉皆弦，此案脉象弦长重按甚实。弦主疟邪伏于少阳胁下，长为阳明火盛之象，重按实说明热盛于气分。故断为阳明火盛，投大剂白虎汤加柴胡，以清阳明而升提少阳疟邪，脉象直接指示热盛邪实之病机。", ["弦", "长", "实"]], "19778": ["病机", "温病热入阳明之府，舌苔黄厚，脉象洪长。洪为阳明热盛、气分燔灼之象，长为热邪亢盛之征。又间日寒热，是温而兼疟。脉洪长紧扣阳明府热，说明热势炽盛而正气素虚，故用白虎加人参汤清补兼施，少加柴胡以兼顾疟邪。", ["洪", "长"]], "19779": ["病机", "原文明言弦为疟脉，其长而有力者显系有伏暑之热。左右皆弦长有力，弦主疟邪，长而有力主伏暑化热内蕴。服金鸡纳霜反复不愈，脉仍弦长有力，说明伏暑之热未清、疟邪未除，故用白虎汤重用石膏清暑热，加柴胡、何首乌以截疟。", ["弦", "长"]], "19780": ["病机", "脉细如丝，微有弦意，至数如常。细为气血亏虚、资禀素弱之象，弦意示肝气郁结。家务劳心致怔忡、胸腹胀满、不能饮食，舌黑便结，皆由气血虚而肝郁化燥。脉细如丝说明正气虽弱而胃气未败，故曰犹可治，以升降汤培补疏达取效。", ["细", "弦"]], "19781": ["病机", "左部弦细，右部似有似无，一分钟数至百至。弦细主肝郁血虚，左部应肝，肝郁不舒则筋挛；右部似有似无示脾土受伤、气血不足；数至百至为气逆作喘、郁而化热之征。合观四肢痉挛、呼吸短促、胸中胀闷，说明肝郁侮脾、筋脉失养之病机。", ["弦", "细", "数"]], "19782": ["病机", "他部皆微弱，惟左关沉而有力。微弱为气血不足之常象，左关独沉而有力，沉主病在里，有力主实邪结聚。左关应肝，胁下掀疼正属肝经部位，说明他部虚弱而肝经局部有实邪郁结，故用金铃泻肝汤加当归，下绿色黏滞之物而愈。", ["沉", "微", "弱"]], "19783": ["病机", "脉弦细，至数微数。弦主筋脉拘急、寒邪内陷，细为气血两伤，数示郁而化热。原文析热砖熨益疼为逼寒内陷，发汗药伤气血，吐血便结为过热所致。脉弦细数正合寒陷筋骨、气血受伤而兼郁热之病机，故见腿痛、忽歌忽哭等症。", ["弦", "细", "数"]], "19784": ["病机", "脉数而有力，微有弦意，数主热，有力为实，弦主筋病、木盛。结合症见筋缩疼、腰背强直，知为宗筋受病，胃腑燥热，津液短少，不能荣养宗筋，故脉数有力兼弦。", ["数", "弦"]], "19785": ["病机", "脉微弦，弦为肝木之象，微弦提示木气偏盛。原文谓“恐其木盛侮土”，故加芍药和肝扶脾胃。此脉说明肝木乘土，胃腑燥热津亏，宗筋失养而拘挛作疼。", ["弦"]], "19786": ["病机", "两尺洪实，洪主热盛，实主邪结。尺部候下焦，洪实说明下焦先有蕴热，又为凉物所迫，热愈结而不散，故脐下剧疼。虽食冷饼，疼非凉疼，乃热结之证。", ["洪", "实"]], "19787": ["病机", "脉迟滞而细，迟主寒、主滞，细主虚。劳苦过甚，气力不支，寒邪乘虚客于经络，气血滞涩，故两腿抽疼、身冷、小溲不利。迟滞细脉反映寒凝络瘀、阳气不宣之病机。", ["迟", "细"]], "19788": ["病机", "右脉洪数有力，洪数主热盛，有力为实。右膝红肿热疼、小便赤热、便闭，显系湿热下注。洪数有力之脉与局部红热肿疼相应，说明湿热壅盛于下焦经络。", ["洪", "数"]], "19789": ["病机", "原文未出脉象，主论寒在经络不在脏腑。经络行于肌肉之间，寒邪客之则血脉凝涩，故用黄芪温补肌肉为君，佐温通经络之品，使血活风去，搐止。此段阐发寒客经络、血滞风动之病机。", []], "19790": ["病机", "右关甚濡弱，右关候脾胃，濡弱主脾胃气虚。询其饮食减少，正合脾胃虚弱、气血生化不足，不能充养腰腿，故腿疼腰疼。濡弱脉说明病本在脾胃气虚，非外邪实痛。", ["濡", "弱"]], "19791": ["病机", "脉大而且弦，然心中无热，非火象。大乃脾胃过虚、真气外泄；弦乃肝胆失和、木盛侮土。年近七旬，陡然腿疼，脉大弦而无力，说明虚中夹木旺，治当补脾胃、抑肝胆。", ["大", "弦"]], "19792": ["病机", "原文言“治肝虚腿疼，左部脉微弱者”，左部候肝，脉微弱为气血两虚之象，肝经气血不足则筋脉失养，故见腿疼。脉微弱直接反映肝虚本质，非气滞血瘀之实，故治法当补肝气血，而非舒肝理气。此脉与肝虚腿疼症候相应，提示病机在肝之气血虚弱。", ["微", "弱"]], "19793": ["治法", "原文为服药后“左脉仍不起者”的加减法，属治法调整。左脉不起说明肝气未复，故加续断、生黄耆以助气分，觉凉则减知母。此段无独立脉象描述，主旨在于根据脉象变化调整方药，体现以脉测证、随脉施治的思路，非论病机或主病。", []], "19794": ["病机", "原文述大怒后腿疼，医者用舒肝理气药反剧，诊得“左脉甚微弱”，断为“过怒则伤肝”伤其气血，非郁其气血。肝主疏泄，藏相火，肝虚不能疏泄则相火郁于经络，故疼处觉热。脉微弱正是气血虚弱之征，与肝虚腿疼、疼处发热症候相应，说明病机为肝经气血虚损而非气郁。", ["微", "弱"]], "19795": ["病机", "原文载“右脉和平如常，左脉微弱，较差于右脉一倍”，左候肝，微弱示肝木之气虚弱，不能条畅敷荣，所寄相火郁于左臂经络而作热，故左臂发热酸软。屡投凉剂伤脾胃，故消化力减。脉微弱与肝虚、臂热酸软相应，说明病机为肝气虚不能疏泄，相火郁滞经络。", ["微", "弱"]], "19796": ["病机", "原文言“其脉亦右部如常，左部微弱”，两胁下连腿作疼如锥刺、尿道艰涩。左脉微弱示肝气虚弱，肝气不能壮旺上达则下郁而作疼；肝虚不能为肾行气，故小便滴沥。服药后左脉较前有力而疼减、小便顺利，反证脉微弱主肝虚气弱、疏泄失职之病机。", ["微", "弱"]], "19797": ["其他", "此段论铁锈、金鸡纳霜、花椒之药性功用，言铁锈荣养血分、流通经脉，金鸡纳霜治贫血调寒热，花椒济其寒凉。全段未涉及脉象描述与脉诊判断，主旨为方药配伍原理，故归其他，脉象要素为空。", []], "19798": ["妇人", "原文述东亚人中将汤调妇女经脉恒有效验，门人寄方未有分量，作者酌定分量用之有效。全段主旨为妇女调经方剂，属妇人经脉不调之治，未涉及具体脉象描述，故脉象要素为空，category归妇人。", []], "19799": ["妇人", "原文列中将汤十二味药物及浸服方法，言方中凉热补破涩滑之药皆有，分量适相当，凡妇女经脉不调皆可服，治白带证尤效。全段论妇人调经方药与服法，未言脉象，故脉象要素为空，主旨属妇人经脉不调之治。", []], "19800": ["治法", "原文言“脉象虚数者，去三棱、莪术”，虚数之脉主正气亏虚而兼有热象，故于消症瘕方中减破血之品，防其更伤气血。虚数示体弱不耐攻伐，与“身体羸弱”相应，故调整方药以顾护正气。", ["虚", "数"]], "19801": ["预后", "脉虽虚弱而“至数不数”，说明气血虽亏但无热象，胃气尚存，故“许为治愈”。虚弱之脉主正气不足，与症瘕日久、饮食减少、昏愦等症相应，因脉不数，示无邪热伤阴之虞，预后尚可。", ["虚", "弱"]], "19802": ["预后", "脉甚微细主气血大虚，然“犹喜至数调匀”，说明胃气未败，故“知其可治”。微细与气弱、心腹满闷、不能饮食相应，至数调匀则示生机尚存，故用理冲汤减破血药而获效。", ["微", "细"]], "19803": ["预后", "原文未识脉名，但言“幸脉有根柢，犹可调治”，根柢即脉有胃气、肾气之根，虽症瘕满腹、久病剧甚，脉有根则生机未绝，故可任攻补兼施之剂，预后尚可。", []], "19804": ["病机", "脉微细稍数，微细主气血亏虚，数主有热，与痃癖结于少腹、坚硬如瓜、饮食减少、形体羸弱相应，示正虚而兼郁热，故用理冲汤补破兼施，服后痃癖全消。", ["微", "细", "数"]], "19805": ["病机", "右脉弱而且濡，右脉主脾胃，弱濡示脾胃气虚且湿滞，与“分毫不敢多食，多即泄泻”相应，脾虚不能统血则经行不止且多，故用安冲汤去黄耆、重用白术以健脾止泻摄血。", ["弱", "濡"]], "19806": ["病机", "脉洪滑有力，洪滑主实热，与心中热而且渴相应，初疑血热妄行，然清热凉血不效，后悟兼外感，洪滑有力实为外感邪热内迫，故改用白虎加人参汤清解外感，火消而血止。", ["洪", "滑"]], "19807": ["病机", "左关尺及右尺浮弦，一息五至强，浮弦主肝气不畅，数主有热，与经水行时多而且久、口干、腰疼无力相应，乃血亏有热、肝气不舒，故用安冲汤加减养血清热疏肝而愈。", ["浮", "弦", "数"]], "19808": ["病机", "右脉弦细、左脉弦硬，弦主肝郁，细为血虚，硬乃肝气冲激之象，因劳心过度，肝失疏泄，冲脉不固而小便下血。后脉尚和平，知昏迷非病进，乃黄耆升补太过，气血上逆所致，故加赭石镇降而愈。", ["弦", "细", "硬", "和平"]], "19809": ["病机", "六脉细数，细为阴血亏虚，数为虚热内生。下血不止，面唇皆白，乃血脱不能上荣，阴亏生热，热迫冲脉，故脉细数。治以安冲汤重用山萸肉，补敛冲脉，三剂而愈。", ["细", "数"]], "19810": ["治法", "此段论安冲汤加减法，非辨脉主病。脉象热者加大生地以清热凉血；凉者加乌附子以温经；大怒肝气冲激血崩者加柴胡疏肝升提。服后觉热者酌加生地，示人随脉证调整，以平为期。", []], "19811": ["病机", "脉微弱而迟，微为阳衰，弱为气弱，迟为阴寒。陡然下血两日不止，昏愦不语，周身皆凉，乃气血将脱、元阳亦脱之候。脉证相合，故急用参附回阳固脱，一剂血止而热复。", ["微", "弱", "迟"]], "19812": ["病机", "右寸关微见如水上浮麻，左部脉皆不见，乃大气下陷、血脱气散之危候。急用生黄耆升补大气，脉虽出而微细异常，血仍不止，呼气不能外出，欲大便，皆大气下陷之征，故用固冲汤加黄耆而愈。", ["微", "细"]], "19813": ["病机", "脉小无力，小为血少，无力为气虚；又见脉滑脱之征，滑脱乃冲脉不固、血滑不止之象。流产旬日忽然下血甚多，头晕腹胀，正是冲脉滑脱，气血两虚。故用固冲汤加柴胡、归身，补敛升提而止。", ["小", "无力", "滑"]], "19814": ["病机", "两部脉皆微细无力，微为阳虚，细为血少，无力为气衰。行经过期不止，诸治不效，乃冲脉虚损不能固摄，气血两亏。固冲汤止血兼补血，服数剂收功，后竟复孕，可见脉微细无力主虚损而非绝候。", ["微", "细", "无力"]], "19815": ["病机", "脉微细而数，微细为气血两虚，数为虚热内扰。小产后血不止绵延月余，阴血亏耗，虚热迫冲，故脉数。用固冲汤加生地清热凉血，病虽轻而不愈，后得地道黄耆两剂全愈，示药力之要。", ["微", "细", "数"]], "19816": ["病机", "原文虽言“脉调和”，然此段重在论冲脉与血室之生理及不育之治则。冲脉为血海，上隶阳明，下连少阴，为化精受胎之所。脉调和则冲脉无病，自能生育；若郁、虚、风、湿、气化不固、阴阳偏胜，则冲脉病而不育。故脉调和在此示冲脉无病之常，反衬病时脉必有偏。", ["和平"]], "19817": ["病机", "原文“经脉则大致调和，偶或后期两三日”，然其生平畏寒凉，下焦虚寒，故虽脉大致调和，仍属虚寒不育。脉调和而后期，说明冲脉虽无大滞，但阳气不足，血海失温，故用紫石英温冲而孕。此脉象提示病机在虚寒，非脉象本身主病。", ["和平"]], "19818": ["病机", "此段未识脉名，专论带下病机。带脉主约束诸脉，冲任滑脱则带脉失约，故病带下。然滑脱之中兼有瘀滞，瘀滞不外气血，有因寒因热之异。方用龙骨、牡蛎固脱，茜草、海螵蛸化滞，山药滋真阴固元气，示带下病机为滑脱兼瘀滞，寒热不同。", []], "19819": ["主病", "脉甚微弱，主阳气虚衰。患者白带甚剧，自言下焦凉甚，乃下焦虚寒，冲任不固，带脉失约。微弱之脉为虚寒之征，故用原方加干姜、鹿角霜温阳散寒，十剂而愈。此脉微弱直接主下焦虚寒之带下。", ["微", "弱"]], "19820": ["主病", "脉甚洪滑，主热盛。患者赤带多于白带，心热头昏，时觉眩晕，乃热郁于内，冲任受灼，带脉失约。洪滑为实热之象，故用原方加白芍，更增苦参、龙胆草、白头翁苦寒清热，赤带愈而诸症除。此脉洪滑主热性带下。", ["洪", "滑"]], "19821": ["病机", "原文“参以脉之或迟或数，有力无力，则凉热可辨矣”。迟脉主寒，数脉主热，有力为实，无力为虚。赤白带下之凉热，不可尽凭赤白，须合脉之迟数有力无力以辨。迟而无力多凉，数而有力多热，此以脉辨带下寒热病机之要。", ["迟", "数"]], "19822": ["病机", "此段未识脉名，论倒经病机。冲为血海，上隶阳明，下连少阴。少阴肾虚，气化不能闭藏以收摄冲气；阳明胃虚，气化不能下行以镇安冲气，则冲气上干，冲血随之上逆，发为倒经。故用麦门冬汤补中生津，半夏降胃安冲，山药补肾敛冲，使冲气安宅，血循故道。", []], "19823": ["误治", "脉象微弱，主气虚。室女倒经年余，脉微弱，投麦门冬汤后短气，脉微弱益甚，知胸中大气下陷，不任半夏之降。此误治因脉微弱未察大气下陷，反用降逆，致气陷更甚。改升陷汤升举大气，短气愈而倒经亦愈。脉微弱在此示大气下陷之机。", ["微", "弱"]], "19824": ["病机", "脉微弱而迟，两寸不起，是胸中大气下陷之征。微弱为气血不足，迟为阳气不振，两寸候胸中，不起则大气不能升举，故呼吸自觉短气。大气陷则血随气乱，倒经半载不愈。投升陷汤升补大气，气升则短气愈、经水顺，终得孕育。", ["微", "弱", "迟"]], "19825": ["治法", "本段无脉象，专论安胎用药之法。以菟丝、寄生、续断、阿胶补肾养血以荫胎，又随证加减：气虚加人参，大气陷加黄耆，食少加白术，凉加补骨脂，热加生地黄。盖胎赖肾气作强、气血濡养，故补虚升陷、调其寒热，则胎自安。", []], "19826": ["预后", "六脉皆虚浮，按之即无，是产后过汗、气阴两脱之候。虚浮无根为元气外越、神魂飞越，故怔忡恍惚、身飘飘上至屋顶，汗出不止。治当急固脱，药后汗止神定。乃误认产后风，投祛风之剂，汗出不止而脱，示虚浮无根之脉主危候。", ["虚", "浮"]], "19827": ["病机", "本段无脉象，论产后气血暴虚之病机。百骸失血濡养，则口紧牙紧、手足拘搐，类中风痫痉；气虚皮毛无卫，则恶寒恶心、身体颤动、发热作渴。虽有虚火泛上、有痰、有外感，皆当以末治之，不可祛风消痰，重虚产妇，宜生化汤加参、耆益气。", []], "19828": ["治法", "脉象洪实，为风热已入阳明之府、表里俱热之征。产后虽气血虚，然外感实热壅盛，脉洪实者可用生石膏清热。惟宜仿白虎加人参汤意，重用人参大补元气，以玄参代知母，使寒凉得温补逗留胃中化燥热，托邪外出，不致直趋下焦伤产妇。", ["洪", "实"]], "19829": ["病机", "本段无脉象，论阴挺病机。肝主筋、络阴器、为肾行气，阴挺挺出形类筋结，故断为肝气郁而下陷。方以黄耆合柴胡、芎䓖补肝舒肝，升其陷；当归合乳香、没药养肝调肝，化其郁；又加知母凉润，解黄耆之热，以合肝寄相火。", []], "19830": ["其他", "本段仅为方剂名「资生通脉汤」，无脉象、无病机论述，故脉象要素为空。其方名提示用于资生通脉，然原文未载脉症，不能据以推断具体病机，仅录方名以备查考，归入其他。", []], "19831": ["病机", "本段无脉象，引《内经》论女子不月之病机。二阳指阳明胃腑，胃病不能消化饮食，推其所发在于心脾，心主神、脾主思，神思郁结则胃减酸汁、食少血亏，故在女子为不月。治当调脾胃、多进饮食，以立生血之本，用白术健胃阳。", []], "19832": ["病机", "脉五至而细无力，为气血两虚、脾胃虚弱之象。患者天癸未至、饮食减少、身体羸瘦、灼热，皆由脾胃虚损、化源不足，血海空虚所致。细而无力正合虚劳内热之机，故治以资生通脉汤健脾益气、养血通经，服后脉象大有起色，示气血渐复。", ["细", "数", "虚"]], "19833": ["病机", "脉数近六至而微细无力，为脾肾两虚、阴亏内热之候。患者泄泻月余伤脾，月事遂闭，身形瘦弱、干嗽潮热、饮食减少，皆脾虚不能化生气血、肾虚阴火上炎所致。数而无力非实热，乃虚热；微细示气血大亏，故先以山药鸡子黄粥培补脾胃，再投资生通脉汤。", ["数", "细", "虚"]], "19834": ["病机", "脉搏五至、弦细无力，为肝郁血虚、脾弱化源不足之象。患者忧思过度致月闭，五心烦热、颧红灼热、饮食停滞、夜不能寐，皆肝郁化火、脾虚不运、血海空虚所致。弦为肝郁，细为血少，数而无力为虚热，故以资生通脉汤加赭石、枣仁，健脾养肝、安神降逆。", ["弦", "细", "数", "虚"]], "19835": ["治法", "此段未出脉象，专述眼疾肿疼、胬肉遮睛、赤脉络目、羞明多泪等一切虚火实热之证的治疗。原文以“虚火实热”统括病机，示目病有虚有实，治当分途。虽无脉可凭，然提示临证治眼疾须辨虚实寒热，不可一概清火，为后文脉诊辨证张本。", []], "19836": ["治法", "此段亦未载脉象，述目睛胀疼、微生云翳、赤脉络目、目眦溃烂及因火视物不真等证之治。原文以“偶因有火”点出火邪为患，然未辨虚实。无脉可参，故只能就症论治，提示目疾有火者须审其虚实，与前后脉案相参，方不致误。", []], "19837": ["病机", "脉大而无力，为气血亏虚、精气不能上承于目之象。大而无力非实火，乃虚阳外浮、中气不足。患者瞳子散大、视物不真，屡药无效，正因未识此虚候。瞳神属肾，散大不收，责在肾精亏耗、元气不固，故制丸缓补，服两月全愈，示虚证当以培补取效。", ["大", "虚"]], "19838": ["病机", "脉细弱而数，为脾肾两虚、阴火上逆之候。细弱示气血大亏，数则为虚热。患者白喉黏涎甚多、须臾满口，原文明言“脾肾两虚，肾虚气化不摄，则阴火上逆，痰水上泛”，脾土虚损不能制之，故咽喉肿疼而涎多。此非实火，故忌表散，投六味地黄汤加于术、苏子，补肾健脾、降火化痰。", ["细", "弱", "数"]], "19839": ["病机", "此段未出具体脉象，仅言“参以脉象之虚实凉热”，论咽喉骤疼闷有因寒因热之异。原文引王洪绪说，谓虚寒阴火可用肉桂、炮姜温通；又指出素有蕴热、外感、劳碌、暴怒皆可致咽喉疼闷。主旨在于临证须细察身体性情动作，再参脉之虚实，以辨寒热，不可一概作热治。", []], "19840": ["病机", "脉象有力而微弦，有力为毒热内蕴之实，微弦则因病久气分有伤，胃中瘟毒上攻致牙龈腐烂。此脉示毒热虽实而正气已损，故用白虎加人参汤清热兼益气。", ["弦", "实"]], "19841": ["病机", "脉象滑数，滑主痰湿壅盛，数主热邪亢盛，结合疮疡红肿、舌苔黄厚，知兼外感实热，热毒壅聚而发为疮痈。故先以白虎加人参汤清热，后以清火消肿解毒收功。", ["滑", "数"]], "19842": ["误治", "此段论煅石膏之害，言其收敛之性将痰火凝结不散，误用则伤人。原文未直接描述脉象，但强调外感实热当用生石膏，若误用煅者，可致热邪锢闭，变生他证。", []], "19843": ["误治", "服煅石膏数钱脉变结代，因煅石膏收敛凝结，使血脉锢闭不通，故脉来结代，甚则言语不遂、肢体痿废。此明煅石膏误服致血脉凝闭之害。", ["结", "代"]], "19844": ["主病", "脉数而洪实，数主热盛，洪主阳明气分热炽，实主邪实，舌苔黄而干，为温病热盛伤津之象。故重用生石膏清解阳明实热，热退则脉和。", ["数", "洪", "实"]], "19845": ["病机", "脉洪长有力，洪长为阳明实热之脉，虽舌苔淡白、不燥渴、畏寒凉，乃痰饮内伏掩盖热象，舍证从脉，知为阳明实热，故用白虎汤加半夏。", ["洪", "长", "实"]], "19846": ["病机", "脉关前洪滑异常，关前主上焦，洪为热盛，滑为痰热内壅，故上焦烦热恶心、闻药即吐。用梨片蘸生石膏末，取清热化痰降逆之意。", ["洪", "滑"]], "19847": ["病机", "脉洪而实，洪实为阳明热盛邪实，头面红肿、壮热谵语，知梅毒夹杂温病，热毒炽盛。服石膏水后脉洪实减半而加数，示热势稍退而余热未清，故加党参扶正。", ["洪", "实", "数"]], "19848": ["病机", "脉甚沉伏，重按有力，乃春温之热郁于阳明，热邪内闭，气血壅滞，故脉沉伏似寒；重按有力说明实热内结。外现身冷腿痛等假寒象，实为热深厥深，舌苔黄厚、小便赤涩可证。此脉主阳明实热内郁之病机，非虚寒也。", ["沉", "伏"]], "19849": ["主病", "脉象洪数，重按有力，为阳明气分热盛之典型脉。外感温病，热已入阳明之府，表里大热，喘息迫促，大便两日未行，皆热盛腑实之象。洪数有力说明正气尚能抗邪，故犹可治，投白虎汤清解阳明，热退则脉自平。", ["洪", "数"]], "19850": ["病机", "产后温病，心中燥热，舌苔黄厚，脉象洪实，为热入阳明之府，邪热亢盛之病机。洪实有力说明实热内结，虽产后亦不忌寒凉。若脉不甚洪实，则热势较轻，可重用玄参；剧者必用白虎加人参汤，以脉之洪实程度辨热之轻重而施治。", ["洪", "实"]], "19851": ["病机", "产后十余日，周身大热无汗，心中热渴，脉甚洪实，舌苔黄而欲黑，撮空摸床，内风已动。洪实之脉主阳明实热亢盛，热极生风，故见神昏撮空。此产后温病，热如燎原，虽在产后亦当急清阳明，不可拘泥产后忌凉之说。", ["洪", "实"]], "19852": ["主病", "脉洪滑有力，心中热而且渴，下血不止，身不觉热，舌上无苔。洪滑有力主热盛于内，滑为血分有热，热迫血妄行而下血。此夹杂外感之热内迫，非单纯血热，故凉血止血不效，改用白虎加人参汤清外感之热，热清则血止。", ["洪", "滑"]], "19853": ["病机", "脉洪而无力，肌肤热烙手，下白痢频繁，旋即昏愦不省人事。洪为气分热盛，无力为正气已伤，此气分热痢兼受暑邪，多病之身不能支持，故精神昏愦。洪而无力说明热盛而正虚，急当清热益气，石膏配党参两顾其虚。", ["洪"]], "19854": ["其他", "此段为痢证医案之总结，说明上所载痢证皆兼外感之热，故重用生石膏治之，非概以一方治痢。强调‘脉证的确，用之自无差忒’，即须凭脉辨证，随证变通。文中未出具体脉象，故脉象要素为空，主旨在于申明治痢须辨兼夹外感之热。", []], "19855": ["病机", "疟疾间日发，热时若燔，舌燥口干，脉象弦长，重按甚实。弦为少阳之脉，长为阳明热盛之象，弦长而实主少阳邪盛兼阳明热盛，即疟而兼温之脉。故用白虎汤清阳明，加柴胡和解少阳，疟热皆愈。脉虽不至甚实而按之有力者，亦加石膏清之。", ["弦", "长"]], "19856": ["病机", "脉左右皆弦而有力，弦为肝脉，有力主实热。结合鼻流浊涕、腥臭、心热神昏、眩晕、便干，知肝热移于脑，胃亦移热。弦而有力说明肝胆实火内盛，热循经上扰，故主肝移热于脑之脑漏，与心热神昏、眩晕、便燥相应。", ["弦"]], "19857": ["病机", "脉浮而有力，浮主表，有力主实。此因风邪外束，卫阳被遏，郁而化热，故脉浮有力。风束生热，热郁鼻窍则流浊涕。脉浮说明表邪未解，与鼻中浊涕、汗后涕减相应，主风束生热之脑漏。", ["浮"]], "19858": ["病机", "脉洪长有力，右部尤甚，洪长为阳明热盛之象，右部候脾胃。伏气化热，阻塞奇经经络，热郁而痛。洪长有力说明热邪亢盛，与舌心红无皮、头疼眩晕、便干溲涩相应，主伏气化热之腹痛。", ["洪", "长"]], "19859": ["病机", "脉洪长有力，为阳明热盛之脉。此证因外感伏邪窜入奇经，久而生热，热郁作痛。屡为热药所误，热益加剧，故脉洪长有力。洪长说明热邪内盛，与昼夜号呼、腹疼剧烈相应，主伏热腹痛。", ["洪", "长"]], "19860": ["病机", "脉象犹浮，虽洪滑而按之不实。浮主表邪未尽，洪滑主里热，按之不实为热未成实。此乃外感之热已入阳明，仍带表证。脉浮说明表邪未解，与头疼、舌苔白或微黄相应，主表里同病之热证。", ["浮", "洪", "滑"]], "19861": ["病机", "脉洪数而实，洪为阳明热盛，数为热炽，实为腑实。此夹杂温病，阳明腑证已实，热毒炽盛，故脉洪数而实。与肌肤发热、周身僵直、抽掣相应，主温病阳明腑实之危候。", ["洪", "数", "实"]], "19862": ["病机", "脉关前洪滑，按之有力。关前候上焦，洪滑为痰热壅盛之象。素有劳疾，感冒风寒，上焦烦热，痰涎胶滞，喘促异常。洪滑有力说明痰热壅肺，与喘嗽、痰涎胶滞相应，主痰热壅肺之劳疾发作。", ["洪", "滑"]], "19863": ["病机", "脉象有力，数近六至。数主热，有力主实。此因外感留邪，余热稽留，故脉数有力。虽羸弱已甚，脉反有力而数，说明有伏热未清。与心中发热、便干溲涩相应，主外感留邪、余热内伏之劳热喘嗽。", ["数"]], "19864": ["病机", "脉象滑实，右脉尤甚，为伏气化热、痰热壅肺之征。滑主痰热，实主邪盛，右脉候肺，故知伏邪之热上透膈膜，熏蒸肺脏，致咳嗽吐痰腥臭。此脉有力，说明热邪尚盛，正气未衰，故宜重用生石膏清解。", ["滑", "实"]], "19865": ["病机", "原文未载脉象，然述伏气下陷奇经，久而化热，不能外发为温，有时随奇经上升。在女子热入血室，可致子宫溃烂。此段重在阐明伏气内陷奇经、化热伤及血室之病机，脉象缺如，故脉素为空。", []], "19866": ["病机", "脉象洪实，为伏有外感热邪，热盛于内之征。洪主热盛，实主邪实，热自下焦上冲脑部，故头巅肿胀、眩晕、心中发热。身体不弱，脉仍有力，说明正气尚充，故可重用生石膏清解伏热。", ["洪", "实"]], "19867": ["病机", "脉弦而有力，尺脉尤甚，为热入血室、伏气下陷化热之征。弦主痛、主热，尺候下焦，故少腹切痛、时时下脓血。热郁血室，阻塞气化，久而生热，致子宫溃烂，故脉弦有力而尺部尤显。", ["弦", "有力"]], "19868": ["病机", "左关弦硬，右关洪实，为伏气之热与疮毒俱发之征。左关候肝，弦硬主热郁疮毒；右关候脾胃，洪实主阳明热盛。热毒内蕴，故烦躁异常，大便数日未行，投白虎汤加解毒之品而愈。", ["弦", "硬", "洪", "实"]], "19869": ["病机", "脉来洪实兼数，为阳明热久、真阴铄耗之征。洪实主热盛邪实，数主热炽，壮热烦渴、大解十日未行，乃热盛津伤。欲透邪则津液已衰，欲通便则无承气确征，故用生石膏合增液汤清热生津。", ["洪", "实", "数"]], "19870": ["病机", "脉左右皆微弱，至数稍迟，为胸中大气下陷之征。微弱主气虚，迟主阳衰，大气下陷不能宣布营卫，故周身皆凉；不达脑中则神昏，不潮舌本则舌干。此因服开破降下药太过，致大气下陷。", ["微", "弱", "迟"]], "19871": ["病机", "脉关前微弱不起，为胸中大气下陷之征。关前候胸中，微弱主气虚陷下，大气不能司肺脏呼吸之枢机，故忽然不能喘息，张口呼气而气不上达，气蓄极下迫肛门突出。投人参、柴胡升补大气而愈。", ["微", "弱"]], "19872": ["病机", "脉沉迟微弱，右部尤甚，沉迟主阳虚，微弱主气虚。然询之不觉寒凉，知非心肺阳虚，乃胸中大气下陷，气陷则脉气不充，故沉迟微弱。大气不举，胸胁满闷、怔忡自汗，皆气陷不摄之候。", ["沉", "迟", "微", "弱"]], "19873": ["病机", "脉微弱欲无，为气血大虚之候。产后大汗淋漓，阴分暴虚，不能维系阳分，阳气亦随汗泄，大气下陷，不能吸摄卫气，故脉微弱欲无，气息奄奄，短气怔忡发热，皆气陷阳浮之象。", ["微", "弱"]], "19874": ["病机", "左脉微弱不起，左主肝，肝气虚弱，气化不行，故脉微弱不起。肝虚则温煦不足，心中寒凉，饮食减少，羸瘦。左半身气化不及，故觉下坠，卧不敢左侧，皆肝虚之征。", ["微", "弱"]], "19875": ["病机", "脉数至八至，数脉主热，虚劳身热劳嗽，脉数至八至，为阴虚内热，虚火妄动之象。肾阴亏虚，水不制火，故脉数；火刑肺金，故劳嗽。治以黄耆补肺气益肾水，知母滋肺津，使阴阳不偏胜。", ["数"]], "19876": ["病机", "脉弱无力而痿废者，胸中大气虚损，不能助血上升以养脑髓神经，脑髓失养，故肢体痿废。此即《内经》「上气不足，脑为之不满」之脑贫血证。若脉强有力而痿废，则为脑充血，血菀于上之薄厥。", ["弱"]], "19877": ["病机", "六脉不全仿佛微动，为气血暴脱之危候。行经下血不止，阴血骤失，气随血脱，脉道不充，故六脉不全，微动无力。精神昏愦，气息若无，皆气血将脱之象，急宜固脱止血。", ["微", "动"]], "19878": ["病机", "脉甚细弱，左部尤甚，细弱主气血虚，左部候肝，肝气太虚，肝中相火亦虚，气化下陷，湿寒下注而为白带。身体羸弱，心中寒凉，皆肝虚火衰之候。治以补肝气、助相火、扶土胜湿。", ["细", "弱"]], "19879": ["其他", "本段未识别脉名，专论山萸肉性味功效。其味酸性温，收敛元气，固涩滑脱，兼条畅之性，通利九窍，流通血脉，治肝虚自汗、胁疼腰疼、内风萌动，敛正气而不敛邪气，故《本经》谓逐寒湿痹。", []], "19880": ["预后", "脉浮力微，按之即无，为脉象无根，乃元气将脱之兆。外感痰喘虽愈，而正气已虚，浮微无根提示根本动摇，故断为危候，当峻补以防变。后果然喘逆、汗出、肢冷、身挺，皆元气外脱之征，急用萸肉敛固，方得挽回。", ["浮", "微"]], "19881": ["病机", "脉浮弱无根，左右皆然，浮为气虚外浮，弱为根本不足，无根则肾气不固。患者素伤烟色，耗损真元，偶感风寒后表散更伤气，致卫气不固而冷汗、怔忡、气息欲断。此属元气虚浮欲脱，故用萸肉、人参敛补固脱。", ["浮", "弱"]], "19882": ["病机", "脉沉迟细弱，右部沉细尤甚，沉迟为阳虚，细弱为气血不足。大汗淋漓数日，卫气外泄，胸中大气下陷，不能统摄，故脉沉细弱而右部尤甚，症见胸中气不上升如巨石压。用黄芪升补大气，萸肉敛汗固脱。", ["沉", "迟", "细", "弱"]], "19883": ["病机", "脉洪数不实，洪数为热盛，不实为正气已虚。伤寒服表药太过，汗出不止，津气两伤，邪热未净，故脉洪数而中空不实，伴怔忡、便闭。此虚热浮越之象，治以萸肉敛汗，山药、石膏、知母清补兼施。", ["洪", "数"]], "19884": ["病机", "左关微弱，左关候肝，微弱为肝气虚弱。因屡经恼怒，怒久伤肝，肝虚不能疏泄，气机郁滞而腹中作疼。前医以通气活血消食祛寒攻邪，皆不效，正因虚不受攻。用萸肉补肝，佐当归、丹参、柏子仁养血疏肝，疼遂愈。", ["微", "弱"]], "19885": ["病机", "脉象濡弱，右关尤甚，右关候脾胃，濡弱为脾胃气虚。泄泻半载，百药不效，因脾胃虚甚，运化失职，水湿下趋。故用生白术健脾燥湿，熟枣肉和胃，缓缓嚼咽，使脾胃渐复而泻止。", ["濡", "弱"]], "19886": ["病机", "脉象浮缓，按之即无，浮缓为气虚外浮，按之无根则中气大虚。行经下血不止，脾胃虚甚，中焦不能健运统摄，下焦因之不固，故血脱而兼饮食不消、大便滑泻。于治血药中加白术、鸡内金健脾统血，血即止。", ["浮", "缓"]], "19887": ["病机", "脉数至七至，数脉主热，七至为数之甚，然喘逆甚剧，投滋阴纳气降气不效，知非纯虚。后加白术数钱，喘反剧而终愈，说明此数脉乃中焦虚馁、气不归元所致，非实热。白术健脾补中，使气机升降复常，喘乃渐平。", ["数"]], "19888": ["病机", "脉微弱迟濡，为脾胃阳气虚衰、湿寒内盛之象。微、弱主正气不足，迟主寒，濡主湿。脾胃湿寒则健运失职，气化不升，津液不能上承，故咽喉干而饮水不解渴。此非燥热伤津，乃湿寒困阻、气化不升所致，故用四君子加干姜、桂枝温运脾胃而渴止。", ["微", "弱", "迟", "濡"]], "19889": ["兼症", "脉有滑象，上盛下虚，为妊娠恶阻之征。滑主痰饮，亦主妊娠；上盛下虚示冲气上逆、下脘结滞。呕吐连连、勺水不存、大便不通、下脘疼结，皆因胎气上冲、胃气不降。脉滑而疑妊，月信五十日不见，故用赭石镇降开结，结开便通而胎安。", ["滑"]], "19890": ["兼症", "原文未识脉名，仅言脉象有力、舌有黄苔、心中发热，知恶阻之外夹杂外感。脉有力主邪实，黄苔、心热为内热之征。恶阻呕吐甚剧，九日水少存、食尽吐，下脘结坚，非轻剂可通，故先用石膏清外感之热，继用赭石细末重剂开结降逆，结开而饮食顺利。", []], "19891": ["病机", "脉滑实，右部尤甚，为痰涎壅滞胃口之象；滑主痰，实主邪壅，右部候肺胃，故痰阻胸膈、饮水亦吐。药不胜病，下行不通复吐。翌日脉转洪长，舌苔由黄变黑，示痰滞化热、热入阳明，故重用白虎汤清之，便通而愈。", ["滑", "实", "洪", "长"]], "19892": ["病机", "脉浮弦，数近六至，重按无力。浮弦为阳明少阳合病，二经病机相并上冲故作呕吐；数主热，无力为无谷气相助又为内热所迫。口苦心热、舌苔微黄，内热已实。故用赭石凉镇降逆，既无臭味又可止吐。", ["浮", "弦", "数"]], "19893": ["病机", "脉象洪实，为外感之热已入阳明之府。洪主热盛，实主邪结，故周身灼热、烦躁怔忡、舌苔黄厚、大便数日未行。热挟胃气上逆、冲气上冲，故饮食下咽即呕吐。用赭石、石膏、蒌仁等清降阳明、镇冲止呕，遂受药不吐而愈。", ["洪", "实"]], "19894": ["预后", "原文未识脉名，言尺部无根、寸部摇摇，此将脱之候也。尺部无根为肾气不固、下元虚脱，寸部摇摇为阳气浮越无依。温病表里俱热，误下两次遂发喘逆，按心口可暂止，正虚气逆欲脱。故用鸡子黄、赭石镇纳浮阳，喘愈脉安，继服参赭镇气汤善后。", []], "19895": ["病机", "脉浮而无力，为正气虚衰、气机上逆之象。浮主气逆于上，无力主中气不足。年七十余，呃逆兼小便不通，剧时杜塞咽喉、息不能通、两目上翻、身躯后挺，皆中虚气逆、冲胃之气上冲所致。故用赭石镇降，台参、山药、芡实补中，牛蒡子利气，呃逆顿愈，小便亦通。", ["浮"]], "19896": ["病机", "关前洪滑主上焦热盛，两尺不任重按为下元虚损，合为“上盛下虚”。热迫血上溢则鼻衄甚剧；阴虚津亏则头目不清、舌干无津、大便燥结。洪滑见于关前，正合阳明胃热上冲，故用赭石、生地等清降镇摄而血止脉平。", ["洪", "滑"]], "19897": ["病机", "脉洪实为阳明府热已实之征，面有火、舌苔黄厚与之相应。产后温病，胃热上逆则恶心呕吐、不能饮食、精神昏愦。洪实示热邪壅盛于内，胃气因热上逆，故用玄参、赭石清热降逆，热退呕止而脉平。", ["洪", "实"]], "19898": ["病机", "脉弦而沉，两尺尤甚，主下焦实寒内结，阳气不能外达。寒凝少腹则抽疼、肾囊紧缩、便结；浮热被格于上则烦热。弦为寒痛，沉为在里，故用赭石引药下行，佐附子温通，使寒散便通而诸症解。", ["弦", "沉"]], "19899": ["病机", "左脉浮弦有力，浮主阳升，弦主少阳火郁。少阳之火挟心经之热，乘阳旺之时上冲脑部，故每日巳时头疼异常、左边尤甚。脉象与头疼定时发作相应，用赭石、龙胆草等清降少阳而愈。", ["浮", "弦"]], "19900": ["病机", "脉象沉实，沉主里，实主邪结。痰火充塞心脑相通之路，神明瞀乱而发癫狂。沉实示痰火实邪内壅，故重用赭石重坠引痰火下行，佐大黄、朴硝、甘遂峻逐实邪，使心脑之路通畅而神志复常。", ["沉", "实"]], "19901": ["病机", "脉弦长有力，弦为肝火暴动，长为气血上冲之势。肝火与气血相并，上冲脑部，致忽然昏倒、口眼歪斜、舌强不语，即《内经》“血之与气并走于上”之大厥。弦长有力正合肝火亢盛、气血上逆之机，故用镇敛肝火、引血下行之法。", ["弦", "长"]], "19902": ["病机", "两尺不见、关前摇摇无根、数至六至，示下焦虚惫，冲气不摄，挟肝胆浮热上干脑部。尺脉不见为肾虚根本动摇，关前无根为虚阳上浮，数脉为热。故见胸膈胀、腹脐塌陷、头晕项强、妄言妄见，状若疯狂，用赭石、龙牡、山药、地黄等镇摄补虚而愈。", []], "19903": ["病机", "六脉闭塞若无，因恼怒气机骤闭所致；得嚏后脉出，至数五至余而两尺弱甚、不堪重按，知肾阴亏损，肝胆之火易上冲。尺弱为根本不足，故昏倒、牙关紧闭、痰涎外吐。用赭石、熟地、山药、龙牡等补肾镇肝，豁然顿愈。", []], "19904": ["病机", "左脉弦硬而浮，为肝胆之火挟热上冲，弦主肝、硬主火盛、浮主上炎，故头疼目睑皆疼、涎沫上溢；右脉沉滑，沉主里、滑主痰，示热痰杜塞中焦。经血两月未见，乃气血两虚、冲脉不充。合观为气血两虚、蕴热挟肝胆之火上冲，兼热痰阻中，故用赭石降逆、参归芍养血而效。", ["弦", "硬", "浮", "滑"]], "19905": ["其他", "本段专论山药性用，未及脉象。原文称其色白入肺、味甘归脾、液浓益肾，能滋润血脉、固摄气化、宁嗽定喘，并强调宜生用煮汁，炒则蛋白质焦枯无效。所主在药性功用，非脉诊病机，故脉象要素为空，归入其他类。", []], "19906": ["其他", "本段述干地黄即生地黄之性用，谓经日晒干则性凉而不寒，能生血脉、益精髓、聪明耳目，治骨蒸劳热、肾虚生热。全段为药性论述，未涉及脉象与诊法，故脉象要素为空，主旨归入其他，不作病机推断。", []], "19907": ["预后", "脉至七至为数，按之不实为虚，数而无力示阴亏气弱、虚热内扰。伤寒旬日而大便滑泻不止、心中怔忡不能支持，正是真阴下亏、中气不固，脉证相符故医者辞不治。投熟地、山药、芍药滋阴固摄，滑石甘草和中，尽剂而愈，说明此脉虽危尚可挽回，属预后判断。", ["数", "虚"]], "19908": ["死脉", "脉如水上浮麻不分至数、按之即无，是浮散无根、至数模糊之象，阴液将竭、阳气欲脱，故原文断为将脱之候。温病痰喘，服小青龙加石膏后喘止而寅时复作、精神恍惚怔忡，正合此脉。急煎山药少愈，继用熟地四两、山药、台参以大滋真阴固脱，示此脉主元气欲脱之危候。", ["浮", "散"]], "19909": ["误治", "脉稍弱示正气不足，当用小青龙汤时若脉弱，服后须以补药继之，或加人参于汤中并加重石膏。原文自述初次失处在服小青龙后未用补药，致变生脱候，故经此证后立此戒。此段主旨为纠前段误治之失，脉弱为辨证关键，提示解表之后当顾护元气。", ["弱"]], "19910": ["病机", "脉数至七至、按之即无，数而无力为下焦虚惫、阴不敛阳，故温病传里后外邪直趋下焦作昼夜泄泻、昏不知人。原文谓下焦虚惫太甚者非重用熟地不能愈，熟地大补肾中元气、止滑泻，少用则作闷无效。此脉示虚极欲脱之病机，与大便滑泻、神昏相应。", ["数"]], "19911": ["其他", "本段专论甘草性用，谓其味甘主和、主缓，能解一切毒性、调和脾胃，炙用补力较大而胀满忌之，生用轧末能通利二便、消胀除满；并举甘草泻心汤护心、白虎汤缓寒、通脉四逆缓热、芍药甘草汤育阴止疼诸方义。全段为药性方义，未涉脉象，故脉象要素为空。", []], "19912": ["其他", "此段论述药物禀赋之偏以救阴阳之偏，非论脉象。原文虽未识脉名，但以丹砂为例，阐发‘阳抱阴，阴承阳’之理，说明药性偏胜可调人身之偏。所论精气失养则魂魄不安，提示病机在阴阳精气之偏，而非具体脉象所主。", []], "19913": ["病机", "脉甚弦硬，为肝火肝风内动之象。弦主肝病，硬则劲急，示肝阳亢盛、化火生风，故见忽然中风肢体不遂。治以龙骨敛戢，使脉象柔和则病自愈，说明此脉主肝风内动、气血上逆之病机。", ["弦", "硬"]], "19914": ["病机", "脉滑脱，指脉象滑利而兼散脱不收。原文谓‘经脉滑脱’因元阳不能固摄，滑为阳气浮越，脱为元气欲散，故见怔忡、虚汗、神魂浮荡。重用生龙骨借元阴翕收欲涣之元阳，正对此滑脱之脉所主元阳不固病机。", ["滑", "脱"]], "19915": ["兼症", "脉象虚数，虚为正气不足，数为有热。温病大热已退而心犹发热、怔忡、小便不利、大便滑泻，脉虚数似外邪未净，实为热伤气阴、虚热内扰。故用芍药甘草汤益气止泻，针对虚数脉所主气阴两伤、余热未清之兼症。", ["虚", "数"]], "19916": ["病机", "脉左大于右一倍，按之有力，左脉候肝，大为邪盛，有力为实。温病热传阳明，脉当右大于左，今反左大，乃温病变证，示热邪偏聚肝经。故重用芍药平肝，小剂白虎清阳明，针对左脉大实所主肝经热盛病机。", ["大", "实"]], "19917": ["病机", "脉数而有力，数为热，有力为实。周身漫肿、腹胀、小便不利，似水湿内停，然脉不沉缓而数实，且心中发热，知非单纯水气，乃阴分亏损、阳分偏盛，热与水结。故用芍药、玄参养阴清热，滑石、地肤子利水，针对数实脉所主阴虚阳盛、水热互结病机。", ["数", "实"]], "19918": ["病机", "脉右部弦硬异常，按之甚实。右脉候脾胃，弦硬为肝木乘土之象，实为邪热内蕴。外感伏邪化热入胃，肝木乘春令之旺侮克胃土，故腹疼泄泻。脉不洪实而弦硬，因胃土受侮从肝木之化。此脉主肝胃不和、木乘土位病机。", ["弦", "硬", "实"]], "19919": ["病机", "脉象左右皆洪实，洪为热盛，实为邪结。表里俱热、腹中切疼、大便日下两三次、舌苔厚黄，知外感邪热已入阳明之府，肝胆乘木气之旺挟实热侮克中土。洪实脉主阳明实热，故用白虎加芍药清阳明、平肝胆，针对热结阳明、木克土病机。", ["洪", "实"]], "19920": ["病机", "脉弦而有力，左关尤甚，为肝血亏损、肝火炽盛之象。弦主肝病，有力为实火，左关候肝，故肝火偏亢。头疼数年反复，乃肝火上冲清窍所致。治以熟地、枸杞等滋肝血，龙胆草、芍药清肝火，龙骨、牡蛎潜阳，药后脉证相应而愈。", ["弦", "有力"]], "19921": ["治法", "泻心汤治吐血衄血，须辨脉之实热与微热。脉象有实热者，宜大黄黄连泻心汤直折火势；脉微似有热者，热势轻浅，故用大黄煎汤送赤石脂末，既清余热又涩血；若脉分毫无热且心中不觉热，则非实火，用大黄肉桂末引火归元。此段以脉象定治法，体现凭脉用药之精细。", ["实", "微"]], "19922": ["治法", "脉实者，邪气盛而正气未衰，故大黄可放胆多用。治癫狂脉实，痰火内结，非大剂攻下不能折其势；治疔毒热盛脉实，火毒壅聚，亦须重剂清热解毒。此段强调用药以胜病为准，脉实为可攻之凭据，若脉不实则不可孟浪。", ["实"]], "19923": ["病机", "脉象洪实，为心热生痰、痰火瘀滞之候。洪主热盛，实主邪结，心热灼津成痰，痰火扰心则烦躁不眠、五心潮热。朴硝咸寒，能胜火开结，佐麦面补心，补破相济。此案以脉洪实为凭，断为痰火实证，故用咸寒攻消而愈。", ["洪", "实"]], "19924": ["主病", "厚朴麻黄汤治咳而脉浮，浮脉主表，为风寒外袭、肺气上逆之咳。厚朴辛温，能升能降，入肺治外感咳逆，兼入肝平木横恣。此段以脉浮为眼目，说明厚朴在表证咳嗽中的应用，并详述其配伍功效，非单纯主病，实为药性脉证合论。", ["浮"]], "19925": ["病机", "越婢汤治水气，脉浮有热，故用麻黄辅石膏以散风热；麻黄附子汤治水气，脉沉而寒，故用麻黄辅附子以温经散寒。脉浮主风热在表，脉沉主寒邪在里，同一麻黄而佐使不同，全凭脉象辨寒热虚实。此段强调通变化裁，息息与病机相符。", ["浮", "沉"]], "19926": ["病机", "脉弦而有力，为肝气胆火恣盛之象。胁下掀疼、大便不通，乃肝胆火郁、气机壅滞所致。前医误用大承气汤攻肠，未及肝胆，故便未通而痛转甚。投金铃泻肝汤加柴胡、龙胆草，清肝泻火、升达少阳，使大便通而胁疼愈。此案以脉弦有力断为肝胆实火，非肠腑燥结。", ["弦", "有力"]], "19927": ["其他", "此段未识脉名，专论桂枝非发汗亦非止汗之品，其宣通表散之力旋转于表里之间，能和营卫、暖肌肉、活血脉。服桂枝汤欲得汗必啜热粥，故不能发汗；阳强阴虚者误服则汗脱，故不能止汗。全段以药性功用为主，未涉及脉象，故脉象要素为空。", []], "19928": ["治法", "原文未识脉名，仅言“脉象有热者，宜加生地黄一两”，提示热象为兼症辨证要点。本案以行经下血不止为主，前医寻常止血不效，后以傅青主老妇血崩方（黄芪、当归、桑叶、三七）一剂而愈，说明病机属气虚不摄、血失统藏，兼瘀滞。脉热者加生地，示热扰血室之兼机。", []], "19929": ["病机", "脉芤而无力，重按甚涩。芤主失血，涩主瘀滞。便血暴止后，虽血止而瘀血凝结经络，新血不归经，故脉芤无力示血虚，涩示瘀阻。身体酸软、饮食减少为瘀血内停、气血不荣之候。原文谓“但知止血，而不知化血，积之日久必成劳瘵”，正合此脉机。", ["芤", "涩"]], "19930": ["病机", "六脉沉数，沉主里，数主热。疳疾兼便血，腹露青紫、腹胀疼、潮热、目赤丝、肌肤甲错、毛发焦枯，皆瘀血内结、郁而化热之象。脉沉数说明瘀热在里，非单纯虚证。原文“审证辨脉，知系瘀血为恙”，以三七化瘀而愈，脉证相应。", ["沉", "数"]], "19931": ["治法", "外感大热已退而阴亏脉数不能自复，数脉为阴虚内热、余热未清之象。原文主张于大滋真阴药中少加滑石，使余热从小便泻出，则脉数易复。滑石质软，不伤阴，兼能利湿清热。此段以脉数不复提示阴亏余热逗留之病机，治法在滋阴中佐以清利。", ["数"]], "19932": ["病机", "脉两寸甚实，寸候上焦，实主邪壅。牙疼久不愈，屡药无效，脉实说明火热壅盛于上，非虚火。原文用怀牛膝、生赭石引血下行，加生地清热，服后霍然。脉实为胃火上炎、气血壅滞之征，与牙疼相应，故主上焦实热病机。", ["实"]], "19933": ["病机", "脉关前浮滑，关前候上焦，浮主表、滑主痰。痰涎郁于胸中，烦闷异常，甚则气不上达、呼吸即停、目翻身挺，舌苔白、肌肤有热，知为温病结胸。浮滑示痰热壅于胸膈，气机痹阻。原文以栝蒌仁通降痰热而愈，脉证相符。", ["浮", "滑"]], "19934": ["病机", "脉微细而迟，微细主气血虚，迟主寒。小便下血久不愈，身体虚弱恶寒、饮食减少，知脾胃虚寒、中气下陷，太阴不升则血亡于便溺。脉微细迟正合虚寒之机，故用干姜、于术、附子、熟地等温补中气、升举脾阳而愈。", ["微", "细", "迟"]], "19935": ["病机", "原文未直接描述脉象，仅言“服之能使心脉跳动加速”，属药后反应。附子大热，补助元阳，能升能降，内达外散，温通凝寒锢冷，又具收敛之力，治汗多亡阳、肠冷泄泻、下焦阳虚阴走。心脉加速示附子补君相二火、振奋心阳之效，非病脉。", []], "19936": ["病机", "脉左右皆弦细，弦主寒主饮，细主虚主积。仲景谓双弦者寒，偏弦者饮，今左右皆弦，知上有寒饮、下有寒积。寒饮阻于上焦则满闷烦躁、不能饮食；寒积结于下则绕脐板硬、月信不行。烦躁乃腹中寒气充溢，迫元阳浮越所致，非实热也。", ["弦", "细"]], "19937": ["其他", "此段论肉桂性用，未涉脉象。肉桂气香而窜，性大热纯阳，下达暖丹田、壮元阳、补相火，温通血脉，治寒痹关节腰肢疼痛及疮家白疽；味辛属金，善平肝木，治肝气横恣多怒。其香窜引诸药透达，故为诸药先聘通使。", []], "19938": ["治法", "脉数主热，热实脉数之证，当以知母滋阴退热。知母寒苦皆不甚大，多液能滋阴，液滑能通大便，故治热实脉数必用知母；若用黄耆补气恐其有热不受者，亦辅以知母。惟大便不实者忌之，以其液滑通便也。", ["数"]], "19939": ["其他", "此段论天冬性用，未涉脉象。天冬味甘微辛，性凉，津液浓厚滑润，入肺清燥热而利痰宁嗽，入胃消实热而生津止渴；津浓液滑之性，能通利二便、流通血脉、畅达经络，虽为滋阴之品，实兼补益气分。", []], "19940": ["病机", "六脉浮洪，浮主表、洪主热，为气分热盛之象。案中骨蒸发热、肤如火燎、吐痰碗许、暑月烦渴、寝食俱废，皆肺经气分火盛所致。前医误用柴胡、麦冬、荆沥等，月余益剧；东垣谓昼盛者气分热也，宜一味黄芩汤泻肺经气分之火，服后热退痰嗽愈，证明浮洪脉主气分实热。", ["浮", "洪"]], "19941": ["病机", "证见痧疹遍身、表里壮热、心中烦躁，而脉虚六部不起，是邪热虽盛而正气已虚，脉证不符。屡服清解之药无效，稍重则大便即溏，说明脾阳亦弱，不耐苦寒。脉虚为正气不足之征，故用鲜茅根甘凉清透，不伤正气，使热透而病愈。", ["虚"]], "19942": ["病机", "脉似有力，惟在浮分、中分，是热邪郁于气分、未入血分，故浮中取之有力而沉取不实。头疼壮热、心中烦躁，服西药退热旋又反复，乃热郁未透。用鲜茅根、滑石煎服，周身得微汗，热从表解，一剂而愈，说明浮中有力之脉主气分郁热。", []], "19943": ["病机", "脉数近六至，重按似有力，数主热，有力主实，是阴虚发热兼有实热。阴虚作热，又兼实热，以致小便不利、积成水肿；心中烦躁亦热象。前服通利小便之药无效，因热灼阴伤、气化不行。用鲜茅根甘凉清热滋阴，昼夜相继，热退便利而肿消。", ["数", "有力"]], "19944": ["病机", "原文述“诊其脉，血热火盛”，虽未列具体脉名，但以脉象判断为血热火盛之病机。吐血反复发作，乃血热妄行所致，热盛迫血上溢，故屡发不愈。脉象当见数或洪等热盛之象，然原文仅言“血热火盛”，未详脉形，故脉素从缺。", []], "19945": ["病机", "原文“诊其脉肝胆火盛”，未明脉形，然以脉测知肝胆火盛。头疼常作，乃肝胆之火上炎，循经上扰清窍。火盛则脉当弦数有力，原文未细述，故脉素从缺。治以清肝泻火，火降则痛止。", []], "19946": ["主病", "脉象虚而无力，主气血亏虚，冲任不固，故血崩甚剧。虚脉主不足，无力为气衰，气虚不能摄血，血脱则脉更虚。用黄芪、白术补气摄血，佐收涩之品，后加海螵蛸、茜草止血，正合虚不摄血之机。", ["虚"]], "19947": ["主病", "脉迟弱无力，迟为阳虚，弱为气衰，无力为虚。下焦凉甚，白带甚剧，乃脾肾阳虚，寒湿下注，带脉失约。阳虚不能温煦，故自觉下焦凉甚；脉迟弱无力，正虚寒之征。治以温补收涩，加干姜、鹿角胶温阳，清带汤固涩。", ["迟", "弱"]], "19948": ["病机", "脉洪滑有力，洪为热盛，滑为血涌，有力为实。足大指隐白穴处破裂出血色紫，乃血热妄行，热迫血溢。洪滑有力正是血热之脉，故知系血热妄行。用生地黄凉血止血，竹茹宣通消瘀，服后脉亦平和，热退血止。", ["洪", "滑"]], "19949": ["病机", "脉象洪滑，重按未实，洪为热盛，滑为痰湿，未实示热未成实。温病表里俱热，胃口满闷，时欲呕吐，舌苔白微黄，乃热郁阳明，痰湿中阻。洪滑未实，故不可早用承气，宜清热化痰，用石膏、竹茹、连翘，热清则脉和。", ["洪", "滑"]], "19950": ["病机", "原文“诊其脉，肺胃似皆有热”，未列脉形，以脉测知肺胃有热。自动失乳，身形羸弱，久嗽不愈，乃肺胃阴虚，虚热内生，灼津为痰，故咳嗽缠绵。脉当见细数，然原文未详，故脉素从缺。用北沙参清养肺胃，热退咳愈。", []], "19951": ["病机", "脉弦而有力，弦为肝脉，有力为气盛。年过七旬，手连臂肿疼数年，且平素易怒，乃肝气郁结，气郁化火，火盛则脉弦有力。肝气横逆，经络壅滞，故肿疼。连翘能舒肝郁、平肝盛，加于清热消肿药中，肝气平则肿疼愈，怒亦除。", ["弦"]], "19952": ["兼症", "产后月余，壮热口渴不引饮，汗出不止，心悸不寐，面红，脉滑。滑为阳脉，主痰热内蕴，然产后阴血亏虚，虚阳外浮，亦可见滑。此脉滑与壮热、汗出、心悸并见，提示热扰心神、津液外泄，然前医清热养阴不效，后以补药获愈，说明脉滑非实热，乃虚热或气血未复之象。", ["滑"]], "19953": ["病机", "头目眩晕、心中怔忡、呕吐涎沫、气上冲、昏愦不省人事，脉浮而无力。浮为阳脉，无力为虚，此乃阳气上浮、痰饮上逆之候。脉浮无力，说明正气虚衰，不能镇摄，痰饮随虚阳上扰，蒙蔽清窍，故昏愦。重用茯苓健脾渗湿、宁心安神，使痰饮下行，阳气归位，故服后病减。", ["浮"]], "19954": ["病机", "少年心中怔忡，夜不能寐，脉弦硬微数。弦硬为肝血不足、筋脉失养之象，微数主虚热内扰。心脾血液短少，则心失所养而怔忡，神不守舍而不寐。脉弦硬微数，正是血虚生热、肝脾失调之反映。龙眼肉甘温补心脾、益气血，使血充神安，故病除根。", ["弦", "硬", "数"]], "19955": ["病机", "肝脏素有伤损，左关脉独微弱，忽胁下作疼。左关候肝，微弱为肝气肝血不足之象。肝体阴而用阳，血虚则肝络失养，气机不畅，故胁下作疼。柏子仁甘平，养肝血、润肝燥，使肝得柔养，则疼痛自止。此脉微弱，正说明肝虚为本，疼痛为标。", ["微", "弱"]], "19956": ["其他", "此段论大枣性味功效，未涉及脉象。大枣味甘微辛，性温，津液浓厚滑润，能滋养血脉、润泽肌肉、强健脾胃、固肠止泻、调和百药。其安中者，味至甘能守中；通九窍者，津液滑润且微辛；补少气少津液者，甘能益气，润能补津。虽为食品，用之得当能建奇功。", []], "19957": ["病机", "老媪年过六旬，腿疼年余不愈，脉两尺沉细。两尺候肾，沉细为肾阳不足、精血亏虚之象。肾主骨，腰为肾之府，肾虚则腰腿失养，寒湿乘虚而入，故腿疼。青娥丸补肾强腰，使肾气充盛，则腿疼自愈。脉沉细，正是肾虚寒湿内着之反映。", ["沉", "细"]], "19958": ["预后", "病淋者误服萆薢分清饮，致小便滴沥不通，精神昏愦，毫无知觉，脉数近十至，按之即无。数近十至为热极，按之即无为正气衰败、脉无胃气，此乃阴竭阳越、正气将脱之危候。脉数无根，说明邪热炽盛而真阴耗竭，预后不良。故谓「据此脉论，即小便通」亦难挽回。", ["数", "无"]], "19959": ["妇人", "此段论女子干血劳之证，未涉及具体脉象。干血劳为难治之证，善用鸡内金者多能奏效。鸡内金善化瘀血，能催月信下行，然过用则月信一月三至。血之来源在脾胃，鸡内金与白术并用，能健脾胃以消饮食，资生血液。脾虚肺亦虚，故多兼劳嗽。", []], "19960": ["治法", "原文未出脉名，仅言\"身体虚弱劳嗽\"，属虚劳兼月信不至之证。以资生通脉汤为主，随案加减，意在培补气血以通月信。虚劳久嗽则气分先亏，血海无源，故月信不至；方后附案加减，示人随证变通，非单恃通破。", []], "19961": ["治法", "承上论服资生通脉汤病愈而月信仍不至者，用生山药四两煮汁送生鸡内金末。鸡内金生用为通月信要药，多用恐损气分，故以山药四两培气分以护之。此段无脉象，主在示通经而不伤气之治法，与上段虚劳月闭相应。", []], "19962": ["主病", "脉象沉而微弦，右部尤甚。沉主里、主积，弦主肝、主痛，右部尤甚则病在脾胃。胃脘有硬物杜塞数年，饮食减少不能下行，正合沉弦之里积。用鸡内金、生酒曲消积化滞，数剂硬物全消，脉证相应。", ["沉", "弦"]], "19963": ["主病", "脉象沉弦，积在左胁下大径三寸、按之甚硬、时或作疼、呃逆气短、饮食减少。沉主里积，弦主肝木，左胁为肝之分野，故断为肝积肥气之类。用生鸡内金、柴胡为末，消积疏肝，旬余全愈，脉沉弦正合肝积之病机。", ["沉", "弦"]], "19964": ["主病", "脉象沉牢，胃中满闷不能饮食，自觉贲门有物窒碍。沉主里，牢主坚积深痼，为瘀滞结聚之象。故用鸡内金、白术、赭石、乳没、丹参、桃仁消瘀降逆，连服八剂全愈。牢脉示积结牢固，非轻剂可拔，与贲门窒碍相应。", ["沉", "牢"]], "19965": ["主病", "脉象沉而无力，右部尤甚。沉主里、主瘀滞，无力则正气已虚，右部尤甚示脾胃气弱。胃有瘀滞作疼、浸至不能饮食，乃虚实夹杂。方中鸡内金、酒曲、三棱、莪术、樗鸡破瘀，党参扶正，服后二便下血而愈，正合沉而无力之虚实兼见。", ["沉"]], "19966": ["主病", "左脉弦细，右脉沉濡。弦细属肝血不足而气郁，沉濡属脾虚湿滞，左右合参为肝郁脾弱、积滞内结。胃脘停积数年、渐大如拳甚硬、不能饮食，故用鸡内金、三棱、莪术消积，黄芪、当归、知母扶正养阴，二十余剂积全消。", ["弦", "细", "沉", "濡"]], "19967": ["治法", "原文以\"其脉不虚弱者\"为用蛭之准绳，未列具体脉象。脉不虚弱则正气尚充，可专任水蛭入血分破瘀，于气分无损，瘀血默消。若脉虚弱则不可径用。此段主在示破血药之用法与脉证禁忌，与妇女月闭症瘕之治相应。", []], "19968": ["病机", "脉象摇摇而动、按之无根，是疹毒内陷、毒火内攻，引动肝风之象。疹出三日即靥而留紫痕，毒不得外透，反内扰神明则精神恍惚、肢体骚扰；风火相煽，肺气上逆则大喘迫促。脉动无根正示正气不支而邪热鸱张，故以羚羊角熄风清火兼托毒外出。", ["动"]], "19969": ["病机", "左脉较右脉洪紧，洪为火盛，紧为邪结，左脉候肝，故知肝火炽盛。疔毒生于左臂，外科失治致毒火内攻、热痰上壅，填塞胸臆而昏不知人，成痰厥之证。脉洪紧应其肿疼属实火，故用蓬砂涌吐痰涎，继以清火解毒、羚羊角清肝火而愈。", ["洪", "紧"]], "19970": ["病机", "原文但言脉象确有实热，未著具体脉形。疹倒靥过急，毒火内郁旬日，大热不止，虽形体病久似弱而脉证实热，且便干溲赤，知非轻剂可治。脉实与便干溲赤相参，断为毒火内郁之实热，故用羚羊角、生石膏大清其热而愈。", []], "19971": ["病机", "脉象数而有力，数为热，有力为实，故知疹毒之余热未清。疹后旬余灼热不退，屡服西药不效，正因余毒郁热留于内，非虚热可比。脉数有力与灼热相应，故单用羚羊角清其余热，热顿愈，亦印证脉实主实热之旨。", ["数", "实"]], "19972": ["病机", "脉象有力、摇摇而动，是热盛风动之兆。疹出三日似靥非靥，壮热渴饮，精神恍惚不稳，热毒内郁将引动肝风，故脉动不宁。原文恐其因热发痉，果未及煎药而痉发，用羚羊角清热托毒而痉愈，可见动脉在此主热极生风。", ["动"]], "19973": ["病机", "脉甚有力，肌肤发热，是温病实热之脉。温邪循督脉上行伤脑，故发痉而昏昏似睡、呼之不应。原文谓督脉实为脑髓神经之根本，脉实正应邪热壅盛于督脉神经。单用羚羊角清督脉之热而痉愈，继以石膏、玄参等清热而脉静身凉，脉实主实热明矣。", ["实"]], "19974": ["病机", "脉数近七至为热盛，重诊无力为气分大伤。因割瘰疬三次、屡闻麻药耗伤气分，故脉虽数而按之无力，属外感实热兼气虚之候。喘息迫促、心热难支、胁下疼甚，皆热盛气耗所致。故先以羚羊角合鸡子黄清热护阴，继用白虎加人参汤清热益气而愈。", ["数", "虚"]], "19975": ["病机", "本段未识出脉名，亦无脉象描述，主旨在于阐发太阳经为表中之表、统营卫而御外邪，并推论其热力源于君相二火：君火出心脉肺循环而散热于胸中大气，相火自命门由膀胱三焦透达体表。全段论经脉生理与热力由来，非诊脉主病之文，故脉象要素从缺。", []], "19976": ["主病", "原文以“脉缓者”名中风，并明言缓脉“至数不改似有懒动之意”，与迟脉“不足四至”相别。缓脉非数非迟，脉来从容和缓而略见怠缓，是营卫受风、卫外不固而脉道弛纵之象。风性疏泄，故汗出恶风；营阴外泄，脉失紧束，故见缓。此脉主太阳中风证，与发热、汗出、恶风相应，非虚寒之迟。", ["缓"]], "19977": ["病机", "原文以关前为阳、关后为阴，谓“浮脉见于关前，弱脉见于关后”，浮者著手即得，弱者不任重按。阳浮则卫气浮盛于外而“热自发”，阴弱则营阴不守而“汗自出”。浮为风邪袭表、卫阳浮越，弱为营阴不足、脉道不充。此脉象说明太阳中风卫强营弱之病机，与啬啬恶寒、淅淅恶风、翕翕发热、鼻鸣干呕相应。", ["浮", "弱"]], "19978": ["病机", "原文辨析桂枝汤证“弱脉惟见于关后”，关前之脉“因受风而浮”，其未病之先关前关后脉皆弱，病后关前之弱“转为浮脉所掩”。故脉虽浮，必不任重按，是浮中仍寓弱象。浮为风邪外袭，弱为胸中大气本弱、营血不充。此段说明桂枝汤证汗出“实由于胸中大气之弱”的病机，脉浮而中弱，与汗出、恶风相应。", ["浮", "弱"]], "19979": ["主病", "原文谓“脉阴阳俱紧者，名曰伤寒”，阴阳俱紧指寸关尺三部脉皆见紧象。紧脉主寒，寒邪外束太阳，卫阳被遏，营阴凝滞，脉道收缩紧急，故脉来紧而有力。寒邪伤表，卫阳不能温煦，故必恶寒；寒凝经脉，故体痛；寒邪犯胃，胃气上逆，故呕逆。此脉主太阳伤寒表实证，与或已发热、或未发热、恶寒体痛呕逆相应。", ["紧"]], "19980": ["病机", "原文形容紧脉“跳动若有力而转若无所起伏”，指下“似甚有力而竟直穿而过”，因寒邪“逼压其脉道使不能起伏”，蓄极而有“左右弹之势”。此说明紧脉由太阳外卫之阳为寒所袭、内陷与脉相并，寒性紧缩使脉道失于起伏而成。紧主寒邪束表、卫阳被遏之病机，为伤寒之确征，与恶寒体痛无汗相应。", ["紧"]], "19981": ["病机", "本段未出脉名，专论麻黄汤证诸症之由：全体疼痛因“筋骨不禁寒气之紧缩”，发热因“元阳为寒气闭塞不能宣散而增热”，无汗恶风因“汗为寒闭内蕴之热原欲借汗透出”，作喘因寒气由皮毛入肺“闭其肺中气管”及胸中大气为寒所闭。所论虽不言脉，实示寒邪外束、卫闭营郁、肺气不宣之病机，与麻黄汤证脉紧相应。", []], "19982": ["误治", "患者体素羸弱，医投麻黄汤而“汗无分毫”，其“脉似紧而不任重按”。似紧为寒邪外束之象，不任重按则示正气本虚、脉中无力。前医但见紧脉即用麻黄峻汗，未察虚体不胜发散，故汗不出而病不愈。后于麻黄汤中加生黄耆、天花粉扶正生津，一剂得汗而愈。此段言误治之由在脉紧而虚，不可纯用峻汗。", ["紧"]], "19983": ["其他", "患者重受外感，内外觉寒凉、头疼微喘、周身寒战，而“诊其脉六部皆无，重按亦不见”。脉伏不见非必死候，因寒邪闭束太甚，阳气不能外达，脉道沉伏；其心中除寒凉外别无所苦，知正气犹存。于麻黄汤中加生黄耆一两扶助正气、助阳外达，服后“六脉皆出”，得微汗而愈。此段示寒闭阳郁、脉伏不出之证治，非真无脉。", []], "19984": ["病机", "脉甚微细而无紧象，说明其人素羸弱又吸鸦片，正气本虚，虽感寒而脉不现紧，是阳虚无力鼓脉之象。粗通医学自服麻黄汤分毫无汗，正因脉微细示正气不足，无力作汗。加生黄耆五钱补气助汗，服后得汗而愈，可见此脉主正虚不能托邪外出之病机，非寒邪不盛。", ["微", "细"]], "19985": ["病机", "脉近六至且甚弦细，医者谓脉数而弱，是阴分素亏而感寒之象。数而细弱说明阴亏不能充盈脉道，弦为寒束，数近六至为虚热内扰。身冷恶寒、舌苔淡白示表寒仍在，然脉弱不可强发其汗。故少用麻黄辅以山药、沙参补正，使汗出而正不伤，此脉主阴亏感寒、正虚邪恋之病机。", ["数", "弦", "细", "弱"]], "19986": ["病机", "脉象浮弦，重按似有力，浮为表邪未罢，弦为热入太阳之腑。表证未罢而时或恶寒、头犹微疼、舌苔犹白，是寒邪仍在表；心中微热、小便色黄，是热已入膀胱。浮弦重按有力，正示表寒里热并见之机。故用麻黄汤加知母、滑石，外解表寒内清腑热，一汗而愈，此脉主太阳腑热兼表之病机。", ["浮", "弦"]], "19987": ["病机", "脉阴阳俱浮，是风温之邪充斥表里，浮脉主风主表，阴阳俱浮说明风热之邪外扬而非沉伏于里。配合自汗出、身重、多眠睡、息必鼾、语言难出，皆风热外透、经热昏沉、上焦热盛之候。此脉象风之飘扬，主风温袭表、热邪外扬之病机，与伤寒寒邪束表之浮紧不同。", ["浮"]], "19988": ["病机", "原文谓脉阴阳俱浮者象风之飘扬也，浮脉应风，风性轻扬外散，故风温之邪使脉浮。自汗出为热随浮脉外透，身重为经热酸软，多眠睡为精神经热昏沉，语言难出为上焦热盛舌肿。此段以浮脉统摄风温诸症，说明风热之邪自太阳化热最速、外扬于表之病机，非寒邪内束之紧脉可比。", ["浮"]], "19989": ["病机", "脉一息五至为数，浮沉皆有力，说明肺中余热未清、肺阴铄耗而热邪仍盛。数主热，浮沉皆有力示热邪充斥表里、正气尚能抗邪。喉痒即咳、吐稠痰、心中发热、大便燥结，皆肺中风热相助为虐之候。用麻杏甘石汤祛风清热后咳愈而脉仍有力，可见此脉主风热恋肺、余热未清之病机。", ["数", "浮", "沉"]], "19990": ["其他", "此段仅为标题，标举脉微弱、汗出恶风及筋惕肉𥆧之治法，原文未展开脉象描述与病机分析。脉微弱主正气虚，汗出恶风为表虚，筋惕肉𥆧为阳虚失于温煦、筋脉失养，属桂枝加附子汤一类证治。因原文仅存目，脉象要素无从确指，故不列脉字，仅识其属治法条目。", []], "19991": ["病机", "此段言太阳中风之脉兼见太阳伤寒之脉，即中风脉浮缓与伤寒脉浮紧并见，为大青龙汤所主之证。中风脉缓示营卫不和，伤寒脉紧示寒邪束表，二脉兼见说明外寒闭表而内有郁热，故用大青龙汤外解表寒内清里热。原文未直书具体脉字，仅以中风脉、伤寒脉对举，故脉象要素从略，主旨在于辨析兼脉之病机。", []], "19992": ["主病", "脉浮紧为风寒束表、卫阳郁闭之象，故见发热恶寒、身疼痛、不汗出而烦躁，主大青龙汤证。若脉微弱而汗出恶风，则属表虚阳弱，不可更发其汗，误服大青龙则阳气外脱，致厥逆、筋惕肉𥆧，此脉示禁汗之机。", ["浮", "紧", "微", "弱"]], "19993": ["病机", "脉微弱汗出恶风，乃胸中大气虚损、不能固摄卫气之候，纵有热亦属虚阳外浮。若误投大青龙汤，则虚者益虚，元阳因气分虚极而欲脱，肝风萌动，遂致筋惕肉𥆧。此脉明示虚阳外浮、气脱风动之病机，与大青龙实证迥异。", ["微", "弱"]], "19994": ["主病", "伤寒脉浮缓，身不疼但重、乍有轻时，无少阴证，此非寒邪凛冽，乃风邪兼湿、郁于肌表之象。脉浮主表，缓主风与湿滞，故身重而不疼，仍属大青龙汤发散之证，以脉不微弱、无少阴里虚为辨。", ["浮", "缓"]], "19995": ["病机", "外感之脉多浮，兼中风故也。前节脉浮紧，为凛冽寒风，中风兼伤寒；后节脉浮缓，为柔和温风，即风温之候。脉紧主寒，缓主温风，浮则同属外感。此以脉之紧缓辨寒温之异，说明温病身重、乍有轻时亦可用石膏之机理。", ["浮", "紧", "缓"]], "19996": ["病机", "脉洪滑而浮，洪为热盛，滑为痰热内壅，浮为热势外越。前医误投麻黄汤，分毫无汗，烦躁益甚，正因胸中蕴热不得外达。此脉示表寒外束、里热壅盛之机，故用大青龙汤加花粉，清热透表而汗出病解。", ["洪", "滑", "浮"]], "19997": ["主病", "脉滑而濡，至数如常，滑主痰饮内蕴，濡主湿滞、气虚。体丰素有痰饮，外感风寒引动，致喘促不休、精神不振、胸膈满闷、舌苔白腻，此痰饮内伏、外寒触发之小青龙汤证。脉滑濡正合痰湿内盛之机。", ["滑", "濡"]], "19998": ["兼症", "脉大略如前，而较前热盛，大脉主热盛邪实。外感痰喘挟热，肺必胀满，故仍用小青龙汤去麻黄加杏仁，并重加生石膏以清肺热。此脉示痰喘挟热、热势较前增盛之兼症，故于原方中加石膏以监制温燥。", ["大"]], "19999": ["治法", "脉虚者用人参于汤中，必加生石膏以辅之，使能受温补之力；脉实者仍宜用麻黄以发散。此以脉之虚实定麻黄、人参之取舍，并以石膏监制方药之热性。脉虚主气弱，脉实主邪盛，示小青龙汤加减须凭脉虚实为治。", ["虚", "实"]]});